function persistentHelpControl(target) {
  return target instanceof Element ? target.closest("[data-help-detail]") : null;
}

function persistentHelpTitle(control) {
  return control?.getAttribute("title")
    || control?.dataset.helpTitle
    || control?.dataset.helpNativeTitle
    || control?.getAttribute("aria-label")
    || "";
}

function configurePersistentHelp(control, {
  title,
  detail,
  kind = "control",
  keyShortcuts = null,
  owner = null,
} = {}) {
  if (!(control instanceof HTMLElement)) return control;
  if (title) control.dataset.helpTitle = title;
  else delete control.dataset.helpTitle;
  if (detail) control.dataset.helpDetail = detail;
  else delete control.dataset.helpDetail;
  if (kind) control.dataset.helpKind = kind;
  else delete control.dataset.helpKind;
  if (owner) control.dataset.helpOwner = owner;
  else delete control.dataset.helpOwner;
  if (keyShortcuts) control.setAttribute("aria-keyshortcuts", keyShortcuts);
  return control;
}

function suspendNativeHelp(control) {
  const title = control.getAttribute("title");
  if (!title) return;
  control.dataset.helpNativeTitle = title;
  control.removeAttribute("title");
}

function restoreNativeHelp(control) {
  if (!(control instanceof Element)) return;
  const suspended = control.dataset.helpNativeTitle;
  if (suspended && !control.hasAttribute("title")) control.setAttribute("title", suspended);
  delete control.dataset.helpNativeTitle;
}

function removePersistentHelpDescription(control) {
  if (!(control instanceof Element)) return;
  const describedBy = (control.getAttribute("aria-describedby") || "")
    .split(/\s+/)
    .filter((id) => id && id !== "persistentHelp");
  if (describedBy.length) control.setAttribute("aria-describedby", describedBy.join(" "));
  else control.removeAttribute("aria-describedby");
}

function hidePersistentHelp({
  restoreTitle = true,
  owner = null,
  preserveOwnerContinuity = false,
} = {}) {
  if (owner != null && owner !== persistentHelpOwner) return false;
  clearTimeout(persistentHelpTimer);
  persistentHelpTimer = null;
  persistentHelpOwner += 1;
  const target = persistentHelpTarget;
  const wasVisible = !elements.persistentHelp.classList.contains("hidden");
  if (preserveOwnerContinuity && wasVisible) {
    persistentHelpLastVisibleOwnerKey = persistentHelpOwnerKey(target);
    persistentHelpLastVisibleAt = performance.now();
  } else if (!preserveOwnerContinuity) {
    persistentHelpLastVisibleOwnerKey = null;
    persistentHelpLastVisibleAt = 0;
  }
  persistentHelpTarget = null;
  persistentHelpInputMode = null;
  elements.persistentHelp.classList.add("hidden");
  elements.persistentHelp.setAttribute("aria-hidden", "true");
  elements.persistentHelp.removeAttribute("data-placement");
  elements.persistentHelp.removeAttribute("data-kind");
  elements.persistentHelp.style.removeProperty("left");
  elements.persistentHelp.style.removeProperty("top");
  removePersistentHelpDescription(target);
  if (restoreTitle) restoreNativeHelp(target);
  return true;
}

function positionPersistentHelp(control) {
  const anchor = control.getBoundingClientRect();
  const helpWidth = elements.persistentHelp.offsetWidth;
  const helpHeight = elements.persistentHelp.offsetHeight;
  const margin = 8;
  const gap = 8;
  const below = anchor.bottom + gap;
  const fitsBelow = below + helpHeight <= globalThis.innerHeight - margin;
  const top = fitsBelow ? below : Math.max(margin, anchor.top - helpHeight - gap);
  const left = Math.max(
    margin,
    Math.min(
      anchor.left + ((anchor.width - helpWidth) / 2),
      globalThis.innerWidth - helpWidth - margin
    )
  );
  elements.persistentHelp.style.left = `${left}px`;
  elements.persistentHelp.style.top = `${top}px`;
  elements.persistentHelp.dataset.placement = fitsBelow ? "below" : "above";
}

function showPersistentHelp(control, owner = persistentHelpOwner) {
  if (owner !== persistentHelpOwner
    || persistentHelpTarget !== control
    || !document.contains(control)) return;
  const title = persistentHelpTitle(control);
  const detail = control.dataset.helpDetail || "";
  if (!title || !detail || control.closest("[inert]")) {
    hidePersistentHelp({ owner });
    return;
  }
  elements.persistentHelpTitle.textContent = title;
  elements.persistentHelpDetail.textContent = detail;
  elements.persistentHelp.dataset.kind = control.dataset.helpKind || "control";
  elements.persistentHelp.classList.remove("hidden");
  elements.persistentHelp.setAttribute("aria-hidden", "false");
  const describedBy = new Set(
    (control.getAttribute("aria-describedby") || "").split(/\s+/).filter(Boolean)
  );
  describedBy.add("persistentHelp");
  control.setAttribute("aria-describedby", [...describedBy].join(" "));
  positionPersistentHelp(control);
}

function schedulePersistentHelp(control, delay, inputMode = "pointer") {
  if (!(control instanceof HTMLElement)) return;
  if (inputMode === "pointer") persistentHelpPointerMisses = 0;
  if (persistentHelpTarget === control && !elements.persistentHelp.classList.contains("hidden")) {
    persistentHelpInputMode = inputMode;
    showPersistentHelp(control, persistentHelpOwner);
    return;
  }
  const ownerKey = persistentHelpOwnerKey(control);
  const preservesCurrentVisibleOwner = !elements.persistentHelp.classList.contains("hidden")
    && ownerKey != null
    && ownerKey === persistentHelpOwnerKey(persistentHelpTarget);
  const resumesVisibleOwner = inputMode === "pointer"
    && elements.persistentHelp.classList.contains("hidden")
    && ownerKey != null
    && ownerKey === persistentHelpLastVisibleOwnerKey
    && performance.now() - persistentHelpLastVisibleAt <= 500;
  hidePersistentHelp();
  persistentHelpTarget = control;
  persistentHelpInputMode = inputMode;
  suspendNativeHelp(control);
  const owner = persistentHelpOwner;
  if (preservesCurrentVisibleOwner || resumesVisibleOwner || delay <= 0) {
    showPersistentHelp(control, owner);
  } else {
    persistentHelpTimer = setTimeout(() => {
      if (owner !== persistentHelpOwner) return;
      persistentHelpTimer = null;
      showPersistentHelp(control, owner);
    }, delay);
  }
}

function persistentHelpOwnerKey(control) {
  if (!(control instanceof HTMLElement)) return null;
  return control.dataset.helpOwner || (control.id ? `id:${control.id}` : null);
}

function persistentHelpControlAtPointer() {
  if (!Number.isFinite(persistentHelpPointerX) || !Number.isFinite(persistentHelpPointerY)) {
    return null;
  }
  return persistentHelpControl(document.elementFromPoint(
    persistentHelpPointerX,
    persistentHelpPointerY
  ));
}

function reconcilePersistentHelpTarget() {
  persistentHelpReconcileFrame = null;
  if (persistentHelpInputMode === "focus") {
    if (!(persistentHelpTarget instanceof HTMLElement)
      || !persistentHelpTarget.isConnected
      || !persistentHelpTarget.contains(document.activeElement)) {
      hidePersistentHelp();
      return;
    }
    if (!elements.persistentHelp.classList.contains("hidden")) {
      showPersistentHelp(persistentHelpTarget, persistentHelpOwner);
    }
    return;
  }

  const control = persistentHelpControlAtPointer();
  if (!(control instanceof HTMLElement)) {
    if (persistentHelpInputMode === "pointer") {
      if (persistentHelpPointerMisses === 0) {
        persistentHelpPointerMisses = 1;
        persistentHelpReconcileFrame = requestAnimationFrame(reconcilePersistentHelpTarget);
      } else {
        persistentHelpPointerMisses = 0;
        hidePersistentHelp({ preserveOwnerContinuity: true });
      }
    }
    return;
  }
  persistentHelpPointerMisses = 0;
  if (control === persistentHelpTarget) {
    if (!elements.persistentHelp.classList.contains("hidden")) {
      showPersistentHelp(control, persistentHelpOwner);
    }
    return;
  }

  const previousOwnerKey = persistentHelpOwnerKey(persistentHelpTarget);
  const nextOwnerKey = persistentHelpOwnerKey(control);
  const preservesVisibleOwner = !elements.persistentHelp.classList.contains("hidden")
    && previousOwnerKey != null
    && previousOwnerKey === nextOwnerKey;
  schedulePersistentHelp(control, preservesVisibleOwner ? 0 : 650, "pointer");
}

function schedulePersistentHelpReconciliation() {
  if (persistentHelpReconcileFrame != null) return;
  persistentHelpReconcileFrame = requestAnimationFrame(reconcilePersistentHelpTarget);
}

function resetPersistentHelpPointer() {
  persistentHelpPointerX = null;
  persistentHelpPointerY = null;
  persistentHelpPointerMisses = 0;
}

function bindPersistentHelp() {
  document.addEventListener("pointermove", (event) => {
    persistentHelpPointerX = event.clientX;
    persistentHelpPointerY = event.clientY;
  }, { passive: true });
  document.addEventListener("pointerover", (event) => {
    persistentHelpPointerX = event.clientX;
    persistentHelpPointerY = event.clientY;
    const control = persistentHelpControl(event.target);
    if (!control || control.contains(event.relatedTarget)) return;
    schedulePersistentHelp(control, 650, "pointer");
  });
  document.addEventListener("pointerout", (event) => {
    const control = persistentHelpControl(event.target);
    if (!control || control.contains(event.relatedTarget)) return;
    if (persistentHelpInputMode === "pointer" && persistentHelpTarget === control) {
      schedulePersistentHelpReconciliation();
    }
  });
  document.addEventListener("focusin", (event) => {
    const control = persistentHelpControl(event.target);
    if (control
      && event.target instanceof HTMLElement
      && event.target.matches(":focus-visible")) {
      schedulePersistentHelp(control, 160, "focus");
    }
  });
  document.addEventListener("focusout", (event) => {
    const control = persistentHelpControl(event.target);
    if (persistentHelpInputMode === "focus" && persistentHelpTarget === control) {
      hidePersistentHelp();
    }
  });
  document.addEventListener("pointerdown", () => {
    resetPersistentHelpPointer();
    hidePersistentHelp();
  }, true);
  document.addEventListener("keydown", () => {
    resetPersistentHelpPointer();
    hidePersistentHelp();
  }, true);
  globalThis.addEventListener("resize", schedulePersistentHelpReconciliation, { passive: true });
  document.addEventListener("scroll", schedulePersistentHelpReconciliation, {
    passive: true,
    capture: true,
  });
  new MutationObserver((mutations) => {
    if (mutations.some((mutation) => !elements.persistentHelp.contains(mutation.target))) {
      schedulePersistentHelpReconciliation();
    }
  }).observe(document.body, { childList: true, subtree: true });
}

function restoreOverlayFocus(target) {
  if (!(target instanceof HTMLElement) || !document.contains(target)) return;
  requestAnimationFrame(() => target.focus({ preventScroll: true }));
}

function stableReturnFocusTarget(target, fallback) {
  if (target instanceof HTMLElement
    && document.contains(target)
    && target !== document.body
    && target !== document.documentElement
    && !(target instanceof HTMLButtonElement && target.disabled)
    && target.getClientRects().length > 0
    && !target.closest("[inert]")) return target;
  return fallback;
}

function stabilizeDismissedOverlayFocus(resolveTarget, dismissedContainer, isStillValid) {
  // Selection aggregates may finish after dragend and repaint the inspector.
  // Keep a bounded recovery window, but stop immediately when the user moves
  // focus anywhere other than the transiently removed/recreated tag chip.
  let remainingFrames = 120;
  let hasRestored = false;
  const restore = () => {
    if (!isStillValid()) return;
    const target = resolveTarget();
    if (!(target instanceof HTMLElement) || !document.contains(target)) {
      remainingFrames -= 1;
      if (remainingFrames > 0) requestAnimationFrame(restore);
      return;
    }
    const active = document.activeElement;
    if (hasRestored
      && active !== document.body
      && active !== document.documentElement
      && !dismissedContainer.contains(active)
      && active !== target) return;
    target.focus({ preventScroll: true });
    target.scrollIntoView({ block: "nearest" });
    hasRestored = true;
    remainingFrames -= 1;
    if (remainingFrames > 0) requestAnimationFrame(restore);
  };
  restore();
}

function galleryInspectorHasContent() {
  return Boolean(
    (!state.selectionMode && state.selectedDetail)
      || (state.selectionMode && state.selectedAssetIDs.size)
  );
}

function galleryInspectorOverlayIsOpen() {
  if (galleryOverviewLayoutQuery.matches
    || visibleWorkspaceRoute() !== "gallery"
    || !elements.inspector.classList.contains("open")) return false;
  return true;
}

function checkpointGalleryInspectorHistory() {
  if (!galleryInspectorOverlayIsOpen()
    || !state.workspaceNavigation.initialized
    || state.workspaceNavigation.applyingHistory
    || state.workspaceNavigation.pendingRestoreEntry
    || elements.appView.classList.contains("hidden")) return;
  const current = activeWorkspaceHistoryEntry();
  if (current?.route === "gallery" && current.navigationLevel === "workspace") {
    recordWorkspaceHistory("gallery", currentGalleryHistoryContext(), "pushInspector");
  } else {
    scheduleWorkspaceHistoryCheckpoint();
  }
}

function openGalleryInspectorOverlay({ returnFocus = null, focus = true } = {}) {
  if (galleryOverviewLayoutQuery.matches || visibleWorkspaceRoute() !== "gallery") {
    return false;
  }
  if (returnFocus instanceof HTMLElement) {
    state.inspectorOverlayReturnFocus = returnFocus;
  }
  state.inspectorDismissed = false;
  state.inspectorDismissedByUser = false;
  elements.inspector.classList.add("open");
  renderInspectorSurface();
  renderInspectorVisibilityControl();
  if (focus) requestAnimationFrame(() => {
    elements.closeInspectorButton.focus({ preventScroll: true });
  });
  return true;
}

function closeInspectorOverlay({ restoreFocus = true, markDismissed = true } = {}) {
  state.inspectorDismissed = true;
  if (markDismissed) state.inspectorDismissedByUser = true;
  elements.inspector.classList.remove("open");
  const explicitReturnFocus = state.inspectorOverlayReturnFocus;
  state.inspectorOverlayReturnFocus = null;
  renderInspectorVisibilityControl();
  const assetID = state.selectionMode && state.selectedAssetIDs.size === 1
    ? [...state.selectedAssetIDs][0]
    : state.selectedAssetID;
  if (restoreFocus) {
    const returnFocus = explicitReturnFocus?.isConnected
      ? explicitReturnFocus
      : (assetID
        ? assetCardMainButton(elements.assetGrid.querySelector(`[data-asset-id="${assetID}"]`))
        : elements.selectionModeButton);
    restoreOverlayFocus(returnFocus);
  }
  scheduleWorkspaceHistoryCheckpoint();
}

function returnFromInspector() {
  if (!galleryInspectorOverlayIsOpen()) return Promise.resolve();
  state.inspectorDismissedByUser = true;
  if (state.workspaceNavigation.pendingReturnPromise) {
    return state.workspaceNavigation.pendingReturnPromise;
  }
  const current = activeWorkspaceHistoryEntry();
  if (state.workspaceNavigation.initialized
    && current?.route === "gallery"
    && current.navigationLevel === "inspector") {
    const pending = new Promise((resolve) => {
      state.workspaceNavigation.pendingReturnResolve = resolve;
    });
    state.workspaceNavigation.pendingReturnPromise = pending;
    history.back();
    return pending;
  }
  closeInspectorOverlay();
  return Promise.resolve();
}

function mobileSidebarOverlayIsOpen() {
  return mobileSidebarLayoutQuery.matches
    && visibleWorkspaceRoute() === "gallery"
    && elements.sourceSidebar.classList.contains("open");
}

function mountWorkspaceOverlayPortals() {
  if (elements.sourceActionsPopover.parentElement !== elements.workspace) {
    elements.workspace.append(elements.sourceActionsPopover);
  }
  if (elements.tagActionsPopover.parentElement !== elements.workspace) {
    elements.workspace.append(elements.tagActionsPopover);
  }
}

function syncMobileSidebarAccessibility() {
  const mobile = mobileSidebarLayoutQuery.matches;
  const open = mobile && elements.sourceSidebar.classList.contains("open");
  elements.appView.classList.toggle("mobile-sidebar-open", open);
  elements.sidebarToggle.setAttribute("aria-expanded", String(open));
  elements.sidebarToggle.setAttribute("aria-label", open ? "隐藏图库导航" : "显示图库导航");
  elements.mobileSidebarScrim.classList.toggle("hidden", !open);
  elements.mobileSidebarScrim.setAttribute("aria-hidden", String(!open));
  elements.sourceSidebar.inert = mobile && !open;
  if (mobile && !open) elements.sourceSidebar.setAttribute("aria-hidden", "true");
  else elements.sourceSidebar.removeAttribute("aria-hidden");

  if (open) {
    if (!state.sidebarOverlayInertSnapshot) {
      state.sidebarOverlayInertSnapshot = {
        libraryPane: elements.libraryPane.inert,
        inspector: elements.inspector.inert,
      };
    }
    elements.libraryPane.inert = true;
    elements.inspector.inert = true;
  } else if (state.sidebarOverlayInertSnapshot) {
    elements.libraryPane.inert = state.sidebarOverlayInertSnapshot.libraryPane;
    elements.inspector.inert = state.sidebarOverlayInertSnapshot.inspector;
    state.sidebarOverlayInertSnapshot = null;
  }
  renderSidebarVisibilityControl();
}

function openMobileSidebar({
  focus = true,
  historyMode = "pushSidebar",
  baseLevel = null,
  returnFocus = null,
} = {}) {
  if (!mobileSidebarLayoutQuery.matches || visibleWorkspaceRoute() !== "gallery") return;
  if (mobileSidebarOverlayIsOpen()) {
    if (focus) requestAnimationFrame(focusCurrentSidebarPrimaryNavigation);
    return;
  }
  const current = activeWorkspaceHistoryEntry();
  const replacesActionMenu = historyMode === "pushSidebar"
    && current?.navigationLevel === "actionMenu";
  hidePersistentHelp();
  closeCompactToolbarMenu({ restoreFocus: false });
  closeLayoutMenu({ restoreFocus: false });
  closeFilterPopover({ restoreFocus: false });
  closeActionMenu({ restoreFocus: false, checkpoint: !replacesActionMenu });
  closeJobsPopover({ restoreFocus: false });
  state.sidebarOverlayReturnFocus = returnFocus instanceof HTMLElement
    ? returnFocus
    : elements.sidebarToggle;
  const currentLevel = current?.navigationLevel;
  state.sidebarOverlayBaseLevel = baseLevel
    || (currentLevel === "inspector" ? "inspector" : "workspace");
  elements.sourceSidebar.classList.add("open");
  syncMobileSidebarAccessibility();
  if (historyMode !== "none") {
    recordWorkspaceHistory(
      "gallery",
      currentGalleryHistoryContext(),
      replacesActionMenu ? "replaceOverlay" : historyMode
    );
  }
  if (focus) requestAnimationFrame(focusCurrentSidebarPrimaryNavigation);
}

function closeMobileSidebar({ restoreFocus = true, checkpoint = true } = {}) {
  const wasOpen = elements.sourceSidebar.classList.contains("open");
  elements.sourceSidebar.classList.remove("open");
  syncMobileSidebarAccessibility();
  const returnFocus = state.sidebarOverlayReturnFocus;
  state.sidebarOverlayReturnFocus = null;
  state.sidebarOverlayBaseLevel = "workspace";
  if (restoreFocus && wasOpen) {
    restoreOverlayFocus(returnFocus || elements.sidebarToggle);
  }
  if (checkpoint && wasOpen) scheduleWorkspaceHistoryCheckpoint();
}

function returnFromMobileSidebar() {
  if (!mobileSidebarOverlayIsOpen()) return Promise.resolve();
  if (state.workspaceNavigation.pendingReturnPromise) {
    return state.workspaceNavigation.pendingReturnPromise;
  }
  const current = activeWorkspaceHistoryEntry();
  if (state.workspaceNavigation.initialized
    && current?.route === "gallery"
    && current.navigationLevel === "sidebar") {
    const pending = new Promise((resolve) => {
      state.workspaceNavigation.pendingReturnResolve = resolve;
    });
    state.workspaceNavigation.pendingReturnPromise = pending;
    history.back();
    return pending;
  }
  closeMobileSidebar();
  return Promise.resolve();
}

function reconcileMobileSidebarFromWorkspaceHistory(route, navigationLevel, context = {}) {
  const shouldOpen = route === "gallery"
    && navigationLevel === "sidebar"
    && mobileSidebarLayoutQuery.matches;
  if (shouldOpen) {
    const baseLevel = context.gallerySidebarBaseLevel === "inspector"
      ? "inspector"
      : "workspace";
    openMobileSidebar({ historyMode: "none", baseLevel });
  } else if (elements.sourceSidebar.classList.contains("open")) {
    closeMobileSidebar({ checkpoint: false });
  } else {
    syncMobileSidebarAccessibility();
  }
}

function handleMobileSidebarLayoutChange() {
  if (!mobileSidebarLayoutQuery.matches
    && elements.sourceSidebar.classList.contains("open")) {
    const baseLevel = state.sidebarOverlayBaseLevel;
    closeMobileSidebar({ restoreFocus: false, checkpoint: false });
    reconcileGalleryInspectorFromWorkspaceHistory("gallery", baseLevel);
    recordWorkspaceHistory("gallery", currentGalleryHistoryContext(), "replace");
  } else {
    syncMobileSidebarAccessibility();
  }
  if (mobileSidebarLayoutQuery.matches) {
    requestAnimationFrame(() => resetCompactSelectionToolScroll({
      preserveFocusedAction: true,
    }));
  }
  scheduleAdaptiveToolbarSync();
}

function setWorkspaceBackButton(button, label) {
  const parts = button.querySelectorAll(":scope > span");
  if (parts[0]) parts[0].textContent = "‹";
  if (parts[1]) parts[1].textContent = label;
  button.setAttribute("aria-label", label);
  button.title = label;
}

function visibleWorkspaceRoute() {
  if (!elements.reviewWorkspace.classList.contains("hidden")) return "review";
  if (!elements.trainingWorkspace.classList.contains("hidden")) return "training";
  if (!elements.slimmingWorkspace.classList.contains("hidden")) return "slimming";
  if (!elements.worldMapWorkspace.classList.contains("hidden")) return "worldMap";
  if (!elements.galleryOverviewWorkspace.classList.contains("hidden")) return "galleryOverview";
  return "gallery";
}

function workspaceLightboxHistoryContext(route, context) {
  if (!context || typeof context !== "object") return null;
  if (route === "gallery") return context.galleryLightbox || null;
  if (route === "review") return context.reviewLightbox || null;
  if (route === "slimming") return context.slimmingLightbox || null;
  if (route === "worldMap") return context.worldMapLightbox || null;
  return null;
}

function workspaceLightboxContext(route) {
  if (route === "gallery") return "library";
  if (["review", "slimming", "worldMap"].includes(route)) return route;
  return null;
}

function workspaceHistoryEntry(route, context = null, navigationLevel = "workspace") {
  const safeNavigationLevel = [
    "confirmation",
    "worldMapLocationBackfill",
    "worldMapPlaceTags",
    "slimmingIdenticalCleanup",
    "slimmingVerification",
    "slimmingRecycleExplanation",
    "slimmingSetup",
    "slimmingThreshold",
    "trainingSetup",
    "tagSuggestion",
    "newTag",
    "tagManager",
    "sourceManager",
    "storageMaintenance",
    "suggestionThreshold",
    "generalSettings",
    "keyboardShortcuts",
    "commandPalette",
    "jobs",
    "filter",
    "layoutMenu",
    "actionMenu",
    "contextMenu",
    "toolbarMenu",
    "sidebar",
    "inspector",
    "lightbox",
  ].includes(navigationLevel)
    ? navigationLevel
    : "workspace";
  return {
    route,
    context: context || null,
    navigationLevel: safeNavigationLevel,
    workspaceGeneration: state.workspaceGeneration,
  };
}

function workspaceNavigationBaseLevel(navigationLevel, context = {}) {
  if (navigationLevel === "confirmation") {
    const parentLevel = [
      "tagManager",
      "sourceManager",
      "storageMaintenance",
      "generalSettings",
      "actionMenu",
      "sidebar",
      "inspector",
      "lightbox",
    ].includes(context.confirmationBaseLevel)
      ? context.confirmationBaseLevel
      : "workspace";
    return workspaceNavigationBaseLevel(parentLevel, context);
  }
  if (navigationLevel === "trainingSetup") {
    return ["sidebar", "inspector", "lightbox"].includes(context.trainingSetupBaseLevel)
      ? context.trainingSetupBaseLevel
      : "workspace";
  }
  if (navigationLevel === "worldMapLocationBackfill") {
    return ["sidebar", "inspector", "lightbox"].includes(
      context.worldMapLocationBackfillBaseLevel
    )
      ? context.worldMapLocationBackfillBaseLevel
      : "workspace";
  }
  if (navigationLevel === "worldMapPlaceTags") {
    return ["sidebar", "inspector", "lightbox"].includes(context.worldMapPlaceTagsBaseLevel)
      ? context.worldMapPlaceTagsBaseLevel
      : "workspace";
  }
  if (navigationLevel === "slimmingIdenticalCleanup") {
    return ["sidebar", "inspector", "lightbox"].includes(
      context.slimmingIdenticalCleanupBaseLevel
    )
      ? context.slimmingIdenticalCleanupBaseLevel
      : "workspace";
  }
  if (navigationLevel === "slimmingVerification") {
    return ["sidebar", "inspector", "lightbox"].includes(
      context.slimmingVerificationBaseLevel
    )
      ? context.slimmingVerificationBaseLevel
      : "workspace";
  }
  if (navigationLevel === "slimmingRecycleExplanation") {
    return ["sidebar", "inspector", "lightbox"].includes(
      context.slimmingRecycleExplanationBaseLevel
    )
      ? context.slimmingRecycleExplanationBaseLevel
      : "workspace";
  }
  if (navigationLevel === "slimmingSetup") {
    return ["sidebar", "inspector", "lightbox"].includes(context.slimmingSetupBaseLevel)
      ? context.slimmingSetupBaseLevel
      : "workspace";
  }
  if (navigationLevel === "slimmingThreshold") {
    return ["sidebar", "inspector", "lightbox"].includes(context.slimmingThresholdBaseLevel)
      ? context.slimmingThresholdBaseLevel
      : "workspace";
  }
  if (navigationLevel === "tagSuggestion") {
    return ["sidebar", "inspector", "lightbox"].includes(context.tagSuggestionBaseLevel)
      ? context.tagSuggestionBaseLevel
      : "workspace";
  }
  if (navigationLevel === "newTag") {
    return ["sidebar", "inspector", "lightbox"].includes(context.newTagBaseLevel)
      ? context.newTagBaseLevel
      : "workspace";
  }
  if (navigationLevel === "tagManager") {
    return ["sidebar", "inspector", "lightbox"].includes(context.tagManagerBaseLevel)
      ? context.tagManagerBaseLevel
      : "workspace";
  }
  if (navigationLevel === "sourceManager") {
    return ["sidebar", "inspector", "lightbox"].includes(context.sourceManagerBaseLevel)
      ? context.sourceManagerBaseLevel
      : "workspace";
  }
  if (navigationLevel === "storageMaintenance") {
    return ["sidebar", "inspector", "lightbox"].includes(context.storageBaseLevel)
      ? context.storageBaseLevel
      : "workspace";
  }
  if (navigationLevel === "keyboardShortcuts") {
    return ["sidebar", "inspector", "lightbox"].includes(
      context.keyboardShortcutsBaseLevel
    )
      ? context.keyboardShortcutsBaseLevel
      : "workspace";
  }
  if (["generalSettings", "suggestionThreshold"].includes(navigationLevel)) {
    return ["sidebar", "inspector", "lightbox"].includes(context.generalSettingsBaseLevel)
      ? context.generalSettingsBaseLevel
      : "workspace";
  }
  if (navigationLevel === "commandPalette") {
    return ["sidebar", "inspector", "lightbox"].includes(context.commandPaletteBaseLevel)
      ? context.commandPaletteBaseLevel
      : "workspace";
  }
  if (navigationLevel === "jobs") {
    return ["sidebar", "inspector", "lightbox"].includes(context.jobsBaseLevel)
      ? context.jobsBaseLevel
      : "workspace";
  }
  if (navigationLevel === "filter") {
    return ["sidebar", "inspector", "lightbox"].includes(context.filterBaseLevel)
      ? context.filterBaseLevel
      : "workspace";
  }
  if (navigationLevel === "layoutMenu") {
    return ["sidebar", "inspector", "lightbox"].includes(context.layoutMenuBaseLevel)
      ? context.layoutMenuBaseLevel
      : "workspace";
  }
  if (navigationLevel === "actionMenu") {
    return ["sidebar", "inspector", "lightbox"].includes(context.actionMenuBaseLevel)
      ? context.actionMenuBaseLevel
      : "workspace";
  }
  if (navigationLevel === "contextMenu") {
    return ["sidebar", "inspector", "lightbox"].includes(context.contextMenuBaseLevel)
      ? context.contextMenuBaseLevel
      : "workspace";
  }
  if (navigationLevel !== "toolbarMenu") return navigationLevel;
  return ["sidebar", "inspector", "lightbox"].includes(context.toolbarMenuBaseLevel)
    ? context.toolbarMenuBaseLevel
    : "workspace";
}

function galleryInspectorHistoryLevel(navigationLevel, context = {}) {
  const baseLevel = workspaceNavigationBaseLevel(navigationLevel, context);
  return baseLevel === "sidebar"
    ? (context.gallerySidebarBaseLevel === "inspector" ? "inspector" : "workspace")
    : baseLevel;
}

function managedWorkspaceHistoryEntry(raw = history.state) {
  const entry = raw?.[WORKSPACE_HISTORY_KEY];
  return entry && typeof entry.route === "string" ? entry : null;
}

function activeWorkspaceHistoryEntry(raw = history.state) {
  const entry = managedWorkspaceHistoryEntry(raw);
  return entry?.workspaceGeneration === state.workspaceGeneration ? entry : null;
}

function initializeWorkspaceHistoryRoot({ restoreExisting = false } = {}) {
  const existing = restoreExisting ? managedWorkspaceHistoryEntry() : null;
  const restored = existing && WORKSPACE_HISTORY_ROUTES.has(existing.route)
    ? workspaceHistoryEntry(existing.route, existing.context, existing.navigationLevel)
    : workspaceHistoryEntry("gallery");
  const resolve = state.workspaceNavigation.pendingReturnResolve;
  state.workspaceNavigation.pendingReturnResolve = null;
  state.workspaceNavigation.pendingReturnPromise = null;
  state.workspaceNavigation.transitionPromise = Promise.resolve();
  resolve?.();
  const nextState = {
    ...(history.state || {}),
    [WORKSPACE_HISTORY_KEY]: restored,
  };
  history.replaceState(nextState, "", location.href);
  state.workspaceNavigation.pendingRestoreEntry = restoreExisting ? restored : null;
  state.workspaceNavigation.initialized = true;
}

function recordWorkspaceHistory(route, context = null, mode = "push") {
  if (!state.workspaceNavigation.initialized
    || mode === "none") return;
  const current = activeWorkspaceHistoryEntry();
  const hasConfirmation = elements.confirmDialog.open;
  const hasWorldMapLocationBackfill = elements.worldMapLocationBackfillDialog.open;
  const hasWorldMapPlaceTags = elements.worldMapPlaceTagDialog.open;
  const hasSlimmingIdenticalCleanup = elements.slimmingIdenticalCleanupDialog.open;
  const hasSlimmingVerification = elements.slimmingVerificationDialog.open;
  const hasSlimmingRecycleExplanation = elements.slimmingRecycleExplanationDialog.open;
  const hasSlimmingSetup = elements.slimmingSetupDialog.open;
  const hasSlimmingThreshold = elements.slimmingThresholdDialog.open;
  const hasTrainingSetup = elements.trainingSetupDialog.open;
  const hasTagSuggestion = elements.tagSuggestionDialog.open;
  const hasNewTag = elements.newTagDialog.open;
  const hasTagManager = elements.tagManagerDialog.open;
  const hasSourceManager = elements.sourceManagerDialog.open;
  const hasStorageMaintenance = elements.storageDialog.open;
  const hasSuggestionThreshold = elements.suggestionThresholdDialog.open;
  const hasGeneralSettings = elements.generalSettingsDialog.open;
  const hasKeyboardShortcuts = elements.shortcutDialog.open;
  const hasCommandPalette = elements.commandPalette.open;
  const hasJobs = !elements.jobsPopover.classList.contains("hidden");
  const hasFilter = !elements.filterPopover.classList.contains("hidden");
  const hasLayoutMenu = Boolean(activeLayoutMenuDescriptor());
  const hasActionMenu = Boolean(activeActionMenuDescriptor());
  const hasContextMenu = Boolean(activeContextMenuDescriptor());
  const hasToolbarMenu = compactToolbarMenuIsOpen();
  const hasSidebar = route === "gallery" && mobileSidebarOverlayIsOpen();
  const historyContext = hasConfirmation
    ? {
        ...(context || {}),
        confirmationBaseLevel: state.confirmationBaseLevel,
        ...(hasTagManager
          ? {
              tagManagerBaseLevel: state.tagManagerBaseLevel,
              ...currentTagManagerHistoryContext(),
            }
          : {}),
        ...(hasSourceManager
          ? {
              sourceManagerBaseLevel: state.sourceManagerBaseLevel,
              ...currentSourceManagerHistoryContext(),
            }
          : {}),
        ...(hasStorageMaintenance
          ? {
              storageBaseLevel: state.storageBaseLevel,
              ...currentStorageMaintenanceHistoryContext(),
            }
          : {}),
        ...(hasActionMenu
          ? {
              actionMenuBaseLevel: state.actionMenuBaseLevel,
              actionMenuKind: state.actionMenuKind,
            }
          : {}),
      }
    : hasWorldMapLocationBackfill
    ? {
        ...(context || {}),
        worldMapLocationBackfillBaseLevel: state.worldMap.locationBackfill.baseLevel,
        ...currentWorldMapLocationBackfillHistoryContext(),
      }
    : hasWorldMapPlaceTags
    ? {
        ...(context || {}),
        worldMapPlaceTagsBaseLevel: state.worldMap.placeTags.baseLevel,
        ...currentWorldMapPlaceTagsHistoryContext(),
      }
    : hasSlimmingIdenticalCleanup
    ? {
        ...(context || {}),
        slimmingIdenticalCleanupBaseLevel: state.slimming.identicalCleanup.baseLevel,
      }
    : hasSlimmingVerification
    ? {
        ...(context || {}),
        slimmingVerificationBaseLevel:
          state.slimming.identicalCleanup.verificationBaseLevel,
      }
    : hasSlimmingRecycleExplanation
    ? {
        ...(context || {}),
        slimmingRecycleExplanationBaseLevel: state.slimming.recycle.explanationBaseLevel,
      }
    : hasSlimmingSetup
    ? {
        ...(context || {}),
        slimmingSetupBaseLevel: state.slimming.setup.baseLevel,
        ...currentSlimmingSetupHistoryContext(),
      }
    : hasSlimmingThreshold
    ? {
        ...(context || {}),
        slimmingThresholdBaseLevel: state.slimming.thresholdEditor.baseLevel,
      }
    : hasTrainingSetup
    ? {
        ...(context || {}),
        trainingSetupBaseLevel: state.training.setup.baseLevel,
        ...currentTrainingSetupHistoryContext(),
      }
    : hasTagSuggestion
    ? {
        ...(context || {}),
        tagSuggestionBaseLevel: state.tagLibrarySuggestions.dialog.baseLevel,
        ...currentTagSuggestionHistoryContext(),
      }
    : hasNewTag
    ? {
        ...(context || {}),
        newTagBaseLevel: state.newTagBaseLevel,
        ...currentNewTagHistoryContext(),
      }
    : hasTagManager
    ? {
        ...(context || {}),
        tagManagerBaseLevel: state.tagManagerBaseLevel,
        ...currentTagManagerHistoryContext(),
      }
    : hasSourceManager
    ? {
        ...(context || {}),
        sourceManagerBaseLevel: state.sourceManagerBaseLevel,
        ...currentSourceManagerHistoryContext(),
      }
    : hasStorageMaintenance
    ? {
        ...(context || {}),
        storageBaseLevel: state.storageBaseLevel,
        ...currentStorageMaintenanceHistoryContext(),
      }
    : hasSuggestionThreshold || hasGeneralSettings
    ? {
        ...(context || {}),
        generalSettingsBaseLevel: state.generalSettings.baseLevel,
        ...currentGeneralSettingsHistoryContext(),
      }
    : hasKeyboardShortcuts
    ? {
        ...(context || {}),
        keyboardShortcutsBaseLevel: state.keyboardShortcutsBaseLevel,
      }
    : hasCommandPalette
    ? {
        ...(context || {}),
        commandPaletteBaseLevel: state.commandPaletteBaseLevel,
      }
    : hasJobs
    ? {
        ...(context || {}),
        jobsBaseLevel: state.jobsBaseLevel,
      }
    : hasFilter
    ? {
        ...(context || {}),
        filterBaseLevel: state.filterBaseLevel,
      }
    : hasLayoutMenu
    ? {
        ...(context || {}),
        layoutMenuBaseLevel: state.layoutMenuBaseLevel,
        layoutMenuKind: state.layoutMenuKind,
      }
    : hasActionMenu
    ? {
        ...(context || {}),
        actionMenuBaseLevel: state.actionMenuBaseLevel,
        actionMenuKind: state.actionMenuKind,
      }
    : hasContextMenu
    ? {
        ...(context || {}),
        contextMenuBaseLevel: state.contextMenuBaseLevel,
        contextMenuKind: state.contextMenuSession?.kind || null,
      }
    : hasToolbarMenu
    ? {
        ...(context || {}),
        toolbarMenuBaseLevel: state.compactToolbarBaseLevel,
      }
    : context;
  const hasLightbox = Boolean(workspaceLightboxHistoryContext(route, historyContext));
  const hasInspector = route === "gallery" && galleryInspectorOverlayIsOpen();
  const navigationLevel = hasConfirmation
    && (mode === "pushConfirmation" || current?.navigationLevel === "confirmation")
    ? "confirmation"
    : hasWorldMapLocationBackfill
    && (mode === "pushWorldMapLocationBackfill"
      || current?.navigationLevel === "worldMapLocationBackfill")
    ? "worldMapLocationBackfill"
    : hasWorldMapPlaceTags
    && (mode === "pushWorldMapPlaceTags"
      || current?.navigationLevel === "worldMapPlaceTags")
    ? "worldMapPlaceTags"
    : hasSlimmingIdenticalCleanup
    && (mode === "pushSlimmingIdenticalCleanup"
      || current?.navigationLevel === "slimmingIdenticalCleanup")
    ? "slimmingIdenticalCleanup"
    : hasSlimmingVerification
    && (mode === "pushSlimmingVerification"
      || current?.navigationLevel === "slimmingVerification")
    ? "slimmingVerification"
    : hasSlimmingRecycleExplanation
    && (mode === "pushSlimmingRecycleExplanation"
      || current?.navigationLevel === "slimmingRecycleExplanation")
    ? "slimmingRecycleExplanation"
    : hasSlimmingSetup
    && (mode === "pushSlimmingSetup" || current?.navigationLevel === "slimmingSetup")
    ? "slimmingSetup"
    : hasSlimmingThreshold
    && (mode === "pushSlimmingThreshold" || current?.navigationLevel === "slimmingThreshold")
    ? "slimmingThreshold"
    : hasTrainingSetup
    && (mode === "pushTrainingSetup" || current?.navigationLevel === "trainingSetup")
    ? "trainingSetup"
    : hasTagSuggestion
    && (mode === "pushTagSuggestion" || current?.navigationLevel === "tagSuggestion")
    ? "tagSuggestion"
    : hasNewTag
    && (mode === "pushNewTag" || current?.navigationLevel === "newTag")
    ? "newTag"
    : hasTagManager
    && (mode === "pushTagManager" || current?.navigationLevel === "tagManager")
    ? "tagManager"
    : hasSourceManager
    && (mode === "pushSourceManager" || current?.navigationLevel === "sourceManager")
    ? "sourceManager"
    : hasStorageMaintenance
    && (mode === "pushStorageMaintenance"
      || current?.navigationLevel === "storageMaintenance")
    ? "storageMaintenance"
    : hasSuggestionThreshold
    && (mode === "pushSuggestionThreshold"
      || current?.navigationLevel === "suggestionThreshold")
    ? "suggestionThreshold"
    : hasGeneralSettings
    && (mode === "pushGeneralSettings" || current?.navigationLevel === "generalSettings")
    ? "generalSettings"
    : hasKeyboardShortcuts
    && (mode === "pushKeyboardShortcuts"
      || current?.navigationLevel === "keyboardShortcuts")
    ? "keyboardShortcuts"
    : hasCommandPalette
    && (mode === "pushCommandPalette" || mode === "replaceOverlay"
      || current?.navigationLevel === "commandPalette")
    ? "commandPalette"
    : hasJobs
    && (mode === "pushJobs" || mode === "replaceOverlay"
      || current?.navigationLevel === "jobs")
    ? "jobs"
    : hasFilter
    && (mode === "pushFilter" || mode === "replaceOverlay"
      || current?.navigationLevel === "filter")
    ? "filter"
    : hasLayoutMenu
    && (mode === "pushLayoutMenu" || mode === "replaceOverlay"
      || current?.navigationLevel === "layoutMenu")
    ? "layoutMenu"
    : hasActionMenu
    && (mode === "pushActionMenu" || mode === "replaceOverlay"
      || current?.navigationLevel === "actionMenu")
    ? "actionMenu"
    : hasContextMenu
    && (mode === "pushContextMenu" || mode === "replaceOverlay"
      || current?.navigationLevel === "contextMenu")
    ? "contextMenu"
    : hasToolbarMenu
    && (mode === "pushToolbarMenu" || mode === "replaceOverlay"
      || current?.navigationLevel === "toolbarMenu")
    ? "toolbarMenu"
    : hasSidebar
    && (mode === "pushSidebar" || mode === "replaceOverlay"
      || current?.navigationLevel === "sidebar")
    ? "sidebar"
    : hasLightbox
    && (mode === "pushLightbox" || current?.navigationLevel === "lightbox")
    ? "lightbox"
    : (hasInspector
        && (mode === "pushInspector" || current?.navigationLevel === "inspector")
      ? "inspector"
      : "workspace");
  const nextState = {
    ...(history.state || {}),
    [WORKSPACE_HISTORY_KEY]: workspaceHistoryEntry(route, historyContext, navigationLevel),
  };
  if ([
    "pushConfirmation",
    "pushWorldMapLocationBackfill",
    "pushWorldMapPlaceTags",
    "pushSlimmingIdenticalCleanup",
    "pushSlimmingVerification",
    "pushSlimmingRecycleExplanation",
    "pushSlimmingSetup",
    "pushSlimmingThreshold",
    "pushTrainingSetup",
    "pushTagSuggestion",
    "pushNewTag",
    "pushTagManager",
    "pushSourceManager",
    "pushStorageMaintenance",
    "pushSuggestionThreshold",
    "pushGeneralSettings",
    "pushKeyboardShortcuts",
    "pushCommandPalette",
    "pushJobs",
    "pushFilter",
    "pushLayoutMenu",
    "pushActionMenu",
    "pushContextMenu",
    "pushToolbarMenu",
    "pushSidebar",
    "pushLightbox",
    "pushInspector",
  ].includes(mode)) {
    history.pushState(nextState, "", location.href);
  } else if (mode === "replace" || current?.route === route) {
    history.replaceState(nextState, "", location.href);
  } else {
    history.pushState(nextState, "", location.href);
  }
}

function currentGalleryHistoryContext() {
  return {
    galleryMediaKind: state.mediaKind,
    gallerySourceID: state.libraryScope === "all" ? (state.selectedSourceID || null) : null,
    galleryScope: state.libraryScope === "favorites" ? "favorites" : "all",
    ...(state.folderScope && state.folderNavigation.selectedSessionID
      ? { galleryFolderSessionID: state.folderNavigation.selectedSessionID }
      : {}),
    gallerySort: state.sort,
    galleryFilters: cloneFilters(state.filters),
    gallerySelectedAssetID: state.selectedAssetID || null,
    gallerySelectionMode: state.selectionMode,
    gallerySelectedAssetIDs: [...state.selectedAssetIDs],
    gallerySelectionAnchorID: state.selectionAnchorID || null,
    galleryLoadedCount: Math.min(GALLERY_HISTORY_LOADED_LIMIT, state.assets.length),
    galleryScrollTop: elements.libraryScroll.scrollTop,
    galleryLightbox: currentLightboxHistoryContext("library"),
    ...(mobileSidebarOverlayIsOpen()
      ? { gallerySidebarBaseLevel: state.sidebarOverlayBaseLevel }
      : {}),
  };
}

function currentWorkspaceHistoryContext(route = visibleWorkspaceRoute()) {
  switch (route) {
  case "gallery":
    return currentGalleryHistoryContext();
  case "review":
    return {
      galleryContext: currentGalleryHistoryContext(),
      ...(state.review.returnTarget?.workspace === "training"
        ? { returnToTrainingRunID: state.review.returnTarget.runID }
        : {}),
      reviewMode: state.review.mode,
      reviewTagID: elements.reviewTagSelect.value || null,
      reviewMediaKind: state.mediaKind,
      reviewSourceIDs: resolvedReviewSourceFilter(),
      reviewAssetID: state.review.items[state.review.selectedIndex]?.assetID || null,
      reviewItemKey: reviewItemKey(state.review.items[state.review.selectedIndex]),
      reviewSelectionMode: state.review.mode === "queue" && state.review.selectionMode,
      reviewSelectedAssetIDs: state.review.mode === "queue"
        ? [...state.review.selectedAssetIDs].slice(0, GALLERY_HISTORY_LOADED_LIMIT)
        : [],
      reviewSelectionAnchorKey: state.review.mode === "queue"
        ? reviewItemKey(state.review.items[state.review.selectionAnchorIndex])
        : null,
      reviewLoadedCount: Math.min(GALLERY_HISTORY_LOADED_LIMIT, state.review.items.length),
      reviewQueueScrollTop: elements.reviewQueuePane.scrollTop,
      reviewGridScrollLeft: elements.reviewGrid.scrollLeft,
      reviewLightbox: currentLightboxHistoryContext("review"),
    };
  case "training":
    captureTrainingRunListScroll();
    return {
      galleryContext: currentGalleryHistoryContext(),
      ...(state.training.returnTarget?.workspace === "review"
        ? { returnToReview: { ...state.training.returnTarget } }
        : {}),
      trainingMediaKind: state.training.mediaKind,
      trainingMethod: state.training.method || null,
      trainingRunScope: state.training.runScope,
      trainingRunID: state.training.selectedRunID || state.training.focusedRunID || null,
      trainingRunScrollTop: elements.trainingRunPane.scrollTop,
      trainingDetailScrollTop: elements.trainingDetailPane.scrollTop,
    };
  case "slimming":
    return {
      galleryContext: currentGalleryHistoryContext(),
      slimmingMediaKind: state.slimming.mediaKind,
      slimmingView: state.slimming.view,
      slimmingJobID: state.slimming.selectedJobID,
      slimmingClusterID: state.slimming.selectedClusterID,
      slimmingClusterScope: state.slimming.clusterScope,
      slimmingNavigatorScrollTop: elements.slimmingNavigatorPane.scrollTop,
      slimmingLightbox: currentLightboxHistoryContext("slimming"),
    };
  case "worldMap":
    return {
      galleryContext: currentGalleryHistoryContext(),
      worldMapClusterID: state.worldMap.selectedClusterID,
      worldMapViewport: normalizedWorldMapViewport(state.worldMap.viewport),
      worldMapLightbox: currentLightboxHistoryContext("worldMap"),
    };
  default:
    return null;
  }
}

function galleryHistoryIdentifier(value) {
  return typeof value === "string" && value.length > 0 && value.length <= 256
    ? value
    : null;
}

function workspaceHistoryFiniteNumber(value, fallback = 0, limit = 100_000) {
  const parsed = Number(value);
  if (!Number.isFinite(parsed)) return fallback;
  return Math.min(limit, Math.max(-limit, parsed));
}

function normalizedLightboxHistoryContext(raw) {
  const context = raw && typeof raw === "object" ? raw : null;
  const assetID = galleryHistoryIdentifier(context?.assetID);
  if (!assetID) return null;
  return {
    assetID,
    reviewKey: galleryHistoryIdentifier(context?.reviewKey),
    scale: Math.min(
      LIGHTBOX_MAX_SCALE,
      Math.max(LIGHTBOX_MIN_SCALE, workspaceHistoryFiniteNumber(context.scale, 1, 8))
    ),
    offsetX: workspaceHistoryFiniteNumber(context.offsetX),
    offsetY: workspaceHistoryFiniteNumber(context.offsetY),
    videoTime: Math.max(0, workspaceHistoryFiniteNumber(context.videoTime, 0, 86_400)),
    original: context.original === true,
    preserveSelection: context.preserveSelection === true,
  };
}

function currentLightboxHistoryContext(expectedContext) {
  if (elements.lightbox.classList.contains("hidden")
    || state.lightboxContext !== expectedContext
    || !state.lightboxAssetID) return null;
  return normalizedLightboxHistoryContext({
    assetID: state.lightboxAssetID,
    reviewKey: expectedContext === "review" ? state.lightboxReviewKey : null,
    scale: state.lightboxViewportScale,
    offsetX: state.lightboxViewportOffsetX,
    offsetY: state.lightboxViewportOffsetY,
    videoTime: lightboxMediaKind() === "video" ? elements.lightboxVideo.currentTime : 0,
    original: lightboxMediaKind() !== "video"
      && state.lightboxOriginalAssetID === state.lightboxAssetID,
    preserveSelection: state.lightboxPreservesSelection,
  });
}

function normalizedGalleryHistoryContext(raw, { validateCatalog = false } = {}) {
  const context = raw && typeof raw === "object" ? raw : {};
  const mediaKind = ["image", "video"].includes(context.galleryMediaKind)
    ? context.galleryMediaKind
    : "image";
  const acceptedMediaTypes = new Set(
    MEDIA_FORMAT_GROUPS
      .filter((group) => group.mediaKinds.includes(mediaKind))
      .flatMap((group) => group.mediaTypes)
  );
  const sourceID = galleryHistoryIdentifier(context.gallerySourceID);
  const validSourceID = validateCatalog
    ? (state.sources.some((source) => source.id === sourceID) ? sourceID : null)
    : sourceID;
  const requestedScope = context.galleryScope === "favorites" ? "favorites" : "all";
  const scope = requestedScope === "favorites" && (!validateCatalog || supportsFavorites())
    ? "favorites"
    : "all";
  const folderSessionID = galleryHistoryIdentifier(context.galleryFolderSessionID);
  const rememberedFolderScope = folderSessionID
    ? state.folderNavigation.historyScopes.get(folderSessionID)
    : null;
  const folderScope = scope === "all"
    && rememberedFolderScope?.sourceID === validSourceID
    ? cloneFolderScope(rememberedFolderScope)
    : null;
  const activeTagIDs = validateCatalog ? new Set(activeTags().map((tag) => tag.id)) : null;
  const seenTagIDs = new Set();
  const tagConditions = [];
  for (const condition of Array.isArray(context.galleryFilters?.tagConditions)
    ? context.galleryFilters.tagConditions
    : []) {
    const tagID = galleryHistoryIdentifier(condition?.tagID);
    if (!tagID
      || seenTagIDs.has(tagID)
      || (activeTagIDs && !activeTagIDs.has(tagID))
      || !["accepted", "rejected", "excluded"].includes(condition?.decision)) continue;
    seenTagIDs.add(tagID);
    tagConditions.push({ tagID, decision: condition.decision });
    if (tagConditions.length >= 100) break;
  }
  const tagPresence = ["any", "tagged", "untagged"].includes(
    context.galleryFilters?.tagPresence
  ) ? context.galleryFilters.tagPresence : "any";
  const selectedAssetIDs = [...new Set(
    (Array.isArray(context.gallerySelectedAssetIDs)
      ? context.gallerySelectedAssetIDs
      : [])
      .map(galleryHistoryIdentifier)
      .filter(Boolean)
  )].slice(0, GALLERY_HISTORY_LOADED_LIMIT);
  const requestedSelectedAssetID = galleryHistoryIdentifier(context.gallerySelectedAssetID);
  const requestedSelectionAnchorID = galleryHistoryIdentifier(context.gallerySelectionAnchorID);
  const selectionMode = Boolean(context.gallerySelectionMode && selectedAssetIDs.length);
  const selectedAssetID = selectionMode
    ? (selectedAssetIDs.includes(requestedSelectedAssetID)
      ? requestedSelectedAssetID
      : selectedAssetIDs[0])
    : requestedSelectedAssetID;
  const selectionAnchorID = selectionMode
    ? (selectedAssetIDs.includes(requestedSelectionAnchorID)
      ? requestedSelectionAnchorID
      : selectedAssetID)
    : null;
  const loadedCount = Math.min(
    GALLERY_HISTORY_LOADED_LIMIT,
    Math.max(0, Math.floor(Number(context.galleryLoadedCount) || 0))
  );
  return {
    mediaKind,
    sourceID: scope === "all" ? validSourceID : null,
    scope,
    folderScope,
    folderSessionID: folderScope ? folderSessionID : null,
    sort: GALLERY_HISTORY_SORTS.has(context.gallerySort)
      ? context.gallerySort
      : "fileNameAscending",
    filters: {
      mediaKind,
      availabilities: [...new Set(
        (Array.isArray(context.galleryFilters?.availabilities)
          ? context.galleryFilters.availabilities
          : [])
          .filter((value) => GALLERY_HISTORY_AVAILABILITIES.has(value))
      )],
      mediaTypes: [...new Set(
        (Array.isArray(context.galleryFilters?.mediaTypes)
          ? context.galleryFilters.mediaTypes
          : [])
          .filter((value) => acceptedMediaTypes.has(value))
      )],
      tagPresence,
      tagMatchMode: context.galleryFilters?.tagMatchMode === "any" ? "any" : "all",
      tagConditions: tagPresence === "any" ? tagConditions : [],
    },
    selectedAssetID,
    selectionMode,
    selectedAssetIDs: selectionMode ? selectedAssetIDs : [],
    selectionAnchorID,
    loadedCount,
    scrollTop: workspaceHistoryScrollTop(context.galleryScrollTop),
    lightbox: normalizedLightboxHistoryContext(context.galleryLightbox),
  };
}

function applyGalleryHistoryContext(raw, options = {}) {
  const context = normalizedGalleryHistoryContext(raw, options);
  state.mediaKind = context.mediaKind;
  state.selectedSourceID = context.sourceID || "";
  state.libraryScope = context.scope;
  state.worldMapGalleryScope = null;
  state.folderScope = cloneFolderScope(context.folderScope);
  state.folderNavigation.selectedSessionID = context.folderSessionID || null;
  state.searchText = "";
  state.sort = context.sort;
  state.filters = cloneFilters(context.filters);
  state.filterDraft = null;
  state.selectedAssetID = context.selectedAssetID;
  state.selectedDetail = null;
  state.selectionMode = context.selectionMode;
  state.selectedAssetIDs = new Set(context.selectedAssetIDs);
  state.selectionAnchorID = context.selectionAnchorID;
  state.inspectorDismissed = false;
  state.inspectorDismissedByUser = false;
  return context;
}

function workspaceHistoryScrollTop(value) {
  const parsed = Number(value);
  return Number.isFinite(parsed) && parsed >= 0 ? parsed : 0;
}

function waitForWorkspaceLayout() {
  return new Promise((resolve) => {
    requestAnimationFrame(() => requestAnimationFrame(resolve));
  });
}

function checkpointActiveWorkspaceHistory() {
  if (!state.workspaceNavigation.initialized
    || state.workspaceNavigation.applyingHistory
    || state.workspaceNavigation.pendingRestoreEntry
    || elements.appView.classList.contains("hidden")) return;
  const route = visibleWorkspaceRoute();
  recordWorkspaceHistory(route, currentWorkspaceHistoryContext(route), "replace");
}

function scheduleWorkspaceHistoryCheckpoint() {
  if (state.workspaceNavigation.checkpointFrame != null) return;
  state.workspaceNavigation.checkpointFrame = requestAnimationFrame(() => {
    state.workspaceNavigation.checkpointFrame = null;
    checkpointActiveWorkspaceHistory();
  });
}

function closeVisibleWorkspaceOneLevel({ restoreFocus = true } = {}) {
  switch (visibleWorkspaceRoute()) {
  case "review": closeReviewWorkspace({ restoreFocus }); break;
  case "training": closeTrainingWorkspace({ restoreFocus }); break;
  case "slimming": closeSlimmingWorkspace({ restoreFocus }); break;
  case "worldMap": closeWorldMapWorkspace({ restoreFocus }); break;
  case "galleryOverview": closeGalleryOverviewWorkspace({ restoreFocus }); break;
  default: break;
  }
}

function closeAllWorkspacesToGallery({ restoreFocus = true } = {}) {
  hideContextMenus();
  closeConfirmation({
    restoreFocus: false,
    checkpoint: false,
    preserveState: false,
  });
  closeWorldMapLocationBackfill({
    restoreFocus: false,
    checkpoint: false,
    preserveState: false,
    refreshMap: false,
  });
  closeWorldMapPlaceTags({
    restoreFocus: false,
    checkpoint: false,
    preserveState: false,
  });
  closeSlimmingIdenticalCleanupDialog({
    restoreFocus: false,
    checkpoint: false,
    preserveState: false,
  });
  closeSlimmingVerificationReport({
    restoreFocus: false,
    checkpoint: false,
    preserveState: false,
  });
  closeSlimmingRecycleExplanation({
    restoreFocus: false,
    checkpoint: false,
    preserveState: false,
  });
  closeSlimmingSetupDialog({ restoreFocus: false, checkpoint: false, preserveState: false });
  closeSlimmingThresholdEditor({ restoreFocus: false, checkpoint: false, preserveState: false });
  closeTrainingSetupDialog({ restoreFocus: false, checkpoint: false, preserveState: false });
  closeTagSuggestionDialog({ restoreFocus: false, checkpoint: false, preserveState: false });
  closeNewTagDialog({ restoreFocus: false, checkpoint: false, preserveState: false });
  closeTagManager({ restoreFocus: false, checkpoint: false, preserveState: false });
  closeSourceManager({ restoreFocus: false, checkpoint: false });
  closeStorageMaintenance({ restoreFocus: false, checkpoint: false });
  closeGeneralSettings({ restoreFocus: false, checkpoint: false });
  closeKeyboardShortcuts({ restoreFocus: false, checkpoint: false });
  closeCommandPalette({ restoreFocus: false, checkpoint: false });
  closeFilterPopover({ restoreFocus: false, checkpoint: false, preserveState: false });
  closeLayoutMenu({ restoreFocus: false, checkpoint: false, preserveState: false });
  closeActionMenu({ restoreFocus: false, checkpoint: false, preserveState: false });
  closeCompactToolbarMenu({ restoreFocus: false, checkpoint: false });
  closeMobileSidebar({ restoreFocus: false, checkpoint: false });
  if (!elements.lightbox.classList.contains("hidden")) closeLightbox({ restoreFocus });
  let remaining = 6;
  while (visibleWorkspaceRoute() !== "gallery" && remaining > 0) {
    closeVisibleWorkspaceOneLevel({ restoreFocus });
    remaining -= 1;
  }
  scheduleDeferredGalleryAssetsRefresh();
}

function scheduleDeferredGalleryAssetsRefresh() {
  if (!state.galleryAssetsRefreshPending || state.galleryAssetsRefreshFrame != null) return;
  state.galleryAssetsRefreshFrame = requestAnimationFrame(() => {
    state.galleryAssetsRefreshFrame = null;
    if (!state.galleryAssetsRefreshPending
      || visibleWorkspaceRoute() !== "gallery"
      || elements.appView.classList.contains("hidden")) return;
    state.galleryAssetsRefreshPending = false;
    void loadAssets({
      preserveSelection: true,
      preserveUnchangedGrid: true,
      preserveLoadedWindow: true,
    });
  });
}

async function applyWorkspaceHistoryEntry(entry, { restoringReload = false } = {}) {
  const activeEntry = entry?.workspaceGeneration === state.workspaceGeneration ? entry : null;
  const target = activeEntry?.route || "gallery";
  const context = activeEntry?.context || {};
  let checkpointWorkspaceHistoryAfterApply = false;
  state.workspaceNavigation.applyingHistory = true;
  try {
    const current = visibleWorkspaceRoute();
    if (target === current) {
      const navigationLevel = activeEntry?.navigationLevel || "workspace";
      const closingReviewSourceMenu = target === "review"
        && activeActionMenuDescriptor()?.kind === "reviewSources"
        && navigationLevel !== "actionMenu";
      const baseLevel = workspaceNavigationBaseLevel(navigationLevel, context);
      const inspectorLevel = galleryInspectorHistoryLevel(navigationLevel, context);
      reconcileGalleryInspectorFromWorkspaceHistory(
        target,
        inspectorLevel
      );
      reconcileMobileSidebarFromWorkspaceHistory(target, baseLevel, context);
      reconcileLightboxFromWorkspaceHistory(target, context);
      reconcileCompactToolbarMenuFromWorkspaceHistory(
        target,
        navigationLevel,
        context
      );
      reconcileJobsPopoverFromWorkspaceHistory(target, navigationLevel, context);
      reconcileFilterPopoverFromWorkspaceHistory(target, navigationLevel, context);
      reconcileLayoutMenuFromWorkspaceHistory(target, navigationLevel, context);
      reconcileActionMenuFromWorkspaceHistory(target, navigationLevel, context);
      checkpointWorkspaceHistoryAfterApply = closingReviewSourceMenu;
      reconcileContextMenuFromWorkspaceHistory(target, navigationLevel, context);
      await reconcileCommandPaletteFromWorkspaceHistory(
        target,
        navigationLevel,
        context
      );
      reconcileKeyboardShortcutsFromWorkspaceHistory(
        target,
        navigationLevel,
        context
      );
      checkpointWorkspaceHistoryAfterApply =
        await reconcileGeneralSettingsFromWorkspaceHistory(
          target,
          navigationLevel,
          context
        ) || checkpointWorkspaceHistoryAfterApply;
      checkpointWorkspaceHistoryAfterApply = await reconcileWorldMapLocationBackfillFromWorkspaceHistory(
        target,
        navigationLevel,
        context
      ) || checkpointWorkspaceHistoryAfterApply;
      checkpointWorkspaceHistoryAfterApply = await reconcileWorldMapPlaceTagsFromWorkspaceHistory(
        target,
        navigationLevel,
        context
      ) || checkpointWorkspaceHistoryAfterApply;
      reconcileSlimmingIdenticalCleanupFromWorkspaceHistory(
        target,
        navigationLevel,
        context
      );
      reconcileSlimmingVerificationFromWorkspaceHistory(target, navigationLevel, context);
      reconcileSlimmingRecycleExplanationFromWorkspaceHistory(
        target,
        navigationLevel,
        context
      );
      checkpointWorkspaceHistoryAfterApply = await reconcileSlimmingSetupFromWorkspaceHistory(
        target,
        navigationLevel,
        context
      ) || checkpointWorkspaceHistoryAfterApply;
      reconcileSlimmingThresholdFromWorkspaceHistory(target, navigationLevel, context);
      checkpointWorkspaceHistoryAfterApply = await reconcileTrainingSetupFromWorkspaceHistory(
        target,
        navigationLevel,
        context
      ) || checkpointWorkspaceHistoryAfterApply;
      checkpointWorkspaceHistoryAfterApply = await reconcileTagSuggestionFromWorkspaceHistory(
        target,
        navigationLevel,
        context
      ) || checkpointWorkspaceHistoryAfterApply;
      checkpointWorkspaceHistoryAfterApply = await reconcileNewTagFromWorkspaceHistory(
        target,
        navigationLevel,
        context
      ) || checkpointWorkspaceHistoryAfterApply;
      checkpointWorkspaceHistoryAfterApply = await reconcileTagManagerFromWorkspaceHistory(
        target,
        navigationLevel,
        context
      ) || checkpointWorkspaceHistoryAfterApply;
      checkpointWorkspaceHistoryAfterApply = await reconcileSourceManagerFromWorkspaceHistory(
        target,
        navigationLevel,
        context
      ) || checkpointWorkspaceHistoryAfterApply;
      checkpointWorkspaceHistoryAfterApply =
        await reconcileStorageMaintenanceFromWorkspaceHistory(
          target,
          navigationLevel,
          context
        ) || checkpointWorkspaceHistoryAfterApply;
      reconcileConfirmationFromWorkspaceHistory(target, navigationLevel, context);
      return;
    }
    if (target === "gallery") {
      closeAllWorkspacesToGallery();
      const navigationLevel = activeEntry?.navigationLevel || "workspace";
      const baseLevel = workspaceNavigationBaseLevel(navigationLevel, context);
      const inspectorLevel = galleryInspectorHistoryLevel(navigationLevel, context);
      reconcileGalleryInspectorFromWorkspaceHistory(
        "gallery",
        inspectorLevel,
        { focus: false, restoreFocusOnClose: false }
      );
      reconcileMobileSidebarFromWorkspaceHistory("gallery", baseLevel, context);
      reconcileLightboxFromWorkspaceHistory("gallery", context);
      reconcileCompactToolbarMenuFromWorkspaceHistory(
        "gallery",
        navigationLevel,
        context
      );
      reconcileJobsPopoverFromWorkspaceHistory("gallery", navigationLevel, context);
      reconcileFilterPopoverFromWorkspaceHistory("gallery", navigationLevel, context);
      reconcileLayoutMenuFromWorkspaceHistory("gallery", navigationLevel, context);
      reconcileActionMenuFromWorkspaceHistory("gallery", navigationLevel, context);
      reconcileContextMenuFromWorkspaceHistory("gallery", navigationLevel, context);
      await reconcileCommandPaletteFromWorkspaceHistory(
        "gallery",
        navigationLevel,
        context
      );
      reconcileKeyboardShortcutsFromWorkspaceHistory(
        "gallery",
        navigationLevel,
        context
      );
      checkpointWorkspaceHistoryAfterApply =
        await reconcileGeneralSettingsFromWorkspaceHistory(
          "gallery",
          navigationLevel,
          context
        ) || checkpointWorkspaceHistoryAfterApply;
      checkpointWorkspaceHistoryAfterApply = await reconcileWorldMapLocationBackfillFromWorkspaceHistory(
        "gallery",
        navigationLevel,
        context
      ) || checkpointWorkspaceHistoryAfterApply;
      checkpointWorkspaceHistoryAfterApply = await reconcileWorldMapPlaceTagsFromWorkspaceHistory(
        "gallery",
        navigationLevel,
        context
      ) || checkpointWorkspaceHistoryAfterApply;
      reconcileSlimmingIdenticalCleanupFromWorkspaceHistory(
        "gallery",
        navigationLevel,
        context
      );
      reconcileSlimmingVerificationFromWorkspaceHistory("gallery", navigationLevel, context);
      reconcileSlimmingRecycleExplanationFromWorkspaceHistory(
        "gallery",
        navigationLevel,
        context
      );
      checkpointWorkspaceHistoryAfterApply = await reconcileSlimmingSetupFromWorkspaceHistory(
        "gallery",
        navigationLevel,
        context
      ) || checkpointWorkspaceHistoryAfterApply;
      reconcileSlimmingThresholdFromWorkspaceHistory("gallery", navigationLevel, context);
      checkpointWorkspaceHistoryAfterApply = await reconcileTrainingSetupFromWorkspaceHistory(
        "gallery",
        navigationLevel,
        context
      ) || checkpointWorkspaceHistoryAfterApply;
      checkpointWorkspaceHistoryAfterApply = await reconcileTagSuggestionFromWorkspaceHistory(
        "gallery",
        navigationLevel,
        context
      ) || checkpointWorkspaceHistoryAfterApply;
      checkpointWorkspaceHistoryAfterApply = await reconcileNewTagFromWorkspaceHistory(
        "gallery",
        navigationLevel,
        context
      ) || checkpointWorkspaceHistoryAfterApply;
      checkpointWorkspaceHistoryAfterApply = await reconcileTagManagerFromWorkspaceHistory(
        "gallery",
        navigationLevel,
        context
      ) || checkpointWorkspaceHistoryAfterApply;
      checkpointWorkspaceHistoryAfterApply = await reconcileSourceManagerFromWorkspaceHistory(
        "gallery",
        navigationLevel,
        context
      ) || checkpointWorkspaceHistoryAfterApply;
      checkpointWorkspaceHistoryAfterApply =
        await reconcileStorageMaintenanceFromWorkspaceHistory(
          "gallery",
          navigationLevel,
          context
        ) || checkpointWorkspaceHistoryAfterApply;
      reconcileConfirmationFromWorkspaceHistory("gallery", navigationLevel, context);
      return;
    }
    if (target === "review" && current === "training"
      && state.training.returnTarget?.workspace === "review") {
      closeTrainingWorkspace();
      return;
    }
    if (target === "training" && current === "review"
      && state.review.returnTarget?.workspace === "training") {
      closeReviewWorkspace();
      return;
    }
    closeAllWorkspacesToGallery();
    if (target === "review") {
      if (["image", "video"].includes(context.reviewMediaKind)
        && context.reviewMediaKind !== state.mediaKind) {
        await switchMediaKind(context.reviewMediaKind);
      }
      applyReviewSourceFilterHistoryContext(context);
      await openReviewWorkspace({
        returnToTrainingRunID: context.returnToTrainingRunID || null,
        initialMode: context.reviewMode || "overview",
        initialTagID: context.reviewTagID || null,
        historyMode: "none",
        refreshTagSuggestions: !restoringReload,
      });
      const reviewLoadedTarget = Math.min(
        GALLERY_HISTORY_LOADED_LIMIT,
        Math.max(48, Math.floor(Number(context.reviewLoadedCount) || 48))
      );
      while (state.review.items.length < reviewLoadedTarget && state.review.nextCursor) {
        const previousCursor = state.review.nextCursor;
        const previousCount = state.review.items.length;
        await loadReviewQueue({
          append: true,
          preserveUnchangedGrid: true,
          schedulePagination: false,
        });
        if (state.review.items.length <= previousCount
          || state.review.nextCursor === previousCursor) break;
      }
      if (state.review.mode === "queue") applyReviewSelectionHistoryContext(context);
      await waitForWorkspaceLayout();
      elements.reviewQueuePane.scrollTop = workspaceHistoryScrollTop(
        context.reviewQueueScrollTop
      );
      elements.reviewGrid.scrollLeft = workspaceHistoryScrollTop(
        context.reviewGridScrollLeft
      );
      restoreLightboxFromHistory(context.reviewLightbox, "review");
      checkpointWorkspaceHistoryAfterApply = true;
    } else if (target === "training") {
      if (["image", "video"].includes(context.trainingMediaKind)) {
        state.training.mediaKind = context.trainingMediaKind;
      }
      if (typeof context.trainingMethod === "string") {
        state.training.method = context.trainingMethod;
      }
      if (["all", "batch", "single"].includes(context.trainingRunScope)) {
        state.training.runScope = context.trainingRunScope;
      }
      if (context.trainingRunID) state.training.focusedRunID = context.trainingRunID;
      if (Object.prototype.hasOwnProperty.call(context, "trainingRunScrollTop")) {
        state.training.runListScrollOffsets.set(
          trainingRunListContextKey(),
          workspaceHistoryScrollTop(context.trainingRunScrollTop)
        );
      }
      await openTrainingWorkspace({
        returnToReview: context.returnToReview || null,
        historyMode: "none",
      });
      await waitForWorkspaceLayout();
      if (Object.prototype.hasOwnProperty.call(context, "trainingRunScrollTop")) {
        elements.trainingRunPane.scrollTop = workspaceHistoryScrollTop(
          context.trainingRunScrollTop
        );
      }
      if (Object.prototype.hasOwnProperty.call(context, "trainingDetailScrollTop")) {
        elements.trainingDetailPane.scrollTop = workspaceHistoryScrollTop(
          context.trainingDetailScrollTop
        );
      }
    } else if (target === "slimming") {
      if (["image", "video"].includes(context.slimmingMediaKind)) {
        state.slimming.mediaKind = context.slimmingMediaKind;
      }
      if (["analysis", "recycle"].includes(context.slimmingView)) {
        state.slimming.view = context.slimmingView;
      }
      if (["pending", "confirmed", "ignored"].includes(context.slimmingClusterScope)) {
        state.slimming.clusterScope = context.slimmingClusterScope;
      }
      if (Object.prototype.hasOwnProperty.call(context, "slimmingJobID")) {
        state.slimming.selectedJobID = context.slimmingJobID || null;
      }
      if (Object.prototype.hasOwnProperty.call(context, "slimmingClusterID")) {
        state.slimming.selectedClusterID = context.slimmingClusterID || null;
      }
      await openSlimmingWorkspace({
        historyMode: "none",
        awaitCatalogSources: (activeEntry?.navigationLevel || "workspace") === "slimmingSetup",
      });
      await waitForWorkspaceLayout();
      elements.slimmingNavigatorPane.scrollTop = workspaceHistoryScrollTop(
        context.slimmingNavigatorScrollTop
      );
      restoreLightboxFromHistory(context.slimmingLightbox, "slimming");
    } else if (target === "worldMap") {
      if (Object.prototype.hasOwnProperty.call(context, "worldMapClusterID")) {
        state.worldMap.selectedClusterID = context.worldMapClusterID || null;
      }
      if (Object.prototype.hasOwnProperty.call(context, "worldMapViewport")) {
        state.worldMap.viewport = normalizedWorldMapViewport(context.worldMapViewport);
        state.worldMap.viewportRestorePending = Boolean(
          worldMapViewportCamera(state.worldMap.viewport)
        );
      }
      await openWorldMapWorkspace({ historyMode: "none" });
      restorePendingWorldMapViewport();
      if (state.worldMap.selectedClusterID) {
        await loadWorldMapSelection(state.worldMap.selectedClusterID);
      }
      restoreLightboxFromHistory(context.worldMapLightbox, "worldMap");
    } else if (target === "galleryOverview") {
      await openGalleryOverviewWorkspace({ historyMode: "none" });
    }
    reconcileCompactToolbarMenuFromWorkspaceHistory(
      target,
      activeEntry?.navigationLevel || "workspace",
      context
    );
    reconcileJobsPopoverFromWorkspaceHistory(
      target,
      activeEntry?.navigationLevel || "workspace",
      context
    );
    reconcileFilterPopoverFromWorkspaceHistory(
      target,
      activeEntry?.navigationLevel || "workspace",
      context
    );
    reconcileLayoutMenuFromWorkspaceHistory(
      target,
      activeEntry?.navigationLevel || "workspace",
      context
    );
    reconcileActionMenuFromWorkspaceHistory(
      target,
      activeEntry?.navigationLevel || "workspace",
      context
    );
    reconcileContextMenuFromWorkspaceHistory(
      target,
      activeEntry?.navigationLevel || "workspace",
      context
    );
    await reconcileCommandPaletteFromWorkspaceHistory(
      target,
      activeEntry?.navigationLevel || "workspace",
      context
    );
    reconcileKeyboardShortcutsFromWorkspaceHistory(
      target,
      activeEntry?.navigationLevel || "workspace",
      context
    );
    checkpointWorkspaceHistoryAfterApply =
      await reconcileGeneralSettingsFromWorkspaceHistory(
        target,
        activeEntry?.navigationLevel || "workspace",
        context
      ) || checkpointWorkspaceHistoryAfterApply;
    checkpointWorkspaceHistoryAfterApply = await reconcileWorldMapLocationBackfillFromWorkspaceHistory(
      target,
      activeEntry?.navigationLevel || "workspace",
      context
    ) || checkpointWorkspaceHistoryAfterApply;
    checkpointWorkspaceHistoryAfterApply = await reconcileWorldMapPlaceTagsFromWorkspaceHistory(
      target,
      activeEntry?.navigationLevel || "workspace",
      context
    ) || checkpointWorkspaceHistoryAfterApply;
    reconcileSlimmingIdenticalCleanupFromWorkspaceHistory(
      target,
      activeEntry?.navigationLevel || "workspace",
      context
    );
    reconcileSlimmingVerificationFromWorkspaceHistory(
      target,
      activeEntry?.navigationLevel || "workspace",
      context
    );
    reconcileSlimmingRecycleExplanationFromWorkspaceHistory(
      target,
      activeEntry?.navigationLevel || "workspace",
      context
    );
    checkpointWorkspaceHistoryAfterApply = await reconcileSlimmingSetupFromWorkspaceHistory(
      target,
      activeEntry?.navigationLevel || "workspace",
      context
    ) || checkpointWorkspaceHistoryAfterApply;
    reconcileSlimmingThresholdFromWorkspaceHistory(
      target,
      activeEntry?.navigationLevel || "workspace",
      context
    );
    checkpointWorkspaceHistoryAfterApply = await reconcileTrainingSetupFromWorkspaceHistory(
      target,
      activeEntry?.navigationLevel || "workspace",
      context
    ) || checkpointWorkspaceHistoryAfterApply;
    checkpointWorkspaceHistoryAfterApply = await reconcileTagSuggestionFromWorkspaceHistory(
      target,
      activeEntry?.navigationLevel || "workspace",
      context
    ) || checkpointWorkspaceHistoryAfterApply;
    checkpointWorkspaceHistoryAfterApply = await reconcileNewTagFromWorkspaceHistory(
      target,
      activeEntry?.navigationLevel || "workspace",
      context
    ) || checkpointWorkspaceHistoryAfterApply;
    checkpointWorkspaceHistoryAfterApply = await reconcileTagManagerFromWorkspaceHistory(
      target,
      activeEntry?.navigationLevel || "workspace",
      context
    ) || checkpointWorkspaceHistoryAfterApply;
    checkpointWorkspaceHistoryAfterApply = await reconcileSourceManagerFromWorkspaceHistory(
      target,
      activeEntry?.navigationLevel || "workspace",
      context
    ) || checkpointWorkspaceHistoryAfterApply;
    checkpointWorkspaceHistoryAfterApply =
      await reconcileStorageMaintenanceFromWorkspaceHistory(
        target,
        activeEntry?.navigationLevel || "workspace",
        context
      ) || checkpointWorkspaceHistoryAfterApply;
    reconcileConfirmationFromWorkspaceHistory(
      target,
      activeEntry?.navigationLevel || "workspace",
      context
    );
    if ((activeEntry?.navigationLevel || "workspace") === "workspace") {
      focusWorkspacePrimaryControl(target);
    }
  } finally {
    state.workspaceNavigation.applyingHistory = false;
    if (checkpointWorkspaceHistoryAfterApply) checkpointActiveWorkspaceHistory();
    const resolve = state.workspaceNavigation.pendingReturnResolve;
    state.workspaceNavigation.pendingReturnResolve = null;
    state.workspaceNavigation.pendingReturnPromise = null;
    resolve?.();
  }
}

function scheduleWorkspaceHistoryEntry(entry) {
  const generation = state.workspaceGeneration;
  const transition = state.workspaceNavigation.transitionPromise
    .catch(() => {})
    .then(async () => {
      if (!state.workspaceNavigation.initialized
        || generation !== state.workspaceGeneration
        || elements.appView.classList.contains("hidden")) return;
      await applyWorkspaceHistoryEntry(entry);
    })
    .catch((error) => {
      if (generation === state.workspaceGeneration) {
        toast(error.message || "无法返回上一工作区");
      }
    });
  state.workspaceNavigation.transitionPromise = transition;
  return transition;
}

function handleWorkspaceHistoryPopState(event) {
  if (!state.workspaceNavigation.initialized
    || elements.appView.classList.contains("hidden")) return;
  let entry = activeWorkspaceHistoryEntry(event.state);
  if (!entry) {
    entry = workspaceHistoryEntry("gallery");
    history.replaceState({
      ...(event.state || {}),
      [WORKSPACE_HISTORY_KEY]: entry,
    }, "", location.href);
  }
  void scheduleWorkspaceHistoryEntry(entry);
}

function returnFromWorkspace(route = visibleWorkspaceRoute()) {
  if (state.workspaceNavigation.pendingReturnPromise) {
    return state.workspaceNavigation.pendingReturnPromise;
  }
  const current = activeWorkspaceHistoryEntry();
  if (state.workspaceNavigation.initialized && current?.route === route) {
    const pending = new Promise((resolve) => {
      state.workspaceNavigation.pendingReturnResolve = resolve;
    });
    state.workspaceNavigation.pendingReturnPromise = pending;
    history.back();
    return pending;
  }
  closeVisibleWorkspaceOneLevel();
  if (state.workspaceNavigation.initialized) {
    recordWorkspaceHistory(visibleWorkspaceRoute(), null, "replace");
  }
  return Promise.resolve();
}

function reviewWorkspaceIsOpen() {
  return !elements.reviewWorkspace.classList.contains("hidden");
}

function reviewWorkspaceUsesIntegratedLayout() {
  return galleryOverviewLayoutQuery.matches;
}

function clearIntegratedReviewFrame() {
  elements.reviewWorkspace.classList.remove("integrated", "inspector-hidden");
  for (const property of [
    "--review-workspace-top",
    "--review-workspace-right",
    "--review-workspace-bottom",
    "--review-workspace-left",
  ]) {
    elements.reviewWorkspace.style.removeProperty(property);
  }
}

function syncIntegratedReviewFrame() {
  if (!reviewWorkspaceIsOpen() || !reviewWorkspaceUsesIntegratedLayout()) return;
  const libraryBounds = elements.libraryPane.getBoundingClientRect();
  const workspaceBounds = elements.workspace.getBoundingClientRect();
  elements.reviewWorkspace.classList.add("integrated");
  elements.reviewWorkspace.style.setProperty(
    "--review-workspace-top",
    `${libraryBounds.top}px`
  );
  elements.reviewWorkspace.style.setProperty(
    "--review-workspace-right",
    `${Math.max(0, globalThis.innerWidth - workspaceBounds.right)}px`
  );
  elements.reviewWorkspace.style.setProperty(
    "--review-workspace-bottom",
    `${Math.max(0, globalThis.innerHeight - libraryBounds.bottom)}px`
  );
  elements.reviewWorkspace.style.setProperty(
    "--review-workspace-left",
    `${libraryBounds.left}px`
  );
  elements.reviewWorkspace.classList.toggle(
    "inspector-hidden",
    !state.layout.inspectorVisible
  );
}

function setIntegratedReviewSurfaceIsolation(isolated) {
  for (const surface of [elements.inspectorResizeHandle, elements.inspector]) {
    if (isolated) {
      surface.dataset.reviewWorkspaceIsolated = "true";
      surface.inert = true;
      surface.setAttribute("aria-hidden", "true");
    } else if (surface.dataset.reviewWorkspaceIsolated === "true") {
      surface.inert = false;
      surface.removeAttribute("aria-hidden");
      delete surface.dataset.reviewWorkspaceIsolated;
    }
  }
}

function syncReviewPresentation({ focus = false, renderSurfaces = true } = {}) {
  const open = reviewWorkspaceIsOpen();
  const integrated = open && reviewWorkspaceUsesIntegratedLayout();
  const lightboxOpen = !elements.lightbox.classList.contains("hidden")
    && state.lightboxContext === "review";
  const dockedLightbox = lightboxOpen
    && elements.lightbox.classList.contains("review-docked");
  renderReviewWorkspaceTitle();

  if (integrated) {
    elements.appView.inert = lightboxOpen && !dockedLightbox;
    elements.appView.classList.add("review-workspace-integrated");
    syncIntegratedReviewFrame();
    elements.reviewWorkspace.setAttribute("role", "region");
    elements.reviewWorkspace.removeAttribute("aria-modal");
    setIntegratedLibraryWorkspaceIsolation(elements.reviewWorkspace, true);
    setIntegratedReviewSurfaceIsolation(true);
  } else {
    setIntegratedLibraryWorkspaceIsolation(elements.reviewWorkspace, false);
    setIntegratedReviewSurfaceIsolation(false);
    clearIntegratedReviewFrame();
    elements.appView.classList.remove("review-workspace-integrated");
    elements.reviewWorkspace.setAttribute("role", "dialog");
    elements.reviewWorkspace.setAttribute("aria-modal", "true");
    elements.appView.inert = open;
  }
  elements.reviewWorkspace.inert = lightboxOpen && !dockedLightbox;

  if (renderSurfaces) {
    renderSources();
    renderInspectorSurface();
    updateLibraryTitle();
  }
  if (focus && open && !lightboxOpen) {
    requestAnimationFrame(() => elements.closeReviewButton.focus({ preventScroll: true }));
  }
}

function leaveIntegratedReviewForLibrary({ historyMode = "push" } = {}) {
  if (!reviewWorkspaceIsOpen() || !reviewWorkspaceUsesIntegratedLayout()) return false;
  closeReviewWorkspace({ restoreFocus: false });
  recordWorkspaceHistory("gallery", null, historyMode);
  return true;
}

function closeReviewWorkspace({ restoreFocus = true } = {}) {
  if (elements.tagSuggestionDialog.open) closeTagSuggestionDialog();
  closeReviewSourceFilter({ restoreFocus: false });
  finishReviewMarqueeSelection();
  resetReviewCloudPreviewRecovery();
  state.review.selectionMode = false;
  elements.reviewWorkspace.classList.remove("touch-selection-mode");
  elements.reviewWorkspace.classList.add("hidden");
  syncReviewPresentation();
  const returnFocus = state.reviewReturnFocus;
  state.reviewReturnFocus = null;
  const returnTarget = state.review.returnTarget;
  state.review.returnTarget = null;
  state.review.pendingFocusTrainingJobID = null;
  syncReviewClosePresentation();
  if (returnTarget?.workspace === "training") {
    elements.trainingWorkspace.classList.remove("hidden");
    if (state.training.runs.some((run) => run.id === returnTarget.runID)) {
      state.training.selectedRunID = returnTarget.runID;
    }
    state.training.pendingReturnFocusRunID = state.training.loading
      ? state.training.selectedRunID
      : null;
    renderTrainingWorkspace();
    syncTrainingPresentation();
    stabilizeDismissedOverlayFocus(
      () => {
        const runID = state.training.selectedRunID;
        if (!runID) return null;
        return elements.trainingRunList.querySelector(
          `[data-training-run-id="${CSS.escape(runID)}"]`
        );
      },
      elements.reviewWorkspace,
      () => !elements.trainingWorkspace.classList.contains("hidden")
    );
    return;
  }
  if (restoreFocus) restoreOverlayFocus(stableReturnFocusTarget(
    returnFocus,
    elements.reviewNavigationButton
  ));
}

function closeTrainingWorkspace({ restoreFocus = true } = {}) {
  if (elements.trainingSetupDialog.open) closeTrainingSetupDialog();
  elements.trainingWorkspace.classList.add("hidden");
  elements.trainingWorkspace.inert = false;
  syncTrainingPresentation();
  const returnFocus = state.trainingReturnFocus;
  state.trainingReturnFocus = null;
  const returnTarget = state.training.returnTarget;
  state.training.returnTarget = null;
  state.training.pendingReturnFocusRunID = null;
  syncTrainingClosePresentation();
  if (returnTarget?.workspace === "review") {
    elements.reviewWorkspace.classList.remove("hidden");
    const returnMode = returnTarget.mode || "overview";
    if (state.review.mode !== returnMode) {
      state.review.mode = returnMode;
      renderReviewMode();
    }
    syncReviewPresentation();
    stabilizeDismissedOverlayFocus(
      () => {
        if (returnTarget.jobID) state.review.pendingFocusTrainingJobID = returnTarget.jobID;
        const trainingControl = returnTarget.jobID
          ? elements.reviewOverviewGrid.querySelector(
            `[data-review-training-job-id="${CSS.escape(returnTarget.jobID)}"]`
          )
          : null;
        const card = !trainingControl && returnTarget.tagID
          ? elements.reviewOverviewGrid.querySelector(
            `[data-review-overview-tag-id="${CSS.escape(returnTarget.tagID)}"]:not(:disabled)`
          )
          : null;
        const focusFallback = returnFocus instanceof HTMLElement && document.contains(returnFocus)
          ? returnFocus
          : elements.closeReviewButton;
        const target = trainingControl || card || focusFallback;
        if (trainingControl && !state.review.overviewLoading) {
          state.review.pendingFocusTrainingJobID = null;
        }
        return target;
      },
      elements.trainingWorkspace,
      () => !elements.reviewWorkspace.classList.contains("hidden")
    );
    return;
  }
  if (restoreFocus) restoreOverlayFocus(stableReturnFocusTarget(
    returnFocus,
    elements.trainingNavigationButton
  ));
}

function syncReviewClosePresentation() {
  const returnsToTraining = state.review.returnTarget?.workspace === "training";
  setWorkspaceBackButton(
    elements.closeReviewButton,
    returnsToTraining ? "返回训练记录" : "返回图库"
  );
}

function syncTrainingClosePresentation() {
  const returnsToReview = state.training.returnTarget?.workspace === "review";
  setWorkspaceBackButton(
    elements.closeTrainingButton,
    returnsToReview ? "返回建议审核" : "返回图库"
  );
}

function trainingWorkspaceIsOpen() {
  return !elements.trainingWorkspace.classList.contains("hidden");
}

function trainingWorkspaceUsesIntegratedLayout() {
  return galleryOverviewLayoutQuery.matches;
}

function clearIntegratedTrainingFrame() {
  elements.trainingWorkspace.classList.remove("integrated");
  for (const property of [
    "--training-workspace-top",
    "--training-workspace-right",
    "--training-workspace-bottom",
    "--training-workspace-left",
  ]) {
    elements.trainingWorkspace.style.removeProperty(property);
  }
}

function syncIntegratedTrainingFrame() {
  if (!trainingWorkspaceIsOpen() || !trainingWorkspaceUsesIntegratedLayout()) return;
  const bounds = elements.libraryPane.getBoundingClientRect();
  elements.trainingWorkspace.classList.add("integrated");
  elements.trainingWorkspace.style.setProperty("--training-workspace-top", `${bounds.top}px`);
  elements.trainingWorkspace.style.setProperty(
    "--training-workspace-right",
    `${Math.max(0, globalThis.innerWidth - bounds.right)}px`
  );
  elements.trainingWorkspace.style.setProperty(
    "--training-workspace-bottom",
    `${Math.max(0, globalThis.innerHeight - bounds.bottom)}px`
  );
  elements.trainingWorkspace.style.setProperty("--training-workspace-left", `${bounds.left}px`);
}

function syncTrainingPresentation({ focus = false, renderSurfaces = true } = {}) {
  const open = trainingWorkspaceIsOpen();
  const integrated = open && trainingWorkspaceUsesIntegratedLayout();

  if (integrated) {
    elements.appView.inert = false;
    elements.appView.classList.add("training-workspace-integrated");
    syncIntegratedTrainingFrame();
    elements.trainingWorkspace.setAttribute("role", "region");
    elements.trainingWorkspace.removeAttribute("aria-modal");
    setIntegratedLibraryWorkspaceIsolation(elements.trainingWorkspace, true);
  } else {
    setIntegratedLibraryWorkspaceIsolation(elements.trainingWorkspace, false);
    clearIntegratedTrainingFrame();
    elements.appView.classList.remove("training-workspace-integrated");
    elements.trainingWorkspace.setAttribute("role", "dialog");
    elements.trainingWorkspace.setAttribute("aria-modal", "true");
    elements.appView.inert = open;
  }
  elements.trainingWorkspace.inert = false;

  if (renderSurfaces) {
    renderSources();
    renderInspectorSurface();
    updateLibraryTitle();
  }
  if (focus && open) {
    requestAnimationFrame(() => elements.closeTrainingButton.focus({ preventScroll: true }));
  }
}

function leaveIntegratedTrainingForLibrary({ historyMode = "push" } = {}) {
  if (!trainingWorkspaceIsOpen() || !trainingWorkspaceUsesIntegratedLayout()) return false;
  closeTrainingWorkspace({ restoreFocus: false });
  recordWorkspaceHistory("gallery", null, historyMode);
  return true;
}

