function leaveIntegratedSlimmingForLibrary({ historyMode = "push" } = {}) {
  if (!slimmingWorkspaceIsOpen() || !slimmingWorkspaceUsesIntegratedLayout()) return false;
  closeSlimmingWorkspace({ restoreFocus: false });
  recordWorkspaceHistory("gallery", null, historyMode);
  return true;
}

function slimmingSemanticReturnFocusTarget(target) {
  if (!target || target.kind !== "workspaceNoticeAction") return null;
  const noticeAction = elements.workspaceNoticeActions.querySelector(
    `[data-workspace-notice-action-id="${CSS.escape(target.actionID || "")}"]`
  );
  if (noticeAction instanceof HTMLElement && noticeAction.getClientRects().length > 0) {
    return noticeAction;
  }
  if (!target.sourceID) return null;
  const source = elements.sourceList.querySelector(
    `[data-source-id="${CSS.escape(target.sourceID)}"]`
  );
  return source instanceof HTMLElement && source.getClientRects().length > 0
    ? source
    : null;
}

function closeSlimmingWorkspace({ restoreFocus = true } = {}) {
  finishSlimmingMarqueeSelection();
  state.slimming.selectionMode = false;
  elements.slimmingWorkspace.classList.remove("touch-selection-mode");
  hideContextMenus();
  closeSlimmingCatalogSourcePicker({ restoreFocus: false });
  closeSlimmingAnalysisOptions({ restoreFocus: false });
  if (elements.slimmingIdenticalCleanupDialog.open) {
    closeSlimmingIdenticalCleanupDialog({
      restoreFocus: false,
      checkpoint: false,
      preserveState: false,
    });
  }
  closeSlimmingVerificationReport({
    restoreFocus: false,
    checkpoint: false,
    preserveState: false,
  });
  closeSlimmingRecycleExplanation({
    restoreFocus: false,
    checkpoint: false,
    preserveState: false,
  });
  clearTimeout(state.slimming.recycle.pollTimer);
  clearTimeout(state.slimming.recycle.searchTimer);
  clearTimeout(state.slimming.removal.pollTimer);
  state.slimming.recycle.pollTimer = null;
  state.slimming.recycle.searchTimer = null;
  state.slimming.removal.pollTimer = null;
  elements.slimmingWorkspace.classList.add("hidden");
  syncSlimmingPresentation();
  const returnFocus = state.slimmingReturnFocus;
  const semanticReturnFocus = slimmingSemanticReturnFocusTarget(
    state.slimmingReturnTarget
  );
  state.slimmingReturnFocus = null;
  state.slimmingReturnTarget = null;
  if (restoreFocus) restoreOverlayFocus(stableReturnFocusTarget(
    semanticReturnFocus || returnFocus,
    elements.slimmingNavigationButton
  ));
}

function galleryOverviewCount(value) {
  return Number(value || 0).toLocaleString("zh-CN");
}

function syncGalleryOverviewText(element, text) {
  if (element.textContent !== text) element.textContent = text;
}

function galleryOverviewTotal(item) {
  return Number(item?.imageCount || 0) + Number(item?.videoCount || 0);
}

function syncGalleryOverviewRovingItems(container, selector, preferred = null) {
  const items = [...container.querySelectorAll(selector)];
  if (!items.length) return [];
  const active = items.includes(document.activeElement) ? document.activeElement : null;
  const current = items.find((item) => item.tabIndex === 0);
  const target = active || (items.includes(preferred) ? preferred : null) || current || items[0];
  for (const item of items) item.tabIndex = item === target ? 0 : -1;
  return items;
}

function galleryOverviewVisiblePageStep(items, viewport, orientation) {
  const viewportRect = viewport.getBoundingClientRect();
  const visibleCount = items.filter((item) => {
    const rect = item.getBoundingClientRect();
    return orientation === "horizontal"
      ? rect.right > viewportRect.left && rect.left < viewportRect.right
      : rect.bottom > viewportRect.top && rect.top < viewportRect.bottom;
  }).length;
  return Math.max(1, visibleCount - 1);
}

function moveGalleryOverviewChartFocus(event, {
  container,
  selector,
  orientation,
  pageNavigation = true,
}) {
  if (event.altKey || event.ctrlKey || event.metaKey || event.shiftKey) return;
  const directionKeys = orientation === "horizontal"
    ? new Map([["ArrowLeft", -1], ["ArrowRight", 1]])
    : new Map([["ArrowUp", -1], ["ArrowDown", 1]]);
  const isPageKey = pageNavigation
    && (event.key === "PageUp" || event.key === "PageDown");
  if (!(directionKeys.has(event.key) || isPageKey || event.key === "Home" || event.key === "End")) {
    return;
  }
  const items = syncGalleryOverviewRovingItems(container, selector, event.target.closest(selector));
  const currentIndex = items.indexOf(document.activeElement);
  if (currentIndex < 0) return;
  let nextIndex = currentIndex;
  if (event.key === "Home") nextIndex = 0;
  else if (event.key === "End") nextIndex = items.length - 1;
  else if (isPageKey) {
    const pageStep = galleryOverviewVisiblePageStep(items, container, orientation);
    nextIndex += event.key === "PageUp" ? -pageStep : pageStep;
  } else {
    nextIndex += directionKeys.get(event.key);
  }
  nextIndex = Math.max(0, Math.min(items.length - 1, nextIndex));
  event.preventDefault();
  const next = items[nextIndex];
  syncGalleryOverviewRovingItems(container, selector, next);
  next.focus({ preventScroll: true });
  next.scrollIntoView({ block: "nearest", inline: "nearest" });
}

function updateGalleryOverviewTimelineStatus(year) {
  if (!year || !elements.galleryOverviewTimelineStatus) return;
  syncGalleryOverviewText(
    elements.galleryOverviewTimelineStatus,
    year.getAttribute("aria-label") || "聚焦年份后可查看精确照片与视频数量"
  );
}

function updateGalleryOverviewAvailabilityStatus(row) {
  if (!row || !elements.galleryOverviewAvailabilityStatus) return;
  syncGalleryOverviewText(
    elements.galleryOverviewAvailabilityStatus,
    row.getAttribute("aria-label") || "聚焦状态后可查看精确照片与视频数量"
  );
}

function galleryOverviewEmpty(message) {
  const empty = document.createElement("p");
  empty.className = "gallery-overview-empty";
  empty.textContent = message;
  return empty;
}

function galleryOverviewMediaSummary(kind) {
  return state.galleryOverview.snapshot?.media?.find((item) => item.mediaKind === kind) || {
    mediaKind: kind,
    totalCount: 0,
    exactUniqueCount: 0,
    exactRedundantCount: 0,
    exactFingerprintCount: 0,
  };
}

function renderGalleryOverviewMediaCard(summary) {
  const card = document.createElement("button");
  card.type = "button";
  card.className = "gallery-overview-media-card";

  const heading = document.createElement("div");
  heading.className = "gallery-overview-media-heading";
  const title = document.createElement("span");
  const total = document.createElement("strong");
  heading.append(title, total);

  const facts = document.createElement("div");
  facts.className = "gallery-overview-media-facts";
  for (const label of ["保守去重后", "确认冗余"]) {
    const fact = document.createElement("div");
    const factValue = document.createElement("strong");
    const factLabel = document.createElement("small");
    factLabel.textContent = label;
    fact.append(factValue, factLabel);
    facts.append(fact);
  }

  const coverageLabel = document.createElement("div");
  coverageLabel.className = "gallery-overview-coverage-label";
  const coverageTitle = document.createElement("span");
  coverageTitle.textContent = "精确摘要覆盖";
  const coverageValue = document.createElement("span");
  coverageLabel.append(coverageTitle, coverageValue);
  const progress = document.createElement("div");
  progress.className = "gallery-overview-progress";
  const fill = document.createElement("i");
  progress.append(fill);
  card.append(heading, facts, coverageLabel, progress);
  return card;
}

function syncGalleryOverviewMediaCard(card, summary, index, count) {
  const kind = summary.mediaKind === "video" ? "video" : "image";
  const title = kind === "video" ? "视频" : "照片";
  card.dataset.galleryOverviewMediaKind = kind;
  card.style.setProperty("--media-tint", kind === "video" ? "#f07d30" : "#2e8cd1");
  syncGalleryOverviewText(
    card.querySelector(".gallery-overview-media-heading span"),
    kind === "video" ? "▶ 视频" : "▧ 照片"
  );
  syncGalleryOverviewText(
    card.querySelector(".gallery-overview-media-heading strong"),
    galleryOverviewCount(summary.totalCount)
  );
  const factValues = card.querySelectorAll(".gallery-overview-media-facts strong");
  syncGalleryOverviewText(factValues[0], galleryOverviewCount(summary.exactUniqueCount));
  syncGalleryOverviewText(factValues[1], galleryOverviewCount(summary.exactRedundantCount));
  syncGalleryOverviewText(
    card.querySelector(".gallery-overview-coverage-label span:last-child"),
    `${galleryOverviewCount(summary.exactFingerprintCount)} / ${galleryOverviewCount(summary.totalCount)}`
  );
  const coverage = summary.totalCount > 0
    ? Math.min(100, Math.max(0, summary.exactFingerprintCount / summary.totalCount * 100))
    : 0;
  card.querySelector(".gallery-overview-progress i")
    .style.setProperty("--coverage", `${coverage}%`);
  card.setAttribute(
    "aria-label",
    `${title}：共 ${galleryOverviewCount(summary.totalCount)} 个，保守去重后 ${galleryOverviewCount(summary.exactUniqueCount)} 个，确认冗余 ${galleryOverviewCount(summary.exactRedundantCount)} 个，精确摘要覆盖 ${galleryOverviewCount(summary.exactFingerprintCount)} 个；第 ${index + 1} 项，共 ${count} 项；按 Enter 打开`
  );
  card.setAttribute("aria-posinset", String(index + 1));
  card.setAttribute("aria-setsize", String(count));
  card.setAttribute("aria-keyshortcuts", "ArrowLeft ArrowRight Home End");
}

function reconcileGalleryOverviewMediaCards(summaries) {
  const existingCards = new Map(
    [...elements.galleryOverviewMediaLedger.querySelectorAll("[data-gallery-overview-media-kind]")]
      .map((card) => [card.dataset.galleryOverviewMediaKind, card])
  );
  for (const [index, summary] of summaries.entries()) {
    const kind = summary.mediaKind === "video" ? "video" : "image";
    const card = existingCards.get(kind) || renderGalleryOverviewMediaCard(summary);
    existingCards.delete(kind);
    syncGalleryOverviewMediaCard(card, summary, index, summaries.length);
    const currentCard = elements.galleryOverviewMediaLedger.children[index] || null;
    if (currentCard !== card) elements.galleryOverviewMediaLedger.insertBefore(card, currentCard);
  }
  for (const card of existingCards.values()) card.remove();
  syncGalleryOverviewRovingItems(
    elements.galleryOverviewMediaLedger,
    "[data-gallery-overview-media-kind]"
  );
}

function createGalleryOverviewBarRow() {
  const button = document.createElement("button");
  button.type = "button";
  button.className = "gallery-overview-bar-row";
  const label = document.createElement("span");
  label.className = "gallery-overview-bar-label";
  const track = document.createElement("span");
  track.className = "gallery-overview-bar-track";
  const photo = document.createElement("i");
  photo.className = "photo";
  const video = document.createElement("i");
  video.className = "video";
  track.append(photo, video);
  const count = document.createElement("span");
  count.className = "gallery-overview-bar-count";
  button.append(label, track, count);
  return button;
}

function syncGalleryOverviewBarRow(button, item, kind, maximum, index, count) {
  if (kind === "source") {
    button.dataset.galleryOverviewSourceId = item.id;
    delete button.dataset.galleryOverviewTagId;
  } else {
    button.dataset.galleryOverviewTagId = item.id;
    delete button.dataset.galleryOverviewSourceId;
  }
  button.title = kind === "source" ? `打开来源：${item.displayName}` : `筛选标签：${item.displayName}`;
  syncGalleryOverviewText(
    button.querySelector(".gallery-overview-bar-label"),
    item.displayName
  );
  button.querySelector(".photo").style.setProperty(
    "--photo-width",
    `${Math.max(0, Number(item.imageCount || 0)) / maximum * 100}%`
  );
  button.querySelector(".video").style.setProperty(
    "--video-width",
    `${Math.max(0, Number(item.videoCount || 0)) / maximum * 100}%`
  );
  syncGalleryOverviewText(
    button.querySelector(".gallery-overview-bar-count"),
    galleryOverviewCount(galleryOverviewTotal(item))
  );
  const action = kind === "source" ? "打开来源" : "筛选标签";
  button.setAttribute(
    "aria-label",
    `${kind === "source" ? "来源" : "标签"} ${item.displayName}：${galleryOverviewCount(item.imageCount)} 张照片，${galleryOverviewCount(item.videoCount)} 个视频，共 ${galleryOverviewCount(galleryOverviewTotal(item))} 个；第 ${index + 1} 项，共 ${count} 项；按 Enter ${action}`
  );
  button.setAttribute("aria-posinset", String(index + 1));
  button.setAttribute("aria-setsize", String(count));
  button.setAttribute("aria-keyshortcuts", "ArrowUp ArrowDown PageUp PageDown Home End");
}

function renderGalleryOverviewBars(container, items, kind) {
  if (!items.length) {
    clearElement(container);
    container.append(galleryOverviewEmpty(
      kind === "source" ? "暂无来源数据" : "还没有人工接受的标签"
    ));
    return;
  }
  container.querySelector(":scope > .gallery-overview-empty")?.remove();
  const maximum = Math.max(1, ...items.map(galleryOverviewTotal));
  const datasetKey = kind === "source" ? "galleryOverviewSourceId" : "galleryOverviewTagId";
  const existingRows = new Map(
    [...container.querySelectorAll(`[data-${kind === "source" ? "gallery-overview-source-id" : "gallery-overview-tag-id"}]`)]
      .map((row) => [row.dataset[datasetKey], row])
  );
  for (const [index, item] of items.entries()) {
    const button = existingRows.get(item.id) || createGalleryOverviewBarRow();
    existingRows.delete(item.id);
    syncGalleryOverviewBarRow(button, item, kind, maximum, index, items.length);
    const currentRow = container.children[index] || null;
    if (currentRow !== button) container.insertBefore(button, currentRow);
  }
  for (const row of existingRows.values()) row.remove();
  syncGalleryOverviewRovingItems(
    container,
    kind === "source"
      ? "[data-gallery-overview-source-id]"
      : "[data-gallery-overview-tag-id]"
  );
}

function galleryOverviewAvailabilityPresentation(availability) {
  return {
    available: ["可用", "#34a853"],
    missing: ["缺失", "#d94747"],
    unreadable: ["不可读", "#f07d30"],
    unsupported: ["不支持", "#8e8e93"],
  }[availability] || [availability || "未知", "#8e8e93"];
}

function renderGalleryOverviewAvailability(items, totalCount) {
  if (!items.length) {
    clearElement(elements.galleryOverviewAvailability);
    elements.galleryOverviewAvailability.append(galleryOverviewEmpty("暂无状态数据"));
    syncGalleryOverviewText(
      elements.galleryOverviewAvailabilityStatus,
      "暂无状态数据"
    );
    return;
  }
  elements.galleryOverviewAvailability.querySelector(":scope > .gallery-overview-empty")?.remove();
  let angle = 0;
  const stops = [];
  for (const item of items) {
    const share = totalCount > 0 ? galleryOverviewTotal(item) / totalCount * 100 : 0;
    const color = galleryOverviewAvailabilityPresentation(item.availability)[1];
    stops.push(`${color} ${angle}% ${Math.min(100, angle + share)}%`);
    angle += share;
  }
  if (angle < 100) stops.push(`var(--separator) ${angle}% 100%`);

  let donut = elements.galleryOverviewAvailability.querySelector(":scope > .gallery-overview-donut");
  if (!donut) {
    donut = document.createElement("div");
    donut.className = "gallery-overview-donut";
    const donutLabel = document.createElement("span");
    donutLabel.className = "gallery-overview-donut-label";
    const total = document.createElement("strong");
    const caption = document.createElement("span");
    caption.textContent = "当前媒体";
    donutLabel.append(total, caption);
    donut.append(donutLabel);
    elements.galleryOverviewAvailability.prepend(donut);
  }
  donut.style.setProperty("--donut", `conic-gradient(${stops.join(", ")})`);
  donut.setAttribute("role", "img");
  donut.setAttribute(
    "aria-label",
    `当前媒体 ${galleryOverviewCount(totalCount)} 个；${items.map((item) => {
      const title = galleryOverviewAvailabilityPresentation(item.availability)[0];
      return `${title} ${galleryOverviewCount(galleryOverviewTotal(item))} 个`;
    }).join("，")}`
  );
  syncGalleryOverviewText(donut.querySelector("strong"), galleryOverviewCount(totalCount));

  let list = elements.galleryOverviewAvailability.querySelector(
    ":scope > .gallery-overview-availability-list"
  );
  if (!list) {
    list = document.createElement("div");
    list.className = "gallery-overview-availability-list";
    elements.galleryOverviewAvailability.append(list);
  }
  const existingRows = new Map(
    [...list.querySelectorAll("[data-gallery-overview-availability]")]
      .map((row) => [row.dataset.galleryOverviewAvailability, row])
  );
  for (const [index, item] of items.entries()) {
    const [title, color] = galleryOverviewAvailabilityPresentation(item.availability);
    const row = existingRows.get(item.availability) || document.createElement("button");
    existingRows.delete(item.availability);
    if (!row.classList.contains("gallery-overview-availability-row")) {
      row.className = "gallery-overview-availability-row";
      row.append(document.createElement("i"), document.createElement("span"), document.createElement("strong"));
    }
    row.type = "button";
    row.dataset.galleryOverviewAvailability = item.availability;
    row.style.setProperty("--status-color", color);
    syncGalleryOverviewText(row.querySelector("span"), title);
    syncGalleryOverviewText(
      row.querySelector("strong"),
      galleryOverviewCount(galleryOverviewTotal(item))
    );
    row.setAttribute(
      "aria-label",
      `${title}：${galleryOverviewCount(item.imageCount)} 张照片，${galleryOverviewCount(item.videoCount)} 个视频，共 ${galleryOverviewCount(galleryOverviewTotal(item))} 个；第 ${index + 1} 项，共 ${items.length} 项；按 Enter 筛选图库`
    );
    row.setAttribute("aria-posinset", String(index + 1));
    row.setAttribute("aria-setsize", String(items.length));
    row.setAttribute("aria-keyshortcuts", "ArrowUp ArrowDown Home End");
    const currentRow = list.children[index] || null;
    if (currentRow !== row) list.insertBefore(row, currentRow);
  }
  for (const row of existingRows.values()) row.remove();
  const rows = syncGalleryOverviewRovingItems(
    list,
    "[data-gallery-overview-availability]"
  );
  updateGalleryOverviewAvailabilityStatus(
    rows.includes(document.activeElement)
      ? document.activeElement
      : rows.find((row) => row.tabIndex === 0)
  );
}

function renderGalleryOverviewTimeline(years) {
  if (!years.length) {
    clearElement(elements.galleryOverviewTimeline);
    elements.galleryOverviewTimeline.append(galleryOverviewEmpty("没有可用的媒体时间"));
    syncGalleryOverviewText(
      elements.galleryOverviewTimelineStatus,
      "没有可用的媒体时间"
    );
    return;
  }
  elements.galleryOverviewTimeline.querySelector(":scope > .gallery-overview-empty")?.remove();
  const maximum = Math.max(1, ...years.map(galleryOverviewTotal));
  const existingYears = new Map(
    [...elements.galleryOverviewTimeline.querySelectorAll("[data-gallery-overview-year]")]
      .map((year) => [year.dataset.galleryOverviewYear, year])
  );
  for (const [index, item] of years.entries()) {
    const key = String(item.year);
    const year = existingYears.get(key) || document.createElement("div");
    existingYears.delete(key);
    if (!year.classList.contains("gallery-overview-year")) {
      year.className = "gallery-overview-year";
      const bars = document.createElement("div");
      bars.className = "gallery-overview-year-bars";
      const photo = document.createElement("i");
      photo.className = "photo";
      const video = document.createElement("i");
      video.className = "video";
      bars.append(photo, video);
      year.append(bars, document.createElement("span"));
    }
    year.dataset.galleryOverviewYear = key;
    year.setAttribute("role", "img");
    year.title = `${item.year}：${galleryOverviewCount(item.imageCount)} 张照片，${galleryOverviewCount(item.videoCount)} 个视频`;
    year.setAttribute(
      "aria-label",
      `${item.year} 年：${galleryOverviewCount(item.imageCount)} 张照片，${galleryOverviewCount(item.videoCount)} 个视频，共 ${galleryOverviewCount(galleryOverviewTotal(item))} 个；第 ${index + 1} 项，共 ${years.length} 项`
    );
    year.setAttribute("aria-posinset", String(index + 1));
    year.setAttribute("aria-setsize", String(years.length));
    year.setAttribute(
      "aria-keyshortcuts",
      "ArrowLeft ArrowRight PageUp PageDown Home End"
    );
    year.querySelector(".photo").style.setProperty(
      "--photo-height",
      `${Math.max(2, Number(item.imageCount || 0) / maximum * 100)}%`
    );
    year.querySelector(".video").style.setProperty(
      "--video-height",
      `${Math.max(2, Number(item.videoCount || 0) / maximum * 100)}%`
    );
    syncGalleryOverviewText(year.querySelector(":scope > span"), key);
    const currentYear = elements.galleryOverviewTimeline.children[index] || null;
    if (currentYear !== year) elements.galleryOverviewTimeline.insertBefore(year, currentYear);
  }
  for (const year of existingYears.values()) year.remove();
  const items = syncGalleryOverviewRovingItems(
    elements.galleryOverviewTimeline,
    "[data-gallery-overview-year]"
  );
  updateGalleryOverviewTimelineStatus(
    items.includes(document.activeElement)
      ? document.activeElement
      : items.find((item) => item.tabIndex === 0)
  );
}

function galleryOverviewContentFingerprint() {
  return state.galleryOverview.snapshot === null
    ? null
    : JSON.stringify(state.galleryOverview.snapshot);
}

function galleryOverviewCanPreserveContent() {
  return state.galleryOverview.renderedContentFingerprint !== null
    && state.galleryOverview.renderedContentFingerprint === galleryOverviewContentFingerprint();
}

function renderGalleryOverview({ preserveContent = false } = {}) {
  const overview = state.galleryOverview;
  const snapshot = overview.snapshot;
  elements.galleryOverviewWorkspace.setAttribute("aria-busy", String(overview.loading));
  elements.refreshGalleryOverviewButton.disabled = overview.loading;
  elements.galleryOverviewNavigationButton.classList.toggle(
    "selected",
    !elements.galleryOverviewWorkspace.classList.contains("hidden")
  );
  const totalCount = snapshot
    ? (snapshot.media || []).reduce((sum, item) => sum + Number(item.totalCount || 0), 0)
    : 0;
  const isEmpty = Boolean(snapshot) && totalCount === 0;
  elements.galleryOverviewStatus.classList.toggle("hidden", Boolean(snapshot));
  elements.galleryOverviewEmpty.classList.toggle("hidden", !isEmpty);
  elements.galleryOverviewBody.classList.toggle("hidden", !snapshot || isEmpty);
  elements.retryGalleryOverviewButton.classList.toggle("hidden", !overview.error);
  elements.galleryOverviewStatus.dataset.state = overview.error ? "error" : "loading";
  syncGalleryOverviewText(
    elements.galleryOverviewStatus.querySelector("strong"),
    overview.error ? "无法读取图库统计" : "正在汇总图库…"
  );
  syncGalleryOverviewText(
    elements.galleryOverviewStatus.querySelector("span"),
    overview.error
      ? "目录库没有被修改。请稍后重试。"
      : "只读取 ImageAll 目录库，不访问原照片。"
  );
  if (!snapshot) {
    state.galleryOverview.renderedContentFingerprint = null;
    return;
  }

  const exactUniqueCount = (snapshot.media || []).reduce((sum, item) => sum + Number(item.exactUniqueCount || 0), 0);
  const exactRedundantCount = (snapshot.media || []).reduce((sum, item) => sum + Number(item.exactRedundantCount || 0), 0);
  const exactFingerprintCount = (snapshot.media || []).reduce((sum, item) => sum + Number(item.exactFingerprintCount || 0), 0);
  syncGalleryOverviewText(elements.galleryOverviewNavigationCount, galleryOverviewCount(totalCount));
  syncGalleryOverviewText(
    elements.galleryOverviewSummary,
    `${galleryOverviewCount(totalCount)} 个媒体 · 保守去重后 ${galleryOverviewCount(exactUniqueCount)}`
  );
  syncGalleryOverviewText(
    elements.galleryOverviewRefreshedAt,
    overview.refreshedAt
      ? `更新于 ${overview.refreshedAt.toLocaleTimeString("zh-CN", { hour: "2-digit", minute: "2-digit" })}`
      : ""
  );
  syncGalleryOverviewText(elements.galleryOverviewTotalMetric, galleryOverviewCount(totalCount));
  syncGalleryOverviewText(elements.galleryOverviewUniqueMetric, galleryOverviewCount(exactUniqueCount));
  syncGalleryOverviewText(elements.galleryOverviewRedundantMetric, galleryOverviewCount(exactRedundantCount));
  syncGalleryOverviewText(
    elements.galleryOverviewPositiveMetric,
    galleryOverviewCount(snapshot.positiveLabeledAssetCount)
  );
  syncGalleryOverviewText(
    elements.galleryOverviewAcceptedMetric,
    `${galleryOverviewCount(snapshot.acceptedDecisionCount)} 条人工接受标签`
  );
  const favoriteSummaries = snapshot.favorites || [];
  const favoriteImageCount = Number(
    favoriteSummaries.find((item) => item.mediaKind === "image")?.count || 0
  );
  const favoriteVideoCount = Number(
    favoriteSummaries.find((item) => item.mediaKind === "video")?.count || 0
  );
  elements.galleryOverviewFavoritesMetric.classList.toggle("hidden", !supportsFavorites());
  syncGalleryOverviewText(
    elements.galleryOverviewFavoriteMetric,
    galleryOverviewCount(favoriteImageCount + favoriteVideoCount)
  );
  syncGalleryOverviewText(
    elements.galleryOverviewFavoriteImageMetric,
    galleryOverviewCount(favoriteImageCount)
  );
  syncGalleryOverviewText(
    elements.galleryOverviewFavoriteVideoMetric,
    galleryOverviewCount(favoriteVideoCount)
  );

  if (preserveContent && galleryOverviewCanPreserveContent()) return;

  reconcileGalleryOverviewMediaCards([
    galleryOverviewMediaSummary("image"),
    galleryOverviewMediaSummary("video"),
  ]);
  const displayedSources = (snapshot.sources || []).slice(0, 8);
  syncGalleryOverviewText(
    elements.galleryOverviewSourceSubtitle,
    (snapshot.sources || []).length > displayedSources.length
      ? `按媒体数最多的前 ${displayedSources.length} 个来源`
      : "每个来源中的照片与视频"
  );
  renderGalleryOverviewBars(elements.galleryOverviewSources, displayedSources, "source");
  renderGalleryOverviewAvailability(snapshot.availability || [], totalCount);
  renderGalleryOverviewBars(elements.galleryOverviewTags, snapshot.positiveTags || [], "tag");
  const years = (snapshot.years || []).slice(-16);
  syncGalleryOverviewText(
    elements.galleryOverviewTimelineSubtitle,
    (snapshot.years || []).length > years.length
      ? `最近 ${years.length} 个有媒体记录的年份`
      : "按拍摄时间优先、修改时间补充"
  );
  renderGalleryOverviewTimeline(years);
  syncGalleryOverviewText(
    elements.galleryOverviewUndated,
    snapshot.undatedCount > 0
      ? `另有 ${galleryOverviewCount(snapshot.undatedCount)} 个无日期媒体`
      : ""
  );
  syncGalleryOverviewText(
    elements.galleryOverviewCoverage,
    `当前精确摘要覆盖 ${galleryOverviewCount(exactFingerprintCount)} / ${galleryOverviewCount(totalCount)}。刷新只读取 ImageAll 目录库，不访问原照片。`
  );
  state.galleryOverview.renderedContentFingerprint = galleryOverviewContentFingerprint();
}

async function loadGalleryOverview({ quiet = false, throwOnError = false } = {}) {
  if (state.galleryOverview.loading) return;
  const generation = ++state.galleryOverview.requestGeneration;
  state.galleryOverview.loading = true;
  state.galleryOverview.error = "";
  renderGalleryOverview({ preserveContent: galleryOverviewCanPreserveContent() });
  try {
    const snapshot = await api("/v1/gallery-overview");
    if (generation !== state.galleryOverview.requestGeneration) return;
    state.galleryOverview.snapshot = snapshot;
    state.galleryOverview.refreshedAt = new Date();
  } catch (error) {
    if (generation !== state.galleryOverview.requestGeneration) return;
    state.galleryOverview.error = error.message || "图库统计读取失败";
    if (!quiet && state.galleryOverview.snapshot) toast(state.galleryOverview.error);
    if (throwOnError) throw error;
  } finally {
    if (generation === state.galleryOverview.requestGeneration) {
      state.galleryOverview.loading = false;
      renderGalleryOverview({ preserveContent: galleryOverviewCanPreserveContent() });
    }
  }
}

function galleryOverviewIsOpen() {
  return !elements.galleryOverviewWorkspace.classList.contains("hidden");
}

function galleryOverviewUsesIntegratedLayout() {
  return galleryOverviewLayoutQuery.matches;
}

function setIntegratedLibraryWorkspaceIsolation(activeWorkspace, isolated) {
  for (const child of elements.libraryPane.children) {
    if (child === activeWorkspace) continue;
    if (isolated) {
      child.dataset.integratedWorkspaceIsolated = "true";
      child.inert = true;
      child.setAttribute("aria-hidden", "true");
    } else if (child.dataset.integratedWorkspaceIsolated === "true") {
      child.inert = false;
      child.removeAttribute("aria-hidden");
      delete child.dataset.integratedWorkspaceIsolated;
    }
  }
}

function restoreWorkspacePortal(workspace, portal) {
  if (workspace.parentElement === portal.parent) return;
  const anchor = portal.nextSibling?.parentElement === portal.parent
    ? portal.nextSibling
    : null;
  portal.parent.insertBefore(workspace, anchor);
}

function syncGalleryOverviewPresentation({ focus = false, renderSurfaces = true } = {}) {
  const open = galleryOverviewIsOpen();
  const integrated = open && galleryOverviewUsesIntegratedLayout();

  if (integrated) {
    elements.appView.inert = false;
    elements.libraryPane.append(elements.galleryOverviewWorkspace);
    elements.appView.classList.add("gallery-overview-integrated");
    elements.galleryOverviewWorkspace.setAttribute("role", "region");
    elements.galleryOverviewWorkspace.removeAttribute("aria-modal");
    elements.closeGalleryOverviewButton.classList.add("hidden");
    setIntegratedLibraryWorkspaceIsolation(elements.galleryOverviewWorkspace, true);
  } else {
    setIntegratedLibraryWorkspaceIsolation(elements.galleryOverviewWorkspace, false);
    restoreWorkspacePortal(elements.galleryOverviewWorkspace, galleryOverviewPortal);
    elements.appView.classList.remove("gallery-overview-integrated");
    elements.galleryOverviewWorkspace.setAttribute("role", "dialog");
    elements.galleryOverviewWorkspace.setAttribute("aria-modal", "true");
    elements.closeGalleryOverviewButton.classList.remove("hidden");
    elements.appView.inert = open;
  }
  elements.galleryOverviewWorkspace.inert = false;

  if (renderSurfaces) {
    renderSources();
    renderInspectorSurface();
    updateLibraryTitle();
  }
  if (focus && open) {
    requestAnimationFrame(() => {
      const target = integrated
        ? elements.refreshGalleryOverviewButton
        : elements.closeGalleryOverviewButton;
      target.focus({ preventScroll: true });
    });
  }
}

function leaveIntegratedGalleryOverviewForLibrary({ historyMode = "push" } = {}) {
  if (!galleryOverviewIsOpen() || !galleryOverviewUsesIntegratedLayout()) return false;
  closeGalleryOverviewWorkspace({ restoreFocus: false });
  recordWorkspaceHistory("gallery", null, historyMode);
  return true;
}

async function openGalleryOverviewWorkspace({ historyMode = "push" } = {}) {
  leaveIntegratedWorldMapForLibrary({ historyMode: "none" });
  if (elements.trainingSetupDialog.open) closeTrainingSetupDialog();
  elements.reviewWorkspace.classList.add("hidden");
  syncReviewPresentation({ renderSurfaces: false });
  state.reviewReturnFocus = null;
  elements.trainingWorkspace.classList.add("hidden");
  syncTrainingPresentation({ renderSurfaces: false });
  state.trainingReturnFocus = null;
  elements.slimmingWorkspace.classList.add("hidden");
  syncSlimmingPresentation({ renderSurfaces: false });
  state.slimmingReturnFocus = null;
  state.slimmingReturnTarget = null;
  elements.worldMapWorkspace.classList.add("hidden");
  state.worldMapReturnFocus = null;
  closeJobsPopover({ restoreFocus: false });
  closeFilterPopover({ restoreFocus: false });
  if (elements.galleryOverviewWorkspace.classList.contains("hidden")) {
    state.galleryOverviewReturnFocus = document.activeElement;
  }
  elements.galleryOverviewWorkspace.classList.remove("hidden");
  syncGalleryOverviewPresentation({ focus: true });
  recordWorkspaceHistory("galleryOverview", null, historyMode);
  renderGalleryOverview();
  if (!state.galleryOverview.snapshot) await loadGalleryOverview();
}

function closeGalleryOverviewWorkspace({ restoreFocus = true } = {}) {
  elements.galleryOverviewWorkspace.classList.add("hidden");
  syncGalleryOverviewPresentation();
  renderGalleryOverview();
  const returnFocus = state.galleryOverviewReturnFocus;
  state.galleryOverviewReturnFocus = null;
  if (restoreFocus) restoreOverlayFocus(stableReturnFocusTarget(
    returnFocus,
    elements.galleryOverviewNavigationButton
  ));
}

async function drillDownFromGalleryOverview({
  mediaKind = null,
  sourceID = null,
  tagID = null,
  availability = null,
}) {
  await returnFromWorkspace("galleryOverview");
  if (mediaKind && mediaKind !== state.mediaKind) await switchMediaKind(mediaKind);
  state.filters = emptyFilters();
  state.filters.mediaKind = state.mediaKind;
  if (["available", "missing", "unreadable", "unsupported"].includes(availability)) {
    state.filters.availabilities = [availability];
  }
  state.filterDraft = null;
  syncFilterControlsFromState();
  renderTagNavigation();
  if (sourceID) {
    await selectSource(sourceID);
  } else {
    await selectSource("");
    if (tagID) await applyQuickTagFilter(tagID);
  }
}

function worldMapRenderer() {
  return elements.worldMapFrame.contentWindow?.ImageAllWorldMap || null;
}

function pushWorldMapClusters() {
  if (!state.worldMap.rendererReady || !state.worldMap.snapshot) return;
  worldMapRenderer()?.updateClusters({
    clusters: state.worldMap.snapshot.clusters || [],
  });
  worldMapRenderer()?.restoreSelection(state.worldMap.selectedClusterID);
}

function selectedWorldMapCluster() {
  return state.worldMap.snapshot?.clusters?.find(
    (cluster) => cluster.id === state.worldMap.selectedClusterID
  ) || null;
}

function worldMapCount(value) {
  return Number(value || 0).toLocaleString("zh-CN");
}

function syncWorldMapPhotoFavoriteButton(card, asset) {
  let button = card.querySelector(":scope > .world-map-photo-favorite");
  if (!supportsFavorites() || !asset.favorite) {
    button?.remove();
    return;
  }
  if (!button) {
    button = document.createElement("button");
    button.type = "button";
    button.className = "world-map-photo-favorite write-action";
    button.dataset.worldMapPhotoFavorite = "true";
    const icon = document.createElement("span");
    icon.className = "world-map-photo-favorite-icon media-favorite-icon";
    icon.setAttribute("aria-hidden", "true");
    const badge = document.createElement("span");
    badge.className = "world-map-photo-favorite-sync media-favorite-sync hidden";
    badge.setAttribute("aria-hidden", "true");
    button.append(icon, badge);
    card.append(button);
  }
  syncMediaFavoriteButton(button, {
    assetID: asset.id,
    fileName: asset.fileName,
    favorite: asset.favorite,
  });
}

function createWorldMapPhotoCard() {
  const card = document.createElement("div");
  card.className = "world-map-photo-card";
  const button = document.createElement("button");
  button.type = "button";
  button.className = "world-map-photo-button";
  const image = document.createElement("img");
  image.alt = "";
  const label = document.createElement("span");
  button.append(image, label);
  card.append(button);
  return card;
}

function syncWorldMapPhotoCard(card, asset) {
  const fileName = asset.fileName || "未命名照片";
  card.dataset.worldMapCardAssetId = asset.id;
  const button = card.querySelector(":scope > .world-map-photo-button");
  button.dataset.worldMapAssetId = asset.id;
  button.title = asset.fileName || "查看照片";
  button.dataset.worldMapPhotoLabel = `查看 ${asset.fileName || "地点照片"}`;
  button.setAttribute("aria-label", button.dataset.worldMapPhotoLabel);
  const image = button.querySelector("img");
  const imageKey = `${asset.id}:${asset.contentRevision ?? ""}`;
  if (image.dataset.worldMapImageKey !== imageKey) {
    image.dataset.worldMapImageKey = imageKey;
    const revision = asset.contentRevision == null
      ? ""
      : `&r=${encodeURIComponent(asset.contentRevision)}`;
    setProtectedImageSource(
      image,
      `/v1/assets/${encodeURIComponent(asset.id)}/thumbnail?w=180${revision}`,
      { priority: "high", preserveCurrent: true }
    );
  }
  button.querySelector(":scope > span").textContent = fileName;
  syncWorldMapPhotoFavoriteButton(card, asset);
}

function clearWorldMapPhotoCardImages(cards) {
  for (const card of cards) {
    card.querySelectorAll("img[data-protected-path]").forEach(clearProtectedImageSource);
  }
}

function reconcileWorldMapPhotoCards(assets) {
  const existingCards = new Map(
    [...elements.worldMapPhotoStrip.querySelectorAll(":scope > .world-map-photo-card")]
      .map((card) => [card.dataset.worldMapCardAssetId, card])
  );
  const cards = assets.map((asset) => {
    const card = existingCards.get(asset.id) || createWorldMapPhotoCard();
    existingCards.delete(asset.id);
    syncWorldMapPhotoCard(card, asset);
    return card;
  });
  cards.forEach((card, index) => {
    const button = card.querySelector(":scope > .world-map-photo-button");
    if (button) {
      button.setAttribute(
        "aria-label",
        `${button.dataset.worldMapPhotoLabel}，第 ${index + 1} 张，共 ${cards.length} 张`
      );
    }
  });
  clearWorldMapPhotoCardImages(existingCards.values());
  reconcileStableChildren(elements.worldMapPhotoStrip, cards);
}

function navigateWorldMapPhotoStrip(event) {
  const keys = ["ArrowLeft", "ArrowRight", "PageUp", "PageDown", "Home", "End"];
  if (!keys.includes(event.key)) return false;
  const origin = event.target.closest(".world-map-photo-card");
  if (!origin) return false;
  const cards = [...elements.worldMapPhotoStrip.querySelectorAll(
    ":scope > .world-map-photo-card"
  )];
  const currentIndex = cards.indexOf(origin);
  if (currentIndex < 0) return false;
  event.preventDefault();
  if (cards.length < 2) return true;

  const first = cards[0];
  const second = cards[1];
  const stride = Math.max(1, second.offsetLeft - first.offsetLeft || first.offsetWidth);
  const pageStep = Math.max(1, Math.floor(elements.worldMapPhotoStrip.clientWidth / stride));
  const offset = {
    ArrowLeft: -1,
    ArrowRight: 1,
    PageUp: -pageStep,
    PageDown: pageStep,
  }[event.key] || 0;
  const nextIndex = event.key === "Home"
    ? 0
    : event.key === "End"
      ? cards.length - 1
      : Math.max(0, Math.min(cards.length - 1, currentIndex + offset));
  if (nextIndex === currentIndex) return true;

  const staysOnFavorite = event.target.closest(".world-map-photo-favorite");
  const target = staysOnFavorite
    ? cards[nextIndex].querySelector(":scope > .world-map-photo-favorite")
    : cards[nextIndex].querySelector(":scope > .world-map-photo-button");
  if (!(target instanceof HTMLElement) || target.disabled) return false;
  target.focus({ preventScroll: true });
  cards[nextIndex].scrollIntoView({ block: "nearest", inline: "nearest" });
  return true;
}

function worldMapPhotoStripStatus(kind, className) {
  let status = elements.worldMapPhotoStrip.querySelector(
    `:scope > [data-world-map-photo-status="${CSS.escape(kind)}"]`
  );
  if (!status) {
    status = document.createElement("div");
    status.dataset.worldMapPhotoStatus = kind;
  }
  status.className = className;
  clearWorldMapPhotoCardImages(
    elements.worldMapPhotoStrip.querySelectorAll(":scope > .world-map-photo-card")
  );
  reconcileStableChildren(elements.worldMapPhotoStrip, [status]);
  return status;
}

async function toggleWorldMapPhotoFavorite(button) {
  const assetID = button?.dataset.mediaFavoriteAssetId
    || button?.closest(".world-map-photo-card")?.dataset.worldMapCardAssetId;
  const favorite = favoriteStateForAssetID(assetID);
  if (!assetID || !favorite || state.favoriteMutating) return;
  const scrollLeft = elements.worldMapPhotoStrip.scrollLeft;
  await applyFavoriteMutation([assetID], favorite.isFavorite !== true);
  elements.worldMapPhotoStrip.scrollLeft = scrollLeft;
  if (button.isConnected) button.focus({ preventScroll: true });
}

function renderWorldMapDetail() {
  const cluster = selectedWorldMapCluster();
  const selection = state.worldMap.selection;
  elements.worldMapDetail.classList.toggle("hidden", !cluster);
  elements.worldMapBrowseClusterButton.classList.add("hidden");
  if (!cluster) {
    clearWorldMapPhotoCardImages(
      elements.worldMapPhotoStrip.querySelectorAll(":scope > .world-map-photo-card")
    );
    reconcileStableChildren(elements.worldMapPhotoStrip, []);
    return;
  }

  elements.worldMapDetailName.textContent = cluster.displayName || "未命名地点";
  elements.worldMapDetailComposition.textContent = [
    `GPS ${worldMapCount(cluster.gpsCount)}`,
    `地点标签 ${worldMapCount(cluster.tagCount)}`,
  ].join(" · ");
  elements.worldMapDetailCount.textContent = `${worldMapCount(cluster.photoCount)} 张照片`;
  const totalPhotoCount = Number(selection?.totalPhotoCount || 0);
  elements.worldMapBrowseClusterButton.classList.toggle(
    "hidden",
    state.worldMap.selectionLoading || totalPhotoCount <= 0
  );
  elements.worldMapBrowseClusterLabel.textContent = totalPhotoCount > 0
    ? `在图库中查看全部 ${worldMapCount(totalPhotoCount)} 张`
    : "在图库中查看全部照片";

  if (state.worldMap.selectionLoading) {
    elements.worldMapSelectionSummary.textContent = "正在载入预览";
    const loading = worldMapPhotoStripStatus("loading", "world-map-photo-empty");
    loading.textContent = "正在读取这个地点的照片…";
    return;
  }

  if (state.worldMap.selectionError) {
    elements.worldMapSelectionSummary.textContent = "预览载入失败";
    const failure = worldMapPhotoStripStatus("error", "world-map-photo-error");
    let icon = failure.querySelector(":scope > [data-world-map-photo-error-icon]");
    if (!icon) {
      icon = document.createElement("span");
      icon.dataset.worldMapPhotoErrorIcon = "true";
      icon.setAttribute("aria-hidden", "true");
      icon.textContent = "!";
    }
    let copy = failure.querySelector(":scope > [data-world-map-photo-error-copy]");
    if (!copy) {
      copy = document.createElement("span");
      copy.dataset.worldMapPhotoErrorCopy = "true";
    }
    copy.textContent = state.worldMap.selectionError;
    let retry = failure.querySelector(":scope > [data-retry-world-map-selection]");
    if (!retry) {
      retry = document.createElement("button");
      retry.type = "button";
      retry.className = "button button-compact";
      retry.textContent = "重试";
    }
    retry.dataset.retryWorldMapSelection = cluster.id;
    reconcileStableChildren(failure, [icon, copy, retry]);
    return;
  }

  const assets = selection?.assets || [];
  elements.worldMapSelectionSummary.textContent = assets.length < Number(selection?.totalPhotoCount || 0)
    ? `显示前 ${worldMapCount(assets.length)} 张`
    : `${worldMapCount(assets.length)} 张可预览`;
  if (!assets.length) {
    const empty = worldMapPhotoStripStatus("empty", "world-map-photo-empty");
    empty.textContent = "这个地点暂时没有可预览照片";
    return;
  }
  reconcileWorldMapPhotoCards(assets);
}

function renderWorldMap() {
  const snapshot = state.worldMap.snapshot;
  const clusters = snapshot?.clusters || [];
  elements.worldMapClusterMetric.textContent = snapshot ? worldMapCount(clusters.length) : "—";
  elements.worldMapLocatedMetric.textContent = snapshot
    ? worldMapCount(snapshot.locatedPhotoCount)
    : "—";
  elements.worldMapUnlocatedMetric.textContent = snapshot
    ? worldMapCount(snapshot.unlocatedPhotoCount)
    : "—";
  elements.worldMapRendererMetric.textContent = state.worldMap.rendererError
    ? "不可用"
    : (state.worldMap.rendererReady ? "已就绪" : "连接中");
  elements.worldMapNavigationCount.textContent = snapshot
    ? worldMapCount(snapshot.locatedPhotoCount)
    : "";
  elements.worldMapSummary.textContent = snapshot
    ? `${worldMapCount(snapshot.locatedPhotoCount)} 张已定位 · ${worldMapCount(clusters.length)} 座照片塔`
    : "按地点探索照片";

  const showStatus = state.worldMap.loading || state.worldMap.rendererError
    || Boolean(state.worldMap.loadError)
    || (snapshot && !clusters.length);
  elements.worldMapStatus.classList.toggle("hidden", !showStatus);
  if (state.worldMap.rendererError) {
    elements.worldMapStatus.dataset.state = "error";
    elements.worldMapStatus.querySelector("strong").textContent = "地图引擎暂时不可用";
    elements.worldMapStatus.querySelector("span:last-child").textContent = "可刷新重试，照片目录没有受到影响";
  } else if (state.worldMap.loading) {
    delete elements.worldMapStatus.dataset.state;
    elements.worldMapStatus.querySelector("strong").textContent = "正在整理照片地图";
    elements.worldMapStatus.querySelector("span:last-child").textContent = "照片仍保留在这台 Mac";
  } else if (state.worldMap.loadError) {
    elements.worldMapStatus.dataset.state = "error";
    elements.worldMapStatus.querySelector("strong").textContent = "照片地图暂时无法读取";
    elements.worldMapStatus.querySelector("span:last-child").textContent = "请点击右上角刷新重试，照片目录没有受到影响";
  } else if (snapshot && !clusters.length) {
    delete elements.worldMapStatus.dataset.state;
    elements.worldMapStatus.querySelector("strong").textContent = "当前范围没有已定位照片";
    elements.worldMapStatus.querySelector("span:last-child").textContent = "缩小地图或回到全球视图后再试";
  }
  renderWorldMapFooter();
  renderWorldMapDetail();
  pushWorldMapClusters();
}

function normalizedWorldMapBounds(viewport) {
  if (!viewport) return null;
  const values = [viewport.west, viewport.south, viewport.east, viewport.north];
  if (!values.every(Number.isFinite)) return null;
  const south = Math.max(-90, Math.min(90, viewport.south));
  const north = Math.max(-90, Math.min(90, viewport.north));
  if (south >= north) return null;
  return {
    west: viewport.west,
    south,
    east: viewport.east,
    north,
  };
}

function worldMapViewportCamera(viewport) {
  if (!viewport) return null;
  const values = [
    viewport.centerLongitude,
    viewport.centerLatitude,
    viewport.zoom,
    viewport.bearing,
    viewport.pitch,
  ].map(Number);
  if (!values.every(Number.isFinite)) return null;
  return {
    centerLongitude: Math.max(-180, Math.min(180, values[0])),
    centerLatitude: Math.max(-85, Math.min(85, values[1])),
    zoom: Math.max(0.7, Math.min(12, values[2])),
    bearing: Math.max(-360, Math.min(360, values[3])),
    pitch: Math.max(0, Math.min(78, values[4])),
  };
}

function normalizedWorldMapViewport(viewport) {
  const bounds = normalizedWorldMapBounds(viewport);
  if (!bounds) return null;
  const camera = worldMapViewportCamera(viewport);
  return camera ? { ...bounds, ...camera } : bounds;
}

function worldMapViewportsMatch(left, right) {
  const leftCamera = worldMapViewportCamera(left);
  const rightCamera = worldMapViewportCamera(right);
  if (!leftCamera || !rightCamera) return false;
  return Object.keys(leftCamera).every(
    (key) => Math.abs(leftCamera[key] - rightCamera[key]) <= 0.0001
  );
}

function restorePendingWorldMapViewport() {
  if (!state.worldMap.viewportRestorePending || !state.worldMap.rendererReady) return;
  const renderer = worldMapRenderer();
  if (typeof renderer?.restoreViewport !== "function") {
    state.worldMap.viewportRestorePending = false;
    return;
  }
  const target = normalizedWorldMapViewport(state.worldMap.viewport);
  if (!worldMapViewportCamera(target)) {
    state.worldMap.viewportRestorePending = false;
    return;
  }
  const current = normalizedWorldMapViewport(renderer.snapshotState?.().viewport);
  state.worldMap.viewportRestorePending = false;
  if (!worldMapViewportsMatch(current, target)) {
    state.worldMap.viewportRefreshSuppression = target;
    renderer.restoreViewport(target);
  }
}

function renderWorldMapFooter() {
  const camera = worldMapViewportCamera(state.worldMap.viewport);
  elements.worldMapViewportReadout.textContent = camera
    ? `ZOOM ${camera.zoom.toFixed(1)} · PITCH ${Math.round(camera.pitch)}° · BEARING ${Math.round(camera.bearing)}°`
    : "等待地图视角";
  if (state.worldMap.rendererError) {
    elements.worldMapFooterPrompt.textContent = "地图引擎暂时不可用；可刷新重试";
  } else if (state.worldMap.loading) {
    elements.worldMapFooterPrompt.textContent = "正在聚合目录库位置…";
  } else if (state.worldMap.loadError) {
    elements.worldMapFooterPrompt.textContent = `位置数据载入失败：${state.worldMap.loadError}`;
  } else if (state.worldMap.snapshot && !(state.worldMap.snapshot.clusters || []).length) {
    elements.worldMapFooterPrompt.textContent = "当前视口暂无已定位照片；缩小地图或更新照片位置";
  } else {
    elements.worldMapFooterPrompt.textContent = "选择一座照片建筑查看构成";
  }
}

async function loadWorldMapSnapshot({ bounds = null, quiet = false } = {}) {
  const generation = ++state.worldMap.requestGeneration;
  state.worldMap.loading = !quiet;
  if (!quiet) state.worldMap.loadError = "";
  if (!quiet) renderWorldMap();
  const query = new URLSearchParams({ maximumClusters: "2000" });
  const normalizedBounds = normalizedWorldMapBounds(bounds);
  if (normalizedBounds) {
    for (const [key, value] of Object.entries(normalizedBounds)) {
      query.set(key, String(value));
    }
  }
  try {
    const snapshot = await api(`/v1/world-map/snapshot?${query}`);
    if (generation !== state.worldMap.requestGeneration) return;
    state.worldMap.snapshot = snapshot;
    state.worldMap.loadError = "";
    if (state.worldMap.selectedClusterID
      && !(snapshot.clusters || []).some(
        (cluster) => cluster.id === state.worldMap.selectedClusterID
      )) {
      state.worldMap.selectedClusterID = null;
      state.worldMap.selection = null;
      state.worldMap.selectionError = "";
    }
  } catch (error) {
    if (generation !== state.worldMap.requestGeneration) return;
    if (!quiet || !state.worldMap.snapshot) {
      state.worldMap.snapshot = null;
      state.worldMap.loadError = error.message || "世界地图载入失败";
      toast(error.message || "世界地图载入失败");
    }
  } finally {
    if (generation === state.worldMap.requestGeneration) {
      state.worldMap.loading = false;
      renderWorldMap();
    }
  }
}

async function loadWorldMapSelection(clusterID) {
  const cluster = state.worldMap.snapshot?.clusters?.find((item) => item.id === clusterID);
  if (!cluster) return;
  const generation = ++state.worldMap.selectionGeneration;
  state.worldMap.selectedClusterID = clusterID;
  state.worldMap.selection = null;
  state.worldMap.selectionError = "";
  state.worldMap.selectionLoading = true;
  checkpointActiveWorkspaceHistory();
  worldMapRenderer()?.restoreSelection(clusterID);
  renderWorldMapDetail();
  try {
    const selection = await api("/v1/world-map/selection", {
      method: "POST",
      body: JSON.stringify({ query: cluster.selectionQuery }),
    });
    if (generation !== state.worldMap.selectionGeneration
      || state.worldMap.selectedClusterID !== clusterID) return;
    state.worldMap.selection = selection;
  } catch (error) {
    if (generation === state.worldMap.selectionGeneration) {
      state.worldMap.selectionError = error.message || "地点照片载入失败";
      toast(state.worldMap.selectionError);
    }
  } finally {
    if (generation === state.worldMap.selectionGeneration) {
      state.worldMap.selectionLoading = false;
      renderWorldMapDetail();
    }
  }
}

function worldMapIsOpen() {
  return !elements.worldMapWorkspace.classList.contains("hidden");
}

function worldMapUsesIntegratedLayout() {
  return galleryOverviewLayoutQuery.matches;
}

function clearIntegratedWorldMapFrame() {
  elements.worldMapWorkspace.classList.remove("integrated");
  for (const property of [
    "--world-map-top",
    "--world-map-right",
    "--world-map-bottom",
    "--world-map-left",
  ]) {
    elements.worldMapWorkspace.style.removeProperty(property);
  }
}

function syncIntegratedWorldMapFrame() {
  if (!worldMapIsOpen() || !worldMapUsesIntegratedLayout()) return;
  const bounds = elements.libraryPane.getBoundingClientRect();
  elements.worldMapWorkspace.classList.add("integrated");
  elements.worldMapWorkspace.style.setProperty("--world-map-top", `${bounds.top}px`);
  elements.worldMapWorkspace.style.setProperty(
    "--world-map-right",
    `${Math.max(0, globalThis.innerWidth - bounds.right)}px`
  );
  elements.worldMapWorkspace.style.setProperty(
    "--world-map-bottom",
    `${Math.max(0, globalThis.innerHeight - bounds.bottom)}px`
  );
  elements.worldMapWorkspace.style.setProperty("--world-map-left", `${bounds.left}px`);
}

function syncWorldMapPresentation({ focus = false, renderSurfaces = true } = {}) {
  const open = worldMapIsOpen();
  const integrated = open && worldMapUsesIntegratedLayout();
  const lightboxOpen = !elements.lightbox.classList.contains("hidden")
    && state.lightboxContext === "worldMap";

  if (integrated) {
    elements.appView.inert = lightboxOpen;
    elements.appView.classList.add("world-map-integrated");
    syncIntegratedWorldMapFrame();
    elements.worldMapWorkspace.setAttribute("role", "region");
    elements.worldMapWorkspace.removeAttribute("aria-modal");
    elements.closeWorldMapButton.classList.add("hidden");
    setIntegratedLibraryWorkspaceIsolation(elements.worldMapWorkspace, true);
  } else {
    setIntegratedLibraryWorkspaceIsolation(elements.worldMapWorkspace, false);
    clearIntegratedWorldMapFrame();
    elements.appView.classList.remove("world-map-integrated");
    elements.worldMapWorkspace.setAttribute("role", "dialog");
    elements.worldMapWorkspace.setAttribute("aria-modal", "true");
    elements.closeWorldMapButton.classList.remove("hidden");
    elements.appView.inert = open;
  }
  elements.worldMapWorkspace.inert = lightboxOpen;

  if (renderSurfaces) {
    renderSources();
    renderInspectorSurface();
    updateLibraryTitle();
  }
  if (focus && open && !lightboxOpen) {
    requestAnimationFrame(() => {
      const target = integrated
        ? elements.refreshWorldMapButton
        : elements.closeWorldMapButton;
      target.focus({ preventScroll: true });
    });
  }
}

function leaveIntegratedWorldMapForLibrary({ historyMode = "push" } = {}) {
  if (!worldMapIsOpen() || !worldMapUsesIntegratedLayout()) return false;
  closeWorldMapWorkspace({ restoreFocus: false });
  recordWorkspaceHistory("gallery", null, historyMode);
  return true;
}

async function openWorldMapWorkspace({ historyMode = "push" } = {}) {
  leaveIntegratedGalleryOverviewForLibrary({ historyMode: "none" });
  if (elements.trainingSetupDialog.open) closeTrainingSetupDialog();
  elements.reviewWorkspace.classList.add("hidden");
  syncReviewPresentation({ renderSurfaces: false });
  state.reviewReturnFocus = null;
  elements.trainingWorkspace.classList.add("hidden");
  syncTrainingPresentation({ renderSurfaces: false });
  state.trainingReturnFocus = null;
  elements.slimmingWorkspace.classList.add("hidden");
  syncSlimmingPresentation({ renderSurfaces: false });
  state.slimmingReturnFocus = null;
  state.slimmingReturnTarget = null;
  closeJobsPopover({ restoreFocus: false });
  closeFilterPopover({ restoreFocus: false });
  if (elements.worldMapWorkspace.classList.contains("hidden")) {
    state.worldMapReturnFocus = document.activeElement;
  }
  elements.worldMapWorkspace.classList.remove("hidden");
  syncWorldMapPresentation({ focus: true });
  recordWorkspaceHistory(
    "worldMap",
    currentWorkspaceHistoryContext("worldMap"),
    historyMode
  );
  renderWorldMap();
  if (!state.worldMap.snapshot) {
    await loadWorldMapSnapshot({ bounds: state.worldMap.viewport });
  }
  else pushWorldMapClusters();
  restorePendingWorldMapViewport();
}

function closeWorldMapWorkspace({ restoreFocus = true } = {}) {
  if (elements.worldMapLocationBackfillDialog.open) {
    closeWorldMapLocationBackfill({
      restoreFocus: false,
      checkpoint: false,
      preserveState: false,
      refreshMap: false,
    });
  }
  if (elements.worldMapPlaceTagDialog.open) {
    closeWorldMapPlaceTags({
      restoreFocus: false,
      checkpoint: false,
      preserveState: false,
    });
  }
  clearTimeout(state.worldMap.cameraTimer);
  state.worldMap.cameraTimer = null;
  elements.worldMapWorkspace.classList.add("hidden");
  syncWorldMapPresentation();
  const returnFocus = state.worldMapReturnFocus;
  state.worldMapReturnFocus = null;
  if (restoreFocus) restoreOverlayFocus(stableReturnFocusTarget(
    returnFocus,
    elements.worldMapNavigationButton
  ));
}

function clearWorldMapSelection({ restoreFocus = false } = {}) {
  if (!state.worldMap.selectedClusterID) return;
  ++state.worldMap.selectionGeneration;
  state.worldMap.selectedClusterID = null;
  state.worldMap.selection = null;
  state.worldMap.selectionError = "";
  state.worldMap.selectionLoading = false;
  worldMapRenderer()?.restoreSelection(null);
  renderWorldMapDetail();
  checkpointActiveWorkspaceHistory();
  if (restoreFocus) restoreOverlayFocus(elements.refreshWorldMapButton);
}

function cloneWorldMapGalleryScope(scope) {
  if (!scope) return null;
  return {
    clusterID: scope.clusterID,
    displayName: scope.displayName,
    photoCount: Number(scope.photoCount || 0),
    selectionQuery: {
      ...scope.selectionQuery,
      bounds: scope.selectionQuery?.bounds
        ? { ...scope.selectionQuery.bounds }
        : null,
    },
  };
}

async function openWorldMapClusterInGallery() {
  const cluster = selectedWorldMapCluster();
  const totalPhotoCount = Number(state.worldMap.selection?.totalPhotoCount || 0);
  if (!cluster?.selectionQuery || totalPhotoCount <= 0) return;

  stopAssetHoverVideo();
  clearTimeout(state.searchTimer);
  state.searchTimer = null;
  cancelPendingFilterApply();
  captureMediaSession();
  state.mediaKind = "image";
  state.libraryScope = "worldMapGallery";
  state.worldMapGalleryScope = cloneWorldMapGalleryScope({
    clusterID: cluster.id,
    displayName: cluster.displayName || "未命名地点",
    photoCount: totalPhotoCount,
    selectionQuery: cluster.selectionQuery,
  });
  state.folderScope = null;
  state.folderNavigation.selectedSessionID = null;
  state.selectedSourceID = "";
  state.selectedAssetID = null;
  state.selectedDetail = null;
  resetAssetLocalSuggestionState();
  state.searchText = "";
  state.filters = emptyFilters();
  state.filters.mediaKind = "image";
  state.filterDraft = null;
  state.selectionMode = false;
  state.selectedAssetIDs.clear();
  state.selectionAnchorID = null;
  state.selectionPrimaryDetail = null;
  state.selectionPrimaryLoadingAssetID = null;
  state.selectionPrimaryRequestGeneration += 1;
  state.inspectorDismissed = false;
  elements.searchInput.value = "";
  elements.clearSearchButton.classList.add("hidden");
  elements.inspector.classList.remove("open");
  closeWorldMapWorkspace({ restoreFocus: false });
  recordWorkspaceHistory("gallery", { worldMapClusterID: cluster.id }, "push");
  renderMediaKindTabs();
  renderSources();
  renderTagNavigation();
  syncFilterControlsFromState();
  syncSelectionModeControls();
  renderInspectorSurface();
  updateLibraryTitle();
  await loadAssets();
  captureMediaSession();
  elements.returnToWorldMapButton.focus({ preventScroll: true });
}

async function clearWorldMapGalleryScope() {
  if (state.libraryScope !== "worldMapGallery" && !state.worldMapGalleryScope) return;
  state.libraryScope = "all";
  state.worldMapGalleryScope = null;
  state.folderScope = null;
  state.folderNavigation.selectedSessionID = null;
  state.selectedSourceID = "";
  state.selectedAssetID = null;
  state.selectedDetail = null;
  state.selectedAssetIDs.clear();
  state.selectionAnchorID = null;
  state.inspectorDismissed = false;
  elements.inspector.classList.remove("open");
  renderMediaKindTabs();
  renderSources();
  renderTagNavigation();
  renderInspectorSurface();
  updateLibraryTitle();
  await loadAssets();
  captureMediaSession();
  document.querySelector('[data-source-id=""]')?.focus({ preventScroll: true });
}

function worldMapLocationPhasePresentation(phase) {
  return {
    ready: ["待检查", "default"],
    queued: ["等待中", "warning"],
    running: ["检查中", "default"],
    cancelling: ["取消中", "warning"],
    retryableFailed: ["可重试", "warning"],
    completed: ["已完成", "success"],
    cancelled: ["已取消", "muted"],
    terminalFailed: ["检查失败", "error"],
    unavailable: ["来源不可用", "muted"],
  }[phase] || ["待检查", "default"];
}

function appendWorldMapLocationMetric(parent, value, label) {
  const metric = document.createElement("span");
  metric.className = "world-map-location-metric";
  const count = document.createElement("strong");
  count.textContent = value;
  const caption = document.createElement("span");
  caption.textContent = label;
  metric.append(count, caption);
  parent.append(metric);
  return metric;
}

const worldMapLocationNavigationShortcuts =
  "ArrowUp ArrowDown PageUp PageDown Home End";

function worldMapLocationActionButtons() {
  return [...elements.worldMapLocationBackfillSources.querySelectorAll(
    ":scope > .world-map-location-source-card button[data-location-backfill-action]"
  )].filter((button) => !button.disabled
    && button.getAttribute("aria-disabled") !== "true");
}

function syncWorldMapLocationActionTabStops(preferredSourceID = null) {
  const allButtons = [...elements.worldMapLocationBackfillSources.querySelectorAll(
    ":scope > .world-map-location-source-card button[data-location-backfill-action]"
  )];
  const buttons = worldMapLocationActionButtons();
  const active = document.activeElement?.closest?.(
    "button[data-location-backfill-action][data-source-id]"
  );
  const preferred = buttons.find((button) => button === active)
    || buttons.find((button) => button.dataset.sourceId === preferredSourceID)
    || buttons.find((button) => (
      button.dataset.sourceId === state.worldMap.locationBackfill.focusTarget?.sourceID
    ))
    || buttons[0]
    || null;
  for (const button of allButtons) button.tabIndex = button === preferred ? 0 : -1;
}

function nearestWorldMapLocationAction(sourceID) {
  const cards = [...elements.worldMapLocationBackfillSources.querySelectorAll(
    ":scope > .world-map-location-source-card"
  )];
  const originIndex = Math.max(0, cards.findIndex((card) => card.dataset.sourceId === sourceID));
  return worldMapLocationActionButtons()
    .map((button) => ({
      button,
      index: cards.indexOf(button.closest(".world-map-location-source-card")),
    }))
    .sort((left, right) => (
      Math.abs(left.index - originIndex) - Math.abs(right.index - originIndex)
      || Number(right.index >= originIndex) - Number(left.index >= originIndex)
      || left.index - right.index
    ))[0]?.button || null;
}

function focusWorldMapLocationAction(button, { reveal = true } = {}) {
  if (!button) return false;
  button.focus({ preventScroll: true });
  if (reveal) button.closest(".world-map-location-source-card")
    ?.scrollIntoView({ block: "nearest", inline: "nearest" });
  syncWorldMapLocationActionTabStops(button.dataset.sourceId);
  return true;
}

function moveWorldMapLocationActionFocus(event) {
  if (event.altKey || event.ctrlKey || event.metaKey) return false;
  if (!worldMapLocationNavigationShortcuts.split(" ").includes(event.key)) return false;
  const current = event.target.closest(
    "button[data-location-backfill-action][data-source-id]"
  );
  const buttons = worldMapLocationActionButtons();
  const currentIndex = buttons.indexOf(current);
  if (currentIndex < 0 || !buttons.length) return false;
  event.preventDefault();
  const rows = buttons.map((button) => button.closest(".world-map-location-source-card"));
  const nextIndex = longListNavigationTarget(
    rows,
    currentIndex,
    event.key,
    elements.worldMapLocationBackfillBody
  );
  return focusWorldMapLocationAction(buttons[nextIndex]);
}

function createWorldMapLocationSourceCard() {
  const card = document.createElement("article");
  card.className = "world-map-location-source-card";

  const heading = document.createElement("div");
  heading.className = "world-map-location-source-heading";
  const icon = document.createElement("span");
  icon.className = "world-map-location-source-icon";
  icon.setAttribute("aria-hidden", "true");
  const title = document.createElement("span");
  title.className = "world-map-location-source-title";
  title.append(document.createElement("strong"), document.createElement("span"));
  const phase = document.createElement("span");
  phase.className = "world-map-location-phase";
  heading.append(icon, title, phase);

  const progress = document.createElement("div");
  progress.className = "world-map-location-progress";
  progress.setAttribute("role", "progressbar");
  progress.append(document.createElement("span"));

  const footer = document.createElement("div");
  footer.className = "world-map-location-source-footer";
  const metrics = document.createElement("span");
  metrics.className = "world-map-location-metrics";
  appendWorldMapLocationMetric(metrics, "", "已检查");
  appendWorldMapLocationMetric(metrics, "", "已定位");
  appendWorldMapLocationMetric(metrics, "", "无坐标");
  footer.append(metrics);

  const scan = document.createElement("div");
  scan.className = "world-map-location-scan-progress";
  card.append(heading, progress, footer, scan);
  return card;
}

function syncWorldMapLocationMetric(metric, value) {
  metric.querySelector(":scope > strong").textContent = value;
}

function syncWorldMapLocationSourceAction(footer, snapshot, busy) {
  const metrics = footer.querySelector(":scope > .world-map-location-metrics");
  const desiredAction = snapshot.canCancel ? "cancel" : (snapshot.canStart ? "start" : "status");
  let action = footer.querySelector(":scope > .world-map-location-source-action");
  const matchesDesiredAction = desiredAction === "status"
    ? action?.tagName === "SPAN" && !action.dataset.locationBackfillAction
    : action?.tagName === "BUTTON";
  if (!matchesDesiredAction) {
    action = document.createElement(desiredAction === "status" ? "span" : "button");
    action.className = "world-map-location-source-action";
  }

  if (desiredAction === "status") {
    action.className = "world-map-location-scan-progress world-map-location-source-action";
    if (snapshot.phase === "cancelling") action.textContent = "正在取消…";
    else if (snapshot.phase === "completed") action.textContent = "✓ 目录已更新";
    else if (snapshot.phase === "unavailable") action.textContent = "请先恢复来源访问";
    else action.textContent = "";
  } else {
    action.className = desiredAction === "start"
      ? "button button-primary world-map-location-source-action"
      : "button world-map-location-source-action";
    action.type = "button";
    action.dataset.locationBackfillAction = desiredAction;
    action.dataset.sourceId = snapshot.sourceID;
    action.setAttribute("aria-keyshortcuts", worldMapLocationNavigationShortcuts);
    action.setAttribute("aria-busy", String(busy));
    action.setAttribute("aria-disabled", String(busy));
    action.disabled = busy && document.activeElement !== action;
    if (desiredAction === "cancel") {
      action.textContent = busy ? "正在提交…" : "取消";
      action.setAttribute(
        "aria-label",
        busy
          ? `正在提交取消“${snapshot.sourceDisplayName}”的位置检查`
          : `取消“${snapshot.sourceDisplayName}”的位置检查`
      );
    } else {
      const retry = ["retryableFailed", "cancelled", "terminalFailed"].includes(snapshot.phase);
      action.textContent = busy ? "正在提交…" : (retry ? "重试" : "开始检查");
      action.setAttribute(
        "aria-label",
        busy
          ? `正在提交“${snapshot.sourceDisplayName}”的位置检查`
          : `${retry ? "重试" : "开始检查"}“${snapshot.sourceDisplayName}”的位置`
      );
    }
  }
  reconcileStableChildren(footer, [metrics, action]);
}

function syncWorldMapLocationSourceCard(card, snapshot, busy) {
  card.dataset.kind = snapshot.sourceKind;
  card.dataset.phase = snapshot.phase;
  card.dataset.sourceId = snapshot.sourceID;
  const heading = card.querySelector(":scope > .world-map-location-source-heading");
  heading.querySelector(":scope > .world-map-location-source-icon").textContent =
    snapshot.sourceKind === "photos" ? "▧" : "▰";
  const title = heading.querySelector(":scope > .world-map-location-source-title");
  title.querySelector(":scope > strong").textContent = snapshot.sourceDisplayName;
  title.querySelector(":scope > span").textContent =
    snapshot.sourceKind === "photos" ? "APPLE PHOTOS" : "文件夹来源";
  const [phaseLabel, phaseTone] = worldMapLocationPhasePresentation(snapshot.phase);
  const phase = heading.querySelector(":scope > .world-map-location-phase");
  phase.dataset.tone = phaseTone;
  phase.textContent = phaseLabel;

  const total = Math.max(0, Number(snapshot.totalPhotoCount || 0));
  const inspected = Math.max(0, Number(snapshot.inspectedPhotoCount || 0));
  const located = Math.max(0, Number(snapshot.locatedPhotoCount || 0));
  const fraction = total === 0 ? 1 : Math.min(1, inspected / total);
  const progress = card.querySelector(":scope > .world-map-location-progress");
  progress.setAttribute("aria-label", `${snapshot.sourceDisplayName} 位置检查进度`);
  progress.setAttribute("aria-valuemin", "0");
  progress.setAttribute("aria-valuemax", String(total));
  progress.setAttribute("aria-valuenow", String(Math.min(inspected, total)));
  progress.querySelector(":scope > span").style.setProperty(
    "--location-progress",
    `${Math.round(fraction * 100)}%`
  );

  const footer = card.querySelector(":scope > .world-map-location-source-footer");
  const metrics = footer.querySelectorAll(":scope > .world-map-location-metrics > .world-map-location-metric");
  syncWorldMapLocationMetric(metrics[0], `${worldMapCount(inspected)} / ${worldMapCount(total)}`);
  syncWorldMapLocationMetric(metrics[1], worldMapCount(located));
  syncWorldMapLocationMetric(metrics[2], worldMapCount(Math.max(0, inspected - located)));
  syncWorldMapLocationSourceAction(footer, snapshot, busy);

  const scan = card.querySelector(":scope > .world-map-location-scan-progress");
  if (!snapshot.scanProgress) {
    scan.textContent = "";
  } else {
    const completed = worldMapCount(snapshot.scanProgress.completedUnitCount);
    scan.textContent = snapshot.scanProgress.totalUnitCount == null
      ? `来源扫描已处理 ${completed} 项`
      : `来源扫描 ${completed} / ${worldMapCount(snapshot.scanProgress.totalUnitCount)}`;
  }
}

function reconcileWorldMapLocationSourceCards(snapshots, busySourceIDs) {
  const activeAction = elements.worldMapLocationBackfillSources.contains(document.activeElement)
    ? document.activeElement.closest?.(
      "button[data-location-backfill-action][data-source-id]"
    )
    : null;
  const activeSourceID = activeAction?.dataset.sourceId || null;
  const existingCards = new Map(
    [...elements.worldMapLocationBackfillSources.querySelectorAll(
      ":scope > .world-map-location-source-card"
    )].map((card) => [card.dataset.sourceId, card])
  );
  const cards = snapshots.map((snapshot) => {
    const card = existingCards.get(snapshot.sourceID) || createWorldMapLocationSourceCard();
    existingCards.delete(snapshot.sourceID);
    syncWorldMapLocationSourceCard(card, snapshot, busySourceIDs.has(snapshot.sourceID));
    return card;
  });
  reconcileStableChildren(elements.worldMapLocationBackfillSources, cards);
  syncWorldMapLocationActionTabStops(activeSourceID);
  if (activeSourceID && (!activeAction.isConnected || document.activeElement !== activeAction)) {
    const fallback = nearestWorldMapLocationAction(activeSourceID);
    if (!focusWorldMapLocationAction(fallback)) {
      elements.closeWorldMapLocationBackfillButton.focus({ preventScroll: true });
    }
  }
}

function renderWorldMapLocationBackfill() {
  const backfill = state.worldMap.locationBackfill;
  elements.worldMapLocationBackfillLoading.classList.toggle("hidden", !backfill.loading);
  elements.worldMapLocationBackfillError.classList.toggle("hidden", !backfill.error);
  elements.worldMapLocationBackfillError.textContent = backfill.error;
  const showEmpty = !backfill.loading && !backfill.error && backfill.snapshots.length === 0;
  elements.worldMapLocationBackfillEmpty.classList.toggle("hidden", !showEmpty);
  if (backfill.loading && backfill.snapshots.length === 0) {
    reconcileWorldMapLocationSourceCards([], backfill.busySourceIDs);
    return;
  }
  reconcileWorldMapLocationSourceCards(backfill.snapshots, backfill.busySourceIDs);
}

function scheduleWorldMapLocationBackfillPoll() {
  const backfill = state.worldMap.locationBackfill;
  clearTimeout(backfill.pollTimer);
  backfill.pollTimer = null;
  if (!elements.worldMapLocationBackfillDialog.open) return;
  backfill.pollTimer = setTimeout(() => {
    void loadWorldMapLocationBackfill({ quiet: true });
  }, 1_500);
}

async function loadWorldMapLocationBackfill({ quiet = false } = {}) {
  const backfill = state.worldMap.locationBackfill;
  const generation = ++backfill.requestGeneration;
  if (!quiet) backfill.loading = true;
  backfill.error = "";
  renderWorldMapLocationBackfill();
  try {
    const snapshots = await api("/v1/world-map/location-backfill");
    if (generation !== backfill.requestGeneration) return;
    backfill.snapshots = Array.isArray(snapshots) ? snapshots : [];
  } catch (error) {
    if (generation !== backfill.requestGeneration) return;
    backfill.error = error.message || "位置目录状态读取失败，请稍后重试。";
  } finally {
    if (generation === backfill.requestGeneration) {
      backfill.loading = false;
      renderWorldMapLocationBackfill();
      scheduleWorldMapLocationBackfillPoll();
    }
  }
}

async function submitWorldMapLocationBackfill(sourceID, action) {
  const backfill = state.worldMap.locationBackfill;
  if (!sourceID || backfill.busySourceIDs.has(sourceID)) return;
  const operationKey = `${action}:${sourceID}`;
  const operationID = backfill.operationIDs.get(operationKey) || crypto.randomUUID();
  backfill.operationIDs.set(operationKey, operationID);
  backfill.busySourceIDs.add(sourceID);
  backfill.error = "";
  renderWorldMapLocationBackfill();
  try {
    const response = await api("/v1/world-map/location-backfill/requests", {
      method: "POST",
      body: JSON.stringify({ operationID, sourceID, action }),
    });
    backfill.operationIDs.delete(operationKey);
    const index = backfill.snapshots.findIndex((item) => item.sourceID === sourceID);
    if (index >= 0 && response.snapshot) backfill.snapshots[index] = response.snapshot;
    if (action === "cancel") toast("已提交取消请求");
  } catch (error) {
    backfill.error = error.message || "位置目录操作提交失败，请稍后重试。";
  } finally {
    backfill.busySourceIDs.delete(sourceID);
    renderWorldMapLocationBackfill();
    scheduleWorldMapLocationBackfillPoll();
  }
}

function normalizedWorldMapLocationBackfillHistoryFocus(raw) {
  if (raw?.kind === "action"
    && ["start", "cancel"].includes(raw.action)) {
    const sourceID = galleryHistoryIdentifier(raw.sourceID);
    if (sourceID) return { kind: "action", sourceID, action: raw.action };
  }
  return { kind: "close" };
}

function currentWorldMapLocationBackfillHistoryContext() {
  const backfill = state.worldMap.locationBackfill;
  const focus = elements.worldMapLocationBackfillDialog.open
    ? (captureWorldMapLocationBackfillFocus() || backfill.focusTarget)
    : backfill.focusTarget;
  return {
    worldMapLocationBackfillScrollTop: workspaceHistoryScrollTop(
      elements.worldMapLocationBackfillDialog.open
        ? elements.worldMapLocationBackfillBody.scrollTop
        : backfill.scrollTop
    ),
    worldMapLocationBackfillFocus:
      normalizedWorldMapLocationBackfillHistoryFocus(focus),
  };
}

function applyWorldMapLocationBackfillHistoryContext(context = {}) {
  const backfill = state.worldMap.locationBackfill;
  backfill.scrollTop = workspaceHistoryScrollTop(
    context.worldMapLocationBackfillScrollTop
  );
  backfill.focusTarget = normalizedWorldMapLocationBackfillHistoryFocus(
    context.worldMapLocationBackfillFocus
  );
}

function reconcileWorldMapLocationBackfillHistoryFocus() {
  const backfill = state.worldMap.locationBackfill;
  const focus = normalizedWorldMapLocationBackfillHistoryFocus(backfill.focusTarget);
  if (focus.kind !== "action") {
    backfill.focusTarget = focus;
    return;
  }
  const snapshot = backfill.snapshots.find((item) => item.sourceID === focus.sourceID);
  const available = focus.action === "start" ? snapshot?.canStart : snapshot?.canCancel;
  if (available) {
    backfill.focusTarget = focus;
    return;
  }
  const currentAction = snapshot?.canCancel ? "cancel" : (snapshot?.canStart ? "start" : null);
  backfill.focusTarget = currentAction
    ? { kind: "action", sourceID: focus.sourceID, action: currentAction }
    : { kind: "close" };
}

async function restoreWorldMapLocationBackfillLayoutFromHistory() {
  const backfill = state.worldMap.locationBackfill;
  if (!elements.worldMapLocationBackfillDialog.open) return;
  reconcileWorldMapLocationBackfillHistoryFocus();
  await waitForWorkspaceLayout();
  elements.worldMapLocationBackfillBody.scrollTop = backfill.scrollTop;
  restoreWorldMapLocationBackfillFocus(backfill.focusTarget);
}

function worldMapLocationBackfillBaseLevelFromHistory(context = {}) {
  return ["sidebar", "inspector", "lightbox"].includes(
    context.worldMapLocationBackfillBaseLevel
  )
    ? context.worldMapLocationBackfillBaseLevel
    : "workspace";
}

function replaceWorldMapLocationBackfillHistoryWithBase(baseLevel) {
  if (!state.workspaceNavigation.initialized
    || elements.appView.classList.contains("hidden")) return;
  const current = activeWorkspaceHistoryEntry();
  const route = visibleWorkspaceRoute();
  if (current?.route !== route
    || current.navigationLevel !== "worldMapLocationBackfill") return;
  const context = currentWorkspaceHistoryContext(route);
  if (context && typeof context === "object") {
    delete context.worldMapLocationBackfillBaseLevel;
  }
  const navigationLevel = visibleWorkspaceNavigationBaseLevel(route, baseLevel);
  history.replaceState({
    ...(history.state || {}),
    [WORKSPACE_HISTORY_KEY]: workspaceHistoryEntry(route, context, navigationLevel),
  }, "", location.href);
}

function captureWorldMapLocationBackfillFocus() {
  if (!elements.worldMapLocationBackfillDialog.open) return null;
  const active = document.activeElement;
  if (!(active instanceof HTMLElement)
    || !elements.worldMapLocationBackfillDialog.contains(active)) return null;
  const action = active.closest("[data-location-backfill-action][data-source-id]");
  if (action) {
    return {
      kind: "action",
      sourceID: action.dataset.sourceId,
      action: action.dataset.locationBackfillAction,
    };
  }
  return { kind: "close" };
}

function restoreWorldMapLocationBackfillFocus(snapshot) {
  if (!elements.worldMapLocationBackfillDialog.open) return;
  let target = elements.closeWorldMapLocationBackfillButton;
  if (snapshot?.kind === "action") {
    target = elements.worldMapLocationBackfillSources.querySelector(
      `[data-location-backfill-action="${CSS.escape(snapshot.action)}"]`
      + `[data-source-id="${CSS.escape(snapshot.sourceID)}"]`
    ) || elements.worldMapLocationBackfillSources.querySelector(
      `button[data-location-backfill-action][data-source-id="${CSS.escape(snapshot.sourceID)}"]`
    ) || target;
  }
  restoreOverlayFocus(target);
  syncWorldMapLocationActionTabStops(target.dataset?.sourceId || null);
}

function clearWorldMapLocationBackfillDialogState({ cancelRequest = true } = {}) {
  const backfill = state.worldMap.locationBackfill;
  clearTimeout(backfill.pollTimer);
  backfill.pollTimer = null;
  if (cancelRequest) backfill.requestGeneration += 1;
  backfill.loading = false;
  backfill.returnFocus = null;
  backfill.baseLevel = "workspace";
  backfill.historyRestoreFocus = true;
  backfill.focusTarget = null;
  backfill.scrollTop = 0;
  backfill.restorable = false;
  backfill.opening = false;
}

function presentWorldMapLocationBackfill({
  historyMode = "pushWorldMapLocationBackfill",
  baseLevel = null,
  focus = true,
} = {}) {
  const backfill = state.worldMap.locationBackfill;
  if (elements.worldMapLocationBackfillDialog.open) {
    if (focus) restoreWorldMapLocationBackfillFocus(backfill.focusTarget);
    return;
  }
  const current = activeWorkspaceHistoryEntry();
  backfill.baseLevel = baseLevel
    || workspaceNavigationBaseLevel(
      current?.navigationLevel || "workspace",
      current?.context || {}
    );
  elements.worldMapLocationBackfillDialog.showModal();
  if (historyMode !== "none") {
    const route = visibleWorkspaceRoute();
    recordWorkspaceHistory(route, currentWorkspaceHistoryContext(route), historyMode);
  }
  backfill.restorable = true;
  renderWorldMapLocationBackfill();
  elements.worldMapLocationBackfillBody.scrollTop = backfill.scrollTop;
  if (focus) {
    requestAnimationFrame(() => restoreWorldMapLocationBackfillFocus(backfill.focusTarget));
  }
}

function openWorldMapLocationBackfill(returnFocus = document.activeElement) {
  const backfill = state.worldMap.locationBackfill;
  if (elements.worldMapLocationBackfillDialog.open || backfill.opening) return;
  backfill.opening = true;
  backfill.returnFocus = returnFocus;
  backfill.focusTarget = { kind: "close" };
  try {
    presentWorldMapLocationBackfill();
  } finally {
    backfill.opening = false;
  }
  void loadWorldMapLocationBackfill();
}

function closeWorldMapLocationBackfill({
  restoreFocus = true,
  checkpoint = true,
  preserveState = false,
  refreshMap = true,
} = {}) {
  if (!elements.worldMapLocationBackfillDialog.open) return;
  const backfill = state.worldMap.locationBackfill;
  backfill.focusTarget = captureWorldMapLocationBackfillFocus() || backfill.focusTarget;
  backfill.scrollTop = elements.worldMapLocationBackfillBody.scrollTop;
  clearTimeout(backfill.pollTimer);
  backfill.pollTimer = null;
  backfill.requestGeneration += 1;
  const baseLevel = backfill.baseLevel;
  const returnFocus = backfill.returnFocus;
  elements.worldMapLocationBackfillDialog.close();
  if (restoreFocus) {
    restoreOverlayFocus(stableReturnFocusTarget(
      returnFocus,
      elements.openWorldMapLocationBackfillButton
    ));
  }
  if (checkpoint) replaceWorldMapLocationBackfillHistoryWithBase(baseLevel);
  if (refreshMap && worldMapIsOpen()) {
    void loadWorldMapSnapshot({ bounds: state.worldMap.viewport, quiet: true });
  }
  if (!preserveState) {
    clearWorldMapLocationBackfillDialogState({ cancelRequest: false });
  }
}

function returnFromWorldMapLocationBackfill({ restoreFocus = true } = {}) {
  if (!elements.worldMapLocationBackfillDialog.open) return Promise.resolve();
  const backfill = state.worldMap.locationBackfill;
  backfill.historyRestoreFocus = restoreFocus;
  if (state.workspaceNavigation.pendingReturnPromise) {
    return state.workspaceNavigation.pendingReturnPromise;
  }
  const current = activeWorkspaceHistoryEntry();
  if (state.workspaceNavigation.initialized
    && current?.route === visibleWorkspaceRoute()
    && current.navigationLevel === "worldMapLocationBackfill") {
    const pending = new Promise((resolve) => {
      state.workspaceNavigation.pendingReturnResolve = resolve;
    });
    state.workspaceNavigation.pendingReturnPromise = pending;
    history.back();
    return pending;
  }
  closeWorldMapLocationBackfill({ restoreFocus });
  backfill.historyRestoreFocus = true;
  return Promise.resolve();
}

async function reconcileWorldMapLocationBackfillFromWorkspaceHistory(
  route,
  navigationLevel,
  context = {}
) {
  const shouldOpen = navigationLevel === "worldMapLocationBackfill"
    && route === "worldMap"
    && route === visibleWorkspaceRoute();
  const backfill = state.worldMap.locationBackfill;
  if (shouldOpen && !backfill.restorable) {
    clearWorldMapLocationBackfillDialogState();
    applyWorldMapLocationBackfillHistoryContext(context);
    backfill.returnFocus = elements.openWorldMapLocationBackfillButton;
    presentWorldMapLocationBackfill({
      historyMode: "none",
      baseLevel: worldMapLocationBackfillBaseLevelFromHistory(context),
      focus: false,
    });
    await loadWorldMapLocationBackfill();
    await restoreWorldMapLocationBackfillLayoutFromHistory();
    return true;
  }
  if (shouldOpen && !elements.worldMapLocationBackfillDialog.open) {
    backfill.returnFocus = elements.openWorldMapLocationBackfillButton;
    presentWorldMapLocationBackfill({
      historyMode: "none",
      baseLevel: worldMapLocationBackfillBaseLevelFromHistory(context),
      focus: false,
    });
    if (backfill.loading) {
      await loadWorldMapLocationBackfill();
    } else {
      scheduleWorldMapLocationBackfillPoll();
    }
    await restoreWorldMapLocationBackfillLayoutFromHistory();
  } else if (!shouldOpen && elements.worldMapLocationBackfillDialog.open) {
    const restoreFocus = backfill.historyRestoreFocus;
    closeWorldMapLocationBackfill({
      restoreFocus,
      checkpoint: false,
      preserveState: true,
    });
    backfill.historyRestoreFocus = true;
  }
  return false;
}

function worldMapPlaceStatusPresentation(status) {
  return {
    unresolved: ["未识别", "muted"],
    resolved: ["已确认", "success"],
    ambiguous: ["待选择", "warning"],
    ignored: ["已忽略", "muted"],
    failed: ["未找到", "error"],
  }[status] || ["未识别", "muted"];
}

function normalizedWorldMapPlaceQuery(item) {
  const value = state.worldMap.placeTags.queryByTagID.get(item.tagID) ?? item.tagName ?? "";
  return value.trim().split(/\s+/u).filter(Boolean).join(" ");
}

function worldMapPlaceQueryHint(item) {
  const placeTags = state.worldMap.placeTags;
  const query = normalizedWorldMapPlaceQuery(item);
  if (!query) return ["请输入至少一个地点线索。", true];
  if (query.length > placeTags.maximumQueryLength) {
    return [`地点描述请控制在 ${placeTags.maximumQueryLength} 个字符以内。`, true];
  }
  return [`将在全球范围搜索；本次只会发送：${query}`, false];
}

function worldMapPlaceProvenance(item) {
  const placeTags = state.worldMap.placeTags;
  const query = normalizedWorldMapPlaceQuery(item);
  if (placeTags.busyTagIDs.has(item.tagID)) {
    const activeQuery = placeTags.activeQueryByTagID.get(item.tagID) || query;
    return query === activeQuery
      ? [`正在用“${activeQuery}”搜索；下方旧结果会在完成后替换。`, "busy"]
      : [`正在用“${activeQuery}”搜索；你可以继续编辑，完成后再搜索“${query}”。`, "busy"];
  }
  const submitted = placeTags.submittedQueryByTagID.get(item.tagID);
  if (submitted) {
    return submitted === query
      ? [`下方结果已用“${submitted}”刷新。`, "success"]
      : [`输入已改为“${query}”；下方仍是“${submitted}”的结果，请点击重新搜索。`, "warning"];
  }
  if (item.candidates?.length) {
    return ["下方是本地缓存结果；修改描述后需点击重新搜索才会替换。", "muted"];
  }
  return ["", "muted"];
}

function updateWorldMapPlaceQueryState(tagID) {
  const placeTags = state.worldMap.placeTags;
  const item = placeTags.items.find((candidate) => candidate.tagID === tagID);
  const card = [...elements.worldMapPlaceTagItems.querySelectorAll("[data-place-tag-card]")]
    .find((candidate) => candidate.dataset.placeTagCard === tagID);
  if (!item || !card) return;
  const [hintText, hintIsError] = worldMapPlaceQueryHint(item);
  const hint = card.querySelector("[data-place-tag-hint]");
  hint.textContent = hintText;
  hint.dataset.tone = hintIsError ? "error" : "muted";
  const query = normalizedWorldMapPlaceQuery(item);
  const searchButton = card.querySelector("[data-place-tag-action=search]");
  if (searchButton) {
    searchButton.disabled = hintIsError || placeTags.busyTagIDs.has(tagID);
  }
  const [provenanceText, provenanceTone] = worldMapPlaceProvenance(item);
  const provenance = card.querySelector("[data-place-tag-provenance]");
  provenance.textContent = provenanceText;
  provenance.dataset.tone = provenanceTone;
  provenance.classList.toggle("hidden", !provenanceText);
  const input = card.querySelector("[data-place-tag-query]");
  if (input) input.setAttribute("aria-invalid", hintIsError ? "true" : "false");
  card.dataset.query = query;
}

function createWorldMapPlaceCandidateRow(interactive) {
  const row = document.createElement(interactive ? "button" : "div");
  row.className = "world-map-place-candidate";
  const mark = document.createElement("span");
  mark.className = "world-map-place-candidate-mark";
  mark.setAttribute("aria-hidden", "true");
  const copy = document.createElement("span");
  copy.className = "world-map-place-candidate-copy";
  const name = document.createElement("strong");
  const detail = document.createElement("span");
  copy.append(name, detail);
  const affordance = document.createElement("span");
  affordance.className = "world-map-place-candidate-affordance";
  affordance.setAttribute("aria-hidden", "true");
  row.append(mark, copy, affordance);
  return row;
}

function syncWorldMapPlaceCandidateRow(row, item, candidate, { interactive = true } = {}) {
  const candidateDetail = candidate.subtitle
    || `${Number(candidate.latitude).toFixed(3)}°, ${Number(candidate.longitude).toFixed(3)}°`;
  row.dataset.tagId = item.tagID;
  row.dataset.placeId = candidate.placeID;
  if (interactive) {
    row.type = "button";
    row.dataset.placeTagAction = "confirm";
    row.disabled = state.worldMap.placeTags.busyTagIDs.has(item.tagID);
    row.setAttribute("aria-label", `确认地点：${candidate.displayName}，${candidateDetail}`);
    row.setAttribute("aria-keyshortcuts", "ArrowUp ArrowDown Home End");
  }
  row.querySelector(":scope > .world-map-place-candidate-mark").textContent =
    candidate.kind === "poi" ? "●" : "▦";
  const copy = row.querySelector(":scope > .world-map-place-candidate-copy");
  copy.querySelector(":scope > strong").textContent = candidate.displayName;
  copy.querySelector(":scope > span").textContent = candidateDetail;
  row.querySelector(":scope > .world-map-place-candidate-affordance").textContent =
    interactive ? "→" : "✓";
}

function captureWorldMapPlaceFocus() {
  if (!elements.worldMapPlaceTagDialog.open) return null;
  const active = document.activeElement;
  if (!(active instanceof HTMLElement) || !elements.worldMapPlaceTagItems.contains(active)) {
    return null;
  }
  const query = active.closest("[data-place-tag-query]");
  const viewportOffset = active.getBoundingClientRect().top
    - elements.worldMapPlaceTagBody.getBoundingClientRect().top;
  if (query) {
    return {
      kind: "query",
      tagID: query.dataset.placeTagQuery,
      value: query.value,
      selectionStart: query.selectionStart,
      selectionEnd: query.selectionEnd,
      viewportOffset,
    };
  }
  const candidate = active.closest("[data-place-tag-action=confirm]");
  if (candidate) {
    return {
      kind: "candidate",
      tagID: candidate.dataset.tagId,
      placeID: candidate.dataset.placeId,
      viewportOffset,
    };
  }
  const search = active.closest("[data-place-tag-action=search]");
  return search ? {
    kind: "search",
    tagID: search.dataset.tagId,
    viewportOffset,
  } : null;
}

function normalizedWorldMapPlaceHistoryFocus(raw) {
  if (!["query", "search", "candidate"].includes(raw?.kind)) return null;
  const tagID = galleryHistoryIdentifier(raw.tagID);
  if (!tagID) return null;
  const focus = {
    kind: raw.kind,
    tagID,
    viewportOffset: workspaceHistoryFiniteNumber(raw.viewportOffset, 0, 100_000),
  };
  if (raw.kind === "candidate") {
    const placeID = galleryHistoryIdentifier(raw.placeID);
    return placeID ? { ...focus, placeID } : null;
  }
  if (raw.kind === "query") {
    focus.selectionStart = Math.max(0, Math.min(10_000, Number(raw.selectionStart) || 0));
    focus.selectionEnd = Math.max(
      focus.selectionStart,
      Math.min(10_000, Number(raw.selectionEnd) || focus.selectionStart)
    );
  }
  return focus;
}

function currentWorldMapPlaceTagsHistoryContext() {
  const placeTags = state.worldMap.placeTags;
  const focus = elements.worldMapPlaceTagDialog.open
    ? (captureWorldMapPlaceFocus() || placeTags.focusSnapshot)
    : placeTags.focusSnapshot;
  return {
    worldMapPlaceTagsScrollTop: workspaceHistoryScrollTop(
      elements.worldMapPlaceTagDialog.open
        ? elements.worldMapPlaceTagBody.scrollTop
        : placeTags.scrollTop
    ),
    worldMapPlaceTagsFocus: normalizedWorldMapPlaceHistoryFocus(focus),
  };
}

function applyWorldMapPlaceTagsHistoryContext(context = {}) {
  const placeTags = state.worldMap.placeTags;
  placeTags.scrollTop = workspaceHistoryScrollTop(context.worldMapPlaceTagsScrollTop);
  placeTags.focusSnapshot = normalizedWorldMapPlaceHistoryFocus(
    context.worldMapPlaceTagsFocus
  );
}

function reconcileWorldMapPlaceTagsHistoryFocus() {
  const placeTags = state.worldMap.placeTags;
  const focus = normalizedWorldMapPlaceHistoryFocus(placeTags.focusSnapshot);
  if (!focus) {
    placeTags.focusSnapshot = null;
    return;
  }
  const item = placeTags.items.find((candidate) => candidate.tagID === focus.tagID);
  if (!item) {
    placeTags.focusSnapshot = null;
    return;
  }
  if (focus.kind === "candidate"
    && !(item.candidates || []).some((candidate) => candidate.placeID === focus.placeID)) {
    placeTags.focusSnapshot = { ...focus, kind: "query" };
    delete placeTags.focusSnapshot.placeID;
    return;
  }
  placeTags.focusSnapshot = focus;
}

async function restoreWorldMapPlaceTagsLayoutFromHistory() {
  const placeTags = state.worldMap.placeTags;
  if (!elements.worldMapPlaceTagDialog.open) return;
  reconcileWorldMapPlaceTagsHistoryFocus();
  await waitForWorkspaceLayout();
  elements.worldMapPlaceTagBody.scrollTop = placeTags.scrollTop;
  if (placeTags.focusSnapshot) {
    restoreWorldMapPlaceFocus(placeTags.focusSnapshot, placeTags.scrollTop);
  } else {
    restoreOverlayFocus(elements.closeWorldMapPlaceTagButton);
  }
}

function restoreWorldMapPlaceFocus(snapshot, preservedScrollTop) {
  if (!snapshot || !elements.worldMapPlaceTagDialog.open) return;
  let target = null;
  if (snapshot.kind === "query") {
    target = elements.worldMapPlaceTagItems.querySelector(
      `[data-place-tag-query="${CSS.escape(snapshot.tagID)}"]`
    );
  } else if (snapshot.kind === "candidate") {
    target = elements.worldMapPlaceTagItems.querySelector(
      `[data-place-tag-action="confirm"][data-tag-id="${CSS.escape(snapshot.tagID)}"]`
      + `[data-place-id="${CSS.escape(snapshot.placeID)}"]`
    );
  } else if (snapshot.kind === "search") {
    target = elements.worldMapPlaceTagItems.querySelector(
      `[data-place-tag-action="search"][data-tag-id="${CSS.escape(snapshot.tagID)}"]`
    );
  }
  if (!(target instanceof HTMLElement) || target.matches(":disabled")) return;
  let remainingFrames = 2;
  let restoredFocus = false;
  const restore = () => {
    if (!target.isConnected || !elements.worldMapPlaceTagDialog.open) return;
    if (restoredFocus && document.activeElement !== target) return;
    if (snapshot.kind === "query"
      && typeof snapshot.value === "string"
      && target.value !== snapshot.value) return;
    if (Number.isFinite(snapshot.viewportOffset)) {
      const currentOffset = target.getBoundingClientRect().top
        - elements.worldMapPlaceTagBody.getBoundingClientRect().top;
      elements.worldMapPlaceTagBody.scrollTop += currentOffset - snapshot.viewportOffset;
    } else {
      elements.worldMapPlaceTagBody.scrollTop = preservedScrollTop;
    }
    const alreadyFocused = document.activeElement === target;
    if (!alreadyFocused) {
      target.focus({ preventScroll: true });
      restoredFocus = true;
    }
    if (!alreadyFocused
      && snapshot.kind === "query"
      && typeof target.setSelectionRange === "function") {
      const end = target.value.length;
      target.setSelectionRange(
        Math.min(snapshot.selectionStart ?? end, end),
        Math.min(snapshot.selectionEnd ?? end, end)
      );
    }
    remainingFrames -= 1;
    if (remainingFrames > 0 && restoredFocus) requestAnimationFrame(restore);
  };
  restore();
}

function createWorldMapPlaceCard() {
  const card = document.createElement("article");
  card.className = "world-map-place-card";

  const heading = document.createElement("header");
  const title = document.createElement("span");
  title.className = "world-map-place-card-title";
  title.append(document.createElement("strong"), document.createElement("span"));
  const count = document.createElement("span");
  count.className = "world-map-place-photo-count";
  const status = document.createElement("span");
  status.className = "world-map-place-status";
  heading.append(title, count, status);

  const editor = document.createElement("form");
  editor.className = "world-map-place-editor";
  const editorLabel = document.createElement("label");
  editorLabel.innerHTML = "<strong>地点描述</strong><span>全球搜索 · 可补充城市 · 州/省 · 国家 · 景区</span>";
  const field = document.createElement("div");
  field.className = "world-map-place-field";
  const input = document.createElement("input");
  input.type = "search";
  input.autocomplete = "off";
  input.spellcheck = false;
  input.placeholder = "例如：大皇宫 曼谷 泰国 / Central Park New York USA";
  const searchButton = document.createElement("button");
  searchButton.className = "button button-primary";
  searchButton.type = "submit";
  searchButton.dataset.placeTagAction = "search";
  field.append(input, searchButton);
  const hint = document.createElement("span");
  hint.className = "world-map-place-query-hint";
  const provenance = document.createElement("span");
  provenance.className = "world-map-place-provenance hidden";
  editor.append(editorLabel, field, hint, provenance);

  const result = document.createElement("section");
  result.className = "world-map-place-result";
  card.append(heading, editor, result);
  return card;
}

function syncWorldMapPlaceResult(result, item) {
  result.removeAttribute("role");
  result.removeAttribute("aria-label");
  let copy = result.querySelector(":scope > [data-world-map-place-result-copy]");
  if (!copy) {
    copy = document.createElement("p");
    copy.dataset.worldMapPlaceResultCopy = "true";
  }
  const existingCandidates = new Map(
    [...result.querySelectorAll(":scope > .world-map-place-candidate")]
      .map((row) => [row.dataset.placeId, row])
  );
  const candidateRows = [];
  if (item.status === "ambiguous") {
    result.setAttribute("role", "group");
    result.setAttribute("aria-label", `${item.tagName}的地点候选`);
    copy.textContent = "找到多个可能地点；如果都不对，请修改描述后重新搜索：";
    for (const candidate of item.candidates || []) {
      let row = existingCandidates.get(candidate.placeID);
      if (row?.tagName !== "BUTTON") row = createWorldMapPlaceCandidateRow(true);
      existingCandidates.delete(candidate.placeID);
      syncWorldMapPlaceCandidateRow(row, item, candidate);
      candidateRows.push(row);
    }
  } else if (item.status === "resolved") {
    const candidate = (item.candidates || []).find(
      (value) => value.placeID === item.confirmedPlaceID
    );
    if (candidate) {
      let row = existingCandidates.get(candidate.placeID);
      if (row?.tagName !== "DIV") row = createWorldMapPlaceCandidateRow(false);
      existingCandidates.delete(candidate.placeID);
      syncWorldMapPlaceCandidateRow(row, item, candidate, { interactive: false });
      candidateRows.push(row);
    }
    copy.textContent = candidate
      ? "地点不对？补充更多信息后重新搜索，新结果会替换当前地点。"
      : "地点已经确认并写入地图目录。";
  } else {
    if (item.status === "failed") {
      copy.textContent = "没有找到合适地点。补充更具体的信息后可以立即重新搜索。";
    } else if (item.status === "ignored") {
      copy.textContent = "这个标签已标记为非地点；输入地点信息后可重新启用定位。";
    } else {
      copy.textContent = "标签名已作为初始线索填入；也可以补充城市、省份、国家或景区名称。";
    }
  }
  const children = item.status === "resolved" ? [...candidateRows, copy] : [copy, ...candidateRows];
  reconcileStableChildren(result, children);
}

function syncWorldMapPlaceCard(card, item, busy) {
  card.dataset.placeTagCard = item.tagID;
  card.dataset.status = item.status;
  card.setAttribute("aria-busy", busy ? "true" : "false");

  const heading = card.querySelector(":scope > header");
  const title = heading.querySelector(":scope > .world-map-place-card-title");
  title.querySelector(":scope > strong").textContent = item.tagName;
  title.querySelector(":scope > span").textContent = item.groupName;
  heading.querySelector(":scope > .world-map-place-photo-count").textContent =
    `${worldMapCount(item.acceptedPhotoCount)} 张`;
  const [statusLabel, statusTone] = worldMapPlaceStatusPresentation(item.status);
  const status = heading.querySelector(":scope > .world-map-place-status");
  status.dataset.tone = statusTone;
  status.textContent = statusLabel;

  const editor = card.querySelector(":scope > .world-map-place-editor");
  editor.dataset.placeTagForm = item.tagID;
  const inputID = `worldMapPlaceQuery-${item.tagID}`;
  editor.querySelector(":scope > label").htmlFor = inputID;
  const field = editor.querySelector(":scope > .world-map-place-field");
  const input = field.querySelector(":scope > input");
  input.id = inputID;
  input.dataset.placeTagQuery = item.tagID;
  const queryValue = state.worldMap.placeTags.queryByTagID.get(item.tagID) ?? item.tagName;
  if (input.value !== queryValue) input.value = queryValue;
  const searchButton = field.querySelector(":scope > [data-place-tag-action=search]");
  searchButton.dataset.tagId = item.tagID;
  searchButton.textContent = busy
    ? "正在搜索…"
    : (item.status === "unresolved" ? "搜索" : "重新搜索");
  editor.querySelector(":scope > .world-map-place-query-hint").dataset.placeTagHint = item.tagID;
  editor.querySelector(":scope > .world-map-place-provenance").dataset.placeTagProvenance = item.tagID;
  syncWorldMapPlaceResult(card.querySelector(":scope > .world-map-place-result"), item);
}

function reconcileWorldMapPlaceCards(items, busyTagIDs) {
  const existingCards = new Map(
    [...elements.worldMapPlaceTagItems.querySelectorAll(":scope > .world-map-place-card")]
      .map((card) => [card.dataset.placeTagCard, card])
  );
  const cards = items.map((item) => {
    const card = existingCards.get(item.tagID) || createWorldMapPlaceCard();
    existingCards.delete(item.tagID);
    syncWorldMapPlaceCard(card, item, busyTagIDs.has(item.tagID));
    return card;
  });
  reconcileStableChildren(elements.worldMapPlaceTagItems, cards);
  for (const item of items) updateWorldMapPlaceQueryState(item.tagID);
}

function renderWorldMapPlaceTags({ focusTagID = null } = {}) {
  const placeTags = state.worldMap.placeTags;
  const preservedScrollTop = elements.worldMapPlaceTagBody.scrollTop;
  const preservedActiveElement = document.activeElement;
  const preservedFocus = captureWorldMapPlaceFocus();
  const showBlockingLoading = placeTags.loading && placeTags.items.length === 0;
  elements.worldMapPlaceTagBody.setAttribute("aria-busy", placeTags.loading ? "true" : "false");
  elements.worldMapPlaceTagLoading.classList.toggle("hidden", !showBlockingLoading);
  elements.worldMapPlaceTagError.classList.toggle("hidden", !placeTags.error);
  elements.worldMapPlaceTagError.textContent = placeTags.error;
  const showEmpty = !placeTags.loading && !placeTags.error && placeTags.items.length === 0;
  elements.worldMapPlaceTagEmpty.classList.toggle("hidden", !showEmpty);
  if (showBlockingLoading) {
    reconcileWorldMapPlaceCards([], placeTags.busyTagIDs);
    return;
  }
  reconcileWorldMapPlaceCards(placeTags.items, placeTags.busyTagIDs);

  elements.worldMapPlaceTagBody.scrollTop = preservedScrollTop;

  const focusSnapshot = focusTagID
    ? (preservedFocus?.tagID === focusTagID && preservedFocus.kind === "query"
      ? { ...preservedFocus, kind: "query", tagID: focusTagID }
      : { kind: "query", tagID: focusTagID })
    : preservedFocus;
  const activeElementStayedInPlace = preservedActiveElement === document.activeElement
    && elements.worldMapPlaceTagItems.contains(preservedActiveElement);
  if (focusSnapshot && elements.worldMapPlaceTagDialog.open && !activeElementStayedInPlace) {
    requestAnimationFrame(() => restoreWorldMapPlaceFocus(focusSnapshot, preservedScrollTop));
  }
}

function replaceWorldMapPlaceTagResolution(resolution) {
  const items = state.worldMap.placeTags.items;
  const index = items.findIndex((item) => item.tagID === resolution.tagID);
  if (index >= 0) items[index] = resolution;
}

async function loadWorldMapPlaceTags() {
  const placeTags = state.worldMap.placeTags;
  const generation = ++placeTags.requestGeneration;
  const mutationGeneration = placeTags.mutationGeneration;
  placeTags.loading = true;
  placeTags.error = "";
  renderWorldMapPlaceTags();
  try {
    const snapshot = await api("/v1/world-map/place-tags");
    if (generation !== placeTags.requestGeneration) return;
    if (mutationGeneration === placeTags.mutationGeneration) {
      placeTags.items = Array.isArray(snapshot.items) ? snapshot.items : [];
      placeTags.maximumQueryLength = Number(snapshot.maximumQueryLength) || 160;
      for (const item of placeTags.items) {
        if (!placeTags.queryByTagID.has(item.tagID)) {
          placeTags.queryByTagID.set(item.tagID, item.tagName);
        }
      }
    }
  } catch (error) {
    if (generation !== placeTags.requestGeneration) return;
    placeTags.error = error.message || "地点标签缓存读取失败。";
  } finally {
    if (generation === placeTags.requestGeneration) {
      placeTags.loading = false;
      renderWorldMapPlaceTags();
    }
  }
}

async function submitWorldMapPlaceTagSearch(tagID) {
  const placeTags = state.worldMap.placeTags;
  const item = placeTags.items.find((candidate) => candidate.tagID === tagID);
  if (!item || placeTags.busyTagIDs.has(tagID)) return;
  const query = normalizedWorldMapPlaceQuery(item);
  if (!query || query.length > placeTags.maximumQueryLength) {
    updateWorldMapPlaceQueryState(tagID);
    return;
  }
  const operationKey = `search:${tagID}:${query}`;
  const operationID = placeTags.operationIDs.get(operationKey) || crypto.randomUUID();
  placeTags.operationIDs.set(operationKey, operationID);
  placeTags.busyTagIDs.add(tagID);
  placeTags.activeQueryByTagID.set(tagID, query);
  placeTags.error = "";
  renderWorldMapPlaceTags({ focusTagID: tagID });
  try {
    const response = await api("/v1/world-map/place-tags/requests", {
      method: "POST",
      body: JSON.stringify({ operationID, tagID, action: "search", query }),
    });
    placeTags.operationIDs.delete(operationKey);
    placeTags.submittedQueryByTagID.set(tagID, query);
    if (response.resolution) {
      placeTags.mutationGeneration += 1;
      replaceWorldMapPlaceTagResolution(response.resolution);
    }
    void loadWorldMapSnapshot({ bounds: state.worldMap.viewport, quiet: true });
  } catch (error) {
    placeTags.error = error.message || `“${query}”的地点搜索失败，请检查描述后重试。`;
  } finally {
    placeTags.busyTagIDs.delete(tagID);
    placeTags.activeQueryByTagID.delete(tagID);
    renderWorldMapPlaceTags({ focusTagID: tagID });
  }
}

async function confirmWorldMapPlaceTag(tagID, placeID) {
  const placeTags = state.worldMap.placeTags;
  if (!tagID || !placeID || placeTags.busyTagIDs.has(tagID)) return;
  const operationKey = `confirm:${tagID}:${placeID}`;
  const operationID = placeTags.operationIDs.get(operationKey) || crypto.randomUUID();
  placeTags.operationIDs.set(operationKey, operationID);
  placeTags.busyTagIDs.add(tagID);
  placeTags.error = "";
  renderWorldMapPlaceTags();
  try {
    const response = await api("/v1/world-map/place-tags/requests", {
      method: "POST",
      body: JSON.stringify({ operationID, tagID, action: "confirm", placeID }),
    });
    placeTags.operationIDs.delete(operationKey);
    if (response.resolution) {
      placeTags.mutationGeneration += 1;
      replaceWorldMapPlaceTagResolution(response.resolution);
    }
    toast("地点已确认并写入地图目录");
    void loadWorldMapSnapshot({ bounds: state.worldMap.viewport, quiet: true });
  } catch (error) {
    placeTags.error = error.message || "地点候选已变化，请重新搜索。";
  } finally {
    placeTags.busyTagIDs.delete(tagID);
    renderWorldMapPlaceTags({ focusTagID: tagID });
  }
}

function worldMapPlaceTagsBaseLevelFromHistory(context = {}) {
  return ["sidebar", "inspector", "lightbox"].includes(context.worldMapPlaceTagsBaseLevel)
    ? context.worldMapPlaceTagsBaseLevel
    : "workspace";
}

function replaceWorldMapPlaceTagsHistoryWithBase(baseLevel) {
  if (!state.workspaceNavigation.initialized
    || elements.appView.classList.contains("hidden")) return;
  const current = activeWorkspaceHistoryEntry();
  const route = visibleWorkspaceRoute();
  if (current?.route !== route || current.navigationLevel !== "worldMapPlaceTags") return;
  const context = currentWorkspaceHistoryContext(route);
  if (context && typeof context === "object") delete context.worldMapPlaceTagsBaseLevel;
  const navigationLevel = visibleWorkspaceNavigationBaseLevel(route, baseLevel);
  history.replaceState({
    ...(history.state || {}),
    [WORKSPACE_HISTORY_KEY]: workspaceHistoryEntry(route, context, navigationLevel),
  }, "", location.href);
}

function clearWorldMapPlaceTagsDialogState({ cancelRequest = true } = {}) {
  const placeTags = state.worldMap.placeTags;
  if (cancelRequest) placeTags.requestGeneration += 1;
  placeTags.loading = false;
  placeTags.returnFocus = null;
  placeTags.baseLevel = "workspace";
  placeTags.historyRestoreFocus = true;
  placeTags.focusSnapshot = null;
  placeTags.scrollTop = 0;
  placeTags.restorable = false;
  placeTags.opening = false;
}

function presentWorldMapPlaceTags({
  historyMode = "pushWorldMapPlaceTags",
  baseLevel = null,
  focus = true,
} = {}) {
  const placeTags = state.worldMap.placeTags;
  if (elements.worldMapPlaceTagDialog.open) {
    if (focus) {
      if (placeTags.focusSnapshot) {
        restoreWorldMapPlaceFocus(placeTags.focusSnapshot, placeTags.scrollTop);
      } else {
        restoreOverlayFocus(elements.closeWorldMapPlaceTagButton);
      }
    }
    return;
  }
  const current = activeWorkspaceHistoryEntry();
  placeTags.baseLevel = baseLevel
    || workspaceNavigationBaseLevel(
      current?.navigationLevel || "workspace",
      current?.context || {}
    );
  elements.worldMapPlaceTagDialog.showModal();
  if (historyMode !== "none") {
    const route = visibleWorkspaceRoute();
    recordWorkspaceHistory(route, currentWorkspaceHistoryContext(route), historyMode);
  }
  placeTags.restorable = true;
  renderWorldMapPlaceTags();
  elements.worldMapPlaceTagBody.scrollTop = placeTags.scrollTop;
  if (focus) {
    requestAnimationFrame(() => {
      if (placeTags.focusSnapshot) {
        restoreWorldMapPlaceFocus(placeTags.focusSnapshot, placeTags.scrollTop);
      } else {
        restoreOverlayFocus(elements.closeWorldMapPlaceTagButton);
      }
    });
  }
}

function openWorldMapPlaceTags(returnFocus = document.activeElement) {
  const placeTags = state.worldMap.placeTags;
  if (elements.worldMapPlaceTagDialog.open || placeTags.opening) return;
  placeTags.opening = true;
  placeTags.returnFocus = returnFocus;
  placeTags.focusSnapshot = null;
  try {
    presentWorldMapPlaceTags();
  } finally {
    placeTags.opening = false;
  }
  void loadWorldMapPlaceTags();
}

function closeWorldMapPlaceTags({
  restoreFocus = true,
  checkpoint = true,
  preserveState = false,
} = {}) {
  if (!elements.worldMapPlaceTagDialog.open) return;
  const placeTags = state.worldMap.placeTags;
  placeTags.focusSnapshot = captureWorldMapPlaceFocus() || placeTags.focusSnapshot;
  placeTags.scrollTop = elements.worldMapPlaceTagBody.scrollTop;
  placeTags.requestGeneration += 1;
  const baseLevel = placeTags.baseLevel;
  const returnFocus = placeTags.returnFocus;
  elements.worldMapPlaceTagDialog.close();
  if (restoreFocus) {
    restoreOverlayFocus(stableReturnFocusTarget(
      returnFocus,
      elements.openWorldMapPlaceTagsButton
    ));
  }
  if (checkpoint) replaceWorldMapPlaceTagsHistoryWithBase(baseLevel);
  if (!preserveState) clearWorldMapPlaceTagsDialogState({ cancelRequest: false });
}

function returnFromWorldMapPlaceTags({ restoreFocus = true } = {}) {
  if (!elements.worldMapPlaceTagDialog.open) return Promise.resolve();
  const placeTags = state.worldMap.placeTags;
  placeTags.historyRestoreFocus = restoreFocus;
  if (state.workspaceNavigation.pendingReturnPromise) {
    return state.workspaceNavigation.pendingReturnPromise;
  }
  const current = activeWorkspaceHistoryEntry();
  if (state.workspaceNavigation.initialized
    && current?.route === visibleWorkspaceRoute()
    && current.navigationLevel === "worldMapPlaceTags") {
    const pending = new Promise((resolve) => {
      state.workspaceNavigation.pendingReturnResolve = resolve;
    });
    state.workspaceNavigation.pendingReturnPromise = pending;
    history.back();
    return pending;
  }
  closeWorldMapPlaceTags({ restoreFocus });
  placeTags.historyRestoreFocus = true;
  return Promise.resolve();
}

async function reconcileWorldMapPlaceTagsFromWorkspaceHistory(
  route,
  navigationLevel,
  context = {}
) {
  const shouldOpen = navigationLevel === "worldMapPlaceTags"
    && route === "worldMap"
    && route === visibleWorkspaceRoute();
  const placeTags = state.worldMap.placeTags;
  if (shouldOpen && !placeTags.restorable) {
    clearWorldMapPlaceTagsDialogState();
    applyWorldMapPlaceTagsHistoryContext(context);
    placeTags.returnFocus = elements.openWorldMapPlaceTagsButton;
    presentWorldMapPlaceTags({
      historyMode: "none",
      baseLevel: worldMapPlaceTagsBaseLevelFromHistory(context),
      focus: false,
    });
    await loadWorldMapPlaceTags();
    await restoreWorldMapPlaceTagsLayoutFromHistory();
    return true;
  }
  if (shouldOpen && !elements.worldMapPlaceTagDialog.open) {
    placeTags.returnFocus = elements.openWorldMapPlaceTagsButton;
    presentWorldMapPlaceTags({
      historyMode: "none",
      baseLevel: worldMapPlaceTagsBaseLevelFromHistory(context),
      focus: false,
    });
    if (placeTags.loading) {
      await loadWorldMapPlaceTags();
    }
    await restoreWorldMapPlaceTagsLayoutFromHistory();
  } else if (!shouldOpen && elements.worldMapPlaceTagDialog.open) {
    const restoreFocus = placeTags.historyRestoreFocus;
    closeWorldMapPlaceTags({
      restoreFocus,
      checkpoint: false,
      preserveState: true,
    });
    placeTags.historyRestoreFocus = true;
  }
  return false;
}

function returnFromLightbox() {
  if (elements.lightbox.classList.contains("hidden")) return Promise.resolve();
  if (state.workspaceNavigation.pendingReturnPromise) {
    return state.workspaceNavigation.pendingReturnPromise;
  }
  const route = visibleWorkspaceRoute();
  const current = activeWorkspaceHistoryEntry();
  if (state.workspaceNavigation.initialized
    && current?.route === route
    && current.navigationLevel === "lightbox") {
    const pending = new Promise((resolve) => {
      state.workspaceNavigation.pendingReturnResolve = resolve;
    });
    state.workspaceNavigation.pendingReturnPromise = pending;
    history.back();
    return pending;
  }
  closeLightbox();
  return Promise.resolve();
}

function handleWorldMapMessage(event) {
  if (event.origin !== globalThis.location.origin
    || event.source !== elements.worldMapFrame.contentWindow
    || event.data?.type !== "imageall-world-map-event") return;
  const message = event.data.payload || {};
  switch (message.type) {
  case "ready":
    state.worldMap.rendererReady = true;
    state.worldMap.rendererError = false;
    renderWorldMap();
    restorePendingWorldMapViewport();
    break;
  case "renderError":
    state.worldMap.rendererError = true;
    renderWorldMap();
    break;
  case "clusterClicked":
    if (typeof message.clusterID === "string") {
      void loadWorldMapSelection(message.clusterID);
    }
    break;
  case "escapePressed":
    if (!worldMapIsOpen()) break;
    if (!elements.worldMapDetail.classList.contains("hidden")) {
      clearWorldMapSelection({ restoreFocus: true });
    } else {
      void returnFromWorkspace("worldMap");
    }
    break;
  case "cameraChanged":
    state.worldMap.viewport = normalizedWorldMapViewport(message.viewport);
    renderWorldMapFooter();
    checkpointActiveWorkspaceHistory();
    clearTimeout(state.worldMap.cameraTimer);
    if (worldMapViewportsMatch(
      state.worldMap.viewport,
      state.worldMap.viewportRefreshSuppression
    )) {
      state.worldMap.viewportRefreshSuppression = null;
      state.worldMap.cameraTimer = null;
      break;
    }
    state.worldMap.viewportRefreshSuppression = null;
    state.worldMap.cameraTimer = setTimeout(() => {
      void loadWorldMapSnapshot({ bounds: state.worldMap.viewport, quiet: true });
    }, 240);
    break;
  default:
    break;
  }
}

function closeLightbox({ restoreFocus = true } = {}) {
  const closingContext = state.lightboxContext;
  const currentHistoryEntry = activeWorkspaceHistoryEntry();
  const consumesLightboxHistory = restoreFocus
    && !state.workspaceNavigation.applyingHistory
    && currentHistoryEntry?.route === visibleWorkspaceRoute()
    && currentHistoryEntry.navigationLevel === "lightbox";
  const preservesLibraryCloudPreview = closingContext === "library"
    && state.cloudPreview.context === "library"
    && state.cloudPreview.assetID === state.selectedDetail?.assetID;
  if (closingContext !== "review" && state.cloudPreview.status !== "hidden"
    && !preservesLibraryCloudPreview) {
    resetCloudPreviewRecovery();
  }
  elements.lightbox.classList.add("hidden");
  elements.lightbox.classList.remove("reviewing");
  elements.lightbox.removeAttribute("aria-busy");
  state.lightboxNavigating = false;
  state.lightboxPendingDirection = 0;
  ++state.lightboxRequestGeneration;
  ++state.lightboxFavoriteRequestGeneration;
  state.lightboxFavoriteLoadingAssetID = null;
  clearLightboxPreviewPrefetches();
  clearProtectedImageSource(elements.lightboxImage);
  stopLightboxVideo();
  elements.lightboxReviewActions.classList.add("hidden");
  clearLibraryLightboxIsolation();
  elements.lightbox.setAttribute("aria-modal", "true");
  state.lightboxContext = null;
  state.lightboxAssetID = null;
  state.lightboxReviewKey = null;
  state.lightboxPreservesSelection = false;
  state.lightboxOriginalAssetID = null;
  state.lightboxOriginalLoading = false;
  resetLightboxViewport(null);
  renderLightboxFavorite();
  renderCloudPreviewRecovery();
  renderReviewCloudPreviewRecovery();
  elements.reviewWorkspace.inert = false;
  elements.slimmingWorkspace.inert = false;
  elements.worldMapWorkspace.inert = false;
  if (closingContext === "review" && reviewWorkspaceIsOpen()) {
    syncReviewPresentation({ renderSurfaces: false });
  } else if (closingContext === "worldMap" && worldMapIsOpen()) {
    syncWorldMapPresentation({ renderSurfaces: false });
  } else if (closingContext === "slimming" && slimmingWorkspaceIsOpen()) {
    syncSlimmingPresentation({ renderSurfaces: false });
  } else if (elements.reviewWorkspace.classList.contains("hidden")
    && elements.slimmingWorkspace.classList.contains("hidden")
    && elements.worldMapWorkspace.classList.contains("hidden")) {
    elements.appView.inert = false;
  }
  const returnFocus = state.lightboxReturnFocus;
  state.lightboxReturnFocus = null;
  if (restoreFocus) {
    restoreOverlayFocus(returnFocus);
    if (closingContext === "slimming") {
      stabilizeDismissedOverlayFocus(
        () => returnFocus,
        elements.lightbox,
        () => visibleWorkspaceRoute() === "slimming"
          && elements.lightbox.classList.contains("hidden")
      );
    }
  }
  if (consumesLightboxHistory) history.back();
  else scheduleWorkspaceHistoryCheckpoint();
}

function focusableOverlayElements(container) {
  return [...container.querySelectorAll(
    "button:not([disabled]), input:not([disabled]), select:not([disabled]), "
      + "textarea:not([disabled]), a[href], [tabindex]:not([tabindex=\"-1\"])"
  )].filter((element) => element.getClientRects().length > 0);
}

function trapOverlayFocus(event, container) {
  if (event.key !== "Tab") return false;
  const focusable = focusableOverlayElements(container);
  if (!focusable.length) return false;
  const first = focusable[0];
  const last = focusable[focusable.length - 1];
  if (!container.contains(document.activeElement)) {
    event.preventDefault();
    (event.shiftKey ? last : first).focus({ preventScroll: true });
    return true;
  }
  if (event.shiftKey && document.activeElement === first) {
    event.preventDefault();
    last.focus({ preventScroll: true });
    return true;
  }
  if (!event.shiftKey && document.activeElement === last) {
    event.preventDefault();
    first.focus({ preventScroll: true });
    return true;
  }
  return false;
}

function trapLibraryLightboxFocus(event) {
  const libraryDocked = elements.lightbox.classList.contains("library-docked");
  const reviewDocked = elements.lightbox.classList.contains("review-docked");
  if (!libraryDocked && !reviewDocked) {
    return trapOverlayFocus(event, elements.lightbox);
  }
  if (event.key !== "Tab") return false;
  const adjacentInspector = reviewDocked
    ? elements.reviewWorkspace.querySelector(".review-detail-pane")
    : elements.inspector;
  const focusable = [
    ...focusableOverlayElements(elements.lightbox),
    ...focusableOverlayElements(adjacentInspector),
  ];
  if (!focusable.length) return false;
  const first = focusable[0];
  const last = focusable[focusable.length - 1];
  if (!focusable.includes(document.activeElement)) {
    event.preventDefault();
    (event.shiftKey ? last : first).focus({ preventScroll: true });
    return true;
  }
  if (event.shiftKey && document.activeElement === first) {
    event.preventDefault();
    last.focus({ preventScroll: true });
    return true;
  }
  if (!event.shiftKey && document.activeElement === last) {
    event.preventDefault();
    first.focus({ preventScroll: true });
    return true;
  }
  return false;
}

function clearLibraryLightboxIsolation() {
  elements.lightbox.classList.remove("library-docked", "review-docked");
  elements.lightbox.style.removeProperty("--lightbox-top");
  elements.lightbox.style.removeProperty("--lightbox-right");
  elements.lightbox.style.removeProperty("--lightbox-bottom");
  elements.lightbox.style.removeProperty("--lightbox-left");
  elements.titlebar.inert = false;
  elements.sourceSidebar.inert = false;
  elements.libraryPane.inert = false;
  elements.reviewQueuePane.inert = false;
  const statusStack = elements.appView.querySelector(".status-banner-stack");
  if (statusStack) statusStack.inert = false;
}

function syncLightboxWorkspaceFrame() {
  clearLibraryLightboxIsolation();
  const libraryPreview = state.lightboxContext === "library";
  const reviewPreview = state.lightboxContext === "review"
    && reviewWorkspaceIsOpen()
    && state.review.mode === "queue";
  if (!libraryPreview && !reviewPreview) return;

  const previewSurface = reviewPreview ? elements.reviewQueuePane : elements.libraryPane;
  const previewBounds = previewSurface.getBoundingClientRect();
  const docked = (reviewPreview
    ? reviewWorkspaceUsesIntegratedLayout()
    : globalThis.innerWidth > 720)
    && previewBounds.width > 0
    && previewBounds.height > 0;
  elements.lightbox.setAttribute("aria-modal", String(!docked));
  if (!docked) {
    elements.appView.inert = true;
    if (reviewPreview) elements.reviewWorkspace.inert = true;
    return;
  }

  elements.appView.inert = false;
  elements.titlebar.inert = true;
  elements.sourceSidebar.inert = true;
  const statusStack = elements.appView.querySelector(".status-banner-stack");
  if (statusStack) statusStack.inert = true;
  if (reviewPreview) {
    elements.libraryPane.inert = true;
    elements.reviewWorkspace.inert = false;
    elements.reviewQueuePane.inert = true;
    elements.lightbox.classList.add("review-docked");
  } else {
    elements.libraryPane.inert = true;
    elements.lightbox.classList.add("library-docked");
  }
  elements.lightbox.style.setProperty("--lightbox-top", `${previewBounds.top}px`);
  elements.lightbox.style.setProperty(
    "--lightbox-right",
    `${Math.max(0, globalThis.innerWidth - previewBounds.right)}px`
  );
  elements.lightbox.style.setProperty(
    "--lightbox-bottom",
    `${Math.max(0, globalThis.innerHeight - previewBounds.bottom)}px`
  );
  elements.lightbox.style.setProperty("--lightbox-left", `${previewBounds.left}px`);
}

function selectAuthMethod(method, { focus = "form" } = {}) {
  const account = method === "account";
  elements.accountLoginTab.classList.toggle("active", account);
  elements.accountLoginTab.setAttribute("aria-selected", String(account));
  elements.pairingLoginTab.classList.toggle("active", !account);
  elements.pairingLoginTab.setAttribute("aria-selected", String(!account));
  elements.accountLoginForm.classList.toggle("hidden", !account);
  elements.pairingForm.classList.toggle("hidden", account);
  syncRovingSegmentedControl(
    elements.accountLoginTab.parentElement,
    ".auth-method-tab"
  );
  if (focus === "tab") {
    (account ? elements.accountLoginTab : elements.pairingLoginTab)
      .focus({ preventScroll: true });
    return;
  }
  if (account) {
    elements.accountUsername.focus({ preventScroll: true });
  } else {
    elements.pairingToken.focus({ preventScroll: true });
  }
}

function moveAuthMethodSelection(event) {
  if (!["ArrowLeft", "ArrowRight", "ArrowUp", "ArrowDown", "Home", "End"].includes(
    event.key
  )) return;
  const container = elements.accountLoginTab.parentElement;
  const currentTab = event.target.closest(".auth-method-tab");
  if (!currentTab || !container.contains(currentTab)) return;
  const tabs = segmentedControlButtons(container, ".auth-method-tab");
  if (!tabs.length) return;
  event.preventDefault();
  event.stopPropagation();
  const current = Math.max(0, tabs.indexOf(currentTab));
  const backwards = event.key === "ArrowLeft" || event.key === "ArrowUp";
  const next = event.key === "Home" ? 0
    : event.key === "End" ? tabs.length - 1
      : (current + (backwards ? -1 : 1) + tabs.length) % tabs.length;
  selectAuthMethod(tabs[next] === elements.accountLoginTab ? "account" : "pairing", {
    focus: "tab",
  });
}

function showPairing(message = "") {
  state.accountAuthorization = null;
  state.authMode = null;
  updateMediaWorkerAuthorization(null);
  resetWorkspaceSessionState();
  closeOverlays();
  clearToast();
  showOnly(elements.pairingView);
  elements.accountLoginError.textContent = message;
  elements.pairingError.textContent = message;
  selectAuthMethod(elements.pairingToken.value.trim() ? "pairing" : "account");
}

function showApp({ restoreHistory = false } = {}) {
  showOnly(elements.appView);
  initializeWorkspaceHistoryRoot({ restoreExisting: restoreHistory });
  scheduleAdaptiveToolbarSync();
}

function setConnection(online, label) {
  const previousOnline = state.online;
  const previousLabel = elements.connectionLabel.textContent.trim();
  const connectionChanged = previousOnline !== online;
  const nextLabel = label || (
    online && previousOnline && previousLabel
      ? previousLabel
      : (online ? "已连接" : "Mac 离线")
  );
  state.online = online;
  const status = online ? "online" : "offline";
  elements.connectionStatus.dataset.state = status;
  elements.connectionLabel.textContent = nextLabel;
  elements.offlineBanner.classList.toggle("hidden", online);
  if (!connectionChanged) {
    if (nextLabel !== previousLabel) syncCompactToolbarMenu();
    return;
  }
  reconcileThumbnailRecoveryConnection(online);
  syncWriteActionControls();
  if (elements.commandPalette.open) renderCommandItems();
  renderPersonalModelControls();
  renderEmbeddingPreparation();
  renderSampleSuggestions();
  renderReviewOverview({
    preserveContent: reviewOverviewCanPreserveContent(),
    reconcileContent: true,
  });
  renderFavoriteControls();
  renderSourcePrewarmStatus();
  if (state.selectedDetail) renderInspectorLocalSuggestions(state.selectedDetail);
  renderSidebarSourceActions();
  syncCurrentSourceRefreshControl();
  if (elements.generalSettingsDialog.open) renderGeneralSettings();
  if (elements.tagSuggestionDialog.open) renderTagSuggestionDialog();
}

function clearToast() {
  clearTimeout(state.toastTimer);
  state.toastTimer = null;
  state.toastUndoKind = null;
  elements.toastMessage.textContent = "";
  elements.undoToastButton.classList.add("hidden");
  elements.toast.classList.add("hidden");
}

function toast(message) {
  clearToast();
  elements.toastMessage.textContent = message;
  elements.toast.classList.remove("hidden");
  state.toastTimer = setTimeout(() => elements.toast.classList.add("hidden"), 2600);
}

function undoToast(message, undoID, kind = "tag") {
  clearTimeout(state.toastTimer);
  const channel = state.undo[kind];
  if (!channel) return;
  const nextUndoID = undoID || null;
  if (channel.id !== nextUndoID) {
    channel.operationID = nextUndoID ? crypto.randomUUID() : null;
    channel.sequence = nextUndoID ? ++state.undoSequence : 0;
  } else if (nextUndoID && !channel.operationID) {
    channel.operationID = crypto.randomUUID();
  }
  channel.id = nextUndoID;
  state.toastUndoKind = nextUndoID ? kind : null;
  elements.toastMessage.textContent = message;
  elements.undoToastButton.classList.toggle("hidden", !undoID);
  elements.undoToastButton.disabled = !undoID || channel.mutating;
  elements.toast.classList.remove("hidden");
  state.toastTimer = setTimeout(() => elements.toast.classList.add("hidden"), 7000);
  renderUndoControls();
}

function renderUndoControls() {
  const tag = state.undo.tag;
  const review = state.undo.review;
  elements.undoTagButton.disabled = !state.online || !tag.id || tag.mutating;
  elements.undoTagButton.setAttribute("aria-disabled", String(elements.undoTagButton.disabled));
  elements.undoReviewButton.classList.toggle("hidden", !review.id);
  elements.undoReviewButton.disabled = !state.online || !review.id || review.mutating;
  elements.undoReviewButton.setAttribute(
    "aria-disabled",
    String(elements.undoReviewButton.disabled)
  );
  elements.reviewUndoButton.classList.toggle("hidden", !review.id);
  elements.reviewUndoButton.disabled = !state.online || !review.id || review.mutating;
  elements.reviewUndoButton.setAttribute(
    "aria-disabled",
    String(elements.reviewUndoButton.disabled)
  );
  if (state.toastUndoKind) {
    const channel = state.undo[state.toastUndoKind];
    elements.undoToastButton.disabled = !state.online || !channel?.id || channel.mutating;
  }
}

function clearElement(element) {
  element.querySelectorAll("img[data-protected-path]").forEach(clearProtectedImageSource);
  element.replaceChildren();
}

function syncWriteActionControls() {
  syncJobsRefreshControl();
  elements.batchTagSelect.disabled = !state.online
    || state.tagMutating
    || activeTags().length === 0;
  document.querySelectorAll(".write-action, .tag-action, .job-action").forEach((button) => {
    if (button.closest("#sourceManagerDialog")) return;
    if (button.closest("#generalSettingsDialog")) return;
    const isReviewAction = button.classList.contains("review-action");
    const isJobAction = button.classList.contains("job-action");
    const isBatchAction = button.classList.contains("batch-action");
    const isSelectionTagAction = Boolean(button.closest("#selectionInspectorTags"));
    const isSelectionTagOrderingChip = button.matches(
      '[data-tag-reorder-surface="selection"]'
    );
    const reviewLocked = isReviewAction
      && (state.review.loading || state.review.mutating);
    const jobLocked = isJobAction
      && state.jobMutatingIDs.has(button.dataset.jobId);
    const tagLocked = !isReviewAction
      && !isJobAction
      && (state.tagMutating || state.tagManagementMutating || state.installingPresetTags);
    const batchUnavailable = isBatchAction
      && (!state.selectedAssetIDs.size || !elements.batchTagSelect.value);
    const aggregateUnavailable = isSelectionTagAction
      && !isSelectionTagOrderingChip
      && (!state.selectedAssetIDs.size || state.loadingAggregate);
    const trainingLaunchUnavailable = button === elements.launchTrainingButton
      && !canLaunchTrainingSetup();
    const trainingActivityUnavailable = Boolean(button.dataset.trainingActivityId)
      && state.training.activityMutatingIDs.has(button.dataset.trainingActivityId);
    const favoriteUnavailable = button.matches(
      "#toolbarFavoriteSelectedButton, #toolbarUnfavoriteSelectedButton, "
        + "#favoriteSelectedButton, #unfavoriteSelectedButton, "
        + "#selectionInspectorFavoriteButton, #selectionInspectorUnfavoriteButton, "
        + "#inspectorFavoriteButton, #inspectorUnfavoriteButton, "
        + "#reviewInspectorFavoriteButton, #reviewInspectorUnfavoriteButton, "
        + "#retryFavoriteSyncButton, #lightboxFavoriteButton, "
        + ".asset-card-favorite, .review-card-favorite, .world-map-photo-favorite, "
        + ".slimming-member-favorite, .slimming-recycle-favorite"
    )
      && (!supportsFavorites() || state.favoriteMutating || state.favoriteRetrying);
    const slimmingLaunchUnavailable = button === elements.launchSlimmingButton
      && !canLaunchSlimmingSetup();
    const slimmingQuickLaunchUnavailable = (
      button === elements.slimmingCatalogAnalyzeButton
        && (Boolean(state.slimming.quickLaunchMode)
          || state.slimming.catalogSources.loading
          || selectedSlimmingCatalogSources().length === 0)
    ) || (
      button === elements.slimmingCurrentFilterAnalysisButton
        && (Boolean(state.slimming.quickLaunchMode)
          || state.mediaKind !== state.slimming.mediaKind)
    ) || (
      button === elements.slimmingSeedAnalysisButton
        && (Boolean(state.slimming.quickLaunchMode)
          || state.mediaKind !== state.slimming.mediaKind
          || currentSlimmingSeedIDs().length === 0)
    );
    const slimmingSaveUnavailable = button === elements.saveSlimmingThresholdsButton
      && !canSaveSlimmingThresholds();
    const slimmingThresholdEditorUnavailable = (
      button === elements.applySlimmingThresholdDialogButton
        && (!slimmingThresholdsValid(state.slimming.thresholdEditor.thresholds)
          || state.slimming.thresholdEditor.loading
          || state.slimming.thresholdEditor.saving)
    ) || (
      button === elements.resetSlimmingThresholdDialogButton
        && (!state.slimming.thresholdEditor.factoryThresholds
          || state.slimming.thresholdEditor.loading
          || state.slimming.thresholdEditor.saving)
    );
    const slimmingJobUnavailable = Boolean(button.dataset.slimmingJobActionId)
      && (state.slimming.jobMutatingIDs.has(button.dataset.slimmingJobActionId)
        || Boolean(state.slimming.appending));
    const slimmingRecycleUnavailable = Boolean(button.dataset.slimmingRecycleEntryId)
      && state.slimming.recycle.mutatingEntryIDs.has(button.dataset.slimmingRecycleEntryId);
    const slimmingRecycleRecoveryUnavailable = button.dataset.slimmingRecycleRecoveryKind === "source"
      && (state.sourceManagement.submitting || sourceManagementHasActiveRequest());
    const isAssetLocalSuggestionAction = button === elements.inspectorStandardModelButton
      || button === elements.inspectorPersonalModelButton;
    const assetLocalSuggestionUnavailable = isAssetLocalSuggestionAction
      && (!supportsAssetLocalSuggestions()
        || state.mediaKind !== "image"
        || state.assetLocalSuggestions.submitting
        || state.selectedDetail?.assetID !== state.assetLocalSuggestions.assetID);
    button.disabled = !state.online
      || reviewLocked
      || jobLocked
      || tagLocked
      || batchUnavailable
      || aggregateUnavailable
      || trainingLaunchUnavailable
      || trainingActivityUnavailable
      || favoriteUnavailable
      || slimmingLaunchUnavailable
      || slimmingQuickLaunchUnavailable
      || slimmingSaveUnavailable
      || slimmingThresholdEditorUnavailable
      || slimmingJobUnavailable
      || slimmingRecycleUnavailable
      || slimmingRecycleRecoveryUnavailable
      || assetLocalSuggestionUnavailable;
  });
  elements.toolbarExportPortableDataButton.disabled = !state.online
    || state.storageMaintenance.loading
    || state.storageMaintenance.submitting
    || storageMaintenanceHasActiveRequest();
  renderSourceActionsMenu();
  renderTagActionsMenu();
  if (elements.sourceManagerDialog.open) renderSourceManagement();
  if (elements.storageDialog.open) renderStorageMaintenance();
  renderFavoriteControls();
  renderGalleryRemovalControls();
  renderUndoControls();
  if (state.selectedDetail) {
    syncInspectorViewOriginalControl(state.selectedDetail);
    syncInspectorOpenOriginalControl(state.selectedDetail);
  }
  const reviewItem = state.review.items[state.review.selectedIndex];
  if (reviewWorkspaceIsOpen() && reviewItem) {
    const detail = reviewInspectorDetailMatches(reviewItem) ? state.review.detail : null;
    syncReviewViewOriginalControl(detail, reviewItem);
    syncReviewOpenOriginalControl(detail, reviewItem);
  }
  syncManagedTagFields({ updateValues: false });
  syncManagedGroupFields({ updateValues: false });
  syncInlineTagCreationControls();
}

function clampSplitWidth(value, range) {
  const numeric = Number(value);
  if (!Number.isFinite(numeric)) return range.default;
  return Math.round(Math.min(range.max, Math.max(range.min, numeric)));
}

function migrateLegacyGridDensity(value) {
  const legacyWidth = LEGACY_DENSITY_WIDTHS[value];
  if (!Number.isFinite(legacyWidth)) return 3;
  return GRID_DENSITY_OPTIONS.reduce((nearest, option) => (
    Math.abs(option.width - legacyWidth)
      < Math.abs(GRID_DENSITY_OPTIONS[nearest].width - legacyWidth)
      ? option.value
      : nearest
  ), 0);
}

function persistWorkspacePreferences() {
  localStorage.setItem("imageall.web.workspace-preferences", JSON.stringify({
    sidebarVisible: state.layout.sidebarVisible,
    inspectorVisible: state.layout.inspectorVisible,
    sidebarWidth: state.layout.sidebarWidth,
    inspectorWidth: state.layout.inspectorWidth,
    reviewModelWidth: state.layout.reviewModelWidth,
    reviewInspectorWidth: state.layout.reviewInspectorWidth,
    trainingNavigatorVisible: state.layout.trainingNavigatorVisible,
    density: state.layout.density,
    densityScaleVersion: GRID_DENSITY_SCALE_VERSION,
    aspectMode: state.layout.aspectMode,
    collapsedTagGroupIDs: [...state.layout.collapsedTagGroupIDs],
    // Keep legacy keys synchronized so an older Web Companion build does not
    // split the shared Mac-style state again after a rollback.
    collapsedSidebarTagGroupIDs: [...state.layout.collapsedTagGroupIDs],
    collapsedInspectorTagGroupIDs: [...state.layout.collapsedTagGroupIDs],
    collapsedReviewTagGroupIDs: [...state.layout.collapsedReviewTagGroupIDs],
    sourceOrderIDs: state.layout.sourceOrderIDs,
    tagOrderIDsByGroup: state.layout.tagOrderIDsByGroup,
  }));
}

function loadWorkspacePreferences() {
  try {
    const saved = JSON.parse(
      localStorage.getItem("imageall.web.workspace-preferences") || "{}"
    );
    if (typeof saved.sidebarVisible === "boolean") {
      state.layout.sidebarVisible = saved.sidebarVisible;
    }
    if (typeof saved.inspectorVisible === "boolean") {
      state.layout.inspectorVisible = saved.inspectorVisible;
    }
    if (Number.isFinite(saved.sidebarWidth)) {
      state.layout.sidebarWidth = clampSplitWidth(saved.sidebarWidth, SIDEBAR_WIDTH);
    }
    if (Number.isFinite(saved.inspectorWidth)) {
      state.layout.inspectorWidth = clampSplitWidth(saved.inspectorWidth, INSPECTOR_WIDTH);
    }
    if (Number.isFinite(saved.reviewModelWidth)) {
      state.layout.reviewModelWidth = clampSplitWidth(
        saved.reviewModelWidth,
        REVIEW_MODEL_WIDTH
      );
    }
    if (Number.isFinite(saved.reviewInspectorWidth)) {
      state.layout.reviewInspectorWidth = clampSplitWidth(
        saved.reviewInspectorWidth,
        REVIEW_INSPECTOR_WIDTH
      );
    }
    if (typeof saved.trainingNavigatorVisible === "boolean") {
      state.layout.trainingNavigatorVisible = saved.trainingNavigatorVisible;
    }
    if (Number.isInteger(saved.density) && saved.density >= 0 && saved.density <= 8) {
      state.layout.density = saved.densityScaleVersion === GRID_DENSITY_SCALE_VERSION
        ? saved.density
        : migrateLegacyGridDensity(saved.density);
    }
    if (["square", "original"].includes(saved.aspectMode)) {
      state.layout.aspectMode = saved.aspectMode;
    }
    const savedCollapsedTagGroupIDs = Array.isArray(saved.collapsedTagGroupIDs)
      ? saved.collapsedTagGroupIDs
      : [
          ...(Array.isArray(saved.collapsedSidebarTagGroupIDs)
            ? saved.collapsedSidebarTagGroupIDs
            : []),
          ...(Array.isArray(saved.collapsedInspectorTagGroupIDs)
            ? saved.collapsedInspectorTagGroupIDs
            : []),
        ];
    state.layout.collapsedTagGroupIDs = new Set(
      savedCollapsedTagGroupIDs.filter((value) => typeof value === "string")
    );
    if (Array.isArray(saved.collapsedReviewTagGroupIDs)) {
      state.layout.collapsedReviewTagGroupIDs = new Set(
        saved.collapsedReviewTagGroupIDs.filter((value) => typeof value === "string")
      );
    }
    if (Array.isArray(saved.sourceOrderIDs)) {
      state.layout.sourceOrderIDs = saved.sourceOrderIDs.filter(
        (value) => typeof value === "string"
      );
    }
    if (saved.tagOrderIDsByGroup && typeof saved.tagOrderIDsByGroup === "object") {
      state.layout.tagOrderIDsByGroup = Object.fromEntries(
        Object.entries(saved.tagOrderIDsByGroup)
          .filter(([key, value]) => typeof key === "string" && Array.isArray(value))
          .map(([key, value]) => [
            key,
            value.filter((item) => typeof item === "string"),
          ])
      );
    }
  } catch {
    // Invalid UI preferences are ignored; credentials are never stored here.
  }
}

function gridDensityControls() {
  return [
    {
      button: elements.gridDensityButton,
      label: elements.gridDensityButtonLabel,
      popover: elements.gridDensityPopover,
      surface: "图库",
      kind: "galleryGridDensity",
      route: "gallery",
    },
    {
      button: elements.reviewGridDensityButton,
      label: elements.reviewGridDensityButtonLabel,
      popover: elements.reviewGridDensityPopover,
      surface: "待审核",
      kind: "reviewGridDensity",
      route: "review",
    },
    {
      button: elements.slimmingGridDensityButton,
      label: elements.slimmingGridDensityButtonLabel,
      popover: elements.slimmingGridDensityPopover,
      surface: "图库瘦身",
      kind: "slimmingGridDensity",
      route: "slimming",
    },
  ];
}

function gridDensityOption(value = state.layout.density) {
  return GRID_DENSITY_OPTIONS.find((option) => option.value === Number(value))
    || GRID_DENSITY_OPTIONS[3];
}

function ensureGridDensityMenuItems(control) {
  if (control.popover.childElementCount === GRID_DENSITY_OPTIONS.length) return;
  clearElement(control.popover);
  for (const option of GRID_DENSITY_OPTIONS) {
    const button = document.createElement("button");
    button.type = "button";
    button.setAttribute("role", "menuitemradio");
    button.dataset.gridDensity = String(option.value);
    button.textContent = option.title;
    control.popover.append(button);
  }
}

function renderGridDensityControls() {
  const selected = gridDensityOption();
  for (const control of gridDensityControls()) {
    ensureGridDensityMenuItems(control);
    control.label.textContent = selected.title;
    control.button.setAttribute("aria-label", `缩略图大小：${selected.title}`);
    control.button.title = `缩略图大小：${selected.title}`;
    configurePersistentHelp(control.button, {
      title: `缩略图大小：${selected.title}`,
      detail: `调整${control.surface}网格。九档大小与 Mac 一致，当前为“${selected.title}”。`,
    });
    for (const button of control.popover.querySelectorAll("[data-grid-density]")) {
      const option = gridDensityOption(button.dataset.gridDensity);
      const isSelected = option.value === selected.value;
      button.setAttribute("aria-checked", String(isSelected));
      configurePersistentHelp(button, {
        title: option.title,
        detail: `把图库、待审核和图库瘦身的共享缩略图大小切换为“${option.title}”。`,
      });
    }
  }
  document.documentElement.style.setProperty("--asset-min-width", `${selected.width}px`);
  document.documentElement.style.setProperty(
    "--slimming-member-min-width",
    `${selected.width}px`
  );
}

function renderLayoutPreferences() {
  const sidebarWidth = clampSplitWidth(state.layout.sidebarWidth, SIDEBAR_WIDTH);
  const inspectorWidth = clampSplitWidth(state.layout.inspectorWidth, INSPECTOR_WIDTH);
  const reviewModelWidth = clampSplitWidth(
    state.layout.reviewModelWidth,
    REVIEW_MODEL_WIDTH
  );
  const reviewInspectorWidth = clampSplitWidth(
    state.layout.reviewInspectorWidth,
    REVIEW_INSPECTOR_WIDTH
  );
  state.layout.sidebarWidth = sidebarWidth;
  state.layout.inspectorWidth = inspectorWidth;
  state.layout.reviewModelWidth = reviewModelWidth;
  state.layout.reviewInspectorWidth = reviewInspectorWidth;
  elements.workspace.style.setProperty("--sidebar-width", `${sidebarWidth}px`);
  elements.workspace.style.setProperty("--inspector-width", `${inspectorWidth}px`);
  elements.sidebarResizeHandle.setAttribute("aria-valuenow", String(sidebarWidth));
  elements.sidebarResizeHandle.setAttribute("aria-valuetext", `侧栏宽度 ${sidebarWidth} 像素`);
  elements.inspectorResizeHandle.setAttribute("aria-valuenow", String(inspectorWidth));
  elements.inspectorResizeHandle.setAttribute("aria-valuetext", `检查器宽度 ${inspectorWidth} 像素`);
  elements.reviewOverviewLayout.style.setProperty(
    "--review-model-width",
    `${reviewModelWidth}px`
  );
  elements.reviewOverviewResizeHandle.setAttribute(
    "aria-valuenow",
    String(reviewModelWidth)
  );
  elements.reviewOverviewResizeHandle.setAttribute(
    "aria-valuetext",
    `本地模型面板宽度 ${reviewModelWidth} 像素`
  );
  elements.reviewQueueLayout.style.setProperty(
    "--review-inspector-width",
    `${reviewInspectorWidth}px`
  );
  elements.reviewQueueResizeHandle.setAttribute(
    "aria-valuenow",
    String(reviewInspectorWidth)
  );
  elements.reviewQueueResizeHandle.setAttribute(
    "aria-valuetext",
    `审核检查器宽度 ${reviewInspectorWidth} 像素`
  );
  elements.workspace.classList.toggle("sidebar-hidden", !state.layout.sidebarVisible);
  elements.workspace.classList.toggle("inspector-hidden", !state.layout.inspectorVisible);
  if (reviewWorkspaceIsOpen() && reviewWorkspaceUsesIntegratedLayout()) {
    syncIntegratedReviewFrame();
  }
  renderSidebarVisibilityControl();
  renderInspectorVisibilityControl();
  renderGridDensityControls();
  const originalAspect = state.layout.aspectMode === "original";
  elements.assetGrid.classList.toggle("original-aspect", originalAspect);
  elements.reviewGrid.classList.toggle("original-aspect", originalAspect);
  elements.slimmingMemberGrid.classList.toggle("original-aspect", originalAspect);
  elements.slimmingRecycleList.classList.toggle("original-aspect", originalAspect);
  renderThumbnailAspectControls();
}

function thumbnailAspectPresentation(aspectMode = state.layout.aspectMode) {
  return aspectMode === "original"
    ? {
      mode: "original",
      title: "原比例",
      help: "当前优先显示已手动缓存的原比例缩略图，未缓存项目仍为正方形。点击切回全部正方形。",
    }
    : {
      mode: "square",
      title: "正方形",
      help: "当前缩略图为正方形。点击后，仅手动生成过原比例缓存的照片和视频会完整显示；其余项目保持正方形。",
    };
}

function renderThumbnailAspectControls() {
  const presentation = thumbnailAspectPresentation();
  const controls = [
    [elements.thumbnailAspectButton, "control"],
    [elements.reviewThumbnailAspectButton, "review"],
    [elements.slimmingThumbnailAspectButton, "slimming"],
  ];
  for (const [control, kind] of controls) {
    control.dataset.aspectMode = presentation.mode;
    control.removeAttribute("aria-pressed");
    control.setAttribute("aria-label", `缩略图比例：${presentation.title}`);
    control.title = `缩略图比例：${presentation.title}`;
    const label = control.querySelector(".thumbnail-aspect-label");
    if (label) label.textContent = presentation.title;
    configurePersistentHelp(control, {
      title: `缩略图比例：${presentation.title}`,
      detail: presentation.help,
      kind,
    });
  }
}

function setSidebarVisible(visible) {
  state.layout.sidebarVisible = visible;
  renderLayoutPreferences();
  persistWorkspacePreferences();
}

function sidebarVisibilityIsPresented() {
  if (mobileSidebarLayoutQuery.matches && visibleWorkspaceRoute() === "gallery") {
    return mobileSidebarOverlayIsOpen();
  }
  return state.layout.sidebarVisible;
}

function renderSidebarVisibilityControl() {
  const presented = sidebarVisibilityIsPresented();
  const title = presented ? "隐藏侧栏" : "显示侧栏";
  elements.sidebarVisibilityButton.setAttribute("aria-pressed", String(presented));
  elements.sidebarVisibilityButton.setAttribute("aria-label", title);
  elements.sidebarVisibilityLabel.textContent = title;
  elements.sidebarVisibilityButton.title = title;
}

async function toggleSidebarVisibility(returnFocus = document.activeElement) {
  if (mobileSidebarLayoutQuery.matches && visibleWorkspaceRoute() === "gallery") {
    if (mobileSidebarOverlayIsOpen()) {
      await returnFromMobileSidebar();
    } else {
      openMobileSidebar({ returnFocus });
    }
    renderSidebarVisibilityControl();
    return;
  }
  setSidebarVisible(!state.layout.sidebarVisible);
}

function setInspectorVisible(visible) {
  state.layout.inspectorVisible = visible;
  renderLayoutPreferences();
  persistWorkspacePreferences();
}

function inspectorVisibilityIsPresented() {
  if (!galleryOverviewLayoutQuery.matches && visibleWorkspaceRoute() === "gallery") {
    return galleryInspectorOverlayIsOpen();
  }
  return state.layout.inspectorVisible;
}

function renderInspectorVisibilityControl() {
  const presented = inspectorVisibilityIsPresented();
  const title = presented ? "隐藏检查器" : "显示检查器";
  elements.inspectorVisibilityButton.setAttribute("aria-pressed", String(presented));
  elements.inspectorVisibilityButton.setAttribute("aria-label", title);
  elements.inspectorVisibilityLabel.textContent = title;
  elements.inspectorVisibilityButton.title = title;
}

async function toggleInspectorVisibility(returnFocus = document.activeElement) {
  if (!galleryOverviewLayoutQuery.matches && visibleWorkspaceRoute() === "gallery") {
    if (galleryInspectorOverlayIsOpen()) {
      await returnFromInspector();
    } else {
      openGalleryInspectorOverlay({ returnFocus });
    }
    renderInspectorVisibilityControl();
    return;
  }
  setInspectorVisible(!state.layout.inspectorVisible);
}

function splitResizeDescriptor(kind) {
  if (kind === "sidebar") {
    return {
      key: "sidebarWidth",
      range: SIDEBAR_WIDTH,
      handle: elements.sidebarResizeHandle,
      pointerMultiplier: 1,
      container: elements.workspace,
    };
  }
  if (kind === "inspector") {
    return {
      key: "inspectorWidth",
      range: INSPECTOR_WIDTH,
      handle: elements.inspectorResizeHandle,
      pointerMultiplier: -1,
      container: elements.workspace,
    };
  }
  if (kind === "reviewModel") {
    return {
      key: "reviewModelWidth",
      range: REVIEW_MODEL_WIDTH,
      handle: elements.reviewOverviewResizeHandle,
      pointerMultiplier: 1,
      container: elements.reviewOverviewLayout,
    };
  }
  return {
    key: "reviewInspectorWidth",
    range: REVIEW_INSPECTOR_WIDTH,
    handle: elements.reviewQueueResizeHandle,
    pointerMultiplier: -1,
    container: elements.reviewQueueLayout,
  };
}

function setSplitWidth(kind, width, { persist = false } = {}) {
  const descriptor = splitResizeDescriptor(kind);
  state.layout[descriptor.key] = clampSplitWidth(width, descriptor.range);
  renderLayoutPreferences();
  if (persist) persistWorkspacePreferences();
}

function beginSplitResize(event, kind) {
  if (event.button !== 0 || globalThis.matchMedia("(max-width: 700px)").matches) return;
  const descriptor = splitResizeDescriptor(kind);
  event.preventDefault();
  state.splitResize = {
    kind,
    pointerID: event.pointerId,
    startX: event.clientX,
    startWidth: state.layout[descriptor.key],
  };
  descriptor.handle.dataset.resizing = "true";
  descriptor.handle.setPointerCapture?.(event.pointerId);
  descriptor.container.classList.add("split-resizing");
  document.documentElement.classList.add("split-resizing");
}

function moveSplitResize(event) {
  const session = state.splitResize;
  if (!session || event.pointerId !== session.pointerID) return;
  const descriptor = splitResizeDescriptor(session.kind);
  const delta = (event.clientX - session.startX) * descriptor.pointerMultiplier;
  setSplitWidth(session.kind, session.startWidth + delta);
}

function finishSplitResize(event) {
  const session = state.splitResize;
  if (!session || event.pointerId !== session.pointerID) return;
  const descriptor = splitResizeDescriptor(session.kind);
  if (descriptor.handle.hasPointerCapture?.(event.pointerId)) {
    descriptor.handle.releasePointerCapture(event.pointerId);
  }
  delete descriptor.handle.dataset.resizing;
  descriptor.container.classList.remove("split-resizing");
  document.documentElement.classList.remove("split-resizing");
  state.splitResize = null;
  persistWorkspacePreferences();
}

function adjustSplitWidthFromKeyboard(event, kind) {
  if (!["ArrowLeft", "ArrowRight", "Home", "End"].includes(event.key)) return;
  const descriptor = splitResizeDescriptor(kind);
  const current = state.layout[descriptor.key];
  let next = current;
  if (event.key === "Home") next = descriptor.range.min;
  else if (event.key === "End") next = descriptor.range.max;
  else {
    const step = event.shiftKey ? SPLIT_KEYBOARD_STEP * 2 : SPLIT_KEYBOARD_STEP;
    const visualDirection = event.key === "ArrowRight" ? 1 : -1;
    next += step * visualDirection * descriptor.pointerMultiplier;
  }
  event.preventDefault();
  setSplitWidth(kind, next, { persist: true });
}

function resetSplitWidth(kind) {
  const descriptor = splitResizeDescriptor(kind);
  setSplitWidth(kind, descriptor.range.default, { persist: true });
}

function captureMediaSession() {
  state.mediaSessions[state.mediaKind] = {
    assets: state.assets.map((asset) => ({ ...asset })),
    nextCursor: state.nextCursor,
    selectedSourceID: state.selectedSourceID,
    libraryScope: state.libraryScope,
    worldMapGalleryScope: cloneWorldMapGalleryScope(state.worldMapGalleryScope),
    folderScope: cloneFolderScope(state.folderScope),
    folderSessionID: state.folderNavigation.selectedSessionID,
    selectedAssetID: state.selectedAssetID,
    selectedDetail: state.selectedDetail,
    searchText: state.searchText,
    sort: state.sort,
    filters: cloneFilters(state.filters),
    selectionMode: state.selectionMode,
    selectedAssetIDs: [...state.selectedAssetIDs],
    selectionAnchorID: state.selectionAnchorID,
    inspectorDismissed: state.inspectorDismissed,
    scrollTop: elements.libraryScroll.scrollTop,
  };
  scheduleWorkspaceHistoryCheckpoint();
}

function currentMediaNoun() {
  return state.mediaKind === "video" ? "视频" : "照片";
}

function mediaItemCountText(count) {
  return state.mediaKind === "video" ? `${count} 个视频` : `${count} 张照片`;
}

function renderMediaKindLabels() {
  const noun = currentMediaNoun();
  elements.allMediaLabel.textContent = `全部${noun}`;
  elements.libraryPane.setAttribute("aria-label", `${noun}图库`);
  elements.filterTitle.textContent = `筛选${noun}`;
  elements.tagPresenceAnyOption.textContent = `全部${noun}`;
  renderLibraryEmptyState();
  elements.inspector.setAttribute("aria-label", `${noun}检查器`);
  elements.inspectorSelectionTitle.textContent = state.mediaKind === "video"
    ? "已选择 1 个视频"
    : "已选择 1 张照片";
  elements.inspectorPlaceholderText.textContent = state.mediaKind === "video"
    ? "选择一个或多个视频后，可左键打上标签、右键取消标签。"
    : "选择一张或多张照片后，可左键打上标签、右键取消标签。";
  elements.inspectorNavigation.setAttribute("aria-label", `${noun}导航`);
  elements.inspectorPreviousButton.setAttribute("aria-label", `上一个${noun}`);
  elements.inspectorNextButton.setAttribute("aria-label", `下一个${noun}`);
  elements.sidebarNewTagButton.title = `为所选${noun}新增标签`;
  elements.lightbox.setAttribute("aria-label", `${noun}全屏预览`);
}

function renderLibraryEmptyState() {
  const noun = currentMediaNoun();
  const noSources = state.sources.length === 0;
  const noTags = activeTags().length === 0;
  const selectedSource = state.sources.find((source) => source.id === state.selectedSourceID);
  const hasSearch = Boolean(state.searchText);
  const hasTagFilters = Boolean(
    state.filters.tagConditions.length || state.filters.tagPresence !== "any"
  );
  const hasPropertyFilters = Boolean(
    state.filters.availabilities.length || state.filters.mediaTypes.length
  );
  const constrained = hasSearch || hasTagFilters || hasPropertyFilters;
  const conditionGroupCount = [hasSearch, hasTagFilters, hasPropertyFilters]
    .filter(Boolean).length;
  let recoveryAction = null;
  elements.emptyStateSymbol.textContent = "▧";

  if (noSources && noTags) {
    elements.emptyStateSymbol.textContent = "+";
    elements.emptyStateTitle.textContent = "开始建立你的照片资料库";
    elements.emptyStateCopy.textContent = "连接一个照片来源，也可以添加一组可编辑的常用标签。常用标签不会分析照片，也不会自动应用到任何照片。";
  } else if (noSources) {
    elements.emptyStateSymbol.textContent = "+";
    elements.emptyStateTitle.textContent = "ImageAll 在原位置读取照片";
    elements.emptyStateCopy.textContent = "连接照片文件夹或 Apple Photos 后即可开始；ImageAll 不会导入、移动或重命名原图。";
  } else if (constrained) {
    elements.emptyStateSymbol.textContent = "≡";
    elements.emptyStateTitle.textContent = `没有找到${noun}`;
    const filterSummary = activeFilterSummaryText();
    if (hasSearch && (hasTagFilters || hasPropertyFilters)) {
      elements.emptyStateCopy.textContent = `搜索“${state.searchText}”与当前筛选“${filterSummary}”没有交集。可以单独清除一组条件，或恢复当前范围的全部${noun}。`;
    } else if (hasSearch) {
      elements.emptyStateCopy.textContent = `没有找到与“${state.searchText}”匹配的${noun}。搜索会同时匹配文件名、相对路径、标签和来源。`;
    } else {
      elements.emptyStateCopy.textContent = `当前筛选“${filterSummary}”没有结果。清除后会恢复当前来源和媒体范围内的${noun}。`;
    }
  } else if (state.libraryScope === "worldMapGallery" && state.worldMapGalleryScope) {
    elements.emptyStateSymbol.textContent = "⌖";
    elements.emptyStateTitle.textContent = "这个地点没有可显示的照片";
    elements.emptyStateCopy.textContent = "地点范围仍然有效；可以返回照片世界选择另一座照片塔，或查看全部照片。";
  } else if (state.libraryScope === "favorites") {
    elements.emptyStateSymbol.textContent = "♡";
    elements.emptyStateTitle.textContent = `还没有红心${noun}`;
    elements.emptyStateCopy.textContent = "在网格菜单、检查器或多选工具栏中加入红心后，会集中显示在这里。";
  } else if (selectedSource?.kind === "photos" && selectedSource.state === "unavailable") {
    elements.emptyStateSymbol.textContent = "!";
    elements.emptyStateTitle.textContent = "系统照片图库已更换";
    elements.emptyStateCopy.textContent = "旧来源的索引、人工标签和历史仍保留；可在 Mac 上确认后连接当前系统照片图库。";
    recoveryAction = "rebindPhotos";
  } else if (selectedSource?.kind === "photos"
    && ["authorizationRequired", "disabled"].includes(selectedSource.state)) {
    elements.emptyStateSymbol.textContent = "⌑";
    elements.emptyStateTitle.textContent = "需要照片访问权限";
    elements.emptyStateCopy.textContent = "请在 Mac 上重新请求或检查照片权限；网页不会绕过 macOS 授权面板。";
    recoveryAction = "reauthorize";
  } else if (selectedSource?.kind === "photos" && selectedSource.state === "active") {
    elements.emptyStateSymbol.textContent = "▣";
    elements.emptyStateTitle.textContent = "系统照片图库中没有可访问的照片";
    elements.emptyStateCopy.textContent = "可在 Mac 上立即同步当前系统照片图库，更新索引和可用状态。";
    recoveryAction = "syncPhotos";
  } else if (selectedSource?.kind === "folder"
    && ["unavailable", "authorizationRequired"].includes(selectedSource.state)) {
    elements.emptyStateSymbol.textContent = "⌑";
    elements.emptyStateTitle.textContent = "需要重新授权文件夹";
    elements.emptyStateCopy.textContent = "请在 Mac 系统选择器中重新选择原文件夹；网页不会接收路径或安全作用域书签。";
    recoveryAction = "reauthorize";
  } else if (selectedSource?.kind === "folder" && selectedSource.state === "active") {
    elements.emptyStateSymbol.textContent = "▤";
    elements.emptyStateTitle.textContent = `没有支持的${noun}`;
    elements.emptyStateCopy.textContent = "可在 Mac 上立即重扫当前文件夹，寻找支持的媒体并更新索引。";
    recoveryAction = "rescan";
  } else {
    elements.emptyStateTitle.textContent = `还没有可显示的${noun}`;
    elements.emptyStateCopy.textContent = "来源仍保留在原位置；可以等待扫描完成，或从来源菜单立即同步。";
  }

  const showsSourceRecovery = Boolean(selectedSource && recoveryAction);
  const showsPhotosPrivacySettings = Boolean(
    selectedSource?.kind === "photos"
      && ["authorizationRequired", "disabled"].includes(selectedSource.state)
  );
  const showsConditionRecovery = constrained && !noSources;
  elements.emptyStateActions.classList.toggle(
    "hidden",
    !noSources && !showsSourceRecovery && !showsConditionRecovery
  );
  elements.emptyClearAllConditionsButton.classList.toggle(
    "hidden",
    !showsConditionRecovery || conditionGroupCount < 2
  );
  elements.emptyClearSearchButton.classList.toggle(
    "hidden",
    !showsConditionRecovery || !hasSearch
  );
  elements.emptyClearTagFiltersButton.classList.toggle(
    "hidden",
    !showsConditionRecovery || !hasTagFilters
  );
  elements.emptyClearPropertyFiltersButton.classList.toggle(
    "hidden",
    !showsConditionRecovery || !hasPropertyFilters
  );
  for (const [button, isOnlyCondition] of [
    [elements.emptyClearSearchButton, hasSearch && conditionGroupCount === 1],
    [elements.emptyClearTagFiltersButton, hasTagFilters && conditionGroupCount === 1],
    [elements.emptyClearPropertyFiltersButton, hasPropertyFilters && conditionGroupCount === 1],
  ]) {
    button.classList.toggle("button-primary", isOnlyCondition);
  }
  elements.emptyConnectFolderButton.classList.toggle("hidden", !noSources);
  elements.emptyConnectPhotosButton.classList.toggle("hidden", !noSources);
  elements.emptyInstallPresetTagsButton.classList.toggle("hidden", !noSources || !noTags);
  elements.emptySourceRecoveryButton.classList.toggle("hidden", !showsSourceRecovery);
  elements.emptyOpenPhotosSettingsButton.classList.toggle(
    "hidden",
    !showsPhotosPrivacySettings
  );
  elements.emptyOpenSourceManagerButton.classList.toggle("hidden", !showsSourceRecovery);
  elements.emptySourceRecoveryButton.dataset.sourceAction = recoveryAction || "";
  elements.emptySourceRecoveryButton.dataset.sourceId = selectedSource?.id || "";
  elements.emptySourceRecoveryButton.textContent = recoveryAction
    ? sourceManagementActionLabel(recoveryAction, selectedSource, { emptyState: true })
    : "";
  elements.emptyOpenPhotosSettingsButton.dataset.sourceId = showsPhotosPrivacySettings
    ? selectedSource.id
    : "";
  elements.emptyConnectFolderButton.disabled = !state.online;
  elements.emptyConnectPhotosButton.disabled = !state.online;
  elements.emptyInstallPresetTagsButton.disabled = !state.online || state.installingPresetTags;
  elements.emptySourceRecoveryButton.disabled = !state.online || !showsSourceRecovery;
  elements.emptyOpenPhotosSettingsButton.disabled = !state.online
    || !showsPhotosPrivacySettings
    || sourceManagementHasActiveRequest();
  elements.emptyOpenSourceManagerButton.disabled = !state.online || !showsSourceRecovery;
}

function renderMediaKindTabs() {
  for (const button of elements.mediaKindTabs.querySelectorAll("[data-media-kind]")) {
    button.setAttribute(
      "aria-pressed",
      String(button.dataset.mediaKind === state.mediaKind)
    );
  }
  syncRovingSegmentedControl(elements.mediaKindTabs, "[data-media-kind]");
  renderMediaKindLabels();
  renderWorldMapGalleryScope();
}

function segmentedControlButtons(container, selector) {
  return [...container.querySelectorAll(selector)]
    .filter((button) => !button.disabled && !button.hidden
      && !button.classList.contains("hidden"));
}

function segmentedControlButtonIsSelected(button) {
  return button.getAttribute("aria-checked") === "true"
    || button.getAttribute("aria-pressed") === "true"
    || button.getAttribute("aria-selected") === "true";
}

function syncRovingSegmentedControl(container, selector) {
  const buttons = segmentedControlButtons(container, selector);
  const selected = buttons.find(segmentedControlButtonIsSelected) || buttons[0] || null;
  for (const button of container.querySelectorAll(selector)) {
    button.tabIndex = button === selected ? 0 : -1;
  }
}

function moveRovingSegmentedSelection(event, container, selector) {
  if (!["ArrowLeft", "ArrowRight", "ArrowUp", "ArrowDown", "Home", "End"].includes(
    event.key
  )) return;
  const currentButton = event.target.closest(selector);
  if (!currentButton || !container.contains(currentButton)) return;
  const buttons = segmentedControlButtons(container, selector);
  if (!buttons.length) return;
  event.preventDefault();
  event.stopPropagation();
  const current = Math.max(0, buttons.indexOf(currentButton));
  const backwards = event.key === "ArrowLeft" || event.key === "ArrowUp";
  const next = event.key === "Home" ? 0
    : event.key === "End" ? buttons.length - 1
      : (current + (backwards ? -1 : 1) + buttons.length) % buttons.length;
  for (const button of buttons) button.tabIndex = button === buttons[next] ? 0 : -1;
  buttons[next].focus({ preventScroll: true });
  buttons[next].click();
}

function syncSelectionModeControls() {
  elements.selectionModeButton.setAttribute("aria-pressed", String(state.selectionMode));
  const selectionModeTitle = state.selectionMode ? "完成选择" : "选择";
  elements.selectionModeButton.setAttribute("aria-label", selectionModeTitle);
  elements.selectionModeButton.title = selectionModeTitle;
  const selectionModeLabel = elements.selectionModeButton.querySelector(
    ".library-toolbar-label"
  );
  if (selectionModeLabel) {
    selectionModeLabel.textContent = state.selectionMode ? "完成" : "选择";
  }
  elements.batchBar.classList.toggle("hidden", !state.selectionMode);
}

function resetCompactSelectionToolScroll({ preserveFocusedAction = false } = {}) {
  if (!mobileSidebarLayoutQuery.matches || !state.selectionMode) return;
  if (preserveFocusedAction
    && elements.selectionToolActions.contains(document.activeElement)) return;
  elements.selectionToolActions.scrollLeft = 0;
}

function revealCompactSelectionToolAction(action) {
  if (!mobileSidebarLayoutQuery.matches
    || !state.selectionMode
    || !(action instanceof HTMLElement)) return;
  requestAnimationFrame(() => {
    const stripRect = elements.selectionToolActions.getBoundingClientRect();
    const actionRect = action.getBoundingClientRect();
    const leadingEdge = stripRect.left + 2;
    const trailingEdge = stripRect.right - 2;
    if (actionRect.left < leadingEdge) {
      elements.selectionToolActions.scrollLeft -= leadingEdge - actionRect.left;
    } else if (actionRect.right > trailingEdge) {
      elements.selectionToolActions.scrollLeft += actionRect.right - trailingEdge;
    }
  });
}

async function switchMediaKind(mediaKind) {
  if (!["image", "video"].includes(mediaKind) || mediaKind === state.mediaKind) return;
  stopAssetHoverVideo();
  closeLayoutMenu({ restoreFocus: false });
  clearTimeout(state.searchTimer);
  state.searchTimer = null;
  cancelPendingFilterApply();
  captureMediaSession();
  const saved = state.mediaSessions[mediaKind];
  state.mediaKind = mediaKind;
  state.filterDraft = null;
  state.selectionAggregates = [];

  if (saved) {
    state.assets = saved.assets.map((asset) => ({ ...asset }));
    state.nextCursor = saved.nextCursor;
    state.selectedSourceID = saved.selectedSourceID;
    state.libraryScope = saved.libraryScope || "all";
    state.worldMapGalleryScope = cloneWorldMapGalleryScope(saved.worldMapGalleryScope);
    state.folderScope = cloneFolderScope(saved.folderScope);
    state.folderNavigation.selectedSessionID = saved.folderSessionID || null;
    state.selectedAssetID = saved.selectedAssetID;
    state.selectedDetail = saved.selectedDetail;
    state.searchText = saved.searchText;
    state.sort = saved.sort;
    state.filters = cloneFilters(saved.filters);
    state.filters.mediaKind = mediaKind;
    state.selectionMode = saved.selectionMode;
    state.selectedAssetIDs = new Set(saved.selectedAssetIDs);
    state.selectionAnchorID = saved.selectionAnchorID;
    state.inspectorDismissed = Boolean(saved.inspectorDismissed);
  } else {
    state.assets = [];
    state.nextCursor = null;
    state.selectedSourceID = "";
    state.libraryScope = "all";
    state.worldMapGalleryScope = null;
    state.folderScope = null;
    state.folderNavigation.selectedSessionID = null;
    state.selectedAssetID = null;
    state.selectedDetail = null;
    state.searchText = "";
    state.sort = "fileNameAscending";
    state.filters = emptyFilters();
    state.filters.mediaKind = mediaKind;
    state.selectionMode = false;
    state.selectedAssetIDs.clear();
    state.selectionAnchorID = null;
    state.inspectorDismissed = false;
  }

  elements.searchInput.value = state.searchText;
  elements.clearSearchButton.classList.toggle("hidden", !state.searchText);
  renderSortControls();
  renderMediaKindTabs();
  renderSources();
  renderTagNavigation();
  syncFilterControlsFromState();
  updateLibraryTitle();
  syncSelectionModeControls();
  renderAssets();
  state.assetRenderedQuerySignature = assetQuerySignature();
  renderSelectionBar();
  if (!state.selectionMode && saved?.selectedDetail) {
    renderInspector(saved.selectedDetail);
  }
  requestAnimationFrame(() => {
    elements.libraryScroll.scrollTop = saved?.scrollTop || 0;
  });
  await loadAssets({
    preserveSelection: true,
    preserveUnchangedGrid: Boolean(saved),
    preserveLoadedWindow: Boolean(saved),
  });
  if (supportsLibrarySlimming()) await loadGalleryRemovals({ quiet: true });
  if (!state.selectionMode && state.selectedAssetID) {
    await loadInspector(state.selectedAssetID, {
      preserveExisting: Boolean(saved?.selectedDetail),
    });
  } else if (state.selectionMode && state.selectedAssetIDs.size) {
    scheduleSelectionAggregate();
  }
  captureMediaSession();
  await loadEmbeddingPreparation({ quiet: true });
  await loadSampleSuggestions({ quiet: true });
  await loadTagLibrarySuggestions({ quiet: true });
  await loadTrainingActivities({ quiet: true });
}

function formatDate(milliseconds) {
  if (!milliseconds) return "—";
  return new Intl.DateTimeFormat("zh-CN", {
    year: "numeric",
    month: "short",
    day: "numeric",
    hour: "2-digit",
    minute: "2-digit",
  }).format(new Date(milliseconds));
}

function formatDuration(milliseconds) {
  if (!Number.isFinite(milliseconds) || milliseconds <= 0) return "—";
  const totalSeconds = Math.round(milliseconds / 1000);
  const seconds = totalSeconds % 60;
  const totalMinutes = Math.floor(totalSeconds / 60);
  const minutes = totalMinutes % 60;
  const hours = Math.floor(totalMinutes / 60);
  if (hours > 0) {
    return `${hours}:${String(minutes).padStart(2, "0")}:${String(seconds).padStart(2, "0")}`;
  }
  return `${minutes}:${String(seconds).padStart(2, "0")}`;
}

function formatFileSize(bytes) {
  if (!Number.isFinite(bytes) || bytes < 0) return "—";
  const units = ["字节", "KB", "MB", "GB", "TB"];
  let value = bytes;
  let unitIndex = 0;
  while (value >= 1000 && unitIndex < units.length - 1) {
    value /= 1000;
    unitIndex += 1;
  }
  const maximumFractionDigits = unitIndex === 0 || value >= 10 ? 0 : 1;
  return `${new Intl.NumberFormat("zh-CN", { maximumFractionDigits }).format(value)} ${units[unitIndex]}`;
}

function availabilityText(value) {
  return {
    available: "可用",
    missing: "文件缺失",
    unreadable: "不可读取",
    unsupported: "格式不支持",
  }[value] || value;
}

function assetCardHelpDetail(asset) {
  const width = Number(asset.width);
  const height = Number(asset.height);
  return [
    `来源：${asset.sourceName || "—"}`,
    asset.relativePath ? `位置：${asset.relativePath}` : "",
    width > 0 && height > 0 ? `尺寸：${width} × ${height}` : "",
    asset.durationMs != null ? `时长：${formatDuration(asset.durationMs)}` : "",
    `格式：${asset.mediaType || "—"}`,
    asset.mediaCreatedAtMs != null ? `拍摄时间：${formatDate(asset.mediaCreatedAtMs)}` : "",
    asset.mediaModifiedAtMs != null ? `修改时间：${formatDate(asset.mediaModifiedAtMs)}` : "",
    `标签：已确认 ${asset.acceptedTagCount} · 已拒绝 ${asset.rejectedTagCount}`,
    `状态：${availabilityText(asset.availability)}`,
    "方向键移动 · Shift 扩展选择 · Space 打开单图",
  ].filter(Boolean).join("\n");
}

function sourceIcon(kind) {
  return kind === "photos" ? "▣" : "▤";
}

function sourceStateText(stateValue) {
  return {
    active: "",
    disabled: "已停用",
    unavailable: "离线",
    authorizationRequired: "需授权",
  }[stateValue] ?? stateValue;
}

function tagByID(tagID) {
  return state.tags.find((tag) => tag.id === tagID);
}

function activeTags() {
  return state.tags.filter((tag) => tag.state === "active");
}

function orderedByPreference(items, preferredIDs, identifier = (item) => item.id) {
  const byID = new Map(items.map((item) => [identifier(item), item]));
  const result = [];
  for (const id of preferredIDs || []) {
    const item = byID.get(id);
    if (!item) continue;
    result.push(item);
    byID.delete(id);
  }
  for (const item of items) {
    const id = identifier(item);
    if (!byID.has(id)) continue;
    result.push(item);
    byID.delete(id);
  }
  return result;
}

function orderedSources() {
  return orderedByPreference(state.sources, state.layout.sourceOrderIDs);
}

function tagOrderPreferenceKey(groupID) {
  return groupID || "__ungrouped__";
}

function orderedTagsInGroup(tags, groupID) {
  return orderedByPreference(
    tags,
    state.layout.tagOrderIDsByGroup[tagOrderPreferenceKey(groupID)] || [],
    (tag) => tag.tagID || tag.id
  );
}

function orderedActiveTags() {
  const tags = activeTags();
  const ordered = [];
  const seen = new Set();
  for (const group of orderedTagGroups()) {
    for (const tag of orderedTagsInGroup(
      tags.filter((item) => item.groupID === group.id),
      group.id
    )) {
      ordered.push(tag);
      seen.add(tag.id);
    }
  }
  for (const tag of orderedTagsInGroup(
    tags.filter((item) => !seen.has(item.id)),
    null
  )) {
    ordered.push(tag);
  }
  return ordered;
}

function moveIDBefore(ids, movingID, beforeID) {
  const result = ids.filter((id) => id !== movingID);
  const targetIndex = beforeID ? result.indexOf(beforeID) : -1;
  result.splice(targetIndex >= 0 ? targetIndex : result.length, 0, movingID);
  return result;
}

function moveIDByOffset(ids, movingID, offset) {
  const currentIndex = ids.indexOf(movingID);
  if (currentIndex < 0) return ids;
  const destination = Math.max(0, Math.min(ids.length - 1, currentIndex + offset));
  if (destination === currentIndex) return ids;
  const result = [...ids];
  result.splice(currentIndex, 1);
  result.splice(destination, 0, movingID);
  return result;
}

function orderedTagGroups() {
  return [...state.tagGroups].sort((left, right) => (
    left.sortOrder - right.sortOrder
      || left.displayName.localeCompare(right.displayName, "zh-CN")
  ));
}

function groupByID(groupID) {
  return state.tagGroups.find((group) => group.id === groupID);
}

function inspectorTagGroupSections(tags) {
  const knownGroups = orderedTagGroups();
  if (!knownGroups.length) {
    return tags.length ? [{ id: "all", displayName: "标签", tags }] : [];
  }
  const sections = knownGroups.map((group) => ({
    id: group.id,
    displayName: group.displayName,
    tags: orderedTagsInGroup(
      tags.filter((tag) => tagByID(tag.tagID || tag.id)?.groupID === group.id),
      group.id
    ),
  })).filter((section) => section.tags.length);
  const groupedTagIDs = new Set(sections.flatMap((section) => (
    section.tags.map((tag) => tag.tagID || tag.id)
  )));
  const ungrouped = orderedTagsInGroup(
    tags.filter((tag) => !groupedTagIDs.has(tag.tagID || tag.id)),
    null
  );
  if (ungrouped.length) sections.push({ id: "other", displayName: "其他", tags: ungrouped });
  return sections;
}

const inspectorTagNodeCaches = new WeakMap();

function inspectorTagNodeCache(container) {
  let cache = inspectorTagNodeCaches.get(container);
  if (!cache) {
    cache = { groups: new Map(), rows: new Map() };
    inspectorTagNodeCaches.set(container, cache);
  }
  return cache;
}

function setInspectorTagText(element, text) {
  if (element.textContent !== text) element.textContent = text;
}

function setInspectorTagAttribute(element, name, value) {
  if (element.getAttribute(name) !== value) element.setAttribute(name, value);
}

function setInspectorTagData(element, key, value) {
  if (element.dataset[key] !== value) element.dataset[key] = value;
}

function toggleInspectorTagClass(element, className, enabled) {
  if (element.classList.contains(className) !== enabled) {
    element.classList.toggle(className, enabled);
  }
}

function syncInspectorTagGroup(group, section) {
  if (!group) {
    group = document.createElement("section");
    group.className = "inspector-tag-group";
  }
  setInspectorTagData(group, "inspectorTagGroupId", section.id);
  if (groupByID(section.id)) {
    setInspectorTagData(group, "inspectorTagDropGroupId", section.id);
  } else if (group.hasAttribute("data-inspector-tag-drop-group-id")) {
    group.removeAttribute("data-inspector-tag-drop-group-id");
  }
  const collapsed = state.layout.collapsedTagGroupIDs.has(section.id);

  let toggle = group.querySelector(":scope > .inspector-tag-group-toggle");
  if (!toggle) {
    toggle = document.createElement("button");
    toggle.type = "button";
    toggle.className = "inspector-tag-group-toggle";
    group.prepend(toggle);
  }
  setInspectorTagData(toggle, "inspectorTagGroupToggle", section.id);
  setInspectorTagAttribute(toggle, "aria-expanded", String(!collapsed));
  setInspectorTagAttribute(
    toggle,
    "aria-keyshortcuts",
    "ArrowLeft ArrowRight ArrowUp ArrowDown PageUp PageDown Home End Shift+F10 ContextMenu"
  );
  const title = collapsed
    ? `展开“${section.displayName}”`
    : `折叠“${section.displayName}”`;
  if (toggle.title !== title) toggle.title = title;
  setInspectorTagData(toggle, "helpTitle", `标签分组 · ${section.displayName}`);
  setInspectorTagData(toggle, "helpKind", "tag");
  setInspectorTagData(toggle, "helpDetail", [
    collapsed
      ? `当前已折叠，点击展开 ${section.tags.length} 个标签。`
      : `当前已展开，点击暂时隐藏 ${section.tags.length} 个标签。`,
    "左/右折叠或展开；上/下、Page Up/Page Down 或 Home/End 在分组之间移动。",
    groupByID(section.id)?.isSystem === false
      ? "右键或 Shift-F10 可重命名或删除分组；删除只移动组内标签，不会归档标签。"
      : "这是系统分组，不能重命名或删除。",
  ].join("\n"));

  let chevron = toggle.querySelector(":scope > span:first-child");
  if (!chevron) {
    chevron = document.createElement("span");
    chevron.setAttribute("aria-hidden", "true");
    toggle.prepend(chevron);
  }
  setInspectorTagText(chevron, collapsed ? "›" : "⌄");
  let name = toggle.querySelector(":scope > strong");
  if (!name) {
    name = document.createElement("strong");
    toggle.append(name);
  }
  setInspectorTagText(name, section.displayName);
  let count = toggle.querySelector(":scope > .secondary");
  if (!count) {
    count = document.createElement("span");
    count.className = "secondary";
    toggle.append(count);
  }
  setInspectorTagText(count, String(section.tags.length));

  let rows = group.querySelector(":scope > .inspector-tag-group-rows");
  if (!rows) {
    rows = document.createElement("div");
    rows.className = "inspector-tag-group-rows";
    group.append(rows);
  }
  toggleInspectorTagClass(rows, "hidden", collapsed);
  return { group, rows };
}

function reconcileInspectorTagGroups(container, tags, syncTagRow) {
  const cache = inspectorTagNodeCache(container);
  const existingGroups = new Map(
    [...container.querySelectorAll(":scope > [data-inspector-tag-group-id]")]
      .map((group) => [group.dataset.inspectorTagGroupId, group])
  );
  const existingRows = new Map(
    [...container.querySelectorAll("[data-inspector-tag-row-id]")]
      .map((row) => [row.dataset.inspectorTagRowId, row])
  );
  const wantedGroups = [];
  const wantedRowLists = [];
  for (const section of inspectorTagGroupSections(tags)) {
    const synced = syncInspectorTagGroup(
      existingGroups.get(section.id) || cache.groups.get(section.id),
      section
    );
    cache.groups.set(section.id, synced.group);
    const wantedRows = section.tags.map((tag) => {
      const tagID = tag.tagID || tag.id;
      const row = syncTagRow(
        existingRows.get(tagID) || cache.rows.get(tagID),
        tag
      );
      setInspectorTagData(row, "inspectorTagRowId", tagID);
      cache.rows.set(tagID, row);
      return row;
    });
    for (const [index, row] of wantedRows.entries()) {
      if (synced.rows.children[index] !== row) {
        synced.rows.insertBefore(row, synced.rows.children[index] || null);
      }
    }
    wantedGroups.push(synced.group);
    wantedRowLists.push({ rows: synced.rows, wantedRows });
  }
  for (const [index, group] of wantedGroups.entries()) {
    if (container.children[index] !== group) {
      container.insertBefore(group, container.children[index] || null);
    }
  }
  for (const { rows, wantedRows } of wantedRowLists) {
    for (const row of [...rows.children]) {
      if (!wantedRows.includes(row)) row.remove();
    }
  }
  for (const group of [...container.children]) {
    if (!wantedGroups.includes(group)) group.remove();
  }
}

function toggleSharedTagGroupCollapsed(groupID) {
  if (state.layout.collapsedTagGroupIDs.has(groupID)) {
    state.layout.collapsedTagGroupIDs.delete(groupID);
  } else {
    state.layout.collapsedTagGroupIDs.add(groupID);
  }
}

function toggleInspectorTagGroup(groupID) {
  toggleSharedTagGroupCollapsed(groupID);
  persistWorkspacePreferences();
  renderTagNavigation();
  renderPlaceholderTagEditor();
  if (state.selectionMode && state.selectedAssetIDs.size) renderSelectionInspector();
  else if (state.selectedDetail) renderInspector(state.selectedDetail);
  if (state.review.mode === "queue" && reviewWorkspaceIsOpen()) renderReviewDetail();
}

function rememberInspectorTagFocus(surface, kind, id, action = null) {
  state.pendingInspectorTagFocus = { surface, kind, id, action };
}

function setupInspectorTagInteractions(
  container,
  surface,
  batch,
  { labelingEnabled = true, applyDecisionOverride = null } = {}
) {
  const applyDecision = (action, tagID, kind = "chip") => {
    if (!labelingEnabled) return;
    rememberInspectorTagFocus(surface, kind, tagID, action);
    if (applyDecisionOverride) applyDecisionOverride(action, tagID);
    else if (batch) applyBatchTagDecision(action, tagID);
    else mutateTag(tagID, action);
  };

  container.addEventListener("click", (event) => {
    if (performance.now() < state.sidebarDrag.suppressClickUntil) return;
    const groupToggle = event.target.closest("[data-inspector-tag-group-toggle]");
    if (groupToggle) {
      const groupID = groupToggle.dataset.inspectorTagGroupToggle;
      rememberInspectorTagFocus(surface, "group", groupID);
      toggleInspectorTagGroup(groupID);
      return;
    }
    const decisionButton = event.target.closest("[data-action][data-tag-id]");
    if (decisionButton) {
      applyDecision(decisionButton.dataset.action, decisionButton.dataset.tagId, "decision");
      return;
    }
    const chip = event.target.closest("[data-tag-chip-action][data-tag-id]");
    if (chip) {
      if (!labelingEnabled) chip.focus({ preventScroll: true });
      else applyDecision("accept", chip.dataset.tagId);
    }
  });

  container.addEventListener("contextmenu", (event) => {
    const groupToggle = event.target.closest("[data-inspector-tag-group-toggle]");
    const groupID = groupToggle?.dataset.inspectorTagGroupToggle;
    const group = groupByID(groupID);
    if (groupToggle && group && !group.isSystem) {
      event.preventDefault();
      rememberInspectorTagFocus(surface, "group", groupID);
      showTagGroupContextMenu(event.clientX, event.clientY, groupID, groupToggle);
      return;
    }
    const chip = event.target.closest("[data-tag-chip-action][data-tag-id]");
    if (!chip || chip.disabled) return;
    if (!labelingEnabled) {
      event.preventDefault();
      chip.focus({ preventScroll: true });
      return;
    }
    event.preventDefault();
    applyDecision("clear", chip.dataset.tagId);
  });

  container.addEventListener("keydown", (event) => {
    const groupToggle = event.target.closest("[data-inspector-tag-group-toggle]");
    if (groupToggle && (event.key === "ContextMenu" || (event.shiftKey && event.key === "F10"))) {
      const groupID = groupToggle.dataset.inspectorTagGroupToggle;
      const group = groupByID(groupID);
      if (group && !group.isSystem) {
        event.preventDefault();
        rememberInspectorTagFocus(surface, "group", groupID);
        const rect = groupToggle.getBoundingClientRect();
        showTagGroupContextMenu(
          rect.left + Math.min(28, rect.width),
          rect.top + Math.min(24, rect.height),
          groupID,
          groupToggle
        );
      }
      return;
    }
    if (handleTagGroupNavigationKeydown(event, {
      container,
      selector: "[data-inspector-tag-group-toggle]",
      toggleGroup: (toggle) => {
        const groupID = toggle.dataset.inspectorTagGroupToggle;
        rememberInspectorTagFocus(surface, "group", groupID);
        toggleInspectorTagGroup(groupID);
      },
    })) {
      return;
    }
    const chip = event.target.closest("[data-tag-chip-action][data-tag-id]");
    if (!chip || chip.disabled) return;
    if (event.altKey && ["ArrowUp", "ArrowDown", "ArrowLeft", "ArrowRight"].includes(event.key)) {
      event.preventDefault();
      if (event.key === "ArrowUp" || event.key === "ArrowDown") {
        reorderSidebarTagByOffset(
          chip.dataset.tagId,
          event.key === "ArrowDown" ? 1 : -1,
          surface
        );
      } else {
        moveSidebarTagToAdjacentGroup(
          chip.dataset.tagId,
          event.key === "ArrowRight" ? 1 : -1,
          surface
        );
      }
    } else if (!labelingEnabled) {
      return;
    } else if (event.key === "Delete" || event.key === "Backspace") {
      event.preventDefault();
      applyDecision("clear", chip.dataset.tagId);
    } else if (!event.metaKey && !event.ctrlKey && !event.altKey
      && event.key.toLocaleLowerCase("en-US") === "x") {
      event.preventDefault();
      applyDecision("reject", chip.dataset.tagId);
    }
  });

  container.addEventListener("dragstart", (event) => {
    const chip = event.target.closest(`[data-tag-reorder-surface="${surface}"]`);
    if (!chip?.draggable) return;
    state.sidebarDrag.tagID = chip.dataset.tagId;
    state.sidebarDrag.tagSurface = surface;
    container.dataset.activeTagDrag = chip.dataset.tagId;
    chip.classList.add("dragging");
    event.dataTransfer.effectAllowed = "move";
    event.dataTransfer.setData("application/x-imageall-tag", chip.dataset.tagId);
  }, true);
  container.addEventListener("dragover", (event) => {
    if (!state.sidebarDrag.tagID) return;
    const section = event.target.closest("[data-inspector-tag-drop-group-id]");
    if (!section) return;
    event.preventDefault();
    event.dataTransfer.dropEffect = "move";
    clearSidebarDropIndicators();
    const target = event.target.closest(`[data-tag-reorder-surface="${surface}"]`);
    if (target && target.dataset.tagId !== state.sidebarDrag.tagID) {
      const rect = target.getBoundingClientRect();
      const after = event.clientY > rect.top + rect.height / 2;
      target.classList.add(after ? "drop-after" : "drop-before");
      state.sidebarDrag.dropTarget = target;
    } else {
      section.classList.add("drag-over-group");
      state.sidebarDrag.dropTarget = section;
    }
  });
  container.addEventListener("drop", (event) => {
    const tagID = state.sidebarDrag.tagID;
    const section = event.target.closest("[data-inspector-tag-drop-group-id]");
    if (!tagID || !section) return;
    event.preventDefault();
    const target = event.target.closest(`[data-tag-reorder-surface="${surface}"]`);
    const dropTargetTagID = target?.dataset.tagId || null;
    let beforeTagID = null;
    if (target && target.dataset.tagId !== tagID) {
      if (target.classList.contains("drop-after")) {
        const siblings = [...section.querySelectorAll(
          `[data-tag-reorder-surface="${surface}"]`
        )];
        const targetIndex = siblings.indexOf(target);
        beforeTagID = siblings[targetIndex + 1]?.dataset.tagId || null;
      } else {
        beforeTagID = target.dataset.tagId;
      }
    }
    // Release the drag render lock before applying the optimistic order. This
    // lets the drop itself repaint immediately while still protecting the live
    // drag from an unrelated aggregate response.
    state.sidebarDrag.tagID = null;
    state.sidebarDrag.tagSurface = null;
    delete container.dataset.activeTagDrag;
    const targetGroupID = section.dataset.inspectorTagDropGroupId;
    // Let the native drop/dragend sequence finish while the dragged element is
    // still attached. Repainting synchronously here makes Chromium focus the
    // drop target after the logical dragged chip has already been detached.
    setTimeout(() => {
      void moveSidebarTag(tagID, targetGroupID, beforeTagID, surface);
    }, 0);
    setTimeout(() => {
      const active = document.activeElement;
      const browserFocusedDropTarget = dropTargetTagID
        && active?.dataset?.tagReorderSurface === surface
        && active?.dataset?.tagId === dropTargetTagID;
      if (active === document.body
        || active === document.documentElement
        || browserFocusedDropTarget) {
        focusTagOrderingSurface(tagID, surface);
      }
    }, 250);
    state.sidebarDrag.suppressClickUntil = performance.now() + 250;
    clearSidebarDropIndicators();
  });
  container.addEventListener("dragend", (event) => {
    const chip = event.target.closest(`[data-tag-reorder-surface="${surface}"]`);
    const tagID = chip?.dataset.tagId;
    chip?.classList.remove("dragging");
    state.sidebarDrag.tagID = null;
    state.sidebarDrag.tagSurface = null;
    delete container.dataset.activeTagDrag;
    state.sidebarDrag.suppressClickUntil = performance.now() + 250;
    clearSidebarDropIndicators();
    if (surface === "selection" && state.sidebarDrag.pendingSelectionRender) {
      renderSelectionInspector();
    }
    if (tagID) focusTagOrderingSurface(tagID, surface);
  });
}

function projectionFingerprint(value) {
  return JSON.stringify(value);
}

function setSelectOptions(select, tags, placeholder) {
  const previous = select.value;
  const existingOptions = new Map(
    [...select.options].map((option) => [option.value, option])
  );
  const wantedOptions = [];
  if (placeholder) {
    const option = existingOptions.get("") || document.createElement("option");
    option.value = "";
    if (option.textContent !== placeholder) option.textContent = placeholder;
    wantedOptions.push(option);
  }
  for (const tag of tags) {
    const option = existingOptions.get(tag.id) || document.createElement("option");
    option.value = tag.id;
    if (option.textContent !== tag.displayName) option.textContent = tag.displayName;
    wantedOptions.push(option);
  }
  reconcileStableChildren(select, wantedOptions);
  if ([...select.options].some((option) => option.value === previous)) {
    select.value = previous;
  }
}

function renderTagSelects() {
  const tags = orderedActiveTags();
  setSelectOptions(elements.filterTagSelect, tags, tags.length ? "选择标签" : "尚无活动标签");
  setSelectOptions(elements.batchTagSelect, tags, tags.length ? "批量标签…" : "尚无活动标签");
  setSelectOptions(elements.reviewTagSelect, tags, tags.length ? "选择审核标签" : "尚无活动标签");
  elements.filterTagSelect.disabled = tags.length === 0;
  elements.batchTagSelect.disabled = tags.length === 0 || state.tagMutating;
  elements.reviewTagSelect.disabled = tags.length === 0
    || state.review.loading
    || state.review.mutating;
  renderReviewWorkspaceTitle();
  renderTagNavigation();
  renderPlaceholderTagEditor();
  renderActiveFilterBar();
  renderTagManager();
  renderTagActionsMenu();
  renderCommandItems();
}

function quickIncludedTagID() {
  const included = state.filters.tagConditions.filter(
    (condition) => condition.decision === "accepted"
  );
  const hasOtherTagCondition = state.filters.tagConditions.some(
    (condition) => condition.decision !== "accepted"
  );
  return included.length === 1 && !hasOtherTagCondition ? included[0].tagID : null;
}

function toggleSidebarTagGroup(groupID) {
  toggleSharedTagGroupCollapsed(groupID);
  persistWorkspacePreferences();
  renderTagNavigation();
  renderPlaceholderTagEditor();
  if (state.selectionMode && state.selectedAssetIDs.size) renderSelectionInspector();
  else if (state.selectedDetail) renderInspector(state.selectedDetail);
  requestAnimationFrame(() => {
    elements.tagNavigation.querySelector(
      `[data-sidebar-tag-group-toggle="${CSS.escape(groupID)}"]`
    )?.focus({ preventScroll: true });
  });
}

function setSidebarTagText(element, text) {
  if (element.textContent !== text) element.textContent = text;
}

function setSidebarTagAttribute(element, name, value) {
  if (element.getAttribute(name) !== value) element.setAttribute(name, value);
}

function setSidebarTagData(element, key, value) {
  if (element.dataset[key] !== value) element.dataset[key] = value;
}

function toggleSidebarTagClass(element, className, enabled) {
  if (element.classList.contains(className) !== enabled) {
    element.classList.toggle(className, enabled);
  }
}

const sidebarTagNavigationSectionCache = new Map();
const sidebarTagNavigationChipCache = new Map();

function configureSidebarTagFilterState(button, tag, query) {
  const condition = state.filters.tagConditions.find((item) => item.tagID === tag.id);
  const included = condition?.decision === "accepted";
  const excluded = condition?.decision === "excluded";
  const stateLabel = excluded
    ? "已排除"
    : included
      ? (state.filters.tagMatchMode === "all" ? "交集筛选" : "并集筛选")
      : "未筛选";
  setSidebarTagData(
    button,
    "tagFilterState",
    excluded ? "excluded" : included ? "included" : "none"
  );
  toggleSidebarTagClass(button, "selected", included);
  toggleSidebarTagClass(button, "excluded", excluded);
  setSidebarTagAttribute(button, "aria-pressed", String(included || excluded));
  setSidebarTagAttribute(button, "aria-label", `${tag.displayName}，${stateLabel}`);
  setSidebarTagData(button, "helpTitle", tag.displayName);
  setSidebarTagData(button, "helpKind", "tag");
  setSidebarTagData(button, "helpDetail", [
    `当前：${stateLabel}。`,
    excluded
      ? "点击改为并集筛选；Command-Option-点击或 Command-Option-Return 取消排除。"
      : included
        ? (state.filters.tagMatchMode === "all"
          ? "点击取消；Command-点击或 Command-Return 保持交集，Command-Option-点击改为排除。"
          : "点击取消；Command-点击或 Command-Return 改为交集，Command-Option-点击改为排除。")
        : "点击加入并集；Command-点击或 Command-Return 加入交集，Command-Option-点击改为排除。",
    "方向键按当前换行位置移动，Page Up/Page Down 按侧栏可见页幅移动，Home/End 直达首尾。",
    "右键、触控长按、Context Menu 或 Shift-F10 可排序、移动分组、筛选、重命名或归档。",
    query
      ? "正在搜索标签；清除搜索后可拖动或用 Option + 方向键调整分组与顺序。"
      : "拖动可调整分组与顺序；Option + 左/右调整组内顺序，上/下移动到相邻分组。",
  ].join("\n"));
  const title = query
    ? "清除标签搜索后可拖放排序"
    : excluded
      ? "已从当前范围排除；⌘⌥点击取消排除；拖动可排序"
      : included
        ? `${stateLabel}；点击切换；⌘⌥点击排除；拖动可排序`
        : "点击并集筛选；⌘点击交集筛选；⌘⌥点击排除；拖动可排序";
  if (button.title !== title) button.title = title;
}

function sidebarTagNavigationSections(tags, knownGroups) {
  const sections = [];
  if (knownGroups.length) {
    for (const group of knownGroups) {
      const groupTags = orderedTagsInGroup(
        tags.filter((tag) => tag.groupID === group.id),
        group.id
      );
      if (groupTags.length) {
        sections.push({
          preferenceID: group.id,
          groupID: group.id,
          displayName: group.displayName,
          isSystem: Boolean(group.isSystem),
          allowsVerticalMove: true,
          tags: groupTags,
        });
      }
    }
    const orphanedTags = orderedTagsInGroup(
      tags.filter((tag) => !groupByID(tag.groupID)),
      null
    );
    if (orphanedTags.length) {
      sections.push({
        preferenceID: "__other__",
        groupID: "",
        displayName: "其他",
        isSystem: true,
        allowsVerticalMove: false,
        tags: orphanedTags,
      });
    }
  } else if (tags.length) {
    sections.push({
      preferenceID: "__all__",
      groupID: "",
      displayName: "标签",
      isSystem: true,
      allowsVerticalMove: true,
      tags: orderedTagsInGroup(tags, null),
    });
  }
  return sections;
}

function syncSidebarTagNavigationSection(section, descriptor, query) {
  if (!section) {
    section = document.createElement("section");
    section.className = "tag-navigation-group";
  }
  sidebarTagNavigationSectionCache.set(descriptor.preferenceID, section);
  setSidebarTagData(section, "tagDropGroupId", descriptor.groupID);
  setSidebarTagData(section, "sidebarTagGroupId", descriptor.preferenceID);
  const collapsed = !query
    && state.layout.collapsedTagGroupIDs.has(descriptor.preferenceID);

  let title = section.querySelector(":scope > .tag-navigation-group-title");
  if (!title) {
    title = document.createElement("button");
    title.type = "button";
    title.className = "tag-navigation-group-title";
    section.prepend(title);
  }
  setSidebarTagData(title, "sidebarTagGroupToggle", descriptor.preferenceID);
  setSidebarTagAttribute(title, "aria-expanded", String(!collapsed));
  setSidebarTagAttribute(
    title,
    "aria-keyshortcuts",
    "ArrowLeft ArrowRight ArrowUp ArrowDown PageUp PageDown Home End Shift+F10 ContextMenu"
  );
  const titleText = collapsed
    ? `展开“${descriptor.displayName}”`
    : `折叠“${descriptor.displayName}”`;
  if (title.title !== titleText) title.title = titleText;
  setSidebarTagData(title, "helpTitle", `标签分组 · ${descriptor.displayName}`);
  setSidebarTagData(title, "helpKind", "tag");
  setSidebarTagData(title, "helpDetail", [
    query
      ? `搜索中显示 ${descriptor.tags.length} 个匹配标签；清除搜索后恢复折叠状态。`
      : collapsed
        ? `当前已折叠，点击展开 ${descriptor.tags.length} 个标签。`
        : `当前已展开，点击暂时隐藏 ${descriptor.tags.length} 个标签。`,
    "左/右折叠或展开；上/下、Page Up/Page Down 或 Home/End 在分组之间移动。",
    descriptor.isSystem
      ? "这是系统分组，不能重命名或删除。"
      : "右键、Context Menu 或 Shift-F10 可重命名或删除分组；删除只移动组内标签。",
  ].join("\n"));

  let chevron = title.querySelector(":scope > .tag-navigation-group-chevron");
  if (!chevron) {
    chevron = document.createElement("span");
    chevron.className = "tag-navigation-group-chevron";
    chevron.setAttribute("aria-hidden", "true");
    title.prepend(chevron);
  }
  setSidebarTagText(chevron, collapsed ? "›" : "⌄");
  let name = title.querySelector(":scope > strong");
  if (!name) {
    name = document.createElement("strong");
    title.append(name);
  }
  setSidebarTagText(name, descriptor.displayName);
  let count = title.querySelector(":scope > .tag-navigation-group-count");
  if (!count) {
    count = document.createElement("span");
    count.className = "tag-navigation-group-count";
    title.append(count);
  }
  setSidebarTagText(count, String(descriptor.tags.length));

  let list = section.querySelector(":scope > .tag-navigation-group-tags");
  if (!list) {
    list = document.createElement("div");
    list.className = "tag-navigation-group-tags";
    section.append(list);
  }
  toggleSidebarTagClass(list, "hidden", collapsed);
  return { section, list };
}

function syncSidebarTagNavigationChip(button, tag, query, allowsVerticalMove) {
  if (!button) {
    button = document.createElement("button");
    button.type = "button";
    button.className = "sidebar-tag-chip";
  }
  sidebarTagNavigationChipCache.set(tag.id, button);
  setSidebarTagData(button, "quickTagId", tag.id);
  const draggable = !query && !state.tagManagementMutating;
  if (button.draggable !== draggable) button.draggable = draggable;
  setSidebarTagAttribute(
    button,
    "aria-keyshortcuts",
    allowsVerticalMove
      ? "ArrowLeft ArrowRight ArrowUp ArrowDown PageUp PageDown Home End Meta+Enter Meta+Alt+Enter Shift+F10 Alt+ArrowLeft Alt+ArrowRight Alt+ArrowUp Alt+ArrowDown"
      : "ArrowLeft ArrowRight ArrowUp ArrowDown PageUp PageDown Home End Meta+Enter Meta+Alt+Enter Shift+F10 Alt+ArrowLeft Alt+ArrowRight"
  );
  setSidebarTagText(button, tag.displayName);
  configureSidebarTagFilterState(button, tag, query);
  return button;
}

function visibleSidebarTagNavigationChips() {
  return [...elements.tagNavigation.querySelectorAll("[data-quick-tag-id]")]
    .filter((button) => !button.closest(".tag-navigation-group-tags.hidden"));
}

function syncSidebarTagRovingTabStop() {
  const chips = visibleSidebarTagNavigationChips();
  const chipIDs = new Set(chips.map((button) => button.dataset.quickTagId));
  const focusedID = document.activeElement?.closest?.("[data-quick-tag-id]")
    ?.dataset.quickTagId || null;
  const filteredID = state.filters.tagConditions.find(
    (condition) => chipIDs.has(condition.tagID)
  )?.tagID || null;
  const rovingID = chipIDs.has(state.sidebarTagNavigationID)
    ? state.sidebarTagNavigationID
    : chipIDs.has(focusedID)
      ? focusedID
      : filteredID || chips[0]?.dataset.quickTagId || null;
  state.sidebarTagNavigationID = rovingID;
  for (const button of elements.tagNavigation.querySelectorAll("[data-quick-tag-id]")) {
    button.tabIndex = button.dataset.quickTagId === rovingID ? 0 : -1;
  }
}

function setSidebarTagNavigationID(tagID, { focus = false } = {}) {
  const chips = visibleSidebarTagNavigationChips();
  const target = chips.find((button) => button.dataset.quickTagId === tagID);
  if (!target) return false;
  state.sidebarTagNavigationID = tagID;
  for (const button of elements.tagNavigation.querySelectorAll("[data-quick-tag-id]")) {
    button.tabIndex = button === target ? 0 : -1;
  }
  if (focus) {
    target.focus({ preventScroll: true });
    target.scrollIntoView({ block: "nearest", inline: "nearest" });
  }
  return true;
}

function sidebarTagDirectionalTarget(chips, currentIndex, direction) {
  const current = chips[currentIndex]?.getBoundingClientRect();
  if (!current) return currentIndex;
  const currentCenterX = current.left + current.width / 2;
  const candidates = chips.map((button, index) => ({
    index,
    rect: button.getBoundingClientRect(),
  })).filter(({ index, rect }) => index !== currentIndex && (
    direction < 0
      ? rect.bottom <= current.top + 1
      : rect.top >= current.bottom - 1
  ));
  if (!candidates.length) return currentIndex;
  candidates.sort((left, right) => {
    const leftGap = direction < 0
      ? current.top - left.rect.bottom
      : left.rect.top - current.bottom;
    const rightGap = direction < 0
      ? current.top - right.rect.bottom
      : right.rect.top - current.bottom;
    if (Math.abs(leftGap - rightGap) > 1) return leftGap - rightGap;
    const leftCenterX = left.rect.left + left.rect.width / 2;
    const rightCenterX = right.rect.left + right.rect.width / 2;
    return Math.abs(leftCenterX - currentCenterX)
      - Math.abs(rightCenterX - currentCenterX);
  });
  return candidates[0].index;
}

function sidebarTagPageTarget(chips, currentIndex, direction) {
  const current = chips[currentIndex]?.getBoundingClientRect();
  if (!current) return currentIndex;
  const currentCenterX = current.left + current.width / 2;
  const currentCenterY = current.top + current.height / 2;
  const pageDistance = Math.max(1, elements.sourceSidebar.clientHeight - current.height);
  const targetCenterY = currentCenterY + direction * pageDistance;
  const candidates = chips.map((button, index) => {
    const rect = button.getBoundingClientRect();
    return {
      index,
      centerX: rect.left + rect.width / 2,
      centerY: rect.top + rect.height / 2,
    };
  }).filter(({ index, centerY }) => index !== currentIndex && (
    direction < 0 ? centerY < currentCenterY : centerY > currentCenterY
  ));
  if (!candidates.length) return direction < 0 ? 0 : chips.length - 1;
  candidates.sort((left, right) => {
    const leftScore = Math.abs(left.centerY - targetCenterY) * 1000
      + Math.abs(left.centerX - currentCenterX);
    const rightScore = Math.abs(right.centerY - targetCenterY) * 1000
      + Math.abs(right.centerX - currentCenterX);
    return leftScore - rightScore;
  });
  return candidates[0].index;
}

function moveSidebarTagNavigation(event) {
  if (event.altKey || event.ctrlKey || event.metaKey) return false;
  const chip = event.target.closest("[data-quick-tag-id]");
  const navigationKeys = [
    "ArrowLeft", "ArrowRight", "ArrowUp", "ArrowDown",
    "PageUp", "PageDown", "Home", "End",
  ];
  if (!chip || !navigationKeys.includes(event.key)) return false;
  const chips = visibleSidebarTagNavigationChips();
  const currentIndex = chips.indexOf(chip);
  if (currentIndex < 0 || !chips.length) return false;
  let targetIndex;
  if (event.key === "Home") targetIndex = 0;
  else if (event.key === "End") targetIndex = chips.length - 1;
  else if (event.key === "ArrowLeft") targetIndex = Math.max(0, currentIndex - 1);
  else if (event.key === "ArrowRight") {
    targetIndex = Math.min(chips.length - 1, currentIndex + 1);
  } else if (event.key === "ArrowUp" || event.key === "ArrowDown") {
    targetIndex = sidebarTagDirectionalTarget(
      chips,
      currentIndex,
      event.key === "ArrowUp" ? -1 : 1
    );
  } else {
    targetIndex = sidebarTagPageTarget(
      chips,
      currentIndex,
      event.key === "PageUp" ? -1 : 1
    );
  }
  event.preventDefault();
  event.stopPropagation();
  return setSidebarTagNavigationID(
    chips[targetIndex]?.dataset.quickTagId,
    { focus: true }
  );
}

function renderTagNavigation() {
  const query = elements.tagNavigationSearch.value.trim().toLocaleLowerCase("zh-CN");
  const allActiveTags = activeTags();
  const tags = allActiveTags.filter((tag) => (
    !query || tag.displayName.toLocaleLowerCase("zh-CN").includes(query)
  ));
  elements.tagNavigationEmpty.classList.toggle("hidden", tags.length > 0);
  elements.tagNavigationEmptyText.textContent = allActiveTags.length
    ? "没有匹配的标签"
    : "尚未添加标签";
  const offersPresets = allActiveTags.length === 0 && !query;
  elements.sidebarInstallPresetTagsButton.classList.toggle("hidden", !offersPresets);
  elements.sidebarInstallPresetTagsButton.disabled = !state.online || state.installingPresetTags;

  const descriptors = sidebarTagNavigationSections(tags, orderedTagGroups());
  const existingSections = new Map(
    [...elements.tagNavigation.querySelectorAll(":scope > [data-sidebar-tag-group-id]")]
      .map((section) => [section.dataset.sidebarTagGroupId, section])
  );
  const existingChips = new Map(
    [...elements.tagNavigation.querySelectorAll("[data-quick-tag-id]")]
      .map((button) => [button.dataset.quickTagId, button])
  );
  const wantedSections = [];
  const wantedLists = [];
  for (const descriptor of descriptors) {
    const synced = syncSidebarTagNavigationSection(
      existingSections.get(descriptor.preferenceID)
        || sidebarTagNavigationSectionCache.get(descriptor.preferenceID),
      descriptor,
      query
    );
    const wantedChips = descriptor.tags.map((tag) => (
      syncSidebarTagNavigationChip(
        existingChips.get(tag.id) || sidebarTagNavigationChipCache.get(tag.id),
        tag,
        query,
        descriptor.allowsVerticalMove
      )
    ));
    for (const [index, button] of wantedChips.entries()) {
      if (synced.list.children[index] !== button) {
        synced.list.insertBefore(button, synced.list.children[index] || null);
      }
    }
    wantedLists.push({ list: synced.list, buttons: wantedChips });
    wantedSections.push(synced.section);
  }
  for (const [index, section] of wantedSections.entries()) {
    if (elements.tagNavigation.children[index] !== section) {
      elements.tagNavigation.insertBefore(
        section,
        elements.tagNavigation.children[index] || null
      );
    }
  }
  for (const { list, buttons } of wantedLists) {
    for (const button of [...list.children]) {
      if (!buttons.includes(button)) button.remove();
    }
  }
  for (const section of [...elements.tagNavigation.children]) {
    if (!wantedSections.includes(section)) section.remove();
  }
  syncSidebarTagRovingTabStop();
  elements.untaggedNavigationButton.classList.toggle(
    "selected",
    state.libraryScope === "all" && state.filters.tagPresence === "untagged"
  );
}

async function applyQuickTagFilter(tagID) {
  leaveIntegratedReviewForLibrary();
  leaveIntegratedGalleryOverviewForLibrary();
  leaveIntegratedWorldMapForLibrary();
  leaveIntegratedTrainingForLibrary();
  leaveIntegratedSlimmingForLibrary();
  const alreadySelected = quickIncludedTagID() === tagID
    && state.filters.tagPresence === "any";
  state.filters.tagConditions = alreadySelected
    ? []
    : [{ tagID, decision: "accepted" }];
  state.filters.tagPresence = "any";
  state.libraryScope = "all";
  state.worldMapGalleryScope = null;
  state.filters.tagMatchMode = "all";
  state.filterDraft = null;
  renderSources();
  renderTagNavigation();
  syncFilterControlsFromState();
  await loadAssets();
}

async function filterToSingleSidebarTag(tagID) {
  leaveIntegratedReviewForLibrary();
  leaveIntegratedGalleryOverviewForLibrary();
  leaveIntegratedWorldMapForLibrary();
  leaveIntegratedTrainingForLibrary();
  leaveIntegratedSlimmingForLibrary();
  state.filters.tagConditions = [{ tagID, decision: "accepted" }];
  state.filters.tagPresence = "any";
  state.libraryScope = "all";
  state.worldMapGalleryScope = null;
  state.filters.tagMatchMode = "all";
  state.filterDraft = null;
  renderSources();
  renderTagNavigation();
  syncFilterControlsFromState();
  await loadAssets();
  focusSidebarTag(tagID);
}

async function toggleSidebarTagFilter(tagID, { matchMode = "any", excluded = false } = {}) {
  leaveIntegratedReviewForLibrary();
  leaveIntegratedGalleryOverviewForLibrary();
  leaveIntegratedWorldMapForLibrary();
  leaveIntegratedTrainingForLibrary();
  leaveIntegratedSlimmingForLibrary();
  const current = state.filters.tagConditions.find((item) => item.tagID === tagID);
  const togglesOff = excluded
    ? current?.decision === "excluded"
    : current?.decision === "accepted";
  state.filters.tagConditions = state.filters.tagConditions.filter(
    (condition) => condition.tagID !== tagID
  );
  if (!togglesOff) {
    state.filters.tagConditions.push({
      tagID,
      decision: excluded ? "excluded" : "accepted",
    });
    state.filters.tagPresence = "any";
    if (!excluded) state.filters.tagMatchMode = matchMode;
  }
  state.libraryScope = "all";
  state.worldMapGalleryScope = null;
  state.filterDraft = null;
  renderSources();
  renderTagNavigation();
  syncFilterControlsFromState();
  await loadAssets();
  focusSidebarTag(tagID);
}

async function applyUntaggedFilter() {
  leaveIntegratedReviewForLibrary();
  leaveIntegratedGalleryOverviewForLibrary();
  leaveIntegratedWorldMapForLibrary();
  leaveIntegratedTrainingForLibrary();
  leaveIntegratedSlimmingForLibrary();
  const clearing = state.libraryScope === "all"
    && state.filters.tagPresence === "untagged";
  state.libraryScope = "all";
  state.worldMapGalleryScope = null;
  state.filters.tagPresence = clearing ? "any" : "untagged";
  state.filters.tagConditions = [];
  state.filterDraft = null;
  renderSources();
  renderTagNavigation();
  syncFilterControlsFromState();
  await loadAssets();
}

async function applyFavoritesFilter() {
  if (!supportsFavorites()) {
    toast("请先更新并重启 Mac Host 后再使用红心收藏");
    return;
  }
  leaveIntegratedReviewForLibrary();
  leaveIntegratedGalleryOverviewForLibrary();
  leaveIntegratedWorldMapForLibrary();
  leaveIntegratedTrainingForLibrary();
  leaveIntegratedSlimmingForLibrary();
  if (state.selectionMode) setSelectionMode(false);
  state.libraryScope = "favorites";
  state.worldMapGalleryScope = null;
  state.folderScope = null;
  state.folderNavigation.selectedSessionID = null;
  state.selectedSourceID = "";
  state.filters.tagPresence = "any";
  state.filters.tagConditions = [];
  state.filterDraft = null;
  state.selectedAssetID = null;
  state.selectedDetail = null;
  state.inspectorDismissed = false;
  elements.inspector.classList.remove("open");
  renderInspectorSurface();
  renderSources();
  renderTagNavigation();
  syncFilterControlsFromState();
  updateLibraryTitle();
  closeMobileSidebar({ restoreFocus: false });
  await loadAssets();
}

function renderTagManager() {
  const previousTagID = elements.tagManagerTagSelect.value;
  const previousGroupID = elements.tagManagerGroupSelect.value;
  setSelectOptions(
    elements.tagManagerTagSelect,
    orderedActiveTags(),
    activeTags().length ? null : "尚无活动标签"
  );
  setSelectOptions(
    elements.tagManagerTagGroupSelect,
    orderedTagGroups(),
    state.tagGroups.length ? null : "尚无标签分组"
  );
  setSelectOptions(
    elements.tagManagerGroupSelect,
    orderedTagGroups(),
    state.tagGroups.length ? null : "尚无标签分组"
  );
  if (previousTagID && tagByID(previousTagID)) {
    elements.tagManagerTagSelect.value = previousTagID;
  }
  if (previousGroupID && groupByID(previousGroupID)) {
    elements.tagManagerGroupSelect.value = previousGroupID;
  }
  syncManagedTagFields();
  syncManagedGroupFields();
  elements.installPresetTagsButton.disabled = state.installingPresetTags
    || state.tagManagementMutating
    || !state.online;
  elements.installPresetTagsButton.textContent = state.installingPresetTags
    ? "正在添加…"
    : "添加常用标签";
  renderTagManagerNotice();
}

function syncManagedTagFields({ updateValues = true } = {}) {
  const tag = tagByID(elements.tagManagerTagSelect.value);
  if (updateValues) {
    elements.tagManagerTagName.value = tag?.displayName || "";
    elements.tagManagerTagGroupSelect.value = tag?.groupID || "";
  }
  const disabled = !tag || state.tagManagementMutating;
  elements.tagManagerTagName.disabled = disabled;
  elements.tagManagerTagGroupSelect.disabled = disabled;
  elements.renameManagedTagButton.disabled = disabled || !state.online;
  elements.moveManagedTagButton.disabled = disabled || !state.online;
  elements.archiveManagedTagButton.disabled = disabled || !state.online;
}

function syncManagedGroupFields({ updateValues = true } = {}) {
  const group = groupByID(elements.tagManagerGroupSelect.value);
  if (updateValues) elements.tagManagerGroupName.value = group?.displayName || "";
  const protectedGroup = !group || group.isSystem;
  elements.renameTagGroupButton.disabled = protectedGroup
    || state.tagManagementMutating
    || !state.online;
  elements.deleteTagGroupButton.disabled = protectedGroup
    || state.tagManagementMutating
    || !state.online;
  elements.createTagGroupButton.disabled = state.tagManagementMutating || !state.online;
}

const TAG_MANAGER_HISTORY_FOCUS_IDS = new Set([
  "closeTagManagerButton",
  "tagManagerTagSelect",
  "tagManagerTagName",
  "tagManagerTagGroupSelect",
  "renameManagedTagButton",
  "moveManagedTagButton",
  "archiveManagedTagButton",
  "installPresetTagsButton",
  "tagManagerGroupSelect",
  "tagManagerGroupName",
  "createTagGroupButton",
  "renameTagGroupButton",
  "deleteTagGroupButton",
]);
const TAG_MANAGER_HISTORY_RETURN_SURFACES = new Set([
  "selection",
  "single",
  "review",
  "placeholder",
  "sidebar",
]);

function normalizedTagManagerHistoryFocusID(value, mode = state.tagManagerMode) {
  if (typeof value === "string" && TAG_MANAGER_HISTORY_FOCUS_IDS.has(value)) return value;
  return mode === "newGroup" ? "tagManagerGroupName" : "tagManagerTagSelect";
}

function captureTagManagerHistoryFocus() {
  if (!elements.tagManagerDialog.open) return;
  const active = document.activeElement;
  if (!(active instanceof HTMLElement)
    || !elements.tagManagerDialog.contains(active)
    || !TAG_MANAGER_HISTORY_FOCUS_IDS.has(active.id)) return;
  state.tagManagerFocusID = active.id;
  if (active instanceof HTMLInputElement) {
    state.tagManagerSelectionStart = Math.max(0, active.selectionStart || 0);
    state.tagManagerSelectionEnd = Math.max(
      state.tagManagerSelectionStart,
      active.selectionEnd || state.tagManagerSelectionStart
    );
  } else {
    state.tagManagerSelectionStart = 0;
    state.tagManagerSelectionEnd = 0;
  }
}

function currentTagManagerHistoryContext() {
  captureTagManagerHistoryFocus();
  if (elements.tagManagerDialog.open) {
    state.tagManagerScrollTop = elements.tagManagerShell.scrollTop;
  }
  return {
    tagManagerTagID: galleryHistoryIdentifier(elements.tagManagerTagSelect.value),
    tagManagerTargetGroupID:
      galleryHistoryIdentifier(elements.tagManagerTagGroupSelect.value),
    tagManagerGroupID: galleryHistoryIdentifier(elements.tagManagerGroupSelect.value),
    tagManagerReturnTagID:
      galleryHistoryIdentifier(state.tagManagerReturnFocus?.tagID),
    tagManagerReturnGroupID:
      galleryHistoryIdentifier(state.tagManagerReturnFocus?.groupID),
    tagManagerReturnSurface: TAG_MANAGER_HISTORY_RETURN_SURFACES.has(
      state.tagManagerReturnFocus?.surface
    )
      ? state.tagManagerReturnFocus.surface
      : null,
    tagManagerMode: state.tagManagerMode === "newGroup" ? "newGroup" : "manage",
    tagManagerFocusID: normalizedTagManagerHistoryFocusID(state.tagManagerFocusID),
    tagManagerSelectionStart: workspaceHistoryFiniteNumber(
      state.tagManagerSelectionStart,
      0,
      80
    ),
    tagManagerSelectionEnd: workspaceHistoryFiniteNumber(
      state.tagManagerSelectionEnd,
      0,
      80
    ),
    tagManagerScrollTop: workspaceHistoryScrollTop(state.tagManagerScrollTop),
  };
}

function renderTagManagerNotice() {
  const privacy = "未提交的标签或分组名称不会保存到浏览器历史。";
  elements.tagManagerNotice.textContent = state.tagManagerNotice
    ? `${state.tagManagerNotice} ${privacy}`
    : privacy;
  elements.tagManagerNotice.classList.remove("hidden");
}

function applyTagManagerHistoryContext(context = {}) {
  const activeTagIDs = new Set(activeTags().map((tag) => tag.id));
  const activeGroupIDs = new Set(orderedTagGroups().map((group) => group.id));
  const savedTagID = galleryHistoryIdentifier(context.tagManagerTagID);
  const savedTargetGroupID = galleryHistoryIdentifier(context.tagManagerTargetGroupID);
  const savedGroupID = galleryHistoryIdentifier(context.tagManagerGroupID);
  const returnTagID = galleryHistoryIdentifier(context.tagManagerReturnTagID);
  const returnGroupID = galleryHistoryIdentifier(context.tagManagerReturnGroupID);
  const returnSurface = TAG_MANAGER_HISTORY_RETURN_SURFACES.has(
    context.tagManagerReturnSurface
  )
    ? context.tagManagerReturnSurface
    : null;
  const notes = [];

  if (savedTagID && activeTagIDs.has(savedTagID)) {
    elements.tagManagerTagSelect.value = savedTagID;
  } else if (savedTagID) {
    notes.push("刷新前选择的标签当前不可用，已切换到可用标签。");
  }
  syncManagedTagFields();
  if (savedTargetGroupID && activeGroupIDs.has(savedTargetGroupID)) {
    elements.tagManagerTagGroupSelect.value = savedTargetGroupID;
  } else if (savedTargetGroupID) {
    notes.push("刷新前的移动目标当前不可用，已恢复为标签所在分组。");
  }
  if (savedGroupID && activeGroupIDs.has(savedGroupID)) {
    elements.tagManagerGroupSelect.value = savedGroupID;
  } else if (savedGroupID) {
    notes.push("刷新前选择的分组当前不可用，已切换到可用分组。");
  }
  if (returnTagID && !activeTagIDs.has(returnTagID)) {
    notes.push("刷新前的返回标签当前不可用，关闭后将回到标签入口。");
  }
  if (returnGroupID && !activeGroupIDs.has(returnGroupID)) {
    notes.push("刷新前的返回分组当前不可用，关闭后将回到标签入口。");
  }

  state.tagManagerMode = context.tagManagerMode === "newGroup" ? "newGroup" : "manage";
  state.tagManagerReturnFocus = {
    element: null,
    tagID: returnTagID && activeTagIDs.has(returnTagID) ? returnTagID : null,
    groupID: returnGroupID && activeGroupIDs.has(returnGroupID) ? returnGroupID : null,
    surface: returnSurface,
  };
  syncManagedGroupFields();
  if (state.tagManagerMode === "newGroup") elements.tagManagerGroupName.value = "";
  state.tagManagerFocusID = normalizedTagManagerHistoryFocusID(
    context.tagManagerFocusID,
    state.tagManagerMode
  );
  state.tagManagerSelectionStart = workspaceHistoryFiniteNumber(
    Math.floor(workspaceHistoryFiniteNumber(context.tagManagerSelectionStart, 0, 80)),
    0,
    80
  );
  state.tagManagerSelectionEnd = Math.max(
    state.tagManagerSelectionStart,
    Math.floor(workspaceHistoryFiniteNumber(context.tagManagerSelectionEnd, 0, 80))
  );
  state.tagManagerScrollTop = workspaceHistoryScrollTop(context.tagManagerScrollTop);
  state.tagManagerNotice = notes.join(" ");
  renderTagManagerNotice();
}

async function restoreTagManagerLayoutFromHistory() {
  await waitForWorkspaceLayout();
  elements.tagManagerShell.scrollTop = Math.min(
    state.tagManagerScrollTop,
    Math.max(0, elements.tagManagerShell.scrollHeight - elements.tagManagerShell.clientHeight)
  );
  let target = document.getElementById(
    normalizedTagManagerHistoryFocusID(state.tagManagerFocusID, state.tagManagerMode)
  );
  if (!(target instanceof HTMLElement)
    || target.disabled
    || !elements.tagManagerDialog.contains(target)) {
    target = state.tagManagerMode === "newGroup"
      ? elements.tagManagerGroupName
      : (elements.tagManagerTagSelect.disabled
        ? elements.closeTagManagerButton
        : elements.tagManagerTagSelect);
  }
  target.focus({ preventScroll: true });
  state.tagManagerFocusID = target.id;
  if (target instanceof HTMLInputElement) {
    const length = target.value.length;
    const start = Math.min(length, Math.max(0, state.tagManagerSelectionStart));
    const end = Math.min(length, Math.max(start, state.tagManagerSelectionEnd));
    target.setSelectionRange(start, end);
  }
}

function tagManagerBaseLevelFromHistory(context = {}) {
  return ["sidebar", "inspector", "lightbox"].includes(context.tagManagerBaseLevel)
    ? context.tagManagerBaseLevel
    : "workspace";
}

function replaceTagManagerHistoryWithBase(baseLevel) {
  if (!state.workspaceNavigation.initialized
    || elements.appView.classList.contains("hidden")) return;
  const current = activeWorkspaceHistoryEntry();
  const route = visibleWorkspaceRoute();
  if (current?.route !== route || current.navigationLevel !== "tagManager") return;
  const context = currentWorkspaceHistoryContext(route);
  if (context && typeof context === "object") delete context.tagManagerBaseLevel;
  const navigationLevel = visibleWorkspaceNavigationBaseLevel(route, baseLevel);
  history.replaceState({
    ...(history.state || {}),
    [WORKSPACE_HISTORY_KEY]: workspaceHistoryEntry(route, context, navigationLevel),
  }, "", location.href);
}

function presentTagManager({
  returnFocus,
  historyMode = "pushTagManager",
  baseLevel = null,
  focusTarget = null,
  focus = true,
  render = true,
  historyContext = null,
} = {}) {
  if (elements.tagManagerDialog.open) {
    if (focus) restoreOverlayFocus(focusTarget || elements.tagManagerTagSelect);
    return;
  }
  if (returnFocus !== undefined) state.tagManagerReturnFocus = returnFocus;
  const current = activeWorkspaceHistoryEntry();
  state.tagManagerBaseLevel = baseLevel
    || workspaceNavigationBaseLevel(
      current?.navigationLevel || "workspace",
      current?.context || {}
    );
  if (render) {
    elements.tagManagerError.textContent = "";
    renderTagManager();
    if (historyContext) applyTagManagerHistoryContext(historyContext);
  }
  const target = focusTarget
    || document.getElementById(state.tagManagerFocusID)
    || elements.tagManagerTagSelect;
  const intendedSelectionStart = state.tagManagerSelectionStart;
  const intendedSelectionEnd = state.tagManagerSelectionEnd;
  elements.tagManagerDialog.showModal();
  if (historyMode !== "none") {
    const route = visibleWorkspaceRoute();
    recordWorkspaceHistory(route, currentWorkspaceHistoryContext(route), historyMode);
  }
  state.tagManagerFocusID = target?.id || "tagManagerTagSelect";
  state.tagManagerSelectionStart = intendedSelectionStart;
  state.tagManagerSelectionEnd = intendedSelectionEnd;
  state.tagManagerRestorable = true;
  if (focus) restoreOverlayFocus(target);
}

function openTagManagerForNewGroup(returnFocus = elements.tagManagerButton) {
  state.tagManagerReturnFocus = { element: returnFocus };
  state.tagManagerMode = "newGroup";
  state.tagManagerNotice = "";
  elements.tagManagerError.textContent = "";
  renderTagManager();
  elements.tagManagerGroupName.value = "";
  presentTagManager({
    returnFocus: state.tagManagerReturnFocus,
    focusTarget: elements.tagManagerGroupName,
    render: false,
  });
}

function openTagManagerFromTagActions(returnFocus = elements.tagManagerButton) {
  state.tagManagerReturnFocus = { element: returnFocus };
  state.tagManagerMode = "manage";
  state.tagManagerNotice = "";
  elements.tagManagerError.textContent = "";
  renderTagManager();
  presentTagManager({
    returnFocus: state.tagManagerReturnFocus,
    focusTarget: elements.tagManagerTagSelect,
    render: false,
  });
}

function tagReturnFocusDescriptor(element, { tagID = null, groupID = null } = {}) {
  let surface = null;
  if (element?.closest?.("#selectionInspectorTags")) surface = "selection";
  else if (element?.closest?.("#inspectorTags")) surface = "single";
  else if (element?.closest?.("#reviewTags")) surface = "review";
  else if (element?.closest?.("#inspectorPlaceholderTags")) surface = "placeholder";
  else if (element?.closest?.("#tagNavigation")) surface = "sidebar";
  return { element, tagID, groupID, surface };
}

function resolveTagReturnFocusTarget(pending) {
  if (!pending) return null;
  if (pending.element?.isConnected) return pending.element;
  const container = pending.surface === "selection"
    ? elements.selectionInspectorTags
    : pending.surface === "single"
      ? elements.inspectorTags
      : pending.surface === "review"
        ? elements.reviewTags
        : pending.surface === "placeholder"
          ? elements.inspectorPlaceholderTags
          : elements.tagNavigation;
  if (pending.tagID) {
    const selector = pending.surface === "sidebar"
      ? `[data-quick-tag-id="${CSS.escape(pending.tagID)}"]`
      : `[data-tag-chip-action][data-tag-id="${CSS.escape(pending.tagID)}"]`;
    const tag = container?.querySelector(selector);
    if (tag) return tag;
  }
  if (pending.groupID) {
    const selector = pending.surface === "sidebar"
      ? `[data-sidebar-tag-group-toggle="${CSS.escape(pending.groupID)}"]`
      : `[data-inspector-tag-group-toggle="${CSS.escape(pending.groupID)}"]`;
    const group = container?.querySelector(selector);
    if (group) return group;
  }
  if (pending.tagID) {
    const sidebarTag = elements.tagNavigation.querySelector(
      `[data-quick-tag-id="${CSS.escape(pending.tagID)}"]`
    );
    if (sidebarTag) return sidebarTag;
  }
  if (pending.groupID) {
    const sidebarGroup = elements.tagNavigation.querySelector(
      `[data-sidebar-tag-group-toggle="${CSS.escape(pending.groupID)}"]`
    );
    if (sidebarGroup) return sidebarGroup;
  }
  return elements.tagManagerButton;
}

function openTagManagerForTag(tagID, returnFocus = null) {
  const tag = tagByID(tagID);
  if (!tag) return;
  state.tagManagerReturnFocus = tagReturnFocusDescriptor(returnFocus, {
    tagID,
    groupID: tag.groupID,
  });
  state.tagManagerMode = "manage";
  state.tagManagerNotice = "";
  elements.tagManagerError.textContent = "";
  renderTagManager();
  elements.tagManagerTagSelect.value = tagID;
  syncManagedTagFields();
  presentTagManager({
    returnFocus: state.tagManagerReturnFocus,
    focusTarget: elements.tagManagerTagName,
    render: false,
  });
  elements.tagManagerTagName.select();
}

function openTagManagerForGroup(groupID, returnFocus = null) {
  const group = groupByID(groupID);
  if (!group) return;
  state.tagManagerReturnFocus = tagReturnFocusDescriptor(returnFocus, { groupID });
  state.tagManagerMode = "manage";
  state.tagManagerNotice = "";
  elements.tagManagerError.textContent = "";
  renderTagManager();
  elements.tagManagerGroupSelect.value = groupID;
  syncManagedGroupFields();
  presentTagManager({
    returnFocus: state.tagManagerReturnFocus,
    focusTarget: elements.tagManagerGroupName,
    render: false,
  });
  elements.tagManagerGroupName.select();
}

function restoreTagManagerReturnFocus(
  pending = state.tagManagerReturnFocus,
  { clear = true } = {}
) {
  if (clear) state.tagManagerReturnFocus = null;
  if (!pending) return;
  requestAnimationFrame(() => {
    resolveTagReturnFocusTarget(pending)?.focus({ preventScroll: true });
  });
}

function closeTagManager({
  restoreFocus = true,
  checkpoint = true,
  preserveState = false,
} = {}) {
  if (!elements.tagManagerDialog.open) return;
  if (elements.confirmDialog.open && state.confirmationBaseLevel === "tagManager") {
    closeConfirmation({ restoreFocus: false, checkpoint: false, preserveState: false });
  }
  captureTagManagerHistoryFocus();
  state.tagManagerScrollTop = elements.tagManagerShell.scrollTop;
  const baseLevel = state.tagManagerBaseLevel;
  const pendingFocus = state.tagManagerReturnFocus;
  elements.tagManagerDialog.close();
  if (restoreFocus) {
    restoreTagManagerReturnFocus(pendingFocus, { clear: !preserveState });
  } else if (!preserveState) {
    state.tagManagerReturnFocus = null;
  }
  if (checkpoint) replaceTagManagerHistoryWithBase(baseLevel);
  state.tagManagerBaseLevel = preserveState ? baseLevel : "workspace";
  if (!preserveState) {
    state.tagManagerRestorable = false;
    state.tagManagerFocusID = "tagManagerTagSelect";
    state.tagManagerMode = "manage";
    state.tagManagerScrollTop = 0;
    state.tagManagerSelectionStart = 0;
    state.tagManagerSelectionEnd = 0;
    state.tagManagerNotice = "";
    elements.tagManagerError.textContent = "";
  }
}

function returnFromTagManager({ restoreFocus = true } = {}) {
  if (elements.confirmDialog.open && state.confirmationBaseLevel === "tagManager") {
    return returnFromConfirmation({ restoreFocus });
  }
  if (!elements.tagManagerDialog.open) return Promise.resolve();
  state.tagManagerHistoryRestoreFocus = restoreFocus;
  if (state.workspaceNavigation.pendingReturnPromise) {
    return state.workspaceNavigation.pendingReturnPromise;
  }
  const current = activeWorkspaceHistoryEntry();
  if (state.workspaceNavigation.initialized
    && current?.route === visibleWorkspaceRoute()
    && current.navigationLevel === "tagManager") {
    const pending = new Promise((resolve) => {
      state.workspaceNavigation.pendingReturnResolve = resolve;
    });
    state.workspaceNavigation.pendingReturnPromise = pending;
    history.back();
    return pending;
  }
  closeTagManager({ restoreFocus });
  state.tagManagerHistoryRestoreFocus = true;
  return Promise.resolve();
}

async function reconcileTagManagerFromWorkspaceHistory(
  route,
  navigationLevel,
  context = {}
) {
  const shouldOpen = (
    navigationLevel === "tagManager"
    || (navigationLevel === "confirmation"
      && context.confirmationBaseLevel === "tagManager")
  ) && route === visibleWorkspaceRoute();
  if (shouldOpen && !state.tagManagerRestorable) {
    state.tagManagerReturnFocus = null;
    state.tagManagerMode = "manage";
    state.tagManagerNotice = "";
    presentTagManager({
      historyMode: "none",
      baseLevel: tagManagerBaseLevelFromHistory(context),
      focus: false,
      render: true,
      historyContext: context,
    });
    if (navigationLevel === "tagManager") await restoreTagManagerLayoutFromHistory();
    return true;
  }
  if (shouldOpen && !elements.tagManagerDialog.open) {
    presentTagManager({
      historyMode: "none",
      baseLevel: tagManagerBaseLevelFromHistory(context),
      focus: false,
      render: false,
    });
    if (navigationLevel === "tagManager") await restoreTagManagerLayoutFromHistory();
  } else if (!shouldOpen && elements.tagManagerDialog.open) {
    const restoreFocus = state.tagManagerHistoryRestoreFocus;
    closeTagManager({
      restoreFocus,
      checkpoint: false,
      preserveState: true,
    });
    state.tagManagerHistoryRestoreFocus = true;
  }
  return false;
}

function confirmationBaseLevelFromHistory(context = {}) {
  return [
    "tagManager",
    "sourceManager",
    "storageMaintenance",
    "generalSettings",
    "actionMenu",
    "sidebar",
    "inspector",
    "lightbox",
  ].includes(context.confirmationBaseLevel)
    ? context.confirmationBaseLevel
    : "workspace";
}

function replaceConfirmationHistoryWithBase(baseLevel, historyContext = {}) {
  if (!state.workspaceNavigation.initialized
    || elements.appView.classList.contains("hidden")) return;
  const current = activeWorkspaceHistoryEntry();
  const route = visibleWorkspaceRoute();
  if (current?.route !== route || current.navigationLevel !== "confirmation") return;
  const context = {
    ...(currentWorkspaceHistoryContext(route) || {}),
    ...historyContext,
  };
  delete context.confirmationBaseLevel;
  let navigationLevel = visibleWorkspaceNavigationBaseLevel(route, baseLevel);
  if (baseLevel === "tagManager" && elements.tagManagerDialog.open) {
    navigationLevel = "tagManager";
    context.tagManagerBaseLevel = state.tagManagerBaseLevel;
    Object.assign(context, currentTagManagerHistoryContext());
  } else if (baseLevel === "sourceManager" && elements.sourceManagerDialog.open) {
    navigationLevel = "sourceManager";
    context.sourceManagerBaseLevel = state.sourceManagerBaseLevel;
    Object.assign(context, currentSourceManagerHistoryContext());
  } else if (baseLevel === "storageMaintenance" && elements.storageDialog.open) {
    navigationLevel = "storageMaintenance";
    context.storageBaseLevel = state.storageBaseLevel;
    Object.assign(context, currentStorageMaintenanceHistoryContext());
  } else if (baseLevel === "generalSettings" && elements.generalSettingsDialog.open) {
    navigationLevel = "generalSettings";
    context.generalSettingsBaseLevel = state.generalSettings.baseLevel;
    Object.assign(context, currentGeneralSettingsHistoryContext());
  } else if (baseLevel === "actionMenu" && activeActionMenuDescriptor()) {
    navigationLevel = "actionMenu";
    context.actionMenuBaseLevel = state.actionMenuBaseLevel;
    context.actionMenuKind = state.actionMenuKind;
  }
  history.replaceState({
    ...(history.state || {}),
    [WORKSPACE_HISTORY_KEY]: workspaceHistoryEntry(route, context, navigationLevel),
  }, "", location.href);
}

function clearConfirmationState() {
  state.pendingConfirmAction = null;
  state.confirmationReturnFocus = null;
  state.confirmationBaseLevel = "workspace";
  state.confirmationHistoryRestoreFocus = true;
}

function requestConfirmation({
  title,
  message,
  actionLabel,
  action,
  returnFocus = { element: document.activeElement },
  tone = "danger",
  eyebrow = null,
}) {
  if (elements.confirmDialog.open) return false;
  const current = activeWorkspaceHistoryEntry();
  const currentLevel = current?.navigationLevel || "workspace";
  state.confirmationBaseLevel = [
    "tagManager",
    "sourceManager",
    "storageMaintenance",
    "generalSettings",
    "actionMenu",
    "sidebar",
    "inspector",
    "lightbox",
  ].includes(currentLevel)
    ? currentLevel
    : workspaceNavigationBaseLevel(currentLevel, current?.context || {});
  state.pendingConfirmAction = action;
  state.confirmationReturnFocus = returnFocus;
  elements.confirmDialog.dataset.tone = tone;
  elements.confirmDialogIcon.textContent = tone === "standard" ? "✓" : "!";
  elements.confirmDialogEyebrow.textContent = eyebrow || {
    danger: "不可逆操作",
    warning: "需要确认",
    standard: "确认操作",
  }[tone] || "需要确认";
  elements.confirmDialogTitle.textContent = title;
  elements.confirmDialogMessage.textContent = message;
  elements.confirmActionButton.textContent = actionLabel;
  elements.confirmActionButton.classList.toggle("button-danger", tone === "danger");
  elements.confirmActionButton.classList.toggle("button-primary", tone !== "danger");
  elements.confirmDialog.showModal();
  const route = visibleWorkspaceRoute();
  recordWorkspaceHistory(route, currentWorkspaceHistoryContext(route), "pushConfirmation");
  elements.confirmActionButton.focus({ preventScroll: true });
  return true;
}

function restoreConfirmationReturnFocus(pending) {
  if (!pending) return;
  if (pending.trainingOperationID) {
    requestAnimationFrame(() => {
      const action = elements.trainingActivityStrip.querySelector(
        `[data-training-activity-id="${CSS.escape(pending.trainingOperationID)}"]`
      );
      (action || elements.refreshTrainingButton || elements.closeTrainingButton)
        ?.focus({ preventScroll: true });
    });
    return;
  }
  if (pending.recycleEntryID) {
    requestAnimationFrame(() => {
      const row = elements.slimmingRecycleList.querySelector(
        `[data-slimming-recycle-row-id="${CSS.escape(pending.recycleEntryID)}"]`
      );
      const originalAction = pending.recycleAction
        ? row?.querySelector(
          `[data-action="${CSS.escape(pending.recycleAction)}"]:not(:disabled)`
        )
        : null;
      const availableAction = row?.querySelector(
        `[data-slimming-recycle-entry-id="${CSS.escape(pending.recycleEntryID)}"]:not(:disabled)`
      );
      const thumbnail = row?.querySelector(":scope > .slimming-recycle-thumbnail-card");
      (originalAction
        || availableAction
        || thumbnail
        || elements.slimmingRecycleLoadMoreButton
        || elements.slimmingButton)
        ?.focus({ preventScroll: true });
    });
    return;
  }
  if (pending.sourceAction) {
    requestAnimationFrame(() => {
      const sourceAction = pending.sourceID
        ? elements.sourceManagerList.querySelector(
          `[data-source-action="${CSS.escape(pending.sourceAction)}"]`
          + `[data-source-id="${CSS.escape(pending.sourceID)}"]`
        )
        : pending.sourceAction === "connectPhotos"
          ? elements.sourceConnectPhotosButton
          : pending.sourceAction === "connectFolder"
            ? elements.sourceConnectFolderButton
            : null;
      const sidebarSource = pending.sourceID
        ? elements.sourceList.querySelector(
          `[data-source-id="${CSS.escape(pending.sourceID)}"]`
        )
        : null;
      (sourceAction || sidebarSource || elements.sourceManagerCloseButton
        || elements.sourceManagerButton)?.focus({ preventScroll: true });
    });
    return;
  }
  if (pending.storageAction) {
    requestAnimationFrame(() => {
      const button = storageActionButton(pending.storageAction);
      if (button && !button.disabled) {
        state.storageMaintenance.pendingReturnAction = null;
        button.focus({ preventScroll: true });
      } else {
        state.storageMaintenance.pendingReturnAction = pending.storageAction;
        (elements.storageCloseButton || elements.storageButton)?.focus({ preventScroll: true });
      }
    });
    return;
  }
  if (pending.slimmingJobID && pending.slimmingJobActionSurface === "options") {
    requestAnimationFrame(() => {
      const action = elements.slimmingCurrentJobActions.querySelector(
        `[data-slimming-job-action-id="${CSS.escape(pending.slimmingJobID)}"]`
        + `[data-action="${CSS.escape(pending.slimmingJobAction || "")}"]`
      );
      const fallback = elements.slimmingCurrentJobActions.querySelector(
        "[data-slimming-job-action-id]:not(:disabled)"
      );
      (action || fallback || elements.closeSlimmingAnalysisOptionsButton)
        ?.focus({ preventScroll: true });
    });
    return;
  }
  if (pending.slimmingJobID && pending.slimmingJobActionSurface === "navigator") {
    requestAnimationFrame(() => {
      const action = elements.slimmingJobActions.querySelector(
        `[data-slimming-job-action-id="${CSS.escape(pending.slimmingJobID)}"]`
        + `[data-action="${CSS.escape(pending.slimmingJobAction || "")}"]`
      );
      const fallback = elements.slimmingJobActions.querySelector(
        "[data-slimming-job-action-id]:not(:disabled)"
      );
      (action || fallback || elements.slimmingJobList.querySelector(
        `[data-slimming-job-id="${CSS.escape(pending.slimmingJobID)}"]`
      ))?.focus({ preventScroll: true });
    });
    return;
  }
  if (pending.slimmingJobID) {
    requestAnimationFrame(() => {
      const job = elements.slimmingJobList.querySelector(
        `[data-slimming-job-id="${CSS.escape(pending.slimmingJobID)}"]`
      );
      if (job) job.focus({ preventScroll: true });
      else focusSelectedSlimmingJob();
    });
    return;
  }
  if (pending.lightboxAssetID) {
    requestAnimationFrame(() => {
      if (!elements.lightbox.classList.contains("hidden")
        && state.lightboxAssetID === pending.lightboxAssetID) {
        elements.lightboxDeleteButton.focus({ preventScroll: true });
        return;
      }
      if (pending.libraryAssetID) {
        assetCardFocusTarget(pending.libraryAssetID)?.focus({ preventScroll: true });
        return;
      }
      const card = elements.slimmingMemberGrid.querySelector(
        `[data-slimming-member-id="${CSS.escape(pending.slimmingMemberID || pending.lightboxAssetID)}"]`
      );
      slimmingMemberMainButton(card)?.focus({ preventScroll: true });
    });
    return;
  }
  if (pending.tagID) {
    requestAnimationFrame(() => {
      resolveTagReturnFocusTarget(pending)?.focus({ preventScroll: true });
    });
    return;
  }
  if (pending.groupID) {
    requestAnimationFrame(() => {
      resolveTagReturnFocusTarget(pending)?.focus({ preventScroll: true });
    });
    return;
  }
  requestAnimationFrame(() => {
    if (pending.element?.isConnected) pending.element.focus({ preventScroll: true });
  });
}

function closeConfirmation({
  restoreFocus = true,
  checkpoint = true,
  preserveState = false,
} = {}) {
  if (!elements.confirmDialog.open) return;
  const baseLevel = state.confirmationBaseLevel;
  const pendingFocus = state.confirmationReturnFocus;
  elements.confirmDialog.close();
  if (restoreFocus) restoreConfirmationReturnFocus(pendingFocus);
  if (checkpoint) replaceConfirmationHistoryWithBase(baseLevel);
  if (!preserveState) clearConfirmationState();
}

function returnFromConfirmation({ restoreFocus = true } = {}) {
  if (!elements.confirmDialog.open) return Promise.resolve();
  state.confirmationHistoryRestoreFocus = restoreFocus;
  if (state.workspaceNavigation.pendingReturnPromise) {
    return state.workspaceNavigation.pendingReturnPromise;
  }
  const current = activeWorkspaceHistoryEntry();
  if (state.workspaceNavigation.initialized
    && current?.route === visibleWorkspaceRoute()
    && current.navigationLevel === "confirmation") {
    const pending = new Promise((resolve) => {
      state.workspaceNavigation.pendingReturnResolve = resolve;
    });
    state.workspaceNavigation.pendingReturnPromise = pending;
    history.back();
    return pending;
  }
  closeConfirmation({ restoreFocus });
  return Promise.resolve();
}

function reconcileConfirmationFromWorkspaceHistory(
  route,
  navigationLevel,
  context = {}
) {
  const shouldOpen = navigationLevel === "confirmation"
    && route === visibleWorkspaceRoute();
  if (shouldOpen && !state.pendingConfirmAction) {
    replaceConfirmationHistoryWithBase(
      confirmationBaseLevelFromHistory(context),
      context
    );
    return;
  }
  if (shouldOpen && !elements.confirmDialog.open) {
    state.confirmationBaseLevel = confirmationBaseLevelFromHistory(context);
    elements.confirmDialog.showModal();
    restoreOverlayFocus(elements.confirmActionButton);
  } else if (!shouldOpen && elements.confirmDialog.open) {
    const restoreFocus = state.confirmationHistoryRestoreFocus;
    closeConfirmation({
      restoreFocus,
      checkpoint: false,
      preserveState: true,
    });
    state.confirmationHistoryRestoreFocus = true;
  }
}

async function refreshTagCatalogAfterMutation() {
  const [tags, groups] = await Promise.all([
    api("/v1/tags"),
    api("/v1/tag-groups"),
  ]);
  state.tags = tags;
  state.tagGroups = groups;
  const activeTagIDs = new Set(activeTags().map((tag) => tag.id));
  state.filters.tagConditions = state.filters.tagConditions.filter(
    (condition) => activeTagIDs.has(condition.tagID)
  );
  renderTagSelects();
  renderFilterChips();
  renderLibraryEmptyState();
}

async function installPresetTags(returnFocus = document.activeElement) {
  if (!state.online || state.installingPresetTags) return;
  const generation = state.workspaceGeneration;
  const operationID = state.presetTagOperationID || crypto.randomUUID();
  state.presetTagOperationID = operationID;
  state.installingPresetTags = true;
  elements.tagManagerError.textContent = "";
  renderTagNavigation();
  renderTagManager();
  renderLibraryEmptyState();
  syncWriteActionControls();
  try {
    const response = await api("/v1/tags/install-presets", {
      method: "POST",
      body: JSON.stringify({ operationID }),
    });
    if (generation !== state.workspaceGeneration) return;
    state.presetTagOperationID = null;
    await refreshTagCatalogAfterMutation();
    if (generation !== state.workspaceGeneration) return;
    if (state.selectionMode && state.selectedAssetIDs.size) {
      scheduleSelectionAggregate();
    } else if (state.selectedAssetID) {
      await loadInspector(state.selectedAssetID, {
        preserveExisting: false,
        quiet: true,
      });
    }
    const count = response.createdTags?.length || 0;
    toast(count ? `已添加 ${count} 个常用标签` : "常用标签已全部存在");
  } catch (error) {
    const message = error.message || "无法添加常用标签";
    if (elements.tagManagerDialog.open) elements.tagManagerError.textContent = message;
    toast(message);
  } finally {
    if (generation === state.workspaceGeneration) {
      state.installingPresetTags = false;
      renderTagNavigation();
      renderTagManager();
      renderLibraryEmptyState();
      syncWriteActionControls();
      requestAnimationFrame(() => {
        const returnIsVisible = returnFocus?.isConnected
          && !returnFocus.disabled
          && !returnFocus.classList?.contains("hidden")
          && !returnFocus.closest?.(".hidden");
        const target = returnIsVisible
          ? returnFocus
          : (elements.tagNavigation.querySelector("[data-quick-tag-id]")
            || elements.tagManagerButton);
        target?.focus?.({ preventScroll: true });
      });
    }
  }
}

async function performTagCatalogMutation(path, body, successMessage) {
  if (!state.online || state.tagManagementMutating) return false;
  const generation = state.workspaceGeneration;
  state.tagManagementMutating = true;
  elements.tagManagerError.textContent = "";
  syncWriteActionControls();
  renderTagNavigation();
  renderTagManager();
  try {
    await api(path, { method: "POST", body: JSON.stringify(body) });
    if (generation !== state.workspaceGeneration) return false;
    await refreshTagCatalogAfterMutation();
    if (generation !== state.workspaceGeneration) return false;
    await loadAssets({
      preserveSelection: true,
      preserveUnchangedGrid: true,
      preserveLoadedWindow: true,
    });
    toast(successMessage);
    return true;
  } catch (error) {
    if (generation === state.workspaceGeneration) {
      elements.tagManagerError.textContent = error.message || "标签操作失败";
      toast(error.message || "标签操作失败");
    }
    return false;
  } finally {
    if (generation === state.workspaceGeneration) {
      state.tagManagementMutating = false;
      renderTagNavigation();
      renderTagManager();
      syncWriteActionControls();
    }
  }
}

async function renameManagedTag() {
  const tag = tagByID(elements.tagManagerTagSelect.value);
  const name = elements.tagManagerTagName.value.trim();
  if (!tag || !name) return;
  await performTagCatalogMutation(
    `/v1/tags/${tag.id}/rename`,
    { operationID: crypto.randomUUID(), name },
    `已将标签重命名为“${name}”`
  );
}

async function moveManagedTag() {
  const tag = tagByID(elements.tagManagerTagSelect.value);
  const group = groupByID(elements.tagManagerTagGroupSelect.value);
  if (!tag || !group) return;
  await performTagCatalogMutation(
    `/v1/tags/${tag.id}/move`,
    { operationID: crypto.randomUUID(), groupID: group.id },
    `已将“${tag.displayName}”移动到“${group.displayName}”`
  );
}

function confirmArchiveManagedTag(tagOverride = null, returnFocus = null) {
  const tag = tagOverride?.id
    ? tagOverride
    : tagByID(elements.tagManagerTagSelect.value);
  if (!tag) return;
  requestConfirmation({
    title: "归档标签？",
    message: `“${tag.displayName}”会从活动标签和网页筛选中移除，已有照片决定仍保留。`,
    actionLabel: "归档",
    action: () => performTagCatalogMutation(
      `/v1/tags/${tag.id}/archive`,
      { operationID: crypto.randomUUID() },
      `已归档标签“${tag.displayName}”`
    ),
    ...(returnFocus ? { returnFocus } : {}),
  });
}

async function createManagedTagGroup() {
  const name = elements.tagManagerGroupName.value.trim();
  if (!name) return;
  const created = await performTagCatalogMutation(
    "/v1/tag-groups",
    { operationID: crypto.randomUUID(), name },
    `已新建分组“${name}”`
  );
  if (created) state.tagManagerMode = "manage";
}

async function renameManagedTagGroup() {
  const group = groupByID(elements.tagManagerGroupSelect.value);
  const name = elements.tagManagerGroupName.value.trim();
  if (!group || group.isSystem || !name) return;
  await performTagCatalogMutation(
    `/v1/tag-groups/${group.id}/rename`,
    { operationID: crypto.randomUUID(), name },
    `已将分组重命名为“${name}”`
  );
}

function confirmDeleteManagedTagGroup(groupOverride = null, returnFocus = null) {
  const group = groupOverride?.id
    ? groupOverride
    : groupByID(elements.tagManagerGroupSelect.value);
  if (!group || group.isSystem) return;
  requestConfirmation({
    title: "删除标签分组？",
    message: `“${group.displayName}”会被删除，其中的标签会移到 Mac 端默认分组，标签本身不会归档。`,
    actionLabel: "删除分组",
    action: () => performTagCatalogMutation(
      `/v1/tag-groups/${group.id}/delete`,
      { operationID: crypto.randomUUID() },
      `已删除分组“${group.displayName}”`
    ),
    ...(returnFocus ? { returnFocus } : {}),
  });
}

async function undoLatestDecision(kind) {
  const channel = state.undo[kind];
  const undoID = channel?.id;
  if (!channel || !state.online || !undoID || channel.mutating) return;
  if (!channel.operationID) {
    channel.operationID = crypto.randomUUID();
  }
  const operationID = channel.operationID;
  const generation = state.workspaceGeneration;
  channel.mutating = true;
  syncWriteActionControls();
  try {
    const endpoint = kind === "review"
      ? "/v1/review/decisions/undo"
      : "/v1/tag-decisions/undo";
    const result = await api(endpoint, {
      method: "POST",
      body: JSON.stringify({ operationID, undoID }),
    });
    if (generation !== state.workspaceGeneration) return;
    channel.id = null;
    channel.operationID = null;
    channel.sequence = 0;
    if (state.toastUndoKind === kind) state.toastUndoKind = null;
    await refreshWorkspace({
      quiet: true,
      kinds: ["assetsChanged", "tagsChanged", "reviewChanged"],
    });
    if (kind === "review" && state.review.mode === "queue") {
      await loadReviewQueue({ preserveLoadedWindow: true });
    }
    toast(`已撤销 ${result.restoredAssetCount} 项${kind === "review" ? "审核" : "标签"}决定`);
  } catch (error) {
    if (generation === state.workspaceGeneration) {
      undoToast(error.message || "撤销失败，可重试", undoID, kind);
    }
  } finally {
    if (generation === state.workspaceGeneration) {
      channel.mutating = false;
      syncWriteActionControls();
    }
  }
}

function latestUndoKind() {
  const candidates = ["tag", "review"]
    .filter((kind) => {
      const channel = state.undo[kind];
      return state.online && channel?.id && !channel.mutating;
    })
    .sort((lhs, rhs) => {
      const sequenceDelta = (state.undo[rhs].sequence || 0) - (state.undo[lhs].sequence || 0);
      if (sequenceDelta !== 0) return sequenceDelta;
      if (state.toastUndoKind === lhs) return -1;
      if (state.toastUndoKind === rhs) return 1;
      return lhs.localeCompare(rhs);
    });
  return candidates[0] || null;
}

function undoLatestAvailableDecision() {
  const kind = latestUndoKind();
  if (!kind) return false;
  void undoLatestDecision(kind);
  return true;
}

function sourceSidebarHelpDetail(source) {
  const availability = {
    active: "来源可用。",
    unavailable: source.kind === "photos"
      ? "当前系统照片图库与这条历史来源不一致；已索引照片和人工标签仍保留。"
      : "来源当前离线；已索引照片和人工标签仍保留。",
    authorizationRequired: "需要重新授权此来源，恢复前只能查看已经保留的目录信息。",
    disabled: "来源已停用；已索引照片和人工标签仍保留。",
  }[source.state] || `当前状态：${sourceStateText(source.state)}。`;
  const refresh = source.kind === "photos"
    ? "来源可用时可立即同步 Apple Photos 的最新变化。"
    : "来源可用时可立即重扫文件夹并更新索引。";
  return [
    availability,
    `点击只显示“${source.displayName}”中的当前媒体。${refresh}`,
    ...(folderSourceSupportsHierarchy(source)
      ? ["左右方向键可展开、进入子目录、折叠或返回父目录；上下键继续沿可见层级移动。"]
      : []),
    "上/下逐项移动，Page Up/Down 按当前可见页幅移动，Home/End 直达侧栏首尾。",
    "右键、触控长按、Context Menu 或 Shift-F10 可排序，并查看同步、缓存、授权、管理和移除动作。",
    "拖动可直接调整来源顺序；Option + 上/下可用键盘移动。",
  ].join("\n");
}

function supportsFolderHierarchy() {
  return state.capabilities?.capabilities?.includes("folderHierarchy") === true;
}

function cloneFolderScope(scope) {
  return scope ? { sourceID: scope.sourceID, relativePath: scope.relativePath } : null;
}

function folderScopeKey(sourceID, relativePath = "") {
  return `${sourceID}\u0000${relativePath || ""}`;
}

function folderBranchKey(sourceID, parentRelativePath = null) {
  return folderScopeKey(sourceID, parentRelativePath || "");
}

function folderSourceSupportsHierarchy(source) {
  return supportsFolderHierarchy() && source?.kind === "folder";
}

function folderBranch(sourceID, parentRelativePath = null) {
  return state.folderNavigation.branches.get(folderBranchKey(sourceID, parentRelativePath));
}

function selectedFolderMatches(sourceID, relativePath) {
  return state.folderScope?.sourceID === sourceID
    && state.folderScope?.relativePath === relativePath;
}

function captureFolderSidebarFocus() {
  const active = document.activeElement;
  if (!active || !elements.sourceList.contains(active)) return null;
  if (active.matches("[data-folder-search-source-id]")) {
    return { kind: "search", sourceID: active.dataset.folderSearchSourceId };
  }
  if (active.matches("[data-folder-search-submit-source-id]")) {
    return { kind: "searchSubmit", sourceID: active.dataset.folderSearchSubmitSourceId };
  }
  if (active.matches("[data-folder-search-retry-source-id]")) {
    return { kind: "searchRetry", sourceID: active.dataset.folderSearchRetrySourceId };
  }
  if (active.matches("[data-folder-path]")) {
    return {
      kind: "folder",
      sourceID: active.dataset.folderSourceId,
      relativePath: active.dataset.folderPath,
    };
  }
  if (active.matches("[data-folder-load-more]")) {
    return {
      kind: "more",
      sourceID: active.dataset.folderSourceId,
      parentRelativePath: active.dataset.folderParentPath || null,
    };
  }
  if (active.matches("[data-folder-retry-source-id]")) {
    return {
      kind: "retry",
      sourceID: active.dataset.folderRetrySourceId,
      parentRelativePath: active.dataset.folderRetryParentPath || null,
    };
  }
  if (active.matches("[data-source-id]")) {
    return { kind: "source", sourceID: active.dataset.sourceId };
  }
  return null;
}

function restoreFolderSidebarFocus(focus) {
  if (!focus) return;
  requestAnimationFrame(() => {
    let target = null;
    if (focus.kind === "search") {
      target = elements.sourceList.querySelector(
        `[data-folder-search-source-id="${CSS.escape(focus.sourceID)}"]`
      );
    } else if (focus.kind === "searchSubmit") {
      target = folderSearchSubmitButton(focus.sourceID);
    } else if (focus.kind === "searchRetry") {
      target = folderSearchRetryButton(focus.sourceID);
    } else if (focus.kind === "folder") {
      target = elements.sourceList.querySelector(
        `[data-folder-source-id="${CSS.escape(focus.sourceID)}"]`
        + `[data-folder-path="${CSS.escape(focus.relativePath)}"]`
      );
    } else if (focus.kind === "more") {
      target = folderLoadMoreButton(focus.sourceID, focus.parentRelativePath);
    } else if (focus.kind === "retry") {
      target = folderBranchRetryButton(focus.sourceID, focus.parentRelativePath);
    } else if (focus.kind === "source") {
      target = elements.sourceList.querySelector(
        `[data-source-id="${CSS.escape(focus.sourceID)}"]`
      );
    }
    target?.focus({ preventScroll: true });
  });
}

async function loadFolderBranch(sourceID, parentRelativePath = null, { append = false } = {}) {
  const key = folderBranchKey(sourceID, parentRelativePath);
  const current = state.folderNavigation.branches.get(key);
  if (current?.loading) return;
  const catalogGeneration = state.folderNavigation.requestGeneration;
  const requestGeneration =
    (state.folderNavigation.branchRequestGenerations.get(key) || 0) + 1;
  state.folderNavigation.branchRequestGenerations.set(key, requestGeneration);
  const offset = append ? (current?.nextOffset || 0) : 0;
  state.folderNavigation.branches.set(key, {
    folders: append ? [...(current?.folders || [])] : [],
    totalCount: current?.totalCount || 0,
    nextOffset: current?.nextOffset ?? null,
    loading: true,
    error: null,
    loadMoreError: null,
  });
  renderSources();
  const query = new URLSearchParams({
    sourceID,
    offset: String(offset),
    limit: "100",
  });
  if (parentRelativePath) query.set("parentRelativePath", parentRelativePath);
  try {
    const page = await api(`/v1/source-folders?${query}`);
    if (catalogGeneration !== state.folderNavigation.requestGeneration
      || requestGeneration !== state.folderNavigation.branchRequestGenerations.get(key)) return;
    const previous = append ? (current?.folders || []) : [];
    state.folderNavigation.branches.set(key, {
      folders: [...previous, ...(page.folders || [])],
      totalCount: page.totalCount || 0,
      nextOffset: page.nextOffset ?? null,
      loading: false,
      error: null,
      loadMoreError: null,
    });
  } catch (error) {
    if (catalogGeneration !== state.folderNavigation.requestGeneration
      || requestGeneration !== state.folderNavigation.branchRequestGenerations.get(key)) return;
    state.folderNavigation.branches.set(key, {
      folders: append ? [...(current?.folders || [])] : [],
      totalCount: current?.totalCount || 0,
      nextOffset: current?.nextOffset ?? null,
      loading: false,
      error: append ? null : (error.message || "无法读取文件夹"),
      loadMoreError: append ? (error.message || "无法载入更多目录") : null,
    });
  }
  renderSources();
}

function folderBranchRetryButton(sourceID, parentRelativePath = null) {
  const expectedParent = parentRelativePath || "";
  return [...elements.sourceList.querySelectorAll(
    `[data-folder-retry-source-id="${CSS.escape(sourceID)}"]`
  )].find((button) => button.dataset.folderRetryParentPath === expectedParent) || null;
}

function folderLoadMoreButton(sourceID, parentRelativePath = null) {
  const expectedParent = parentRelativePath || "";
  return [...elements.sourceList.querySelectorAll(
    `[data-folder-load-more][data-folder-source-id="${CSS.escape(sourceID)}"]`
  )].find((button) => button.dataset.folderParentPath === expectedParent) || null;
}

async function loadMoreFolderBranch(sourceID, parentRelativePath = null) {
  const key = folderBranchKey(sourceID, parentRelativePath);
  const current = folderBranch(sourceID, parentRelativePath);
  if (!current || current.loading || current.nextOffset == null) return;
  const previousCount = current.folders.length;
  const catalogGeneration = state.folderNavigation.requestGeneration;
  const requestGeneration =
    (state.folderNavigation.branchRequestGenerations.get(key) || 0) + 1;
  await loadFolderBranch(sourceID, parentRelativePath, { append: true });
  if (catalogGeneration !== state.folderNavigation.requestGeneration
    || requestGeneration !== state.folderNavigation.branchRequestGenerations.get(key)) return;
  requestAnimationFrame(() => {
    if (!document.hasFocus()) return;
    const active = document.activeElement;
    if (active !== document.body && active !== document.documentElement) return;
    const branch = folderBranch(sourceID, parentRelativePath);
    const firstAppendedFolder = branch?.folders?.[previousCount] || null;
    const target = branch?.error
      ? folderBranchRetryButton(sourceID, parentRelativePath)
      : folderLoadMoreButton(sourceID, parentRelativePath)
        || (firstAppendedFolder
          ? folderTreeRow(sourceID, firstAppendedFolder.relativePath)
          : parentRelativePath
            ? folderTreeRow(sourceID, parentRelativePath)
            : elements.sourceList.querySelector(
              `[data-source-id="${CSS.escape(sourceID)}"]`
            ));
    target?.focus({ preventScroll: true });
    target?.scrollIntoView({ block: "nearest" });
  });
}

async function retryFolderBranch(sourceID, parentRelativePath = null) {
  await loadFolderBranch(sourceID, parentRelativePath);
  requestAnimationFrame(() => {
    if (!document.hasFocus()) return;
    const active = document.activeElement;
    if (active !== document.body && active !== document.documentElement) return;
    const branch = folderBranch(sourceID, parentRelativePath);
    const target = branch?.error
      ? folderBranchRetryButton(sourceID, parentRelativePath)
      : firstFolderTreeChild(sourceID, parentRelativePath)
        || (parentRelativePath
          ? folderTreeRow(sourceID, parentRelativePath)
          : elements.sourceList.querySelector(
            `[data-source-id="${CSS.escape(sourceID)}"]`
          ));
    target?.focus({ preventScroll: true });
    target?.scrollIntoView({ block: "nearest" });
  });
}

async function searchFolders(sourceID, text) {
  const focus = captureFolderSidebarFocus();
  const queryText = text.trim();
  const catalogGeneration = state.folderNavigation.requestGeneration;
  const requestGeneration =
    (state.folderNavigation.searchRequestGenerations.get(sourceID) || 0) + 1;
  state.folderNavigation.searchRequestGenerations.set(sourceID, requestGeneration);
  if (!queryText) {
    state.folderNavigation.searches.delete(sourceID);
    renderSources();
    return;
  }
  state.folderNavigation.searches.set(sourceID, {
    query: text,
    folders: [],
    loading: true,
    error: null,
  });
  renderSources();
  try {
    const query = new URLSearchParams({ sourceID, q: queryText, limit: "50" });
    const page = await api(`/v1/source-folders?${query}`);
    if (catalogGeneration !== state.folderNavigation.requestGeneration
      || requestGeneration !== state.folderNavigation.searchRequestGenerations.get(sourceID)) return;
    state.folderNavigation.searches.set(sourceID, {
      query: text,
      folders: page.folders || [],
      totalCount: page.totalCount || 0,
      loading: false,
      error: null,
    });
  } catch (error) {
    if (catalogGeneration !== state.folderNavigation.requestGeneration
      || requestGeneration !== state.folderNavigation.searchRequestGenerations.get(sourceID)) return;
    state.folderNavigation.searches.set(sourceID, {
      query: text,
      folders: [],
      loading: false,
      error: error.message || "搜索失败",
    });
  }
  renderSources();
  restoreFolderSidebarFocus(focus);
}

function folderSearchInput(sourceID) {
  return elements.sourceList.querySelector(
    `[data-folder-search-source-id="${CSS.escape(sourceID)}"]`
  );
}

function folderSearchSubmitButton(sourceID) {
  return elements.sourceList.querySelector(
    `[data-folder-search-submit-source-id="${CSS.escape(sourceID)}"]`
  );
}

function submitFolderSearch(sourceID) {
  const text = folderSearchInput(sourceID)?.value
    ?? state.folderNavigation.searches.get(sourceID)?.query
    ?? "";
  if (!text.trim()) return;
  clearTimeout(state.folderNavigation.searchTimers.get(sourceID));
  state.folderNavigation.searchTimers.delete(sourceID);
  void searchFolders(sourceID, text);
}

function folderSearchRetryButton(sourceID) {
  return elements.sourceList.querySelector(
    `[data-folder-search-retry-source-id="${CSS.escape(sourceID)}"]`
  );
}

async function retryFolderSearch(sourceID) {
  const query = state.folderNavigation.searches.get(sourceID)?.query || "";
  if (!query.trim()) return;
  clearTimeout(state.folderNavigation.searchTimers.get(sourceID));
  state.folderNavigation.searchTimers.delete(sourceID);
  await searchFolders(sourceID, query);
  requestAnimationFrame(() => {
    if (!document.hasFocus()) return;
    const active = document.activeElement;
    if (active !== document.body && active !== document.documentElement) return;
    const search = state.folderNavigation.searches.get(sourceID);
    if (search?.query !== query) return;
    const target = search.error
      ? folderSearchRetryButton(sourceID)
      : elements.sourceList.querySelector(
        `[data-folder-search-result="true"]`
        + `[data-folder-source-id="${CSS.escape(sourceID)}"]`
      ) || elements.sourceList.querySelector(
        `[data-folder-search-source-id="${CSS.escape(sourceID)}"]`
      );
    target?.focus({ preventScroll: true });
    target?.scrollIntoView({ block: "nearest" });
  });
}

function expandFolderScopeAncestors(sourceID, relativePath) {
  const branchParents = [null];
  state.folderNavigation.expanded.add(folderScopeKey(sourceID));
  const components = relativePath.split("/").filter(Boolean);
  for (let length = 1; length < components.length; length += 1) {
    const ancestor = components.slice(0, length).join("/");
    state.folderNavigation.expanded.add(folderScopeKey(sourceID, ancestor));
    branchParents.push(ancestor);
  }
  return branchParents;
}

function loadFolderScopeAncestorBranches(sourceID, branchParents) {
  for (const parentRelativePath of branchParents) {
    const branch = folderBranch(sourceID, parentRelativePath);
    if (!branch || branch.error) {
      void loadFolderBranch(sourceID, parentRelativePath);
    }
  }
}

function loadExpandedFolderBranches() {
  for (const key of state.folderNavigation.expanded) {
    const separator = key.indexOf("\u0000");
    if (separator < 1) continue;
    const sourceID = key.slice(0, separator);
    const parentRelativePath = key.slice(separator + 1) || null;
    const source = state.sources.find((candidate) => candidate.id === sourceID);
    if (!folderSourceSupportsHierarchy(source)) continue;
    const branch = folderBranch(sourceID, parentRelativePath);
    if (!branch || branch.error) void loadFolderBranch(sourceID, parentRelativePath);
  }
}

async function reconcileSelectedFolderAfterSourceRefresh() {
  const original = cloneFolderScope(state.folderScope);
  if (!original) return;
  if (!state.sources.some((source) => source.id === original.sourceID)) {
    state.folderScope = null;
    state.folderNavigation.selectedSessionID = null;
    return;
  }
  const components = original.relativePath.split("/").filter(Boolean);
  while (components.length) {
    const candidate = components.join("/");
    const query = new URLSearchParams({
      sourceID: original.sourceID,
      q: candidate,
      limit: "50",
    });
    try {
      const page = await api(`/v1/source-folders?${query}`);
      if ((page.folders || []).some((folder) => folder.relativePath === candidate)) {
        state.folderScope = { sourceID: original.sourceID, relativePath: candidate };
        if (state.folderNavigation.selectedSessionID) {
          state.folderNavigation.historyScopes.set(
            state.folderNavigation.selectedSessionID,
            cloneFolderScope(state.folderScope)
          );
        }
        if (candidate !== original.relativePath) {
          toast("原文件夹已移动或移除，已回到最近的可用上级目录");
        }
        return;
      }
    } catch {
      return;
    }
    components.pop();
  }
  state.folderScope = null;
  state.folderNavigation.selectedSessionID = null;
  toast("原文件夹已不在最新索引中，已返回来源根目录");
}

function appendFolderRows(
  container,
  sourceID,
  folders,
  depth = 0,
  { search = false, parentRelativePath = null } = {}
) {
  for (const folder of folders) {
    const key = folderScopeKey(sourceID, folder.relativePath);
    const expanded = state.folderNavigation.expanded.has(key);
    const row = document.createElement("button");
    row.type = "button";
    row.className = "source-folder-row";
    row.dataset.folderSourceId = sourceID;
    row.dataset.folderPath = folder.relativePath;
    if (search) row.dataset.folderSearchResult = "true";
    else {
      row.dataset.folderParentPath = folder.parentRelativePath ?? parentRelativePath ?? "";
      row.setAttribute("role", "treeitem");
      row.setAttribute("aria-level", String(depth + 2));
      row.setAttribute("aria-expanded", String(expanded));
      row.setAttribute("aria-selected", String(selectedFolderMatches(
        sourceID,
        folder.relativePath
      )));
      row.setAttribute(
        "aria-keyshortcuts",
        "ArrowLeft ArrowRight ArrowUp ArrowDown PageUp PageDown Home End"
      );
    }
    row.style.setProperty("--folder-depth", String(depth));
    row.classList.toggle("selected", selectedFolderMatches(sourceID, folder.relativePath));
    row.setAttribute("aria-current", selectedFolderMatches(sourceID, folder.relativePath) ? "page" : "false");
    row.title = folder.relativePath;
    configurePersistentHelp(row, {
      title: search ? folder.relativePath : folder.name,
      detail: search
        ? `打开“${folder.relativePath}”，并在普通目录树中展开其上级；只显示这个目录及其所有子目录中的媒体。`
        : `只显示“${folder.relativePath}”目录及其所有子目录中的媒体。点击打开；右方向键展开，左方向键折叠或返回上级；Page Up/Down 按侧栏当前可见页幅移动。`,
      kind: "source",
      owner: `folder:${sourceID}:${search ? "search" : "tree"}:${folder.relativePath}`,
    });
    const disclosure = document.createElement("span");
    disclosure.className = "folder-disclosure";
    if (!search) disclosure.dataset.folderToggle = key;
    disclosure.setAttribute("aria-hidden", "true");
    disclosure.textContent = search ? "·" : (expanded ? "▾" : "▸");
    const name = document.createElement("span");
    name.className = "folder-name";
    name.textContent = search ? folder.relativePath : folder.name;
    row.append(disclosure, name);
    container.append(row);
    if (!search && expanded) {
      const branch = folderBranch(sourceID, folder.relativePath);
      appendFolderBranch(container, sourceID, folder.relativePath, branch, depth + 1);
    }
  }
}

function appendFolderBranch(container, sourceID, parentRelativePath, branch, depth = 0) {
  if (!branch) return;
  if (branch.loading && !branch.folders.length) {
    const status = document.createElement("p");
    status.className = "source-folder-status";
    status.textContent = "正在读取…";
    container.append(status);
    return;
  }
  if (branch.error) {
    const status = document.createElement("p");
    status.className = "source-folder-status";
    status.setAttribute("role", "status");
    status.textContent = branch.error;
    container.append(status);
    const retry = document.createElement("button");
    retry.type = "button";
    retry.className = "source-folder-retry";
    retry.dataset.folderRetrySourceId = sourceID;
    retry.dataset.folderRetryParentPath = parentRelativePath || "";
    retry.textContent = "重新载入子文件夹";
    retry.title = "重新读取这个目录的第一页；不会改变当前图库范围";
    retry.setAttribute("aria-label", `${retry.textContent}：${parentRelativePath || "来源根目录"}`);
    configurePersistentHelp(retry, {
      title: retry.textContent,
      detail: `重新读取“${parentRelativePath || "来源根目录"}”的第一页；不会选择目录、读取媒体或改变当前图库范围。`,
      kind: "source",
      owner: `folder-retry:${sourceID}:${parentRelativePath || "root"}`,
    });
    container.append(retry);
  }
  appendFolderRows(container, sourceID, branch.folders, depth, { parentRelativePath });
  if (!branch.loading && !branch.error && !branch.folders.length) {
    const empty = document.createElement("p");
    empty.className = "source-folder-status";
    empty.textContent = "没有已索引的子文件夹";
    container.append(empty);
  }
  if (branch.loadMoreError) {
    const status = document.createElement("p");
    status.className = "source-folder-status";
    status.setAttribute("role", "status");
    status.textContent = `无法载入更多目录：${branch.loadMoreError}`;
    container.append(status);
  }
  if (branch.nextOffset != null) {
    const more = document.createElement("button");
    more.type = "button";
    more.className = "source-folder-more";
    more.dataset.folderLoadMore = folderBranchKey(sourceID, parentRelativePath);
    more.dataset.folderSourceId = sourceID;
    more.dataset.folderParentPath = parentRelativePath || "";
    const pageProgress = `${branch.folders.length} / ${branch.totalCount}`;
    more.textContent = branch.loading
      ? "正在读取…"
      : branch.loadMoreError
        ? `重试显示更多（${pageProgress}）`
        : `显示更多（${pageProgress}）`;
    more.title = branch.loadMoreError
      ? "从上次失败的位置继续载入；不会重读已经显示的目录"
      : "载入下一页目录";
    configurePersistentHelp(more, {
      title: branch.loadMoreError ? "重试显示更多" : "显示更多目录",
      detail: branch.loadMoreError
        ? `从上次失败的位置继续读取“${parentRelativePath || "来源根目录"}”；已显示的 ${branch.folders.length} 项保持不变。`
        : `继续读取“${parentRelativePath || "来源根目录"}”的下一页；已显示 ${pageProgress} 项。`,
      kind: "source",
      owner: `folder-more:${sourceID}:${parentRelativePath || "root"}`,
    });
    more.disabled = branch.loading;
    container.append(more);
  }
}

function appendSourceFolderTree(source) {
  const tree = document.createElement("div");
  tree.className = "source-folder-tree";
  tree.dataset.folderTreeSourceId = source.id;
  tree.id = `source-folder-tree-${source.id}`;
  tree.setAttribute("role", "group");
  tree.setAttribute("aria-label", `${source.displayName}中的文件夹`);
  const root = folderBranch(source.id);
  if (root?.totalCount > 500) {
    const capacity = document.createElement("p");
    capacity.className = "source-folder-capacity";
    capacity.textContent = `共 ${root.totalCount} 个子文件夹，按需显示`;
    configurePersistentHelp(capacity, {
      title: `${source.displayName}的大型目录`,
      detail: "每次读取最多 100 个直接子文件夹；可继续显示更多，也可搜索完整来源中的目录。",
      kind: "source",
      owner: `folder-capacity:${source.id}`,
    });
    tree.append(capacity);
    const search = state.folderNavigation.searches.get(source.id);
    const controls = document.createElement("div");
    controls.className = "source-folder-search-controls";
    const input = document.createElement("input");
    input.type = "search";
    input.className = "source-folder-search";
    input.dataset.folderSearchSourceId = source.id;
    input.placeholder = `搜索 ${root.totalCount} 个文件夹`;
    input.value = search?.query || "";
    input.enterKeyHint = "search";
    input.setAttribute("aria-label", `搜索${source.displayName}中的文件夹`);
    configurePersistentHelp(input, {
      title: `搜索${source.displayName}中的目录`,
      detail: "在完整来源中查找目录；结果保留在普通目录树上方，不会改变当前图库范围。Escape 清空查询。",
      kind: "source",
      owner: `folder-search:${source.id}`,
    });
    const submit = document.createElement("button");
    submit.type = "button";
    submit.className = "source-folder-search-submit";
    submit.dataset.folderSearchSubmitSourceId = source.id;
    submit.textContent = "⌕";
    submit.disabled = !input.value.trim();
    submit.title = "搜索目录（Enter）";
    submit.setAttribute("aria-label", `搜索${source.displayName}中的文件夹`);
    submit.setAttribute("aria-keyshortcuts", "Enter");
    configurePersistentHelp(submit, {
      title: "搜索目录（Enter）",
      detail: `立即搜索${source.displayName}中的目录；不会替换已经载入的普通目录树。`,
      kind: "source",
      owner: `folder-search-submit:${source.id}`,
    });
    controls.append(input, submit);
    tree.append(controls);
    if (search?.query) {
      const results = document.createElement("div");
      results.className = "source-folder-search-results";
      results.setAttribute("role", "group");
      results.setAttribute("aria-label", "文件夹搜索结果");
      const summary = document.createElement("p");
      summary.className = "source-folder-search-summary";
      if (search.loading) {
        summary.textContent = "正在搜索…";
      } else if (search.error) {
        summary.textContent = search.error;
        results.append(summary);
        const retry = document.createElement("button");
        retry.type = "button";
        retry.className = "source-folder-search-retry";
        retry.dataset.folderSearchRetrySourceId = source.id;
        retry.textContent = "搜索失败，重试";
        retry.title = `重新搜索${source.displayName}中的文件夹`;
        retry.setAttribute("aria-label", `重新搜索${source.displayName}中的文件夹`);
        configurePersistentHelp(retry, {
          title: "搜索失败，重试",
          detail: `使用保留的原查询重新搜索${source.displayName}；普通目录树和当前图库范围保持不变。`,
          kind: "source",
          owner: `folder-search-retry:${source.id}`,
        });
        results.append(retry);
      } else if (search.folders.length) {
        summary.textContent = search.totalCount > search.folders.length
          ? `搜索结果 ${search.folders.length} / ${search.totalCount} · 请缩小范围`
          : `搜索结果 ${search.folders.length} 项`;
        results.append(summary);
        appendFolderRows(results, source.id, search.folders, 0, { search: true });
      } else {
        summary.textContent = "没有匹配的文件夹";
      }
      if (!results.contains(summary)) results.append(summary);
      tree.append(results);
    }
  }
  appendFolderBranch(tree, source.id, null, root, 0);
  return tree;
}

function sourceSidebarNodeKey(node) {
  if (!(node instanceof HTMLElement)) return null;
  if (node.dataset.sourceId !== undefined) return `source:${node.dataset.sourceId}`;
  if (node.dataset.folderTreeSourceId) {
    return `tree:${node.dataset.folderTreeSourceId}`;
  }
  if (node.dataset.folderSearchSourceId) {
    return `search:${node.dataset.folderSearchSourceId}`;
  }
  if (node.dataset.folderSearchSubmitSourceId) {
    return `search-submit:${node.dataset.folderSearchSubmitSourceId}`;
  }
  if (node.dataset.folderSearchRetrySourceId) {
    return `search-retry:${node.dataset.folderSearchRetrySourceId}`;
  }
  if (node.dataset.folderPath && node.dataset.folderSourceId) {
    const surface = node.dataset.folderSearchResult === "true" ? "search" : "tree";
    return `folder:${surface}:${node.dataset.folderSourceId}:${node.dataset.folderPath}`;
  }
  if (node.dataset.folderLoadMore) return `more:${node.dataset.folderLoadMore}`;
  if (node.dataset.folderRetrySourceId) {
    return `retry:${node.dataset.folderRetrySourceId}:`
      + `${node.dataset.folderRetryParentPath || "root"}`;
  }
  if (node.dataset.folderSourceToggle) {
    return `source-toggle:${node.dataset.folderSourceToggle}`;
  }
  if (node.dataset.folderToggle) return `folder-toggle:${node.dataset.folderToggle}`;
  const stableClass = [
    "source-folder-capacity",
    "source-folder-search-controls",
    "source-folder-search-results",
    "source-folder-search-summary",
    "sidebar-icon",
    "sidebar-count",
    "folder-disclosure",
    "folder-name",
  ].find((className) => node.classList.contains(className));
  return stableClass ? `class:${stableClass}` : null;
}

function sourceSidebarNodesCanReconcile(existing, desired) {
  if (existing.nodeType !== desired.nodeType) return false;
  if (existing.nodeType === Node.TEXT_NODE) return true;
  if (!(existing instanceof HTMLElement) || !(desired instanceof HTMLElement)) return false;
  if (existing.tagName !== desired.tagName) return false;
  const desiredKey = sourceSidebarNodeKey(desired);
  const existingKey = sourceSidebarNodeKey(existing);
  return desiredKey ? existingKey === desiredKey : !existingKey;
}

function syncSourceSidebarAttributes(existing, desired) {
  const desiredNames = new Set([...desired.attributes].map((attribute) => attribute.name));
  for (const attribute of [...existing.attributes]) {
    if (!desiredNames.has(attribute.name)) existing.removeAttribute(attribute.name);
  }
  for (const attribute of desired.attributes) {
    if (existing.getAttribute(attribute.name) !== attribute.value) {
      existing.setAttribute(attribute.name, attribute.value);
    }
  }
  if (existing instanceof HTMLInputElement && desired instanceof HTMLInputElement) {
    if (existing.value !== desired.value) existing.value = desired.value;
    existing.disabled = desired.disabled;
  }
  if (existing instanceof HTMLButtonElement && desired instanceof HTMLButtonElement) {
    existing.disabled = desired.disabled;
    existing.draggable = desired.draggable;
  }
}

function syncSourceSidebarNode(existing, desired) {
  if (existing.nodeType === Node.TEXT_NODE) {
    if (existing.nodeValue !== desired.nodeValue) existing.nodeValue = desired.nodeValue;
    return existing;
  }
  syncSourceSidebarAttributes(existing, desired);
  reconcileSourceSidebarChildren(existing, [...desired.childNodes]);
  return existing;
}

function reconcileSourceSidebarChildren(container, desiredChildren) {
  const existingChildren = [...container.childNodes];
  const used = new Set();
  for (const [index, desired] of desiredChildren.entries()) {
    const desiredKey = sourceSidebarNodeKey(desired);
    let existing = null;
    if (desiredKey) {
      existing = existingChildren.find((candidate) =>
        !used.has(candidate) && sourceSidebarNodeKey(candidate) === desiredKey
      ) || null;
    } else {
      const candidate = existingChildren[index];
      if (candidate && !used.has(candidate)
        && sourceSidebarNodesCanReconcile(candidate, desired)) {
        existing = candidate;
      }
    }
    const child = existing ? syncSourceSidebarNode(existing, desired) : desired;
    if (existing) used.add(existing);
    if (container.childNodes[index] !== child) {
      container.insertBefore(child, container.childNodes[index] || null);
    }
  }
  for (const child of existingChildren) {
    if (!used.has(child) && child.parentNode === container) child.remove();
  }
}

function renderSources() {
  const priorActive = elements.sourceList.contains(document.activeElement)
    ? document.activeElement
    : null;
  const priorFocus = captureFolderSidebarFocus();
  elements.sourceEmpty.classList.toggle("hidden", state.sources.length > 0);
  const galleryOverviewSelected = galleryOverviewIsOpen()
    && galleryOverviewUsesIntegratedLayout();
  const worldMapSelected = worldMapIsOpen() && worldMapUsesIntegratedLayout();
  const reviewSelected = reviewWorkspaceIsOpen() && reviewWorkspaceUsesIntegratedLayout();
  const trainingSelected = trainingWorkspaceIsOpen() && trainingWorkspaceUsesIntegratedLayout();
  const slimmingSelected = slimmingWorkspaceIsOpen() && slimmingWorkspaceUsesIntegratedLayout();
  const integratedWorkspaceSelected = galleryOverviewSelected
    || worldMapSelected
    || reviewSelected
    || trainingSelected
    || slimmingSelected;
  const desiredSources = document.createDocumentFragment();

  for (const source of orderedSources()) {
    const button = document.createElement("button");
    button.type = "button";
    button.className = "sidebar-row";
    button.dataset.sourceId = source.id;
    button.draggable = true;
    button.setAttribute("role", "treeitem");
    button.setAttribute("aria-level", "1");
    button.setAttribute(
      "aria-keyshortcuts",
      "ArrowUp ArrowDown PageUp PageDown Home End "
        + "Alt+ArrowUp Alt+ArrowDown Shift+F10 ContextMenu"
    );
    button.setAttribute("aria-haspopup", "menu");
    button.title = "拖动可调整顺序；右键、触控长按或 Shift-F10 查看来源操作";
    button.dataset.helpTitle = source.displayName;
    button.dataset.helpKind = "source";
    button.dataset.helpDetail = sourceSidebarHelpDetail(source);
    button.classList.toggle(
      "selected",
      !integratedWorkspaceSelected
        && state.libraryScope === "all"
        && state.selectedSourceID === source.id
    );
    if (!integratedWorkspaceSelected
      && state.libraryScope === "all"
      && state.selectedSourceID === source.id) {
      button.setAttribute("aria-current", "page");
    }
    button.setAttribute("aria-selected", String(
      !integratedWorkspaceSelected
        && state.libraryScope === "all"
        && state.selectedSourceID === source.id
    ));
    button.classList.toggle("unavailable", source.state !== "active");

    const icon = document.createElement("span");
    icon.className = "sidebar-icon";
    icon.setAttribute("aria-hidden", "true");
    if (folderSourceSupportsHierarchy(source)) {
      const expanded = state.folderNavigation.expanded.has(folderScopeKey(source.id));
      icon.dataset.folderSourceToggle = source.id;
      icon.textContent = expanded ? "▾" : "▸";
      button.setAttribute("aria-expanded", String(expanded));
      button.setAttribute(
        "aria-keyshortcuts",
        "ArrowLeft ArrowRight ArrowUp ArrowDown PageUp PageDown Home End "
          + "Alt+ArrowUp Alt+ArrowDown Shift+F10 ContextMenu"
      );
      if (expanded) {
        button.setAttribute("aria-controls", `source-folder-tree-${source.id}`);
        button.setAttribute("aria-owns", `source-folder-tree-${source.id}`);
      }
    } else {
      icon.textContent = sourceIcon(source.kind);
    }
    const name = document.createElement("span");
    name.textContent = source.displayName;
    const status = document.createElement("span");
    status.className = "sidebar-count";
    status.textContent = sourceStateText(source.state);
    button.append(icon, name, status);
    desiredSources.append(button);
    if (folderSourceSupportsHierarchy(source)
      && state.folderNavigation.expanded.has(folderScopeKey(source.id))) {
      desiredSources.append(appendSourceFolderTree(source));
    }
  }
  reconcileSourceSidebarChildren(elements.sourceList, [...desiredSources.childNodes]);

  const allMediaButton = document.querySelector('[data-source-id=""]');
  const allMediaSelected = !integratedWorkspaceSelected
    && state.libraryScope === "all"
    && state.selectedSourceID === "";
  allMediaButton?.classList.toggle("selected", allMediaSelected);
  if (allMediaSelected) allMediaButton?.setAttribute("aria-current", "page");
  else allMediaButton?.removeAttribute("aria-current");
  elements.favoritesNavigationButton.classList.toggle("hidden", !supportsFavorites());
  elements.favoritesNavigationButton.classList.toggle(
    "selected",
    !integratedWorkspaceSelected && state.libraryScope === "favorites"
  );
  if (!integratedWorkspaceSelected && state.libraryScope === "favorites") {
    elements.favoritesNavigationButton.setAttribute("aria-current", "page");
  } else {
    elements.favoritesNavigationButton.removeAttribute("aria-current");
  }
  elements.galleryOverviewNavigationButton.classList.toggle(
    "selected",
    galleryOverviewSelected
  );
  if (galleryOverviewSelected) {
    elements.galleryOverviewNavigationButton.setAttribute("aria-current", "page");
  } else {
    elements.galleryOverviewNavigationButton.removeAttribute("aria-current");
  }
  elements.worldMapNavigationButton.classList.toggle("selected", worldMapSelected);
  if (worldMapSelected) {
    elements.worldMapNavigationButton.setAttribute("aria-current", "page");
  } else {
    elements.worldMapNavigationButton.removeAttribute("aria-current");
  }
  elements.reviewNavigationButton.classList.toggle("selected", reviewSelected);
  if (reviewSelected) {
    elements.reviewNavigationButton.setAttribute("aria-current", "page");
  } else {
    elements.reviewNavigationButton.removeAttribute("aria-current");
  }
  elements.trainingNavigationButton.classList.toggle("selected", trainingSelected);
  if (trainingSelected) {
    elements.trainingNavigationButton.setAttribute("aria-current", "page");
  } else {
    elements.trainingNavigationButton.removeAttribute("aria-current");
  }
  elements.slimmingNavigationButton.classList.toggle("selected", slimmingSelected);
  if (slimmingSelected) {
    elements.slimmingNavigationButton.setAttribute("aria-current", "page");
  } else {
    elements.slimmingNavigationButton.removeAttribute("aria-current");
  }
  renderSidebarSourceActions();
  syncCurrentSourceRefreshControl();
  if (priorFocus && (!priorActive?.isConnected || document.activeElement !== priorActive)) {
    restoreFolderSidebarFocus(priorFocus);
  }
}

function sidebarPrimaryNavigationItems() {
  return [...elements.sourceSidebar.querySelectorAll([
    "#libraryNavigation .sidebar-row:not(.hidden):not(:disabled)",
    "#sourceList .sidebar-row:not(.hidden):not(:disabled)",
    "#sourceList .source-folder-row:not(.hidden):not(:disabled)",
    "#sourceList .source-folder-more:not(.hidden):not(:disabled)",
    "#sourceList .source-folder-retry:not(.hidden):not(:disabled)",
    "#sourceList .source-folder-search-retry:not(.hidden):not(:disabled)",
    "#sidebarSourceActions button:not(.hidden):not(:disabled)",
  ].join(", "))].filter((item) => item.offsetParent !== null);
}

function moveSidebarPrimaryNavigation(event) {
  if (event.altKey || event.metaKey || event.ctrlKey) return false;
  if (!["ArrowUp", "ArrowDown", "PageUp", "PageDown", "Home", "End"].includes(
    event.key
  )) return false;
  const current = event.target.closest(
    "#libraryNavigation .sidebar-row, #sourceList .sidebar-row, "
      + "#sourceList .source-folder-row, #sourceList .source-folder-more, "
      + "#sourceList .source-folder-retry, #sourceList .source-folder-search-retry, "
      + "#sidebarSourceActions button"
  );
  if (!current) return false;
  const items = sidebarPrimaryNavigationItems();
  const currentIndex = items.indexOf(current);
  if (currentIndex < 0 || !items.length) return false;
  const nextIndex = longListNavigationTarget(
    items,
    currentIndex,
    event.key,
    elements.sourceSidebar
  );
  event.preventDefault();
  event.stopPropagation();
  items[nextIndex].focus({ preventScroll: true });
  items[nextIndex].scrollIntoView({ block: "nearest" });
  return true;
}

function focusCurrentSidebarPrimaryNavigation() {
  const items = sidebarPrimaryNavigationItems();
  const current = items.find((item) => item.getAttribute("aria-current") === "page")
    || items.find((item) => item.classList.contains("selected"))
    || items[0];
  current?.focus({ preventScroll: true });
  current?.scrollIntoView({ block: "nearest" });
}

function focusSidebarSource(sourceID) {
  requestAnimationFrame(() => {
    elements.sourceList.querySelector(`[data-source-id="${CSS.escape(sourceID)}"]`)
      ?.focus({ preventScroll: true });
  });
}

function folderTreeRow(sourceID, relativePath) {
  return [...elements.sourceList.querySelectorAll(
    `[data-folder-source-id="${CSS.escape(sourceID)}"]`
      + ":not([data-folder-search-result])"
  )].find((row) => row.dataset.folderPath === relativePath) || null;
}

function firstFolderTreeChild(sourceID, parentRelativePath = null) {
  const expectedParent = parentRelativePath || "";
  return [...elements.sourceList.querySelectorAll(
    `[data-folder-source-id="${CSS.escape(sourceID)}"]`
      + ":not([data-folder-search-result])"
  )].find((row) => row.dataset.folderParentPath === expectedParent) || null;
}

function focusFolderTreeParent(sourceID, parentRelativePath = null) {
  const target = parentRelativePath
    ? folderTreeRow(sourceID, parentRelativePath)
    : elements.sourceList.querySelector(
      `[data-source-id="${CSS.escape(sourceID)}"]`
    );
  target?.focus({ preventScroll: true });
  target?.scrollIntoView({ block: "nearest" });
}

function moveFolderTreeHorizontalNavigation(event) {
  if (event.altKey || event.metaKey || event.ctrlKey
    || !["ArrowRight", "ArrowLeft"].includes(event.key)) return false;
  const folderRow = event.target.closest(
    "[data-folder-path]:not([data-folder-search-result])"
  );
  const sourceRow = event.target.closest("[data-source-id]");
  const sourceID = folderRow?.dataset.folderSourceId || sourceRow?.dataset.sourceId;
  const source = state.sources.find((candidate) => candidate.id === sourceID);
  if (!sourceID || !folderSourceSupportsHierarchy(source)) return false;
  const relativePath = folderRow?.dataset.folderPath || null;
  const key = folderScopeKey(sourceID, relativePath || "");
  const expanded = state.folderNavigation.expanded.has(key);

  if (event.key === "ArrowRight") {
    event.preventDefault();
    event.stopPropagation();
    if (!expanded) {
      state.folderNavigation.expanded.add(key);
      if (folderBranch(sourceID, relativePath)) renderSources();
      else void loadFolderBranch(sourceID, relativePath);
      return true;
    }
    const child = firstFolderTreeChild(sourceID, relativePath);
    if (child) {
      child.focus({ preventScroll: true });
      child.scrollIntoView({ block: "nearest" });
    } else if (!folderBranch(sourceID, relativePath)) {
      void loadFolderBranch(sourceID, relativePath);
    }
    return true;
  }

  if (expanded) {
    event.preventDefault();
    event.stopPropagation();
    state.folderNavigation.expanded.delete(key);
    renderSources();
    return true;
  }
  if (folderRow) {
    event.preventDefault();
    event.stopPropagation();
    focusFolderTreeParent(sourceID, folderRow.dataset.folderParentPath || null);
    return true;
  }
  return false;
}

function focusSidebarTag(tagID) {
  requestAnimationFrame(() => {
    elements.tagNavigation.querySelector(`[data-quick-tag-id="${CSS.escape(tagID)}"]`)
      ?.focus({ preventScroll: true });
  });
}

function focusTagOrderingSurface(tagID, surface = "sidebar") {
  if (surface === "sidebar") {
    focusSidebarTag(tagID);
    return;
  }
  // The selection aggregate request can repaint this surface shortly after a
  // drag completes. Keep recovering the same logical chip for a bounded
  // window so the later repaint neither drops keyboard focus nor makes the
  // next command target a detached element.
  let remainingFrames = 120;
  let hasRestored = false;
  const restore = () => {
    const container = surface === "selection"
      ? elements.selectionInspectorTags
      : surface === "placeholder"
        ? elements.inspectorPlaceholderTags
        : surface === "review"
          ? elements.reviewTags
          : elements.inspectorTags;
    const target = container.querySelector(
      `[data-tag-reorder-surface="${CSS.escape(surface)}"]`
        + `[data-tag-id="${CSS.escape(tagID)}"]`
    );
    const active = document.activeElement;
    if (hasRestored
      && active !== document.body
      && active !== document.documentElement
      && active !== target) return;
    if (target && active !== target) {
      target.focus({ preventScroll: true });
      hasRestored = true;
    }
    remainingFrames -= 1;
    if (remainingFrames > 0) requestAnimationFrame(restore);
  };
  requestAnimationFrame(restore);
}

function renderTagOrderingSurfaces(focusTagID = null, focusSurface = "sidebar") {
  renderTagSelects();
  if (state.selectionMode && state.selectedAssetIDs.size) {
    renderSelectionInspector();
  } else if (state.selectedDetail) {
    renderInspector(state.selectedDetail);
  }
  if (state.review.mode === "queue" && reviewWorkspaceIsOpen()) renderReviewDetail();
  if (focusTagID) focusTagOrderingSurface(focusTagID, focusSurface);
}

function applySourceOrder(sourceIDs, focusSourceID) {
  state.layout.sourceOrderIDs = sourceIDs;
  persistWorkspacePreferences();
  renderSources();
  focusSidebarSource(focusSourceID);
}

function reorderSourceBefore(sourceID, beforeSourceID) {
  const ids = orderedSources().map((source) => source.id);
  const reordered = moveIDBefore(ids, sourceID, beforeSourceID);
  if (reordered.join("|") === ids.join("|")) return;
  applySourceOrder(reordered, sourceID);
}

function reorderSourceByOffset(sourceID, offset) {
  const ids = orderedSources().map((source) => source.id);
  const reordered = moveIDByOffset(ids, sourceID, offset);
  if (reordered.join("|") === ids.join("|")) return;
  applySourceOrder(reordered, sourceID);
}

function tagIDsForGroup(groupID) {
  return orderedTagsInGroup(
    activeTags().filter((tag) => (tag.groupID || "") === (groupID || "")),
    groupID || null
  ).map((tag) => tag.id);
}

function applyLocalTagOrder(groupID, ids) {
  state.layout.tagOrderIDsByGroup = {
    ...state.layout.tagOrderIDsByGroup,
    [tagOrderPreferenceKey(groupID)]: ids,
  };
  persistWorkspacePreferences();
}

function tagReorderSearchActive(surface) {
  if (surface === "single") return Boolean(state.inspectorTagSearchText.trim());
  if (surface === "selection") return Boolean(state.selectionTagSearchText.trim());
  if (surface === "review") return Boolean(state.review.tagSearchText.trim());
  if (surface === "placeholder") return false;
  return Boolean(elements.tagNavigationSearch.value.trim());
}

async function moveSidebarTag(
  tagID,
  targetGroupID,
  beforeTagID = null,
  focusSurface = "sidebar"
) {
  const tag = tagByID(tagID);
  if (!tag || state.tagManagementMutating || tagReorderSearchActive(focusSurface)) return;
  const currentGroupID = tag.groupID || "";
  const normalizedTargetGroupID = targetGroupID || "";
  if (currentGroupID === normalizedTargetGroupID) {
    const ids = tagIDsForGroup(currentGroupID);
    const reordered = moveIDBefore(ids, tagID, beforeTagID);
    if (reordered.join("|") === ids.join("|")) {
      focusTagOrderingSurface(tagID, focusSurface);
      return;
    }
    applyLocalTagOrder(currentGroupID, reordered);
    renderTagOrderingSurfaces(tagID, focusSurface);
    return;
  }
  const targetGroup = groupByID(normalizedTargetGroupID);
  if (!targetGroup) return;

  const previousOrders = structuredClone(state.layout.tagOrderIDsByGroup);
  const previousGroupID = currentGroupID;
  const sourceIDs = tagIDsForGroup(currentGroupID).filter((id) => id !== tagID);
  const targetIDs = moveIDBefore(tagIDsForGroup(normalizedTargetGroupID), tagID, beforeTagID);
  applyLocalTagOrder(currentGroupID, sourceIDs);
  applyLocalTagOrder(normalizedTargetGroupID, targetIDs);
  tag.groupID = normalizedTargetGroupID;
  renderTagOrderingSurfaces(tagID, focusSurface);

  const succeeded = await performTagCatalogMutation(
    `/v1/tags/${tag.id}/move`,
    { operationID: crypto.randomUUID(), groupID: normalizedTargetGroupID },
    `已将“${tag.displayName}”移动到“${targetGroup.displayName}”`
  );
  if (succeeded) {
    renderTagOrderingSurfaces(tagID, focusSurface);
    return;
  }
  const currentTag = tagByID(tagID);
  if (currentTag) currentTag.groupID = previousGroupID;
  state.layout.tagOrderIDsByGroup = previousOrders;
  persistWorkspacePreferences();
  renderTagOrderingSurfaces(tagID, focusSurface);
}

function reorderSidebarTagByOffset(tagID, offset, focusSurface = "sidebar") {
  const tag = tagByID(tagID);
  if (!tag || tagReorderSearchActive(focusSurface)) return;
  const groupID = tag.groupID || "";
  const ids = tagIDsForGroup(groupID);
  const reordered = moveIDByOffset(ids, tagID, offset);
  if (reordered.join("|") === ids.join("|")) return;
  applyLocalTagOrder(groupID, reordered);
  renderTagOrderingSurfaces(tagID, focusSurface);
}

function moveSidebarTagToAdjacentGroup(tagID, offset, focusSurface = "sidebar") {
  const tag = tagByID(tagID);
  if (!tag || tagReorderSearchActive(focusSurface)) return;
  const groups = orderedTagGroups();
  const currentIndex = groups.findIndex((group) => group.id === tag.groupID);
  const target = groups[currentIndex + offset];
  if (!target) return;
  moveSidebarTag(tagID, target.id, null, focusSurface);
}

function clearSidebarDropIndicators() {
  state.sidebarDrag.dropTarget?.classList.remove(
    "drop-before",
    "drop-after",
    "drag-over-group"
  );
  state.sidebarDrag.dropTarget = null;
  elements.sourceList.querySelectorAll(".drop-before, .drop-after").forEach((item) => {
    item.classList.remove("drop-before", "drop-after");
  });
  elements.tagNavigation.querySelectorAll(
    ".drop-before, .drop-after, .drag-over-group"
  ).forEach((item) => {
    item.classList.remove("drop-before", "drop-after", "drag-over-group");
  });
  [
    elements.inspectorTags,
    elements.selectionInspectorTags,
    elements.inspectorPlaceholderTags,
  ].forEach((container) => {
    container.querySelectorAll(
      ".drop-before, .drop-after, .drag-over-group"
    ).forEach((item) => {
      item.classList.remove("drop-before", "drop-after", "drag-over-group");
    });
  });
}

function sourceManagementActions(source) {
  const prewarm = ["active", "unavailable"].includes(source.state)
    ? ["prewarmThumbnails", "prewarmOriginalAspect"]
    : [];
  if (source.kind === "photos") {
    if (source.state === "active") {
      return [
        "syncPhotos",
        ...prewarm,
        "fullRepair",
        "requestPhotosWriteAuthorization",
        "delete",
      ];
    }
    if (source.state === "unavailable") return ["rebindPhotos", ...prewarm, "delete"];
    if (["authorizationRequired", "disabled"].includes(source.state)) {
      return ["reauthorize", "openPhotosPrivacySettings", "delete"];
    }
    return ["delete"];
  }
  if (source.state === "active") {
    return ["rescan", ...prewarm, "refreshFolderMutationAuthorization", "delete"];
  }
  if (source.state === "unavailable") {
    return ["reauthorize", ...prewarm, "delete"];
  }
  if (source.state === "authorizationRequired") {
    return ["reauthorize", "delete"];
  }
  return ["delete"];
}

function supportsGeneralSettings() {
  return state.capabilities?.capabilities?.includes("generalSettings") === true;
}

function supportsWorkspaceNotices() {
  return state.capabilities?.capabilities?.includes("workspaceNotices") === true;
}

function supportsLibrarySlimming() {
  return state.capabilities?.capabilities?.includes("librarySlimming") === true;
}

function setWorkspaceNoticeText(element, text) {
  if (element.textContent !== text) element.textContent = text;
}

function setWorkspaceNoticeAttribute(element, name, value) {
  if (element.getAttribute(name) !== value) element.setAttribute(name, value);
}

function workspaceNoticeVisibleActions(notice) {
  const actions = Array.isArray(notice?.actions) ? notice.actions : [];
  return actions.filter((action) => (
    action?.id && ["undoTagMutation", "openRecycleBin"].includes(action.kind)
  ));
}

function syncWorkspaceNoticeActionButton(button, action) {
  if (!button) {
    button = document.createElement("button");
    button.type = "button";
    button.className = "button button-plain workspace-notice-action";
    button.addEventListener("click", () => {
      void performWorkspaceNoticeAction(button.dataset.workspaceNoticeActionId);
    });
  }
  if (button.dataset.workspaceNoticeActionId !== action.id) {
    button.dataset.workspaceNoticeActionId = action.id;
  }
  const isActive = state.workspaceNotice.activeActionID === action.id;
  setWorkspaceNoticeText(button, isActive ? "正在处理…" : (action.title || "执行"));
  const disabled = state.workspaceNotice.dismissing
    || Boolean(state.workspaceNotice.activeActionID)
    || !state.online;
  if (button.disabled !== disabled) button.disabled = disabled;
  setWorkspaceNoticeAttribute(
    button,
    "aria-label",
    action.title || "执行状态提示操作"
  );
  return button;
}

function workspaceNoticeFocusTarget(actionID = null) {
  const preferred = actionID
    ? elements.workspaceNoticeActions.querySelector(
      `[data-workspace-notice-action-id="${CSS.escape(actionID)}"]`
    )
    : null;
  if (preferred && !preferred.disabled) return preferred;
  return elements.workspaceNoticeActions.querySelector("button:not(:disabled)")
    || (!elements.dismissWorkspaceNoticeButton.disabled
      ? elements.dismissWorkspaceNoticeButton
      : elements.refreshButton);
}

function renderWorkspaceNotice() {
  const notice = state.workspaceNotice.notice;
  const focusedActionID = document.activeElement?.dataset?.workspaceNoticeActionId || null;
  elements.workspaceNoticeBanner.classList.toggle("hidden", !notice);
  if (!notice) {
    elements.workspaceNoticeBanner.removeAttribute("data-severity");
    setWorkspaceNoticeText(elements.workspaceNoticeMessage, "");
    for (const button of [...elements.workspaceNoticeActions.children]) button.remove();
    if (elements.dismissWorkspaceNoticeButton.disabled) {
      elements.dismissWorkspaceNoticeButton.disabled = false;
    }
    setWorkspaceNoticeText(elements.dismissWorkspaceNoticeButton, "关闭");
    if (focusedActionID || state.workspaceNotice.pendingReturnActionID) {
      state.workspaceNotice.pendingReturnActionID = null;
      elements.refreshButton.focus({ preventScroll: true });
    }
    return;
  }
  const severity = ["information", "success", "warning"].includes(notice.severity)
    ? notice.severity
    : "warning";
  if (elements.workspaceNoticeBanner.dataset.severity !== severity) {
    elements.workspaceNoticeBanner.dataset.severity = severity;
  }
  setWorkspaceNoticeText(elements.workspaceNoticeIcon, {
    information: "i",
    success: "✓",
    warning: "!",
  }[severity]);
  setWorkspaceNoticeText(
    elements.workspaceNoticeMessage,
    notice.message || "Mac 状态已更新。"
  );

  const existing = new Map(
    [...elements.workspaceNoticeActions.querySelectorAll(
      ":scope > [data-workspace-notice-action-id]"
    )].map((button) => [button.dataset.workspaceNoticeActionId, button])
  );
  const wanted = workspaceNoticeVisibleActions(notice).map((action) => (
    syncWorkspaceNoticeActionButton(existing.get(action.id), action)
  ));
  for (const [index, button] of wanted.entries()) {
    if (elements.workspaceNoticeActions.children[index] !== button) {
      elements.workspaceNoticeActions.insertBefore(
        button,
        elements.workspaceNoticeActions.children[index] || null
      );
    }
  }
  for (const button of [...elements.workspaceNoticeActions.children]) {
    if (!wanted.includes(button)) button.remove();
  }
  const dismissDisabled = state.workspaceNotice.dismissing
    || Boolean(state.workspaceNotice.activeActionID);
  if (elements.dismissWorkspaceNoticeButton.disabled !== dismissDisabled) {
    elements.dismissWorkspaceNoticeButton.disabled = dismissDisabled;
  }
  setWorkspaceNoticeText(
    elements.dismissWorkspaceNoticeButton,
    state.workspaceNotice.dismissing ? "正在关闭…" : "关闭"
  );

  if (focusedActionID) {
    const focusedAction = elements.workspaceNoticeActions.querySelector(
      `[data-workspace-notice-action-id="${CSS.escape(focusedActionID)}"]`
    );
    if (document.activeElement !== focusedAction) {
      workspaceNoticeFocusTarget(focusedActionID)?.focus({ preventScroll: true });
    }
  }
  if (state.workspaceNotice.pendingReturnActionID
    && !state.workspaceNotice.activeActionID
    && !state.workspaceNotice.dismissing) {
    const pendingActionID = state.workspaceNotice.pendingReturnActionID;
    state.workspaceNotice.pendingReturnActionID = null;
    workspaceNoticeFocusTarget(pendingActionID)?.focus({ preventScroll: true });
  }
}

async function dismissWorkspaceNotice() {
  const notice = state.workspaceNotice.notice;
  if (!notice
    || state.workspaceNotice.dismissing
    || state.workspaceNotice.activeActionID
    || !state.online) return;
  const generation = ++state.workspaceNotice.requestGeneration;
  state.workspaceNotice.dismissing = true;
  renderWorkspaceNotice();
  try {
    const response = await api("/v1/workspace-notice/dismiss", {
      method: "POST",
      body: JSON.stringify({ noticeID: notice.id }),
    });
    if (generation !== state.workspaceNotice.requestGeneration) return;
    state.workspaceNotice.notice = response.notice || null;
    if (!response.dismissed && response.notice?.id !== notice.id) {
      toast("Mac 出现了更新的状态提示，已保留新提示");
    }
  } catch (error) {
    if (generation === state.workspaceNotice.requestGeneration) {
      toast(error.message || "无法关闭 Mac 状态提示");
    }
  } finally {
    if (generation === state.workspaceNotice.requestGeneration) {
      state.workspaceNotice.dismissing = false;
      renderWorkspaceNotice();
    }
  }
}

async function loadWorkspaceNotice({ quiet = false } = {}) {
  if (!supportsWorkspaceNotices()) return null;
  const generation = state.workspaceGeneration;
  try {
    const snapshot = await api("/v1/workspace-notice");
    if (generation !== state.workspaceGeneration) return null;
    if (!state.workspaceNotice.dismissing && !state.workspaceNotice.activeActionID) {
      state.workspaceNotice.notice = snapshot.notice || null;
      renderWorkspaceNotice();
    }
    return snapshot;
  } catch (error) {
    if (!quiet) toast(error.message || "无法读取 Mac 状态提示");
    return null;
  }
}

async function performWorkspaceNoticeAction(actionID) {
  const notice = state.workspaceNotice.notice;
  const action = notice?.actions?.find((candidate) => candidate.id === actionID);
  if (!notice || !action || state.workspaceNotice.dismissing
    || state.workspaceNotice.activeActionID || !state.online) return;
  const generation = ++state.workspaceNotice.requestGeneration;
  state.workspaceNotice.pendingReturnActionID = actionID;
  state.workspaceNotice.activeActionID = actionID;
  renderWorkspaceNotice();
  try {
    const response = await api("/v1/workspace-notice/action", {
      method: "POST",
      body: JSON.stringify({ noticeID: notice.id, actionID }),
    });
    if (generation !== state.workspaceNotice.requestGeneration) return;
    state.workspaceNotice.notice = response.notice || null;
    if (!response.performed) {
      const changed = response.notice?.id !== notice.id;
      toast(changed
        ? "Mac 出现了更新的状态提示，旧操作未执行"
        : "这项状态提示操作已不可用");
      return;
    }
    if (action.kind === "undoTagMutation") {
      await refreshWorkspace({
        quiet: true,
        kinds: ["assetsChanged", "tagsChanged", "reviewChanged"],
      });
      toast("已撤销最近一次标签操作");
    } else if (action.kind === "openRecycleBin") {
      state.workspaceNotice.pendingReturnActionID = null;
      state.slimming.view = "recycle";
      state.slimming.recycle.sourceID = action.sourceID || "";
      state.slimming.recycle.searchText = "";
      await openSlimmingWorkspace({
        returnTarget: {
          kind: "workspaceNoticeAction",
          actionID,
          sourceID: action.sourceID || null,
        },
      });
    }
  } catch (error) {
    if (generation === state.workspaceNotice.requestGeneration) {
      toast(error.message || "状态提示操作未完成");
    }
  } finally {
    if (generation === state.workspaceNotice.requestGeneration) {
      state.workspaceNotice.activeActionID = null;
      renderWorkspaceNotice();
    }
  }
}

function supportsFavorites() {
  return state.capabilities?.capabilities?.includes("favorites") === true;
}

function supportsLibrarySuggestions() {
  return state.capabilities?.capabilities?.includes("librarySuggestions") === true;
}

function supportsTrainingActivities() {
  return state.capabilities?.capabilities?.includes("trainingActivities") === true;
}

function supportsAssetLocalSuggestions() {
  return state.capabilities?.capabilities?.includes("assetLocalSuggestions") === true;
}

function supportsCloudPreviewLifecycle() {
  return state.capabilities?.capabilities?.includes("cloudPreviewLifecycle") === true;
}

function supportsSourceManagement() {
  return state.capabilities?.capabilities?.includes("sourceManagement") === true;
}

function renderSidebarSourceActions() {
  const snapshot = state.sourceManagement.snapshot;
  const sources = snapshot?.sources || state.sources;
  const activeRequest = sourceManagementActiveRequest();
  const busy = state.sourceManagement.loading
    || state.sourceManagement.submitting
    || Boolean(activeRequest);
  const photosSources = sources.filter((source) => source.kind === "photos");
  const activePhotosSource = photosSources.find((source) => source.state === "active");
  const canConnectPhotos = snapshot?.canConnectPhotos ?? photosSources.length === 0;

  elements.sidebarConnectFolderButton.disabled = !state.online || busy;
  elements.toolbarConnectFolderButton.disabled = !state.online || busy;
  elements.sidebarConnectPhotosButton.classList.toggle("hidden", photosSources.length > 0);
  elements.sidebarConnectPhotosButton.disabled = !state.online || busy || !canConnectPhotos;
  elements.sidebarPhotosConnectedStatus.classList.toggle("hidden", !activePhotosSource);
  elements.sidebarConnectFolderButton.title = busy
    ? "当前已有来源操作正在进行"
    : "在 Mac 上选择一个文件夹；ImageAll 只索引，不修改原文件";
  elements.sidebarConnectPhotosButton.title = canConnectPhotos
    ? "在 Mac 上确认并请求 Apple Photos 权限"
    : "已有 Apple Photos 来源；请在对应来源上恢复或重新绑定";
  renderSourceActionsMenu();
}

function sourceActionsFocusableButtons() {
  return [...elements.sourceActionsPopover.querySelectorAll("button:not(:disabled)")]
    .filter((button) => !button.classList.contains("hidden")
      && button.getClientRects().length > 0);
}

function tagActionsFocusableButtons() {
  return [...elements.tagActionsPopover.querySelectorAll("button:not(:disabled)")]
    .filter((button) => !button.classList.contains("hidden")
      && button.getClientRects().length > 0);
}

function renderTagActionsMenu() {
  const targetCount = currentTagTargetAssetIDs().length;
  const unavailable = !state.online || state.tagManagementMutating;
  elements.tagManagerButton.disabled = false;
  elements.tagActionsSummary.textContent = `${activeTags().length} 个标签 · ${state.tagGroups.length} 个分组`;
  elements.tagActionsNewGroupButton.disabled = unavailable;
  elements.tagActionsNewGroupButton.title = unavailable
    ? "等待 Mac 重新连接或当前标签操作完成"
    : "打开分组名称输入框；创建后立即出现在侧栏与检查器";
  elements.tagActionsInstallPresetsButton.disabled = unavailable || state.installingPresetTags;
  elements.tagActionsInstallPresetsButton.querySelector("span:last-child").textContent = state.installingPresetTags
    ? "正在添加常用标签…"
    : "添加常用标签";
  elements.tagActionsInstallPresetsButton.title = state.installingPresetTags
    ? "Mac 正在安装尚未存在的常用标签"
    : "只补充尚未存在的常用标签；不会分析照片或写入标签决定";
  elements.tagActionsNewTagButton.disabled = unavailable || targetCount === 0;
  elements.tagActionsNewTagButton.title = targetCount
    ? `为当前 ${mediaItemCountText(targetCount)}新建并确认标签`
    : `请先选择至少${mediaItemCountText(1)}`;
  elements.tagActionsOpenManagerButton.disabled = false;
  elements.tagActionsOpenManagerButton.title = state.online
    ? "查看、重命名、移动或归档标签，并管理分组"
    : "离线时仍可查看当前标签；写操作需等待 Mac 重新连接";
}

async function viewAllSourcesFromActionMenu() {
  await returnFromActionMenu({ restoreFocus: false });
  const alreadyShowingAll = visibleWorkspaceRoute() === "gallery"
    && state.libraryScope === "all"
    && state.selectedSourceID === "";
  if (alreadyShowingAll) {
    closeMobileSidebar({ restoreFocus: false });
  } else {
    await selectSource("");
  }
  const allMediaButton = document.querySelector('[data-source-id=""]');
  const target = mobileSidebarLayoutQuery.matches
    && !elements.sourceSidebar.classList.contains("open")
    ? elements.sidebarToggle
    : allMediaButton;
  restoreOverlayFocus(stableReturnFocusTarget(target, elements.sidebarToggle));
}

function openSourceActionsContextMenu(clientX, clientY) {
  openActionMenu("sourceActions");
  if (elements.sourceActionsPopover.classList.contains("hidden")) return;
  positionContextMenu(elements.sourceActionsPopover, clientX, clientY);
}

function openTagActionsContextMenu(clientX, clientY) {
  openActionMenu("tagActions");
  if (elements.tagActionsPopover.classList.contains("hidden")) return;
  positionContextMenu(elements.tagActionsPopover, clientX, clientY);
}

function renderSourceActionsMenu() {
  const manager = state.sourceManagement;
  const sources = manager.snapshot?.sources || state.sources;
  const activeRequest = sourceManagementActiveRequest();
  const busy = manager.loading || manager.submitting || Boolean(activeRequest);
  const activeSources = sources.filter((source) => source.state === "active");
  const prewarmSources = sources.filter(
    (source) => ["active", "unavailable"].includes(source.state)
  );
  const accessAuthorizationTargets = sources.filter((source) => (
    source.kind === "folder"
      ? ["unavailable", "authorizationRequired"].includes(source.state)
      : ["authorizationRequired", "disabled"].includes(source.state)
  ));
  const mutationAuthorizationTargets = sources.filter(
    (source) => source.kind === "folder" && source.state === "active"
  );
  const activePhotosSource = sources.find(
    (source) => source.kind === "photos" && source.state === "active"
  );
  const unavailable = !state.online || !supportsSourceManagement();

  elements.sourceAllActionsButton.disabled = false;
  elements.sourceAllActionsButton.title = !state.online
    ? "仍可返回全部照片；来源写操作需等待 Mac 重新连接"
    : supportsSourceManagement()
      ? "更新、缓存或批量处理来源"
      : "仍可返回全部照片；当前 Mac 版本不支持来源管理";
  elements.sourceActionsSummary.textContent = activeRequest?.message
    || (sources.length
      ? `${sources.length} 个已连接来源 · 操作由 Mac 执行`
      : manager.loading ? "正在读取 Mac 上的来源…" : "尚无已连接来源");
  elements.sourceActionsViewAllButton.disabled = false;
  elements.sourceActionsViewAllButton.title = visibleWorkspaceRoute() === "gallery"
    && state.libraryScope === "all"
    && state.selectedSourceID === ""
    ? "当前已在全部照片；关闭此菜单"
    : "回到全部照片；不会修改任何来源";

  elements.sourceActionsRefreshAllButton.disabled = unavailable
    || busy || activeSources.length === 0;
  elements.sourceActionsRefreshAllButton.title = activeSources.length
    ? `更新全部 ${activeSources.length} 个活跃来源`
    : "当前没有可更新的活跃来源";
  elements.sourceActionsPrewarmAllButton.disabled = unavailable
    || busy || prewarmSources.length === 0;
  elements.sourceActionsPrewarmAllButton.title = prewarmSources.length
    ? `检查 ${prewarmSources.length} 个来源并生成缺失的网格缩略图`
    : "当前没有可缓存的来源";
  elements.sourceActionsPrewarmAllOriginalButton.disabled = unavailable
    || busy || prewarmSources.length === 0;
  elements.sourceActionsPrewarmAllOriginalButton.title = prewarmSources.length
    ? `检查 ${prewarmSources.length} 个来源并生成缺失的原比例网格缓存`
    : "当前没有可缓存的来源";

  elements.sourceActionsReauthorizeAllButton.querySelector("span:last-child").textContent =
    `依次重新授权来源（${accessAuthorizationTargets.length}）…`;
  elements.sourceActionsRefreshMutationButton.querySelector("span:last-child").textContent =
    `依次更新文件夹回收权限（${mutationAuthorizationTargets.length}）…`;
  elements.sourceActionsReauthorizeAllButton.disabled = unavailable
    || busy || accessAuthorizationTargets.length === 0;
  elements.sourceActionsRefreshMutationButton.disabled = unavailable
    || busy || mutationAuthorizationTargets.length === 0;
  elements.sourceActionsReauthorizeAllButton.title =
    "按来源依次显示系统授权窗口；取消任意一次会停止后续来源";
  elements.sourceActionsRefreshMutationButton.title =
    "按文件夹依次确认回收权限；不会立即修改任何照片";
  elements.sourceActionsPhotosWriteButton.classList.toggle("hidden", !activePhotosSource);
  elements.sourceActionsPhotosWriteButton.disabled = unavailable || busy || !activePhotosSource;
  elements.sourceActionsPhotosWriteButton.dataset.sourceId = activePhotosSource?.id || "";
  elements.sourceActionsPhotosWriteButton.title =
    "Apple Photos 权限由系统图库统一管理，只需请求一次";
  elements.sourceActionsOpenManagerButton.disabled = unavailable;
}

function generalSettingsModelStateText(model) {
  return {
    disabled: "已关闭",
    validating: "正在校验",
    ready: "模型已就绪",
    unavailable: "模型不可用",
  }[model?.state] || "—";
}

function applyToolbarDisplayMode(mode) {
  const normalized = mode === "iconAndTitle" ? "iconAndTitle" : "iconOnly";
  elements.appView.dataset.toolbarDisplayMode = normalized;
  for (const button of elements.toolbarDisplayModeControl.querySelectorAll(
    "[data-toolbar-display-mode]"
  )) {
    const selected = button.dataset.toolbarDisplayMode === normalized;
    button.setAttribute("aria-checked", String(selected));
    button.tabIndex = selected ? 0 : -1;
  }
  scheduleAdaptiveToolbarSync();
  requestAnimationFrame(() => {
    syncPersonalModelToolbarPresentation();
    syncSelectionFavoriteToolbarPresentation();
  });
}

const suggestionThresholdMethodLabels = {
  featureKnn: "特征向量",
  personalCentroid: "个人模型",
  personalAdamW: "超级个人模型",
};

function formatSuggestionThreshold(value) {
  return Number.isFinite(Number(value)) ? Number(value).toFixed(2) : "0.00";
}

function suggestionThresholdSnapshot() {
  return state.generalSettings.snapshot?.suggestionThresholds || null;
}

function renderSuggestionThresholdDefaults(unavailable) {
  const thresholds = suggestionThresholdSnapshot();
  elements.generalSuggestionSection.classList.toggle("hidden", !thresholds);
  if (!thresholds) return;
  const defaults = new Map(thresholds.defaults.map((item) => [item.method, item.minScore]));
  for (const input of elements.generalSuggestionDefaults.querySelectorAll(
    "[data-suggestion-default]"
  )) {
    input.disabled = unavailable;
    if (document.activeElement !== input) {
      input.value = formatSuggestionThreshold(defaults.get(input.dataset.suggestionDefault));
    }
    input.dataset.persistedValue = formatSuggestionThreshold(
      defaults.get(input.dataset.suggestionDefault)
    );
  }
  for (const button of elements.generalSuggestionDefaults.querySelectorAll(
    "[data-suggestion-default-step]"
  )) {
    button.disabled = unavailable;
  }
  const overrideCount = thresholds.tags.reduce(
    (count, tag) => count + tag.methods.filter((method) => method.overrideMinScore != null).length,
    0
  );
  elements.suggestionOverrideCount.textContent = String(overrideCount);
  elements.suggestionOverridesButton.disabled = unavailable;
}

function suggestionDefaultFocusKey(target) {
  const control = target instanceof Element
    ? target.closest("[data-suggestion-default-focus][data-suggestion-default-method]")
    : null;
  if (!control) return null;
  return [
    control.dataset.suggestionDefaultFocus,
    control.dataset.suggestionDefaultMethod,
  ];
}

function suggestionDefaultFocusTarget(key) {
  if (!key) return null;
  const [kind, method] = key;
  return elements.generalSuggestionDefaults.querySelector(
    `[data-suggestion-default-focus="${CSS.escape(kind)}"]`
      + `[data-suggestion-default-method="${CSS.escape(method)}"]`
  );
}

function suggestionReferenceText(reference) {
  if (!reference) {
    return "暂无参考建议；至少需要同轨 5 个可追溯拒绝分数，或正负样本各 5 个。";
  }
  if (reference.acceptedSampleCount >= 5 && reference.rejectedSampleCount >= 5) {
    return `参考建议：${formatSuggestionThreshold(reference.minScore)}（${reference.acceptedSampleCount} 确认 / ${reference.rejectedSampleCount} 拒绝的中位分隔）`;
  }
  return `参考建议：${formatSuggestionThreshold(reference.minScore)}（最近 ${reference.rejectedSampleCount} 个拒绝分数的第 90 百分位）`;
}

function thresholdFocusSelector(target) {
  const control = target instanceof Element ? target.closest("[data-threshold-focus]") : null;
  if (!control) return null;
  return [
    control.dataset.thresholdFocus,
    control.dataset.thresholdTagId || "",
    control.dataset.thresholdMethod || "",
  ];
}

function restoreThresholdFocus(key, { onlyIfUnfocused = false } = {}) {
  if (!key) return null;
  const [kind, tagID, method] = key;
  const selector = `[data-threshold-focus="${CSS.escape(kind)}"]`
    + `[data-threshold-tag-id="${CSS.escape(tagID)}"]`
    + `[data-threshold-method="${CSS.escape(method)}"]`;
  const target = elements.suggestionThresholdList.querySelector(selector)
    || elements.suggestionThresholdList.querySelector(
      `[data-threshold-focus="input"]`
        + `[data-threshold-tag-id="${CSS.escape(tagID)}"]`
        + `[data-threshold-method="${CSS.escape(method)}"]`
    );
  if (!target) return null;
  requestAnimationFrame(() => {
    const active = document.activeElement;
    if (onlyIfUnfocused && active !== document.body && active !== document.documentElement) return;
    if (!target.disabled && document.contains(target)) target.focus({ preventScroll: true });
  });
  return target;
}

function suggestionThresholdTagRow(tagID) {
  return suggestionThresholdSnapshot()?.tags?.find((tag) => tag.tagID === tagID) || null;
}

function reviewThresholdFocusTarget(key) {
  if (!key) return null;
  const [kind, tagID, method] = key;
  const exact = elements.reviewOverviewGrid.querySelector(
    `[data-threshold-focus="${CSS.escape(kind)}"]`
      + `[data-threshold-tag-id="${CSS.escape(tagID)}"]`
      + `[data-threshold-method="${CSS.escape(method)}"]`
  );
  if (exact) return exact;
  return elements.reviewOverviewGrid.querySelector(
    `[data-threshold-focus="input"]`
      + `[data-threshold-tag-id="${CSS.escape(tagID)}"]`
      + `[data-threshold-method="${CSS.escape(method)}"]`
  ) || elements.reviewOverviewGrid.querySelector(
    `[data-review-control-tag-id="${CSS.escape(tagID)}"] > summary`
  );
}

function decorateReviewThresholdControl(control, kind, tagID, method) {
  control.dataset.thresholdFocus = kind;
  control.dataset.thresholdTagId = tagID;
  control.dataset.thresholdMethod = method;
  return control;
}

function reviewThresholdControlsUnavailable() {
  return state.generalSettings.loading
    || state.generalSettings.submitting
    || !state.online;
}

function syncReviewThresholdControlAvailability() {
  const unavailable = reviewThresholdControlsUnavailable();
  for (const control of elements.reviewOverviewGrid.querySelectorAll(
    "[data-threshold-focus]"
  )) {
    control.disabled = unavailable;
  }
}

function renderReviewThresholdControls(overview) {
  const tag = suggestionThresholdTagRow(overview.id);
  if (!tag) return null;
  const unavailable = reviewThresholdControlsUnavailable();
  const section = document.createElement("section");
  section.className = "review-thresholds";
  configurePersistentHelp(section, {
    title: `${overview.displayName} · 生效门槛`,
    detail: "三条建议轨道分别使用自己的最低分数；修改只影响之后保留的待审建议，不会重新扫描图库。",
    kind: "review",
  });
  const heading = document.createElement("div");
  heading.className = "review-thresholds-heading";
  const title = document.createElement("strong");
  title.textContent = "生效门槛";
  const hint = document.createElement("span");
  hint.textContent = "每条建议轨道独立设置";
  heading.append(title, hint);
  section.append(heading);

  for (const method of tag.methods || []) {
    const row = document.createElement("div");
    row.className = "review-threshold-row";
    const methodLabel = suggestionThresholdMethodLabels[method.method] || method.method;
    const label = document.createElement("span");
    label.className = "review-threshold-label";
    label.textContent = methodLabel;

    const editor = document.createElement("div");
    editor.className = "review-threshold-editor";
    const decrease = decorateReviewThresholdControl(
      document.createElement("button"), "decrease", tag.tagID, method.method
    );
    decrease.type = "button";
    decrease.textContent = "−";
    decrease.disabled = unavailable;
    decrease.dataset.reviewThresholdStep = "-0.05";
    decrease.setAttribute("aria-label", `${overview.displayName} ${methodLabel}门槛减少 0.05`);
    configurePersistentHelp(decrease, {
      title: `${methodLabel}门槛减少 0.05`,
      detail: `把“${overview.displayName}”的${methodLabel}最低分数降低 0.05；提交后只更新这条建议轨道。`,
      kind: "review",
    });

    const input = decorateReviewThresholdControl(
      document.createElement("input"), "input", tag.tagID, method.method
    );
    input.type = "number";
    input.inputMode = "decimal";
    input.step = "0.05";
    input.value = formatSuggestionThreshold(method.effectiveMinScore);
    input.dataset.persistedValue = input.value;
    input.disabled = unavailable;
    input.dataset.reviewThresholdInput = "true";
    input.setAttribute("aria-label", `${overview.displayName} ${methodLabel}最低门槛`);
    configurePersistentHelp(input, {
      title: `${methodLabel}最低门槛`,
      detail: `输入“${overview.displayName}”这条建议轨道的最低分数，按 Return 或离开输入框提交；不会重新扫描图库。`,
      kind: "review",
      keyShortcuts: "Enter",
    });

    const increase = decorateReviewThresholdControl(
      document.createElement("button"), "increase", tag.tagID, method.method
    );
    increase.type = "button";
    increase.textContent = "+";
    increase.disabled = unavailable;
    increase.dataset.reviewThresholdStep = "0.05";
    increase.setAttribute("aria-label", `${overview.displayName} ${methodLabel}门槛增加 0.05`);
    configurePersistentHelp(increase, {
      title: `${methodLabel}门槛增加 0.05`,
      detail: `把“${overview.displayName}”的${methodLabel}最低分数提高 0.05；提交后只更新这条建议轨道。`,
      kind: "review",
    });

    const prune = decorateReviewThresholdControl(
      document.createElement("button"), "prune", tag.tagID, method.method
    );
    prune.type = "button";
    prune.className = "button button-plain review-threshold-prune";
    prune.textContent = "刷新";
    prune.disabled = unavailable;
    prune.dataset.reviewThresholdAction = "prune";
    prune.title = "按当前门槛移除分数过低的待审建议；不会重新扫描图库";
    configurePersistentHelp(prune, {
      detail: `按当前${methodLabel}门槛清理“${overview.displayName}”分数过低的待审建议；不会重新扫描图库或改变其他轨道。`,
      kind: "review",
    });
    editor.append(decrease, input, increase, prune);

    const meta = document.createElement("div");
    meta.className = "review-threshold-meta";
    const badge = document.createElement("span");
    badge.className = `threshold-source-badge${method.overrideMinScore == null ? " inherited" : ""}`;
    badge.textContent = method.overrideMinScore == null ? "继承默认" : "单独设置";
    meta.append(badge);
    if (method.reference) {
      const reference = document.createElement("span");
      reference.textContent = `参考 ${formatSuggestionThreshold(method.reference.minScore)}`;
      reference.title = suggestionReferenceText(method.reference);
      const adopt = decorateReviewThresholdControl(
        document.createElement("button"), "adopt", tag.tagID, method.method
      );
      adopt.type = "button";
      adopt.className = "button button-plain";
      adopt.textContent = "采用";
      adopt.disabled = unavailable;
      adopt.dataset.reviewThresholdAction = "setOverride";
      adopt.dataset.thresholdScore = String(method.reference.minScore);
      configurePersistentHelp(adopt, {
        title: `采用${methodLabel}参考门槛`,
        detail: `采用根据近期样本计算的 ${formatSuggestionThreshold(method.reference.minScore)}；只覆盖“${overview.displayName}”这条建议轨道。`,
        kind: "review",
      });
      meta.append(reference, adopt);
    }
    if (method.overrideMinScore != null) {
      const inherit = decorateReviewThresholdControl(
        document.createElement("button"), "inherit", tag.tagID, method.method
      );
      inherit.type = "button";
      inherit.className = "button button-plain";
      inherit.textContent = "继承";
      inherit.disabled = unavailable;
      inherit.dataset.reviewThresholdAction = "clearOverride";
      configurePersistentHelp(inherit, {
        title: `继承${methodLabel}默认门槛`,
        detail: `移除“${overview.displayName}”的单独设置，恢复使用全局${methodLabel}门槛。`,
        kind: "review",
      });
      meta.append(inherit);
    }
    row.append(label, editor, meta);
    section.append(row);
  }
  return section;
}

function setSuggestionThresholdText(element, text) {
  if (element.textContent !== text) element.textContent = text;
}

function configureSuggestionThresholdControl(control, kind, tagID, method) {
  control.dataset.thresholdFocus = kind;
  control.dataset.thresholdTagId = tagID;
  control.dataset.thresholdMethod = method;
}

function createSuggestionThresholdMethod() {
  const block = document.createElement("div");
  block.className = "suggestion-threshold-method";
  const row = document.createElement("div");
  row.className = "suggestion-threshold-method-row";
  const editorGroup = document.createElement("div");
  editorGroup.className = "suggestion-threshold-method-editor-group";
  const labelText = document.createElement("span");
  labelText.className = "suggestion-threshold-method-label";
  const stepper = document.createElement("div");
  stepper.className = "suggestion-threshold-stepper";
  const decrease = document.createElement("button");
  decrease.type = "button";
  decrease.className = "threshold-step-button";
  decrease.dataset.thresholdStep = "-0.05";
  decrease.textContent = "−";
  const input = document.createElement("input");
  input.type = "number";
  input.inputMode = "decimal";
  input.step = "0.05";
  configureSuggestionThresholdControl(input, "input", "", "");
  const increase = document.createElement("button");
  increase.type = "button";
  increase.className = "threshold-step-button";
  increase.dataset.thresholdStep = "0.05";
  increase.textContent = "+";
  stepper.append(decrease, input, increase);
  editorGroup.append(labelText, stepper);
  const badge = document.createElement("span");
  badge.className = "threshold-source-badge";
  row.append(editorGroup, badge);
  const reference = document.createElement("div");
  reference.className = "suggestion-threshold-reference";
  reference.append(document.createElement("span"));
  block.append(row, reference);
  return block;
}

function suggestionThresholdActionButton(block, action, label) {
  let button = block.querySelector(`[data-threshold-action="${action}"]`);
  if (!button) {
    button = document.createElement("button");
    button.type = "button";
    button.className = "button button-small";
    button.dataset.thresholdAction = action;
  }
  setSuggestionThresholdText(button, label);
  return button;
}

function syncSuggestionThresholdMethod(block, tag, method, unavailable) {
  const methodName = suggestionThresholdMethodLabels[method.method] || method.method;
  block.dataset.thresholdMethod = method.method;
  const row = block.querySelector(":scope > .suggestion-threshold-method-row");
  const editorGroup = row.querySelector(":scope > .suggestion-threshold-method-editor-group");
  const labelText = editorGroup.querySelector(":scope > .suggestion-threshold-method-label");
  const stepper = editorGroup.querySelector(":scope > .suggestion-threshold-stepper");
  const input = stepper.querySelector(":scope > input");
  const badge = row.querySelector(":scope > .threshold-source-badge");
  setSuggestionThresholdText(labelText, methodName);
  configureSuggestionThresholdControl(input, "input", tag.tagID, method.method);
  const persistedValue = formatSuggestionThreshold(method.effectiveMinScore);
  const hasLocalDraft = input.dataset.persistedValue !== undefined
    && input.value !== input.dataset.persistedValue;
  if (!hasLocalDraft && input.value !== persistedValue) input.value = persistedValue;
  input.dataset.persistedValue = persistedValue;
  input.disabled = unavailable;
  input.setAttribute("aria-label", `${tag.displayName} ${methodName}最低门槛`);
  for (const [button, kind, direction] of [
    [stepper.querySelector('[data-threshold-step="-0.05"]'), "decrease", "减少"],
    [stepper.querySelector('[data-threshold-step="0.05"]'), "increase", "增加"],
  ]) {
    configureSuggestionThresholdControl(button, kind, tag.tagID, method.method);
    button.disabled = unavailable;
    button.setAttribute(
      "aria-label",
      `${tag.displayName} ${methodName}门槛${direction} 0.05`
    );
  }
  const inherited = method.overrideMinScore == null;
  const badgeClass = `threshold-source-badge${inherited ? " inherited" : ""}`;
  if (badge.className !== badgeClass) badge.className = badgeClass;
  setSuggestionThresholdText(badge, inherited ? "继承默认" : "单独设置");

  let inherit = null;
  if (!inherited) {
    inherit = suggestionThresholdActionButton(block, "clearOverride", "继承默认");
    inherit.disabled = unavailable;
    configureSuggestionThresholdControl(inherit, "inherit", tag.tagID, method.method);
  }
  reconcileStableChildren(row, [editorGroup, badge, inherit].filter(Boolean));

  const referenceRow = block.querySelector(":scope > .suggestion-threshold-reference");
  const referenceText = referenceRow.querySelector(":scope > span");
  const referenceClass = `suggestion-threshold-reference${method.reference ? "" : " unavailable"}`;
  if (referenceRow.className !== referenceClass) referenceRow.className = referenceClass;
  setSuggestionThresholdText(referenceText, suggestionReferenceText(method.reference));
  let adopt = null;
  if (method.reference) {
    adopt = suggestionThresholdActionButton(block, "setOverride", "采用");
    adopt.disabled = unavailable;
    adopt.dataset.thresholdScore = String(method.reference.minScore);
    configureSuggestionThresholdControl(adopt, "adopt", tag.tagID, method.method);
  }
  reconcileStableChildren(referenceRow, [referenceText, adopt].filter(Boolean));
}

function createSuggestionThresholdCard() {
  const card = document.createElement("section");
  card.className = "suggestion-threshold-card";
  card.append(document.createElement("h3"));
  return card;
}

function syncSuggestionThresholdCard(card, tag, unavailable) {
  card.dataset.thresholdTagId = tag.tagID;
  const title = card.querySelector(":scope > h3");
  setSuggestionThresholdText(title, tag.displayName);
  const existingMethods = new Map(
    [...card.querySelectorAll(":scope > [data-threshold-method]")]
      .map((block) => [block.dataset.thresholdMethod, block])
  );
  const methods = (tag.methods || []).map((method) => {
    const block = existingMethods.get(method.method) || createSuggestionThresholdMethod();
    existingMethods.delete(method.method);
    syncSuggestionThresholdMethod(block, tag, method, unavailable);
    return block;
  });
  reconcileStableChildren(card, [title, ...methods]);
}

function reconcileSuggestionThresholdCards(tags, unavailable) {
  const existingCards = new Map(
    [...elements.suggestionThresholdList.querySelectorAll(":scope > [data-threshold-tag-id]")]
      .map((card) => [card.dataset.thresholdTagId, card])
  );
  const cards = tags.map((tag) => {
    const card = existingCards.get(tag.tagID) || createSuggestionThresholdCard();
    existingCards.delete(tag.tagID);
    syncSuggestionThresholdCard(card, tag, unavailable);
    return card;
  });
  reconcileStableChildren(elements.suggestionThresholdList, cards);
}

function renderSuggestionThresholdDialog() {
  if (!elements.suggestionThresholdDialog.open) return;
  const manager = state.generalSettings;
  const thresholds = suggestionThresholdSnapshot();
  const unavailable = manager.loading || manager.submitting || !state.online || !thresholds;
  elements.suggestionThresholdDialog.setAttribute("aria-busy", String(manager.submitting));
  if (manager.submitting) {
    for (const control of elements.suggestionThresholdDialog.querySelectorAll("input, button")) {
      control.disabled = true;
    }
    return;
  }
  const activeFocusKey = thresholdFocusSelector(document.activeElement);
  if (unavailable && activeFocusKey) manager.pendingThresholdFocus = activeFocusKey;
  const active = document.activeElement;
  const canRestorePending = !activeFocusKey
    && Boolean(manager.pendingThresholdFocus)
    && (active === document.body || active === document.documentElement);
  const focusKey = activeFocusKey || (canRestorePending ? manager.pendingThresholdFocus : null);
  const query = elements.suggestionThresholdSearch.value.trim().toLocaleLowerCase();
  const tags = (thresholds?.tags || []).filter(
    (tag) => !query || tag.displayName.toLocaleLowerCase().includes(query)
  );
  elements.suggestionThresholdSummary.textContent = thresholds
    ? `显示 ${tags.length} / ${thresholds.tags.length} 个活动标签`
    : "这台 Mac 暂未提供建议阈值设置。";
  elements.suggestionThresholdEmpty.classList.toggle("hidden", tags.length > 0);
  reconcileSuggestionThresholdCards(tags, unavailable);
  for (const control of [elements.suggestionThresholdSearch, elements.suggestionThresholdCloseButton]) {
    control.disabled = unavailable && control !== elements.suggestionThresholdCloseButton;
  }
  const restoredTarget = restoreThresholdFocus(focusKey, {
    onlyIfUnfocused: canRestorePending,
  });
  if (!unavailable && canRestorePending && restoredTarget) {
    manager.pendingThresholdFocus = null;
  }
}

function renderGeneralSettings() {
  const manager = state.generalSettings;
  const snapshot = manager.snapshot;
  const unavailable = manager.loading || !state.online || !snapshot;
  renderReviewSuggestionLimit();
  syncReviewThresholdControlAvailability();
  elements.generalSettingsDialog.setAttribute("aria-busy", String(manager.submitting));
  elements.generalSettingsLoading.classList.toggle("hidden", Boolean(snapshot) || !manager.loading);
  elements.generalSettingsContent.classList.toggle("hidden", !snapshot);
  for (const button of elements.toolbarDisplayModeControl.querySelectorAll("button")) {
    button.disabled = unavailable;
  }
  elements.generalSettingsModelToggle.disabled = unavailable;
  elements.generalSettingsPrewarmToggle.disabled = unavailable;
  renderSuggestionThresholdDefaults(unavailable);
  if (!snapshot) {
    renderReviewLocalModelStatus();
    return;
  }

  applyToolbarDisplayMode(snapshot.toolbarDisplayMode);
  const model = snapshot.localModel;
  elements.generalSettingsModelToggle.setAttribute("aria-checked", String(model.isEnabled));
  elements.generalSettingsModelState.textContent = generalSettingsModelStateText(model);
  elements.generalSettingsModelName.textContent = model.modelName;
  elements.generalSettingsModelRuntime.textContent = model.runtimeName;
  elements.generalSettingsModelDetail.textContent = model.detail;
  elements.generalSettingsPrewarmToggle.setAttribute(
    "aria-checked",
    String(snapshot.idleThumbnailPrewarmEnabled)
  );
  const minutes = Math.max(1, Math.round(snapshot.idleThresholdSeconds / 60));
  elements.generalSettingsPrewarmDetail.textContent =
    `连续 ${minutes} 分钟无操作后，会在后台预热缩略图、特征向量与本地模型嵌入缓存；任意操作立即让路给浏览。`;
  renderSuggestionThresholdDialog();
  renderReviewLocalModelStatus();
}

async function loadGeneralSettings({ quiet = false } = {}) {
  if (!supportsGeneralSettings()) return;
  const manager = state.generalSettings;
  if (manager.loading || manager.submitting) return;
  const generation = ++manager.requestGeneration;
  manager.loading = true;
  if (!quiet) elements.generalSettingsError.classList.add("hidden");
  renderGeneralSettings();
  try {
    const snapshot = await api("/v1/settings/general");
    if (generation !== manager.requestGeneration) return;
    manager.snapshot = snapshot;
    applyToolbarDisplayMode(snapshot.toolbarDisplayMode);
  } catch (error) {
    if (generation !== manager.requestGeneration) return;
    if (!quiet || elements.generalSettingsDialog.open) {
      elements.generalSettingsError.textContent = error.message || "无法读取 Mac 通用设置";
      elements.generalSettingsError.classList.remove("hidden");
    }
  } finally {
    if (generation === manager.requestGeneration) {
      manager.loading = false;
      renderGeneralSettings();
    }
  }
}

async function submitGeneralSettingsPatch(patch) {
  const manager = state.generalSettings;
  if (!state.online || manager.loading || manager.submitting || !manager.snapshot) return false;
  manager.pendingDefaultFocus = suggestionDefaultFocusKey(document.activeElement);
  manager.pendingThresholdFocus = thresholdFocusSelector(document.activeElement);
  if (elements.reviewOverviewGrid.contains(document.activeElement)) {
    state.review.pendingThresholdFocus = manager.pendingThresholdFocus;
  }
  manager.submitting = true;
  elements.generalSettingsError.classList.add("hidden");
  elements.suggestionThresholdError.classList.add("hidden");
  renderGeneralSettings();
  let succeeded = false;
  try {
    const response = await api("/v1/settings/general", {
      method: "PUT",
      body: JSON.stringify({ operationID: crypto.randomUUID(), ...patch }),
    });
    manager.snapshot = response.settings;
    applyToolbarDisplayMode(response.settings.toolbarDisplayMode);
    succeeded = true;
  } catch (error) {
    const message = error.message || "Mac 未能保存通用设置";
    elements.generalSettingsError.textContent = message;
    elements.generalSettingsError.classList.remove("hidden");
    if (elements.suggestionThresholdDialog.open) {
      elements.suggestionThresholdError.textContent = message;
      elements.suggestionThresholdError.classList.remove("hidden");
    }
  } finally {
    manager.submitting = false;
    renderGeneralSettings();
    if (manager.pendingDefaultFocus) {
      restoreOverlayFocus(suggestionDefaultFocusTarget(manager.pendingDefaultFocus));
    }
    manager.pendingDefaultFocus = null;
    manager.pendingThresholdFocus = null;
  }
  return succeeded;
}

function commitSuggestionDefault(input) {
  const minScore = Number(input.value);
  if (!Number.isFinite(minScore)) {
    renderGeneralSettings();
    return;
  }
  input.value = formatSuggestionThreshold(minScore);
  if (input.value === input.dataset.persistedValue) return;
  submitGeneralSettingsPatch({
    suggestionThresholdMutation: {
      action: "setDefault",
      method: input.dataset.suggestionDefault,
      minScore,
    },
  });
}

function commitSuggestionOverride(input) {
  const minScore = Number(input.value);
  if (!Number.isFinite(minScore)) {
    renderSuggestionThresholdDialog();
    return;
  }
  input.value = formatSuggestionThreshold(minScore);
  if (input.value === input.dataset.persistedValue) return;
  submitGeneralSettingsPatch({
    suggestionThresholdMutation: {
      action: "setOverride",
      method: input.dataset.thresholdMethod,
      tagID: input.dataset.thresholdTagId,
      minScore,
    },
  });
}

function stepSuggestionThresholdInput(input, step) {
  if (!input || input.disabled || !Number.isFinite(step)) return false;
  const current = Number(input.value);
  const baseline = Number.isFinite(current) ? current : Number(input.dataset.persistedValue);
  if (!Number.isFinite(baseline)) return false;
  input.value = formatSuggestionThreshold(baseline + step);
  return true;
}

async function submitReviewThresholdMutation(mutation, successMessage) {
  const succeeded = await submitGeneralSettingsPatch({
    suggestionThresholdMutation: mutation,
  });
  if (!succeeded) {
    renderReviewOverview();
    toast("Mac 未能更新这个标签的建议门槛");
    return false;
  }
  if (mutation.action === "prune") {
    await loadReviewOverview();
  } else {
    renderReviewOverview();
  }
  if (successMessage) toast(successMessage);
  return true;
}

async function commitReviewThresholdInput(input) {
  const minScore = Number(input.value);
  if (!Number.isFinite(minScore)) {
    input.value = input.dataset.persistedValue || "0.00";
    return false;
  }
  input.value = formatSuggestionThreshold(minScore);
  if (input.value === input.dataset.persistedValue) return true;
  return submitReviewThresholdMutation({
    action: "setOverride",
    method: input.dataset.thresholdMethod,
    tagID: input.dataset.thresholdTagId,
    minScore,
  });
}

async function applyReviewThresholdAction(button) {
  const row = button.closest(".review-threshold-row");
  const input = row?.querySelector("[data-review-threshold-input]");
  if (button.dataset.reviewThresholdStep != null) {
    const current = Number(input?.value);
    const step = Number(button.dataset.reviewThresholdStep);
    if (!input || !Number.isFinite(current) || !Number.isFinite(step)) return;
    input.value = formatSuggestionThreshold(current + step);
    await commitReviewThresholdInput(input);
    return;
  }
  const action = button.dataset.reviewThresholdAction;
  if (!action) return;
  if (action === "prune" && input && input.value !== input.dataset.persistedValue) {
    const saved = await commitReviewThresholdInput(input);
    if (!saved) return;
  }
  const mutation = {
    action,
    method: button.dataset.thresholdMethod,
    tagID: button.dataset.thresholdTagId,
  };
  if (button.dataset.thresholdScore != null) {
    mutation.minScore = Number(button.dataset.thresholdScore);
  }
  const methodName = suggestionThresholdMethodLabels[mutation.method] || "建议";
  await submitReviewThresholdMutation(
    mutation,
    action === "prune" ? `已按当前${methodName}门槛刷新待审项` : null
  );
}

function generalSettingsBaseLevelFromHistory(context = {}) {
  return ["sidebar", "inspector", "lightbox"].includes(context.generalSettingsBaseLevel)
    ? context.generalSettingsBaseLevel
    : "workspace";
}

const GENERAL_SETTINGS_HISTORY_CONTROL_IDS = new Set([
  "generalSettingsCloseButton",
  "generalSettingsModelToggle",
  "generalSettingsPrewarmToggle",
  "suggestionOverridesButton",
]);
const GENERAL_SETTINGS_HISTORY_RETURN_IDS = new Set([
  "settingsButton",
  "compactToolbarMenuButton",
  "commandButton",
]);
const GENERAL_SETTINGS_HISTORY_DISPLAY_MODES = new Set([
  "iconOnly",
  "iconAndTitle",
]);
const SUGGESTION_THRESHOLD_HISTORY_METHODS = new Set([
  "featureKnn",
  "personalCentroid",
  "personalAdamW",
]);
const SUGGESTION_DEFAULT_HISTORY_FOCUS_KINDS = new Set([
  "input",
  "decrease",
  "increase",
]);
const SUGGESTION_THRESHOLD_HISTORY_FOCUS_KINDS = new Set([
  "input",
  "decrease",
  "increase",
  "inherit",
  "adopt",
]);
const SUGGESTION_THRESHOLD_HISTORY_CONTROL_IDS = new Set([
  "suggestionThresholdCloseButton",
  "suggestionThresholdSearch",
]);

function defaultGeneralSettingsHistoryFocus() {
  return { kind: "control", id: "generalSettingsCloseButton" };
}

function normalizedGeneralSettingsHistoryFocus(raw) {
  if (!raw || typeof raw !== "object") return defaultGeneralSettingsHistoryFocus();
  if (raw.kind === "control" && GENERAL_SETTINGS_HISTORY_CONTROL_IDS.has(raw.id)) {
    return { kind: "control", id: raw.id };
  }
  if (raw.kind === "toolbarDisplayMode"
    && GENERAL_SETTINGS_HISTORY_DISPLAY_MODES.has(raw.value)) {
    return { kind: "toolbarDisplayMode", value: raw.value };
  }
  if (raw.kind === "suggestionDefault"
    && SUGGESTION_DEFAULT_HISTORY_FOCUS_KINDS.has(raw.focusKind)
    && SUGGESTION_THRESHOLD_HISTORY_METHODS.has(raw.method)) {
    return {
      kind: "suggestionDefault",
      focusKind: raw.focusKind,
      method: raw.method,
    };
  }
  return defaultGeneralSettingsHistoryFocus();
}

function generalSettingsHistoryFocusForElement(target) {
  if (!(target instanceof Element)) return null;
  const control = target.closest("button, input");
  if (!(control instanceof HTMLElement) || !elements.generalSettingsDialog.contains(control)) {
    return null;
  }
  if (GENERAL_SETTINGS_HISTORY_CONTROL_IDS.has(control.id)) {
    return { kind: "control", id: control.id };
  }
  if (GENERAL_SETTINGS_HISTORY_DISPLAY_MODES.has(control.dataset.toolbarDisplayMode)) {
    return { kind: "toolbarDisplayMode", value: control.dataset.toolbarDisplayMode };
  }
  const focusKey = suggestionDefaultFocusKey(control);
  if (focusKey
    && SUGGESTION_DEFAULT_HISTORY_FOCUS_KINDS.has(focusKey[0])
    && SUGGESTION_THRESHOLD_HISTORY_METHODS.has(focusKey[1])) {
    return { kind: "suggestionDefault", focusKind: focusKey[0], method: focusKey[1] };
  }
  return null;
}

function captureGeneralSettingsHistoryFocus() {
  const descriptor = generalSettingsHistoryFocusForElement(document.activeElement);
  if (descriptor) state.generalSettings.focus = descriptor;
}

function defaultSuggestionThresholdHistoryFocus() {
  return { kind: "control", id: "suggestionThresholdSearch" };
}

function normalizedSuggestionThresholdHistoryFocus(raw) {
  if (!raw || typeof raw !== "object") return defaultSuggestionThresholdHistoryFocus();
  if (raw.kind === "control" && SUGGESTION_THRESHOLD_HISTORY_CONTROL_IDS.has(raw.id)) {
    return { kind: "control", id: raw.id };
  }
  const tagID = galleryHistoryIdentifier(raw.tagID);
  if (raw.kind === "threshold"
    && tagID
    && SUGGESTION_THRESHOLD_HISTORY_FOCUS_KINDS.has(raw.focusKind)
    && SUGGESTION_THRESHOLD_HISTORY_METHODS.has(raw.method)) {
    return {
      kind: "threshold",
      focusKind: raw.focusKind,
      tagID,
      method: raw.method,
    };
  }
  return defaultSuggestionThresholdHistoryFocus();
}

function suggestionThresholdHistoryFocusForElement(target) {
  if (!(target instanceof Element)) return null;
  const control = target.closest("button, input");
  if (!(control instanceof HTMLElement)
    || !elements.suggestionThresholdDialog.contains(control)) return null;
  if (SUGGESTION_THRESHOLD_HISTORY_CONTROL_IDS.has(control.id)) {
    return { kind: "control", id: control.id };
  }
  const focusKey = thresholdFocusSelector(control);
  const tagID = galleryHistoryIdentifier(focusKey?.[1]);
  if (focusKey
    && tagID
    && SUGGESTION_THRESHOLD_HISTORY_FOCUS_KINDS.has(focusKey[0])
    && SUGGESTION_THRESHOLD_HISTORY_METHODS.has(focusKey[2])) {
    return {
      kind: "threshold",
      focusKind: focusKey[0],
      tagID,
      method: focusKey[2],
    };
  }
  return null;
}

function captureSuggestionThresholdHistoryFocus() {
  const descriptor = suggestionThresholdHistoryFocusForElement(document.activeElement);
  if (descriptor) state.generalSettings.thresholdFocus = descriptor;
}

function currentGeneralSettingsHistoryContext() {
  const manager = state.generalSettings;
  if (elements.generalSettingsDialog.open) {
    captureGeneralSettingsHistoryFocus();
    manager.scrollTop = elements.generalSettingsContent.scrollTop;
  }
  if (elements.suggestionThresholdDialog.open) {
    captureSuggestionThresholdHistoryFocus();
    manager.thresholdScrollTop = elements.suggestionThresholdList.scrollTop;
  }
  return {
    generalSettingsFocus: normalizedGeneralSettingsHistoryFocus(manager.focus),
    generalSettingsScrollTop: Math.max(
      0,
      workspaceHistoryFiniteNumber(manager.scrollTop)
    ),
    generalSettingsReturnControlID: GENERAL_SETTINGS_HISTORY_RETURN_IDS.has(
      manager.returnControlID
    ) ? manager.returnControlID : null,
    suggestionThresholdFocus: normalizedSuggestionThresholdHistoryFocus(
      manager.thresholdFocus
    ),
    suggestionThresholdScrollTop: Math.max(
      0,
      workspaceHistoryFiniteNumber(manager.thresholdScrollTop)
    ),
  };
}

function applyGeneralSettingsHistoryContext(context = {}) {
  const manager = state.generalSettings;
  manager.focus = normalizedGeneralSettingsHistoryFocus(context.generalSettingsFocus);
  manager.scrollTop = Math.max(
    0,
    workspaceHistoryFiniteNumber(context.generalSettingsScrollTop)
  );
  manager.returnControlID = GENERAL_SETTINGS_HISTORY_RETURN_IDS.has(
    context.generalSettingsReturnControlID
  ) ? context.generalSettingsReturnControlID : null;
  manager.thresholdFocus = normalizedSuggestionThresholdHistoryFocus(
    context.suggestionThresholdFocus
  );
  manager.thresholdScrollTop = Math.max(
    0,
    workspaceHistoryFiniteNumber(context.suggestionThresholdScrollTop)
  );
}

function generalSettingsReturnControlID(target) {
  return target instanceof HTMLElement && GENERAL_SETTINGS_HISTORY_RETURN_IDS.has(target.id)
    ? target.id
    : null;
}

function resolveGeneralSettingsReturnFocus() {
  const manager = state.generalSettings;
  if (manager.returnFocus?.isConnected) return manager.returnFocus;
  if (manager.returnControlID) {
    const target = document.getElementById(manager.returnControlID);
    if (target instanceof HTMLElement && !target.disabled && target.getClientRects().length) {
      return target;
    }
  }
  return stableReturnFocusTarget(
    elements.settingsButton,
    stableReturnFocusTarget(elements.compactToolbarMenuButton, elements.commandButton)
  );
}

function generalSettingsHistoryFocusTarget(descriptor = state.generalSettings.focus) {
  const normalized = normalizedGeneralSettingsHistoryFocus(descriptor);
  if (normalized.kind === "control") return document.getElementById(normalized.id);
  if (normalized.kind === "toolbarDisplayMode") {
    return elements.toolbarDisplayModeControl.querySelector(
      `[data-toolbar-display-mode="${CSS.escape(normalized.value)}"]`
    );
  }
  if (normalized.kind === "suggestionDefault") {
    return suggestionDefaultFocusTarget([normalized.focusKind, normalized.method]);
  }
  return null;
}

async function restoreGeneralSettingsLayoutFromHistory({ focus = true } = {}) {
  await waitForWorkspaceLayout();
  const manager = state.generalSettings;
  const scrollTop = Math.min(
    manager.scrollTop,
    Math.max(
      0,
      elements.generalSettingsContent.scrollHeight - elements.generalSettingsContent.clientHeight
    )
  );
  elements.generalSettingsContent.scrollTop = scrollTop;
  let target = generalSettingsHistoryFocusTarget();
  if (!(target instanceof HTMLElement)
    || target.disabled
    || !elements.generalSettingsDialog.contains(target)
    || target.offsetParent === null) {
    target = elements.toolbarDisplayModeControl.querySelector('[aria-checked="true"]')
      || elements.generalSettingsCloseButton;
  }
  manager.focus = generalSettingsHistoryFocusForElement(target)
    || defaultGeneralSettingsHistoryFocus();
  if (focus) target.focus({ preventScroll: true });
  manager.scrollTop = scrollTop;
  elements.generalSettingsContent.scrollTop = scrollTop;
}

function suggestionThresholdHistoryFocusTarget(
  descriptor = state.generalSettings.thresholdFocus
) {
  const normalized = normalizedSuggestionThresholdHistoryFocus(descriptor);
  if (normalized.kind === "control") return document.getElementById(normalized.id);
  const selector = `[data-threshold-focus="${CSS.escape(normalized.focusKind)}"]`
    + `[data-threshold-tag-id="${CSS.escape(normalized.tagID)}"]`
    + `[data-threshold-method="${CSS.escape(normalized.method)}"]`;
  return elements.suggestionThresholdList.querySelector(selector)
    || elements.suggestionThresholdList.querySelector(
      `[data-threshold-focus="input"]`
        + `[data-threshold-tag-id="${CSS.escape(normalized.tagID)}"]`
        + `[data-threshold-method="${CSS.escape(normalized.method)}"]`
    );
}

async function restoreSuggestionThresholdLayoutFromHistory() {
  await waitForWorkspaceLayout();
  const manager = state.generalSettings;
  const scrollTop = Math.min(
    manager.thresholdScrollTop,
    Math.max(
      0,
      elements.suggestionThresholdList.scrollHeight
        - elements.suggestionThresholdList.clientHeight
    )
  );
  elements.suggestionThresholdList.scrollTop = scrollTop;
  let target = suggestionThresholdHistoryFocusTarget();
  if (!(target instanceof HTMLElement)
    || target.disabled
    || !elements.suggestionThresholdDialog.contains(target)
    || target.offsetParent === null) {
    target = elements.suggestionThresholdSearch.disabled
      ? elements.suggestionThresholdCloseButton
      : elements.suggestionThresholdSearch;
  }
  target.focus({ preventScroll: true });
  manager.thresholdFocus = suggestionThresholdHistoryFocusForElement(target)
    || defaultSuggestionThresholdHistoryFocus();
  manager.thresholdScrollTop = scrollTop;
  elements.suggestionThresholdList.scrollTop = scrollTop;
}

function replaceGeneralSettingsHistoryWithBase(baseLevel) {
  if (!state.workspaceNavigation.initialized
    || elements.appView.classList.contains("hidden")) return;
  const current = activeWorkspaceHistoryEntry();
  const route = visibleWorkspaceRoute();
  if (current?.route !== route
    || !["generalSettings", "suggestionThreshold"].includes(current.navigationLevel)) return;
  const context = currentWorkspaceHistoryContext(route);
  if (context && typeof context === "object") delete context.generalSettingsBaseLevel;
  const navigationLevel = visibleWorkspaceNavigationBaseLevel(route, baseLevel);
  history.replaceState({
    ...(history.state || {}),
    [WORKSPACE_HISTORY_KEY]: workspaceHistoryEntry(route, context, navigationLevel),
  }, "", location.href);
}

function replaceSuggestionThresholdHistoryWithSettings() {
  if (!state.workspaceNavigation.initialized
    || elements.appView.classList.contains("hidden")) return;
  const current = activeWorkspaceHistoryEntry();
  const route = visibleWorkspaceRoute();
  if (current?.route !== route || current.navigationLevel !== "suggestionThreshold") return;
  const context = {
    ...(currentWorkspaceHistoryContext(route) || {}),
    generalSettingsBaseLevel: state.generalSettings.baseLevel,
    ...currentGeneralSettingsHistoryContext(),
  };
  history.replaceState({
    ...(history.state || {}),
    [WORKSPACE_HISTORY_KEY]: workspaceHistoryEntry(route, context, "generalSettings"),
  }, "", location.href);
}

function openSuggestionThresholdDialog({
  focus = true,
  historyMode = "pushSuggestionThreshold",
  preserveState = false,
} = {}) {
  if (!elements.generalSettingsDialog.open
    || !suggestionThresholdSnapshot()
    || state.generalSettings.submitting) return;
  if (elements.suggestionThresholdDialog.open) {
    if (focus) restoreOverlayFocus(elements.suggestionThresholdSearch);
    return;
  }
  if (!preserveState) {
    state.generalSettings.thresholdReturnFocus = document.activeElement;
    state.generalSettings.thresholdFocus = defaultSuggestionThresholdHistoryFocus();
    state.generalSettings.thresholdScrollTop = 0;
  }
  elements.suggestionThresholdSearch.value = "";
  elements.suggestionThresholdError.classList.add("hidden");
  elements.suggestionThresholdDialog.showModal();
  renderSuggestionThresholdDialog();
  if (historyMode !== "none") {
    const route = visibleWorkspaceRoute();
    recordWorkspaceHistory(route, currentWorkspaceHistoryContext(route), historyMode);
  }
  if (focus) restoreOverlayFocus(elements.suggestionThresholdSearch);
  scheduleWorkspaceHistoryCheckpoint();
}

function closeSuggestionThresholdDialog({
  restoreFocus = true,
  checkpoint = true,
  preserveState = false,
} = {}) {
  if (!elements.suggestionThresholdDialog.open) return;
  captureSuggestionThresholdHistoryFocus();
  state.generalSettings.thresholdScrollTop = elements.suggestionThresholdList.scrollTop;
  const returnFocus = state.generalSettings.thresholdReturnFocus;
  if (!preserveState) state.generalSettings.thresholdReturnFocus = null;
  elements.suggestionThresholdDialog.close();
  if (restoreFocus) {
    const target = returnFocus || elements.suggestionOverridesButton;
    state.generalSettings.focus = generalSettingsHistoryFocusForElement(target)
      || { kind: "control", id: "suggestionOverridesButton" };
    restoreOverlayFocus(target);
  }
  if (checkpoint) replaceSuggestionThresholdHistoryWithSettings();
  if (!preserveState) {
    state.generalSettings.thresholdFocus = defaultSuggestionThresholdHistoryFocus();
    state.generalSettings.thresholdScrollTop = 0;
  }
}

function returnFromSuggestionThreshold({ restoreFocus = true } = {}) {
  if (!elements.suggestionThresholdDialog.open) return Promise.resolve();
  state.generalSettings.thresholdHistoryRestoreFocus = restoreFocus;
  if (state.workspaceNavigation.pendingReturnPromise) {
    return state.workspaceNavigation.pendingReturnPromise.then(() => {
      if (elements.suggestionThresholdDialog.open) {
        return returnFromSuggestionThreshold({ restoreFocus });
      }
      return elements.generalSettingsDialog.open
        ? returnFromGeneralSettings({ restoreFocus })
        : undefined;
    });
  }
  const current = activeWorkspaceHistoryEntry();
  if (state.workspaceNavigation.initialized
    && current?.route === visibleWorkspaceRoute()
    && current.navigationLevel === "suggestionThreshold") {
    const pending = new Promise((resolve) => {
      state.workspaceNavigation.pendingReturnResolve = resolve;
    });
    state.workspaceNavigation.pendingReturnPromise = pending;
    history.back();
    return pending;
  }
  closeSuggestionThresholdDialog({ restoreFocus });
  state.generalSettings.thresholdHistoryRestoreFocus = true;
  return Promise.resolve();
}

async function openGeneralSettings({
  focus = true,
  historyMode = "pushGeneralSettings",
  baseLevel = null,
  refresh = true,
  preserveState = false,
} = {}) {
  if (!state.online || !supportsGeneralSettings()
    || elements.generalSettingsDialog.open
    || state.generalSettings.opening) return;
  state.generalSettings.opening = true;
  try {
    if (!preserveState) {
      state.generalSettings.returnFocus = document.activeElement instanceof HTMLElement
        ? document.activeElement
        : null;
      state.generalSettings.returnControlID = generalSettingsReturnControlID(
        state.generalSettings.returnFocus
      );
      state.generalSettings.focus = defaultGeneralSettingsHistoryFocus();
      state.generalSettings.scrollTop = 0;
      state.generalSettings.thresholdFocus = defaultSuggestionThresholdHistoryFocus();
      state.generalSettings.thresholdScrollTop = 0;
    }
    const current = activeWorkspaceHistoryEntry();
    state.generalSettings.baseLevel = baseLevel
      || workspaceNavigationBaseLevel(
        current?.navigationLevel || "workspace",
        current?.context || {}
    );
    elements.generalSettingsDialog.showModal();
    state.generalSettings.restorable = true;
    elements.generalSettingsError.classList.add("hidden");
    if (historyMode !== "none") {
      const route = visibleWorkspaceRoute();
      recordWorkspaceHistory(route, currentWorkspaceHistoryContext(route), historyMode);
    }
    if (focus) restoreOverlayFocus(elements.generalSettingsCloseButton);
    if (refresh || !state.generalSettings.snapshot) await loadGeneralSettings();
    else renderGeneralSettings();
    if (focus && elements.generalSettingsDialog.open) {
      const selected = elements.toolbarDisplayModeControl.querySelector('[aria-checked="true"]');
      restoreOverlayFocus(selected || elements.generalSettingsCloseButton);
    }
    scheduleWorkspaceHistoryCheckpoint();
  } finally {
    state.generalSettings.opening = false;
  }
}

function closeGeneralSettings({
  restoreFocus = true,
  checkpoint = true,
  preserveState = false,
} = {}) {
  if (!elements.generalSettingsDialog.open) return;
  if (elements.suggestionThresholdDialog.open) {
    closeSuggestionThresholdDialog({
      restoreFocus: false,
      checkpoint: false,
      preserveState,
    });
  }
  state.generalSettings.requestGeneration += 1;
  state.generalSettings.loading = false;
  captureGeneralSettingsHistoryFocus();
  state.generalSettings.scrollTop = elements.generalSettingsContent.scrollTop;
  const baseLevel = state.generalSettings.baseLevel;
  const returnFocus = resolveGeneralSettingsReturnFocus();
  if (!preserveState) {
    state.generalSettings.returnFocus = null;
    state.generalSettings.returnControlID = null;
  }
  state.generalSettings.baseLevel = preserveState ? baseLevel : "workspace";
  elements.generalSettingsDialog.close();
  if (restoreFocus) {
    const toolbarFallback = stableReturnFocusTarget(
      elements.compactToolbarMenuButton,
      elements.commandButton
    );
    restoreOverlayFocus(stableReturnFocusTarget(
      returnFocus || elements.settingsButton,
      toolbarFallback
    ));
  }
  if (checkpoint) replaceGeneralSettingsHistoryWithBase(baseLevel);
  if (!preserveState) {
    state.generalSettings.restorable = false;
    state.generalSettings.focus = defaultGeneralSettingsHistoryFocus();
    state.generalSettings.scrollTop = 0;
  }
}

function returnFromGeneralSettings({ restoreFocus = true } = {}) {
  if (elements.suggestionThresholdDialog.open) {
    return returnFromSuggestionThreshold({ restoreFocus });
  }
  if (!elements.generalSettingsDialog.open) return Promise.resolve();
  state.generalSettings.historyRestoreFocus = restoreFocus;
  if (state.workspaceNavigation.pendingReturnPromise) {
    return state.workspaceNavigation.pendingReturnPromise.then(() => (
      elements.generalSettingsDialog.open
        ? returnFromGeneralSettings({ restoreFocus })
        : undefined
    ));
  }
  const current = activeWorkspaceHistoryEntry();
  if (state.workspaceNavigation.initialized
    && current?.route === visibleWorkspaceRoute()
    && current.navigationLevel === "generalSettings") {
    const pending = new Promise((resolve) => {
      state.workspaceNavigation.pendingReturnResolve = resolve;
    });
    state.workspaceNavigation.pendingReturnPromise = pending;
    history.back();
    return pending;
  }
  closeGeneralSettings({ restoreFocus });
  state.generalSettings.historyRestoreFocus = true;
  return Promise.resolve();
}

async function reconcileGeneralSettingsFromWorkspaceHistory(
  route,
  navigationLevel,
  context = {}
) {
  const shouldOpenSettings = ["generalSettings", "suggestionThreshold"].includes(
    navigationLevel
  ) && route === visibleWorkspaceRoute();
  if (shouldOpenSettings && (!state.online || !supportsGeneralSettings())) {
    replaceGeneralSettingsHistoryWithBase(generalSettingsBaseLevelFromHistory(context));
    return;
  }
  const restoringFreshState = shouldOpenSettings && !state.generalSettings.restorable;
  if (shouldOpenSettings) applyGeneralSettingsHistoryContext(context);
  if (shouldOpenSettings && !elements.generalSettingsDialog.open) {
    await openGeneralSettings({
      focus: false,
      historyMode: "none",
      baseLevel: generalSettingsBaseLevelFromHistory(context),
      refresh: false,
      preserveState: true,
    });
  }
  if (navigationLevel === "suggestionThreshold" && elements.generalSettingsDialog.open) {
    await restoreGeneralSettingsLayoutFromHistory({ focus: false });
    openSuggestionThresholdDialog({
      focus: false,
      historyMode: "none",
      preserveState: true,
    });
    await restoreSuggestionThresholdLayoutFromHistory();
  } else if (elements.suggestionThresholdDialog.open) {
    const restoreFocus = state.generalSettings.thresholdHistoryRestoreFocus;
    closeSuggestionThresholdDialog({
      restoreFocus,
      checkpoint: false,
      preserveState: true,
    });
    state.generalSettings.thresholdHistoryRestoreFocus = true;
  }
  if (navigationLevel === "generalSettings" && elements.generalSettingsDialog.open) {
    await restoreGeneralSettingsLayoutFromHistory();
  }
  if (!shouldOpenSettings && elements.generalSettingsDialog.open) {
    const restoreFocus = state.generalSettings.historyRestoreFocus;
    closeGeneralSettings({ restoreFocus, checkpoint: false, preserveState: true });
    state.generalSettings.historyRestoreFocus = true;
  }
  return restoringFreshState;
}

function moveDialogButtonFocus(event, dialog) {
  if (isTextInputTarget(event.target)) return false;
  if (!["ArrowLeft", "ArrowRight", "ArrowUp", "ArrowDown", "Home", "End"].includes(event.key)) {
    return false;
  }
  const buttons = [...dialog.querySelectorAll("button:not(:disabled)")]
    .filter((button) => button.offsetParent !== null);
  if (!buttons.length) return false;
  const currentIndex = Math.max(0, buttons.indexOf(document.activeElement));
  let nextIndex = currentIndex;
  if (event.key === "Home") nextIndex = 0;
  else if (event.key === "End") nextIndex = buttons.length - 1;
  else nextIndex = (currentIndex
    + (["ArrowLeft", "ArrowUp"].includes(event.key) ? -1 : 1)
    + buttons.length) % buttons.length;
  event.preventDefault();
  buttons[nextIndex].focus({ preventScroll: true });
  buttons[nextIndex].scrollIntoView({ block: "nearest" });
  return true;
}

function sourceManagementActionLabel(action, source = null, { emptyState = false } = {}) {
  if (action === "reauthorize" && source?.kind === "photos") {
    if (emptyState) return "重新检查并同步";
    if (source.state === "disabled") return "重新启用…";
  }
  return {
    refreshAll: "更新全部来源",
    prewarmAllThumbnails: "缓存所有缩略图",
    prewarmAllOriginalAspect: "缓存所有原比例",
    reauthorizeAll: "批量重新授权来源",
    refreshAllFolderMutationAuthorizations: "批量更新文件夹回收权限",
    rebindPhotos: "连接当前图库…",
    reauthorize: "重新授权…",
    rescan: "立即重扫",
    syncPhotos: "立即同步",
    fullRepair: "完整修复…",
    openPhotosPrivacySettings: "打开照片权限设置…",
    requestPhotosWriteAuthorization: "请求照片写入权限…",
    refreshFolderMutationAuthorization: "更新回收权限…",
    prewarmThumbnails: "预热缩略图缓存",
    prewarmOriginalAspect: "专门用于原比例的缓存",
    cancelPrewarm: "取消缓存预热",
    delete: "删除来源…",
  }[action] || action;
}

function sourceManagementActionHelp(action, source = null) {
  const sourceName = source?.displayName || "当前来源";
  const photos = source?.kind === "photos";
  return {
    rescan: `重新扫描“${sourceName}”并更新照片索引`,
    syncPhotos: `同步“${sourceName}”的最新 Apple Photos 变化`,
    prewarmThumbnails: "检查并补齐网格缩略图；已有缓存会直接复用",
    prewarmOriginalAspect: "检查并补齐原比例网格缓存；已有缓存会直接复用",
    cancelPrewarm: "停止当前缩略图缓存任务；已经生成的缓存会保留",
    rebindPhotos: "保留旧图库历史，并把当前系统照片图库连接为新来源",
    reauthorize: photos
      ? "重新请求 Apple Photos 权限或重新启用这个来源"
      : "在 Mac 上重新选择原文件夹，恢复这个来源的访问授权",
    fullRepair: "重新扫描整个 Apple Photos 图库并修复缺失状态",
    openPhotosPrivacySettings: "在 Mac 上打开系统照片权限设置",
    requestPhotosWriteAuthorization: "请求 Photos 写入权限；普通浏览仍保持只读",
    refreshFolderMutationAuthorization: "重新确认回收权限；不会立即修改任何照片",
    delete: "删除 ImageAll 中的来源记录与缓存；不会删除原始媒体",
  }[action] || "该操作由 Mac Host 执行并返回权威状态";
}

function sourceManagementActionGroup(action) {
  if ([
    "rescan",
    "syncPhotos",
    "prewarmThumbnails",
    "prewarmOriginalAspect",
    "cancelPrewarm",
  ].includes(action)) return "update";
  if (action === "delete") return "remove";
  return "recovery";
}

function sourceManagerStatusDescription(source) {
  if (source.state === "active") {
    return source.kind === "photos"
      ? "已连接当前系统照片图库，可以浏览、同步和维护缓存。"
      : "文件夹授权有效，可以浏览、重扫和维护缓存。";
  }
  if (source.state === "authorizationRequired") {
    return source.kind === "photos"
      ? "需要在 Mac 上重新授予 Apple Photos 访问权限。"
      : "原文件夹授权已失效，需要在 Mac 上重新选择。";
  }
  if (source.state === "unavailable") {
    return source.kind === "photos"
      ? "这是历史照片图库；可保留历史并连接当前系统图库。"
      : "文件夹当前离线；重新连接磁盘后可授权恢复。";
  }
  return "来源已停用；恢复操作需要在 Mac 上完成。";
}

function sourceManagerSelectedSource() {
  const sources = state.sourceManagement.snapshot?.sources || [];
  return sources.find((source) => source.id === state.sourceManagement.selectedSourceID) || null;
}

const SOURCE_MANAGER_HISTORY_CONTROL_IDS = new Set([
  "sourceManagerCloseButton",
  "sourceConnectFolderButton",
  "sourceConnectPhotosButton",
  "sourceAllActionsSummary",
  "sourceRefreshAllButton",
  "sourcePrewarmAllButton",
  "sourcePrewarmAllOriginalButton",
  "sourceBatchAuthorizationSummary",
  "sourceReauthorizeAllButton",
  "sourceRefreshAllMutationAuthorizationButton",
  "sourceRequestPhotosWriteAuthorizationButton",
  "sourceManagerRefreshButton",
]);
const SOURCE_MANAGER_HISTORY_RETURN_CONTROL_IDS = new Set([
  "sourceManagerButton",
  "sourcePrewarmStatusButton",
  "emptyOpenSourceManagerButton",
  "emptySourceRecoveryButton",
  "sourceAllActionsButton",
  "sourceActionsOpenManagerButton",
  "sidebarConnectFolderButton",
  "toolbarConnectFolderButton",
  "sidebarConnectPhotosButton",
  "emptyConnectFolderButton",
  "emptyConnectPhotosButton",
  "commandButton",
]);
const SOURCE_MANAGER_HISTORY_ACTIONS = new Set([
  "syncPhotos",
  "prewarmThumbnails",
  "prewarmOriginalAspect",
  "fullRepair",
  "requestPhotosWriteAuthorization",
  "delete",
  "rebindPhotos",
  "reauthorize",
  "openPhotosPrivacySettings",
  "rescan",
  "refreshFolderMutationAuthorization",
  "cancelPrewarm",
]);

function normalizedSourceManagerHistoryFocus(value) {
  if (!value || typeof value !== "object") {
    return { kind: "control", id: "sourceConnectFolderButton" };
  }
  if (value.kind === "control" && SOURCE_MANAGER_HISTORY_CONTROL_IDS.has(value.id)) {
    return { kind: "control", id: value.id };
  }
  const sourceID = galleryHistoryIdentifier(value.sourceID);
  if (value.kind === "source" && sourceID) return { kind: "source", sourceID };
  if (value.kind === "view" && sourceID) return { kind: "view", sourceID };
  if (["action", "pending"].includes(value.kind)
    && sourceID
    && SOURCE_MANAGER_HISTORY_ACTIONS.has(value.action)) {
    return { kind: value.kind, sourceID, action: value.action };
  }
  return { kind: "control", id: "sourceConnectFolderButton" };
}

function captureSourceManagerHistoryFocus() {
  if (!elements.sourceManagerDialog.open) return;
  const active = document.activeElement;
  if (!(active instanceof HTMLElement) || !elements.sourceManagerDialog.contains(active)) return;
  if (SOURCE_MANAGER_HISTORY_CONTROL_IDS.has(active.id)) {
    state.sourceManagerFocus = { kind: "control", id: active.id };
    return;
  }
  const sourceRow = active.closest("[data-source-manager-select]");
  if (sourceRow) {
    state.sourceManagerFocus = {
      kind: "source",
      sourceID: galleryHistoryIdentifier(sourceRow.dataset.sourceManagerSelect),
    };
    return;
  }
  const view = active.closest("[data-source-manager-view]");
  if (view) {
    state.sourceManagerFocus = {
      kind: "view",
      sourceID: galleryHistoryIdentifier(view.dataset.sourceManagerView),
    };
    return;
  }
  const action = active.closest("[data-source-action][data-source-id]");
  if (action && SOURCE_MANAGER_HISTORY_ACTIONS.has(action.dataset.sourceAction)) {
    state.sourceManagerFocus = {
      kind: "action",
      sourceID: galleryHistoryIdentifier(action.dataset.sourceId),
      action: action.dataset.sourceAction,
    };
    return;
  }
  const pending = active.closest("[data-source-pending-action][data-source-id]");
  if (pending && SOURCE_MANAGER_HISTORY_ACTIONS.has(pending.dataset.sourcePendingAction)) {
    state.sourceManagerFocus = {
      kind: "pending",
      sourceID: galleryHistoryIdentifier(pending.dataset.sourceId),
      action: pending.dataset.sourcePendingAction,
    };
  }
}

function captureSourceManagerLayout() {
  captureSourceManagerHistoryFocus();
  const navigation = elements.sourceManagerList.querySelector(".source-manager-source-list");
  const detail = elements.sourceManagerList.querySelector(".source-manager-detail");
  if (navigation) state.sourceManagerNavigationScrollTop = navigation.scrollTop;
  if (detail) state.sourceManagerDetailScrollTop = detail.scrollTop;
  state.sourceManagerAllActionsOpen = elements.sourceAllActionsPanel.open;
  state.sourceManagerBatchAuthorizationOpen = elements.sourceBatchAuthorizationPanel.open;
}

function sourceManagerReturnFocusDescriptor(element) {
  if (!(element instanceof HTMLElement)) return null;
  if (SOURCE_MANAGER_HISTORY_RETURN_CONTROL_IDS.has(element.id)) {
    return { element, controlID: element.id, sourceID: null };
  }
  const source = element.closest("[data-source-id]");
  const sourceID = galleryHistoryIdentifier(source?.dataset.sourceId);
  return sourceID ? { element, controlID: null, sourceID } : null;
}

function resolveSourceManagerReturnFocus() {
  const descriptor = state.sourceManagerReturnDescriptor;
  if (descriptor?.element?.isConnected) return descriptor.element;
  if (descriptor?.sourceID) {
    const source = elements.sourceList.querySelector(
      `[data-source-id="${CSS.escape(descriptor.sourceID)}"]`
    );
    if (source) return source;
  }
  if (descriptor?.controlID && SOURCE_MANAGER_HISTORY_RETURN_CONTROL_IDS.has(
    descriptor.controlID
  )) {
    const control = document.getElementById(descriptor.controlID);
    if (control instanceof HTMLElement && control.offsetParent !== null && !control.disabled) {
      return control;
    }
  }
  return elements.sourceManagerButton;
}

function currentSourceManagerHistoryContext() {
  if (elements.sourceManagerDialog.open) captureSourceManagerLayout();
  const descriptor = state.sourceManagerReturnDescriptor;
  return {
    sourceManagerSelectedSourceID: galleryHistoryIdentifier(
      state.sourceManagement.selectedSourceID
    ),
    sourceManagerAllActionsOpen: state.sourceManagerAllActionsOpen === true,
    sourceManagerBatchAuthorizationOpen:
      state.sourceManagerAllActionsOpen === true
      && state.sourceManagerBatchAuthorizationOpen === true,
    sourceManagerNavigationScrollTop: workspaceHistoryFiniteNumber(
      state.sourceManagerNavigationScrollTop
    ),
    sourceManagerDetailScrollTop: workspaceHistoryFiniteNumber(
      state.sourceManagerDetailScrollTop
    ),
    sourceManagerFocus: normalizedSourceManagerHistoryFocus(state.sourceManagerFocus),
    sourceManagerReturnControlID: SOURCE_MANAGER_HISTORY_RETURN_CONTROL_IDS.has(
      descriptor?.controlID
    ) ? descriptor.controlID : null,
    sourceManagerReturnSourceID: galleryHistoryIdentifier(descriptor?.sourceID),
  };
}

function renderSourceManagerHistoryNotice() {
  elements.sourceManagerHistoryNotice.textContent = state.sourceManagerHistoryNotice;
  elements.sourceManagerHistoryNotice.classList.toggle(
    "hidden",
    !state.sourceManagerHistoryNotice
  );
}

function applySourceManagerHistoryContext(context = {}) {
  const sources = state.sourceManagement.snapshot?.sources || [];
  const sourceIDs = new Set(sources.map((source) => source.id));
  const savedSourceID = galleryHistoryIdentifier(context.sourceManagerSelectedSourceID);
  const returnSourceID = galleryHistoryIdentifier(context.sourceManagerReturnSourceID);
  const returnControlID = SOURCE_MANAGER_HISTORY_RETURN_CONTROL_IDS.has(
    context.sourceManagerReturnControlID
  ) ? context.sourceManagerReturnControlID : null;
  const notes = [];
  if (savedSourceID && sourceIDs.has(savedSourceID)) {
    state.sourceManagement.selectedSourceID = savedSourceID;
  } else if (savedSourceID) {
    state.sourceManagement.selectedSourceID = sources[0]?.id || null;
    notes.push("刷新前选择的来源当前不可用，已切换到可用来源。");
  }
  if (returnSourceID && !sourceIDs.has(returnSourceID)) {
    notes.push("刷新前的返回来源当前不可用，关闭后将回到来源管理入口。");
  }
  let focus = normalizedSourceManagerHistoryFocus(context.sourceManagerFocus);
  if (focus.sourceID && !sourceIDs.has(focus.sourceID)) {
    focus = { kind: "control", id: "sourceConnectFolderButton" };
    notes.push("刷新前的焦点来源当前不可用，已恢复到安全入口。");
  }
  state.sourceManagerFocus = focus;
  state.sourceManagerAllActionsOpen = context.sourceManagerAllActionsOpen === true;
  state.sourceManagerBatchAuthorizationOpen = state.sourceManagerAllActionsOpen
    && context.sourceManagerBatchAuthorizationOpen === true;
  state.sourceManagerNavigationScrollTop = workspaceHistoryFiniteNumber(
    context.sourceManagerNavigationScrollTop
  );
  state.sourceManagerDetailScrollTop = workspaceHistoryFiniteNumber(
    context.sourceManagerDetailScrollTop
  );
  state.sourceManagerReturnDescriptor = {
    element: null,
    controlID: returnControlID,
    sourceID: returnSourceID && sourceIDs.has(returnSourceID) ? returnSourceID : null,
  };
  state.sourceManagerHistoryNotice = notes.join(" ");
  renderSourceManagerHistoryNotice();
}

function sourceManagerHistoryFocusTarget() {
  const focus = normalizedSourceManagerHistoryFocus(state.sourceManagerFocus);
  if (focus.kind === "control") return document.getElementById(focus.id);
  if (focus.kind === "source") {
    return elements.sourceManagerList.querySelector(
      `[data-source-manager-select="${CSS.escape(focus.sourceID)}"]`
    );
  }
  if (focus.kind === "view") {
    return elements.sourceManagerList.querySelector(
      `[data-source-manager-view="${CSS.escape(focus.sourceID)}"]`
    );
  }
  if (focus.kind === "action") {
    return elements.sourceManagerList.querySelector(
      `[data-source-id="${CSS.escape(focus.sourceID)}"]`
      + `[data-source-action="${CSS.escape(focus.action)}"]`
    );
  }
  return elements.sourceManagerPending.querySelector(
    `[data-source-id="${CSS.escape(focus.sourceID)}"]`
    + `[data-source-pending-action="${CSS.escape(focus.action)}"]`
  );
}

async function restoreSourceManagerLayoutFromHistory() {
  await waitForWorkspaceLayout();
  elements.sourceAllActionsPanel.open = state.sourceManagerAllActionsOpen;
  elements.sourceBatchAuthorizationPanel.open = state.sourceManagerBatchAuthorizationOpen;
  const navigation = elements.sourceManagerList.querySelector(".source-manager-source-list");
  const detail = elements.sourceManagerList.querySelector(".source-manager-detail");
  if (navigation) {
    navigation.scrollTop = Math.min(
      state.sourceManagerNavigationScrollTop,
      Math.max(0, navigation.scrollHeight - navigation.clientHeight)
    );
  }
  if (detail) {
    detail.scrollTop = Math.min(
      state.sourceManagerDetailScrollTop,
      Math.max(0, detail.scrollHeight - detail.clientHeight)
    );
  }
  let target = sourceManagerHistoryFocusTarget();
  if (!(target instanceof HTMLElement)
    || target.disabled
    || !elements.sourceManagerDialog.contains(target)
    || target.offsetParent === null) {
    target = elements.sourceManagerList.querySelector(
      `[data-source-manager-select="${CSS.escape(
        state.sourceManagement.selectedSourceID || ""
      )}"]`
    ) || (elements.sourceConnectFolderButton.disabled
      ? elements.sourceManagerCloseButton
      : elements.sourceConnectFolderButton);
  }
  target.focus({ preventScroll: true });
  captureSourceManagerHistoryFocus();
  if (navigation) navigation.scrollTop = state.sourceManagerNavigationScrollTop;
  if (detail) detail.scrollTop = state.sourceManagerDetailScrollTop;
}

function selectSourceManagerSource(sourceID, { focus = false, reveal = false } = {}) {
  const sources = state.sourceManagement.snapshot?.sources || [];
  if (!sources.some((source) => source.id === sourceID)) return false;
  state.sourceManagement.selectedSourceID = sourceID;
  renderSourceManagement({ reconcileContent: true });
  if (focus) {
    const row = elements.sourceManagerList.querySelector(
      `[data-source-manager-select="${CSS.escape(sourceID)}"]`
    );
    if (reveal) row?.scrollIntoView({ block: "nearest", inline: "nearest" });
    row?.focus({ preventScroll: true });
  }
  scheduleWorkspaceHistoryCheckpoint();
  return true;
}

function handleSourceManagerKeyboardNavigation(event) {
  if (isTextInputTarget(event.target)) return false;
  const sourceRow = event.target.closest("[data-source-manager-select]");
  if (sourceRow) {
    const rows = [...elements.sourceManagerList.querySelectorAll(
      "[data-source-manager-select]"
    )];
    const index = rows.indexOf(sourceRow);
    if (["ArrowUp", "ArrowDown", "PageUp", "PageDown", "Home", "End"].includes(
      event.key
    )) {
      const navigation = sourceRow.closest(".source-manager-source-list");
      const nextIndex = longListNavigationTarget(rows, index, event.key, navigation);
      event.preventDefault();
      event.stopPropagation();
      selectSourceManagerSource(rows[nextIndex].dataset.sourceManagerSelect, {
        focus: true,
        reveal: true,
      });
      return true;
    }
    if (event.key === "ArrowRight") {
      event.preventDefault();
      elements.sourceManagerList.querySelector(
        ".source-manager-detail button:not(:disabled)"
      )?.focus({ preventScroll: true });
      return true;
    }
  }
  if (event.key === "ArrowLeft"
    && event.target.closest(".source-manager-detail")) {
    event.preventDefault();
    const selectedSourceID = state.sourceManagement.selectedSourceID;
    elements.sourceManagerList.querySelector(
      `[data-source-manager-select="${CSS.escape(selectedSourceID || "")}"]`
    )?.focus({ preventScroll: true });
    return true;
  }
  return false;
}

function closeSourceManagerAllActions({ restoreFocus = false } = {}) {
  if (!elements.sourceAllActionsPanel.open) return false;
  elements.sourceAllActionsPanel.open = false;
  const batchPanel = $("#sourceBatchAuthorizationPanel");
  if (batchPanel) batchPanel.open = false;
  if (restoreFocus) elements.sourceAllActionsSummary.focus({ preventScroll: true });
  return true;
}

function sourceManagerAllActionButtons() {
  return [...elements.sourceAllActionsPanel.querySelectorAll("button:not(:disabled)")]
    .filter((button) => button.offsetParent !== null);
}

function handleSourceManagerAllActionsKeyboard(event) {
  if (event.target === elements.sourceAllActionsSummary
    && event.key === "ArrowDown") {
    event.preventDefault();
    elements.sourceAllActionsPanel.open = true;
    sourceManagerAllActionButtons()[0]?.focus({ preventScroll: true });
    return true;
  }
  if (!event.target.closest(".source-manager-all-actions-menu")) return false;
  if (event.key === "Escape" || event.key === "ArrowLeft") {
    event.preventDefault();
    closeSourceManagerAllActions({ restoreFocus: true });
    return true;
  }
  if (!["ArrowUp", "ArrowDown", "Home", "End"].includes(event.key)) return false;
  const buttons = sourceManagerAllActionButtons();
  if (!buttons.length) return false;
  const currentIndex = Math.max(0, buttons.indexOf(document.activeElement));
  const nextIndex = event.key === "Home" ? 0
    : event.key === "End" ? buttons.length - 1
      : (currentIndex + (event.key === "ArrowUp" ? -1 : 1) + buttons.length)
        % buttons.length;
  event.preventDefault();
  buttons[nextIndex].focus({ preventScroll: true });
  return true;
}

function currentSourceRefreshDescriptor() {
  const selected = state.sources.find((source) => source.id === state.selectedSourceID);
  if (selected) {
    const photos = selected.kind === "photos";
    return {
      action: photos ? "syncPhotos" : "rescan",
      sourceID: selected.id,
      label: photos ? "立即同步" : "立即重扫",
      available: selected.state === "active",
      detail: selected.state === "active"
        ? `${photos ? "同步" : "重新扫描"}“${selected.displayName}”`
        : `“${selected.displayName}”当前不可更新，请先恢复来源`,
    };
  }
  if (state.sources.length === 1) {
    const source = state.sources[0];
    const photos = source.kind === "photos";
    return {
      action: photos ? "syncPhotos" : "rescan",
      sourceID: source.id,
      label: photos ? "立即同步" : "立即重扫",
      available: source.state === "active",
      detail: source.state === "active"
        ? `${photos ? "同步" : "重新扫描"}“${source.displayName}”`
        : `“${source.displayName}”当前不可更新，请先恢复来源`,
    };
  }
  const activeCount = state.sources.filter((source) => source.state === "active").length;
  return {
    action: "refreshAll",
    sourceID: null,
    label: "立即重扫",
    available: activeCount > 0,
    detail: activeCount > 0
      ? `更新全部 ${activeCount} 个活跃来源`
      : "当前没有可更新的活跃来源",
  };
}

function syncCurrentSourceRefreshControl() {
  const descriptor = currentSourceRefreshDescriptor();
  const activeRequest = sourceManagementActiveRequest();
  const busy = state.sourceManagement.submitting || Boolean(activeRequest);
  elements.currentSourceRefreshLabel.textContent = descriptor.label;
  elements.currentSourceRefreshButton.disabled = !state.online || busy || !descriptor.available;
  elements.currentSourceRefreshButton.classList.toggle("busy", busy);
  elements.currentSourceRefreshButton.setAttribute("aria-busy", String(busy));
  elements.currentSourceRefreshButton.setAttribute(
    "aria-label",
    busy ? "来源更新进行中" : descriptor.label
  );
  elements.currentSourceRefreshButton.title = activeRequest?.message || descriptor.detail;
  syncCompactToolbarMenu();
  scheduleAdaptiveToolbarSync();
}

async function refreshCurrentSource() {
  const descriptor = currentSourceRefreshDescriptor();
  if (!state.online
    || !descriptor.available
    || state.sourceManagement.submitting
    || sourceManagementHasActiveRequest()) return;
  await submitSourceManagementAction(descriptor.action, descriptor.sourceID);
}

function sourceManagementIsPrewarmAction(action) {
  return [
    "prewarmThumbnails",
    "prewarmOriginalAspect",
    "prewarmAllThumbnails",
    "prewarmAllOriginalAspect",
  ].includes(action);
}

function sourceManagementIsBatchAuthorizationAction(action) {
  return ["reauthorizeAll", "refreshAllFolderMutationAuthorizations"].includes(action);
}

function sourceManagementActiveRequest() {
  return (state.sourceManagement.snapshot?.requests || [])
    .find((request) => ["awaitingMac", "running"].includes(request.phase)) || null;
}

function sourceManagementHasActiveRequest() {
  return Boolean(sourceManagementActiveRequest());
}

function sourceManagementSnapshotFingerprint(snapshot) {
  if (!snapshot) return null;
  return JSON.stringify([
    Boolean(snapshot.canConnectPhotos),
    snapshot.sources || [],
    snapshot.requests || [],
  ]);
}

function sourceManagementActionsForCurrentState(source) {
  const actions = sourceManagementActions(source);
  const active = sourceManagementActiveRequest();
  if (!active || active.sourceID !== source.id || !sourceManagementIsPrewarmAction(active.action)) {
    return actions;
  }
  return [
    "cancelPrewarm",
    ...actions.filter((action) => !sourceManagementIsPrewarmAction(action)),
  ];
}

function renderSourcePrewarmStatus() {
  const active = sourceManagementActiveRequest();
  const shows = Boolean(active && sourceManagementIsPrewarmAction(active.action));
  elements.appView.classList.toggle("source-prewarm-active", shows);
  elements.sourcePrewarmStatusButton.classList.toggle("hidden", !shows);
  elements.sourcePrewarmCancelButton.classList.toggle("hidden", !shows);
  elements.sourcePrewarmStatusButton.disabled = !state.online;
  elements.sourcePrewarmCancelButton.disabled = !state.online
    || state.sourceManagement.submitting;
  if (!shows) {
    elements.sourcePrewarmStatusLabel.textContent = "缓存";
    elements.sourcePrewarmStatusButton.removeAttribute("aria-label");
    elements.sourcePrewarmCancelButton.setAttribute("aria-label", "取消来源缩略图预热");
    elements.sourcePrewarmCancelButton.title = "取消来源缩略图预热";
    syncCompactToolbarMenu();
    return;
  }
  const hasProgress = Number.isInteger(active.completedCount)
    && Number.isInteger(active.totalCount);
  const progress = hasProgress ? ` ${active.completedCount}/${active.totalCount}` : "";
  const sourceProgress = Number.isInteger(active.completedSourceCount)
    && Number.isInteger(active.totalSourceCount)
    ? ` 来源 ${active.completedSourceCount + 1}/${active.totalSourceCount}`
    : "";
  elements.sourcePrewarmStatusLabel.textContent = `缓存${sourceProgress}${progress}`;
  elements.sourcePrewarmStatusButton.setAttribute(
    "aria-label",
    `${active.sourceDisplayName || "来源"}缩略图预热${sourceProgress}${progress}，打开来源管理`
  );
  elements.sourcePrewarmStatusButton.title = active.message || "查看来源缩略图预热";
  const sourceName = active.sourceDisplayName || (active.sourceID ? "当前来源" : "全部来源");
  elements.sourcePrewarmCancelButton.setAttribute(
    "aria-label",
    `取消${sourceName}缩略图预热${sourceProgress}${progress}`
  );
  elements.sourcePrewarmCancelButton.title = `取消${sourceName}缩略图预热`;
  syncCompactToolbarMenu();
}

async function cancelActiveSourcePrewarm() {
  const active = sourceManagementActiveRequest();
  if (!active
    || !sourceManagementIsPrewarmAction(active.action)
    || !state.online
    || state.sourceManagement.submitting) return;
  await submitSourceManagementAction("cancelPrewarm", active.sourceID || null);
  if (elements.sourcePrewarmCancelButton.classList.contains("hidden")) {
    elements.jobsButton.focus({ preventScroll: true });
  }
}

function syncRenderedSourceManagerDetailActions(selectedSource, activeRequest, busy) {
  if (!selectedSource) return;
  for (const button of elements.sourceManagerList.querySelectorAll(
    ".source-manager-detail [data-source-action][data-source-id]"
  )) {
    const action = button.dataset.sourceAction;
    const canCancelPrewarm = action === "cancelPrewarm"
      && activeRequest?.sourceID === selectedSource.id
      && sourceManagementIsPrewarmAction(activeRequest.action);
    button.disabled = !state.online
      || state.sourceManagement.submitting
      || (action === "cancelPrewarm" ? !canCancelPrewarm : busy);
  }
}

function sourceManagerRowFingerprint(source, selectedSourceID) {
  return JSON.stringify([
    source.id,
    source.kind,
    source.displayName,
    source.state,
    source.id === selectedSourceID,
  ]);
}

function syncSourceManagerRow(row, source, selectedSourceID) {
  row.type = "button";
  row.className = "source-manager-row";
  row.dataset.sourceManagerId = source.id;
  row.dataset.sourceManagerSelect = source.id;
  row.dataset.sourceManagerFingerprint = sourceManagerRowFingerprint(
    source,
    selectedSourceID
  );
  row.setAttribute("role", "option");
  const selected = source.id === selectedSourceID;
  row.setAttribute("aria-selected", String(selected));
  row.setAttribute(
    "aria-keyshortcuts",
    "ArrowUp ArrowDown PageUp PageDown Home End ArrowLeft ArrowRight"
  );
  row.tabIndex = selected ? 0 : -1;
  row.classList.toggle("selected", selected);

  let icon = row.querySelector(":scope > .source-manager-icon");
  if (!icon) {
    icon = document.createElement("span");
    icon.className = "source-manager-icon";
    icon.setAttribute("aria-hidden", "true");
    row.append(icon);
  }
  icon.textContent = sourceIcon(source.kind);

  let copy = row.querySelector(":scope > .source-manager-identity");
  if (!copy) {
    copy = document.createElement("span");
    copy.className = "source-manager-identity";
    row.append(copy);
  }
  let name = copy.querySelector(":scope > .source-manager-name");
  if (!name) {
    name = document.createElement("span");
    name.className = "source-manager-name";
    copy.append(name);
  }
  name.textContent = source.displayName;
  let status = copy.querySelector(":scope > .source-manager-state");
  if (!status) {
    status = document.createElement("span");
    status.className = "source-manager-state";
    copy.append(status);
  }
  status.textContent = source.kind === "photos" ? "Apple Photos" : "文件夹";

  let stateBadge = row.querySelector(":scope > .source-manager-state-badge");
  if (!stateBadge) {
    stateBadge = document.createElement("span");
    stateBadge.className = "source-manager-state-badge";
    row.append(stateBadge);
  }
  stateBadge.dataset.state = source.state;
  stateBadge.textContent = sourceStateText(source.state) || "可用";
}

function sourceManagerActionDisabled(action, source, activeRequest, busy) {
  const canCancelPrewarm = action === "cancelPrewarm"
    && activeRequest?.sourceID === source.id
    && sourceManagementIsPrewarmAction(activeRequest.action);
  return !state.online
    || state.sourceManagement.submitting
    || (action === "cancelPrewarm" ? !canCancelPrewarm : busy);
}

function syncSourceManagerActionButton(
  button,
  action,
  source,
  activeRequest,
  busy
) {
  button.type = "button";
  button.className = `button button-small write-action${action === "delete" ? " button-danger" : ""}`;
  button.dataset.sourceAction = action;
  button.dataset.sourceId = source.id;
  button.textContent = sourceManagementActionLabel(action, source);
  button.title = sourceManagementActionHelp(action, source);
  button.disabled = sourceManagerActionDisabled(action, source, activeRequest, busy);
}

function syncSourceManagerActionGroup(
  section,
  group,
  actions,
  source,
  activeRequest,
  busy
) {
  const groupDetails = {
    update: ["更新与缓存", "更新索引或准备网页和 Mac 共用的缩略图缓存。"],
    recovery: ["权限与修复", "需要系统权限或选择器的步骤会在 Mac 上继续。"],
    remove: ["移除来源", "只清理 ImageAll 中的记录和缓存，原始媒体保持不变。"],
  };
  section.className = `source-manager-action-group source-manager-action-group-${group}`;
  section.dataset.sourceManagerActionGroup = group;

  let heading = section.querySelector(":scope > .source-manager-action-heading");
  if (!heading) {
    heading = document.createElement("div");
    heading.className = "source-manager-action-heading";
    section.append(heading);
  }
  let headingTitle = heading.querySelector(":scope > h5");
  if (!headingTitle) {
    headingTitle = document.createElement("h5");
    heading.append(headingTitle);
  }
  headingTitle.textContent = groupDetails[group][0];
  let headingCopy = heading.querySelector(":scope > p");
  if (!headingCopy) {
    headingCopy = document.createElement("p");
    heading.append(headingCopy);
  }
  headingCopy.textContent = groupDetails[group][1];

  let actionsContainer = section.querySelector(":scope > .source-manager-actions");
  if (!actionsContainer) {
    actionsContainer = document.createElement("div");
    actionsContainer.className = "source-manager-actions";
    section.append(actionsContainer);
  }
  const existing = new Map(
    [...actionsContainer.querySelectorAll(":scope > [data-source-action]")]
      .map((button) => [button.dataset.sourceAction, button])
  );
  const wanted = actions.map((action) => {
    const button = existing.get(action) || document.createElement("button");
    syncSourceManagerActionButton(button, action, source, activeRequest, busy);
    return button;
  });
  for (const [index, button] of wanted.entries()) {
    if (actionsContainer.children[index] !== button) {
      actionsContainer.insertBefore(button, actionsContainer.children[index] || null);
    }
  }
  for (const button of [...actionsContainer.children]) {
    if (!wanted.includes(button)) button.remove();
  }
}

function syncSourceManagerDetail(detail, source, activeRequest, busy) {
  const scrollTop = detail.scrollTop;
  const focused = detail.contains(document.activeElement) ? document.activeElement : null;
  const focusedAction = focused?.closest("[data-source-action]")?.dataset.sourceAction || null;

  detail.className = "source-manager-detail";
  detail.dataset.sourceManagerDetail = source.id;
  detail.setAttribute("aria-label", `${source.displayName} 来源操作`);

  let header = detail.querySelector(":scope > .source-manager-detail-header");
  if (!header) {
    header = document.createElement("header");
    header.className = "source-manager-detail-header";
    detail.append(header);
  }
  let identity = header.querySelector(":scope > .source-manager-detail-identity");
  if (!identity) {
    identity = document.createElement("div");
    identity.className = "source-manager-detail-identity";
    header.append(identity);
  }
  let icon = identity.querySelector(":scope > .source-manager-detail-icon");
  if (!icon) {
    icon = document.createElement("span");
    icon.className = "source-manager-detail-icon";
    icon.setAttribute("aria-hidden", "true");
    identity.append(icon);
  }
  icon.textContent = sourceIcon(source.kind);
  let copy = identity.querySelector(":scope > .source-manager-detail-copy");
  if (!copy) {
    copy = document.createElement("div");
    copy.className = "source-manager-detail-copy";
    identity.append(copy);
  }
  let title = copy.querySelector(":scope > h4");
  if (!title) {
    title = document.createElement("h4");
    copy.append(title);
  }
  title.textContent = source.displayName;
  let typeAndState = copy.querySelector(":scope > p");
  if (!typeAndState) {
    typeAndState = document.createElement("p");
    copy.append(typeAndState);
  }
  typeAndState.textContent = `${source.kind === "photos" ? "Apple Photos" : "文件夹"} · ${sourceStateText(source.state) || "可用"}`;

  let viewButton = header.querySelector(":scope > [data-source-manager-view]");
  if (!viewButton) {
    viewButton = document.createElement("button");
    header.append(viewButton);
  }
  viewButton.type = "button";
  viewButton.className = "button button-small";
  viewButton.dataset.sourceManagerView = source.id;
  viewButton.textContent = "在图库中查看";
  viewButton.title = `关闭来源管理并只显示“${source.displayName}”中的媒体`;

  let status = detail.querySelector(":scope > .source-manager-detail-status");
  if (!status) {
    status = document.createElement("p");
    status.className = "source-manager-detail-status";
    detail.append(status);
  }
  status.dataset.state = source.state;
  status.textContent = sourceManagerStatusDescription(source);

  const actionsByGroup = new Map([
    ["update", []],
    ["recovery", []],
    ["remove", []],
  ]);
  for (const action of sourceManagementActionsForCurrentState(source)) {
    actionsByGroup.get(sourceManagementActionGroup(action)).push(action);
  }
  const existingGroups = new Map(
    [...detail.querySelectorAll(":scope > [data-source-manager-action-group]")]
      .map((section) => [section.dataset.sourceManagerActionGroup, section])
  );
  const wantedGroups = [];
  for (const [group, actions] of actionsByGroup) {
    if (!actions.length) continue;
    const section = existingGroups.get(group) || document.createElement("section");
    syncSourceManagerActionGroup(section, group, actions, source, activeRequest, busy);
    wantedGroups.push(section);
  }
  const stableChildren = [header, status, ...wantedGroups];
  for (const [index, child] of stableChildren.entries()) {
    if (detail.children[index] !== child) {
      detail.insertBefore(child, detail.children[index] || null);
    }
  }
  for (const child of [...detail.children]) {
    if (!stableChildren.includes(child)) child.remove();
  }

  detail.dataset.sourceManagerFingerprint = sourceManagerDetailFingerprint(
    source,
    activeRequest,
    busy
  );
  detail.scrollTop = scrollTop;

  if (focusedAction) {
    const sameAction = detail.querySelector(
      `[data-source-action="${CSS.escape(focusedAction)}"]:not(:disabled)`
    );
    const fallback = sameAction
      || detail.querySelector("[data-source-action]:not(:disabled)")
      || viewButton;
    fallback?.focus({ preventScroll: true });
    detail.scrollTop = scrollTop;
  }
}

function sourceManagerDetailFingerprint(source, activeRequest, busy) {
  return JSON.stringify([
    source.id,
    source.kind,
    source.displayName,
    source.state,
    sourceManagementActionsForCurrentState(source),
    activeRequest?.id || null,
    activeRequest?.action || null,
    activeRequest?.sourceID || null,
    activeRequest?.phase || null,
    Boolean(busy),
    Boolean(state.online),
    Boolean(state.sourceManagement.submitting),
  ]);
}

function reconcileSourceManagerContent(sources, selectedSource, activeRequest, busy) {
  const navigation = elements.sourceManagerList.querySelector(
    ":scope > .source-manager-source-list"
  );
  const detail = elements.sourceManagerList.querySelector(
    ":scope > .source-manager-detail"
  );
  if (!navigation || !detail) return false;
  const navigationScrollTop = navigation.scrollTop;
  const focusedRow = navigation.contains(document.activeElement)
    ? document.activeElement.closest(".source-manager-row")
    : null;
  const existingRows = new Map(
    [...navigation.querySelectorAll(":scope > .source-manager-row")]
      .map((row) => [row.dataset.sourceManagerId, row])
  );
  const nextDetailFingerprint = sourceManagerDetailFingerprint(
    selectedSource,
    activeRequest,
    busy
  );
  const wantedRows = sources.map((source) => {
    const row = existingRows.get(source.id) || document.createElement("button");
    const nextFingerprint = sourceManagerRowFingerprint(source, selectedSource.id);
    if (row.dataset.sourceManagerFingerprint !== nextFingerprint) {
      syncSourceManagerRow(row, source, selectedSource.id);
    }
    return row;
  });
  reconcileStableChildren(navigation, wantedRows);
  navigation.scrollTop = navigationScrollTop;
  if (focusedRow && !wantedRows.includes(focusedRow)) {
    navigation.querySelector(
      `[data-source-manager-select="${CSS.escape(selectedSource.id)}"]`
    )?.focus({ preventScroll: true });
    navigation.scrollTop = navigationScrollTop;
  }
  if (detail.dataset.sourceManagerFingerprint !== nextDetailFingerprint) {
    syncSourceManagerDetail(detail, selectedSource, activeRequest, busy);
  }
  return true;
}

function sourceManagerPendingPart(part, tagName, className = "") {
  let node = elements.sourceManagerPending.querySelector(
    `[data-source-manager-pending-part="${CSS.escape(part)}"]`
  );
  if (node && node.localName !== tagName) {
    node.remove();
    node = null;
  }
  if (!node) {
    node = document.createElement(tagName);
    node.dataset.sourceManagerPendingPart = part;
    node.className = className;
  }
  return node;
}

function syncSourceManagerPending(activeRequest) {
  const pending = elements.sourceManagerPending;
  pending.classList.toggle("hidden", !activeRequest);
  if (!activeRequest) {
    if (pending.childElementCount) pending.replaceChildren();
    return;
  }

  const wanted = [];
  const copy = sourceManagerPendingPart("message", "span");
  copy.textContent = `${activeRequest.message}（可切回网页等待，完成后会自动更新）`;
  wanted.push(copy);

  if (sourceManagementIsPrewarmAction(activeRequest.action)) {
    if (Number.isInteger(activeRequest.completedCount)
      && Number.isInteger(activeRequest.totalCount)) {
      const progress = sourceManagerPendingPart(
        "progress",
        "progress",
        "source-prewarm-progress"
      );
      progress.max = Math.max(1, activeRequest.totalCount);
      progress.value = Math.min(activeRequest.completedCount, progress.max);
      progress.setAttribute(
        "aria-label",
        `缩略图预热 ${activeRequest.completedCount} / ${activeRequest.totalCount}`
      );
      wanted.push(progress);

      const counts = sourceManagerPendingPart("counts", "small");
      const sourceCounts = Number.isInteger(activeRequest.completedSourceCount)
        && Number.isInteger(activeRequest.totalSourceCount)
        ? `来源 ${activeRequest.completedSourceCount + 1} / ${activeRequest.totalSourceCount} · `
        : "";
      const reused = Number(activeRequest.reusedCount || 0);
      const ineligible = Number(activeRequest.ineligibleCount || 0);
      const details = [
        `生成 ${activeRequest.warmedCount || 0}`,
        reused > 0 ? `复用 ${reused}` : null,
        ineligible > 0 ? `不可处理跳过 ${ineligible}` : null,
        `失败 ${activeRequest.failedCount || 0}`,
      ].filter(Boolean).join(" · ");
      counts.textContent = `${sourceCounts}${details}`;
      wanted.push(counts);
    }

    const cancel = sourceManagerPendingPart(
      "cancel",
      "button",
      "button button-small"
    );
    cancel.type = "button";
    cancel.dataset.sourcePendingAction = "cancelPrewarm";
    cancel.dataset.sourceId = activeRequest.sourceID || "";
    cancel.textContent = "取消";
    cancel.disabled = state.sourceManagement.submitting || !state.online;
    if (!cancel.dataset.sourceManagerPendingBound) {
      cancel.dataset.sourceManagerPendingBound = "true";
      cancel.addEventListener("click", () => {
        submitSourceManagementAction(
          cancel.dataset.sourcePendingAction,
          cancel.dataset.sourceId || null
        );
      });
    }
    wanted.push(cancel);
  } else if (sourceManagementIsBatchAuthorizationAction(activeRequest.action)
    && Number.isInteger(activeRequest.completedSourceCount)
    && Number.isInteger(activeRequest.totalSourceCount)) {
    const progress = sourceManagerPendingPart("batch-progress", "small");
    progress.textContent = `已完成来源 ${activeRequest.completedSourceCount} / ${activeRequest.totalSourceCount}`;
    wanted.push(progress);
  }

  for (const [index, node] of wanted.entries()) {
    if (pending.children[index] !== node) {
      pending.insertBefore(node, pending.children[index] || null);
    }
  }
  for (const child of [...pending.children]) {
    if (!wanted.includes(child)) child.remove();
  }
}

function renderSourceManagement({ preserveContent = false, reconcileContent = true } = {}) {
  const manager = state.sourceManagement;
  const snapshot = manager.snapshot;
  const activeRequest = sourceManagementActiveRequest();
  const busy = manager.loading || manager.submitting || Boolean(activeRequest);
  syncCurrentSourceRefreshControl();
  renderSidebarSourceActions();
  elements.sourceConnectFolderButton.disabled = busy || !state.online;
  elements.sourceConnectPhotosButton.disabled = busy || !state.online || !snapshot?.canConnectPhotos;
  const hasActiveSource = (snapshot?.sources || []).some((source) => source.state === "active");
  const hasPrewarmSource = (snapshot?.sources || []).some(
    (source) => ["active", "unavailable"].includes(source.state)
  );
  elements.sourceRefreshAllButton.disabled = busy || !state.online || !hasActiveSource;
  elements.sourcePrewarmAllButton.disabled = busy || !state.online || !hasPrewarmSource;
  elements.sourcePrewarmAllOriginalButton.disabled = busy || !state.online || !hasPrewarmSource;
  const accessAuthorizationTargets = (snapshot?.sources || []).filter((source) => (
    source.kind === "folder"
      ? ["unavailable", "authorizationRequired"].includes(source.state)
      : ["authorizationRequired", "disabled"].includes(source.state)
  ));
  const mutationAuthorizationTargets = (snapshot?.sources || []).filter(
    (source) => source.kind === "folder" && source.state === "active"
  );
  const activePhotosSource = (snapshot?.sources || []).find(
    (source) => source.kind === "photos" && source.state === "active"
  );
  elements.sourceReauthorizeAllButton.textContent = `依次重新授权需要访问权限的来源（${accessAuthorizationTargets.length}）…`;
  elements.sourceRefreshAllMutationAuthorizationButton.textContent = `依次更新全部文件夹回收权限（${mutationAuthorizationTargets.length}）…`;
  elements.sourceReauthorizeAllButton.title = "按来源依次显示系统授权窗口；取消任意一次会停止后续来源";
  elements.sourceRefreshAllMutationAuthorizationButton.title = "按文件夹依次确认回收权限；不会立即修改任何照片";
  elements.sourceRequestPhotosWriteAuthorizationButton.title = "Apple Photos 权限由系统图库统一管理，只需请求一次";
  elements.sourceReauthorizeAllButton.disabled = busy
    || !state.online || accessAuthorizationTargets.length === 0;
  elements.sourceRefreshAllMutationAuthorizationButton.disabled = busy
    || !state.online || mutationAuthorizationTargets.length === 0;
  elements.sourceRequestPhotosWriteAuthorizationButton.classList.toggle(
    "hidden",
    !activePhotosSource
  );
  elements.sourceRequestPhotosWriteAuthorizationButton.disabled = busy
    || !state.online || !activePhotosSource;
  elements.sourceRequestPhotosWriteAuthorizationButton.dataset.sourceId = activePhotosSource?.id || "";
  elements.sourceRefreshAllButton.title = hasActiveSource
    ? "为全部活跃文件夹排入重扫，并同步全部活跃 Apple Photos 来源"
    : "当前没有可更新的活跃来源";
  elements.sourcePrewarmAllButton.title = hasPrewarmSource
    ? "依次检查全部来源的网格缩略图；复用已有缓存，只生成当前可处理的缺失项"
    : "当前没有可缓存的来源";
  elements.sourcePrewarmAllOriginalButton.title = hasPrewarmSource
    ? "依次检查全部来源的原比例网格缓存；复用已有缓存，只生成当前可处理的缺失项"
    : "当前没有可缓存的来源";
  elements.sourceConnectPhotosButton.title = snapshot?.canConnectPhotos
    ? "在 Mac 上确认并请求 Apple Photos 权限"
    : "已有 Apple Photos 来源；请在对应来源上恢复或重新绑定";
  elements.sourceManagerRefreshButton.disabled = manager.loading;
  syncSourceManagerPending(activeRequest);
  renderSourceManagerHistoryNotice();
  renderSourcePrewarmStatus();

  const preservedSelectedSource = sourceManagerSelectedSource();
  if (preserveContent
    && preservedSelectedSource
    && elements.sourceManagerList.querySelector(".source-manager-source-list")
    && elements.sourceManagerList.querySelector(
      `[data-source-manager-detail="${CSS.escape(preservedSelectedSource.id)}"]`
    )) {
    syncRenderedSourceManagerDetailActions(preservedSelectedSource, activeRequest, busy);
    return;
  }

  const sources = snapshot?.sources || [];
  const activeSourceCount = sources.filter((source) => source.state === "active").length;
  elements.sourceManagerListSummary.textContent = sources.length
    ? `${sources.length} 个来源 · ${activeSourceCount} 个可用`
    : manager.loading ? "正在读取 Mac 上的来源…" : "没有已连接来源";
  elements.sourceManagerEmpty.classList.toggle("hidden", sources.length > 0 || manager.loading);
  if (!sources.length) {
    clearElement(elements.sourceManagerList);
    return;
  }

  const preferredSourceIDs = [
    state.sourceManagement.selectedSourceID,
    activeRequest?.sourceID,
    state.selectedSourceID,
    sources[0]?.id,
  ].filter(Boolean);
  if (!preferredSourceIDs.includes(state.sourceManagement.selectedSourceID)
    || !sources.some((source) => source.id === state.sourceManagement.selectedSourceID)) {
    state.sourceManagement.selectedSourceID = preferredSourceIDs.find(
      (sourceID) => sources.some((source) => source.id === sourceID)
    ) || sources[0].id;
  }
  const selectedSource = sourceManagerSelectedSource() || sources[0];

  if (reconcileContent
    && reconcileSourceManagerContent(sources, selectedSource, activeRequest, busy)) return;

  clearElement(elements.sourceManagerList);

  const sourceNavigation = document.createElement("nav");
  sourceNavigation.className = "source-manager-source-list";
  sourceNavigation.setAttribute("aria-label", "已连接来源");
  sourceNavigation.setAttribute("role", "listbox");
  for (const source of sources) {
    const row = document.createElement("button");
    syncSourceManagerRow(row, source, selectedSource.id);
    sourceNavigation.append(row);
  }

  const detail = document.createElement("section");
  syncSourceManagerDetail(detail, selectedSource, activeRequest, busy);
  elements.sourceManagerList.append(sourceNavigation, detail);
}

function scheduleSourceManagementPoll() {
  clearTimeout(state.sourceManagement.pollTimer);
  state.sourceManagement.pollTimer = null;
  if (!sourceManagementHasActiveRequest()) return;
  state.sourceManagement.pollTimer = setTimeout(() => {
    loadSourceManagement({ quiet: true, notifyTerminal: true });
  }, 1_000);
}

async function reconcileSlimmingRecycleSourceProjection() {
  if (elements.slimmingWorkspace.classList.contains("hidden")
    || state.slimming.view !== "recycle") return;
  const recycleSourceInvalidated = Boolean(state.slimming.recycle.sourceID)
    && !state.sources.some(
      (source) => source.id === state.slimming.recycle.sourceID
    );
  if (recycleSourceInvalidated) {
    state.slimming.recycle.sourceID = "";
    state.slimming.recycle.limit = 60;
    await loadSlimmingRecycle({ quiet: true });
    return;
  }
  const scrollTop = elements.slimmingRecycleBody.scrollTop;
  renderSlimmingRecycle({ preserveList: true });
  elements.slimmingRecycleBody.scrollTop = scrollTop;
}

function applySourceManagementSourcesToWorkspace(sources) {
  if (projectionFingerprint(sources) === projectionFingerprint(state.sources)) return;
  state.sources = sources;
  state.folderNavigation.branches.clear();
  state.folderNavigation.branchRequestGenerations.clear();
  state.folderNavigation.searches.clear();
  state.folderNavigation.searchRequestGenerations.clear();
  state.folderNavigation.requestGeneration += 1;
  if (state.selectedSourceID
    && !state.sources.some((source) => source.id === state.selectedSourceID)) {
    state.selectedSourceID = "";
    state.selectedAssetID = null;
    state.selectedDetail = null;
  }
  renderSources();
  sanitizeReviewSourceFilter();
  renderReviewSourceFilter();
  renderReviewLocalModelStatus();
  updateLibraryTitle();
  renderLibraryEmptyState();
}

async function loadSourceManagement({ quiet = false, notifyTerminal = false } = {}) {
  const manager = state.sourceManagement;
  if (manager.loading) return;
  const generation = ++manager.requestGeneration;
  const hadSnapshot = Boolean(manager.snapshot);
  const previousSnapshotFingerprint = sourceManagementSnapshotFingerprint(manager.snapshot);
  let preserveLoadedContent = hadSnapshot;
  let reconcileLoadedContent = false;
  manager.loading = !quiet;
  renderSourceManagement({ preserveContent: hadSnapshot });
  try {
    const snapshot = await api("/v1/source-management");
    if (generation !== manager.requestGeneration) return;
    preserveLoadedContent = previousSnapshotFingerprint
      === sourceManagementSnapshotFingerprint(snapshot);
    reconcileLoadedContent = hadSnapshot && !preserveLoadedContent;
    manager.snapshot = snapshot;
    applySourceManagementSourcesToWorkspace(snapshot.sources);
    let shouldRefreshWorkspaceNotice = false;
    for (const request of snapshot.requests || []) {
      if (!["completed", "cancelled", "failed"].includes(request.phase)) continue;
      const firstSeen = !manager.seenTerminalRequestIDs.has(request.id);
      manager.seenTerminalRequestIDs.add(request.id);
      if (notifyTerminal && hadSnapshot && firstSeen) toast(request.message);
      if (firstSeen && request.action === "delete") shouldRefreshWorkspaceNotice = true;
    }
    if (shouldRefreshWorkspaceNotice) await loadWorkspaceNotice({ quiet: true });
  } catch (error) {
    if (!quiet) toast(error.message || "无法读取来源管理状态");
  } finally {
    if (generation === manager.requestGeneration) {
      manager.loading = false;
      renderSourceManagement({
        preserveContent: preserveLoadedContent,
        reconcileContent: reconcileLoadedContent,
      });
      await reconcileSlimmingRecycleSourceProjection();
      scheduleSourceManagementPoll();
    }
  }
}

function sourceManagerBaseLevelFromHistory(context = {}) {
  return ["sidebar", "inspector", "lightbox"].includes(context.sourceManagerBaseLevel)
    ? context.sourceManagerBaseLevel
    : "workspace";
}

function replaceSourceManagerHistoryWithBase(baseLevel) {
  if (!state.workspaceNavigation.initialized
    || elements.appView.classList.contains("hidden")) return;
  const current = activeWorkspaceHistoryEntry();
  const route = visibleWorkspaceRoute();
  if (current?.route !== route || current.navigationLevel !== "sourceManager") return;
  const context = currentWorkspaceHistoryContext(route);
  if (context && typeof context === "object") delete context.sourceManagerBaseLevel;
  const navigationLevel = visibleWorkspaceNavigationBaseLevel(route, baseLevel);
  history.replaceState({
    ...(history.state || {}),
    [WORKSPACE_HISTORY_KEY]: workspaceHistoryEntry(route, context, navigationLevel),
  }, "", location.href);
}

async function openSourceManager({
  selectedSourceID = null,
  focus = true,
  historyMode = "pushSourceManager",
  baseLevel = null,
  refresh = true,
  returnFocus = null,
  preserveState = false,
} = {}) {
  if (!state.online || state.sourceManagerOpening) return;
  if (elements.sourceManagerDialog.open) {
    if (selectedSourceID) {
      state.sourceManagement.selectedSourceID = selectedSourceID;
      renderSourceManagement();
    }
    if (focus) restoreOverlayFocus(elements.sourceManagerCloseButton);
    return;
  }
  state.sourceManagerOpening = true;
  try {
    state.sourceManagerReturnFocus = returnFocus
      || (document.activeElement instanceof HTMLElement ? document.activeElement : null);
    if (!preserveState) {
      state.sourceManagerReturnDescriptor = sourceManagerReturnFocusDescriptor(
        state.sourceManagerReturnFocus
      );
      state.sourceManagerFocus = { kind: "control", id: "sourceConnectFolderButton" };
      state.sourceManagerNavigationScrollTop = 0;
      state.sourceManagerDetailScrollTop = 0;
      state.sourceManagerAllActionsOpen = false;
      state.sourceManagerBatchAuthorizationOpen = false;
      state.sourceManagerHistoryNotice = "";
    }
    const current = activeWorkspaceHistoryEntry();
    state.sourceManagerBaseLevel = baseLevel
      || workspaceNavigationBaseLevel(
        current?.navigationLevel || "workspace",
        current?.context || {}
      );
    if (selectedSourceID) state.sourceManagement.selectedSourceID = selectedSourceID;
    if (!preserveState) closeSourceManagerAllActions();
    elements.sourceManagerDialog.showModal();
    if (historyMode !== "none") {
      const route = visibleWorkspaceRoute();
      recordWorkspaceHistory(route, currentWorkspaceHistoryContext(route), historyMode);
    }
    if (refresh) state.sourceManagement.snapshot = null;
    if (focus) restoreOverlayFocus(elements.sourceManagerCloseButton);
    if (refresh || !state.sourceManagement.snapshot) await loadSourceManagement();
    else {
      renderSourceManagement();
      scheduleSourceManagementPoll();
    }
    if (focus && elements.sourceManagerDialog.open) {
      restoreOverlayFocus(elements.sourceConnectFolderButton.disabled
        ? elements.sourceManagerCloseButton
        : elements.sourceConnectFolderButton);
    }
    state.sourceManagerRestorable = true;
    scheduleWorkspaceHistoryCheckpoint();
  } finally {
    state.sourceManagerOpening = false;
  }
}

async function openSourceManagerForAction(action) {
  await openSourceManager();
  if (!elements.sourceManagerDialog.open) return;
  requestSourceManagementAction(action, null);
}

function closeSourceManager({
  restoreFocus = true,
  checkpoint = true,
  preserveState = false,
} = {}) {
  if (!elements.sourceManagerDialog.open) return;
  if (elements.confirmDialog.open && state.confirmationBaseLevel === "sourceManager") {
    closeConfirmation({ restoreFocus: false, checkpoint: false, preserveState: false });
  }
  clearTimeout(state.sourceManagement.pollTimer);
  state.sourceManagement.pollTimer = null;
  state.sourceManagement.requestGeneration += 1;
  state.sourceManagement.loading = false;
  captureSourceManagerLayout();
  const baseLevel = state.sourceManagerBaseLevel;
  const returnFocus = resolveSourceManagerReturnFocus();
  if (!preserveState) {
    state.sourceManagerReturnFocus = null;
    state.sourceManagerReturnDescriptor = null;
  }
  state.sourceManagerBaseLevel = preserveState ? baseLevel : "workspace";
  if (!preserveState) closeSourceManagerAllActions();
  if (elements.sourceManagerDialog.open) elements.sourceManagerDialog.close();
  if (restoreFocus) {
    restoreOverlayFocus(stableReturnFocusTarget(returnFocus, elements.sourceManagerButton));
  }
  if (checkpoint) replaceSourceManagerHistoryWithBase(baseLevel);
  renderSourcePrewarmStatus();
  scheduleSourceManagementPoll();
  if (!preserveState) {
    state.sourceManagerRestorable = false;
    state.sourceManagerFocus = { kind: "control", id: "sourceConnectFolderButton" };
    state.sourceManagerNavigationScrollTop = 0;
    state.sourceManagerDetailScrollTop = 0;
    state.sourceManagerAllActionsOpen = false;
    state.sourceManagerBatchAuthorizationOpen = false;
    state.sourceManagerHistoryNotice = "";
    renderSourceManagerHistoryNotice();
  }
}

function returnFromSourceManager({ restoreFocus = true } = {}) {
  if (elements.confirmDialog.open && state.confirmationBaseLevel === "sourceManager") {
    return returnFromConfirmation({ restoreFocus });
  }
  if (!elements.sourceManagerDialog.open) return Promise.resolve();
  state.sourceManagerHistoryRestoreFocus = restoreFocus;
  if (state.workspaceNavigation.pendingReturnPromise) {
    return state.workspaceNavigation.pendingReturnPromise;
  }
  const current = activeWorkspaceHistoryEntry();
  if (state.workspaceNavigation.initialized
    && current?.route === visibleWorkspaceRoute()
    && current.navigationLevel === "sourceManager") {
    const pending = new Promise((resolve) => {
      state.workspaceNavigation.pendingReturnResolve = resolve;
    });
    state.workspaceNavigation.pendingReturnPromise = pending;
    history.back();
    return pending;
  }
  closeSourceManager({ restoreFocus });
  state.sourceManagerHistoryRestoreFocus = true;
  return Promise.resolve();
}

async function reconcileSourceManagerFromWorkspaceHistory(
  route,
  navigationLevel,
  context = {}
) {
  const shouldOpen = (
    navigationLevel === "sourceManager"
    || (navigationLevel === "confirmation"
      && context.confirmationBaseLevel === "sourceManager")
  ) && route === visibleWorkspaceRoute();
  if (shouldOpen && !state.online) return;
  if (shouldOpen && !state.sourceManagerRestorable) {
    applySourceManagerHistoryContext(context);
    await openSourceManager({
      focus: false,
      historyMode: "none",
      baseLevel: sourceManagerBaseLevelFromHistory(context),
      refresh: false,
      preserveState: true,
    });
    if (navigationLevel === "sourceManager") {
      await restoreSourceManagerLayoutFromHistory();
    }
    return true;
  }
  if (shouldOpen && !elements.sourceManagerDialog.open) {
    await openSourceManager({
      focus: false,
      historyMode: "none",
      baseLevel: sourceManagerBaseLevelFromHistory(context),
      refresh: false,
      preserveState: true,
    });
    if (navigationLevel === "sourceManager") {
      await restoreSourceManagerLayoutFromHistory();
    }
  } else if (!shouldOpen && elements.sourceManagerDialog.open) {
    const restoreFocus = state.sourceManagerHistoryRestoreFocus;
    closeSourceManager({ restoreFocus, checkpoint: false, preserveState: true });
    state.sourceManagerHistoryRestoreFocus = true;
  }
  return false;
}

async function submitSourceManagementAction(action, sourceID = null) {
  const manager = state.sourceManagement;
  const cancellingPrewarm = action === "cancelPrewarm";
  if (!state.online
    || manager.submitting
    || (sourceManagementHasActiveRequest() && !cancellingPrewarm)) return;
  manager.submitting = true;
  renderSourceManagement();
  try {
    const request = await api("/v1/source-management/requests", {
      method: "POST",
      body: JSON.stringify({ operationID: crypto.randomUUID(), action, sourceID }),
    });
    const snapshot = manager.snapshot || { sources: state.sources, canConnectPhotos: false, requests: [] };
    manager.snapshot = {
      ...snapshot,
      requests: [request, ...(snapshot.requests || []).filter((item) => item.id !== request.id)],
    };
    renderSourceManagement();
    if (["completed", "cancelled", "failed"].includes(request.phase)) {
      manager.seenTerminalRequestIDs.add(request.id);
      toast(request.message || "来源操作已结束");
    }
    if (["refreshAll", "rescan", "syncPhotos"].includes(action)) {
      void refreshJobs({
        announce: false,
        indicateBusy: false,
        reportError: false,
      });
    }
    scheduleSourceManagementPoll();
  } catch (error) {
    toast(error.message || "Mac 未能接收来源操作");
  } finally {
    manager.submitting = false;
    renderSourceManagement();
  }
}

function requestSourceManagementAction(action, sourceID) {
  const source = state.sourceManagement.snapshot?.sources
    ?.find((item) => item.id === sourceID);
  const sourceName = source?.displayName || "当前来源";
  const confirmations = {
    connectPhotos: {
      eyebrow: "APPLE PHOTOS",
      title: "连接 Apple Photos？",
      message: "ImageAll 平时只读访问静态照片和元数据，并在自身容器保存索引、标签和缓存；只有你在“图库瘦身”中明确确认时，才会经系统 Photos 将所选照片移入“最近删除”。普通浏览不会自动下载 iCloud 原图。",
      actionLabel: "继续并请求照片权限",
      tone: "standard",
    },
    rebindPhotos: {
      eyebrow: "PHOTO LIBRARY",
      title: "连接当前系统照片图库？",
      message: "ImageAll 会保留旧图库的索引、人工标签和历史，并为当前系统照片图库创建一个新的来源。不会迁移或合并无法确认身份的照片，也不会修改 Apple Photos 中的原图。",
      actionLabel: "保留历史并连接",
      tone: "standard",
    },
    fullRepair: {
      eyebrow: "FULL REPAIR",
      title: `对“${sourceName}”执行完整修复扫描？`,
      message: "这会重新扫描整个 Apple Photos 图库，并在后台修复先前可能误标为缺失的照片。扫描期间仍可浏览已有索引；大图库可能需要数分钟。",
      actionLabel: "开始完整修复扫描",
      tone: "warning",
    },
    delete: {
      eyebrow: "REMOVE SOURCE",
      title: `删除来源“${source?.displayName || ""}”？`,
      message: "网页提交后，Mac 还会再次确认。只删除 ImageAll 的来源记录、相关索引和 App 缓存；不会删除磁盘或 Apple Photos 中的原始媒体。",
      actionLabel: "交给 Mac 确认",
      tone: "danger",
    },
  };
  const confirmation = confirmations[action];
  if (!confirmation) {
    submitSourceManagementAction(action, sourceID || null);
    return;
  }
  requestConfirmation({
    ...confirmation,
    returnFocus: { sourceID: sourceID || null, sourceAction: action },
    action: () => submitSourceManagementAction(action, sourceID),
  });
}

function storageMaintenanceActiveRequest() {
  return (state.storageMaintenance.snapshot?.requests || [])
    .find((request) => ["awaitingMac", "running"].includes(request.phase)) || null;
}

function storageMaintenanceHasActiveRequest() {
  return Boolean(storageMaintenanceActiveRequest());
}

const STORAGE_MAINTENANCE_HISTORY_FOCUS_IDS = new Set([
  "storageCloseButton",
  "clearPreviewCacheButton",
  "clearPhotosOriginalsButton",
  "chooseExternalStorageButton",
  "exportPortableDataButton",
  "storageRefreshButton",
]);
const STORAGE_MAINTENANCE_HISTORY_RETURN_IDS = new Set([
  "storageButton",
  "toolbarExportPortableDataButton",
  "compactToolbarMenuButton",
  "commandButton",
]);

function normalizedStorageMaintenanceHistoryFocusID(value) {
  return STORAGE_MAINTENANCE_HISTORY_FOCUS_IDS.has(value)
    ? value
    : "storageRefreshButton";
}

function captureStorageMaintenanceHistoryFocus() {
  if (!elements.storageDialog.open) return;
  const active = document.activeElement;
  if (!(active instanceof HTMLElement)
    || !elements.storageDialog.contains(active)
    || !STORAGE_MAINTENANCE_HISTORY_FOCUS_IDS.has(active.id)) return;
  state.storageFocusID = active.id;
}

function currentStorageMaintenanceHistoryContext() {
  if (elements.storageDialog.open) {
    captureStorageMaintenanceHistoryFocus();
    state.storageScrollTop = elements.storageContent.scrollTop;
  }
  return {
    storageFocusID: normalizedStorageMaintenanceHistoryFocusID(state.storageFocusID),
    storageScrollTop: Math.max(
      0,
      workspaceHistoryFiniteNumber(state.storageScrollTop)
    ),
    storageReturnControlID: STORAGE_MAINTENANCE_HISTORY_RETURN_IDS.has(
      state.storageReturnControlID
    ) ? state.storageReturnControlID : null,
  };
}

function applyStorageMaintenanceHistoryContext(context = {}) {
  state.storageFocusID = normalizedStorageMaintenanceHistoryFocusID(
    context.storageFocusID
  );
  state.storageScrollTop = Math.max(
    0,
    workspaceHistoryFiniteNumber(context.storageScrollTop)
  );
  state.storageReturnControlID = STORAGE_MAINTENANCE_HISTORY_RETURN_IDS.has(
    context.storageReturnControlID
  ) ? context.storageReturnControlID : null;
  state.storageReturnFocus = null;
}

function storageMaintenanceReturnControlID(element) {
  return element instanceof HTMLElement
    && STORAGE_MAINTENANCE_HISTORY_RETURN_IDS.has(element.id)
    ? element.id
    : null;
}

function resolveStorageMaintenanceReturnFocus() {
  if (state.storageReturnFocus?.isConnected) return state.storageReturnFocus;
  if (state.storageReturnControlID) {
    const target = document.getElementById(state.storageReturnControlID);
    if (target instanceof HTMLElement && !target.disabled && target.getClientRects().length) {
      return target;
    }
  }
  return stableReturnFocusTarget(
    elements.storageButton,
    stableReturnFocusTarget(elements.compactToolbarMenuButton, elements.commandButton)
  );
}

async function restoreStorageMaintenanceLayoutFromHistory() {
  await waitForWorkspaceLayout();
  const scrollTop = Math.min(
    state.storageScrollTop,
    Math.max(0, elements.storageContent.scrollHeight - elements.storageContent.clientHeight)
  );
  elements.storageContent.scrollTop = scrollTop;
  let target = document.getElementById(
    normalizedStorageMaintenanceHistoryFocusID(state.storageFocusID)
  );
  if (!(target instanceof HTMLElement)
    || target.disabled
    || !elements.storageDialog.contains(target)
    || target.offsetParent === null) {
    target = elements.storageRefreshButton.disabled
      ? elements.storageCloseButton
      : elements.storageRefreshButton;
  }
  target.focus({ preventScroll: true });
  state.storageFocusID = target.id;
  state.storageScrollTop = scrollTop;
  elements.storageContent.scrollTop = scrollTop;
}

function storageMaintenanceNeedsPoll() {
  if (storageMaintenanceHasActiveRequest()) return true;
  if (!elements.storageDialog.open) return false;
  return storageActionAvailability("clearPhotosOriginals").reason
    === "librarySlimmingAnalysisInProgress";
}

function storageActionLabel(action) {
  return {
    exportPortableData: "导出用户数据",
    chooseExternalStorage: "选择外置存储",
    clearPreviewCache: "清理预览缓存",
    clearPhotosOriginals: "清理 Photos 原图副本",
  }[action] || action;
}

function storageActionButton(action) {
  return {
    exportPortableData: elements.exportPortableDataButton,
    chooseExternalStorage: elements.chooseExternalStorageButton,
    clearPreviewCache: elements.clearPreviewCacheButton,
    clearPhotosOriginals: elements.clearPhotosOriginalsButton,
  }[action] || null;
}

function storageActionAvailability(action, snapshot = state.storageMaintenance.snapshot) {
  if (!snapshot) return { isAvailable: false, reason: null };
  const projected = action === "clearPreviewCache"
    ? snapshot.clearPreviewCacheAvailability
    : action === "clearPhotosOriginals"
      ? snapshot.clearPhotosOriginalsAvailability
      : null;
  if (typeof projected?.isAvailable === "boolean") return projected;

  // Older Hosts do not project action availability. Keep browsing compatible,
  // while still matching Mac's empty-cache behavior from the redacted counts.
  const usage = action === "clearPreviewCache"
    ? snapshot.previewCache
    : action === "clearPhotosOriginals" ? snapshot.photosOriginals : null;
  if (usage && Number(usage.entryCount || 0) <= 0) {
    return { isAvailable: false, reason: "empty" };
  }
  return { isAvailable: true, reason: null };
}

function storageActionUnavailableMessage(reason) {
  return {
    empty: "当前没有可清理的内容。",
    librarySlimmingAnalysisInProgress: "相同检测运行期间不能清理；暂停或完成后可操作。",
  }[reason] || "当前不能执行此操作。";
}

function storageRequestMark(phase) {
  return {
    awaitingMac: "◷",
    running: "↻",
    completed: "✓",
    cancelled: "−",
    failed: "!",
  }[phase] || "•";
}

function storageRequestFingerprint(request) {
  return JSON.stringify([
    request.id,
    request.action,
    request.phase,
    request.message,
    request.updatedAtMs,
  ]);
}

function createStorageHistoryRow() {
  const row = document.createElement("article");
  row.className = "storage-history-row";
  const mark = document.createElement("span");
  mark.className = "storage-history-mark";
  mark.setAttribute("aria-hidden", "true");
  const message = document.createElement("span");
  message.className = "storage-history-message";
  const time = document.createElement("small");
  row.append(mark, message, time);
  return row;
}

function syncStorageHistoryRow(row, request) {
  const fingerprint = storageRequestFingerprint(request);
  if (row.dataset.storageRequestFingerprint === fingerprint) return;
  row.dataset.storageRequestId = request.id;
  row.dataset.storageRequestFingerprint = fingerprint;
  row.dataset.phase = request.phase;
  row.querySelector(".storage-history-mark").textContent = storageRequestMark(request.phase);
  const message = row.querySelector(".storage-history-message");
  message.textContent = request.message;
  message.title = `${storageActionLabel(request.action)}：${request.message}`;
  row.querySelector("small").textContent = formatDate(request.updatedAtMs);
}

function reconcileStorageHistory(requests) {
  const existing = new Map(
    [...elements.storageHistory.querySelectorAll(":scope > [data-storage-request-id]")]
      .map((row) => [row.dataset.storageRequestId, row])
  );
  const rows = requests.map((request) => {
    const row = existing.get(request.id) || createStorageHistoryRow();
    existing.delete(request.id);
    syncStorageHistoryRow(row, request);
    return row;
  });
  reconcileStableChildren(elements.storageHistory, rows);
}

function renderStorageMaintenance() {
  const manager = state.storageMaintenance;
  const snapshot = manager.snapshot;
  const activeRequest = storageMaintenanceActiveRequest();
  const busy = manager.loading || manager.submitting || Boolean(activeRequest);
  const hasSnapshot = Boolean(snapshot);
  const previewClearAvailability = storageActionAvailability("clearPreviewCache", snapshot);
  const originalsClearAvailability = storageActionAvailability("clearPhotosOriginals", snapshot);

  const storageStatus = activeRequest?.phase === "awaitingMac"
    ? "等待 Mac"
    : activeRequest ? "存储处理中" : "预览缓存";
  elements.storageStatusLabel.textContent = storageStatus;
  elements.storageButton.classList.toggle("busy", Boolean(activeRequest));
  elements.storageButton.setAttribute("aria-busy", String(Boolean(activeRequest)));
  elements.storageButton.setAttribute(
    "aria-label",
    activeRequest
      ? `${activeRequest.message}，打开应用存储与预览缓存`
      : "应用存储与预览缓存"
  );
  elements.storageButton.title = activeRequest
    ? `${activeRequest.message}（可继续浏览，点击查看）`
    : "应用存储与预览缓存";
  elements.toolbarExportPortableDataButton.disabled = !state.online || busy;
  elements.toolbarExportPortableDataButton.setAttribute("aria-busy", String(Boolean(activeRequest)));
  elements.toolbarExportPortableDataButton.title = activeRequest
    ? `${activeRequest.message}（当前不能再次导出）`
    : "导出用户数据";
  syncCompactToolbarMenu();

  elements.storageLoading.classList.toggle("hidden", hasSnapshot || !manager.loading);
  elements.storageContent.classList.toggle("hidden", !hasSnapshot);
  elements.storageRefreshButton.disabled = manager.loading;
  for (const button of [
    elements.clearPreviewCacheButton,
    elements.clearPhotosOriginalsButton,
    elements.chooseExternalStorageButton,
    elements.exportPortableDataButton,
  ]) {
    button.disabled = busy || !state.online || !hasSnapshot;
  }
  elements.clearPreviewCacheButton.disabled ||= !previewClearAvailability.isAvailable;
  elements.clearPhotosOriginalsButton.disabled ||= !originalsClearAvailability.isAvailable;
  const originalsBlockedByAnalysis = originalsClearAvailability.reason
    === "librarySlimmingAnalysisInProgress";
  elements.photosOriginalsBlocked.classList.toggle("hidden", !originalsBlockedByAnalysis);
  elements.clearPhotosOriginalsButton.title = originalsClearAvailability.isAvailable
    ? "打开清理确认；删除 ImageAll 自有的 Photos 原图副本，不修改 Apple Photos。"
    : storageActionUnavailableMessage(originalsClearAvailability.reason);
  if (manager.pendingReturnAction && !busy && elements.storageDialog.open) {
    const returnButton = storageActionButton(manager.pendingReturnAction);
    manager.pendingReturnAction = null;
    requestAnimationFrame(() => {
      (returnButton && !returnButton.disabled ? returnButton : elements.storageRefreshButton)
        ?.focus({ preventScroll: true });
    });
  }
  elements.storagePending.classList.toggle("hidden", !activeRequest);
  elements.storagePending.textContent = activeRequest
    ? `${activeRequest.message}（完成 Mac 上的操作后，本页会自动更新）`
    : "";

  if (!snapshot) return;
  elements.previewCacheSize.textContent = formatFileSize(snapshot.previewCache.registeredBytes);
  elements.previewCacheEntries.textContent = `${snapshot.previewCache.entryCount.toLocaleString("zh-CN")} 条可重建记录`;
  elements.photosOriginalsSize.textContent = formatFileSize(snapshot.photosOriginals.registeredBytes);
  elements.photosOriginalsEntries.textContent = `${snapshot.photosOriginals.entryCount.toLocaleString("zh-CN")} 条 ImageAll 副本`;
  elements.appStorageKind.textContent = snapshot.appStorage.kind === "externalStorage"
    ? "外置存储" : "Mac 内置存储";
  if (snapshot.appStorage.requiresRestart) {
    const name = snapshot.appStorage.pendingExternalRootName;
    elements.appStorageDetail.textContent = name
      ? `已选择“${name}” · 重启 ImageAll 后迁移`
      : "已选择新的外置位置 · 重启 ImageAll 后迁移";
  } else {
    elements.appStorageDetail.textContent = snapshot.appStorage.kind === "externalStorage"
      ? "应用资料和缓存由 Mac 在外置位置管理"
      : "应用资料和缓存保留在这台 Mac";
  }
  elements.chooseExternalStorageButton.textContent = snapshot.appStorage.requiresRestart
    ? "重新选择外置位置…" : "选择外置存储位置…";

  const requests = (snapshot.requests || []).slice(0, 6);
  elements.storageHistorySection.classList.toggle("hidden", !requests.length);
  reconcileStorageHistory(requests);
}

function scheduleStorageMaintenancePoll() {
  clearTimeout(state.storageMaintenance.pollTimer);
  state.storageMaintenance.pollTimer = null;
  if (!storageMaintenanceNeedsPoll()) return;
  state.storageMaintenance.pollTimer = setTimeout(() => {
    loadStorageMaintenance({ quiet: true, notifyTerminal: true });
  }, 1_000);
}

async function loadStorageMaintenance({
  quiet = false,
  notifyTerminal = false,
  returnFocus = null,
} = {}) {
  const manager = state.storageMaintenance;
  if (manager.loading) return;
  const generation = ++manager.requestGeneration;
  const hadSnapshot = Boolean(manager.snapshot);
  manager.loading = true;
  if (!quiet) elements.storageError.classList.add("hidden");
  renderStorageMaintenance();
  try {
    const snapshot = await api("/v1/storage-maintenance");
    if (generation !== manager.requestGeneration) return;
    manager.snapshot = snapshot;
    for (const request of snapshot.requests || []) {
      if (!["completed", "cancelled", "failed"].includes(request.phase)) continue;
      const firstSeen = !manager.seenTerminalRequestIDs.has(request.id);
      manager.seenTerminalRequestIDs.add(request.id);
      if (notifyTerminal && hadSnapshot && firstSeen) toast(request.message);
    }
  } catch (error) {
    if (generation !== manager.requestGeneration) return;
    elements.storageError.textContent = error.message || "无法读取 Mac 存储状态";
    elements.storageError.classList.remove("hidden");
  } finally {
    if (generation === manager.requestGeneration) {
      manager.loading = false;
      renderStorageMaintenance();
      scheduleStorageMaintenancePoll();
      if (returnFocus
        && elements.storageDialog.open
        && document.activeElement === document.body) {
        requestAnimationFrame(() => {
          if (elements.storageDialog.open
            && document.activeElement === document.body
            && !returnFocus.disabled) {
            returnFocus.focus({ preventScroll: true });
          }
        });
      }
    }
  }
}

function storageBaseLevelFromHistory(context = {}) {
  return ["sidebar", "inspector", "lightbox"].includes(context.storageBaseLevel)
    ? context.storageBaseLevel
    : "workspace";
}

function replaceStorageHistoryWithBase(baseLevel) {
  if (!state.workspaceNavigation.initialized
    || elements.appView.classList.contains("hidden")) return;
  const current = activeWorkspaceHistoryEntry();
  const route = visibleWorkspaceRoute();
  if (current?.route !== route || current.navigationLevel !== "storageMaintenance") return;
  const context = currentWorkspaceHistoryContext(route);
  if (context && typeof context === "object") delete context.storageBaseLevel;
  const navigationLevel = visibleWorkspaceNavigationBaseLevel(route, baseLevel);
  history.replaceState({
    ...(history.state || {}),
    [WORKSPACE_HISTORY_KEY]: workspaceHistoryEntry(route, context, navigationLevel),
  }, "", location.href);
}

async function openStorageMaintenance({
  focus = true,
  historyMode = "pushStorageMaintenance",
  baseLevel = null,
  refresh = true,
  returnFocus = null,
  preserveState = false,
} = {}) {
  if (!state.online || elements.storageDialog.open || state.storageOpening) return;
  state.storageOpening = true;
  try {
    if (!preserveState) {
      state.storageReturnFocus = returnFocus
        || (document.activeElement instanceof HTMLElement ? document.activeElement : null);
      state.storageReturnControlID = storageMaintenanceReturnControlID(
        state.storageReturnFocus
      );
      state.storageFocusID = "storageRefreshButton";
      state.storageScrollTop = 0;
    }
    const current = activeWorkspaceHistoryEntry();
    state.storageBaseLevel = baseLevel
      || workspaceNavigationBaseLevel(
        current?.navigationLevel || "workspace",
        current?.context || {}
      );
    elements.storageDialog.showModal();
    state.storageRestorable = true;
    if (historyMode !== "none") {
      const route = visibleWorkspaceRoute();
      recordWorkspaceHistory(route, currentWorkspaceHistoryContext(route), historyMode);
    }
    elements.storageError.classList.add("hidden");
    renderStorageMaintenance();
    if (focus) restoreOverlayFocus(elements.storageCloseButton);
    if (refresh || !state.storageMaintenance.snapshot) await loadStorageMaintenance();
    else scheduleStorageMaintenancePoll();
    if (focus && elements.storageDialog.open) {
      restoreOverlayFocus(elements.storageRefreshButton);
    }
    scheduleWorkspaceHistoryCheckpoint();
  } finally {
    state.storageOpening = false;
  }
}

function closeStorageMaintenance({
  restoreFocus = true,
  checkpoint = true,
  preserveState = false,
} = {}) {
  if (!elements.storageDialog.open) return;
  if (elements.confirmDialog.open && state.confirmationBaseLevel === "storageMaintenance") {
    closeConfirmation({ restoreFocus: false, checkpoint: false, preserveState: false });
  }
  const keepsTracking = storageMaintenanceHasActiveRequest();
  if (!keepsTracking) {
    clearTimeout(state.storageMaintenance.pollTimer);
    state.storageMaintenance.pollTimer = null;
    state.storageMaintenance.requestGeneration += 1;
  }
  state.storageMaintenance.loading = false;
  state.storageMaintenance.pendingReturnAction = null;
  captureStorageMaintenanceHistoryFocus();
  state.storageScrollTop = elements.storageContent.scrollTop;
  const baseLevel = state.storageBaseLevel;
  const returnFocus = resolveStorageMaintenanceReturnFocus();
  if (!preserveState) {
    state.storageReturnFocus = null;
    state.storageReturnControlID = null;
  }
  state.storageBaseLevel = preserveState ? baseLevel : "workspace";
  elements.storageDialog.close();
  if (restoreFocus) {
    const toolbarFallback = stableReturnFocusTarget(
      elements.compactToolbarMenuButton,
      elements.commandButton
    );
    const storageFallback = stableReturnFocusTarget(
      elements.storageButton,
      toolbarFallback
    );
    restoreOverlayFocus(stableReturnFocusTarget(
      returnFocus,
      storageFallback
    ));
  }
  if (checkpoint) replaceStorageHistoryWithBase(baseLevel);
  if (keepsTracking) scheduleStorageMaintenancePoll();
  if (!preserveState) {
    state.storageRestorable = false;
    state.storageFocusID = "storageRefreshButton";
    state.storageScrollTop = 0;
  }
}

function returnFromStorageMaintenance({ restoreFocus = true } = {}) {
  if (elements.confirmDialog.open && state.confirmationBaseLevel === "storageMaintenance") {
    return returnFromConfirmation({ restoreFocus });
  }
  if (!elements.storageDialog.open) return Promise.resolve();
  state.storageHistoryRestoreFocus = restoreFocus;
  if (state.workspaceNavigation.pendingReturnPromise) {
    return state.workspaceNavigation.pendingReturnPromise;
  }
  const current = activeWorkspaceHistoryEntry();
  if (state.workspaceNavigation.initialized
    && current?.route === visibleWorkspaceRoute()
    && current.navigationLevel === "storageMaintenance") {
    const pending = new Promise((resolve) => {
      state.workspaceNavigation.pendingReturnResolve = resolve;
    });
    state.workspaceNavigation.pendingReturnPromise = pending;
    history.back();
    return pending;
  }
  closeStorageMaintenance({ restoreFocus });
  state.storageHistoryRestoreFocus = true;
  return Promise.resolve();
}

async function reconcileStorageMaintenanceFromWorkspaceHistory(
  route,
  navigationLevel,
  context = {}
) {
  const shouldOpen = (
    navigationLevel === "storageMaintenance"
    || (navigationLevel === "confirmation"
      && context.confirmationBaseLevel === "storageMaintenance")
  ) && route === visibleWorkspaceRoute();
  if (shouldOpen && !state.online) return;
  if (shouldOpen && !state.storageRestorable) {
    applyStorageMaintenanceHistoryContext(context);
    await openStorageMaintenance({
      focus: false,
      historyMode: "none",
      baseLevel: storageBaseLevelFromHistory(context),
      refresh: false,
      preserveState: true,
    });
    if (navigationLevel === "storageMaintenance") {
      await restoreStorageMaintenanceLayoutFromHistory();
    }
    return true;
  }
  if (shouldOpen && !elements.storageDialog.open) {
    await openStorageMaintenance({
      focus: false,
      historyMode: "none",
      baseLevel: storageBaseLevelFromHistory(context),
      refresh: false,
      preserveState: true,
    });
    if (navigationLevel === "storageMaintenance") {
      await restoreStorageMaintenanceLayoutFromHistory();
    }
  } else if (!shouldOpen && elements.storageDialog.open) {
    const restoreFocus = state.storageHistoryRestoreFocus;
    closeStorageMaintenance({ restoreFocus, checkpoint: false, preserveState: true });
    state.storageHistoryRestoreFocus = true;
  }
  return false;
}

async function submitStorageMaintenanceAction(action) {
  const manager = state.storageMaintenance;
  if (!state.online || manager.submitting || storageMaintenanceHasActiveRequest()) return;
  if (["clearPreviewCache", "clearPhotosOriginals"].includes(action)) {
    const availability = storageActionAvailability(action);
    if (!availability.isAvailable) {
      toast(storageActionUnavailableMessage(availability.reason));
      return;
    }
  }
  manager.submitting = true;
  elements.storageError.classList.add("hidden");
  renderStorageMaintenance();
  try {
    const request = await api("/v1/storage-maintenance/requests", {
      method: "POST",
      body: JSON.stringify({ operationID: crypto.randomUUID(), action }),
    });
    const snapshot = manager.snapshot;
    if (snapshot) {
      manager.snapshot = {
        ...snapshot,
        requests: [request, ...(snapshot.requests || []).filter((item) => item.id !== request.id)],
      };
    }
    renderStorageMaintenance();
    scheduleStorageMaintenancePoll();
  } catch (error) {
    elements.storageError.textContent = error.message || "Mac 未能接收存储操作";
    elements.storageError.classList.remove("hidden");
  } finally {
    manager.submitting = false;
    renderStorageMaintenance();
  }
}

function requestStorageMaintenanceAction(action) {
  if (["clearPreviewCache", "clearPhotosOriginals"].includes(action)) {
    const availability = storageActionAvailability(action);
    if (!availability.isAvailable) {
      toast(storageActionUnavailableMessage(availability.reason));
      return;
    }
  }
  const confirmations = {
    clearPreviewCache: {
      eyebrow: "PREVIEW CACHE",
      title: "清理预览缓存？",
      message: "只会删除可重建的网格缩略图和单图预览；不会删除原照片、人工标签、Feature Print 或个性化模型。iCloud 预览之后需要再次手动获取。",
      actionLabel: "清理预览缓存",
    },
    clearPhotosOriginals: {
      eyebrow: "PHOTOS ORIGINALS",
      title: "清理全部长期原图副本？",
      message: "只删除 ImageAll 在 Application Support 中长期保存的 Photos 原图副本及其缓存索引。不会修改 Apple Photos、人工标签或已计算的相同检测结果；以后再次需要原图时，“相同”检测可能重新从 iCloud 下载。",
      actionLabel: "清理全部长期原图副本",
    },
  };
  const confirmation = confirmations[action];
  if (!confirmation) {
    submitStorageMaintenanceAction(action);
    return;
  }
  requestConfirmation({
    ...confirmation,
    tone: "danger",
    returnFocus: { storageAction: action },
    action: () => submitStorageMaintenanceAction(action),
  });
}

function unavailableBadge(text) {
  const badge = document.createElement("span");
  badge.className = "asset-unavailable";
  badge.textContent = text;
  return badge;
}

function thumbnailRequestPath(assetID, { width = 420, revision = null } = {}) {
  const query = new URLSearchParams({ w: String(width) });
  if (revision != null) query.set("r", String(revision));
  if (state.layout.aspectMode === "original") query.set("aspect", "original");
  return `/v1/assets/${encodeURIComponent(assetID)}/thumbnail?${query}`;
}

function syncThumbnailRenderedAspect(image) {
  if (!(image instanceof HTMLImageElement)
    || state.layout.aspectMode !== "original"
    || !image.dataset.protectedPath?.includes("aspect=original")
    || image.naturalWidth <= 0
    || image.naturalHeight <= 0) return;
  const aspect = `${image.naturalWidth} / ${image.naturalHeight}`;
  const assetCard = image.closest(".asset-card");
  const reviewCard = image.closest(".review-card");
  const slimmingMemberCard = image.closest(".slimming-member-card");
  const scrollContainer = assetCard
    ? elements.libraryScroll
    : reviewCard
      ? elements.reviewQueuePane
      : slimmingMemberCard
        ? slimmingMemberScrollContainer()
        : null;
  const scrollTop = scrollContainer?.scrollTop ?? null;
  if (assetCard) assetCard.style.setProperty("--asset-aspect", aspect);
  if (reviewCard) reviewCard.style.setProperty("--review-card-aspect", aspect);
  if (slimmingMemberCard) {
    slimmingMemberCard.style.setProperty("--slimming-member-aspect", aspect);
  }
  const changedCard = assetCard || reviewCard || slimmingMemberCard;
  if (scrollContainer && changedCard && scrollTop != null) {
    // Resolving a lazily loaded original-aspect request can change a row from
    // its metadata ratio to a square Host fallback. Force that reflow now and
    // restore the user's exact scroll position so browser scroll anchoring does
    // not move the workspace while thumbnails arrive.
    void changedCard.offsetHeight;
    scrollContainer.scrollTop = scrollTop;
  }
}

function bindThumbnailRenderedAspect(image) {
  if (!(image instanceof HTMLImageElement)
    || image.dataset.thumbnailAspectBound === "true") return;
  image.dataset.thumbnailAspectBound = "true";
  image.addEventListener("load", () => syncThumbnailRenderedAspect(image));
}

function syncProtectedThumbnailSource(image, assetID, options = {}) {
  if (!(image instanceof HTMLImageElement) || !assetID) return;
  bindThumbnailRenderedAspect(image);
  bindProtectedThumbnailRecovery(image);
  const path = thumbnailRequestPath(assetID, options);
  protectedThumbnailDescriptors.set(image, { assetID, path });
  if (image.dataset.protectedPath === path) {
    syncThumbnailRenderedAspect(image);
    return;
  }
  setProtectedImageSource(image, path);
}

function appendAssetImage(container, asset, variant = "thumbnail", before = null) {
  const insert = (node) => {
    const reference = before?.parentNode === container ? before : container.firstChild;
    container.insertBefore(node, reference);
  };
  if (asset.availability !== "available") {
    insert(unavailableBadge(availabilityText(asset.availability)));
    return;
  }
  const image = document.createElement("img");
  image.className = "loading";
  image.alt = "";
  image.loading = "lazy";
  image.decoding = "async";
  image.addEventListener("imageall-protected-load", () => {
    image.classList.remove("loading", "thumbnail-load-failed");
    container.querySelector(":scope > [data-thumbnail-error-placeholder]")?.remove();
  });
  image.addEventListener("imageall-protected-error", () => {
    if (container.querySelector(":scope > [data-thumbnail-error-placeholder]")) return;
    const placeholder = unavailableBadge("缩略图暂不可用");
    placeholder.dataset.thumbnailErrorPlaceholder = "true";
    insert(placeholder);
  });
  if (variant === "thumbnail") {
    syncProtectedThumbnailSource(image, asset.id || asset.assetID, {
      width: 420,
      revision: asset.contentRevision,
    });
  } else {
    const revision = asset.contentRevision == null ? "" : `&r=${asset.contentRevision}`;
    setProtectedImageSource(
      image,
      `/v1/assets/${asset.id || asset.assetID}/${variant}?w=420${revision}`
    );
  }
  if (image.complete && image.naturalWidth > 0) image.classList.remove("loading");
  insert(image);
}

function syncAssetCardImage(button, asset) {
  const assetID = asset.id || asset.assetID;
  const imageKey = [
    assetID,
    asset.availability,
    asset.contentRevision == null ? "" : asset.contentRevision,
    state.layout.aspectMode,
  ].join(":");
  const currentImage = button.querySelector(":scope > img");
  const currentPlaceholder = button.querySelector(":scope > .asset-unavailable");
  if (button.dataset.imageKey === imageKey && (currentImage || currentPlaceholder)) return;
  if (currentImage instanceof HTMLImageElement) clearProtectedImageSource(currentImage);
  currentImage?.remove();
  currentPlaceholder?.remove();
  button.dataset.imageKey = imageKey;
  appendAssetImage(button, asset, "thumbnail", button.firstChild);
}

function refreshVisibleThumbnailAspect() {
  for (const asset of state.assets) {
    const card = elements.assetGrid.querySelector(
      `[data-asset-id="${CSS.escape(asset.id)}"]`
    );
    if (card) syncAssetCardImage(card, asset);
  }
  state.review.items.forEach((item, index) => {
    const card = elements.reviewGrid.querySelector(`[data-review-index="${index}"]`);
    if (card) syncAssetCardImage(card, item);
  });
  for (const member of state.slimming.members) {
    const image = elements.slimmingMemberGrid.querySelector(
      `[data-slimming-member-id="${CSS.escape(member.id)}"] img`
    );
    syncProtectedThumbnailSource(image, member.id, {
      width: 360,
      revision: member.contentRevision,
    });
  }
  for (const entry of state.slimming.recycle.entries) {
    const image = elements.slimmingRecycleList.querySelector(
      `[data-slimming-recycle-thumbnail-entry-id="${CSS.escape(entry.id)}"] img`
    );
    syncProtectedThumbnailSource(image, entry.assetID, { width: 180 });
  }
}

function setThumbnailAspectMode(aspectMode) {
  if (!["square", "original"].includes(aspectMode)
    || state.layout.aspectMode === aspectMode) return;
  state.layout.aspectMode = aspectMode;
  renderLayoutPreferences();
  refreshVisibleThumbnailAspect();
  persistWorkspacePreferences();
}

function toggleThumbnailAspectMode() {
  setThumbnailAspectMode(state.layout.aspectMode === "original" ? "square" : "original");
}

function stopAssetHoverVideo(card = activeAssetHoverCard) {
  assetHoverVideoGeneration += 1;
  clearTimeout(assetHoverVideoTimer);
  assetHoverVideoTimer = null;
  if (!card) return;
  const video = card.querySelector(":scope > .asset-hover-video");
  if (video) {
    video.pause();
    video.removeAttribute("src");
    video.load();
    video.remove();
  }
  card.classList.remove("hover-video-loading", "hover-video-ready");
  if (activeAssetHoverCard === card) activeAssetHoverCard = null;
}

async function mountAssetHoverVideo(card, asset, generation) {
  if (generation !== assetHoverVideoGeneration || activeAssetHoverCard !== card) return;
  if (state.authMode === "account") {
    const workerReady = await updateMediaWorkerAuthorization(state.accountAuthorization);
    if (!workerReady
      || generation !== assetHoverVideoGeneration
      || activeAssetHoverCard !== card) {
      stopAssetHoverVideo(card);
      return;
    }
  }
  const video = document.createElement("video");
  video.className = "asset-hover-video";
  video.muted = true;
  video.defaultMuted = true;
  video.loop = true;
  video.playsInline = true;
  video.preload = "metadata";
  video.disableRemotePlayback = true;
  video.tabIndex = -1;
  video.setAttribute("aria-hidden", "true");
  video.addEventListener("loadeddata", () => {
    if (generation !== assetHoverVideoGeneration || activeAssetHoverCard !== card) return;
    card.classList.remove("hover-video-loading");
    card.classList.add("hover-video-ready");
    void video.play().catch(() => stopAssetHoverVideo(card));
  }, { once: true });
  video.addEventListener("error", () => {
    if (generation === assetHoverVideoGeneration && activeAssetHoverCard === card) {
      stopAssetHoverVideo(card);
    }
  }, { once: true });
  const revision = asset.contentRevision == null ? "" : `?r=${asset.contentRevision}`;
  video.src = `/v1/assets/${asset.id}/media${revision}`;
  card.insertBefore(video, card.querySelector(".asset-card-meta, .asset-video-badge"));
  video.load();
}

function beginAssetHoverVideo(card) {
  const asset = state.assets.find((item) => item.id === card?.dataset.assetId);
  const mediaKind = asset?.mediaKind || state.mediaKind;
  if (!asset
    || mediaKind !== "video"
    || asset.availability !== "available"
    || globalThis.matchMedia?.("(prefers-reduced-motion: reduce)").matches) return;
  const hoverKey = `${asset.id}:${asset.contentRevision ?? ""}`;
  if (activeAssetHoverCard === card
    && card.dataset.hoverVideoKey === hoverKey
    && card.querySelector(":scope > .asset-hover-video")) return;
  stopAssetHoverVideo();
  activeAssetHoverCard = card;
  card.dataset.hoverVideoKey = hoverKey;
  card.classList.add("hover-video-loading");
  const generation = ++assetHoverVideoGeneration;
  assetHoverVideoTimer = setTimeout(() => {
    assetHoverVideoTimer = null;
    void mountAssetHoverVideo(card, asset, generation);
  }, 180);
}

function syncAssetCardSelectionMark(card) {
  let mark = card.querySelector(":scope > .asset-selection-mark");
  if (!mark) {
    mark = document.createElement("span");
    mark.className = "asset-selection-mark";
    mark.setAttribute("aria-hidden", "true");
    card.append(mark);
  }
  mark.classList.toggle("hidden", !state.selectionMode);
  syncAssetCardOverlayText(
    mark,
    state.selectedAssetIDs.has(card.dataset.assetId) ? "✓" : ""
  );
}

function syncAssetCardOverlayText(element, text) {
  if (
    element.childNodes.length === 1
    && element.firstChild?.nodeType === Node.TEXT_NODE
  ) {
    if (element.firstChild.data !== text) element.firstChild.data = text;
  } else if (!element.childNodes.length) {
    element.append(document.createTextNode(text));
  } else if (element.textContent !== text) {
    element.textContent = text;
  }
}

function syncAssetTagCountBadge(meta, decision, count, symbol) {
  let badge = meta.querySelector(
    `:scope > [data-asset-tag-count="${decision}"]`
  );
  if (!count) {
    badge?.remove();
    return null;
  }
  if (!badge) {
    badge = document.createElement("span");
    badge.className = "asset-tag-count";
    badge.dataset.assetTagCount = decision;
  }
  const symbolPart = badge.querySelector(
    ':scope > [data-asset-tag-count-part="symbol"]'
  ) || document.createElement("span");
  symbolPart.dataset.assetTagCountPart = "symbol";
  symbolPart.setAttribute("aria-hidden", "true");
  syncAssetCardOverlayText(symbolPart, symbol);
  const valuePart = badge.querySelector(
    ':scope > [data-asset-tag-count-part="value"]'
  ) || document.createElement("span");
  valuePart.dataset.assetTagCountPart = "value";
  syncAssetCardOverlayText(valuePart, String(count));
  badge.setAttribute(
    "aria-label",
    `${decision === "accepted" ? "已确认" : "已拒绝"} ${count} 个标签`
  );
  reconcileStableChildren(badge, [symbolPart, valuePart]);
  return badge;
}

function syncAssetCardMeta(button, asset) {
  let meta = button.querySelector(".asset-card-meta");
  if (!asset.acceptedTagCount && !asset.rejectedTagCount) {
    meta?.remove();
    return;
  }
  if (!meta) {
    meta = document.createElement("span");
    meta.className = "asset-card-meta";
    button.append(meta);
  }
  const wanted = [
    syncAssetTagCountBadge(meta, "accepted", asset.acceptedTagCount, "✓"),
    syncAssetTagCountBadge(meta, "rejected", asset.rejectedTagCount, "×"),
  ].filter(Boolean);
  reconcileStableChildren(meta, wanted);
}

function syncAssetCardMediaBadge(button, asset) {
  const mediaKind = asset.mediaKind || state.mediaKind;
  let badge = button.querySelector(":scope > .asset-video-badge");
  if (mediaKind !== "video") {
    badge?.remove();
    return;
  }
  if (!badge) {
    badge = document.createElement("span");
    badge.className = "asset-video-badge";
    badge.setAttribute("aria-hidden", "true");
    button.append(badge);
  }
  const icon = badge.querySelector(
    ':scope > [data-asset-video-badge-part="icon"]'
  ) || document.createElement("span");
  icon.dataset.assetVideoBadgePart = "icon";
  syncAssetCardOverlayText(icon, "▶");
  let duration = badge.querySelector(
    ':scope > [data-asset-video-badge-part="duration"]'
  );
  if (asset.durationMs == null) {
    duration?.remove();
    duration = null;
  } else {
    if (!duration) {
      duration = document.createElement("span");
      duration.dataset.assetVideoBadgePart = "duration";
    }
    syncAssetCardOverlayText(duration, ` ${formatDuration(asset.durationMs)}`);
  }
  reconcileStableChildren(badge, [icon, duration].filter(Boolean));
}

function favoriteSyncText(favorite) {
  return {
    localOnly: "仅保存在 ImageAll",
    synced: "已与 Apple Photos 同步",
    pending: "等待与 Apple Photos 同步",
    failed: "Apple Photos 同步失败",
  }[favorite?.syncStatus] || "";
}

function assetCardMainButton(card, { create = false } = {}) {
  let button = card?.querySelector(":scope > .asset-card-main") || null;
  if (!button && create && card) {
    button = document.createElement("button");
    button.type = "button";
    button.className = "asset-card-main";
    card.append(button);
  }
  return button;
}

function libraryGridRovingAssetID() {
  const visibleIDs = new Set(state.assets.map((asset) => asset.id));
  const focusedCard = document.activeElement?.closest?.("#assetGrid > .asset-card");
  if (visibleIDs.has(focusedCard?.dataset.assetId)) return focusedCard.dataset.assetId;
  if (visibleIDs.has(state.selectedAssetID)) return state.selectedAssetID;
  if (visibleIDs.has(state.libraryGridFocusAssetID)) return state.libraryGridFocusAssetID;
  return state.assets[0]?.id || null;
}

function syncAssetCardKeyboardAccess(card, rovingAssetID = libraryGridRovingAssetID()) {
  const isTabStop = card?.dataset.assetId === rovingAssetID;
  const mainButton = assetCardMainButton(card);
  if (mainButton) mainButton.tabIndex = isTabStop ? 0 : -1;
  const favoriteButton = card?.querySelector(":scope > .asset-card-favorite");
  if (favoriteButton) favoriteButton.tabIndex = isTabStop ? 0 : -1;
}

function syncLibraryGridTabStops(assetID = null) {
  const visibleIDs = new Set(state.assets.map((asset) => asset.id));
  if (assetID && visibleIDs.has(assetID)) state.libraryGridFocusAssetID = assetID;
  const rovingAssetID = libraryGridRovingAssetID();
  state.libraryGridFocusAssetID = rovingAssetID;
  for (const card of elements.assetGrid.querySelectorAll(":scope > .asset-card")) {
    syncAssetCardKeyboardAccess(card, rovingAssetID);
  }
}

function syncMediaFavoriteButton(button, { assetID, fileName, favorite }) {
  const isFavorite = favorite?.isFavorite === true;
  const syncStatus = favorite?.syncStatus || "";
  const syncText = favoriteSyncText(favorite);
  const actionText = isFavorite ? "取消红心" : "加入红心";
  const title = syncText ? `${actionText}；${syncText}` : actionText;
  button.dataset.mediaFavoriteAssetId = assetID;
  button.dataset.favorite = String(isFavorite);
  button.dataset.syncStatus = syncStatus;
  button.disabled = !state.online || state.favoriteMutating || state.favoriteRetrying;
  button.title = title;
  button.setAttribute("aria-label", `${fileName || "当前项目"}：${title}`);
  button.setAttribute("aria-pressed", String(isFavorite));
  const icon = button.querySelector(":scope > .media-favorite-icon");
  syncAssetCardOverlayText(icon, isFavorite ? "♥" : "♡");
  const badge = button.querySelector(":scope > .media-favorite-sync");
  const showBadge = syncStatus === "pending" || syncStatus === "failed";
  badge.classList.toggle("hidden", !showBadge);
  badge.dataset.syncStatus = syncStatus;
  syncAssetCardOverlayText(badge, syncStatus === "failed" ? "!" : "");
}

function syncAssetCardFavoriteButton(card, asset) {
  let button = card.querySelector(":scope > .asset-card-favorite");
  if (!supportsFavorites()) {
    button?.remove();
    return;
  }
  if (!button) {
    button = document.createElement("button");
    button.type = "button";
    button.className = "asset-card-favorite write-action";
    button.dataset.assetCardFavorite = "true";
    const icon = document.createElement("span");
    icon.className = "asset-card-favorite-icon media-favorite-icon";
    icon.setAttribute("aria-hidden", "true");
    const badge = document.createElement("span");
    badge.className = "asset-card-favorite-sync media-favorite-sync hidden";
    badge.setAttribute("aria-hidden", "true");
    button.append(icon, badge);
    card.append(button);
  }
  syncMediaFavoriteButton(button, {
    assetID: asset.id,
    fileName: asset.fileName,
    favorite: asset.favorite || null,
  });
}

function syncAssetCard(card, asset) {
  const mediaKind = asset.mediaKind || state.mediaKind;
  const fileName = asset.fileName || (mediaKind === "video" ? "未命名视频" : "未命名照片");
  const nextHoverKey = `${asset.id}:${asset.contentRevision ?? ""}`;
  if (activeAssetHoverCard === card && card.dataset.hoverVideoKey !== nextHoverKey) {
    stopAssetHoverVideo(card);
  }
  card.className = "asset-card";
  if (activeAssetHoverCard === card) {
    const hoverVideo = card.querySelector(":scope > .asset-hover-video");
    card.classList.add(hoverVideo?.readyState >= HTMLMediaElement.HAVE_CURRENT_DATA
      ? "hover-video-ready"
      : "hover-video-loading");
  }
  card.dataset.assetId = asset.id;
  card.dataset.mediaKind = mediaKind;
  if (Number(asset.width) > 0 && Number(asset.height) > 0) {
    card.style.setProperty("--asset-aspect", `${Number(asset.width)} / ${Number(asset.height)}`);
  } else {
    card.style.removeProperty("--asset-aspect");
  }
  card.classList.toggle("selected", state.selectedAssetID === asset.id && !state.selectionMode);
  card.classList.toggle("batch-selected", state.selectedAssetIDs.has(asset.id));
  const mainButton = assetCardMainButton(card, { create: true });
  mainButton.setAttribute(
    "aria-label",
    `${fileName}，`
      + `${mediaKind === "video" ? "视频" : "照片"}，${asset.sourceName}，`
      + (mediaKind === "video" && asset.durationMs != null
        ? `时长 ${formatDuration(asset.durationMs)}，`
        : "")
      + `${asset.favorite?.isFavorite ? "已加入红心，" : ""}`
      + `标签：已确认 ${asset.acceptedTagCount}，已拒绝 ${asset.rejectedTagCount}`
  );
  mainButton.setAttribute(
    "aria-pressed",
    String(state.selectionMode
      ? state.selectedAssetIDs.has(asset.id)
      : state.selectedAssetID === asset.id)
  );
  mainButton.setAttribute(
    "aria-keyshortcuts",
    "ArrowLeft ArrowRight ArrowUp ArrowDown Home End PageUp PageDown Space"
  );
  if (mediaKind === "video") {
    if (persistentHelpTarget === mainButton) hidePersistentHelp({ restoreTitle: false });
    delete mainButton.dataset.helpTitle;
    delete mainButton.dataset.helpDetail;
    delete mainButton.dataset.helpKind;
    delete mainButton.dataset.helpNativeTitle;
    mainButton.title = [
      fileName,
      `来源：${asset.sourceName}`,
      "媒体：视频",
      asset.durationMs != null ? `时长：${formatDuration(asset.durationMs)}` : "",
      "悬停静音播放；双击打开单图",
      asset.width && asset.height ? `尺寸：${asset.width} × ${asset.height}` : "",
      `标签：已确认 ${asset.acceptedTagCount} · 已拒绝 ${asset.rejectedTagCount}`,
      asset.favorite?.isFavorite ? `红心：${favoriteSyncText(asset.favorite)}` : "",
      "方向键移动 · Shift 扩展选择 · Space 打开单图",
    ].filter(Boolean).join("\n");
  } else {
    mainButton.dataset.helpTitle = fileName;
    mainButton.dataset.helpDetail = assetCardHelpDetail(asset);
    mainButton.dataset.helpKind = "asset";
    if (persistentHelpTarget === mainButton) {
      mainButton.dataset.helpNativeTitle = fileName;
      mainButton.removeAttribute("title");
    } else {
      delete mainButton.dataset.helpNativeTitle;
      mainButton.title = fileName;
    }
    if (persistentHelpTarget === mainButton
      && !elements.persistentHelp.classList.contains("hidden")) {
      showPersistentHelp(mainButton);
    }
  }
  syncAssetCardImage(card, asset);
  syncAssetCardSelectionMark(card);
  syncAssetCardMeta(card, asset);
  syncAssetCardMediaBadge(card, asset);
  syncAssetCardFavoriteButton(card, asset);
  syncAssetCardKeyboardAccess(card);
}

function syncAssetCardPosition(button, index) {
  const currentButton = elements.assetGrid.children[index] || null;
  if (currentButton !== button) {
    elements.assetGrid.insertBefore(button, currentButton);
  }
}

function renderAssetCollectionSummary() {
  renderLibraryEmptyState();
  elements.emptyState.classList.toggle("hidden", state.assets.length > 0 || state.loadingAssets);
  elements.loadMoreButton.classList.toggle("hidden", !state.nextCursor);
  elements.allAssetCount.textContent = state.assets.length
    ? `${state.assets.length}${state.nextCursor ? "+" : ""}`
    : "";
  elements.allAssetCount.title = state.assets.length
    ? `当前已载入 ${state.assets.length} 项${state.nextCursor ? "，还有更多" : ""}`
    : "";
  elements.favoritesNavigationCount.textContent = state.libraryScope === "favorites"
    ? `${state.assets.length}${state.nextCursor ? "+" : ""}`
    : "";
  elements.assetSummary.textContent = state.assets.length
    ? `已载入 ${state.assets.length} 项${state.nextCursor ? " · 还有更多" : ""}`
    : "";
}

function renderAssets() {
  renderAssetCollectionSummary();
  state.libraryGridFocusAssetID = libraryGridRovingAssetID();

  const existing = new Map(
    [...elements.assetGrid.querySelectorAll(":scope > .asset-card")]
      .map((button) => [button.dataset.assetId, button])
  );
  const visibleIDs = new Set();
  for (const [index, asset] of state.assets.entries()) {
    const button = existing.get(asset.id) || document.createElement("div");
    visibleIDs.add(asset.id);
    syncAssetCard(button, asset);
    syncAssetCardPosition(button, index);
  }
  for (const button of existing.values()) {
    if (!visibleIDs.has(button.dataset.assetId)) {
      if (activeAssetHoverCard === button) stopAssetHoverVideo(button);
      button.querySelectorAll("img[data-protected-path]").forEach(clearProtectedImageSource);
      button.remove();
    }
  }
  updateInspectorNavigation();
  renderFavoriteControls();
}

function appendAssetCards(assets) {
  if (!assets.length) return;
  const fragment = document.createDocumentFragment();
  for (const asset of assets) {
    const card = document.createElement("div");
    syncAssetCard(card, asset);
    fragment.append(card);
  }
  elements.assetGrid.append(fragment);
  updateInspectorNavigation();
  renderFavoriteControls();
}

function renderAssetCardsForIDs(assetIDs) {
  const requestedIDs = new Set(assetIDs);
  if (!requestedIDs.size) return;
  const assetsByID = new Map(
    state.assets
      .filter((asset) => requestedIDs.has(asset.id))
      .map((asset) => [asset.id, asset])
  );
  for (const card of elements.assetGrid.querySelectorAll(":scope > .asset-card")) {
    const asset = assetsByID.get(card.dataset.assetId);
    if (asset) syncAssetCard(card, asset);
  }
}

function metadataRow(label, value) {
  return { key: label, label, value: value || "—" };
}

function reconcileMetadataRows(container, rows) {
  const existing = new Map(
    [...container.querySelectorAll(":scope > dt[data-metadata-key]")]
      .map((term) => {
        const detail = term.nextElementSibling;
        return detail?.matches("dd[data-metadata-key]")
          && detail.dataset.metadataKey === term.dataset.metadataKey
          ? [term.dataset.metadataKey, { term, detail }]
          : null;
      })
      .filter(Boolean)
  );
  const wanted = [];
  for (const row of rows) {
    let pair = existing.get(row.key) || null;
    existing.delete(row.key);
    if (!pair) {
      const term = document.createElement("dt");
      const detail = document.createElement("dd");
      term.dataset.metadataKey = row.key;
      detail.dataset.metadataKey = row.key;
      pair = { term, detail };
    }
    if (pair.term.textContent !== row.label) pair.term.textContent = row.label;
    if (pair.detail.textContent !== row.value) pair.detail.textContent = row.value;
    wanted.push(pair.term, pair.detail);
  }
  reconcileStableChildren(container, wanted);
}

function assetThumbnailPlaceholder(assetID) {
  const card = [...elements.assetGrid.querySelectorAll(":scope > .asset-card")]
    .find((candidate) => candidate.dataset.assetId === assetID);
  const thumbnail = card?.querySelector("img");
  if (!thumbnail?.complete || thumbnail.naturalWidth <= 0 || thumbnail.naturalHeight <= 0) {
    return null;
  }
  try {
    const canvas = document.createElement("canvas");
    canvas.width = thumbnail.naturalWidth;
    canvas.height = thumbnail.naturalHeight;
    canvas.getContext("2d")?.drawImage(thumbnail, 0, 0);
    return canvas.toDataURL("image/jpeg", 0.84);
  } catch {
    return null;
  }
}

function showPreviewPlaceholder(assetID) {
  const source = assetThumbnailPlaceholder(assetID);
  if (!source) {
    elements.previewPlaceholderImage.classList.add("hidden");
    elements.previewPlaceholderImage.removeAttribute("src");
    delete elements.previewPlaceholderImage.dataset.assetId;
    return false;
  }
  elements.previewPlaceholderImage.dataset.assetId = assetID;
  elements.previewPlaceholderImage.src = source;
  elements.previewPlaceholderImage.classList.remove("hidden");
  return true;
}

function hidePreviewPlaceholder() {
  elements.previewPlaceholderImage.classList.add("hidden");
  elements.previewPlaceholderImage.removeAttribute("src");
  delete elements.previewPlaceholderImage.dataset.assetId;
}

function stopCloudPreviewPolling() {
  clearTimeout(state.cloudPreview.pollTimer);
  state.cloudPreview.pollTimer = null;
}

function resetCloudPreviewRecovery({ cancelActive = true } = {}) {
  const activeAssetID = state.cloudPreview.assetID;
  const activeOperationID = state.cloudPreview.operationID;
  const shouldCancel = cancelActive
    && state.cloudPreview.status === "downloading"
    && activeAssetID
    && activeOperationID
    && supportsCloudPreviewLifecycle();
  stopCloudPreviewPolling();
  state.cloudPreview.requestGeneration += 1;
  state.cloudPreview.assetID = null;
  state.cloudPreview.context = null;
  state.cloudPreview.status = "hidden";
  state.cloudPreview.operationID = null;
  state.cloudPreview.progress = 0;
  renderCloudPreviewRecovery();
  if (shouldCancel) {
    void api(`/v1/assets/${activeAssetID}/cloud-preview-requests/cancel`, {
      method: "POST",
      body: JSON.stringify({ operationID: activeOperationID }),
    }).catch(() => {});
  }
}

function renderCloudPreviewRecovery() {
  const recovery = state.cloudPreview;
  const inspectorVisible = recovery.status !== "hidden"
    && recovery.assetID === state.selectedDetail?.assetID
    && state.mediaKind === "image"
    && recovery.context === "library";
  syncCloudPreviewControl({
    container: elements.cloudPreviewRecovery,
    icon: elements.cloudPreviewIcon,
    title: elements.cloudPreviewTitle,
    message: elements.cloudPreviewMessage,
    progress: elements.cloudPreviewProgress,
    button: elements.cloudPreviewButton,
  }, recovery, inspectorVisible);

  if (state.lightboxContext !== "review") {
    const lightboxVisible = recovery.status !== "hidden"
      && recovery.assetID === state.lightboxAssetID
      && state.lightboxContext != null
      && lightboxMediaKind() === "image"
      && !elements.lightbox.classList.contains("hidden");
    syncCloudPreviewControl(lightboxCloudPreviewControl(), recovery, lightboxVisible);
  }
}

function cloudPreviewCurrentAssetID() {
  if (state.lightboxContext && state.lightboxContext !== "review"
    && lightboxMediaKind() === "image"
    && !elements.lightbox.classList.contains("hidden")) {
    return state.lightboxAssetID;
  }
  if (state.cloudPreview.context === "library" && state.mediaKind === "image") {
    return state.selectedDetail?.assetID || null;
  }
  return null;
}

function cloudPreviewIsCurrent(assetID, generation) {
  return generation === state.cloudPreview.requestGeneration
    && state.cloudPreview.assetID === assetID
    && cloudPreviewCurrentAssetID() === assetID;
}

function showCloudPreviewRecovery(assetID, status = "available", context = null) {
  const recoveryContext = context
    || (state.lightboxContext && state.lightboxContext !== "review"
      ? state.lightboxContext
      : "library");
  if (state.cloudPreview.assetID === assetID
    && state.cloudPreview.status !== "hidden") {
    if (recoveryContext !== "library") state.cloudPreview.context = recoveryContext;
    renderCloudPreviewRecovery();
    return;
  }
  if (state.cloudPreview.status !== "hidden") resetCloudPreviewRecovery();
  stopCloudPreviewPolling();
  const generation = ++state.cloudPreview.requestGeneration;
  state.cloudPreview.assetID = assetID;
  state.cloudPreview.context = recoveryContext;
  state.cloudPreview.status = status;
  state.cloudPreview.operationID = null;
  state.cloudPreview.progress = 0;
  elements.previewLoading.classList.add("hidden");
  elements.previewImage.classList.add("hidden");
  elements.openLightboxButton.classList.add("hidden");
  if (state.lightboxContext && state.lightboxContext !== "review"
    && state.lightboxAssetID === assetID) {
    clearProtectedImageSource(elements.lightboxImage);
    elements.lightboxImage.classList.add("hidden");
  }
  renderCloudPreviewRecovery();
  if (status === "available" && supportsCloudPreviewLifecycle()) {
    void resumeCloudPreviewLifecycle(assetID, generation);
  }
}

function displayDownloadedCloudPreview(assetID, generation) {
  const detail = state.selectedDetail;
  if (!cloudPreviewIsCurrent(assetID, generation)) return;
  stopCloudPreviewPolling();
  state.cloudPreview.status = "hidden";
  state.cloudPreview.operationID = null;
  state.cloudPreview.progress = 1;
  renderCloudPreviewRecovery();
  const lightboxItem = lightboxItems().find((item) => item.id === assetID);
  const contentRevision = detail?.assetID === assetID
    ? detail.contentRevision
    : lightboxItem?.contentRevision;
  const query = new URLSearchParams({ cloud: "1" });
  if (contentRevision != null) query.set("r", String(contentRevision));
  const previewPath = `/v1/assets/${assetID}/preview?${query}`;
  if (detail?.assetID === assetID) {
    elements.previewLoading.classList.remove("hidden");
    setProtectedImageSource(elements.previewImage, previewPath, {
      priority: "high",
      forceFetch: true,
    });
  }
  if (state.lightboxContext && state.lightboxContext !== "review"
    && state.lightboxAssetID === assetID
    && !elements.lightbox.classList.contains("hidden")) {
    elements.lightboxImage.classList.remove("hidden");
    setProtectedImageSource(elements.lightboxImage, previewPath, {
      priority: "high",
      forceFetch: true,
    });
  }
  toast("iCloud 预览已获取");
}

function scheduleCloudPreviewPoll(assetID, generation) {
  stopCloudPreviewPolling();
  state.cloudPreview.pollTimer = setTimeout(() => {
    void pollCloudPreviewLifecycle(assetID, generation);
  }, 320);
}

function applyCloudPreviewSnapshot(snapshot, assetID, generation) {
  if (!cloudPreviewIsCurrent(assetID, generation)
    || snapshot?.assetID !== assetID) return;
  state.cloudPreview.operationID = snapshot.operationID || null;
  state.cloudPreview.progress = Number(snapshot.progress) || 0;
  if (snapshot.phase === "downloading") {
    state.cloudPreview.status = "downloading";
    renderCloudPreviewRecovery();
    scheduleCloudPreviewPoll(assetID, generation);
    return;
  }
  if (snapshot.phase === "completed") {
    displayDownloadedCloudPreview(assetID, generation);
    return;
  }
  stopCloudPreviewPolling();
  state.cloudPreview.operationID = null;
  state.cloudPreview.status = snapshot.phase === "cancelled" ? "available" : "failed";
  renderCloudPreviewRecovery();
  if (snapshot.phase === "cancelled") toast("已停止获取 iCloud 预览");
  else toast(snapshot.message || "无法获取 iCloud 预览");
}

async function resumeCloudPreviewLifecycle(assetID, generation) {
  try {
    const snapshot = await api(`/v1/assets/${assetID}/cloud-preview-requests`);
    if (snapshot.phase === "downloading") {
      applyCloudPreviewSnapshot(snapshot, assetID, generation);
    }
  } catch (error) {
    if (error?.status !== 404) {
      // A status-read failure must not replace the explicit user-controlled
      // start action; the ordinary recovery button remains available.
      console.debug("cloud preview resume unavailable", error);
    }
  }
}

async function pollCloudPreviewLifecycle(assetID, generation) {
  if (!cloudPreviewIsCurrent(assetID, generation)
    || state.cloudPreview.status !== "downloading") return;
  try {
    const snapshot = await api(`/v1/assets/${assetID}/cloud-preview-requests`);
    applyCloudPreviewSnapshot(snapshot, assetID, generation);
  } catch (error) {
    if (!cloudPreviewIsCurrent(assetID, generation)) return;
    stopCloudPreviewPolling();
    state.cloudPreview.operationID = null;
    state.cloudPreview.status = "failed";
    renderCloudPreviewRecovery();
    toast(error.message || "无法读取 iCloud 预览进度");
  }
}

async function cancelSelectedCloudPreview() {
  const recovery = state.cloudPreview;
  const assetID = cloudPreviewCurrentAssetID();
  if (!assetID || recovery.assetID !== assetID
    || recovery.status !== "downloading" || !recovery.operationID) return;
  const operationID = recovery.operationID;
  const generation = recovery.requestGeneration;
  stopCloudPreviewPolling();
  recovery.status = "cancelling";
  renderCloudPreviewRecovery();
  try {
    const snapshot = await api(`/v1/assets/${assetID}/cloud-preview-requests/cancel`, {
      method: "POST",
      body: JSON.stringify({ operationID }),
    });
    applyCloudPreviewSnapshot(snapshot, assetID, generation);
  } catch (error) {
    if (!cloudPreviewIsCurrent(assetID, generation)) return;
    recovery.status = "downloading";
    renderCloudPreviewRecovery();
    scheduleCloudPreviewPoll(assetID, generation);
    toast(error.message || "无法取消 iCloud 预览");
  }
}

async function downloadSelectedCloudPreview() {
  const assetID = cloudPreviewCurrentAssetID();
  if (!assetID || !state.online) return;
  if (state.cloudPreview.status === "downloading" && supportsCloudPreviewLifecycle()) {
    await cancelSelectedCloudPreview();
    return;
  }
  const generation = ++state.cloudPreview.requestGeneration;
  state.cloudPreview.assetID = assetID;
  if (!state.cloudPreview.context) {
    state.cloudPreview.context = state.lightboxContext || "library";
  }
  state.cloudPreview.status = "downloading";
  state.cloudPreview.progress = 0;
  state.cloudPreview.operationID = supportsCloudPreviewLifecycle()
    ? crypto.randomUUID()
    : null;
  renderCloudPreviewRecovery();

  if (supportsCloudPreviewLifecycle()) {
    const operationID = state.cloudPreview.operationID;
    try {
      const snapshot = await api(`/v1/assets/${assetID}/cloud-preview-requests`, {
        method: "POST",
        body: JSON.stringify({ operationID }),
      });
      applyCloudPreviewSnapshot(snapshot, assetID, generation);
    } catch (error) {
      if (!cloudPreviewIsCurrent(assetID, generation)) return;
      state.cloudPreview.operationID = null;
      state.cloudPreview.status = "failed";
      renderCloudPreviewRecovery();
      toast(error.message || "无法获取 iCloud 预览");
    }
    return;
  }

  try {
    const response = await rawFetch(`/v1/assets/${assetID}/cloud-preview`, {
      method: "POST",
    });
    if (!response.ok) {
      const payload = await parseResponse(response).catch(() => null);
      throw new APIError(response.status, typeof payload === "object" ? payload : {
        message: `获取预览失败（${response.status}）`,
      });
    }
    // Consume and validate the response before reusing the ordinary local-only
    // preview route. The Host has atomically cached the bounded preview by now.
    const downloaded = await response.blob();
    if (!downloaded.type.startsWith("image/")) {
      throw new Error("Host 未返回可显示的预览");
    }
    displayDownloadedCloudPreview(assetID, generation);
  } catch (error) {
    if (!cloudPreviewIsCurrent(assetID, generation)) return;
    state.cloudPreview.status = "failed";
    renderCloudPreviewRecovery();
    toast(error.message || "无法获取 iCloud 预览");
  }
}

function reviewCloudPreviewCurrentAssetID() {
  if (state.lightboxContext === "review" && state.lightboxAssetID) {
    return state.lightboxAssetID;
  }
  return state.review.items[state.review.selectedIndex]?.assetID || null;
}

function lightboxCloudPreviewControl() {
  return {
    container: elements.lightboxCloudPreviewRecovery,
    icon: elements.lightboxCloudPreviewIcon,
    title: elements.lightboxCloudPreviewTitle,
    message: elements.lightboxCloudPreviewMessage,
    progress: elements.lightboxCloudPreviewProgress,
    button: elements.lightboxCloudPreviewButton,
  };
}

function syncCloudPreviewControl(controls, recovery, visible) {
  controls.container.classList.toggle("hidden", !visible);
  if (!visible) return;
  const downloading = recovery.status === "downloading";
  const cancelling = recovery.status === "cancelling";
  const failed = recovery.status === "failed";
  const lifecycle = supportsCloudPreviewLifecycle();
  const percent = Math.max(0, Math.min(100, Math.round(recovery.progress * 100)));
  controls.icon.classList.toggle("spinner", downloading || cancelling);
  controls.icon.textContent = downloading || cancelling ? "" : (failed ? "⚠︎" : "☁︎");
  controls.title.textContent = cancelling
    ? "正在取消 iCloud 预览"
    : (downloading
      ? "正在从 iCloud 获取预览"
      : (failed ? "无法获取 iCloud 预览" : "此照片仅存储在 iCloud"));
  controls.message.textContent = cancelling
    ? "正在通知这台 Mac 停止当前照片的下载。"
    : (downloading
      ? (lifecycle
        ? `只获取当前照片的标准预览 · ${percent}%`
        : "只获取当前照片的标准预览；完成后会自动显示。")
      : (failed
        ? "请确认网络与“照片”访问权限后重试。"
        : "仅在你明确操作后，才会从 iCloud 获取这张照片的标准预览。"));
  controls.progress.classList.toggle("hidden", !downloading || !lifecycle);
  controls.progress.value = recovery.progress;
  controls.progress.setAttribute("aria-valuetext", `${percent}%`);
  controls.button.classList.toggle("hidden", downloading && !lifecycle);
  controls.button.textContent = cancelling
    ? "正在取消…"
    : (downloading ? "取消" : (failed ? "重试" : "从 iCloud 获取预览"));
  controls.button.disabled = cancelling || !state.online;
}

function renderReviewCloudPreviewRecovery() {
  const recovery = state.review.cloudPreview;
  const selectedAssetID = state.review.items[state.review.selectedIndex]?.assetID || null;
  const reviewVisible = recovery.status !== "hidden"
    && recovery.assetID === selectedAssetID
    && state.mediaKind === "image"
    && state.review.mode === "queue"
    && !elements.reviewWorkspace.classList.contains("hidden");
  const lightboxVisible = recovery.status !== "hidden"
    && recovery.assetID === state.lightboxAssetID
    && state.lightboxContext === "review"
    && !elements.lightbox.classList.contains("hidden");
  syncCloudPreviewControl({
    container: elements.reviewCloudPreviewRecovery,
    icon: elements.reviewCloudPreviewIcon,
    title: elements.reviewCloudPreviewTitle,
    message: elements.reviewCloudPreviewMessage,
    progress: elements.reviewCloudPreviewProgress,
    button: elements.reviewCloudPreviewButton,
  }, recovery, reviewVisible);
  if (state.lightboxContext === "review" || state.lightboxContext == null) {
    syncCloudPreviewControl(lightboxCloudPreviewControl(), recovery, lightboxVisible);
  }
}

function stopReviewCloudPreviewPolling() {
  clearTimeout(state.review.cloudPreview.pollTimer);
  state.review.cloudPreview.pollTimer = null;
}

function resetReviewCloudPreviewRecovery({ cancelActive = true } = {}) {
  const recovery = state.review.cloudPreview;
  const activeAssetID = recovery.assetID;
  const activeOperationID = recovery.operationID;
  const shouldCancel = cancelActive
    && recovery.status === "downloading"
    && activeAssetID
    && activeOperationID
    && supportsCloudPreviewLifecycle();
  stopReviewCloudPreviewPolling();
  recovery.requestGeneration += 1;
  recovery.assetID = null;
  recovery.status = "hidden";
  recovery.operationID = null;
  recovery.progress = 0;
  renderReviewCloudPreviewRecovery();
  if (shouldCancel) {
    void api(`/v1/assets/${activeAssetID}/cloud-preview-requests/cancel`, {
      method: "POST",
      body: JSON.stringify({ operationID: activeOperationID }),
    }).catch(() => {});
  }
}

function showReviewCloudPreviewRecovery(assetID, status = "available") {
  const recovery = state.review.cloudPreview;
  if (recovery.assetID === assetID && recovery.status !== "hidden") {
    renderReviewCloudPreviewRecovery();
    return;
  }
  stopReviewCloudPreviewPolling();
  const generation = ++recovery.requestGeneration;
  recovery.assetID = assetID;
  recovery.status = status;
  recovery.operationID = null;
  recovery.progress = 0;
  elements.reviewPreviewImage.classList.add("hidden");
  renderReviewCloudPreviewRecovery();
  if (status === "available" && supportsCloudPreviewLifecycle()) {
    void resumeReviewCloudPreviewLifecycle(assetID, generation);
  }
}

function reviewCloudPreviewIsCurrent(assetID, generation) {
  return generation === state.review.cloudPreview.requestGeneration
    && state.review.cloudPreview.assetID === assetID
    && reviewCloudPreviewCurrentAssetID() === assetID;
}

function displayDownloadedReviewCloudPreview(assetID, generation) {
  if (!reviewCloudPreviewIsCurrent(assetID, generation)) return;
  const recovery = state.review.cloudPreview;
  stopReviewCloudPreviewPolling();
  recovery.status = "hidden";
  recovery.operationID = null;
  recovery.progress = 1;
  renderReviewCloudPreviewRecovery();
  const revision = state.review.detail?.assetID === assetID
    ? state.review.detail.contentRevision
    : null;
  const query = new URLSearchParams({ cloud: "1" });
  if (revision != null) query.set("r", String(revision));
  const previewPath = `/v1/assets/${assetID}/preview?${query}`;
  elements.reviewPreviewImage.classList.remove("hidden");
  setProtectedImageSource(elements.reviewPreviewImage, previewPath, {
    priority: "high",
    forceFetch: true,
  });
  if (state.lightboxContext === "review" && state.lightboxAssetID === assetID) {
    elements.lightboxImage.classList.remove("hidden");
    setProtectedImageSource(elements.lightboxImage, previewPath, {
      priority: "high",
      forceFetch: true,
    });
  }
  toast("iCloud 预览已获取");
}

function scheduleReviewCloudPreviewPoll(assetID, generation) {
  stopReviewCloudPreviewPolling();
  state.review.cloudPreview.pollTimer = setTimeout(() => {
    void pollReviewCloudPreviewLifecycle(assetID, generation);
  }, 320);
}

function applyReviewCloudPreviewSnapshot(snapshot, assetID, generation) {
  if (!reviewCloudPreviewIsCurrent(assetID, generation)
    || snapshot?.assetID !== assetID) return;
  const recovery = state.review.cloudPreview;
  recovery.operationID = snapshot.operationID || null;
  recovery.progress = Number(snapshot.progress) || 0;
  if (snapshot.phase === "downloading") {
    recovery.status = "downloading";
    renderReviewCloudPreviewRecovery();
    scheduleReviewCloudPreviewPoll(assetID, generation);
    return;
  }
  if (snapshot.phase === "completed") {
    displayDownloadedReviewCloudPreview(assetID, generation);
    return;
  }
  stopReviewCloudPreviewPolling();
  recovery.operationID = null;
  recovery.status = snapshot.phase === "cancelled" ? "available" : "failed";
  renderReviewCloudPreviewRecovery();
  if (snapshot.phase === "cancelled") toast("已停止获取 iCloud 预览");
  else toast(snapshot.message || "无法获取 iCloud 预览");
}

async function resumeReviewCloudPreviewLifecycle(assetID, generation) {
  try {
    const snapshot = await api(`/v1/assets/${assetID}/cloud-preview-requests`);
    if (snapshot.phase === "downloading") {
      applyReviewCloudPreviewSnapshot(snapshot, assetID, generation);
    }
  } catch (error) {
    if (error?.status !== 404) {
      console.debug("review cloud preview resume unavailable", error);
    }
  }
}

async function pollReviewCloudPreviewLifecycle(assetID, generation) {
  const recovery = state.review.cloudPreview;
  if (!reviewCloudPreviewIsCurrent(assetID, generation)
    || recovery.status !== "downloading") return;
  try {
    const snapshot = await api(`/v1/assets/${assetID}/cloud-preview-requests`);
    applyReviewCloudPreviewSnapshot(snapshot, assetID, generation);
  } catch (error) {
    if (!reviewCloudPreviewIsCurrent(assetID, generation)) return;
    stopReviewCloudPreviewPolling();
    recovery.operationID = null;
    recovery.status = "failed";
    renderReviewCloudPreviewRecovery();
    toast(error.message || "无法读取 iCloud 预览进度");
  }
}

async function cancelReviewCloudPreview() {
  const recovery = state.review.cloudPreview;
  const assetID = reviewCloudPreviewCurrentAssetID();
  if (!assetID || recovery.assetID !== assetID
    || recovery.status !== "downloading" || !recovery.operationID) return;
  const operationID = recovery.operationID;
  const generation = recovery.requestGeneration;
  stopReviewCloudPreviewPolling();
  recovery.status = "cancelling";
  renderReviewCloudPreviewRecovery();
  try {
    const snapshot = await api(`/v1/assets/${assetID}/cloud-preview-requests/cancel`, {
      method: "POST",
      body: JSON.stringify({ operationID }),
    });
    applyReviewCloudPreviewSnapshot(snapshot, assetID, generation);
  } catch (error) {
    if (!reviewCloudPreviewIsCurrent(assetID, generation)) return;
    recovery.status = "downloading";
    renderReviewCloudPreviewRecovery();
    scheduleReviewCloudPreviewPoll(assetID, generation);
    toast(error.message || "无法取消 iCloud 预览");
  }
}

async function downloadReviewCloudPreview() {
  const recovery = state.review.cloudPreview;
  const assetID = reviewCloudPreviewCurrentAssetID();
  if (!assetID || state.mediaKind !== "image" || !state.online) return;
  if (recovery.status === "downloading" && supportsCloudPreviewLifecycle()) {
    await cancelReviewCloudPreview();
    return;
  }
  const generation = ++recovery.requestGeneration;
  recovery.assetID = assetID;
  recovery.status = "downloading";
  recovery.progress = 0;
  recovery.operationID = supportsCloudPreviewLifecycle() ? crypto.randomUUID() : null;
  renderReviewCloudPreviewRecovery();

  if (supportsCloudPreviewLifecycle()) {
    const operationID = recovery.operationID;
    try {
      const snapshot = await api(`/v1/assets/${assetID}/cloud-preview-requests`, {
        method: "POST",
        body: JSON.stringify({ operationID }),
      });
      applyReviewCloudPreviewSnapshot(snapshot, assetID, generation);
    } catch (error) {
      if (!reviewCloudPreviewIsCurrent(assetID, generation)) return;
      recovery.operationID = null;
      recovery.status = "failed";
      renderReviewCloudPreviewRecovery();
      toast(error.message || "无法获取 iCloud 预览");
    }
    return;
  }

  try {
    const response = await rawFetch(`/v1/assets/${assetID}/cloud-preview`, { method: "POST" });
    if (!response.ok) {
      const payload = await parseResponse(response).catch(() => null);
      throw new APIError(response.status, typeof payload === "object" ? payload : {
        message: `获取预览失败（${response.status}）`,
      });
    }
    const downloaded = await response.blob();
    if (!downloaded.type.startsWith("image/")) {
      throw new Error("Host 未返回可显示的预览");
    }
    displayDownloadedReviewCloudPreview(assetID, generation);
  } catch (error) {
    if (!reviewCloudPreviewIsCurrent(assetID, generation)) return;
    recovery.status = "failed";
    renderReviewCloudPreviewRecovery();
    toast(error.message || "无法获取 iCloud 预览");
  }
}

function stopInspectorVideo() {
  elements.previewVideo.pause();
  elements.previewVideo.removeAttribute("src");
  elements.previewVideo.removeAttribute("poster");
  delete elements.previewVideo.dataset.assetId;
  delete elements.previewVideo.dataset.contentRevision;
  elements.previewVideo.load();
  elements.previewVideo.classList.add("hidden");
}

function stopLightboxVideo() {
  state.lightboxRequestGeneration += 1;
  elements.lightboxVideo.pause();
  elements.lightboxVideo.removeAttribute("src");
  elements.lightboxVideo.removeAttribute("poster");
  delete elements.lightboxVideo.dataset.assetId;
  delete elements.lightboxVideo.dataset.contentRevision;
  elements.lightboxVideo.load();
  elements.lightboxVideo.classList.add("hidden");
}

async function showInspectorVideo(detail) {
  const assetID = detail.assetID;
  const contentRevision = String(detail.contentRevision);
  if (elements.previewVideo.dataset.assetId === assetID
    && elements.previewVideo.dataset.contentRevision === contentRevision
    && elements.previewVideo.hasAttribute("src")
    && !elements.previewVideo.error) {
    elements.previewVideo.classList.remove("hidden");
    elements.previewLoading.classList.add("hidden");
    return;
  }
  stopInspectorVideo();
  clearProtectedImageSource(elements.previewImage);
  elements.previewImage.classList.add("hidden");
  elements.previewPlaceholderImage.classList.add("hidden");
  resetCloudPreviewRecovery();
  elements.openLightboxButton.classList.add("hidden");
  elements.previewLoading.classList.remove("hidden");

  const poster = assetThumbnailPlaceholder(assetID);
  if (poster) elements.previewVideo.poster = poster;
  elements.previewVideo.dataset.assetId = assetID;
  elements.previewVideo.dataset.contentRevision = contentRevision;
  if (state.authMode === "account") {
    const workerReady = await updateMediaWorkerAuthorization(state.accountAuthorization);
    if (!workerReady || state.selectedDetail?.assetID !== assetID) {
      if (state.selectedDetail?.assetID === assetID) {
        elements.previewLoading.classList.add("hidden");
        toast("当前浏览器无法建立视频播放通道");
      }
      return;
    }
  }
  if (state.selectedDetail?.assetID !== assetID) return;
  elements.previewVideo.src = `/v1/assets/${assetID}/media?r=${contentRevision}`;
  elements.previewVideo.classList.remove("hidden");
  elements.previewVideo.load();
}

function syncInspectorTagChip(chip, {
  tagID,
  displayName,
  decision,
  summary = "",
  batch = false,
  disabled = false,
  surface = null,
  searchActive = false,
  baseTitle = null,
  baseHelpDetail = null,
}) {
  const created = !chip;
  if (!chip) {
    chip = document.createElement("button");
    chip.type = "button";
    chip.className = "inspector-tag-chip write-action";
  }
  toggleInspectorTagClass(chip, "batch", batch);
  setInspectorTagData(chip, "tagChipAction", "accept");
  setInspectorTagData(chip, "tagId", tagID);
  setInspectorTagData(chip, "decision", decision);
  setInspectorTagAttribute(chip, "aria-pressed", String(decision === "accepted"));
  setInspectorTagAttribute(
    chip,
    "aria-label",
    `${displayName}，${summary || ({ accepted: "已确认", rejected: "已拒绝", unknown: "未决定", mixed: "混合状态" }[decision] || decision)}；点击确认，右键清除`
  );
  setInspectorTagData(chip, "helpTitle", displayName);
  setInspectorTagData(chip, "helpKind", "tag");
  const defaultHelpDetail = [
    batch
      ? `所选项目：${summary || ({ accepted: "全部确认", rejected: "全部拒绝", unknown: "全部未决定", mixed: "状态不一致" }[decision] || decision)}。`
      : `当前项目：${({ accepted: "已确认", rejected: "已拒绝", unknown: "未决定", mixed: "状态不一致" }[decision] || decision)}。`,
    batch
      ? "左键把所选项目全部确认，右键全部清除；右侧按钮可全部确认、拒绝或设为未决定。"
      : "左键确认，右键清除；右侧按钮可确认、拒绝或设为未决定。",
    "聚焦后按 X 拒绝，按 Delete 清除。",
  ].join("\n");
  const nextDisabled = !state.online || state.tagMutating || disabled;
  if (chip.disabled !== nextDisabled) chip.disabled = nextDisabled;
  const resolvedTitle = baseTitle || `点击确认“${displayName}”；右键清除`;
  const resolvedHelpDetail = baseHelpDetail || defaultHelpDetail;
  const reorderTitle = surface
    ? (searchActive ? "；清除标签搜索后可拖放排序" : "；拖动可排序或移动分组")
    : "";
  const reorderHelpDetail = surface
    ? (searchActive
      ? "\n当前正在搜索；清除搜索后才能调整标签顺序或分组。"
      : "\n拖动可调整顺序或分组；Option + 上/下调整顺序，Option + 左/右移动分组。")
    : "";
  const title = resolvedTitle + reorderTitle;
  if (chip.title !== title) chip.title = title;
  setInspectorTagData(chip, "helpDetail", resolvedHelpDetail + reorderHelpDetail);
  if (surface) {
    setInspectorTagData(chip, "tagReorderSurface", surface);
    const draggable = !searchActive
      && !state.tagManagementMutating
      && !state.tagMutating
      && !chip.disabled;
    if (chip.draggable !== draggable) chip.draggable = draggable;
    setInspectorTagAttribute(
      chip,
      "aria-keyshortcuts",
      "Alt+ArrowUp Alt+ArrowDown Alt+ArrowLeft Alt+ArrowRight"
    );
  }

  let icon = chip.querySelector(":scope > .inspector-tag-chip-icon");
  if (!icon) {
    icon = document.createElement("span");
    icon.className = "inspector-tag-chip-icon";
    icon.setAttribute("aria-hidden", "true");
    icon.textContent = "#";
    chip.prepend(icon);
  }
  let copy = chip.querySelector(":scope > .inspector-tag-chip-copy");
  if (!copy) {
    copy = document.createElement("span");
    copy.className = "inspector-tag-chip-copy";
    if (icon.nextSibling) chip.insertBefore(copy, icon.nextSibling);
    else chip.append(copy);
  }
  let name = copy.querySelector(":scope > strong");
  if (!name) {
    name = document.createElement("strong");
    copy.prepend(name);
  }
  setInspectorTagText(name, displayName);
  let detail = copy.querySelector(":scope > small");
  if (summary) {
    if (!detail) {
      detail = document.createElement("small");
      copy.append(detail);
    }
    setInspectorTagText(detail, summary);
  } else {
    detail?.remove();
  }
  let marker = chip.querySelector(":scope > .inspector-tag-chip-marker");
  if (!marker) {
    marker = document.createElement("span");
    marker.className = "inspector-tag-chip-marker";
    marker.setAttribute("aria-hidden", "true");
    chip.append(marker);
  }
  setInspectorTagText(
    marker,
    { accepted: "✓", rejected: "×", mixed: "混" }[decision] || ""
  );
  if (created) chip.append(icon, copy, marker);
  return chip;
}

function syncSingleInspectorTagRow(row, tag, searchActive) {
  if (!row) {
    row = document.createElement("div");
    row.className = "tag-row";
  }
  let chip = row.querySelector(":scope > [data-tag-chip-action]");
  chip = syncInspectorTagChip(chip, {
    tagID: tag.tagID,
    displayName: tag.displayName,
    decision: tag.decision,
    surface: "single",
    searchActive,
  });

  let actions = row.querySelector(":scope > .tag-actions");
  if (!actions) {
    actions = document.createElement("div");
    actions.className = "tag-actions";
    actions.setAttribute("role", "group");
    row.append(actions);
  }
  setInspectorTagAttribute(actions, "aria-label", `${tag.displayName} 标签决定`);
  appendTagDecisionButtons(actions, tag.tagID, {
    accepted: tag.decision === "accepted",
    rejected: tag.decision === "rejected",
    unknown: tag.decision === "unknown",
  }, {
    displayName: tag.displayName,
  });
  if (row.firstElementChild !== chip) row.prepend(chip);
  if (chip.nextElementSibling !== actions) row.insertBefore(actions, chip.nextElementSibling);
  return row;
}

function syncSelectionInspectorTagRow(
  row,
  tag,
  aggregate,
  total,
  loading,
  searchActive
) {
  if (!row) {
    row = document.createElement("div");
    row.className = "selection-tag-row";
  }
  const summary = loading
    ? "正在统计…"
    : selectionAggregateText(aggregate, total);
  const decision = aggregate?.acceptedCount === total
    ? "accepted"
    : aggregate?.rejectedCount === total
      ? "rejected"
      : aggregate?.unknownCount === total
        ? "unknown"
        : "mixed";
  let chip = row.querySelector(":scope > [data-tag-chip-action]");
  chip = syncInspectorTagChip(chip, {
    tagID: tag.id,
    displayName: tag.displayName,
    decision,
    summary,
    batch: true,
    // Reordering remains available while aggregate counts refresh. Decision
    // buttons below stay disabled until the authoritative projection arrives.
    disabled: !total,
    surface: "selection",
    searchActive,
  });

  let actions = row.querySelector(":scope > .tag-actions");
  if (!actions) {
    actions = document.createElement("div");
    actions.className = "tag-actions";
    actions.setAttribute("role", "group");
    row.append(actions);
  }
  setInspectorTagAttribute(actions, "aria-label", `${tag.displayName} 批量标签决定`);
  appendTagDecisionButtons(actions, tag.id, {
    accepted: aggregate?.acceptedCount === total,
    rejected: aggregate?.rejectedCount === total,
    unknown: aggregate?.unknownCount === total,
    disabled: !total || loading,
  }, {
    displayName: tag.displayName,
    batch: true,
  });
  if (row.firstElementChild !== chip) row.prepend(chip);
  if (chip.nextElementSibling !== actions) row.insertBefore(actions, chip.nextElementSibling);
  return row;
}

function syncReviewInspectorTagRow(
  row,
  tag,
  projection,
  selectedCount,
  searchActive
) {
  if (!row) {
    row = document.createElement("div");
    row.className = "tag-row";
  }
  const batch = selectedCount > 1;
  let chip = row.querySelector(":scope > [data-tag-chip-action]");
  chip = syncInspectorTagChip(chip, {
    tagID: tag.id,
    displayName: tag.displayName,
    decision: projection.decision,
    summary: projection.summary,
    batch,
    disabled: !selectedCount || Boolean(projection.states.disabled),
    surface: "review",
    searchActive,
  });

  let actions = row.querySelector(":scope > .tag-actions");
  if (!actions) {
    actions = document.createElement("div");
    actions.className = "tag-actions";
    actions.setAttribute("role", "group");
    row.append(actions);
  }
  setInspectorTagAttribute(actions, "aria-label", `${tag.displayName} 标签决定`);
  appendTagDecisionButtons(actions, tag.id, projection.states, {
    displayName: tag.displayName,
    batch,
  });
  if (row.firstElementChild !== chip) row.prepend(chip);
  if (chip.nextElementSibling !== actions) row.insertBefore(actions, chip.nextElementSibling);
  return row;
}

function syncPlaceholderInspectorTagRow(row, tag) {
  if (!row) {
    row = document.createElement("div");
    row.className = "tag-row inspector-placeholder-tag-row";
  }
  let chip = row.querySelector(":scope > [data-tag-chip-action]");
  chip = syncInspectorTagChip(chip, {
    tagID: tag.id,
    displayName: tag.displayName,
    decision: "unknown",
    summary: "选择照片后可应用",
    surface: "placeholder",
    baseTitle: `选择照片后可应用“${tag.displayName}”；当前可拖动整理`,
    baseHelpDetail: [
      "当前没有选择照片；点击、右键、X 或 Delete 不会写入标签决定。",
      "选择照片后可在同一检查器直接确认、拒绝或清除这个标签。",
    ].join("\n"),
  });
  toggleInspectorTagClass(chip, "labeling-disabled", true);
  setInspectorTagAttribute(chip, "aria-disabled", "true");
  setInspectorTagAttribute(
    chip,
    "aria-label",
    `${tag.displayName}，当前未选择照片；可整理顺序或移动分组`
  );
  setInspectorTagData(chip, "helpTitle", tag.displayName);
  setInspectorTagData(chip, "helpKind", "tag");
  if (row.firstElementChild !== chip) row.prepend(chip);
  for (const child of [...row.children]) {
    if (child !== chip) child.remove();
  }
  return row;
}

function renderPlaceholderTagEditor() {
  const container = elements.inspectorPlaceholderTags;
  if (!container || container.dataset.activeTagDrag) return;
  const tags = orderedActiveTags();
  reconcileInspectorTagGroups(container, tags, syncPlaceholderInspectorTagRow);
  if (!tags.length) {
    let empty = container.querySelector(":scope > .sidebar-empty");
    if (!empty) {
      empty = document.createElement("p");
      empty.className = "sidebar-empty";
      container.append(empty);
    }
    setInspectorTagText(empty, "尚无活动标签；选择照片后可新建并应用。");
  } else {
    container.querySelector(":scope > .sidebar-empty")?.remove();
  }
  restoreInspectorTagFocus("placeholder");
}

function inspectorTagFocusSelector(pending) {
  if (!pending) return null;
  if (pending.kind === "group") {
    return `[data-inspector-tag-group-toggle="${CSS.escape(pending.id)}"]`;
  }
  if (pending.kind === "decision") {
    return `[data-action="${CSS.escape(pending.action)}"]`
      + `[data-tag-id="${CSS.escape(pending.id)}"]`;
  }
  return `[data-tag-chip-action][data-tag-id="${CSS.escape(pending.id)}"]`;
}

function restoreInspectorTagFocus(surface) {
  const pending = state.pendingInspectorTagFocus;
  if (!pending || pending.surface !== surface) return;
  requestAnimationFrame(() => {
    const container = surface === "selection"
      ? elements.selectionInspectorTags
      : surface === "placeholder"
        ? elements.inspectorPlaceholderTags
        : surface === "review"
          ? elements.reviewTags
          : elements.inspectorTags;
    const selector = inspectorTagFocusSelector(pending);
    const target = selector ? container.querySelector(selector) : null;
    if (!target) return;
    target.focus({ preventScroll: true });
    if (document.activeElement === target) state.pendingInspectorTagFocus = null;
  });
}

function appendTagDecisionButtons(
  actions,
  tagID,
  states,
  { displayName = "当前标签", batch = false } = {}
) {
  const existing = new Map(
    [...actions.querySelectorAll(":scope > [data-action]")]
      .map((button) => [button.dataset.action, button])
  );
  const wanted = [];
  for (const [action, symbol, label, active] of [
    ["accept", "✓", "确认", states.accepted],
    ["reject", "×", "拒绝", states.rejected],
    ["clear", "−", "清除", states.unknown],
  ]) {
    let button = existing.get(action);
    if (!button) {
      button = document.createElement("button");
      button.type = "button";
      button.className = "tag-action write-action";
    }
    setInspectorTagData(button, "action", action);
    setInspectorTagData(button, "tagId", tagID);
    if (button.title !== label) button.title = label;
    setInspectorTagData(button, "helpTitle", `${displayName} · ${label}`);
    setInspectorTagData(button, "helpKind", "tag");
    setInspectorTagData(button, "helpDetail", active
      ? `当前已是“${label}”状态；再次执行保持不变。`
      : `${batch ? "把全部所选项目" : "把当前项目"}设为“${label}”；不会改变其他标签。`);
    setInspectorTagAttribute(button, "aria-label", label);
    setInspectorTagAttribute(button, "aria-pressed", String(Boolean(active)));
    toggleInspectorTagClass(button, "active", Boolean(active));
    const disabled = !state.online || state.tagMutating || Boolean(states.disabled);
    if (button.disabled !== disabled) button.disabled = disabled;
    setInspectorTagText(button, symbol);
    wanted.push(button);
  }
  for (const [index, button] of wanted.entries()) {
    if (actions.children[index] !== button) {
      actions.insertBefore(button, actions.children[index] || null);
    }
  }
  for (const button of [...actions.children]) {
    if (!wanted.includes(button)) button.remove();
  }
}

function suggestionOriginText(origin) {
  return {
    featurePrint: "特征向量",
    standardModel: "标准模型",
    personalModel: "个人模型",
    personalAdamW: "超级个人模型",
  }[origin] || "模型建议";
}

function inspectorSuggestionKey(suggestion) {
  return `${suggestion.tagID}|${suggestion.suggestionOrigin}`;
}

function createInspectorSuggestionRow(key) {
  const row = document.createElement("div");
  row.className = "inspector-suggestion-row";
  row.dataset.inspectorSuggestionRowKey = key;

  const copy = document.createElement("div");
  copy.className = "inspector-suggestion-copy";
  const name = document.createElement("strong");
  const origin = document.createElement("span");
  origin.className = "inspector-suggestion-origin";
  copy.append(name, origin);

  const actions = document.createElement("div");
  actions.className = "inspector-suggestion-actions";
  actions.setAttribute("role", "group");
  for (const [action, label, className] of [
    ["accept", "属于", "accept"],
    ["reject", "不属于", "reject"],
  ]) {
    const button = document.createElement("button");
    button.type = "button";
    button.className = `button button-plain inspector-suggestion-action ${className} write-action`;
    button.dataset.action = action;
    button.textContent = label;
    actions.append(button);
  }
  row.append(copy, actions);
  return row;
}

function syncInspectorSuggestionRow(row, suggestion, index) {
  const key = inspectorSuggestionKey(suggestion);
  row.dataset.inspectorSuggestionRowKey = key;
  const name = row.querySelector(".inspector-suggestion-copy strong");
  const origin = row.querySelector(".inspector-suggestion-origin");
  const actions = row.querySelector(".inspector-suggestion-actions");
  if (name.textContent !== suggestion.displayName) name.textContent = suggestion.displayName;
  const originText = suggestionOriginText(suggestion.suggestionOrigin);
  if (origin.textContent !== originText) origin.textContent = originText;
  actions.setAttribute("aria-label", `${suggestion.displayName} AI 建议`);
  for (const button of actions.querySelectorAll("[data-action]")) {
    button.dataset.tagId = suggestion.tagID;
    button.dataset.inspectorSuggestionKey = key;
    button.dataset.inspectorSuggestionIndex = String(index);
    button.disabled = !state.online || state.tagMutating;
  }
}

function restoreInspectorSuggestionFocus(suggestions) {
  const pending = state.pendingInspectorSuggestionFocus;
  if (!pending) return;
  requestAnimationFrame(() => {
    let target = elements.inspectorSuggestions.querySelector(
      `[data-inspector-suggestion-key="${CSS.escape(pending.key)}"]`
        + `[data-action="${CSS.escape(pending.action)}"]`
    );
    if (!target && suggestions.length) {
      const index = Math.min(pending.index, suggestions.length - 1);
      const key = inspectorSuggestionKey(suggestions[index]);
      target = elements.inspectorSuggestions.querySelector(
        `[data-inspector-suggestion-key="${CSS.escape(key)}"]`
          + `[data-action="${CSS.escape(pending.action)}"]`
      );
    }
    if (!target) target = elements.inspectorSuggestionsTitle;
    target.focus({ preventScroll: true });
    if (document.activeElement === target) state.pendingInspectorSuggestionFocus = null;
  });
}

function renderInspectorSuggestions(detail) {
  const suggestions = detail.pendingSuggestions || [];
  const visible = state.inspectorSuggestionsExpanded ? suggestions : suggestions.slice(0, 5);
  elements.inspectorSuggestionsSection.classList.toggle("hidden", suggestions.length === 0);
  elements.inspectorSuggestionCount.textContent = suggestions.length ? String(suggestions.length) : "";
  const wanted = [];
  for (const [index, suggestion] of visible.entries()) {
    const key = inspectorSuggestionKey(suggestion);
    const row = elements.inspectorSuggestions.querySelector(
      `[data-inspector-suggestion-row-key="${CSS.escape(key)}"]`
    ) || createInspectorSuggestionRow(key);
    syncInspectorSuggestionRow(row, suggestion, index);
    wanted.push(row);
  }
  for (const [index, row] of wanted.entries()) {
    if (elements.inspectorSuggestions.children[index] !== row) {
      elements.inspectorSuggestions.insertBefore(
        row,
        elements.inspectorSuggestions.children[index] || null
      );
    }
  }
  for (const row of [...elements.inspectorSuggestions.children]) {
    if (!wanted.includes(row)) row.remove();
  }

  const remaining = suggestions.length - visible.length;
  elements.expandInspectorSuggestionsButton.classList.toggle(
    "hidden",
    state.inspectorSuggestionsExpanded || remaining <= 0
  );
  elements.expandInspectorSuggestionsButton.textContent = remaining > 0
    ? `另外 ${remaining} 条建议`
    : "";
  restoreInspectorSuggestionFocus(visible);
}

function resetAssetLocalSuggestionState(assetID = null) {
  state.assetLocalSuggestions.requestGeneration += 1;
  state.assetLocalSuggestions.assetID = assetID;
  state.assetLocalSuggestions.track = "standard";
  state.assetLocalSuggestions.phase = "ready";
  state.assetLocalSuggestions.suggestions = [];
  state.assetLocalSuggestions.submitting = false;
  state.assetLocalSuggestions.errorMessage = "";
  state.assetLocalSuggestions.pendingFocus = null;
}

function assetLocalSuggestionTrackText(track) {
  return track === "personal" ? "个人标签" : "标准场景";
}

function assetLocalSuggestionRecommendationText(recommendation) {
  return recommendation === "autoAssigned" ? "自动匹配" : "建议复核";
}

function restoreAssetLocalSuggestionFocus() {
  const pending = state.assetLocalSuggestions.pendingFocus;
  if (!pending) return;
  requestAnimationFrame(() => {
    let target = pending.id
      ? elements.inspectorLocalModelBody.querySelector(
        `[data-local-suggestion-id="${CSS.escape(pending.id)}"]`
          + `[data-action="${CSS.escape(pending.action)}"]`
      )
      : null;
    if (!target) {
      const actions = [...elements.inspectorLocalModelBody.querySelectorAll(
        "[data-local-suggestion-id][data-action]"
      )];
      target = actions[Math.min(pending.index, Math.max(0, actions.length - 1))]
        || elements.inspectorLocalModelTitle;
    }
    target.focus({ preventScroll: true });
    if (document.activeElement === target) {
      state.assetLocalSuggestions.pendingFocus = null;
    }
  });
}

function syncAssetLocalSuggestionState(message, { loading = false } = {}) {
  let row = elements.inspectorLocalModelBody.querySelector(
    ":scope > [data-local-suggestion-state]"
  );
  if (!row) {
    row = document.createElement("p");
    row.className = "inspector-local-model-state";
    row.dataset.localSuggestionState = "true";
    const spinner = document.createElement("span");
    spinner.className = "spinner";
    spinner.setAttribute("aria-hidden", "true");
    const copy = document.createElement("span");
    row.append(spinner, copy);
  }
  row.querySelector(".spinner").classList.toggle("hidden", !loading);
  const existingCopy = row.querySelector("span:last-child");
  if (existingCopy.textContent !== message) existingCopy.textContent = message;
  for (const child of [...elements.inspectorLocalModelBody.children]) {
    if (child !== row) child.remove();
  }
  if (elements.inspectorLocalModelBody.firstElementChild !== row) {
    elements.inspectorLocalModelBody.prepend(row);
  }
}

function createAssetLocalSuggestionRow(suggestionID) {
  const row = document.createElement("div");
  row.className = "inspector-local-model-result";
  row.dataset.localSuggestionRowId = suggestionID;
  const copy = document.createElement("div");
  copy.className = "inspector-local-model-result-copy";
  const name = document.createElement("strong");
  const recommendation = document.createElement("span");
  recommendation.className = "inspector-local-model-recommendation";
  copy.append(name, recommendation);
  row.append(copy);
  return row;
}

function syncAssetLocalSuggestionRow(row, suggestion, index, selectedTrack, localState) {
  row.dataset.localSuggestionRowId = suggestion.id;
  const name = row.querySelector(".inspector-local-model-result-copy strong");
  const recommendation = row.querySelector(".inspector-local-model-recommendation");
  const displayName = suggestion.displayName || "未命名标签";
  if (name.textContent !== displayName) name.textContent = displayName;
  const recommendationText = assetLocalSuggestionRecommendationText(suggestion.recommendation);
  if (recommendation.textContent !== recommendationText) {
    recommendation.textContent = recommendationText;
  }

  let actions = row.querySelector(".inspector-local-model-result-actions");
  if (selectedTrack !== "personal" || !suggestion.tagID) {
    actions?.remove();
    return;
  }
  if (!actions) {
    actions = document.createElement("div");
    actions.className = "inspector-local-model-result-actions";
    actions.setAttribute("role", "group");
    for (const [action, symbol, label] of [
      ["reject", "×", "不属于"],
      ["accept", "✓", "属于"],
    ]) {
      const button = document.createElement("button");
      button.type = "button";
      button.className = "button button-plain write-action";
      button.dataset.action = action;
      button.title = label;
      button.setAttribute("aria-label", label);
      button.textContent = symbol;
      actions.append(button);
    }
    row.append(actions);
  }
  actions.setAttribute("aria-label", `${displayName} 个人模型建议`);
  for (const button of actions.querySelectorAll("[data-action]")) {
    button.dataset.localSuggestionId = suggestion.id;
    button.dataset.localSuggestionIndex = String(index);
    button.dataset.tagId = suggestion.tagID;
    button.disabled = !state.online || state.tagMutating || localState.submitting;
  }
}

function reconcileAssetLocalSuggestionRows(suggestions, selectedTrack, localState) {
  elements.inspectorLocalModelBody.querySelector(
    ":scope > [data-local-suggestion-state]"
  )?.remove();
  const wanted = [];
  for (const [index, suggestion] of suggestions.entries()) {
    const row = elements.inspectorLocalModelBody.querySelector(
      `[data-local-suggestion-row-id="${CSS.escape(suggestion.id)}"]`
    ) || createAssetLocalSuggestionRow(suggestion.id);
    syncAssetLocalSuggestionRow(row, suggestion, index, selectedTrack, localState);
    wanted.push(row);
  }
  for (const [index, row] of wanted.entries()) {
    if (elements.inspectorLocalModelBody.children[index] !== row) {
      elements.inspectorLocalModelBody.insertBefore(
        row,
        elements.inspectorLocalModelBody.children[index] || null
      );
    }
  }
  for (const row of [...elements.inspectorLocalModelBody.children]) {
    if (!wanted.includes(row)) row.remove();
  }
}

function renderInspectorLocalSuggestions(detail) {
  const supported = supportsAssetLocalSuggestions()
    && state.mediaKind === "image"
    && Boolean(detail);
  elements.inspectorLocalModelSection.classList.toggle("hidden", !supported);
  if (!supported) {
    clearElement(elements.inspectorLocalModelBody);
    elements.inspectorLocalModelTrack.classList.add("hidden");
    return;
  }

  const localState = state.assetLocalSuggestions;
  const selectedTrack = localState.track === "personal" ? "personal" : "standard";
  const controlsDisabled = !state.online
    || localState.submitting
    || state.tagMutating
    || localState.assetID !== detail.assetID;
  for (const [button, track] of [
    [elements.inspectorStandardModelButton, "standard"],
    [elements.inspectorPersonalModelButton, "personal"],
  ]) {
    const selected = selectedTrack === track;
    button.setAttribute("aria-pressed", String(selected));
    button.disabled = controlsDisabled;
    button.textContent = assetLocalSuggestionTrackText(track);
  }

  const showsTrack = localState.phase !== "ready";
  elements.inspectorLocalModelTrack.classList.toggle("hidden", !showsTrack);
  elements.inspectorLocalModelTrack.textContent = assetLocalSuggestionTrackText(selectedTrack);

  if (localState.phase === "ready") {
    syncAssetLocalSuggestionState("对当前照片运行标准场景或个人标签模型。");
    return;
  }
  if (localState.phase === "loading") {
    syncAssetLocalSuggestionState("正在分析当前照片…", { loading: true });
    return;
  }
  if (localState.phase === "previewUnavailable") {
    syncAssetLocalSuggestionState("这张照片的本地预览尚不可用，请先使用上方的 iCloud 获取入口。");
    return;
  }
  if (localState.phase === "personalUnavailable") {
    syncAssetLocalSuggestionState("当前目录没有可用于这些标签的个人模型。");
    return;
  }
  if (localState.phase === "serviceUnavailable") {
    syncAssetLocalSuggestionState("本地模型服务当前不可用；照片、标签和已有建议不受影响。");
    return;
  }
  if (localState.phase === "failed") {
    syncAssetLocalSuggestionState(
      localState.errorMessage || "结果未通过安全校验，已忽略本次分析。"
    );
    return;
  }

  const suggestions = Array.isArray(localState.suggestions)
    ? localState.suggestions
    : [];
  if (!suggestions.length) {
    syncAssetLocalSuggestionState("当前模型没有给出建议。");
    return;
  }
  reconcileAssetLocalSuggestionRows(suggestions, selectedTrack, localState);
  restoreAssetLocalSuggestionFocus();
}

async function requestAssetLocalSuggestions(track) {
  const detail = state.selectedDetail;
  if (!detail
    || detail.assetID !== state.selectedAssetID
    || state.mediaKind !== "image"
    || !supportsAssetLocalSuggestions()
    || !state.online
    || state.assetLocalSuggestions.submitting) return false;

  const assetID = detail.assetID;
  const workspaceGeneration = state.workspaceGeneration;
  const requestGeneration = ++state.assetLocalSuggestions.requestGeneration;
  state.assetLocalSuggestions.assetID = assetID;
  state.assetLocalSuggestions.track = track === "personal" ? "personal" : "standard";
  state.assetLocalSuggestions.phase = "loading";
  state.assetLocalSuggestions.suggestions = [];
  state.assetLocalSuggestions.submitting = true;
  state.assetLocalSuggestions.errorMessage = "";
  state.assetLocalSuggestions.pendingFocus = null;
  renderInspectorLocalSuggestions(detail);
  syncWriteActionControls();

  try {
    const response = await api(`/v1/assets/${assetID}/local-suggestions`, {
      method: "POST",
      body: JSON.stringify({
        operationID: crypto.randomUUID(),
        track: state.assetLocalSuggestions.track,
      }),
    });
    if (workspaceGeneration !== state.workspaceGeneration
      || requestGeneration !== state.assetLocalSuggestions.requestGeneration
      || state.selectedAssetID !== assetID
      || state.selectedDetail?.assetID !== assetID) return false;
    if (response.assetID !== assetID || response.track !== state.assetLocalSuggestions.track) {
      throw new Error("Mac 返回了不匹配的照片分析结果");
    }
    state.assetLocalSuggestions.phase = response.state || "failed";
    state.assetLocalSuggestions.suggestions = Array.isArray(response.suggestions)
      ? response.suggestions
      : [];

    if (response.track === "standard" && response.state === "results") {
      try {
        await Promise.all([
          refreshTagCatalogAfterMutation(),
          loadInspector(assetID, { preserveExisting: true, quiet: true }),
        ]);
      } catch {
        void refreshWorkspace({
          quiet: true,
          kinds: ["tagsChanged", "reviewChanged"],
        });
      }
      if (workspaceGeneration !== state.workspaceGeneration
        || requestGeneration !== state.assetLocalSuggestions.requestGeneration
        || state.selectedAssetID !== assetID) return false;
    }
    return true;
  } catch (error) {
    if (workspaceGeneration === state.workspaceGeneration
      && requestGeneration === state.assetLocalSuggestions.requestGeneration
      && state.selectedAssetID === assetID) {
      state.assetLocalSuggestions.phase = "failed";
      state.assetLocalSuggestions.suggestions = [];
      state.assetLocalSuggestions.errorMessage = error.message || "本地模型分析失败";
    }
    return false;
  } finally {
    if (workspaceGeneration === state.workspaceGeneration
      && requestGeneration === state.assetLocalSuggestions.requestGeneration
      && state.selectedAssetID === assetID) {
      state.assetLocalSuggestions.submitting = false;
      if (state.selectedDetail?.assetID === assetID) {
        renderInspectorLocalSuggestions(state.selectedDetail);
      }
      syncWriteActionControls();
    }
  }
}

async function applyAssetLocalSuggestionDecision(button) {
  const assetID = state.selectedDetail?.assetID;
  const suggestionID = button.dataset.localSuggestionId;
  const tagID = button.dataset.tagId;
  const action = button.dataset.action;
  if (!assetID || !suggestionID || !tagID || !["accept", "reject"].includes(action)) return;
  const suggestions = state.assetLocalSuggestions.suggestions;
  const index = Number(button.dataset.localSuggestionIndex) || 0;
  const nextSuggestion = suggestions[index + 1] || suggestions[index - 1] || null;
  state.assetLocalSuggestions.pendingFocus = {
    id: nextSuggestion?.id || null,
    index,
    action,
  };
  const updated = await mutateTag(tagID, action);
  if (!updated
    || state.selectedDetail?.assetID !== assetID
    || state.assetLocalSuggestions.assetID !== assetID) return;
  state.assetLocalSuggestions.suggestions = state.assetLocalSuggestions.suggestions.filter(
    (suggestion) => suggestion.id !== suggestionID
  );
  renderInspectorLocalSuggestions(state.selectedDetail);
}

function syncInspectorViewOriginalControl(detail) {
  const isVideo = state.mediaKind === "video";
  elements.viewOriginalButtonLabel.textContent = isVideo
    ? "在网页播放原视频"
    : "在网页查看原图";
  elements.viewOriginalButtonIcon.textContent = isVideo ? "▶" : "⌕";
  elements.viewOriginalButton.disabled = !state.online
    || detail.availability !== "available";
}

function syncInspectorOpenOriginalControl(detail) {
  const isVideo = state.mediaKind === "video";
  elements.openOriginalButtonLabel.textContent = state.openingOriginal
    ? "正在 Mac 上打开…"
    : (isVideo ? "在 Mac 上用系统播放器打开" : "在 Mac 上用“预览”打开原图");
  elements.openOriginalButtonIcon.textContent = isVideo ? "▶" : "↗";
  elements.openOriginalButton.classList.toggle("busy", state.openingOriginal);
  elements.openOriginalHint.textContent = isVideo
    ? "网页直接播放原始视频；也可交给运行 ImageAll 的 Mac 系统播放器"
    : "网页只在明确点击后读取本地原图；iCloud 原图不会静默下载，也可在 Mac 打开";
  elements.openOriginalButton.disabled = !state.online
    || detail.availability !== "available"
    || state.openingOriginal;
}

function renderInspector(detail) {
  if (state.selectedDetail?.assetID !== detail.assetID) {
    state.inspectorSuggestionsExpanded = false;
    state.pendingInspectorSuggestionFocus = null;
    resetCloudPreviewRecovery();
  }
  if (state.assetLocalSuggestions.assetID !== detail.assetID) {
    resetAssetLocalSuggestionState(detail.assetID);
  }
  state.selectedDetail = detail;
  if (!state.inspectorDismissed) elements.inspector.classList.add("open");
  elements.inspectorSelectionTitle.textContent = state.mediaKind === "video"
    ? "已选择 1 个视频"
    : "已选择 1 张照片";
  elements.assetFileName.textContent = detail.fileName || "未命名照片";
  renderInspectorLocalSuggestions(detail);
  renderInspectorSuggestions(detail);

  if (state.mediaKind === "video") {
    showInspectorVideo(detail);
  } else {
    stopInspectorVideo();
    elements.openLightboxButton.classList.remove("hidden");
    elements.previewImage.alt = detail.fileName || `所选${currentMediaNoun()}预览`;
    const previewPath = `/v1/assets/${detail.assetID}/preview?r=${detail.contentRevision}`;
    const previewReady = elements.previewImage.dataset.protectedPath === previewPath
      && elements.previewImage.hasAttribute("src")
      && elements.previewImage.dataset.protectedAssignedRequestId
        === elements.previewImage.dataset.protectedRequestId
      && elements.previewImage.complete
      && elements.previewImage.naturalWidth > 0;
    const recoveringCloudPreview = state.cloudPreview.assetID === detail.assetID
      && state.cloudPreview.status !== "hidden";
    if (recoveringCloudPreview) {
      elements.previewLoading.classList.add("hidden");
      elements.previewImage.classList.add("hidden");
      elements.openLightboxButton.classList.add("hidden");
      renderCloudPreviewRecovery();
    } else if (!previewReady) {
      const showsPlaceholder = showPreviewPlaceholder(detail.assetID);
      elements.previewLoading.classList.toggle("hidden", showsPlaceholder);
      elements.previewImage.classList.add("hidden");
      setProtectedImageSource(elements.previewImage, previewPath, {
        priority: "high",
        forceFetch: true,
      });
    } else {
      elements.previewLoading.classList.add("hidden");
      elements.previewImage.classList.remove("hidden");
      hidePreviewPlaceholder();
      resetCloudPreviewRecovery();
    }
  }

  const isVideo = state.mediaKind === "video";
  const rows = [
    metadataRow("来源", detail.sourceName),
    metadataRow("相对位置", detail.relativePath),
    metadataRow("媒体", isVideo ? "视频" : "照片"),
    metadataRow("尺寸", detail.width && detail.height ? `${detail.width} × ${detail.height}` : "—"),
    ...(isVideo ? [metadataRow("时长", formatDuration(detail.durationMs))] : []),
    metadataRow("文件大小", formatFileSize(detail.fingerprintSizeBytes)),
    metadataRow("拍摄时间", formatDate(detail.mediaCreatedAtMs)),
    metadataRow("修改时间", formatDate(detail.mediaModifiedAtMs)),
    metadataRow("格式", detail.mediaType),
    metadataRow("状态", availabilityText(detail.availability)),
  ];
  reconcileMetadataRows(elements.assetMetadata, rows);
  syncInspectorViewOriginalControl(detail);
  syncInspectorOpenOriginalControl(detail);
  renderFavoriteControls();
  renderGalleryRemovalControls();

  const tagQuery = state.inspectorTagSearchText.toLocaleLowerCase("zh-CN");
  const tags = detail.tags.filter((tag) => (
    tagByID(tag.tagID)?.state !== "archived"
      && (!tagQuery || tag.displayName.toLocaleLowerCase("zh-CN").includes(tagQuery))
  ));
  elements.tagEmpty.classList.toggle("hidden", tags.length > 0);
  elements.tagSummary.textContent = `已确认 ${detail.acceptedTagCount} · 已拒绝 ${detail.rejectedTagCount}`;

  reconcileInspectorTagGroups(elements.inspectorTags, tags, (row, tag) => (
    syncSingleInspectorTagRow(row, tag, Boolean(tagQuery))
  ));
  restoreInspectorTagFocus("single");
  updateInspectorNavigation();
  renderInspectorSurface();
}

async function openOriginalAssetOnMac(assetID, mediaKind, availability) {
  if (!assetID || availability !== "available" || !state.online || state.openingOriginal) return;
  state.openingOriginal = true;
  if (state.selectedDetail) syncInspectorOpenOriginalControl(state.selectedDetail);
  const reviewItem = state.review.items[state.review.selectedIndex];
  if (reviewWorkspaceIsOpen() && reviewItem) {
    syncReviewOpenOriginalControl(
      reviewInspectorDetailMatches(reviewItem) ? state.review.detail : null,
      reviewItem
    );
  }
  const lightboxItem = currentLightboxItem();
  if (lightboxItem) syncLightboxOpenOriginalControl(lightboxItem);
  try {
    await api(`/v1/assets/${assetID}/open-original`, { method: "POST" });
    toast(mediaKind === "video" ? "已交给 Mac 系统播放器" : "已交给 Mac“预览”打开");
  } catch (error) {
    toast(error.message || "无法在 Mac 上打开原始文件");
  } finally {
    state.openingOriginal = false;
    if (state.selectedDetail) syncInspectorOpenOriginalControl(state.selectedDetail);
    const currentReviewItem = state.review.items[state.review.selectedIndex];
    if (reviewWorkspaceIsOpen() && currentReviewItem) {
      syncReviewOpenOriginalControl(
        reviewInspectorDetailMatches(currentReviewItem) ? state.review.detail : null,
        currentReviewItem
      );
    }
    const lightboxItemAfterOpen = currentLightboxItem();
    if (lightboxItemAfterOpen) syncLightboxOpenOriginalControl(lightboxItemAfterOpen);
  }
}

async function openSelectedOriginalOnMac() {
  const detail = state.selectedDetail;
  if (!detail) return;
  await openOriginalAssetOnMac(detail.assetID, state.mediaKind, detail.availability);
}

async function openLightboxOriginalOnMac() {
  const item = currentLightboxItem();
  if (!item) return;
  await openOriginalAssetOnMac(item.id, lightboxMediaKind(), item.availability);
}

function viewOriginalAssetInWeb(context, assetID, mediaKind, availability) {
  if (!assetID || availability !== "available" || !state.online) return;
  openLightbox(context, assetID, { original: mediaKind !== "video" });
}

function viewSelectedOriginalInWeb() {
  const detail = state.selectedDetail;
  if (!detail) return;
  viewOriginalAssetInWeb("library", detail.assetID, state.mediaKind, detail.availability);
}

function viewReviewOriginalInWeb() {
  const item = state.review.items[state.review.selectedIndex];
  const detail = reviewInspectorDetailMatches(item) ? state.review.detail : null;
  if (!item || !detail || state.review.selectedAssetIDs.size !== 1) return;
  viewOriginalAssetInWeb("review", item.assetID, state.mediaKind, detail.availability);
}

function updateInspectorNavigation() {
  const index = state.assets.findIndex((asset) => asset.id === state.selectedAssetID);
  const hasSelection = index >= 0;
  elements.inspectorPosition.textContent = hasSelection
    ? `${index + 1} / ${state.assets.length}`
    : "";
  elements.inspectorPreviousButton.disabled = !hasSelection || index === 0;
  elements.inspectorNextButton.disabled = !hasSelection || index >= state.assets.length - 1;
}

function selectionAggregateText(aggregate, total) {
  if (!aggregate) return "未决定";
  if (aggregate.acceptedCount === total) return "全部确认";
  if (aggregate.rejectedCount === total) return "全部拒绝";
  if (aggregate.unknownCount === total) return "全部未决定";
  return `混合 · 确认 ${aggregate.acceptedCount} · 拒绝 ${aggregate.rejectedCount} · 未决定 ${aggregate.unknownCount}`;
}

function selectionPrimaryAssetID() {
  const loadedIDs = new Set(state.assets.map((asset) => asset.id));
  if (state.selectedAssetID
    && loadedIDs.has(state.selectedAssetID)
    && state.selectedAssetIDs.has(state.selectedAssetID)) {
    return state.selectedAssetID;
  }
  if (state.selectionAnchorID
    && loadedIDs.has(state.selectionAnchorID)
    && state.selectedAssetIDs.has(state.selectionAnchorID)) {
    return state.selectionAnchorID;
  }
  return state.assets.find((asset) => state.selectedAssetIDs.has(asset.id))?.id || null;
}

function renderSelectionPrimary() {
  const assetID = selectionPrimaryAssetID();
  const asset = state.assets.find((candidate) => candidate.id === assetID) || null;
  const detail = state.selectionPrimaryDetail?.assetID === assetID
    && state.selectionPrimaryDetail.contentRevision === asset.contentRevision
    ? state.selectionPrimaryDetail
    : null;
  const visible = state.selectionMode && Boolean(assetID && asset);
  elements.selectionInspectorPrimary.classList.toggle("hidden", !visible);
  if (!visible) {
    clearProtectedImageSource(elements.selectionInspectorPrimaryImage);
    reconcileMetadataRows(elements.selectionInspectorPrimaryMetadata, []);
    return;
  }

  const orderedSelection = state.assets.filter((candidate) => (
    state.selectedAssetIDs.has(candidate.id)
  ));
  const selectedIndex = orderedSelection.findIndex((candidate) => candidate.id === assetID);
  elements.selectionInspectorPrimaryPosition.textContent = selectedIndex >= 0
    ? `当前主项 · 选区 ${selectedIndex + 1} / ${orderedSelection.length}`
    : "当前主项";
  elements.selectionInspectorPrimaryTitle.textContent = detail?.fileName
    || asset.fileName
    || `未命名${currentMediaNoun()}`;
  elements.selectionInspectorPrimaryPreview.setAttribute(
    "aria-label",
    `全屏查看${elements.selectionInspectorPrimaryTitle.textContent}`
  );
  elements.selectionInspectorPrimaryImage.alt = `${elements.selectionInspectorPrimaryTitle.textContent}预览`;
  syncProtectedThumbnailSource(elements.selectionInspectorPrimaryImage, assetID, {
    width: 520,
    revision: detail?.contentRevision ?? asset.contentRevision,
  });

  const width = detail?.width ?? asset.width;
  const height = detail?.height ?? asset.height;
  const rows = [
    metadataRow("来源", detail?.sourceName || asset.sourceName),
    ...(detail?.relativePath ? [metadataRow("相对位置", detail.relativePath)] : []),
    metadataRow("媒体", state.mediaKind === "video" ? "视频" : "照片"),
    metadataRow("尺寸", width && height ? `${width} × ${height}` : "—"),
    ...(state.mediaKind === "video"
      ? [metadataRow("时长", formatDuration(detail?.durationMs ?? asset.durationMs))]
      : []),
    ...(detail ? [
      metadataRow("文件大小", formatFileSize(detail.fingerprintSizeBytes)),
      metadataRow("拍摄时间", formatDate(detail.mediaCreatedAtMs)),
      metadataRow("修改时间", formatDate(detail.mediaModifiedAtMs)),
      metadataRow("格式", detail.mediaType),
      metadataRow("状态", availabilityText(detail.availability)),
    ] : []),
  ];
  reconcileMetadataRows(elements.selectionInspectorPrimaryMetadata, rows);
}

async function loadSelectionPrimaryDetail() {
  const assetID = selectionPrimaryAssetID();
  if (!state.selectionMode || !assetID) {
    state.selectionPrimaryDetail = null;
    state.selectionPrimaryLoadingAssetID = null;
    state.selectionPrimaryRequestGeneration += 1;
    renderSelectionPrimary();
    return;
  }
  const asset = state.assets.find((candidate) => candidate.id === assetID) || null;
  if (!asset) {
    state.selectionPrimaryDetail = null;
    state.selectionPrimaryLoadingAssetID = null;
    state.selectionPrimaryRequestGeneration += 1;
    renderSelectionPrimary();
    return;
  }
  if ((state.selectionPrimaryDetail?.assetID === assetID
      && state.selectionPrimaryDetail.contentRevision === asset?.contentRevision)
    || state.selectionPrimaryLoadingAssetID === assetID) {
    renderSelectionPrimary();
    return;
  }

  const workspaceGeneration = state.workspaceGeneration;
  const requestGeneration = ++state.selectionPrimaryRequestGeneration;
  state.selectionPrimaryDetail = null;
  state.selectionPrimaryLoadingAssetID = assetID;
  renderSelectionPrimary();
  try {
    const detail = await api(`/v1/assets/${assetID}`);
    if (workspaceGeneration !== state.workspaceGeneration
      || requestGeneration !== state.selectionPrimaryRequestGeneration
      || !state.selectionMode
      || selectionPrimaryAssetID() !== assetID) return;
    state.selectionPrimaryDetail = detail;
  } catch {
    // The loaded asset summary and protected thumbnail still provide useful
    // context; a transient detail failure must not disrupt batch labeling.
  } finally {
    if (requestGeneration === state.selectionPrimaryRequestGeneration) {
      state.selectionPrimaryLoadingAssetID = null;
      renderSelectionPrimary();
    }
  }
}

function renderSelectionInspectorHeader({ pending = false } = {}) {
  const total = state.selectedAssetIDs.size;
  elements.selectionInspectorTitle.textContent = `已选择 ${mediaItemCountText(total)}`;
  elements.selectionInspectorTags.setAttribute("aria-busy", String(pending));
  if (pending && total) elements.batchAggregate.textContent = "正在统计…";
  renderSelectionPrimary();
}

function renderSelectionInspector() {
  if (elements.selectionInspectorTags.dataset.activeTagDrag) {
    // Loading the batch aggregate must not replace the DOM node that currently
    // owns the native drag session. Apply the latest counts as soon as the drop
    // or cancellation ends.
    state.sidebarDrag.pendingSelectionRender = true;
    return;
  }
  state.sidebarDrag.pendingSelectionRender = false;
  const total = state.selectedAssetIDs.size;
  renderFavoriteControls();
  renderSelectionInspectorHeader({ pending: state.loadingAggregate });
  const aggregates = new Map(
    state.selectionAggregates.map((aggregate) => [aggregate.tagID, aggregate])
  );
  const query = state.selectionTagSearchText.toLocaleLowerCase("zh-CN");
  const tags = orderedActiveTags().filter((tag) => (
    !query || tag.displayName.toLocaleLowerCase("zh-CN").includes(query)
  ));

  reconcileInspectorTagGroups(elements.selectionInspectorTags, tags, (row, tag) => (
    syncSelectionInspectorTagRow(
      row,
      tag,
      aggregates.get(tag.id),
      total,
      state.loadingAggregate,
      Boolean(query)
    )
  ));

  if (!tags.length) {
    let empty = elements.selectionInspectorTags.querySelector(":scope > .sidebar-empty");
    if (!empty) {
      empty = document.createElement("p");
      empty.className = "sidebar-empty";
      elements.selectionInspectorTags.append(empty);
    }
    setInspectorTagText(empty, "没有匹配的标签");
  } else {
    elements.selectionInspectorTags.querySelector(":scope > .sidebar-empty")?.remove();
  }
  restoreInspectorTagFocus("selection");
}

function renderInspectorSurface() {
  const workspacePresentation = galleryOverviewIsOpen() && galleryOverviewUsesIntegratedLayout()
    ? {
      symbol: "▥",
      title: "图库总览",
      description: "总览页已在主窗口展示聚合统计。",
    }
    : (worldMapIsOpen() && worldMapUsesIntegratedLayout()
      ? {
        symbol: "◎",
        title: "照片世界",
        description: "在主窗口拖拽、缩放和选择照片建筑。",
      }
      : null);
  const showsWorkspace = Boolean(workspacePresentation);
  const showsTrainingWorkspace = trainingWorkspaceIsOpen()
    && trainingWorkspaceUsesIntegratedLayout();
  const showsSlimmingWorkspace = slimmingWorkspaceIsOpen()
    && slimmingWorkspaceUsesIntegratedLayout();
  const showsIntegratedWorkspace = showsWorkspace
    || showsTrainingWorkspace
    || showsSlimmingWorkspace;
  if (workspacePresentation) {
    elements.inspectorWorkspacePlaceholderSymbol.textContent = workspacePresentation.symbol;
    elements.inspectorWorkspacePlaceholderTitle.textContent = workspacePresentation.title;
    elements.inspectorWorkspacePlaceholderText.textContent = workspacePresentation.description;
  }
  const showsSelection = state.selectionMode && state.selectedAssetIDs.size > 0;
  const showsDetail = !showsSelection && Boolean(state.selectedDetail);
  elements.inspectorWorkspacePlaceholder.classList.toggle("hidden", !showsWorkspace);
  elements.inspectorTrainingWorkspace.classList.toggle("hidden", !showsTrainingWorkspace);
  if (showsTrainingWorkspace) renderTrainingWorkspaceInspector();
  elements.inspectorSlimmingWorkspace.classList.toggle("hidden", !showsSlimmingWorkspace);
  if (showsSlimmingWorkspace) renderSlimmingInspector();
  elements.inspectorPlaceholder.classList.toggle(
    "hidden",
    showsIntegratedWorkspace || showsSelection || showsDetail
  );
  elements.selectionInspector.classList.toggle(
    "hidden",
    showsIntegratedWorkspace || !showsSelection
  );
  elements.inspectorContent.classList.toggle(
    "hidden",
    showsIntegratedWorkspace || !showsDetail
  );
  if (!showsDetail) {
    hidePreviewPlaceholder();
    stopInspectorVideo();
    resetCloudPreviewRecovery();
  }
  if (!showsIntegratedWorkspace && !showsSelection && !showsDetail) {
    renderPlaceholderTagEditor();
  }
  if (!showsIntegratedWorkspace
    && (showsSelection || showsDetail)
    && !state.inspectorDismissed) {
    elements.inspector.classList.add("open");
  }
  if (!showsIntegratedWorkspace && showsSelection) {
    renderSelectionInspector();
  }
  syncInlineTagCreationControls();
  checkpointGalleryInspectorHistory();
}

function renderSelectionMutation() {
  const showsSelection = state.selectionMode && state.selectedAssetIDs.size > 0;
  const selectionSurfaceVisible = !elements.selectionInspector.classList.contains("hidden");
  renderSelectionBar({ updateInspector: false });
  if (showsSelection && selectionSurfaceVisible) {
    renderSelectionInspectorHeader({ pending: true });
  } else {
    renderInspectorSurface();
  }
  scheduleWorkspaceHistoryCheckpoint();
}

function updateLibraryTitle() {
  const source = state.sources.find((item) => item.id === state.selectedSourceID);
  const mediaTitle = state.mediaKind === "video" ? "视频" : "照片";
  if (galleryOverviewIsOpen() && galleryOverviewUsesIntegratedLayout()) {
    elements.libraryTitle.textContent = "图库总览";
  } else if (worldMapIsOpen() && worldMapUsesIntegratedLayout()) {
    elements.libraryTitle.textContent = "照片世界";
  } else if (reviewWorkspaceIsOpen() && reviewWorkspaceUsesIntegratedLayout()) {
    elements.libraryTitle.textContent = "待审核建议";
  } else if (trainingWorkspaceIsOpen() && trainingWorkspaceUsesIntegratedLayout()) {
    elements.libraryTitle.textContent = "训练工程";
  } else if (slimmingWorkspaceIsOpen() && slimmingWorkspaceUsesIntegratedLayout()) {
    elements.libraryTitle.textContent = "图库瘦身";
  } else if (state.libraryScope === "worldMapGallery" && state.worldMapGalleryScope) {
    elements.libraryTitle.textContent = `${state.worldMapGalleryScope.displayName} · 照片世界`;
  } else if (state.libraryScope === "favorites") {
    elements.libraryTitle.textContent = `红心收藏 · ${mediaTitle}`;
  } else if (source) {
    const folderName = state.folderScope?.relativePath.split("/").filter(Boolean).at(-1);
    elements.libraryTitle.textContent = folderName
      ? `${folderName} · ${source.displayName} · ${mediaTitle}`
      : `${source.displayName} · ${mediaTitle}`;
  } else {
    elements.libraryTitle.textContent = `全部${mediaTitle}`;
  }
  renderWorldMapGalleryScope();
  renderFolderBreadcrumb();
  scheduleAdaptiveToolbarSync();
}

function folderBreadcrumbIdentity(sourceID, relativePath = null) {
  return JSON.stringify([sourceID, relativePath || ""]);
}

function createFolderBreadcrumbButton() {
  const button = document.createElement("button");
  button.type = "button";
  button.className = "folder-breadcrumb-button";
  return button;
}

function syncFolderBreadcrumbButton(button, sourceID, relativePath, title, current) {
  button.dataset.folderBreadcrumbSourceId = sourceID;
  if (relativePath) button.dataset.folderBreadcrumbPath = relativePath;
  else delete button.dataset.folderBreadcrumbPath;
  if (button.textContent !== title) button.textContent = title;
  if (current) button.setAttribute("aria-current", "page");
  else button.removeAttribute("aria-current");
}

function createFolderBreadcrumbSeparator(relativePath) {
  const separator = document.createElement("span");
  separator.className = "folder-breadcrumb-separator";
  separator.dataset.folderBreadcrumbSeparatorPath = relativePath;
  separator.setAttribute("aria-hidden", "true");
  separator.textContent = "›";
  return separator;
}

function renderFolderBreadcrumb() {
  const scope = state.libraryScope === "all" ? state.folderScope : null;
  const source = scope
    ? state.sources.find((candidate) => candidate.id === scope.sourceID)
    : null;
  const items = elements.folderBreadcrumbItems;
  elements.folderBreadcrumb.classList.toggle("hidden", !scope || !source);
  if (!scope || !source) {
    delete items.dataset.folderBreadcrumbIdentity;
    reconcileStableChildren(items, []);
    return;
  }

  const identity = folderBreadcrumbIdentity(source.id, scope.relativePath);
  const sameIdentity = items.dataset.folderBreadcrumbIdentity === identity;
  const preservedScrollLeft = items.scrollLeft;
  const existingButtons = new Map(
    [...items.querySelectorAll(":scope > [data-folder-breadcrumb-source-id]")]
      .map((button) => [
        folderBreadcrumbIdentity(
          button.dataset.folderBreadcrumbSourceId,
          button.dataset.folderBreadcrumbPath
        ),
        button,
      ])
  );
  const existingSeparators = new Map(
    [...items.querySelectorAll(":scope > [data-folder-breadcrumb-separator-path]")]
      .map((separator) => [separator.dataset.folderBreadcrumbSeparatorPath, separator])
  );
  const children = [];
  const rootIdentity = folderBreadcrumbIdentity(source.id);
  const root = existingButtons.get(rootIdentity) || createFolderBreadcrumbButton();
  syncFolderBreadcrumbButton(root, source.id, null, source.displayName, false);
  children.push(root);

  const components = scope.relativePath.split("/").filter(Boolean);
  components.forEach((name, index) => {
    const relativePath = components.slice(0, index + 1).join("/");
    const separator = existingSeparators.get(relativePath)
      || createFolderBreadcrumbSeparator(relativePath);
    const buttonIdentity = folderBreadcrumbIdentity(source.id, relativePath);
    const button = existingButtons.get(buttonIdentity) || createFolderBreadcrumbButton();
    syncFolderBreadcrumbButton(
      button,
      source.id,
      relativePath,
      name,
      index === components.length - 1
    );
    children.push(separator, button);
  });
  reconcileStableChildren(items, children);
  items.dataset.folderBreadcrumbIdentity = identity;
  if (sameIdentity) {
    items.scrollLeft = preservedScrollLeft;
    return;
  }
  requestAnimationFrame(() => {
    if (items.dataset.folderBreadcrumbIdentity !== identity) return;
    items.scrollLeft = items.scrollWidth;
  });
}

function folderBreadcrumbButton(sourceID, relativePath = null) {
  const expectedPath = relativePath || "";
  return [...elements.folderBreadcrumbItems.querySelectorAll(
    `[data-folder-breadcrumb-source-id="${CSS.escape(sourceID)}"]`
  )].find((button) => (button.dataset.folderBreadcrumbPath || "") === expectedPath) || null;
}

function focusFolderBreadcrumbNavigation(sourceID, relativePath = null) {
  const target = relativePath
    ? folderBreadcrumbButton(sourceID, relativePath)
    : mobileSidebarLayoutQuery.matches
      ? elements.sidebarToggle
      : elements.sourceList.querySelector(
        `[data-source-id="${CSS.escape(sourceID)}"]`
      );
  target?.focus({ preventScroll: true });
  target?.scrollIntoView({ block: "nearest", inline: "nearest" });
}

function renderWorldMapGalleryScope() {
  const scope = state.libraryScope === "worldMapGallery"
    ? state.worldMapGalleryScope
    : null;
  elements.worldMapGalleryBanner.classList.toggle("hidden", !scope);
  elements.mediaKindTabs.classList.toggle("hidden", Boolean(scope));
  if (!scope) return;
  elements.worldMapGalleryName.textContent = scope.displayName || "未命名地点";
  elements.worldMapGallerySummary.textContent = `来自照片世界的精确地点范围 · ${worldMapCount(scope.photoCount)} 张照片`;
}

function filterCount() {
  const filters = state.filters;
  return filters.tagConditions.length
    + filters.availabilities.length
    + selectedMediaFormatGroups(filters.mediaTypes).length
    + Number(filters.tagPresence !== "any");
}

function renderFilterBadge() {
  const count = filterCount();
  elements.filterBadge.textContent = String(count);
  elements.filterBadge.classList.toggle("hidden", count === 0);
}

function filterDecisionText(decision) {
  return {
    accepted: "已确认",
    rejected: "已拒绝",
    excluded: "不包含",
  }[decision] || decision;
}

function selectedMediaFormatGroups(mediaTypes, mediaKind = state.mediaKind) {
  const selected = new Set(mediaTypes);
  return MEDIA_FORMAT_GROUPS.filter(
    (group) => group.mediaKinds.includes(mediaKind)
      && group.mediaTypes.every((mediaType) => selected.has(mediaType))
  );
}

function filterMediaTypeText(mediaTypes) {
  const groups = selectedMediaFormatGroups(mediaTypes);
  const recognized = new Set(groups.flatMap((group) => group.mediaTypes));
  const unknown = mediaTypes.filter((mediaType) => !recognized.has(mediaType));
  return [...groups.map((group) => group.label), ...unknown].join("、");
}

function activeFilterSummaryText() {
  const filters = state.filters;
  const positive = filters.tagConditions.filter(
    (condition) => condition.decision !== "excluded"
  );
  const separator = positive.length > 1
    ? (filters.tagMatchMode === "any" ? " 或 " : " 且 ")
    : " · ";
  const parts = filters.tagConditions.map((condition) => {
    const name = tagByID(condition.tagID)?.displayName || "未知标签";
    return `${name} ${filterDecisionText(condition.decision)}`;
  });
  let tagSummary = "";
  if (parts.length) {
    const positiveParts = filters.tagConditions
      .filter((condition) => condition.decision !== "excluded")
      .map((condition) => {
        const name = tagByID(condition.tagID)?.displayName || "未知标签";
        return `${name} ${filterDecisionText(condition.decision)}`;
      });
    const excludedParts = filters.tagConditions
      .filter((condition) => condition.decision === "excluded")
      .map((condition) => {
        const name = tagByID(condition.tagID)?.displayName || "未知标签";
        return `${name} ${filterDecisionText(condition.decision)}`;
      });
    tagSummary = [...(positiveParts.length ? [positiveParts.join(separator)] : []), ...excludedParts]
      .join(" · ");
  }
  const scopeSummary = {
    tagged: "仅已有标签",
    untagged: "仅无标签",
  }[filters.tagPresence];
  if (tagSummary) parts.splice(0, parts.length, tagSummary);
  else parts.length = 0;
  if (scopeSummary) parts.push(scopeSummary);
  if (filters.availabilities.length) {
    parts.push(filters.availabilities.map(availabilityText).join("、"));
  }
  if (filters.mediaTypes.length) parts.push(filterMediaTypeText(filters.mediaTypes));
  return parts.join(" · ");
}

function renderActiveFilterBar() {
  const count = filterCount();
  const positiveTagCount = state.filters.tagConditions.filter(
    (condition) => condition.decision !== "excluded"
  ).length;
  elements.activeFilterBar.classList.toggle("hidden", count === 0);
  elements.activeFilterSummary.textContent = activeFilterSummaryText();
  elements.activeFilterRelation.classList.toggle("hidden", positiveTagCount < 2);
  for (const button of elements.activeFilterRelation.querySelectorAll("[data-active-filter-match]")) {
    button.setAttribute(
      "aria-pressed",
      String(button.dataset.activeFilterMatch === state.filters.tagMatchMode)
    );
  }
  syncRovingSegmentedControl(
    elements.activeFilterRelation,
    "[data-active-filter-match]"
  );
  renderPersonalModelControls();
}

function libraryPersonalTrainingTagIDs() {
  return state.filters.tagConditions
    .filter((condition) => condition.decision === "accepted")
    .map((condition) => condition.tagID);
}

function activePersonalModelTrainingActivity() {
  return state.personalModelActivities.items.find((activity) =>
    ["personalCentroid", "personalAdamW"].includes(activity.method)
      && isActiveTrainingActivity(activity)
  ) || null;
}

function personalModelOperationState() {
  const training = activePersonalModelTrainingActivity();
  const sampleSuggestion = activeSampleSuggestion();
  const tagSuggestion = activeTagLibrarySuggestion();
  const librarySuggestion = activeLibrarySuggestionJobs()[0] || null;
  const suggestion = sampleSuggestion || tagSuggestion || librarySuggestion;
  const summary = training?.method === "personalAdamW"
    ? "正在训练超级个人模型"
    : training
      ? "正在重建个人模型"
      : suggestion
        ? "正在生成个人建议"
        : "";
  return {
    training,
    suggestion,
    busy: Boolean(training || suggestion),
    summary,
  };
}

function syncPersonalModelActionPresentation(
  button,
  { running, idleTitle, runningTitle, idleIcon, busy, busySummary }
) {
  const icon = button.querySelector(".library-toolbar-icon, .personal-model-action-icon");
  const label = button.querySelector(".library-toolbar-label");
  button.classList.toggle("is-running", running);
  button.setAttribute("aria-busy", String(running));
  button.setAttribute("aria-label", running ? runningTitle : idleTitle);
  button.title = running
    ? runningTitle
    : (busy ? `${idleTitle}（${busySummary}）` : idleTitle);
  if (icon) icon.textContent = running ? "" : idleIcon;
  if (label) label.textContent = running ? runningTitle.replace("个人模型", "").trim() : idleTitle;
}

function renderPersonalModelControls() {
  const tagIDs = libraryPersonalTrainingTagIDs();
  const tagNames = tagIDs
    .map((tagID) => tagByID(tagID)?.displayName)
    .filter(Boolean);
  const noun = state.mediaKind === "video" ? "视频" : "照片";
  const scope = state.selectedAssetIDs.size
    ? `当前选择 ${state.selectedAssetIDs.size} 项`
    : `全库${noun}`;
  elements.personalModelScopeSummary.textContent = tagNames.length
    ? `${tagNames.join("、")} · ${scope}`
    : `请先选择已确认标签 · ${scope}`;
  const offline = !state.online;
  const operation = personalModelOperationState();
  const centroidRunning = operation.training?.method === "personalCentroid";
  const adamWRunning = operation.training?.method === "personalAdamW";
  const suggestionRunning = Boolean(operation.suggestion);
  elements.personalModelButton.disabled = offline;
  elements.personalModelButton.classList.toggle("has-running-action", operation.busy);
  elements.personalModelButton.setAttribute("aria-busy", String(operation.busy));
  elements.personalModelButton.setAttribute(
    "aria-label",
    operation.busy ? `个人模型：${operation.summary}` : "个人模型"
  );
  elements.personalModelButton.title = operation.busy
    ? `${operation.summary}；打开查看状态`
    : "重建或训练个人模型";
  const personalModelIcon = elements.personalModelButton.querySelector(".library-toolbar-icon");
  if (personalModelIcon) personalModelIcon.textContent = operation.busy ? "" : "◎";
  elements.rebuildPersonalModelButton.disabled = offline || operation.busy;
  elements.rebuildPersonalAdamWButton.disabled = offline || operation.busy;
  elements.toolbarRebuildPersonalModelButton.disabled = offline || operation.busy;
  elements.toolbarRebuildPersonalAdamWButton.disabled = offline || operation.busy;
  syncPersonalModelActionPresentation(elements.toolbarRebuildPersonalModelButton, {
    running: centroidRunning,
    idleTitle: "重建个人模型",
    runningTitle: "正在重建…",
    idleIcon: "◎",
    busy: operation.busy,
    busySummary: operation.summary,
  });
  syncPersonalModelActionPresentation(elements.toolbarRebuildPersonalAdamWButton, {
    running: adamWRunning,
    idleTitle: "训练超级个人模型",
    runningTitle: "正在训练…",
    idleIcon: "✦",
    busy: operation.busy,
    busySummary: operation.summary,
  });
  syncPersonalModelActionPresentation(elements.rebuildPersonalModelButton, {
    running: centroidRunning,
    idleTitle: "重建个人模型",
    runningTitle: "正在重建个人模型…",
    idleIcon: "◎",
    busy: operation.busy,
    busySummary: operation.summary,
  });
  syncPersonalModelActionPresentation(elements.rebuildPersonalAdamWButton, {
    running: adamWRunning,
    idleTitle: "训练超级个人模型",
    runningTitle: "正在训练超级个人模型…",
    idleIcon: "✦",
    busy: operation.busy,
    busySummary: operation.summary,
  });
  elements.rebuildPersonalModelTitle.textContent = centroidRunning
    ? "正在重建个人模型…"
    : "重建个人模型";
  elements.rebuildPersonalAdamWTitle.textContent = adamWRunning
    ? "正在训练超级个人模型…"
    : "训练超级个人模型";
  const fullLibrary = state.librarySuggestions.snapshot?.personalMode === "fullLibrary";
  const activeSuggestion = fullLibrary
    ? activeLibrarySuggestionJobs().length > 0
    : Boolean(activeSampleSuggestion());
  elements.generatePersonalSuggestionsTitle.textContent = fullLibrary
    ? "使用个人模型扫描全库"
    : `抽 ${state.sampleSuggestions.maximumSampleCount || 500} 张生成建议`;
  elements.toolbarGeneratePersonalSuggestionsLabel.textContent =
    elements.generatePersonalSuggestionsTitle.textContent;
  elements.toolbarGeneratePersonalSuggestionsButton.setAttribute(
    "aria-label",
    elements.generatePersonalSuggestionsTitle.textContent
  );
  elements.toolbarGeneratePersonalSuggestionsButton.title =
    elements.generatePersonalSuggestionsTitle.textContent;
  elements.generatePersonalSuggestionsDetail.textContent = fullLibrary
    ? "按已确认标签扫描图库，结果进入待审核建议"
    : "从当前审核来源抽样，结果进入待审核建议";
  elements.generatePersonalSuggestionsButton.disabled = offline
    || operation.busy
    || state.mediaKind !== "image"
    || activeSuggestion
    || (!fullLibrary && !state.sampleSuggestions.isAvailable);
  elements.toolbarGeneratePersonalSuggestionsButton.disabled =
    elements.generatePersonalSuggestionsButton.disabled;
  syncPersonalModelActionPresentation(elements.toolbarGeneratePersonalSuggestionsButton, {
    running: suggestionRunning,
    idleTitle: elements.generatePersonalSuggestionsTitle.textContent,
    runningTitle: fullLibrary ? "正在扫描全库…" : "正在生成建议…",
    idleIcon: "✦",
    busy: operation.busy,
    busySummary: operation.summary,
  });
  elements.generatePersonalSuggestionsButton.classList.toggle("is-running", suggestionRunning);
  elements.generatePersonalSuggestionsButton.setAttribute(
    "aria-busy",
    String(suggestionRunning)
  );
  elements.generatePersonalSuggestionsTitle.textContent = suggestionRunning
    ? (fullLibrary ? "正在扫描全库…" : "正在生成建议…")
    : elements.toolbarGeneratePersonalSuggestionsLabel.textContent;
  elements.generatePersonalSuggestionsButton.title = state.mediaKind !== "image"
    ? "个人建议目前仅支持照片"
    : operation.busy
      ? operation.summary
      : elements.generatePersonalSuggestionsDetail.textContent;
  elements.toolbarGeneratePersonalSuggestionsButton.dataset.helpDetail = fullLibrary
    ? "按顶部审核来源范围使用 Mac 本地个人模型扫描全库；结果进入待审核队列。"
    : state.selectedAssetIDs.size
      ? `对当前选中的 ${Math.min(
        state.selectedAssetIDs.size,
        state.sampleSuggestions.maximumSampleCount || 500
      )} 项${noun}生成建议；结果进入待审核队列，可用 P 接受、X 拒绝。`
      : `从库中抽最多 ${state.sampleSuggestions.maximumSampleCount || 500} 张${noun}生成建议；结果进入待审核队列，可用 P 接受、X 拒绝。`;
  const hasSelection = state.selectedAssetIDs.size > 0;
  const canPrepareSelection = hasSelection && state.embeddingPreparation.isAvailable;
  const canFindSelection = hasSelection && supportsLibrarySlimming();
  for (const button of [
    elements.toolbarPrepareSelectedFeaturesButton,
    elements.preparePersonalSelectionButton,
  ]) {
    button.classList.toggle("hidden", !canPrepareSelection);
  }
  for (const button of [
    elements.toolbarFindSimilarSelectionButton,
    elements.findSimilarPersonalSelectionButton,
  ]) {
    button.classList.toggle("hidden", !canFindSelection);
  }
  requestAnimationFrame(syncPersonalModelToolbarPresentation);
}

function scheduleTrainingActivityPoll() {
  clearTimeout(state.personalModelActivities.pollTimer);
  state.personalModelActivities.pollTimer = null;
  if (!activePersonalModelTrainingActivity()) return;
  state.personalModelActivities.pollTimer = setTimeout(
    () => loadTrainingActivities({ quiet: true }),
    900
  );
}

async function loadTrainingActivities({ quiet = false } = {}) {
  const projection = state.personalModelActivities;
  if (!supportsTrainingActivities()) {
    projection.mediaKind = state.mediaKind;
    projection.items = [];
    projection.loading = false;
    renderPersonalModelControls();
    return;
  }
  const generation = ++projection.requestGeneration;
  const mediaKind = state.mediaKind;
  projection.loading = true;
  try {
    const query = new URLSearchParams({ mediaKind });
    const activities = await api(`/v1/training/activities?${query}`);
    if (generation !== projection.requestGeneration || mediaKind !== state.mediaKind) return;
    projection.mediaKind = mediaKind;
    projection.items = Array.isArray(activities) ? activities : [];
  } catch (error) {
    if (generation === projection.requestGeneration && !quiet) {
      toast(error.message || "无法读取个人模型训练状态");
    }
  } finally {
    if (generation === projection.requestGeneration) {
      projection.loading = false;
      renderPersonalModelControls();
      scheduleTrainingActivityPoll();
    }
  }
}

function syncPersonalModelToolbarPresentation() {
  const directActionsVisible = getComputedStyle(
    elements.personalModelToolbarActions
  ).display !== "none";
  syncPersonalModelSelectionActionPresentation(directActionsVisible);
  elements.personalModelToolbarActions.setAttribute(
    "aria-hidden",
    String(!directActionsVisible)
  );
  if (directActionsVisible && !elements.personalModelPopover.classList.contains("hidden")) {
    closePersonalModelPopover({ restoreFocus: false });
  }
}

function personalModelToolbarActionKind(button) {
  return new Map([
    [elements.toolbarRebuildPersonalModelButton, "rebuild"],
    [elements.toolbarRebuildPersonalAdamWButton, "adamw"],
    [elements.toolbarGeneratePersonalSuggestionsButton, "suggestions"],
    [elements.toolbarPrepareSelectedFeaturesButton, "prepare"],
    [elements.toolbarFindSimilarSelectionButton, "find"],
  ]).get(button) || null;
}

function syncPersonalModelSelectionActionPresentation(directActionsVisible) {
  const group = elements.personalModelToolbarActions;
  const wasVisible = state.personalModelToolbarWasVisible;
  const selectedDirectActionsVisible = directActionsVisible
    && state.selectedAssetIDs.size > 0;
  state.personalModelToolbarWasVisible = directActionsVisible;
  elements.batchPersonalModelActions.classList.toggle(
    "toolbar-personal-model-fallback-hidden",
    selectedDirectActionsVisible
  );
  elements.batchPersonalModelActions.setAttribute(
    "aria-hidden",
    String(selectedDirectActionsVisible)
  );

  const focusedAction = state.personalModelToolbarFocusedAction;
  const focusedButton = {
    rebuild: elements.toolbarRebuildPersonalModelButton,
    adamw: elements.toolbarRebuildPersonalAdamWButton,
    suggestions: elements.toolbarGeneratePersonalSuggestionsButton,
    prepare: elements.toolbarPrepareSelectedFeaturesButton,
    find: elements.toolbarFindSimilarSelectionButton,
  }[focusedAction] || null;
  const focusedActionStillVisible = directActionsVisible
    && focusedButton?.getClientRects().length > 0;
  const focusStayedInCollapsedGroup = group.contains(document.activeElement);
  if (!focusedAction
    || focusedActionStillVisible
    || (!wasVisible && !focusStayedInCollapsedGroup)) return;

  const compactTarget = {
    suggestions: elements.generateSelectedSuggestionsButton,
    prepare: elements.prepareSelectedFeaturesButton,
    find: elements.findSimilarSelectionButton,
  }[focusedAction] || null;
  const compactTargetVisible = compactTarget
    && !elements.batchBar.classList.contains("hidden")
    && compactTarget.getClientRects().length > 0;
  const fallback = compactTargetVisible
    ? compactTarget
    : elements.personalModelButton.getClientRects().length > 0
      ? elements.personalModelButton
      : elements.selectionModeButton;
  fallback.focus({ preventScroll: true });
  state.personalModelToolbarFocusedAction = null;
}

function syncSelectionFavoriteToolbarPresentation() {
  const group = elements.selectionFavoriteToolbarActions;
  const wasVisible = state.selectionFavoriteToolbarWasVisible;
  const directActionsVisible = !group.classList.contains("hidden")
    && getComputedStyle(group).display !== "none";
  state.selectionFavoriteToolbarWasVisible = directActionsVisible;
  group.setAttribute("aria-hidden", String(!directActionsVisible));
  elements.batchFavoriteActions.classList.toggle(
    "toolbar-favorite-fallback-hidden",
    directActionsVisible
  );
  elements.batchFavoriteActions.setAttribute(
    "aria-hidden",
    String(directActionsVisible)
  );

  const focusedAction = state.selectionFavoriteToolbarFocusedAction;
  const focusStayedInCollapsedGroup = group.contains(document.activeElement);
  if (directActionsVisible
    || !focusedAction
    || (!wasVisible && !focusStayedInCollapsedGroup)) return;
  const fallback = focusedAction === "unfavorite"
    ? elements.unfavoriteSelectedButton
    : elements.favoriteSelectedButton;
  const fallbackVisible = !elements.batchBar.classList.contains("hidden")
    && getComputedStyle(fallback).display !== "none";
  (fallbackVisible ? fallback : elements.selectionModeButton).focus({ preventScroll: true });
  state.selectionFavoriteToolbarFocusedAction = null;
}

function actionMenuDescriptor(kind) {
  return {
    sourceActions: {
      kind,
      route: "gallery",
      button: elements.sourceAllActionsButton,
      popover: elements.sourceActionsPopover,
    },
    tagActions: {
      kind,
      route: "gallery",
      button: elements.tagManagerButton,
      popover: elements.tagActionsPopover,
    },
    personalModel: {
      kind,
      route: "gallery",
      button: elements.personalModelButton,
      popover: elements.personalModelPopover,
    },
    reviewSources: {
      kind,
      route: "review",
      button: elements.reviewSourceFilterButton,
      popover: elements.reviewSourceFilterPopover,
    },
    slimmingSources: {
      kind,
      route: "slimming",
      button: elements.slimmingCatalogSourceButton,
      popover: elements.slimmingCatalogSourcePopover,
    },
    slimmingOptions: {
      kind,
      route: "slimming",
      button: elements.slimmingAnalysisOptionsButton,
      popover: elements.slimmingAnalysisOptionsPopover,
    },
  }[kind] || null;
}

function activeActionMenuDescriptor() {
  for (const kind of [
    "sourceActions",
    "tagActions",
    "personalModel",
    "reviewSources",
    "slimmingSources",
    "slimmingOptions",
  ]) {
    const descriptor = actionMenuDescriptor(kind);
    if (!descriptor.popover.classList.contains("hidden")) return descriptor;
  }
  return null;
}

function actionMenuBaseLevelFromHistory(context = {}) {
  return ["sidebar", "inspector", "lightbox"].includes(context.actionMenuBaseLevel)
    ? context.actionMenuBaseLevel
    : "workspace";
}

function actionMenuSelectorForTarget(descriptor, target = document.activeElement) {
  if (!descriptor?.popover.contains(target)) return null;
  const focusable = target.closest?.("button, input, select, textarea, [tabindex]");
  if (!(focusable instanceof HTMLElement) || !descriptor.popover.contains(focusable)) return null;
  if (focusable.id) return `#${CSS.escape(focusable.id)}`;
  for (const key of [
    "reviewSourceId",
    "slimmingCatalogSourceId",
    "slimmingMaintenanceSourceId",
    "slimmingJobActionId",
  ]) {
    const value = focusable.dataset[key];
    if (!value) continue;
    const attribute = key.replace(/[A-Z]/g, (letter) => `-${letter.toLowerCase()}`);
    const action = key === "slimmingJobActionId" && focusable.dataset.action
      ? `[data-action="${CSS.escape(focusable.dataset.action)}"]`
      : "";
    return `[data-${attribute}="${CSS.escape(value)}"]${action}`;
  }
  return null;
}

function actionMenuFallbackFocusTarget(descriptor) {
  if (!descriptor) return null;
  if (descriptor.kind === "sourceActions") {
    return sourceActionsFocusableButtons()[0] || elements.sourceActionsOpenManagerButton;
  }
  if (descriptor.kind === "tagActions") {
    return tagActionsFocusableButtons()[0] || elements.tagActionsOpenManagerButton;
  }
  if (descriptor.kind === "reviewSources") {
    return elements.reviewSourceFilterPopover.querySelector("button:not(:disabled)");
  }
  if (descriptor.kind === "slimmingSources") {
    return elements.slimmingCatalogSourceOptions.querySelector(
      "[data-slimming-catalog-source-id]:not(:disabled)"
    ) || elements.closeSlimmingCatalogSourceButton;
  }
  if (descriptor.kind === "slimmingOptions") {
    return elements.closeSlimmingAnalysisOptionsButton;
  }
  return elements.personalModelPopover.querySelector("button:not(:disabled)");
}

function actionMenuRestorableFocusTarget(descriptor) {
  const selector = state.actionMenuKind === descriptor?.kind
    ? state.actionMenuFocusedSelector
    : null;
  if (selector) {
    const target = descriptor.popover.querySelector(selector);
    if (target instanceof HTMLElement
      && !target.matches(":disabled")
      && target.getClientRects().length > 0) return target;
  }
  return actionMenuFallbackFocusTarget(descriptor);
}

function actionMenuIsAvailable(descriptor, route = visibleWorkspaceRoute()) {
  const routeMatches = ["sourceActions", "tagActions"].includes(descriptor?.kind)
    ? ["gallery", "galleryOverview", "worldMap", "review", "training", "slimming"]
      .includes(route)
    : descriptor?.route === route;
  return Boolean(
    descriptor
      && routeMatches
      && !descriptor.button.disabled
      && descriptor.button.getClientRects().length > 0
  );
}

function replaceActionMenuHistoryWithBase(baseLevel) {
  if (!state.workspaceNavigation.initialized
    || elements.appView.classList.contains("hidden")) return;
  const current = activeWorkspaceHistoryEntry();
  const route = visibleWorkspaceRoute();
  if (current?.route !== route || current.navigationLevel !== "actionMenu") return;
  const context = currentWorkspaceHistoryContext(route);
  if (context && typeof context === "object") {
    delete context.actionMenuBaseLevel;
    delete context.actionMenuKind;
  }
  const navigationLevel = visibleWorkspaceNavigationBaseLevel(route, baseLevel);
  history.replaceState({
    ...(history.state || {}),
    [WORKSPACE_HISTORY_KEY]: workspaceHistoryEntry(route, context, navigationLevel),
  }, "", location.href);
}

function closeActionMenu({
  restoreFocus = true,
  checkpoint = true,
  preserveState = true,
} = {}) {
  const descriptor = activeActionMenuDescriptor();
  if (!descriptor) return;
  if (elements.confirmDialog.open && state.confirmationBaseLevel === "actionMenu") {
    closeConfirmation({ restoreFocus: false, checkpoint: false, preserveState: false });
  }
  const focusedSelector = actionMenuSelectorForTarget(descriptor);
  if (focusedSelector) state.actionMenuFocusedSelector = focusedSelector;
  state.actionMenuKind = descriptor.kind;
  state.actionMenuScrollTop = descriptor.popover.scrollTop;
  if (descriptor.kind === "reviewSources" && focusedSelector) {
    state.review.sourceFilterFocusSelector = focusedSelector;
  }
  if (descriptor.kind === "slimmingOptions") {
    const maintenance = state.slimming.sourceMaintenance;
    maintenance.requestGeneration += 1;
    maintenance.loading = false;
    stopSlimmingSourceIndexPolling();
  }
  const baseLevel = state.actionMenuBaseLevel;
  const returnFocus = state.actionMenuReturnFocus;
  descriptor.popover.classList.add("hidden");
  descriptor.button.setAttribute("aria-expanded", "false");
  state.actionMenuReturnFocus = null;
  state.actionMenuBaseLevel = "workspace";
  if (!preserveState) {
    state.actionMenuKind = null;
    state.actionMenuFocusedSelector = null;
    state.actionMenuScrollTop = 0;
    if (descriptor.kind === "reviewSources") state.review.sourceFilterFocusSelector = null;
  }
  if (restoreFocus) restoreOverlayFocus(stableReturnFocusTarget(
    returnFocus || descriptor.button,
    descriptor.button
  ));
  if (checkpoint) replaceActionMenuHistoryWithBase(baseLevel);
}

function returnFromActionMenu({ restoreFocus = true } = {}) {
  if (elements.confirmDialog.open && state.confirmationBaseLevel === "actionMenu") {
    return returnFromConfirmation({ restoreFocus });
  }
  if (!activeActionMenuDescriptor()) return Promise.resolve();
  state.actionMenuHistoryRestoreFocus = restoreFocus;
  if (state.workspaceNavigation.pendingReturnPromise) {
    return state.workspaceNavigation.pendingReturnPromise;
  }
  const current = activeWorkspaceHistoryEntry();
  if (state.workspaceNavigation.initialized
    && current?.route === visibleWorkspaceRoute()
    && current.navigationLevel === "actionMenu") {
    const pending = new Promise((resolve) => {
      state.workspaceNavigation.pendingReturnResolve = resolve;
    });
    state.workspaceNavigation.pendingReturnPromise = pending;
    history.back();
    return pending;
  }
  closeActionMenu({ restoreFocus });
  state.actionMenuHistoryRestoreFocus = true;
  return Promise.resolve();
}

function openActionMenu(kind, {
  focus = true,
  historyMode = "pushActionMenu",
  baseLevel = null,
  restoring = false,
} = {}) {
  const descriptor = actionMenuDescriptor(kind);
  const route = visibleWorkspaceRoute();
  if (!actionMenuIsAvailable(descriptor, route)) return;
  const active = activeActionMenuDescriptor();
  if (active?.kind === kind) {
    if (focus) restoreOverlayFocus(actionMenuRestorableFocusTarget(descriptor));
    return;
  }
  const current = activeWorkspaceHistoryEntry();
  const replacesOverlay = historyMode === "pushActionMenu"
    && [
      "jobs",
      "filter",
      "layoutMenu",
      "actionMenu",
      "toolbarMenu",
      "sidebar",
      "commandPalette",
    ].includes(current?.navigationLevel)
    && !(["sourceActions", "tagActions"].includes(kind)
      && current?.navigationLevel === "sidebar");
  if (active) closeActionMenu({ restoreFocus: false, checkpoint: !replacesOverlay });
  state.actionMenuReturnFocus = descriptor.button;
  state.actionMenuBaseLevel = baseLevel
    || workspaceNavigationBaseLevel(
      current?.navigationLevel || "workspace",
      current?.context || {}
    );
  state.actionMenuKind = kind;
  if (!restoring) {
    state.actionMenuFocusedSelector = null;
    state.actionMenuScrollTop = 0;
    if (kind === "reviewSources") state.review.sourceFilterFocusSelector = null;
  }
  closeCompactToolbarMenu({ restoreFocus: false, checkpoint: !replacesOverlay });
  closeLayoutMenu({ restoreFocus: false, checkpoint: !replacesOverlay });
  closeFilterPopover({ restoreFocus: false, checkpoint: !replacesOverlay });
  closeJobsPopover({ restoreFocus: false, checkpoint: !replacesOverlay });
  hideContextMenus();
  if (kind === "personalModel") {
    renderPersonalModelControls();
  } else if (kind === "sourceActions") {
    renderSourceActionsMenu();
  } else if (kind === "tagActions") {
    renderTagActionsMenu();
  } else if (kind === "reviewSources") {
    renderReviewSourceFilter();
  } else if (kind === "slimmingSources") {
    renderSlimmingCatalogSourcePicker();
  } else if (kind === "slimmingOptions") {
    renderSlimmingSourceMaintenance();
  }
  descriptor.popover.classList.remove("hidden");
  descriptor.button.setAttribute("aria-expanded", "true");
  if (kind === "sourceActions") {
    positionSourceActionsMenu();
  } else if (kind === "tagActions") {
    positionTagActionsMenu();
  } else if (kind === "slimmingSources") {
    positionSlimmingCatalogSourcePicker();
    if (!restoring || !state.slimming.catalogSources.snapshot) {
      void loadSlimmingCatalogSources();
    }
  } else if (kind === "slimmingOptions") {
    if (!restoring || !state.slimming.sourceMaintenance.snapshot) {
      void loadSlimmingSourceMaintenance();
    } else {
      scheduleSlimmingSourceIndexPolling();
    }
  }
  if (historyMode !== "none") {
    recordWorkspaceHistory(
      route,
      currentWorkspaceHistoryContext(route),
      replacesOverlay ? "replaceOverlay" : historyMode
    );
  }
  requestAnimationFrame(() => {
    descriptor.popover.scrollTop = state.actionMenuScrollTop;
    if (!focus) return;
    const target = actionMenuRestorableFocusTarget(descriptor);
    target?.focus({ preventScroll: true });
    const selector = actionMenuSelectorForTarget(descriptor, target);
    if (selector) state.actionMenuFocusedSelector = selector;
  });
}

function reconcileActionMenuFromWorkspaceHistory(route, navigationLevel, context = {}) {
  const kind = typeof context.actionMenuKind === "string"
    ? context.actionMenuKind
    : null;
  const descriptor = actionMenuDescriptor(kind);
  const isConfirmationChild = navigationLevel === "confirmation"
    && context.confirmationBaseLevel === "actionMenu";
  const shouldOpen = (navigationLevel === "actionMenu" || isConfirmationChild)
    && route === visibleWorkspaceRoute()
    && actionMenuIsAvailable(descriptor, route);
  const active = activeActionMenuDescriptor();
  if (shouldOpen && active?.kind !== kind) {
    if (active) closeActionMenu({ restoreFocus: false, checkpoint: false });
    openActionMenu(kind, {
      focus: navigationLevel === "actionMenu",
      historyMode: "none",
      baseLevel: actionMenuBaseLevelFromHistory(context),
      restoring: true,
    });
  } else if (!shouldOpen && active) {
    const restoreFocus = state.actionMenuHistoryRestoreFocus;
    closeActionMenu({ restoreFocus, checkpoint: false, preserveState: true });
    state.actionMenuHistoryRestoreFocus = true;
  } else if (navigationLevel === "actionMenu" && !shouldOpen) {
    replaceActionMenuHistoryWithBase(actionMenuBaseLevelFromHistory(context));
  }
}

function toggleActionMenu(kind) {
  if (activeActionMenuDescriptor()?.kind === kind) {
    void returnFromActionMenu();
  } else {
    openActionMenu(kind);
  }
}

function positionSourceActionsMenu() {
  if (elements.sourceActionsPopover.classList.contains("hidden")) return;
  const anchor = elements.sourceAllActionsButton.getBoundingClientRect();
  const menu = elements.sourceActionsPopover;
  const gap = 5;
  const margin = 8;
  const maxLeft = Math.max(margin, window.innerWidth - menu.offsetWidth - margin);
  const maxTop = Math.max(margin, window.innerHeight - menu.offsetHeight - margin);
  menu.style.left = `${Math.min(Math.max(anchor.left, margin), maxLeft)}px`;
  menu.style.top = `${Math.min(Math.max(anchor.bottom + gap, margin), maxTop)}px`;
}

function positionTagActionsMenu() {
  if (elements.tagActionsPopover.classList.contains("hidden")) return;
  const anchor = elements.tagManagerButton.getBoundingClientRect();
  const menu = elements.tagActionsPopover;
  const gap = 5;
  const margin = 8;
  const maxLeft = Math.max(margin, window.innerWidth - menu.offsetWidth - margin);
  const maxTop = Math.max(margin, window.innerHeight - menu.offsetHeight - margin);
  menu.style.left = `${Math.min(Math.max(anchor.left, margin), maxLeft)}px`;
  menu.style.top = `${Math.min(Math.max(anchor.bottom + gap, margin), maxTop)}px`;
}

function moveSourceActionsFocus(event) {
  if (!["ArrowDown", "ArrowUp", "Home", "End"].includes(event.key)) return false;
  const buttons = sourceActionsFocusableButtons();
  if (!buttons.length) return false;
  event.preventDefault();
  const index = buttons.indexOf(document.activeElement);
  const targetIndex = event.key === "Home"
    ? 0
    : event.key === "End"
      ? buttons.length - 1
      : event.key === "ArrowDown"
        ? (index + 1 + buttons.length) % buttons.length
        : (index - 1 + buttons.length) % buttons.length;
  buttons[targetIndex].focus({ preventScroll: true });
  return true;
}

function moveTagActionsFocus(event) {
  if (!["ArrowDown", "ArrowUp", "Home", "End"].includes(event.key)) return false;
  const buttons = tagActionsFocusableButtons();
  if (!buttons.length) return false;
  event.preventDefault();
  const index = buttons.indexOf(document.activeElement);
  const targetIndex = event.key === "Home"
    ? 0
    : event.key === "End"
      ? buttons.length - 1
      : event.key === "ArrowDown"
        ? (index + 1 + buttons.length) % buttons.length
        : (index - 1 + buttons.length) % buttons.length;
  buttons[targetIndex].focus({ preventScroll: true });
  return true;
}

function closePersonalModelPopover(options = {}) {
  if (activeActionMenuDescriptor()?.kind !== "personalModel") return;
  closeActionMenu(options);
}

function togglePersonalModelPopover() {
  toggleActionMenu("personalModel");
}

async function openLibraryPersonalTraining(method, returnFocus = elements.personalModelButton) {
  const operation = personalModelOperationState();
  if (operation.busy) {
    toast(`${operation.summary}；完成或取消后再开始新任务`);
    return;
  }
  const tagIDs = libraryPersonalTrainingTagIDs();
  const selectedCount = state.selectedAssetIDs.size;
  const noun = state.mediaKind === "video" ? "视频" : "照片";
  state.training.mediaKind = state.mediaKind;
  await returnFromActionMenu({ restoreFocus: false });
  await openTrainingSetupDialog({
    method,
    tagIDs,
    requireExplicitTag: !tagIDs.length,
    scope: selectedCount ? "currentSelection" : "allSources",
    returnFocus,
    note: tagIDs.length
      ? `已从图库筛选带入 ${tagIDs.length} 个已确认标签；${selectedCount ? `只使用当前选中的 ${selectedCount} 项${noun}` : `使用全库已确认${noun}`}。`
      : "请选择要训练的标签；只会使用已确认样本。",
  });
}

async function generateGalleryPersonalSuggestions() {
  const operation = personalModelOperationState();
  if (operation.busy) {
    toast(`${operation.summary}；完成或取消后再开始新任务`);
    return;
  }
  const fullLibrary = state.librarySuggestions.snapshot?.personalMode === "fullLibrary";
  await returnFromActionMenu({ restoreFocus: false });
  if (fullLibrary) {
    await openReviewWorkspace();
    await submitLibrarySuggestions("personal");
    return;
  }
  await generateSampleSuggestions();
}

function createFilterChip() {
  const chip = document.createElement("span");
  chip.className = "filter-chip";
  const label = document.createElement("span");
  label.dataset.filterChipLabel = "true";
  const remove = document.createElement("button");
  remove.type = "button";
  remove.textContent = "×";
  chip.append(label, remove);
  return chip;
}

function syncFilterChip(chip, condition, tag) {
  chip.dataset.filterTagId = condition.tagID;
  const label = chip.querySelector(":scope > [data-filter-chip-label]");
  label.textContent = `${filterDecisionText(condition.decision)} · ${tag.displayName}`;
  const remove = chip.querySelector(":scope > button");
  remove.dataset.removeTagFilter = condition.tagID;
  remove.setAttribute("aria-label", `移除 ${tag.displayName} 条件`);
}

function renderFilterChips() {
  const filters = state.filterDraft || state.filters;
  const existingChips = new Map(
    [...elements.filterTagChips.querySelectorAll(":scope > [data-filter-tag-id]")]
      .map((chip) => [chip.dataset.filterTagId, chip])
  );
  const chips = [];
  for (const condition of filters.tagConditions) {
    const tag = tagByID(condition.tagID);
    if (!tag) continue;
    const chip = existingChips.get(condition.tagID) || createFilterChip();
    existingChips.delete(condition.tagID);
    syncFilterChip(chip, condition, tag);
    chips.push(chip);
  }
  reconcileStableChildren(elements.filterTagChips, chips);
  elements.tagMatchModeLabel.classList.toggle(
    "hidden",
    filters.tagConditions.filter((condition) => condition.decision !== "excluded").length < 2
  );
  renderFilterBadge();
}

function syncFilterControlsFromState() {
  const filters = state.filterDraft || state.filters;
  elements.mediaKindFilter.value = state.mediaKind;
  const selectedAvailabilities = new Set(filters.availabilities);
  for (const checkbox of elements.availabilityFilter.querySelectorAll('input[type="checkbox"]')) {
    checkbox.checked = selectedAvailabilities.has(checkbox.value);
  }
  const selectedMediaTypes = new Set(filters.mediaTypes);
  for (const checkbox of elements.mediaTypeFilter.querySelectorAll('input[type="checkbox"]')) {
    const mediaTypes = checkbox.dataset.mediaTypes.split(",");
    checkbox.checked = mediaTypes.every((mediaType) => selectedMediaTypes.has(mediaType));
    checkbox.closest("[data-filter-media-kind]")?.classList.toggle(
      "hidden",
      checkbox.closest("[data-filter-media-kind]")?.dataset.filterMediaKind !== state.mediaKind
    );
  }
  elements.tagPresenceFilter.value = filters.tagPresence;
  elements.tagMatchMode.value = filters.tagMatchMode;
  renderFilterChips();
  renderActiveFilterBar();
}

function updateFiltersFromControls() {
  const filters = state.filterDraft || cloneFilters(state.filters);
  filters.mediaKind = state.mediaKind;
  filters.availabilities = [...elements.availabilityFilter.querySelectorAll(
    'input[type="checkbox"]:checked'
  )].map((checkbox) => checkbox.value);
  filters.mediaTypes = [...new Set(
    [...elements.mediaTypeFilter.querySelectorAll(
      'input[type="checkbox"]:checked'
    )]
      .filter((checkbox) => checkbox.closest("[data-filter-media-kind]")
        ?.dataset.filterMediaKind === state.mediaKind)
      .flatMap((checkbox) => checkbox.dataset.mediaTypes.split(","))
  )];
  filters.tagPresence = elements.tagPresenceFilter.value;
  filters.tagMatchMode = elements.tagMatchMode.value;
  if (filters.tagPresence !== "any") {
    filters.tagConditions = [];
  }
  state.filterDraft = filters;
}

function setFilterLiveStatus(stateName, message) {
  elements.filterLiveStatus.dataset.state = stateName;
  elements.filterLiveStatus.textContent = message;
  elements.filterPopover.setAttribute("aria-busy", String(stateName === "loading"));
}

function cancelPendingFilterApply() {
  clearTimeout(state.filterApplyTimer);
  state.filterApplyTimer = null;
  state.filterApplyGeneration += 1;
}

function scheduleImmediateFilterLoad(focusTarget = document.activeElement) {
  clearTimeout(state.filterApplyTimer);
  const generation = ++state.filterApplyGeneration;
  const scheduledSignature = assetQuerySignature();
  setFilterLiveStatus("loading", "正在更新…");
  state.filterApplyTimer = setTimeout(async () => {
    state.filterApplyTimer = null;
    if (generation !== state.filterApplyGeneration
      || scheduledSignature !== assetQuerySignature()) {
      if (generation === state.filterApplyGeneration) {
        setFilterLiveStatus("idle", "范围已更新");
      }
      return;
    }
    try {
      await loadAssets({
        preserveSelection: true,
        preserveUnchangedGrid: true,
      });
      if (generation !== state.filterApplyGeneration) return;
      setFilterLiveStatus("ready", "已更新");
    } catch {
      if (generation !== state.filterApplyGeneration) return;
      setFilterLiveStatus("error", "更新失败，可重试");
    } finally {
      if (generation !== state.filterApplyGeneration
        || elements.filterPopover.classList.contains("hidden")
        || !focusTarget?.isConnected) return;
      if (!elements.filterPopover.contains(document.activeElement)) {
        focusTarget.focus({ preventScroll: true });
      }
    }
  }, 120);
}

function applyFilterControlsImmediately(focusTarget = document.activeElement) {
  updateFiltersFromControls();
  state.filters = cloneFilters(state.filterDraft);
  state.filters.mediaKind = state.mediaKind;
  state.filterDraft = cloneFilters(state.filters);
  renderFilterChips();
  renderActiveFilterBar();
  renderTagNavigation();
  scheduleImmediateFilterLoad(focusTarget);
}

async function clearLibrarySearch({ restoreFocus = true } = {}) {
  clearTimeout(state.searchTimer);
  state.searchTimer = null;
  state.searchText = "";
  elements.searchInput.value = "";
  elements.clearSearchButton.classList.add("hidden");
  await loadAssets({ preserveSelection: true, preserveUnchangedGrid: true });
  if (restoreFocus) elements.searchInput.focus({ preventScroll: true });
}

function cancelPendingSlimmingRecycleSearch() {
  clearTimeout(state.slimming.recycle.searchTimer);
  state.slimming.recycle.searchTimer = null;
}

async function clearSlimmingRecycleSearch({ restoreFocus = true } = {}) {
  cancelPendingSlimmingRecycleSearch();
  state.slimming.recycle.searchText = "";
  state.slimming.recycle.limit = 60;
  await loadSlimmingRecycle({ quiet: true });
  if (restoreFocus) elements.slimmingRecycleSearchInput.focus({ preventScroll: true });
}

function clearInlineSearchFromEscape(target) {
  const folderSearch = target?.closest?.("[data-folder-search-source-id]");
  if (folderSearch) {
    const sourceID = folderSearch.dataset.folderSearchSourceId;
    const search = state.folderNavigation.searches.get(sourceID);
    if (folderSearch.value || search?.query) {
      clearTimeout(state.folderNavigation.searchTimers.get(sourceID));
      state.folderNavigation.searchTimers.delete(sourceID);
      void searchFolders(sourceID, "");
      return true;
    }
  }
  if (target === elements.searchInput
    && (elements.searchInput.value || state.searchText)) {
    void clearLibrarySearch();
    return true;
  }
  if (target === elements.tagNavigationSearch && elements.tagNavigationSearch.value) {
    elements.tagNavigationSearch.value = "";
    renderTagNavigation();
    elements.tagNavigationSearch.focus({ preventScroll: true });
    return true;
  }
  if (target === elements.selectionTagSearch
    && (elements.selectionTagSearch.value || state.selectionTagSearchText)) {
    state.selectionTagSearchText = "";
    elements.selectionTagSearch.value = "";
    renderSelectionInspector();
    elements.selectionTagSearch.focus({ preventScroll: true });
    return true;
  }
  if (target === elements.inspectorTagSearch
    && (elements.inspectorTagSearch.value || state.inspectorTagSearchText)) {
    state.inspectorTagSearchText = "";
    elements.inspectorTagSearch.value = "";
    if (state.selectedDetail) renderInspector(state.selectedDetail);
    elements.inspectorTagSearch.focus({ preventScroll: true });
    return true;
  }
  if (target === elements.reviewTagSearch
    && (elements.reviewTagSearch.value || state.review.tagSearchText)) {
    state.review.tagSearchText = "";
    elements.reviewTagSearch.value = "";
    renderReviewDetail();
    elements.reviewTagSearch.focus({ preventScroll: true });
    return true;
  }
  if (target === elements.slimmingRecycleSearchInput
    && (elements.slimmingRecycleSearchInput.value || state.slimming.recycle.searchText)) {
    void clearSlimmingRecycleSearch();
    return true;
  }
  return false;
}

async function clearLibraryFilters({ tags = false, properties = false } = {}) {
  cancelPendingFilterApply();
  const filters = cloneFilters(state.filters);
  if (tags) {
    filters.tagConditions = [];
    filters.tagPresence = "any";
    filters.tagMatchMode = "all";
  }
  if (properties) {
    filters.availabilities = [];
    filters.mediaTypes = [];
  }
  filters.mediaKind = state.mediaKind;
  state.filters = filters;
  state.filterDraft = null;
  setFilterLiveStatus("idle", "更改立即生效");
  syncFilterControlsFromState();
  renderTagNavigation();
  await loadAssets({ preserveSelection: true, preserveUnchangedGrid: true });
  elements.filterButton.focus({ preventScroll: true });
}

async function clearAllLibraryConditions() {
  clearTimeout(state.searchTimer);
  state.searchTimer = null;
  cancelPendingFilterApply();
  state.searchText = "";
  elements.searchInput.value = "";
  elements.clearSearchButton.classList.add("hidden");
  state.filters = emptyFilters();
  state.filters.mediaKind = state.mediaKind;
  state.filterDraft = null;
  setFilterLiveStatus("idle", "更改立即生效");
  syncFilterControlsFromState();
  renderTagNavigation();
  await loadAssets({ preserveSelection: true, preserveUnchangedGrid: true });
  elements.filterButton.focus({ preventScroll: true });
}

function appendAdvancedFilterQuery(query, filters = state.filters) {
  const acceptedTagIDs = [];
  const rejectedTagIDs = [];
  const excludedTagIDs = [];
  for (const condition of filters.tagConditions) {
    if (condition.decision === "accepted") acceptedTagIDs.push(condition.tagID);
    if (condition.decision === "rejected") rejectedTagIDs.push(condition.tagID);
    if (condition.decision === "excluded") excludedTagIDs.push(condition.tagID);
  }
  if (acceptedTagIDs.length) query.set("acceptedTagIDs", acceptedTagIDs.join(","));
  if (rejectedTagIDs.length) query.set("rejectedTagIDs", rejectedTagIDs.join(","));
  if (excludedTagIDs.length) query.set("excludedTagIDs", excludedTagIDs.join(","));
  if (acceptedTagIDs.length + rejectedTagIDs.length > 1) {
    query.set("tagMatchMode", filters.tagMatchMode);
  }
  if (filters.availabilities.length) {
    query.set("availabilities", filters.availabilities.join(","));
  }
  if (filters.mediaKind) query.set("mediaKinds", filters.mediaKind);
  if (filters.mediaTypes.length) query.set("mediaTypes", filters.mediaTypes.join(","));
  if (filters.tagPresence !== "any") query.set("tagPresence", filters.tagPresence);
}

function assetCardFingerprint(asset) {
  return JSON.stringify([
    asset.id,
    asset.sourceID,
    asset.sourceName,
    asset.fileName,
    asset.relativePath,
    asset.mediaKind,
    asset.mediaType,
    asset.availability,
    asset.contentRevision,
    asset.acceptedTagCount,
    asset.rejectedTagCount,
    asset.mediaCreatedAtMs,
    asset.mediaModifiedAtMs,
    asset.width,
    asset.height,
    asset.durationMs,
    asset.fingerprintSizeBytes,
    asset.favorite?.isFavorite ?? null,
    asset.favorite?.photosObservedValue ?? null,
    asset.favorite?.syncStatus ?? null,
    asset.favorite?.lastErrorCode ?? null,
  ]);
}

function assetPageFingerprint(items, nextCursor) {
  return JSON.stringify([
    nextCursor || null,
    items.map(assetCardFingerprint),
  ]);
}

function assetPageStructureMatches(leftItems, leftCursor, rightItems, rightCursor) {
  return (leftCursor || null) === (rightCursor || null)
    && leftItems.length === rightItems.length
    && leftItems.every((asset, index) => asset.id === rightItems[index]?.id);
}

function renderedAssetGridMatches(items) {
  const cards = [...elements.assetGrid.querySelectorAll(":scope > .asset-card")];
  return cards.length === items.length
    && cards.every((card, index) => card.dataset.assetId === items[index]?.id);
}

function assetQuerySnapshot() {
  return {
    workspaceGeneration: state.workspaceGeneration,
    selectedSourceID: state.selectedSourceID,
    libraryScope: state.libraryScope,
    worldMapGalleryScope: cloneWorldMapGalleryScope(state.worldMapGalleryScope),
    folderScope: cloneFolderScope(state.folderScope),
    searchText: state.searchText,
    sort: state.sort,
    filters: cloneFilters(state.filters),
  };
}

function appendWorldMapSelectionQuery(query, scope) {
  const selection = scope?.selectionQuery;
  if (!selection) return;
  query.set("worldMapCellDegrees", String(selection.cellDegrees));
  query.set("worldMapLongitudeBucket", String(selection.longitudeBucket));
  query.set("worldMapLatitudeBucket", String(selection.latitudeBucket));
  query.set("worldMapMaximumAssets", String(selection.maximumAssets || 36));
  if (selection.bounds) {
    query.set("worldMapWest", String(selection.bounds.west));
    query.set("worldMapSouth", String(selection.bounds.south));
    query.set("worldMapEast", String(selection.bounds.east));
    query.set("worldMapNorth", String(selection.bounds.north));
  }
}

function assetQuerySignature(snapshot = assetQuerySnapshot()) {
  return JSON.stringify(snapshot);
}

function assetPageQuery({
  cursor = null,
  limit = 72,
  snapshot = assetQuerySnapshot(),
} = {}) {
  const query = new URLSearchParams({
    sort: snapshot.sort,
    limit: String(limit),
  });
  if (snapshot.selectedSourceID) query.set("sourceIDs", snapshot.selectedSourceID);
  if (snapshot.folderScope) {
    query.set("folderSourceID", snapshot.folderScope.sourceID);
    query.set("folderRelativePath", snapshot.folderScope.relativePath);
  }
  if (snapshot.libraryScope === "favorites") query.set("favorite", "favorited");
  if (snapshot.libraryScope === "worldMapGallery") {
    appendWorldMapSelectionQuery(query, snapshot.worldMapGalleryScope);
  }
  if (snapshot.searchText) query.set("q", snapshot.searchText);
  if (cursor) query.set("cursor", cursor);
  appendAdvancedFilterQuery(query, snapshot.filters);
  return query;
}

async function fetchLoadedAssetWindow(targetCount, snapshot) {
  const items = [];
  const seenCursors = new Set();
  let nextCursor = null;

  do {
    const remaining = Math.max(1, targetCount - items.length);
    const query = assetPageQuery({
      cursor: nextCursor,
      limit: Math.min(200, remaining),
      snapshot,
    });
    const page = await api(`/v1/assets?${query}`);
    items.push(...page.items);
    nextCursor = page.nextCursor || null;
    if (!nextCursor || seenCursors.has(nextCursor)) break;
    seenCursors.add(nextCursor);
  } while (items.length < targetCount);

  return { items, nextCursor };
}

function mergeQueuedAssetLoadOptions(existing, incoming) {
  if (!existing) return incoming;
  if (!incoming.append) return incoming;
  if (!existing.append) return existing;
  return incoming;
}

async function loadAssets(options = {}) {
  const {
    append = false,
    preserveSelection = false,
    preserveUnchangedGrid = false,
    preserveLoadedWindow = false,
    targetLoadedCount = null,
  } = options;
  const normalizedOptions = {
    append,
    preserveSelection,
    preserveUnchangedGrid,
    preserveLoadedWindow,
    targetLoadedCount,
  };
  if (state.loadingAssets) {
    state.queuedAssetLoadOptions = mergeQueuedAssetLoadOptions(
      state.queuedAssetLoadOptions,
      normalizedOptions
    );
    do {
      await state.assetLoadPromise;
    } while (state.loadingAssets && state.assetLoadPromise);
    if (state.queuedAssetLoadOptions) {
      const queuedOptions = state.queuedAssetLoadOptions;
      state.queuedAssetLoadOptions = null;
      return loadAssets(queuedOptions);
    }
    return false;
  }
  const querySnapshot = assetQuerySnapshot();
  const requestSignature = assetQuerySignature(querySnapshot);
  const existingAssets = state.assets;
  const existingCursor = state.nextCursor;
  let finishAssetLoad;
  state.assetLoadPromise = new Promise((resolve) => {
    finishAssetLoad = resolve;
  });
  const requestedTargetCount = Number(targetLoadedCount);
  const loadedTargetCount = Number.isFinite(requestedTargetCount) && requestedTargetCount > 0
    ? Math.min(GALLERY_HISTORY_LOADED_LIMIT, Math.floor(requestedTargetCount))
    : (preserveLoadedWindow ? Math.max(72, state.assets.length) : 72);
  state.loadingAssets = true;
  elements.loadMoreButton.disabled = true;
  let shouldRender = !preserveUnchangedGrid;
  let changedAssetIDs = null;
  let appendedAssets = null;
  if (!append) {
    if (!preserveSelection) {
      state.selectedAssetIDs.clear();
      state.selectionAnchorID = null;
    }
    if (!preserveUnchangedGrid) {
      state.nextCursor = null;
      state.assets = [];
      renderAssets();
    }
  }

  try {
    const page = append
      ? await api(`/v1/assets?${assetPageQuery({
        cursor: existingCursor,
        snapshot: querySnapshot,
      })}`)
      : await fetchLoadedAssetWindow(loadedTargetCount, querySnapshot);
    if (requestSignature !== assetQuerySignature()) {
      shouldRender = false;
      return false;
    }
    const nextAssets = append ? existingAssets.concat(page.items) : page.items;
    const nextCursor = page.nextCursor || null;
    shouldRender = shouldRender
      || state.assetRenderedQuerySignature !== requestSignature
      || assetPageFingerprint(state.assets, state.nextCursor)
        !== assetPageFingerprint(nextAssets, nextCursor);
    const canRenderChangedCardsOnly = !append
      && preserveUnchangedGrid
      && state.assetRenderedQuerySignature === requestSignature
      && renderedAssetGridMatches(existingAssets)
      && assetPageStructureMatches(
        existingAssets,
        existingCursor,
        nextAssets,
        nextCursor
      );
    if (canRenderChangedCardsOnly) {
      changedAssetIDs = nextAssets
        .filter((asset, index) => (
          assetCardFingerprint(asset) !== assetCardFingerprint(existingAssets[index])
        ))
        .map((asset) => asset.id);
    }
    const existingAssetIDs = append
      ? new Set(existingAssets.map((asset) => asset.id))
      : null;
    const appendedAssetIDs = append ? new Set() : null;
    const canAppendCardsOnly = append
      && state.assetRenderedQuerySignature === requestSignature
      && renderedAssetGridMatches(existingAssets)
      && page.items.every((asset) => {
        if (!asset.id
          || existingAssetIDs.has(asset.id)
          || appendedAssetIDs.has(asset.id)) return false;
        appendedAssetIDs.add(asset.id);
        return true;
      });
    if (canAppendCardsOnly) appendedAssets = page.items;
    state.assets = nextAssets;
    state.nextCursor = nextCursor;
    const visibleIDs = new Set(state.assets.map((asset) => asset.id));
    state.selectedAssetIDs = new Set(
      [...state.selectedAssetIDs].filter((assetID) => visibleIDs.has(assetID))
    );
    if (state.selectionAnchorID && !visibleIDs.has(state.selectionAnchorID)) {
      state.selectionAnchorID = null;
    }
    if (state.selectedAssetID && !visibleIDs.has(state.selectedAssetID)) {
      state.selectedAssetID = null;
      state.selectedDetail = null;
      elements.inspector.classList.remove("open");
    }
  } finally {
    state.loadingAssets = false;
    elements.loadMoreButton.disabled = false;
    if (shouldRender) {
      if (appendedAssets !== null) {
        renderAssetCollectionSummary();
        appendAssetCards(appendedAssets);
        renderSelectionBar({ updateInspector: false });
      } else if (changedAssetIDs !== null) {
        renderAssetCardsForIDs(changedAssetIDs);
        updateInspectorNavigation();
        renderFavoriteControls();
        renderSelectionBar({ updateInspector: false });
      } else {
        renderAssets();
        renderSelectionBar();
      }
      state.assetRenderedQuerySignature = requestSignature;
    }
    finishAssetLoad();
    state.assetLoadPromise = null;
  }
  captureMediaSession();
  if (append) requestAnimationFrame(autoPaginateIfNeeded);
  return shouldRender;
}

async function loadInspector(assetID, {
  reveal = false,
  focusInspector = false,
  preserveExisting = false,
  quiet = false,
  throwOnError = false,
} = {}) {
  const workspaceGeneration = state.workspaceGeneration;
  const requestGeneration = ++state.inspectorRequestGeneration;
  const keepExisting = preserveExisting
    && state.selectedAssetID === assetID
    && Boolean(state.selectedDetail);
  if (reveal) {
    state.inspectorDismissed = false;
    state.inspectorDismissedByUser = false;
  }
  state.selectedAssetID = assetID;
  scheduleWorkspaceHistoryCheckpoint();
  if (!keepExisting) {
    state.selectedDetail = null;
    renderAssetSelectionState();
    renderInspectorSurface();
    elements.previewLoading.classList.remove("hidden");
  }
  try {
    const detail = await api(`/v1/assets/${assetID}`);
    if (
      workspaceGeneration === state.workspaceGeneration
      && requestGeneration === state.inspectorRequestGeneration
      && state.selectedAssetID === assetID
      && !state.selectionMode
    ) {
      renderInspector(detail);
      if (focusInspector && globalThis.matchMedia("(max-width: 980px)").matches) {
        requestAnimationFrame(() => {
          elements.closeInspectorButton.focus({ preventScroll: true });
        });
      }
      return true;
    }
    return false;
  } catch (error) {
    const isCurrentRequest = workspaceGeneration === state.workspaceGeneration
      && requestGeneration === state.inspectorRequestGeneration
      && state.selectedAssetID === assetID;
    if (!quiet && isCurrentRequest) {
      toast(error.message || `无法载入${currentMediaNoun()}详情`);
    }
    if (throwOnError && isCurrentRequest) throw error;
    return false;
  }
}

async function mutateTag(tagID, action) {
  if (!state.selectedAssetID || !state.online || state.tagMutating) return false;
  const generation = state.workspaceGeneration;
  const assetID = state.selectedAssetID;
  state.tagMutating = true;
  syncWriteActionControls();
  try {
    const result = await api("/v1/tag-decisions/batch", {
      method: "POST",
      body: JSON.stringify({
        operationID: crypto.randomUUID(),
        tagID,
        assetIDs: [assetID],
        action,
      }),
    });
    if (generation !== state.workspaceGeneration) return false;
    try {
      const shouldRefreshDetail = state.selectedAssetID === assetID && !state.selectionMode;
      await Promise.all([
        loadAssets({
          preserveSelection: true,
          preserveUnchangedGrid: true,
          preserveLoadedWindow: true,
        }),
        shouldRefreshDetail
          ? loadInspector(assetID, {
            preserveExisting: true,
            quiet: true,
            throwOnError: true,
          })
          : null,
      ]);
      if (generation !== state.workspaceGeneration) return false;
      undoToast(result.replayed ? "标签操作已恢复" : "标签已更新", result.undoID);
    } catch {
      if (generation !== state.workspaceGeneration) return false;
      void refreshWorkspace({ quiet: true, kinds: ["assetsChanged"] });
      undoToast("标签已更新，界面同步暂时失败，正在重试", result.undoID);
    }
    return true;
  } catch (error) {
    if (generation === state.workspaceGeneration) {
      toast(error.message || "标签更新失败");
    }
    return false;
  } finally {
    if (generation === state.workspaceGeneration) {
      state.tagMutating = false;
      syncWriteActionControls();
      if (state.selectedDetail?.assetID === assetID && !state.selectionMode) {
        renderInspector(state.selectedDetail);
      }
    }
  }
}

function favoriteStateForAssetID(assetID) {
  if (!assetID) return null;
  if (state.selectedDetail?.assetID === assetID && state.selectedDetail.favorite) {
    return state.selectedDetail.favorite;
  }
  if (state.lightboxFavoriteStates.has(assetID)) {
    return state.lightboxFavoriteStates.get(assetID);
  }
  return state.assets.find((asset) => asset.id === assetID)?.favorite
    || state.review.items.find((item) => item.assetID === assetID)?.favorite
    || state.worldMap.selection?.assets?.find((asset) => asset.id === assetID)?.favorite
    || state.slimming.members.find((member) => member.id === assetID)?.favorite
    || state.slimming.recycle.entries.find((entry) => entry.assetID === assetID)?.favorite
    || null;
}

function renderLightboxFavorite() {
  const assetID = state.lightboxAssetID;
  const open = !elements.lightbox.classList.contains("hidden");
  const supported = supportsFavorites();
  elements.lightboxFavoriteButton.classList.toggle(
    "hidden",
    !open || !supported || !assetID
  );
  if (!open || !supported || !assetID) return;

  const favorite = favoriteStateForAssetID(assetID);
  const isFavorite = favorite?.isFavorite === true;
  const loading = state.lightboxFavoriteLoadingAssetID === assetID && !favorite;
  elements.lightboxFavoriteButton.disabled = !state.online
    || state.favoriteMutating
    || state.favoriteRetrying
    || loading
    || !favorite;
  elements.lightboxFavoriteButton.dataset.favorite = String(isFavorite);
  elements.lightboxFavoriteButtonIcon.textContent = isFavorite ? "♥" : "♡";
  const syncText = favoriteSyncText(favorite);
  const actionText = isFavorite ? "取消红心" : "加入红心";
  const title = loading
    ? "正在读取红心状态"
    : (syncText ? `${actionText}；${syncText}` : actionText);
  elements.lightboxFavoriteButton.title = title;
  elements.lightboxFavoriteButton.setAttribute("aria-label", title);
  const syncStatus = favorite?.syncStatus || "";
  const showBadge = syncStatus === "pending" || syncStatus === "failed";
  elements.lightboxFavoriteSyncBadge.classList.toggle("hidden", !showBadge);
  elements.lightboxFavoriteSyncBadge.dataset.syncStatus = syncStatus;
  elements.lightboxFavoriteSyncBadge.textContent = syncStatus === "failed" ? "!" : "";
}

async function loadLightboxFavorite(assetID) {
  if (!assetID || !supportsFavorites() || favoriteStateForAssetID(assetID)) return;
  if (state.lightboxFavoriteLoadingAssetID === assetID) return;
  const workspaceGeneration = state.workspaceGeneration;
  const requestGeneration = ++state.lightboxFavoriteRequestGeneration;
  let failed = false;
  state.lightboxFavoriteLoadingAssetID = assetID;
  renderLightboxFavorite();
  try {
    const detail = await api(`/v1/assets/${assetID}`);
    if (workspaceGeneration !== state.workspaceGeneration
      || requestGeneration !== state.lightboxFavoriteRequestGeneration
      || state.lightboxAssetID !== assetID) return;
    if (detail.favorite) {
      state.lightboxFavoriteStates.set(assetID, detail.favorite);
    }
  } catch {
    failed = workspaceGeneration === state.workspaceGeneration
      && requestGeneration === state.lightboxFavoriteRequestGeneration
      && state.lightboxAssetID === assetID;
  } finally {
    if (requestGeneration === state.lightboxFavoriteRequestGeneration) {
      state.lightboxFavoriteLoadingAssetID = null;
      renderLightboxFavorite();
      if (failed) {
        elements.lightboxFavoriteButton.title = "无法读取红心状态";
        elements.lightboxFavoriteButton.setAttribute("aria-label", "无法读取红心状态");
      }
    }
  }
}

async function toggleLightboxFavorite() {
  const assetID = state.lightboxAssetID;
  const favorite = favoriteStateForAssetID(assetID);
  if (!assetID || !favorite || state.favoriteMutating) return;
  const restoreFavoriteFocus = document.activeElement === elements.lightboxFavoriteButton;
  await applyFavoriteMutation([assetID], favorite.isFavorite !== true);
  if (elements.lightbox.classList.contains("hidden")) return;

  if (!lightboxItems().some((item) => item.id === state.lightboxAssetID)) {
    const fallbackID = state.selectedAssetID
      && lightboxItems().some((item) => item.id === state.selectedAssetID)
      ? state.selectedAssetID
      : lightboxItems()[0]?.id;
    if (!fallbackID) {
      closeLightbox();
      return;
    }
    state.lightboxAssetID = fallbackID;
    state.lightboxOriginalAssetID = null;
    state.lightboxOriginalLoading = false;
  }
  renderLightbox();
  if (restoreFavoriteFocus && !elements.lightboxFavoriteButton.disabled) {
    restoreOverlayFocus(elements.lightboxFavoriteButton);
  }
}

function visibleFavoriteSyncCounts() {
  return state.assets.reduce((counts, asset) => {
    if (asset.favorite?.syncStatus === "pending") counts.pending += 1;
    if (asset.favorite?.syncStatus === "failed") counts.failed += 1;
    return counts;
  }, { pending: 0, failed: 0 });
}

function renderFavoriteControls() {
  const supported = supportsFavorites();
  for (const card of elements.assetGrid.querySelectorAll(":scope > .asset-card")) {
    const asset = state.assets.find((item) => item.id === card.dataset.assetId);
    if (asset) syncAssetCardFavoriteButton(card, asset);
  }
  for (const card of elements.reviewGrid.querySelectorAll(":scope > .review-card")) {
    const item = state.review.items.find(
      (candidate) => candidate.assetID === card.dataset.reviewAssetId
    );
    if (item) syncReviewCardFavoriteButton(card, item);
  }
  for (const card of elements.worldMapPhotoStrip.querySelectorAll(
    ":scope > .world-map-photo-card"
  )) {
    const asset = state.worldMap.selection?.assets?.find(
      (candidate) => candidate.id === card.dataset.worldMapCardAssetId
    );
    if (asset) syncWorldMapPhotoFavoriteButton(card, asset);
  }
  for (const card of elements.slimmingMemberGrid.querySelectorAll(
    ":scope > .slimming-member-card"
  )) {
    const member = state.slimming.members.find(
      (candidate) => candidate.id === card.dataset.slimmingMemberId
    );
    if (member) syncSlimmingMemberFavoriteButton(card, member);
  }
  for (const card of elements.slimmingRecycleList.querySelectorAll(
    ".slimming-recycle-thumbnail-card"
  )) {
    const entry = state.slimming.recycle.entries.find(
      (candidate) => candidate.id === card.dataset.slimmingRecycleThumbnailEntryId
    );
    if (entry) syncSlimmingRecycleFavoriteButton(card, entry);
  }
  syncSlimmingRecycleGridTabStops();
  const selectedCount = state.selectedAssetIDs.size;
  elements.selectionFavoriteToolbarActions.classList.toggle(
    "hidden",
    !supported || selectedCount === 0
  );
  const batchDisabled = !supported
    || !state.online
    || state.favoriteMutating
    || selectedCount === 0;
  for (const button of [
    elements.toolbarFavoriteSelectedButton,
    elements.toolbarUnfavoriteSelectedButton,
    elements.favoriteSelectedButton,
    elements.unfavoriteSelectedButton,
    elements.selectionInspectorFavoriteButton,
    elements.selectionInspectorUnfavoriteButton,
  ]) {
    button.classList.toggle("hidden", !supported);
    button.disabled = batchDisabled;
  }
  requestAnimationFrame(syncSelectionFavoriteToolbarPresentation);

  const detail = state.selectedDetail;
  const favorite = detail?.favorite || null;
  const isFavorite = favorite?.isFavorite === true;
  for (const button of [
    elements.inspectorFavoriteButton,
    elements.inspectorUnfavoriteButton,
  ]) {
    button.classList.toggle("hidden", !supported);
    button.disabled = !supported
      || !state.online
      || state.favoriteMutating
      || !detail;
  }
  elements.inspectorFavoriteButton.dataset.current = String(isFavorite);
  elements.inspectorUnfavoriteButton.dataset.current = String(!isFavorite);
  elements.inspectorFavoriteButtonIcon.textContent = "♥";
  elements.inspectorFavoriteButtonLabel.textContent = "加入红心";
  const syncText = favoriteSyncText(favorite);
  elements.inspectorFavoriteButton.title = syncText
    ? `加入红心；${syncText}`
    : "加入红心";
  elements.inspectorFavoriteButton.setAttribute(
    "aria-label",
    elements.inspectorFavoriteButton.title
  );
  elements.inspectorUnfavoriteButton.title = syncText
    ? `取消红心；${syncText}`
    : "取消红心";
  elements.inspectorUnfavoriteButton.setAttribute(
    "aria-label",
    elements.inspectorUnfavoriteButton.title
  );

  const syncCounts = visibleFavoriteSyncCounts();
  const retryCount = syncCounts.pending + syncCounts.failed;
  elements.retryFavoriteSyncButton.classList.toggle(
    "hidden",
    !supported || retryCount === 0
  );
  elements.retryFavoriteSyncButton.disabled = !supported
    || !state.online
    || state.favoriteMutating
    || state.favoriteRetrying
    || retryCount === 0;
  elements.retryFavoriteSyncCount.textContent = String(retryCount);
  elements.retryFavoriteSyncButton.title = `重试红心同步：待同步 ${syncCounts.pending} 项，失败 ${syncCounts.failed} 项。不会弹出照片权限框。`;
  renderReviewInspectorActions();
  renderLightboxFavorite();
}

async function retryFavoriteSync() {
  const syncCounts = visibleFavoriteSyncCounts();
  if (!supportsFavorites()
    || !state.online
    || state.favoriteMutating
    || state.favoriteRetrying
    || syncCounts.pending + syncCounts.failed === 0) return;
  const generation = state.workspaceGeneration;
  state.favoriteRetrying = true;
  renderFavoriteControls();
  try {
    const result = await api("/v1/favorites/retry", {
      method: "POST",
      body: JSON.stringify({ operationID: crypto.randomUUID() }),
    });
    if (generation !== state.workspaceGeneration) return;
    await refreshWorkspace({ quiet: true, kinds: ["assetsChanged"] });
    if (generation !== state.workspaceGeneration) return;
    if (result.pendingCount || result.failedCount) {
      toast(`仍有 ${result.pendingCount} 项待同步、${result.failedCount} 项失败`);
    } else {
      toast("Photos 红心同步已完成");
    }
  } catch (error) {
    if (generation === state.workspaceGeneration) {
      toast(error.message || "重试 Photos 红心同步失败");
    }
  } finally {
    if (generation === state.workspaceGeneration) {
      state.favoriteRetrying = false;
      renderFavoriteControls();
    }
  }
}

function reconcileLibrarySelectionAfterFavoriteRemoval(
  previousIDs,
  removedAssetIDs,
  { primaryAssetID = state.selectedAssetID, anchorAssetID = state.selectionAnchorID } = {}
) {
  const primaryWasRemoved = Boolean(
    primaryAssetID && removedAssetIDs.has(primaryAssetID)
  );
  const anchorWasRemoved = Boolean(
    anchorAssetID && removedAssetIDs.has(anchorAssetID)
  );
  if (!primaryWasRemoved && !anchorWasRemoved) return;

  const remainingIDs = state.assets.map((asset) => asset.id);
  const remainingSelectedIDs = remainingIDs.filter((assetID) => (
    state.selectedAssetIDs.has(assetID)
  ));
  if (primaryWasRemoved
    && (!state.selectedAssetID || removedAssetIDs.has(state.selectedAssetID))) {
    const replacementCandidates = remainingSelectedIDs.length
      ? remainingSelectedIDs
      : remainingIDs;
    const replacementID = replacementPreviewAssetID(
      previousIDs,
      replacementCandidates,
      primaryAssetID
    ) || replacementCandidates[0] || null;
    state.selectedAssetID = replacementID;
    state.selectedDetail = null;
    if (state.selectionMode && !remainingSelectedIDs.length && replacementID) {
      state.selectedAssetIDs = new Set([replacementID]);
    }
    state.selectionPrimaryDetail = null;
    state.selectionPrimaryLoadingAssetID = null;
    state.selectionPrimaryRequestGeneration += 1;
  }
  if (state.selectionMode && ((anchorWasRemoved
      && (!state.selectionAnchorID || removedAssetIDs.has(state.selectionAnchorID)))
    || (state.selectionAnchorID && !state.selectedAssetIDs.has(state.selectionAnchorID)))) {
    state.selectionAnchorID = state.selectedAssetID
      && state.selectedAssetIDs.has(state.selectedAssetID)
      ? state.selectedAssetID
      : ([...state.selectedAssetIDs][0] || null);
  } else if (anchorWasRemoved
    && (!state.selectionAnchorID || removedAssetIDs.has(state.selectionAnchorID))) {
    state.selectionAnchorID = null;
  }
}

function reconcileLibraryLightboxAfterFavoriteRemoval(previousIDs, removedAssetIDs) {
  const previewAssetID = state.lightboxAssetID;
  if (!previewAssetID
    || !removedAssetIDs.has(previewAssetID)
    || state.lightboxContext !== "library"
    || elements.lightbox.classList.contains("hidden")) return false;

  const remainingIDs = state.assets.map((asset) => asset.id);
  const replacementID = replacementPreviewAssetID(
    previousIDs,
    remainingIDs,
    previewAssetID
  );
  if (!replacementID) {
    closeLightbox();
    return true;
  }

  if (state.cloudPreview.assetID === previewAssetID
    && state.cloudPreview.status !== "hidden") resetCloudPreviewRecovery();
  state.lightboxAssetID = replacementID;
  state.lightboxOriginalAssetID = null;
  state.lightboxOriginalLoading = false;
  const replacementCard = elements.assetGrid.querySelector(
    `[data-asset-id="${CSS.escape(replacementID)}"]`
  );
  state.lightboxReturnFocus = assetCardMainButton(replacementCard)
    || state.lightboxReturnFocus;
  return true;
}

async function applyFavoriteMutation(assetIDs, isFavorite) {
  const uniqueIDs = [...new Set(assetIDs)].filter(Boolean);
  if (!supportsFavorites() || !state.online || state.favoriteMutating || !uniqueIDs.length) return;
  const generation = state.workspaceGeneration;
  const previousAssets = state.assets;
  const previousAssetIDs = previousAssets.map((asset) => asset.id);
  const favoriteRemovalSelectionContext = {
    primaryAssetID: state.selectedAssetID,
    anchorAssetID: state.selectionAnchorID,
  };
  state.favoriteMutating = true;
  renderFavoriteControls();
  syncWriteActionControls();
  try {
    const result = await api("/v1/favorites", {
      method: "POST",
      body: JSON.stringify({
        operationID: crypto.randomUUID(),
        assetIDs: uniqueIDs,
        isFavorite,
      }),
    });
    if (generation !== state.workspaceGeneration) return;
    const statesByID = new Map((result.states || []).map((item) => [item.assetID, item]));
    for (const [assetID, favorite] of statesByID) {
      state.lightboxFavoriteStates.set(assetID, favorite);
    }
    state.assets = state.assets.map((asset) => (
      statesByID.has(asset.id) ? { ...asset, favorite: statesByID.get(asset.id) } : asset
    ));
    state.review.items = state.review.items.map((item) => (
      statesByID.has(item.assetID)
        ? { ...item, favorite: statesByID.get(item.assetID) }
        : item
    ));
    if (state.worldMap.selection) {
      state.worldMap.selection = {
        ...state.worldMap.selection,
        assets: (state.worldMap.selection.assets || []).map((asset) => (
          statesByID.has(asset.id)
            ? { ...asset, favorite: statesByID.get(asset.id) }
            : asset
        )),
      };
    }
    state.slimming.members = state.slimming.members.map((member) => (
      statesByID.has(member.id)
        ? { ...member, favorite: statesByID.get(member.id) }
        : member
    ));
    state.slimming.recycle.entries = state.slimming.recycle.entries.map((entry) => (
      statesByID.has(entry.assetID)
        ? { ...entry, favorite: statesByID.get(entry.assetID) }
        : entry
    ));
    if (state.selectedDetail && statesByID.has(state.selectedDetail.assetID)) {
      state.selectedDetail = {
        ...state.selectedDetail,
        favorite: statesByID.get(state.selectedDetail.assetID),
      };
    }

    let favoriteRemovalReconciledLightbox = false;
    let favoriteRemovalContinuationPageFailed = false;
    if (state.libraryScope === "favorites" && !isFavorite) {
      const removed = new Set(uniqueIDs);
      state.assets = state.assets.filter((asset) => !removed.has(asset.id));
      state.selectedAssetIDs = new Set(
        [...state.selectedAssetIDs].filter((assetID) => !removed.has(assetID))
      );
      if (state.nextCursor && removed.has(previousAssetIDs.at(-1))) {
        try {
          await loadAssets({ append: true, preserveSelection: true });
        } catch {
          favoriteRemovalContinuationPageFailed = true;
        }
        if (generation !== state.workspaceGeneration) return;
      }
      const continuationAssetIDs = continuedAssetIDs(
        previousAssetIDs,
        state.assets.map((asset) => asset.id)
      );
      reconcileLibrarySelectionAfterFavoriteRemoval(
        continuationAssetIDs,
        removed,
        favoriteRemovalSelectionContext
      );
      favoriteRemovalReconciledLightbox = reconcileLibraryLightboxAfterFavoriteRemoval(
        continuationAssetIDs,
        removed
      );
    }

    const nextSelectedAssetID = state.selectedAssetID;

    if (state.libraryScope === "favorites" && !isFavorite) {
      renderAssets();
    } else {
      renderAssetCardsForIDs(statesByID.keys());
    }
    renderSelectionBar({ updateInspector: false });
    renderFavoriteControls();
    renderGalleryRemovalControls();
    if (state.slimming.view === "analysis" && state.slimming.members.length) {
      renderSlimmingMemberSelection();
    }
    if (["library", "slimming"].includes(state.lightboxContext)
      && !elements.lightbox.classList.contains("hidden")) {
      renderLightbox();
      if (favoriteRemovalReconciledLightbox) checkpointActiveWorkspaceHistory();
    }
    if (!state.selectionMode && nextSelectedAssetID && !state.selectedDetail) {
      await loadInspector(nextSelectedAssetID, { reveal: true, quiet: true });
    } else if (!nextSelectedAssetID) {
      renderInspectorSurface();
    } else if (state.selectedDetail) {
      renderInspector(state.selectedDetail);
    }
    if (state.selectionMode && favoriteRemovalReconciledLightbox) {
      renderAssetSelectionState();
      renderSelectionMutation();
      scheduleSelectionAggregate();
    }
    const syncParts = [
      result.pendingCount ? `${result.pendingCount} 项等待 Photos 同步` : "",
      result.failedCount ? `${result.failedCount} 项 Photos 同步失败` : "",
      favoriteRemovalContinuationPageFailed ? "下一页载入失败，可刷新重试" : "",
    ].filter(Boolean);
    toast(
      `${isFavorite ? "已加入" : "已取消"}红心 ${result.changedCount} 项`
        + (syncParts.length ? `；${syncParts.join("，")}` : "")
    );
  } catch (error) {
    if (generation === state.workspaceGeneration) {
      toast(error.message || "红心操作失败");
    }
  } finally {
    if (generation === state.workspaceGeneration) {
      state.favoriteMutating = false;
      renderFavoriteControls();
      syncWriteActionControls();
    }
  }
}

function favoriteMutationFocusCandidates(preferred, isFavorite) {
  const equivalents = isFavorite
    ? [
      elements.toolbarFavoriteSelectedButton,
      elements.favoriteSelectedButton,
      elements.selectionInspectorFavoriteButton,
    ]
    : [
      elements.toolbarUnfavoriteSelectedButton,
      elements.unfavoriteSelectedButton,
      elements.selectionInspectorUnfavoriteButton,
    ];
  return [preferred, ...equivalents].filter(
    (button, index, buttons) => button && buttons.indexOf(button) === index
  );
}

async function applyFavoriteMutationFromControl(button, assetIDs, isFavorite) {
  await applyFavoriteMutation(assetIDs, isFavorite);
  syncSelectionFavoriteToolbarPresentation();
  const focusTarget = favoriteMutationFocusCandidates(button, isFavorite).find(
    (candidate) => candidate.isConnected
      && !candidate.disabled
      && candidate.getClientRects().length > 0
  );
  focusTarget?.focus({ preventScroll: true });
}

async function toggleAssetCardFavorite(button) {
  const assetID = button?.dataset.mediaFavoriteAssetId
    || button?.closest(".asset-card")?.dataset.assetId;
  const assetIndex = state.assets.findIndex((asset) => asset.id === assetID);
  const favorite = favoriteStateForAssetID(assetID);
  if (!assetID || assetIndex < 0 || state.favoriteMutating) return;
  const scrollTop = elements.libraryScroll.scrollTop;
  await applyFavoriteMutation([assetID], favorite?.isFavorite !== true);
  elements.libraryScroll.scrollTop = scrollTop;

  if (button.isConnected) {
    button.focus({ preventScroll: true });
    return;
  }
  const fallback = state.assets[Math.min(assetIndex, Math.max(0, state.assets.length - 1))];
  const fallbackCard = fallback
    ? elements.assetGrid.querySelector(`[data-asset-id="${CSS.escape(fallback.id)}"]`)
    : null;
  assetCardMainButton(fallbackCard)?.focus({ preventScroll: true });
}

function setSelectionMode(enabled, { seedCurrent = false } = {}) {
  state.gridDoubleClickSelectionSnapshot = null;
  const enteringSelectionMode = enabled && !state.selectionMode;
  if (enabled && seedCurrent && state.selectedAssetID
    && state.assets.some((asset) => asset.id === state.selectedAssetID)) {
    state.selectedAssetIDs.add(state.selectedAssetID);
    state.selectionAnchorID = state.selectedAssetID;
  }
  state.selectionMode = enabled;
  if (enabled) {
    state.inspectorDismissed = !galleryOverviewLayoutQuery.matches;
    state.inspectorDismissedByUser = state.inspectorDismissed;
    if (state.inspectorDismissed) elements.inspector.classList.remove("open");
  }
  if (!enabled) {
    state.inspectorDismissedByUser = false;
    state.inspectorOverlayReturnFocus = null;
    state.selectedAssetIDs.clear();
    state.selectionAnchorID = null;
    state.selectionAggregates = [];
    state.aggregateGeneration += 1;
    state.selectionPrimaryDetail = null;
    state.selectionPrimaryLoadingAssetID = null;
    state.selectionPrimaryRequestGeneration += 1;
  }
  syncSelectionModeControls();
  if (enteringSelectionMode) {
    requestAnimationFrame(resetCompactSelectionToolScroll);
  }
  renderAssetSelectionState();
  renderSelectionMutation();
}

function openSelectionInspectorOverlay() {
  if (!state.selectionMode || !state.selectedAssetIDs.size) return;
  openGalleryInspectorOverlay({
    returnFocus: elements.selectionInspectorOverlayButton,
  });
}

function toggleAssetSelection(assetID) {
  if (state.selectedAssetIDs.has(assetID)) {
    state.selectedAssetIDs.delete(assetID);
  } else {
    state.selectedAssetIDs.add(assetID);
  }
  state.selectedAssetID = state.selectedAssetIDs.has(assetID)
    ? assetID
    : ([...state.selectedAssetIDs][0] || null);
  renderAssetSelectionState();
  renderSelectionMutation();
  scheduleSelectionAggregate();
}

function selectAssetRange(assetID, additive = false) {
  const anchorID = state.selectionAnchorID || state.selectedAssetID || assetID;
  const anchorIndex = state.assets.findIndex((asset) => asset.id === anchorID);
  const targetIndex = state.assets.findIndex((asset) => asset.id === assetID);
  if (anchorIndex < 0 || targetIndex < 0) return;
  const start = Math.min(anchorIndex, targetIndex);
  const end = Math.max(anchorIndex, targetIndex);
  const next = additive ? new Set(state.selectedAssetIDs) : new Set();
  for (const asset of state.assets.slice(start, end + 1)) next.add(asset.id);
  state.selectedAssetIDs = next;
  state.selectedAssetID = assetID;
  state.selectionAnchorID = anchorID;
  renderAssetSelectionState();
  renderSelectionMutation();
  scheduleSelectionAggregate();
}

function handleAssetSelection(assetID, { additive = false, range = false } = {}) {
  if (range) {
    if (!state.selectionMode) setSelectionMode(true, { seedCurrent: true });
    selectAssetRange(assetID, additive);
    return;
  }
  if (additive) {
    if (!state.selectionMode) setSelectionMode(true, { seedCurrent: true });
    toggleAssetSelection(assetID);
    state.selectionAnchorID = assetID;
    return;
  }
  if (state.selectionMode) {
    state.selectedAssetIDs = new Set([assetID]);
    state.selectedAssetID = assetID;
    state.selectionAnchorID = assetID;
    renderAssetSelectionState();
    renderSelectionMutation();
    scheduleSelectionAggregate();
    return;
  }
  const preservesCloudPreview = state.cloudPreview.assetID === assetID
    && state.cloudPreview.status !== "hidden";
  loadInspector(assetID, {
    reveal: true,
    focusInspector: true,
    preserveExisting: preservesCloudPreview,
  });
}

function rememberGridSelectionBeforeClick(surface, itemID, event) {
  const clickCount = Number(event.detail);
  const pending = state.gridDoubleClickSelectionSnapshot;
  if (clickCount >= 2) {
    if (pending
      && pending.surface === surface
      && pending.itemID === itemID
      && performance.now() - pending.capturedAt <= GRID_DOUBLE_CLICK_MAX_DELAY_MS) {
      pending.ready = true;
      return true;
    }
    state.gridDoubleClickSelectionSnapshot = null;
    return false;
  }
  if (clickCount !== 1) return false;

  let selection;
  if (surface === "library") {
    selection = {
      selectedIDs: [...state.selectedAssetIDs],
      primaryID: state.selectedAssetID,
      anchorID: state.selectionAnchorID,
    };
  } else if (surface === "review") {
    selection = {
      selectedIDs: [...state.review.selectedAssetIDs],
      selectedIndex: state.review.selectedIndex,
      anchorIndex: state.review.selectionAnchorIndex,
    };
  } else if (surface === "slimming") {
    selection = {
      selectedIDs: [...state.slimming.selectedMemberIDs],
      anchorID: state.slimming.selectionAnchorID,
    };
  } else {
    return false;
  }
  state.gridDoubleClickSelectionSnapshot = {
    surface,
    itemID,
    selection,
    capturedAt: performance.now(),
    ready: false,
  };
  return false;
}

function continuesGridSelectionDoubleClick(surface, itemID, event) {
  const pending = state.gridDoubleClickSelectionSnapshot;
  return Number(event.detail) >= 2
    && pending?.surface === surface
    && pending.itemID === itemID;
}

function restoreGridSelectionForDoubleClick(surface, itemID) {
  const pending = state.gridDoubleClickSelectionSnapshot;
  state.gridDoubleClickSelectionSnapshot = null;
  if (!pending
    || !pending.ready
    || pending.surface !== surface
    || pending.itemID !== itemID
    || performance.now() - pending.capturedAt > GRID_DOUBLE_CLICK_MAX_DELAY_MS) return false;

  if (surface === "library" && state.selectionMode) {
    state.selectedAssetIDs = new Set(pending.selection.selectedIDs);
    state.selectedAssetID = pending.selection.primaryID;
    state.selectionAnchorID = pending.selection.anchorID;
    renderAssetSelectionState();
    renderSelectionMutation();
    scheduleSelectionAggregate();
    return true;
  }
  if (surface === "review"
    && (state.review.selectionMode || pending.selection.selectedIDs.length > 1)) {
    state.review.selectedAssetIDs = new Set(pending.selection.selectedIDs);
    state.review.selectedIndex = pending.selection.selectedIndex;
    state.review.selectionAnchorIndex = pending.selection.anchorIndex;
    renderReviewSelectionState();
    checkpointActiveWorkspaceHistory();
    return true;
  }
  if (surface === "slimming"
    && (state.slimming.selectionMode || pending.selection.selectedIDs.length > 1)) {
    state.slimming.selectedMemberIDs = new Set(pending.selection.selectedIDs);
    state.slimming.selectionAnchorID = pending.selection.anchorID;
    renderSlimmingMemberSelection();
    return true;
  }
  return false;
}

function openReviewLightbox(item, options = {}) {
  if (!item?.assetID) return;
  openLightbox("review", item.assetID, {
    ...options,
    reviewKey: reviewItemKey(item),
  });
}

function openLightboxFromContextMenu(context, assetID, returnFocus, {
  reviewKey = null,
} = {}) {
  const resolvedReturnFocus = returnFocus instanceof HTMLElement
    && document.contains(returnFocus)
    ? returnFocus
    : null;
  openLightbox(context, assetID, { preserveSelection: true, reviewKey });
  if (resolvedReturnFocus) state.lightboxReturnFocus = resolvedReturnFocus;
}

function selectAllLoadedAssets() {
  if (!state.assets.length) return;
  if (!state.selectionMode) setSelectionMode(true);
  state.selectedAssetIDs = new Set(state.assets.map((asset) => asset.id));
  const primaryID = state.assets.some((asset) => asset.id === state.selectedAssetID)
    ? state.selectedAssetID
    : state.assets[0]?.id;
  state.selectedAssetID = primaryID || null;
  state.selectionAnchorID = primaryID || null;
  renderAssetSelectionState();
  renderSelectionMutation();
  scheduleSelectionAggregate();
}

function currentTagTargetAssetIDs() {
  if (reviewWorkspaceIsOpen() && state.review.mode === "queue") {
    return selectedReviewItems().map((item) => item.assetID);
  }
  if (state.selectionMode) return [...state.selectedAssetIDs];
  return state.selectedAssetID ? [state.selectedAssetID] : [];
}

function galleryRemovalTargetAssetIDs(
  requestedAssetIDs = null,
  { surface = "gallery" } = {}
) {
  const candidates = surface === "review"
    ? state.review.items.map((item) => ({ ...item, id: item.assetID }))
    : state.assets;
  const visibleByID = new Map(candidates.map((asset) => [asset.id, asset]));
  return [...new Set(requestedAssetIDs || currentTagTargetAssetIDs())].filter((assetID) => {
    const asset = visibleByID.get(assetID);
    if (!asset || asset.availability !== "available") return false;
    return !asset.mediaKind || asset.mediaKind === state.mediaKind;
  });
}

function assetIsDeletionProtected(assetID) {
  const favorite = favoriteStateForAssetID(assetID);
  return favorite?.isFavorite === true || favorite?.photosObservedValue === true;
}

function removalFavoriteProtectionPlan(assetIDs) {
  const requestedAssetIDs = [...new Set(assetIDs)];
  const unverifiableAssetIDs = requestedAssetIDs.filter(
    (assetID) => !favoriteStateForAssetID(assetID)
  );
  const favoriteProtectedAssetIDs = requestedAssetIDs.filter(assetIsDeletionProtected);
  const protectedSet = new Set(favoriteProtectedAssetIDs);
  return {
    requestedAssetIDs,
    removalAssetIDs: requestedAssetIDs.filter((assetID) => !protectedSet.has(assetID)),
    favoriteProtectedAssetIDs,
    unverifiableAssetIDs,
  };
}

function activeGalleryRemovalRequest() {
  return state.galleryRemoval.requests.find(
    (request) => request.phase === "awaitingMac" || request.phase === "running"
  ) || null;
}

function galleryRemovalStatusText(request) {
  if (!request) return "";
  if (request.scope !== "gallerySelection") {
    return request.phase === "awaitingMac"
      ? "另一项删除或回收正在等待 Mac 确认"
      : "Mac 正在处理另一项删除或回收";
  }
  if (request.phase === "awaitingMac") return "等待 Mac 原生确认";
  const total = Math.max(0, Number(request.progress?.totalAssetCount || request.assetIDs?.length || 0));
  const completed = Math.min(total, Math.max(0, Number(request.progress?.completedAssetCount || 0)));
  return total > 0 ? `正在删除 ${completed} / ${total}` : "Mac 正在安全删除并核验";
}

function renderGalleryRemovalControls() {
  const targetIDs = galleryRemovalTargetAssetIDs();
  const protection = removalFavoriteProtectionPlan(targetIDs);
  const active = activeGalleryRemovalRequest();
  const unavailable = !supportsLibrarySlimming()
    || !state.online
    || state.galleryRemoval.submitting
    || Boolean(active)
    || protection.removalAssetIDs.length === 0
    || protection.unverifiableAssetIDs.length > 0;
  const activeText = galleryRemovalStatusText(active);
  const noun = state.mediaKind === "video" ? "个视频" : "张照片";
  const targetLabel = protection.removalAssetIDs.length > 1
    ? `删除 ${protection.removalAssetIDs.length} 项`
    : "删除";
  for (const button of [
    elements.deleteSelectedButton,
    elements.selectionInspectorDeleteButton,
    elements.inspectorDeleteButton,
  ]) {
    button.classList.toggle("hidden", !supportsLibrarySlimming());
    button.disabled = unavailable;
    button.title = !supportsLibrarySlimming()
      ? "当前 Mac Host 不支持图库快速删除"
      : activeText || (protection.unverifiableAssetIDs.length
        ? "无法核验红心保护，暂不能删除"
        : protection.removalAssetIDs.length
          ? `立即删除 ${protection.removalAssetIDs.length} ${noun}`
            + `${protection.favoriteProtectedAssetIDs.length ? `，保留 ${protection.favoriteProtectedAssetIDs.length} 项红心` : ""}；仍需在 Mac 原生窗口确认`
          : targetIDs.length
            ? "所选项目均有红心保护；请先取消红心再删除"
        : `请先选择要删除的${currentMediaNoun()}`);
    button.setAttribute("aria-label", button.title);
  }
  elements.deleteSelectedButton.textContent = state.galleryRemoval.submitting
    ? "正在交给 Mac…"
    : (activeText || targetLabel);
  elements.selectionInspectorDeleteButton.textContent = state.galleryRemoval.submitting
    ? "正在交给 Mac…"
    : (activeText || targetLabel);
  elements.inspectorDeleteButtonLabel.textContent = state.galleryRemoval.submitting
    ? "正在交给 Mac…"
    : (activeText || "删除");

  const showsStatus = Boolean(activeText);
  for (const status of [elements.galleryRemovalStatus, elements.selectionInspectorRemovalStatus]) {
    status.classList.toggle("hidden", !showsStatus);
    status.textContent = activeText;
  }
  const favoriteCount = protection.favoriteProtectedAssetIDs.length;
  elements.inspectorDeleteHint.textContent = protection.unverifiableAssetIDs.length
    ? "无法核验红心保护，未删除任何项目。"
    : favoriteCount
    ? `将保留 ${favoriteCount} 项红心，只删除其余 ${protection.removalAssetIDs.length} 项。文件夹原始媒体将永久删除，Apple Photos 项进入系统“最近删除”。`
    : "文件夹原始媒体将永久删除；Apple Photos 项进入系统“最近删除”。";
  if (elements.assetDeleteContextAction) {
    const contextAsset = state.assets.find((asset) => asset.id === state.contextAssetID);
    elements.assetDeleteContextAction.classList.toggle("hidden", !supportsLibrarySlimming());
    elements.assetDeleteContextAction.disabled = !state.online
      || state.galleryRemoval.submitting
      || Boolean(active)
      || contextAsset?.availability !== "available"
      || !favoriteStateForAssetID(contextAsset?.id)
      || assetIsDeletionProtected(contextAsset?.id);
  }
  renderReviewInspectorActions();
}

function galleryRemovalConfirmationMessage(protection) {
  const favoriteCount = protection.favoriteProtectedAssetIDs.length;
  const favoriteWarning = favoriteCount
    ? `将保留 ${favoriteCount} 项红心，只删除其余 ${protection.removalAssetIDs.length} 项。`
    : "";
  return `${favoriteWarning}文件夹来源会在身份核验后永久删除，无法从 ImageAll 恢复；Apple Photos 项只会进入系统“最近删除”。提交后还需要在 Mac 原生窗口再次确认。`;
}

function galleryRemovalReturnFocus(previewAssetID = null) {
  if (previewAssetID) {
    return {
      lightboxAssetID: previewAssetID,
      libraryAssetID: previewAssetID,
    };
  }
  return { element: document.activeElement };
}

function reconcileLibrarySelectionAfterGalleryRemoval(context, hiddenAssetIDs) {
  const primaryWasHidden = Boolean(
    state.selectedAssetID && hiddenAssetIDs.has(state.selectedAssetID)
  );
  const anchorWasHidden = Boolean(
    state.selectionAnchorID && hiddenAssetIDs.has(state.selectionAnchorID)
  );
  if (!primaryWasHidden && !anchorWasHidden) return;

  const remainingSelectedIDs = state.assets
    .map((asset) => asset.id)
    .filter((assetID) => state.selectedAssetIDs.has(assetID));
  const previousIDs = context?.assetIDs || state.assets.map((asset) => asset.id);
  if (primaryWasHidden) {
    state.selectedAssetID = replacementPreviewAssetID(
      previousIDs,
      remainingSelectedIDs,
      state.selectedAssetID
    ) || remainingSelectedIDs[0] || null;
  }
  if (anchorWasHidden) {
    state.selectionAnchorID = state.selectedAssetID
      || replacementPreviewAssetID(
        previousIDs,
        remainingSelectedIDs,
        state.selectionAnchorID
      )
      || remainingSelectedIDs[0]
      || null;
  }
}

async function reconcileLibraryPreviewAfterGalleryRemoval(context, hiddenAssetIDs) {
  const previewAssetID = context?.surface !== "review" ? context?.previewAssetID : null;
  if (!previewAssetID || !hiddenAssetIDs.has(previewAssetID)) return;
  if (state.lightboxContext !== "library"
    || state.lightboxAssetID !== previewAssetID
    || elements.lightbox.classList.contains("hidden")) return;

  const remainingIDs = state.assets.map((asset) => asset.id);
  const continuationIDs = continuedAssetIDs(context.assetIDs || [], remainingIDs);
  const replacementID = replacementPreviewAssetID(
    continuationIDs,
    remainingIDs,
    previewAssetID
  );
  if (!replacementID) {
    closeLightbox();
    return;
  }

  if (state.cloudPreview.assetID === previewAssetID
    && state.cloudPreview.status !== "hidden") resetCloudPreviewRecovery();
  state.lightboxAssetID = replacementID;
  state.lightboxOriginalAssetID = null;
  state.lightboxOriginalLoading = false;
  const replacementCard = elements.assetGrid.querySelector(
    `[data-asset-id="${CSS.escape(replacementID)}"]`
  );
  state.lightboxReturnFocus = assetCardMainButton(replacementCard)
    || state.lightboxReturnFocus;

  if (state.lightboxPreservesSelection && state.selectionMode) {
    const remainingSelectedIDs = state.assets
      .map((asset) => asset.id)
      .filter((assetID) => state.selectedAssetIDs.has(assetID));
    if (!remainingSelectedIDs.length) {
      state.selectedAssetIDs = new Set([replacementID]);
      state.selectedAssetID = replacementID;
      state.selectionAnchorID = replacementID;
    } else {
      if (!remainingSelectedIDs.includes(state.selectedAssetID)) {
        state.selectedAssetID = replacementPreviewAssetID(
          continuationIDs,
          remainingSelectedIDs,
          context.selectedAssetID || previewAssetID
        ) || remainingSelectedIDs[0];
      }
      if (!remainingSelectedIDs.includes(state.selectionAnchorID)) {
        state.selectionAnchorID = state.selectedAssetID;
      }
    }
    renderAssetSelectionState();
    renderSelectionMutation();
    scheduleSelectionAggregate();
  }

  renderLightbox();
  checkpointActiveWorkspaceHistory();
  if (!state.lightboxPreservesSelection) {
    await syncLibraryLightboxSelection(replacementID);
  }
}

async function submitGalleryRemoval({
  assetIDs: requestedAssetIDs = null,
  previewAssetID = null,
  returnFocus = null,
  confirmed = false,
  surface = "gallery",
} = {}) {
  const assetIDs = galleryRemovalTargetAssetIDs(requestedAssetIDs, { surface });
  const protection = removalFavoriteProtectionPlan(assetIDs);
  const activeReviewPreviewID = surface === "review"
    && state.lightboxContext === "review"
    && !elements.lightbox.classList.contains("hidden")
    ? state.lightboxAssetID
    : null;
  const effectivePreviewAssetID = previewAssetID || activeReviewPreviewID;
  const active = activeGalleryRemovalRequest();
  if (!supportsLibrarySlimming()) {
    toast("请先更新并重启 Mac Host 后再使用图库快速删除");
    return;
  }
  if (!assetIDs.length) {
    toast(`请先选择至少${mediaItemCountText(1)}`);
    return;
  }
  if (protection.unverifiableAssetIDs.length) {
    toast("无法核验红心保护，未删除任何项目");
    return;
  }
  if (!protection.removalAssetIDs.length) {
    toast("所选项目均有红心保护；请先取消红心再删除");
    return;
  }
  if (active || state.galleryRemoval.submitting) {
    toast(galleryRemovalStatusText(active) || "已有删除或回收正在处理");
    return;
  }
  const noun = state.mediaKind === "video" ? "个视频" : "张照片";
  if (!confirmed) {
    requestConfirmation({
      eyebrow: "QUICK DELETE",
      title: `立即删除选中的 ${protection.removalAssetIDs.length} ${noun}？`,
      message: galleryRemovalConfirmationMessage(protection),
      actionLabel: "删除",
      tone: "danger",
      returnFocus: returnFocus || galleryRemovalReturnFocus(previewAssetID),
      action: () => submitGalleryRemoval({
        assetIDs,
        previewAssetID,
        returnFocus,
        confirmed: true,
        surface,
      }),
    });
    return;
  }

  const workspaceGeneration = state.workspaceGeneration;
  const scrollTop = surface === "review"
    ? elements.reviewQueuePane.scrollTop
    : elements.libraryScroll.scrollTop;
  state.galleryRemoval.submitting = true;
  renderGalleryRemovalControls();
  if (effectivePreviewAssetID
    && state.lightboxAssetID === effectivePreviewAssetID
    && ["library", "review"].includes(state.lightboxContext)) renderLightbox();
  try {
    const request = await api("/v1/library-slimming/removals", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        operationID: crypto.randomUUID(),
        scope: "gallerySelection",
        jobID: null,
        clusterID: null,
        mediaKind: state.mediaKind,
        assetIDs,
        mode: "releaseSourceSpace",
      }),
    });
    if (workspaceGeneration !== state.workspaceGeneration) return;
    state.galleryRemoval.requests = [
      request,
      ...state.galleryRemoval.requests.filter((item) => item.id !== request.id),
    ];
    state.slimming.removal.requests = [
      request,
      ...state.slimming.removal.requests.filter((item) => item.id !== request.id),
    ];
    state.galleryRemoval.contexts.set(request.id, {
      surface,
      mediaKind: state.mediaKind,
      assetIDs: state.assets.map((asset) => asset.id),
      selectedAssetID: state.selectedAssetID,
      selectedAssetIDs: [...state.selectedAssetIDs],
      selectionAnchorID: state.selectionAnchorID,
      selectionMode: state.selectionMode,
      scrollTop,
      previewAssetID: effectivePreviewAssetID,
      reviewItemIDs: surface === "review"
        ? state.review.items.map((item) => item.assetID)
        : [],
      reviewSelectedIndex: surface === "review" ? state.review.selectedIndex : -1,
      reviewSelectedAssetIDs: surface === "review"
        ? [...state.review.selectedAssetIDs]
        : [],
    });
    toast("已冻结当前选区，请回到 Mac 核对并确认");
  } catch (error) {
    if (workspaceGeneration === state.workspaceGeneration) {
      toast(error.message || "图库删除提交失败");
    }
  } finally {
    if (workspaceGeneration === state.workspaceGeneration) {
      state.galleryRemoval.submitting = false;
      renderGalleryRemovalControls();
      if (effectivePreviewAssetID
        && state.lightboxAssetID === effectivePreviewAssetID
        && ["library", "review"].includes(state.lightboxContext)
        && !elements.lightbox.classList.contains("hidden")) renderLightbox();
      scheduleGalleryRemovalPoll();
    }
  }
}

function reconcileReviewPreviewAfterGalleryRemoval(context, hiddenAssetIDs) {
  const previewAssetID = context?.surface === "review" ? context.previewAssetID : null;
  if (!previewAssetID || !hiddenAssetIDs.has(previewAssetID)) return;
  if (state.lightboxContext !== "review"
    || state.lightboxAssetID !== previewAssetID
    || elements.lightbox.classList.contains("hidden")) return;

  const remainingIDs = state.review.items.map((item) => item.assetID);
  const continuationIDs = continuedAssetIDs(
    context.reviewItemIDs || [],
    remainingIDs
  );
  const replacementID = replacementPreviewAssetID(
    continuationIDs,
    remainingIDs,
    previewAssetID
  );
  if (!replacementID) {
    closeLightbox();
    return;
  }

  const replacementIndex = state.review.items.findIndex(
    (item) => item.assetID === replacementID
  );
  state.review.selectedIndex = replacementIndex;
  state.review.selectedAssetIDs = new Set([replacementID]);
  state.review.selectionAnchorIndex = replacementIndex;
  state.lightboxAssetID = replacementID;
  state.lightboxReviewKey = reviewItemKey(state.review.items[replacementIndex]);
  state.lightboxOriginalAssetID = null;
  state.lightboxOriginalLoading = false;
  const replacementCard = elements.reviewGrid.querySelector(
    `[data-review-index="${replacementIndex}"]`
  );
  state.lightboxReturnFocus = reviewCardMainButton(replacementCard)
    || state.lightboxReturnFocus;
  renderReviewSelectionState();
  renderLightbox();
  checkpointActiveWorkspaceHistory();
}

function scheduleGalleryRemovalPoll() {
  clearTimeout(state.galleryRemoval.pollTimer);
  state.galleryRemoval.pollTimer = null;
  if (!state.galleryRemoval.requests.some(
    (request) => request.phase === "awaitingMac" || request.phase === "running"
  )) return;
  state.galleryRemoval.pollTimer = setTimeout(
    () => loadGalleryRemovals({ quiet: true }),
    900
  );
}

async function applyGalleryRemovalTerminal(request) {
  const context = state.galleryRemoval.contexts.get(request.id) || null;
  state.galleryRemoval.contexts.delete(request.id);
  const hidden = new Set(request.audit?.hiddenAssetIDs || []);
  if (hidden.size && request.mediaKind === state.mediaKind) {
    const scrollTop = elements.libraryScroll.scrollTop;
    state.selectedAssetIDs = new Set(
      [...state.selectedAssetIDs].filter((assetID) => !hidden.has(assetID))
    );
    const selectedAssetWasHidden = Boolean(
      state.selectedAssetID && hidden.has(state.selectedAssetID)
    );
    if (selectedAssetWasHidden) {
      state.selectedDetail = null;
      state.inspectorRequestGeneration += 1;
    }
    reconcileLibrarySelectionAfterGalleryRemoval(context, hidden);
    for (const assetID of hidden) state.lightboxFavoriteStates.delete(assetID);
    await loadAssets({
      preserveSelection: true,
      preserveUnchangedGrid: true,
      preserveLoadedWindow: true,
    });
    await reconcileLibraryPreviewAfterGalleryRemoval(context, hidden);
    elements.libraryScroll.scrollTop = scrollTop;
    if (state.selectionMode && state.selectedAssetIDs.size) scheduleSelectionAggregate();
    else renderInspectorSurface();
    checkpointActiveWorkspaceHistory();
  } else if (hidden.size) {
    const session = state.mediaSessions[request.mediaKind];
    if (session) {
      session.assets = session.assets.filter((asset) => !hidden.has(asset.id));
      session.selectedAssetIDs = session.selectedAssetIDs.filter((assetID) => !hidden.has(assetID));
      if (hidden.has(session.selectedAssetID)) {
        session.selectedAssetID = null;
        session.selectedDetail = null;
      }
      if (hidden.has(session.selectionAnchorID)) session.selectionAnchorID = null;
    }
  }
  if (context?.surface === "review"
    && state.review.mode === "queue"
    && request.mediaKind === state.mediaKind) {
    state.review.selectedAssetIDs = new Set(
      [...state.review.selectedAssetIDs].filter((assetID) => !hidden.has(assetID))
    );
    const anchorAssetID = state.review.items[state.review.selectionAnchorIndex]?.assetID;
    if (anchorAssetID && hidden.has(anchorAssetID)) state.review.selectionAnchorIndex = -1;
    state.review.detail = null;
    state.review.tagAggregates = [];
    state.review.detailSelectionKey = null;
    state.review.detailRequestGeneration += 1;
    await Promise.all([
      loadReviewOverview({ throwOnError: false }),
      loadReviewQueue({
        preserveLoadedWindow: true,
        preserveUnchangedGrid: true,
        schedulePagination: false,
      }),
    ]);
    reconcileReviewPreviewAfterGalleryRemoval(context, hidden);
    if (context.scrollTop != null) {
      const delta = Math.abs(elements.reviewQueuePane.scrollTop - context.scrollTop);
      if (delta < 2) elements.reviewQueuePane.scrollTop = context.scrollTop;
    }
    scheduleReviewAutoPagination();
  }
  if (context?.surface !== "review"
    && context?.scrollTop != null
    && request.mediaKind === state.mediaKind) {
    // Only restore the submission position when the user has not intentionally
    // moved elsewhere while the Mac confirmation was pending.
    const delta = Math.abs(elements.libraryScroll.scrollTop - context.scrollTop);
    if (delta < 2) elements.libraryScroll.scrollTop = context.scrollTop;
  }
  toast(request.message || "图库删除已结束");
  renderGalleryRemovalControls();
}

async function loadGalleryRemovals({ quiet = false } = {}) {
  if (!supportsLibrarySlimming()) return;
  const generation = ++state.galleryRemoval.requestGeneration;
  const workspaceGeneration = state.workspaceGeneration;
  const previouslyActiveIDs = new Set(
    state.galleryRemoval.requests
      .filter((request) => request.scope === "gallerySelection"
        && (request.phase === "awaitingMac" || request.phase === "running"))
      .map((request) => request.id)
  );
  state.galleryRemoval.loading = true;
  try {
    const query = new URLSearchParams({ mediaKind: state.mediaKind });
    const snapshot = await api(`/v1/library-slimming/removals?${query}`);
    if (generation !== state.galleryRemoval.requestGeneration
      || workspaceGeneration !== state.workspaceGeneration) return;
    state.galleryRemoval.requests = snapshot.requests || [];
    const terminal = state.galleryRemoval.requests.find((request) => (
      request.scope === "gallerySelection"
        && ["completed", "cancelled", "failed"].includes(request.phase)
        && (previouslyActiveIDs.has(request.id)
          || state.galleryRemoval.contexts.has(request.id))
        && !state.galleryRemoval.seenTerminalRequestIDs.has(request.id)
    ));
    if (terminal) {
      state.galleryRemoval.seenTerminalRequestIDs.add(terminal.id);
      await applyGalleryRemovalTerminal(terminal);
    }
  } catch (error) {
    if (generation === state.galleryRemoval.requestGeneration
      && workspaceGeneration === state.workspaceGeneration && !quiet) {
      toast(error.message || "图库删除状态载入失败");
    }
  } finally {
    if (generation === state.galleryRemoval.requestGeneration
      && workspaceGeneration === state.workspaceGeneration) {
      state.galleryRemoval.loading = false;
      renderGalleryRemovalControls();
      scheduleGalleryRemovalPoll();
    }
  }
}

const NEW_TAG_HISTORY_CONTROL_IDS = new Set([
  "newTagName",
  "cancelNewTagButton",
  "cancelNewTagFooterButton",
  "createTagButton",
]);
const NEW_TAG_HISTORY_RETURN_IDS = new Set([
  "sidebarNewTagButton",
  "batchNewTagButton",
  "tagManagerButton",
  "commandButton",
]);

function normalizedNewTagHistoryFocusID(value) {
  return NEW_TAG_HISTORY_CONTROL_IDS.has(value) ? value : "newTagName";
}

function captureNewTagHistoryFocus() {
  const control = document.activeElement instanceof Element
    ? document.activeElement.closest("button, input")
    : null;
  if (control instanceof HTMLElement
    && elements.newTagDialog.contains(control)
    && NEW_TAG_HISTORY_CONTROL_IDS.has(control.id)) {
    state.newTagFocusID = control.id;
  }
}

function newTagReturnControlID(target) {
  return target instanceof HTMLElement && NEW_TAG_HISTORY_RETURN_IDS.has(target.id)
    ? target.id
    : null;
}

function currentNewTagHistoryContext() {
  if (elements.newTagDialog.open) captureNewTagHistoryFocus();
  return {
    newTagFocusID: normalizedNewTagHistoryFocusID(state.newTagFocusID),
    newTagReturnControlID: NEW_TAG_HISTORY_RETURN_IDS.has(state.newTagReturnControlID)
      ? state.newTagReturnControlID
      : null,
  };
}

function applyNewTagHistoryContext(context = {}) {
  state.newTagFocusID = normalizedNewTagHistoryFocusID(context.newTagFocusID);
  state.newTagReturnControlID = NEW_TAG_HISTORY_RETURN_IDS.has(
    context.newTagReturnControlID
  ) ? context.newTagReturnControlID : null;
}

function resolveNewTagReturnFocus() {
  if (state.newTagReturnFocus?.isConnected) return state.newTagReturnFocus;
  if (state.newTagReturnControlID) {
    const target = document.getElementById(state.newTagReturnControlID);
    if (target instanceof HTMLElement && !target.disabled && target.getClientRects().length) {
      return target;
    }
  }
  return stableReturnFocusTarget(
    elements.sidebarNewTagButton,
    stableReturnFocusTarget(elements.batchNewTagButton, elements.commandButton)
  );
}

async function restoreNewTagLayoutFromHistory() {
  await waitForWorkspaceLayout();
  let target = document.getElementById(normalizedNewTagHistoryFocusID(state.newTagFocusID));
  if (!(target instanceof HTMLElement)
    || target.disabled
    || !elements.newTagDialog.contains(target)
    || target.offsetParent === null) {
    target = elements.newTagName;
  }
  state.newTagFocusID = target.id;
  target.focus({ preventScroll: true });
}

function newTagBaseLevelFromHistory(context = {}) {
  return ["sidebar", "inspector", "lightbox"].includes(context.newTagBaseLevel)
    ? context.newTagBaseLevel
    : "workspace";
}

function replaceNewTagHistoryWithBase(baseLevel) {
  if (!state.workspaceNavigation.initialized
    || elements.appView.classList.contains("hidden")) return;
  const current = activeWorkspaceHistoryEntry();
  const route = visibleWorkspaceRoute();
  if (current?.route !== route || current.navigationLevel !== "newTag") return;
  const context = currentWorkspaceHistoryContext(route);
  if (context && typeof context === "object") {
    delete context.newTagBaseLevel;
    delete context.newTagFocusID;
    delete context.newTagReturnControlID;
  }
  const navigationLevel = visibleWorkspaceNavigationBaseLevel(route, baseLevel);
  history.replaceState({
    ...(history.state || {}),
    [WORKSPACE_HISTORY_KEY]: workspaceHistoryEntry(route, context, navigationLevel),
  }, "", location.href);
}

function clearNewTagState() {
  elements.newTagError.textContent = "";
  elements.newTagName.value = "";
  elements.newTagRestoreNotice.classList.add("hidden");
  state.newTagOperationID = null;
  state.newTagReturnFocus = null;
  state.newTagBaseLevel = "workspace";
  state.newTagHistoryRestoreFocus = true;
  state.newTagOpening = false;
  state.newTagRestorable = false;
  state.newTagFocusID = "newTagName";
  state.newTagReturnControlID = null;
  state.newTagReloadNotice = false;
}

function closeNewTagDialog({
  restoreFocus = true,
  checkpoint = true,
  preserveState = false,
} = {}) {
  if (!elements.newTagDialog.open) return;
  captureNewTagHistoryFocus();
  const baseLevel = state.newTagBaseLevel;
  const returnFocus = resolveNewTagReturnFocus();
  elements.newTagDialog.close();
  if (restoreFocus) {
    restoreOverlayFocus(stableReturnFocusTarget(returnFocus, elements.sidebarNewTagButton));
  }
  if (checkpoint) replaceNewTagHistoryWithBase(baseLevel);
  if (!preserveState) clearNewTagState();
}

function presentNewTagDialog({
  historyMode = "pushNewTag",
  baseLevel = null,
  focus = true,
  reset = true,
  returnFocus = null,
} = {}) {
  const assetIDs = currentTagTargetAssetIDs();
  if (!assetIDs.length) {
    toast(`请先选择至少${mediaItemCountText(1)}`);
    return false;
  }
  if (elements.newTagDialog.open || state.newTagOpening) {
    if (focus) restoreOverlayFocus(elements.newTagName);
    return true;
  }
  state.newTagOpening = true;
  try {
    state.newTagReturnFocus = returnFocus
      || state.newTagReturnFocus
      || (document.activeElement instanceof HTMLElement ? document.activeElement : null);
    state.newTagReturnControlID = newTagReturnControlID(state.newTagReturnFocus)
      || state.newTagReturnControlID;
    const current = activeWorkspaceHistoryEntry();
    state.newTagBaseLevel = baseLevel
      || workspaceNavigationBaseLevel(
        current?.navigationLevel || "workspace",
        current?.context || {}
      );
    if (reset) {
      state.newTagOperationID = crypto.randomUUID();
      elements.newTagError.textContent = "";
      elements.newTagName.value = "";
      state.newTagFocusID = "newTagName";
      state.newTagReloadNotice = false;
    }
    elements.newTagRestoreNotice.classList.toggle("hidden", !state.newTagReloadNotice);
    elements.newTagTargetSummary.textContent = `创建后将为 ${mediaItemCountText(assetIDs.length)}确认此标签`;
    elements.newTagDialog.showModal();
    state.newTagRestorable = true;
    if (historyMode !== "none") {
      const route = visibleWorkspaceRoute();
      recordWorkspaceHistory(route, currentWorkspaceHistoryContext(route), historyMode);
    }
  } finally {
    state.newTagOpening = false;
  }
  if (focus) {
    const target = document.getElementById(normalizedNewTagHistoryFocusID(state.newTagFocusID));
    restoreOverlayFocus(target instanceof HTMLElement ? target : elements.newTagName);
  }
  scheduleWorkspaceHistoryCheckpoint();
  return true;
}

function openNewTagDialog() {
  presentNewTagDialog();
}

function returnFromNewTag({ restoreFocus = true } = {}) {
  if (!elements.newTagDialog.open) return Promise.resolve();
  state.newTagHistoryRestoreFocus = restoreFocus;
  if (state.workspaceNavigation.pendingReturnPromise) {
    return state.workspaceNavigation.pendingReturnPromise;
  }
  const current = activeWorkspaceHistoryEntry();
  if (state.workspaceNavigation.initialized
    && current?.route === visibleWorkspaceRoute()
    && current.navigationLevel === "newTag") {
    const pending = new Promise((resolve) => {
      state.workspaceNavigation.pendingReturnResolve = resolve;
    });
    state.workspaceNavigation.pendingReturnPromise = pending;
    history.back();
    return pending;
  }
  closeNewTagDialog({ restoreFocus });
  state.newTagHistoryRestoreFocus = true;
  return Promise.resolve();
}

async function reconcileNewTagFromWorkspaceHistory(route, navigationLevel, context = {}) {
  const shouldOpen = navigationLevel === "newTag"
    && route === visibleWorkspaceRoute();
  if (shouldOpen && !currentTagTargetAssetIDs().length) {
    clearNewTagState();
    replaceNewTagHistoryWithBase(newTagBaseLevelFromHistory(context));
    return false;
  }
  const restoringFreshState = shouldOpen && !state.newTagRestorable;
  if (shouldOpen) applyNewTagHistoryContext(context);
  if (restoringFreshState) {
    state.newTagOperationID = crypto.randomUUID();
    state.newTagReloadNotice = true;
    state.newTagFocusID = "newTagName";
    elements.newTagName.value = "";
    elements.newTagError.textContent = "";
  }
  if (shouldOpen && !elements.newTagDialog.open) {
    presentNewTagDialog({
      historyMode: "none",
      baseLevel: newTagBaseLevelFromHistory(context),
      focus: false,
      reset: false,
    });
    await restoreNewTagLayoutFromHistory();
  } else if (!shouldOpen && elements.newTagDialog.open) {
    const restoreFocus = state.newTagHistoryRestoreFocus;
    closeNewTagDialog({
      restoreFocus,
      checkpoint: false,
      preserveState: true,
    });
    state.newTagHistoryRestoreFocus = true;
  }
  return restoringFreshState;
}

function inlineTagSurfaceElements(surface) {
  if (surface === "review") {
    return {
      form: elements.reviewInlineTagForm,
      input: elements.reviewInlineTagName,
      button: elements.reviewNewTagButton,
      error: elements.reviewInlineTagError,
    };
  }
  return surface === "selection"
    ? {
      form: elements.selectionInspectorInlineTagForm,
      input: elements.selectionInspectorInlineTagName,
      button: elements.selectionInspectorNewTagButton,
      error: elements.selectionInspectorInlineTagError,
    }
    : {
      form: elements.inspectorInlineTagForm,
      input: elements.inspectorInlineTagName,
      button: elements.inspectorNewTagButton,
      error: elements.inspectorInlineTagError,
    };
}

function inlineTagSurfaceAvailable(surface) {
  if (surface === "review") {
    return reviewWorkspaceIsOpen()
      && state.review.mode === "queue"
      && state.review.selectedAssetIDs.size > 0;
  }
  return surface === "selection"
    ? state.selectionMode && state.selectedAssetIDs.size > 0
    : !state.selectionMode && Boolean(state.selectedAssetID);
}

function focusInlineTagCreationFromCommand(returnFocus = null) {
  const surface = state.selectionMode && state.selectedAssetIDs.size > 0
    ? "selection"
    : "single";
  if (!inlineTagSurfaceAvailable(surface)) return false;

  if (!galleryOverviewLayoutQuery.matches) {
    openGalleryInspectorOverlay({ returnFocus, focus: false });
  } else if (!state.layout.inspectorVisible) {
    setInspectorVisible(true);
  }

  const { form, input } = inlineTagSurfaceElements(surface);
  requestAnimationFrame(() => {
    if (!inlineTagSurfaceAvailable(surface)
      || form.classList.contains("hidden")
      || input.disabled) return;
    form.scrollIntoView({ block: "nearest" });
    input.focus({ preventScroll: true });
  });
  return true;
}

function setInlineTagError(surface, message = "") {
  const { error } = inlineTagSurfaceElements(surface);
  error.textContent = message;
  error.classList.toggle("hidden", !message);
}

function syncInlineTagCreationControls() {
  for (const surface of ["single", "selection", "review"]) {
    const { input, button } = inlineTagSurfaceElements(surface);
    const unavailable = !state.online
      || state.tagMutating
      || !inlineTagSurfaceAvailable(surface);
    input.disabled = unavailable;
    button.disabled = unavailable || !input.value.trim();
    input.setAttribute("aria-busy", String(state.tagMutating));
  }
}

function updateInlineTagDraft(surface) {
  const { input } = inlineTagSurfaceElements(surface);
  const pending = state.inlineTagOperations[surface];
  if (pending && pending.name !== input.value.trim()) {
    state.inlineTagOperations[surface] = null;
  }
  setInlineTagError(surface);
  syncInlineTagCreationControls();
}

function handleInlineTagEscape(event, surface) {
  if (event.key !== "Escape") return;
  const { input, error } = inlineTagSurfaceElements(surface);
  if (!input.value && error.classList.contains("hidden")) return;
  event.preventDefault();
  event.stopPropagation();
  input.value = "";
  state.inlineTagOperations[surface] = null;
  setInlineTagError(surface);
  syncInlineTagCreationControls();
}

async function performCreateTagAndApply({ name, assetIDs, operationID }) {
  const generation = state.workspaceGeneration;
  state.tagMutating = true;
  syncWriteActionControls();
  try {
    const result = await api("/v1/tags/create-and-apply", {
      method: "POST",
      body: JSON.stringify({ operationID, name, assetIDs }),
    });
    if (generation !== state.workspaceGeneration) return null;
    let synchronized = true;
    try {
      const tags = await api("/v1/tags");
      if (generation !== state.workspaceGeneration) return null;
      state.tags = tags;
      renderTagSelects();
      await loadAssets({
        preserveSelection: true,
        preserveUnchangedGrid: true,
        preserveLoadedWindow: true,
      });
      if (generation !== state.workspaceGeneration) return null;
      if (reviewWorkspaceIsOpen() && state.review.mode === "queue") {
        state.review.detail = null;
        state.review.tagAggregates = [];
        state.review.detailSelectionKey = null;
        state.review.detailRequestGeneration += 1;
        await Promise.all([
          loadReviewOverview({ throwOnError: true }),
          loadReviewQueue({
            preserveLoadedWindow: true,
            throwOnError: true,
          }),
        ]);
        await loadReviewInspectorDetail({ force: true, quiet: true });
      } else if (state.selectionMode) {
        elements.batchTagSelect.value = result.tagID;
        await loadSelectionAggregate();
      } else if (state.selectedAssetID) {
        await loadInspector(state.selectedAssetID, {
          preserveExisting: true,
        });
      }
      if (generation !== state.workspaceGeneration) return null;
    } catch {
      if (generation !== state.workspaceGeneration) return null;
      synchronized = false;
      void refreshWorkspace({
        quiet: true,
        kinds: ["tagsChanged", "assetsChanged"],
      });
    }
    return { result, synchronized };
  } finally {
    if (generation === state.workspaceGeneration) {
      state.tagMutating = false;
      syncWriteActionControls();
    }
  }
}

function announceCreatedTag(outcome) {
  const { result, synchronized } = outcome;
  undoToast(
    synchronized
      ? `已新增标签“${result.displayName}”并应用到 ${mediaItemCountText(result.appliedAssetCount)}`
      : `标签“${result.displayName}”已创建并应用，界面同步暂时失败，正在重试`,
    result.undoID
  );
}

async function createTagAndApply(event) {
  event.preventDefault();
  const name = elements.newTagName.value.trim();
  const assetIDs = currentTagTargetAssetIDs();
  if (!name || !assetIDs.length || !state.online || state.tagMutating) return;
  const operationID = state.newTagOperationID || crypto.randomUUID();
  state.newTagOperationID = operationID;
  elements.createTagButton.disabled = true;
  elements.createTagButton.textContent = "正在创建…";
  elements.newTagError.textContent = "";
  try {
    const outcome = await performCreateTagAndApply({ name, assetIDs, operationID });
    if (!outcome) return;
    const returnFocus = resolveNewTagReturnFocus();
    await returnFromNewTag({ restoreFocus: false });
    clearNewTagState();
    announceCreatedTag(outcome);
    restoreOverlayFocus(stableReturnFocusTarget(returnFocus, elements.sidebarNewTagButton));
  } catch (error) {
    if (elements.newTagDialog.open) {
      elements.newTagError.textContent = error.message || "新增标签失败";
    }
  } finally {
    elements.createTagButton.textContent = "创建并确认";
    syncWriteActionControls();
  }
}

async function createInlineTagAndApply(event, surface) {
  event.preventDefault();
  const { input, button } = inlineTagSurfaceElements(surface);
  const name = input.value.trim();
  const assetIDs = currentTagTargetAssetIDs();
  if (!name || !assetIDs.length || !state.online || state.tagMutating) return;
  const pending = state.inlineTagOperations[surface];
  const operationID = pending?.name === name ? pending.operationID : crypto.randomUUID();
  state.inlineTagOperations[surface] = { name, operationID };
  setInlineTagError(surface);
  button.textContent = "…";
  try {
    const outcome = await performCreateTagAndApply({ name, assetIDs, operationID });
    if (!outcome) return;
    state.inlineTagOperations[surface] = null;
    input.value = "";
    setInlineTagError(surface);
    announceCreatedTag(outcome);
    requestAnimationFrame(() => {
      if (inlineTagSurfaceAvailable(surface) && input.isConnected) {
        input.focus({ preventScroll: true });
      }
    });
  } catch (error) {
    setInlineTagError(surface, error.message || "新增标签失败");
  } finally {
    button.textContent = "＋";
    syncInlineTagCreationControls();
  }
}

function renderSelectionBar({ updateInspector = true } = {}) {
  const count = state.selectedAssetIDs.size;
  elements.selectionSummary.textContent = `已选择 ${count} 项`;
  elements.selectionInspectorOverlayButton.disabled = count === 0;
  elements.selectAllLoadedButton.textContent = count === state.assets.length && count > 0
    ? "取消全选"
    : "全选已载入";
  document.querySelectorAll(".batch-action").forEach((button) => {
    button.disabled = !state.online
      || state.tagMutating
      || count === 0
      || !elements.batchTagSelect.value;
  });
  if (!count) elements.batchAggregate.textContent = `选择${currentMediaNoun()}后可查看标签汇总`;
  renderFavoriteControls();
  renderGalleryRemovalControls();
  renderPersonalModelControls();
  renderEmbeddingPreparation();
  renderSampleSuggestions();
  syncInlineTagCreationControls();
  if (updateInspector) renderInspectorSurface();
}

function activeEmbeddingPreparation() {
  return state.embeddingPreparation.activities.find((activity) => activity.phase === "running")
    || null;
}

function embeddingPreparationTerminalText(activity) {
  if (activity.phase === "cancelled") return "照片特征准备已停止";
  if (activity.phase === "failed") {
    return activity.errorCode === "modelUnavailable"
      ? "个人模型特征当前不可用"
      : "照片特征准备未完成";
  }
  const parts = [`新准备 ${activity.preparedCount || 0}`, `已有缓存 ${activity.cachedCount || 0}`];
  if (activity.cloudOnlyCount) parts.push(`仅云端 ${activity.cloudOnlyCount}`);
  if (activity.failedCount) parts.push(`失败 ${activity.failedCount}`);
  return `照片特征准备完成 · ${parts.join(" · ")}`;
}

function embeddingPreparationFocusCandidates(preferred) {
  return [
    preferred,
    elements.toolbarPrepareSelectedFeaturesButton,
    elements.prepareSelectedFeaturesButton,
    elements.selectionInspectorPrepareFeaturesButton,
    elements.preparePersonalSelectionButton,
  ].filter((button, index, buttons) => button && buttons.indexOf(button) === index);
}

function restoreEmbeddingPreparationFocus() {
  const preparation = state.embeddingPreparation;
  const active = document.activeElement;
  const shouldRestore = !preparation.cancelFocus
    || active === preparation.cancelFocus
    || active === document.body;
  const target = shouldRestore
    ? embeddingPreparationFocusCandidates(preparation.returnFocus).find(
      (button) => button.isConnected
        && !button.disabled
        && button.getClientRects().length > 0
    )
    : null;
  preparation.returnFocus = null;
  preparation.cancelFocus = null;
  target?.focus({ preventScroll: true });
}

function focusEmbeddingPreparationCancel(preferred) {
  const preparation = state.embeddingPreparation;
  if (!activeEmbeddingPreparation() || preparation.returnFocus !== preferred) return;
  const inspectorPreferred = preferred === elements.selectionInspectorPrepareFeaturesButton;
  const candidates = inspectorPreferred
    ? [elements.selectionInspectorCancelPreparationButton, elements.cancelEmbeddingPreparationButton]
    : [elements.cancelEmbeddingPreparationButton, elements.selectionInspectorCancelPreparationButton];
  const target = candidates.find(
    (button) => !button.disabled && button.getClientRects().length > 0
  );
  preparation.cancelFocus = target || null;
  target?.focus({ preventScroll: true });
}

function renderEmbeddingPreparation() {
  const preparation = state.embeddingPreparation;
  const activity = activeEmbeddingPreparation();
  const count = state.selectedAssetIDs.size;
  const prepareDisabled = !state.online
    || !preparation.isAvailable
    || preparation.loading
    || preparation.submitting
    || Boolean(activity)
    || count === 0;
  for (const button of [
    elements.prepareSelectedFeaturesButton,
    elements.selectionInspectorPrepareFeaturesButton,
    elements.toolbarPrepareSelectedFeaturesButton,
    elements.preparePersonalSelectionButton,
  ]) {
    button.disabled = prepareDisabled;
  }
  const findDisabled = !state.online
    || !supportsLibrarySlimming()
    || state.findingSimilarFromSelection
    || count === 0;
  for (const button of [
    elements.findSimilarSelectionButton,
    elements.selectionInspectorFindSimilarButton,
    elements.toolbarFindSimilarSelectionButton,
    elements.findSimilarPersonalSelectionButton,
  ]) {
    button.disabled = findDisabled;
  }
  elements.prepareSelectedFeaturesButton.textContent = preparation.submitting
    ? "正在交给 Mac…"
    : "准备特征";
  elements.selectionInspectorPrepareFeaturesButton.textContent =
    elements.prepareSelectedFeaturesButton.textContent;
  const prepareRunning = preparation.submitting || Boolean(activity);
  syncPersonalModelActionPresentation(elements.toolbarPrepareSelectedFeaturesButton, {
    running: prepareRunning,
    idleTitle: "准备选中照片特征",
    runningTitle: preparation.submitting ? "正在交给 Mac…" : "正在准备…",
    idleIcon: "✦",
    busy: prepareRunning,
    busySummary: "正在准备所选项目特征",
  });
  syncPersonalModelActionPresentation(elements.preparePersonalSelectionButton, {
    running: prepareRunning,
    idleTitle: "准备选中照片特征",
    runningTitle: preparation.submitting ? "正在交给 Mac…" : "正在准备…",
    idleIcon: "✦",
    busy: prepareRunning,
    busySummary: "正在准备所选项目特征",
  });
  elements.preparePersonalSelectionTitle.textContent = prepareRunning
    ? (preparation.submitting ? "正在交给 Mac…" : "正在准备选中照片特征…")
    : "准备选中照片特征";
  elements.embeddingPreparationStatus.classList.toggle("hidden", !activity);
  elements.cancelEmbeddingPreparationButton.classList.toggle("hidden", !activity);
  elements.selectionInspectorToolStatus.classList.toggle("hidden", !activity);
  elements.selectionInspectorCancelPreparationButton.classList.toggle("hidden", !activity);
  elements.cancelEmbeddingPreparationButton.disabled = !state.online || preparation.cancelling;
  elements.selectionInspectorCancelPreparationButton.disabled =
    elements.cancelEmbeddingPreparationButton.disabled;
  elements.cancelEmbeddingPreparationButton.textContent = preparation.cancelling
    ? "正在停止…"
    : "停止准备";
  elements.selectionInspectorCancelPreparationButton.textContent = preparation.cancelling
    ? "正在停止…"
    : "停止";
  if (activity) {
    const status = `正在准备 ${activity.completedUnitCount}/${activity.totalUnitCount}`;
    elements.embeddingPreparationStatus.textContent = status;
    elements.selectionInspectorToolStatus.textContent = status;
  }
  requestAnimationFrame(syncPersonalModelToolbarPresentation);
}

function scheduleEmbeddingPreparationPoll() {
  clearTimeout(state.embeddingPreparation.pollTimer);
  state.embeddingPreparation.pollTimer = null;
  if (!activeEmbeddingPreparation()) return;
  state.embeddingPreparation.pollTimer = setTimeout(
    () => loadEmbeddingPreparation({ quiet: true }),
    900
  );
}

async function loadEmbeddingPreparation({ quiet = false } = {}) {
  const preparation = state.embeddingPreparation;
  const generation = ++preparation.requestGeneration;
  let completedReturnFocus = false;
  const activeIDs = new Set(
    preparation.activities.filter((activity) => activity.phase === "running")
      .map((activity) => activity.operationID)
  );
  preparation.loading = true;
  try {
    const query = new URLSearchParams({ mediaKind: state.mediaKind });
    const snapshot = await api(`/v1/embedding-preparation?${query}`);
    if (generation !== preparation.requestGeneration) return;
    preparation.isAvailable = Boolean(snapshot.isAvailable);
    preparation.activities = snapshot.activities || [];
    const terminal = preparation.activities.find((activity) =>
      activeIDs.has(activity.operationID) && activity.phase !== "running"
    );
    if (terminal && !preparation.seenTerminalOperationIDs.has(terminal.operationID)) {
      preparation.seenTerminalOperationIDs.add(terminal.operationID);
      toast(embeddingPreparationTerminalText(terminal));
      completedReturnFocus = true;
    }
  } catch (error) {
    if (generation === preparation.requestGeneration && !quiet) {
      toast(error.message || "无法读取照片特征状态");
    }
  } finally {
    if (generation === preparation.requestGeneration) {
      preparation.loading = false;
      renderEmbeddingPreparation();
      scheduleEmbeddingPreparationPoll();
      if (completedReturnFocus) {
        requestAnimationFrame(restoreEmbeddingPreparationFocus);
      }
    }
  }
}

async function prepareSelectedFeatures(returnFocus = document.activeElement) {
  const preparation = state.embeddingPreparation;
  const assetIDs = [...state.selectedAssetIDs];
  if (!assetIDs.length || preparation.submitting || activeEmbeddingPreparation()) return;
  preparation.returnFocus = returnFocus instanceof HTMLElement ? returnFocus : null;
  preparation.cancelFocus = null;
  let started = false;
  preparation.submitting = true;
  renderEmbeddingPreparation();
  try {
    const response = await api("/v1/embedding-preparation/requests", {
      method: "POST",
      body: JSON.stringify({
        operationID: crypto.randomUUID(),
        mediaKind: state.mediaKind,
        assetIDs,
      }),
    });
    preparation.activities = [
      response.activity,
      ...preparation.activities.filter(
        (activity) => activity.operationID !== response.activity.operationID
      ),
    ];
    started = true;
    toast(`已交给 Mac 准备 ${assetIDs.length} 项特征`);
  } catch (error) {
    toast(error.message || "无法准备所选项目特征");
  } finally {
    preparation.submitting = false;
    renderEmbeddingPreparation();
    scheduleEmbeddingPreparationPoll();
    if (started) {
      requestAnimationFrame(() => focusEmbeddingPreparationCancel(returnFocus));
    } else {
      requestAnimationFrame(restoreEmbeddingPreparationFocus);
    }
  }
}

async function cancelEmbeddingPreparation() {
  const preparation = state.embeddingPreparation;
  const activity = activeEmbeddingPreparation();
  if (!activity || preparation.cancelling) return;
  preparation.cancelling = true;
  renderEmbeddingPreparation();
  try {
    const response = await api(
      `/v1/embedding-preparation/requests/${activity.operationID}/actions`,
      { method: "POST", body: JSON.stringify({ action: "cancel" }) }
    );
    preparation.activities = preparation.activities.map((item) =>
      item.operationID === response.activity.operationID ? response.activity : item
    );
    state.embeddingPreparation.seenTerminalOperationIDs.add(response.activity.operationID);
    toast(embeddingPreparationTerminalText(response.activity));
  } catch (error) {
    toast(error.message || "无法停止照片特征准备");
  } finally {
    preparation.cancelling = false;
    renderEmbeddingPreparation();
    scheduleEmbeddingPreparationPoll();
    if (!activeEmbeddingPreparation()) {
      requestAnimationFrame(restoreEmbeddingPreparationFocus);
    }
  }
}

function activeSampleSuggestion() {
  return state.sampleSuggestions.activities.find((activity) => activity.phase === "running")
    || null;
}

function sampleSuggestionTerminalText(activity) {
  if (activity.phase === "cancelled") return "个人建议抽检已停止";
  if (activity.phase === "failed") {
    return {
      personalUnavailable: "还没有可用的个人模型，请先训练个人模型",
      modelUnavailable: "个人模型当前不可用",
      identityMismatch: "个人模型与当前图库不匹配，请重新训练",
      embeddingUnavailable: "照片特征准备失败",
    }[activity.errorCode] || "个人建议生成未完成";
  }
  return `已抽检 ${activity.totalUnitCount} 项 · 写入 ${activity.suggestedCount || 0} 条建议`
    + (activity.skippedCount ? ` · 跳过 ${activity.skippedCount}` : "");
}

function renderReviewLocalModelStatus() {
  const library = state.librarySuggestions;
  const snapshot = library.snapshot;
  const manager = state.generalSettings;
  const model = manager.snapshot?.localModel || null;
  const badge = elements.reviewLocalModelStateBadge;
  const status = elements.reviewLocalModelStatus;
  const detail = elements.reviewLocalModelDetail;
  const refresh = elements.refreshReviewModelStatusButton;
  const refreshing = library.loading || manager.loading || state.sampleSuggestions.loading;
  refresh.disabled = !state.online || refreshing;
  refresh.textContent = refreshing ? "正在刷新…" : "↻ 刷新模型状态";
  configurePersistentHelp(refresh, {
    title: refreshing ? "正在刷新模型状态" : "刷新模型状态",
    detail: "重新检查这台 Mac 的本地模型服务、个人模型和建议任务；不会启动服务、下载模型或读取原始媒体。",
    kind: "review",
  });

  if (supportsLibrarySuggestions()) {
    if (!snapshot) {
      badge.textContent = library.loading ? "读取中" : "尚未读取";
      badge.dataset.state = library.loading ? "validating" : "unchecked";
      status.textContent = library.loading ? "正在检查本地模型服务…" : "模型状态尚未读取。";
      detail.textContent = "模型只在这台 Mac 内运行，网页不会下载模型或读取原始照片。";
    } else {
      const service = snapshot.service || { state: "unavailable" };
      badge.textContent = {
        unchecked: "尚未检查",
        ready: "服务已就绪",
        degraded: "模型未加载",
        unavailable: "服务未运行",
      }[service.state] || "状态未知";
      badge.dataset.state = service.state === "degraded" ? "validating" : service.state;
      status.textContent = {
        unchecked: "本地模型服务尚未检查。",
        ready: `已就绪 · ${service.provider || "本地模型"} / ${service.modelID || "默认模型"}`,
        degraded: "已连接，但模型尚未加载。",
        unavailable: `服务未运行；现有${currentMediaNoun()}、标签和 Feature Print 不受影响。`,
      }[service.state] || "模型服务状态未知。";
      detail.textContent = service.serviceVersion
        ? `服务版本 ${service.serviceVersion} · 所有模型计算仅在这台 Mac 上执行。`
        : "所有模型计算仅在这台 Mac 上执行；网页只读取任务状态。";
    }
    renderLibrarySuggestionCards();
    return;
  }

  if (!supportsGeneralSettings()) {
    badge.textContent = "Host 不支持";
    badge.dataset.state = "unavailable";
    status.textContent = "当前 Mac Host 无法提供 App 内模型状态。";
    detail.textContent = "个人建议任务仍以 Host 返回的实际可用性为准。";
    return;
  }
  if (!model) {
    badge.textContent = manager.loading ? "读取中" : "尚未读取";
    badge.dataset.state = manager.loading ? "validating" : "unchecked";
    status.textContent = manager.loading ? "正在读取 Mac 模型状态…" : "模型状态尚未读取。";
    detail.textContent = "模型只在这台 Mac 内运行，网页不会下载模型或读取原始照片。";
    return;
  }

  badge.textContent = generalSettingsModelStateText(model);
  badge.dataset.state = model.state;
  status.textContent = {
    disabled: "App 内模型已关闭。",
    validating: "正在校验 App 内模型…",
    ready: `已就绪 · ${model.modelName}`,
    unavailable: `${model.modelName} 当前不可用。`,
  }[model.state] || "模型状态未知。";
  detail.textContent = `${model.runtimeName} · ${model.detail}`;
  elements.standardLibrarySuggestionCard.classList.add("hidden");
  elements.personalLibrarySuggestionPath.textContent = "App 内抽检";
}

function activeLibrarySuggestionJob(job) {
  return Boolean(job && ["pending", "running", "paused", "retryableFailed"].includes(job.state));
}

function librarySuggestionJobStatus(job, idleText) {
  if (!job) return idleText;
  const counts = `已检 ${job.checkedCount || 0}`
    + (job.totalCount == null ? "" : ` / ${job.totalCount}`)
    + ` · 建议 ${job.suggestedCount || 0}`
    + (job.skippedCount ? ` · 跳过 ${job.skippedCount}` : "");
  return {
    pending: `等待 · ${counts}`,
    running: counts,
    paused: `已暂停 · ${counts}`,
    retryableFailed: `将重试 · ${counts}`,
    completed: `完成 · ${counts}`,
    cancelled: `已取消 · ${counts}`,
    terminalFailed: `结果未通过校验，已安全忽略 · ${counts}`,
  }[job.state] || counts;
}

function renderLibrarySuggestionProgress(progress, bar, job) {
  const visible = activeLibrarySuggestionJob(job);
  progress.classList.toggle("hidden", !visible);
  const total = Math.max(0, Number(job?.totalCount) || 0);
  const checked = Math.max(0, Number(job?.checkedCount) || 0);
  const percent = total > 0 ? Math.min(100, Math.round((checked / total) * 100)) : 0;
  progress.setAttribute("aria-valuenow", String(percent));
  progress.dataset.state = job?.state || "idle";
  bar.style.width = `${percent}%`;
}

function librarySuggestionJobActionKey(jobID, action) {
  return `${jobID}:${["pause", "resume"].includes(action) ? "primary" : action}`;
}

function syncLibrarySuggestionJobAction(button, job, action) {
  const text = jobActionText(action);
  button.type = "button";
  button.className = "button button-plain review-local-model-job-action job-action write-action";
  button.dataset.librarySuggestionActionKey = librarySuggestionJobActionKey(job.jobID, action);
  button.dataset.librarySuggestionJobId = job.jobID;
  button.dataset.jobId = job.jobID;
  button.dataset.action = action;
  button.disabled = !state.online || state.jobMutatingIDs.has(job.jobID);
  let label = button.querySelector(":scope > [data-library-suggestion-action-part=label]");
  if (!label) {
    label = document.createElement("span");
    label.dataset.librarySuggestionActionPart = "label";
    button.append(label);
  }
  if (label.textContent !== text) label.textContent = text;
  configurePersistentHelp(button, {
    title: `${text}建议任务`,
    detail: {
      pause: "暂停当前全库建议任务并保存已完成进度；已经写入审核队列的建议会保留。",
      resume: "从保存的进度继续当前全库建议任务；范围仍使用任务创建时冻结的来源。",
      cancel: "取消当前全库建议任务；已经写入审核队列的建议不会被删除。",
    }[action] || "控制当前全库建议任务；任务状态以 Mac 为准。",
    kind: "review",
  });
}

function librarySuggestionTrackForActionContainer(container) {
  if (container === elements.standardLibrarySuggestionActions) return "standard";
  if (container === elements.personalLibrarySuggestionActions) return "personal";
  return null;
}

function restorePendingLibrarySuggestionTerminalFocus() {
  const pending = state.librarySuggestions.pendingTerminalFocus;
  if (!pending) return false;
  if (elements.reviewWorkspace.classList.contains("hidden")) {
    state.librarySuggestions.pendingTerminalFocus = null;
    return false;
  }
  const active = document.activeElement;
  if (active !== pending.origin
    && active !== document.body
    && active !== document.documentElement) {
    state.librarySuggestions.pendingTerminalFocus = null;
    return false;
  }
  const snapshot = state.librarySuggestions.snapshot;
  const job = pending.track === "standard"
    ? snapshot?.standardJob
    : snapshot?.personalJob;
  if (state.librarySuggestions.loading || activeLibrarySuggestionJob(job)) return false;
  const target = pending.track === "standard"
    ? elements.generateStandardLibrarySuggestionsButton
    : elements.generateLibrarySuggestionsButton;
  if (target.disabled || target.offsetParent === null) return false;
  state.librarySuggestions.pendingTerminalFocus = null;
  target.focus({ preventScroll: true });
  return true;
}

function renderLibrarySuggestionJobActions(container, job, fallbackFocus) {
  const active = container.contains(document.activeElement) ? document.activeElement : null;
  const activeKey = active?.dataset.librarySuggestionActionKey || null;
  const existing = new Map(
    [...container.querySelectorAll(":scope > [data-library-suggestion-action-key]")]
      .map((button) => [button.dataset.librarySuggestionActionKey, button])
  );
  const staticControls = [...container.children].filter(
    (control) => !control.matches("[data-library-suggestion-action-key]")
  );
  const wanted = [];
  for (const action of job?.availableActions || []) {
    const key = librarySuggestionJobActionKey(job.jobID, action);
    const button = existing.get(key) || document.createElement("button");
    syncLibrarySuggestionJobAction(button, job, action);
    wanted.push(button);
  }
  reconcileStableChildren(container, [...staticControls, ...wanted]);
  if (!activeKey || active.isConnected) return;
  requestAnimationFrame(() => {
    if (document.activeElement !== document.body
      && document.activeElement !== document.documentElement) return;
    const sameAction = container.querySelector(
      `[data-library-suggestion-action-key="${CSS.escape(activeKey)}"]:not(:disabled)`
    );
    const target = sameAction
      || container.querySelector("[data-library-suggestion-action-key]:not(:disabled)")
      || (!fallbackFocus?.disabled && fallbackFocus.offsetParent !== null ? fallbackFocus : null)
      || (state.librarySuggestions.pendingTerminalFocus?.track
        !== librarySuggestionTrackForActionContainer(container)
        ? elements.refreshReviewModelStatusButton
        : null);
    target?.focus({ preventScroll: true });
  });
}

function restoreLibrarySuggestionJobActionFocus(
  container,
  actionKey,
  originalButton,
  fallbackFocus
) {
  requestAnimationFrame(() => {
    if (elements.reviewWorkspace.classList.contains("hidden")) return;
    const active = document.activeElement;
    if (active !== originalButton
      && active !== document.body
      && active !== document.documentElement) return;
    const pendingTerminal = state.librarySuggestions.pendingTerminalFocus;
    const projectedJob = pendingTerminal?.jobID === originalButton.dataset.librarySuggestionJobId
      ? state.jobs.find((job) => job.id === pendingTerminal.jobID)
      : null;
    const projectedTerminal = projectedJob
      && !["pending", "running", "paused", "retryableFailed"].includes(projectedJob.state);
    if (pendingTerminal?.origin === originalButton && projectedTerminal) {
      restorePendingLibrarySuggestionTerminalFocus();
      return;
    }
    if (pendingTerminal?.origin === originalButton) {
      state.librarySuggestions.pendingTerminalFocus = null;
    }
    const target = container.querySelector(
      `[data-library-suggestion-action-key="${CSS.escape(actionKey)}"]:not(:disabled)`
    ) || (!fallbackFocus?.disabled && fallbackFocus.offsetParent !== null
      ? fallbackFocus
      : null);
    target?.focus({ preventScroll: true });
  });
}

function renderLibrarySuggestionCards() {
  renderPersonalModelControls();
  const library = state.librarySuggestions;
  const snapshot = library.snapshot;
  const sourceIDs = resolvedReviewSourceFilter();
  const hasReviewSource = sourceIDs == null || sourceIDs.length > 0;
  const standardJob = snapshot?.standardJob || null;
  const personalJob = snapshot?.personalJob || null;
  const anyJobActive = activeLibrarySuggestionJob(standardJob)
    || activeLibrarySuggestionJob(personalJob);

  const showStandard = Boolean(snapshot?.standardAvailable || standardJob);
  elements.standardLibrarySuggestionCard.classList.toggle("hidden", !showStandard);
  elements.standardLibrarySuggestionStatus.textContent = librarySuggestionJobStatus(
    standardJob,
    snapshot?.standardAvailable
      ? "把标准模型建议加入审核队列。"
      : "当前 Mac 未提供标准模型全库建议。"
  );
  renderLibrarySuggestionProgress(
    elements.standardLibrarySuggestionProgress,
    elements.standardLibrarySuggestionProgressBar,
    standardJob
  );
  elements.generateStandardLibrarySuggestionsButton.disabled = !state.online
    || library.loading
    || library.launchingTrack != null
    || !snapshot?.standardAvailable
    || !hasReviewSource
    || anyJobActive;
  elements.generateStandardLibrarySuggestionsButton.textContent =
    library.launchingTrack === "standard"
      ? "正在交给 Mac…"
      : (activeLibrarySuggestionJob(standardJob) ? "正在扫描全库" : "扫描全库");
  elements.generateStandardLibrarySuggestionsButton.title = hasReviewSource
    ? "按顶部审核来源范围使用 Mac 本地标准模型扫描全库"
    : "请先在顶部选择至少一个审核来源";
  configurePersistentHelp(elements.generateStandardLibrarySuggestionsButton, {
    detail: hasReviewSource
      ? "按顶部审核来源范围创建标准模型全库扫描任务；只在 Mac 本地分析可读取预览，结果进入待审核队列。"
      : "先在顶部选择至少一个审核来源；未选择来源时不会创建任务。",
    kind: "review",
  });
  renderLibrarySuggestionJobActions(
    elements.standardLibrarySuggestionActions,
    standardJob,
    elements.generateStandardLibrarySuggestionsButton
  );

  const personalMode = snapshot?.personalMode || "unavailable";
  if (personalMode === "sample") {
    elements.personalLibrarySuggestionPath.textContent = "App 内抽检";
    renderLibrarySuggestionJobActions(
      elements.personalLibrarySuggestionActions,
      null,
      elements.generateLibrarySuggestionsButton
    );
    restorePendingLibrarySuggestionTerminalFocus();
    return;
  }

  elements.personalLibrarySuggestionPath.textContent = personalMode === "fullLibrary"
    ? "全库建议"
    : "当前不可用";
  elements.cancelSampleSuggestionsButton.classList.add("hidden");
  elements.sampleSuggestionReviewStatus.textContent = librarySuggestionJobStatus(
    personalJob,
    personalMode === "fullLibrary"
      ? "把当前个人模型建议加入审核队列。"
      : "当前 Mac 没有可用的个人模型建议路径。"
  );
  renderLibrarySuggestionProgress(
    elements.sampleSuggestionReviewProgress,
    elements.sampleSuggestionReviewProgressBar,
    personalJob
  );
  elements.generateLibrarySuggestionsButton.disabled = !state.online
    || library.loading
    || library.launchingTrack != null
    || personalMode !== "fullLibrary"
    || !hasReviewSource
    || anyJobActive;
  elements.generateLibrarySuggestionsButton.textContent = library.launchingTrack === "personal"
    ? "正在交给 Mac…"
    : (activeLibrarySuggestionJob(personalJob) ? "正在扫描全库" : "扫描全库");
  elements.generateLibrarySuggestionsButton.setAttribute(
    "aria-label",
    "使用个人模型扫描全库"
  );
  elements.generateLibrarySuggestionsButton.title = hasReviewSource
    ? "按顶部审核来源范围使用 Mac 本地个人模型扫描全库"
    : "请先在顶部选择至少一个审核来源";
  configurePersistentHelp(elements.generateLibrarySuggestionsButton, {
    detail: hasReviewSource
      ? "按顶部审核来源范围创建个人模型全库扫描任务；任务只在 Mac 本地运行，结果进入待审核队列。"
      : "先在顶部选择至少一个审核来源；未选择来源时不会创建任务。",
    kind: "review",
  });
  renderLibrarySuggestionJobActions(
    elements.personalLibrarySuggestionActions,
    personalJob,
    elements.generateLibrarySuggestionsButton
  );
  restorePendingLibrarySuggestionTerminalFocus();
}

function renderSampleSuggestions() {
  renderPersonalModelControls();
  const suggestions = state.sampleSuggestions;
  const activity = activeSampleSuggestion();
  const selectedCount = state.selectedAssetIDs.size;
  const sourceIDs = resolvedReviewSourceFilter();
  const hasReviewSource = sourceIDs == null || sourceIDs.length > 0;
  const available = state.online
    && state.mediaKind === "image"
    && suggestions.isAvailable
    && hasReviewSource;
  const locked = suggestions.loading || suggestions.submitting || Boolean(activity);
  elements.generateSelectedSuggestionsButton.disabled = !available || locked || selectedCount === 0;
  elements.selectionInspectorGenerateSuggestionsButton.disabled =
    elements.generateSelectedSuggestionsButton.disabled;
  elements.generateLibrarySuggestionsButton.disabled = !available || locked;
  elements.generateSelectedSuggestionsButton.textContent = suggestions.submitting
    ? "正在交给 Mac…"
    : "生成建议";
  elements.selectionInspectorGenerateSuggestionsButton.textContent =
    elements.generateSelectedSuggestionsButton.textContent;
  elements.generateLibrarySuggestionsButton.textContent = suggestions.submitting
    ? "正在开始抽检…"
    : `抽 ${suggestions.maximumSampleCount} 张生成建议`;
  elements.generateLibrarySuggestionsButton.setAttribute(
    "aria-label",
    "抽取样本并生成建议"
  );
  elements.generateLibrarySuggestionsButton.title = hasReviewSource
    ? "按顶部来源筛选抽取照片，并使用 Mac 的 App 内个人模型生成建议"
    : "请先在顶部选择至少一个审核来源";
  configurePersistentHelp(elements.generateLibrarySuggestionsButton, {
    detail: hasReviewSource
      ? `按顶部来源范围抽取最多 ${suggestions.maximumSampleCount} 张照片，在 Mac 本地生成个人建议并加入审核队列。`
      : "先在顶部选择至少一个审核来源；未选择来源时不会开始抽检。",
    kind: "review",
  });
  elements.cancelSampleSuggestionsButton.classList.toggle("hidden", !activity);
  elements.cancelSampleSuggestionsButton.disabled = !state.online || suggestions.cancelling;
  elements.cancelSampleSuggestionsButton.textContent = suggestions.cancelling
    ? "正在停止…"
    : "停止抽检";
  configurePersistentHelp(elements.cancelSampleSuggestionsButton, {
    title: suggestions.cancelling ? "正在停止个人建议抽检" : "停止个人建议抽检",
    detail: "停止当前抽检任务；已经写入待审核队列的建议会保留，原始照片和个人模型不会改变。",
    kind: "review",
  });
  if (activity) {
    const total = Math.max(0, Number(activity.totalUnitCount) || 0);
    const completed = Math.max(0, Number(activity.completedUnitCount) || 0);
    const percent = total > 0 ? Math.min(100, Math.round((completed / total) * 100)) : 0;
    const status = `已检 ${completed} / ${total} · 建议 ${activity.suggestedCount || 0}`
      + (activity.skippedCount ? ` · 跳过 ${activity.skippedCount}` : "");
    elements.sampleSuggestionReviewStatus.textContent = status;
    elements.sampleSuggestionReviewProgress.classList.remove("hidden");
    elements.sampleSuggestionReviewProgress.setAttribute("aria-valuenow", String(percent));
    elements.sampleSuggestionReviewProgressBar.style.width = `${percent}%`;
    if (!activeEmbeddingPreparation()) {
      elements.embeddingPreparationStatus.classList.remove("hidden");
      elements.embeddingPreparationStatus.textContent = `Mac 正在抽检 ${completed}/${total}`;
      elements.selectionInspectorToolStatus.classList.remove("hidden");
      elements.selectionInspectorToolStatus.textContent = `Mac 正在抽检 ${completed}/${total}`;
    }
  } else {
    elements.sampleSuggestionReviewProgress.classList.add("hidden");
    elements.sampleSuggestionReviewProgress.setAttribute("aria-valuenow", "0");
    elements.sampleSuggestionReviewProgressBar.style.width = "0%";
    if (!hasReviewSource) {
      elements.sampleSuggestionReviewStatus.textContent = "没有选择审核来源，暂不能抽检。";
    } else if (suggestions.loading) {
      elements.sampleSuggestionReviewStatus.textContent = "正在读取个人建议任务…";
    } else if (!suggestions.isAvailable || state.mediaKind !== "image") {
      elements.sampleSuggestionReviewStatus.textContent = "当前媒体类型暂无可用的个人模型抽检。";
    } else {
      elements.sampleSuggestionReviewStatus.textContent =
        `抽检最多 ${suggestions.maximumSampleCount} 张加入审核队列。`;
    }
  }
  renderReviewLocalModelStatus();
}

function scheduleSampleSuggestionPoll() {
  clearTimeout(state.sampleSuggestions.pollTimer);
  state.sampleSuggestions.pollTimer = null;
  if (!activeSampleSuggestion()) return;
  state.sampleSuggestions.pollTimer = setTimeout(
    () => loadSampleSuggestions({ quiet: true }),
    900
  );
}

async function loadSampleSuggestions({ quiet = false } = {}) {
  const suggestions = state.sampleSuggestions;
  const generation = ++suggestions.requestGeneration;
  const activeIDs = new Set(
    suggestions.activities.filter((activity) => activity.phase === "running")
      .map((activity) => activity.operationID)
  );
  suggestions.loading = true;
  try {
    const query = new URLSearchParams({ mediaKind: state.mediaKind });
    const snapshot = await api(`/v1/sample-suggestions?${query}`);
    if (generation !== suggestions.requestGeneration) return;
    suggestions.isAvailable = Boolean(snapshot.isAvailable);
    suggestions.maximumSampleCount = snapshot.maximumSampleCount || 500;
    suggestions.activities = snapshot.activities || [];
    const terminal = suggestions.activities.find((activity) =>
      activeIDs.has(activity.operationID) && activity.phase !== "running"
    );
    if (terminal && !suggestions.seenTerminalOperationIDs.has(terminal.operationID)) {
      suggestions.seenTerminalOperationIDs.add(terminal.operationID);
      toast(sampleSuggestionTerminalText(terminal));
      if (terminal.phase === "completed"
        && !elements.reviewWorkspace.classList.contains("hidden")) {
        await loadReviewOverview();
      }
    }
  } catch (error) {
    if (generation === suggestions.requestGeneration && !quiet) {
      toast(error.message || "无法读取个人建议抽检状态");
    }
  } finally {
    if (generation === suggestions.requestGeneration) {
      suggestions.loading = false;
      renderSampleSuggestions();
      scheduleSampleSuggestionPoll();
    }
  }
}

function selectedAssetIDsInGridOrder(limit) {
  const inGrid = state.assets
    .filter((asset) => state.selectedAssetIDs.has(asset.id))
    .map((asset) => asset.id);
  const included = new Set(inGrid);
  const remaining = [...state.selectedAssetIDs]
    .filter((assetID) => !included.has(assetID))
    .sort();
  return [...inGrid, ...remaining].slice(0, limit);
}

async function generateSampleSuggestions({ useSelection = false } = {}) {
  const suggestions = state.sampleSuggestions;
  const sourceIDs = useSelection ? null : resolvedReviewSourceFilter();
  const assetIDs = useSelection
    ? selectedAssetIDsInGridOrder(suggestions.maximumSampleCount)
    : [];
  if ((useSelection && !assetIDs.length)
    || (!useSelection && Array.isArray(sourceIDs) && sourceIDs.length === 0)
    || suggestions.submitting
    || activeSampleSuggestion()) return;
  suggestions.submitting = true;
  renderSampleSuggestions();
  try {
    const response = await api("/v1/sample-suggestions/requests", {
      method: "POST",
      body: JSON.stringify({
        operationID: crypto.randomUUID(),
        mediaKind: state.mediaKind,
        assetIDs,
        sourceIDs,
      }),
    });
    suggestions.activities = [
      response.activity,
      ...suggestions.activities.filter(
        (activity) => activity.operationID !== response.activity.operationID
      ),
    ];
    toast(useSelection
      ? `已交给 Mac 为 ${assetIDs.length} 项生成建议`
      : `已交给 Mac${sourceIDs == null ? "从全部来源" : `从 ${sourceIDs.length} 个来源`}`
        + `抽取最多 ${suggestions.maximumSampleCount} 张生成建议`);
    await openReviewWorkspace();
  } catch (error) {
    toast(error.message || "无法开始个人建议抽检");
  } finally {
    suggestions.submitting = false;
    renderSampleSuggestions();
    scheduleSampleSuggestionPoll();
  }
}

function activeLibrarySuggestionJobs() {
  const snapshot = state.librarySuggestions.snapshot;
  return [snapshot?.standardJob, snapshot?.personalJob].filter(activeLibrarySuggestionJob);
}

function scheduleLibrarySuggestionPoll() {
  clearTimeout(state.librarySuggestions.pollTimer);
  state.librarySuggestions.pollTimer = null;
  if (!activeLibrarySuggestionJobs().length) return;
  state.librarySuggestions.pollTimer = setTimeout(
    () => loadLibrarySuggestions({ quiet: true }),
    900
  );
}

async function loadLibrarySuggestions({ quiet = false, refreshServiceHealth = false } = {}) {
  if (!supportsLibrarySuggestions()) {
    state.librarySuggestions.snapshot = null;
    renderReviewLocalModelStatus();
    return;
  }
  const library = state.librarySuggestions;
  const generation = ++library.requestGeneration;
  const previouslyActive = new Set(activeLibrarySuggestionJobs().map((job) => job.jobID));
  library.loading = true;
  renderReviewLocalModelStatus();
  try {
    const query = new URLSearchParams({ mediaKind: state.mediaKind });
    if (refreshServiceHealth) query.set("refreshServiceHealth", "1");
    const snapshot = await api(`/v1/library-suggestions?${query}`);
    if (generation !== library.requestGeneration) return;
    library.snapshot = snapshot;
    const jobs = [snapshot.standardJob, snapshot.personalJob].filter(Boolean);
    const terminal = jobs.find((job) => previouslyActive.has(job.jobID)
      && !activeLibrarySuggestionJob(job)
      && !library.terminalJobIDs.has(job.jobID));
    if (terminal) {
      library.terminalJobIDs.add(terminal.jobID);
      const label = terminal.jobID === snapshot.standardJob?.jobID ? "标准模型" : "个人模型";
      toast(`${label}${librarySuggestionJobStatus(terminal, "任务已更新")}`);
      if (!elements.reviewWorkspace.classList.contains("hidden")) {
        await loadReviewOverview();
        await loadLibrarySuggestions({ quiet: true });
      }
    }
  } catch (error) {
    if (generation === library.requestGeneration && !quiet) {
      toast(error.message || "无法读取全库模型建议状态");
    }
  } finally {
    if (generation === library.requestGeneration) {
      library.loading = false;
      renderReviewLocalModelStatus();
      scheduleLibrarySuggestionPoll();
    }
  }
}

async function submitLibrarySuggestions(track) {
  const library = state.librarySuggestions;
  const sourceIDs = resolvedReviewSourceFilter();
  if (!supportsLibrarySuggestions()
    || !state.online
    || library.launchingTrack != null
    || (Array.isArray(sourceIDs) && sourceIDs.length === 0)) return;
  library.launchingTrack = track;
  renderReviewLocalModelStatus();
  try {
    const response = await api("/v1/library-suggestions/requests", {
      method: "POST",
      body: JSON.stringify({
        operationID: crypto.randomUUID(),
        mediaKind: state.mediaKind,
        track,
        sourceIDs,
      }),
    });
    toast(`${track === "standard" ? "标准" : "个人"}模型任务已交给 Mac`
      + (sourceIDs == null ? "，范围为全部来源" : `，范围为 ${sourceIDs.length} 个来源`));
    await Promise.all([
      loadLibrarySuggestions({ quiet: true }),
      api("/v1/jobs").then((jobs) => {
        state.jobs = jobs;
        renderJobs();
      }),
    ]);
    state.focusedActivityJobID = response.jobID;
  } catch (error) {
    toast(error.message || "无法开始全库模型建议");
  } finally {
    library.launchingTrack = null;
    renderReviewLocalModelStatus();
    scheduleLibrarySuggestionPoll();
  }
}

async function refreshReviewLocalModelStatus() {
  if (!state.online) return;
  const returnFocus = document.activeElement === elements.refreshReviewModelStatusButton;
  await Promise.all([
    supportsGeneralSettings() ? loadGeneralSettings({ quiet: true }) : Promise.resolve(),
    loadSampleSuggestions({ quiet: true }),
    loadLibrarySuggestions({ quiet: true, refreshServiceHealth: true }),
  ]);
  renderReviewLocalModelStatus();
  if (returnFocus) {
    requestAnimationFrame(() => {
      elements.refreshReviewModelStatusButton.focus({ preventScroll: true });
    });
  }
}

async function cancelSampleSuggestions() {
  const suggestions = state.sampleSuggestions;
  const activity = activeSampleSuggestion();
  if (!activity || suggestions.cancelling) return;
  suggestions.cancelling = true;
  renderSampleSuggestions();
  try {
    const response = await api(
      `/v1/sample-suggestions/requests/${activity.operationID}/actions`,
      { method: "POST", body: JSON.stringify({ action: "cancel" }) }
    );
    suggestions.activities = suggestions.activities.map((item) =>
      item.operationID === response.activity.operationID ? response.activity : item
    );
    suggestions.seenTerminalOperationIDs.add(response.activity.operationID);
    toast(sampleSuggestionTerminalText(response.activity));
  } catch (error) {
    toast(error.message || "无法停止个人建议抽检");
  } finally {
    suggestions.cancelling = false;
    renderSampleSuggestions();
    scheduleSampleSuggestionPoll();
  }
}

function tagLibrarySuggestionActivities() {
  return state.tagLibrarySuggestions.snapshot?.activities || [];
}

function activeTagLibrarySuggestion(tagID = null) {
  const activePhases = new Set(["preparingCandidates", "scoring", "publishing"]);
  return tagLibrarySuggestionActivities().find((activity) =>
    activePhases.has(activity.phase) && (!tagID || activity.tagID === tagID)
  ) || null;
}

function tagLibrarySuggestionMethodText(method) {
  if (method === "personalAdamW") return "超级个人模型";
  if (method === "personalCentroid") return "个人模型";
  return "方法当前不可用";
}

function tagLibrarySuggestionMethodAvailable(method) {
  if (method === "personalAdamW") {
    return Boolean(state.tagLibrarySuggestions.snapshot?.personalAdamWAvailable);
  }
  if (method === "personalCentroid") {
    return Boolean(state.tagLibrarySuggestions.snapshot?.personalCentroidAvailable);
  }
  return false;
}

function tagLibrarySuggestionPhaseText(activity) {
  const checked = activity.totalUnitCount > 0
    ? `${activity.completedUnitCount}/${activity.totalUnitCount}`
    : `${activity.completedUnitCount}`;
  return {
    preparingCandidates: "正在整理未审核照片…",
    scoring: `正在评分 ${checked}`,
    publishing: `正在写入 ${activity.aboveThresholdCount} 条候选…`,
    completed: `已检查 ${activity.totalUnitCount} 项 · 写入 ${activity.insertedCount} 条`,
    failed: "生成未完成",
    cancelled: "已停止",
  }[activity.phase] || "正在处理…";
}

function tagLibrarySuggestionTerminalText(activity) {
  if (activity.phase === "cancelled") {
    return `${tagLibrarySuggestionMethodText(activity.method)}扫描已停止`;
  }
  if (activity.phase === "failed") {
    const reason = {
      noCandidates: "没有需要扫描的照片",
      personalUnavailable: "还没有可用的个人模型",
      tagNotInPersonalModel: "这个标签尚未进入个人模型",
      modelUnavailable: "个人模型当前不可用",
      identityMismatch: "个人模型与当前图库不匹配，请重新训练",
      activeConflict: "另一个个人模型任务仍在运行",
    }[activity.errorCode] || "请在 Mac 端检查模型状态";
    return `${tagLibrarySuggestionMethodText(activity.method)}生成未完成：${reason}`;
  }
  return `${tagLibrarySuggestionMethodText(activity.method)}已检查 ${activity.totalUnitCount} 项`
    + ` · 超过阈值 ${activity.aboveThresholdCount} 项 · 写入 ${activity.insertedCount} 条`
    + (activity.skippedCount ? ` · 跳过 ${activity.skippedCount}` : "");
}

function tagLibrarySuggestionOption(tagID) {
  return state.tagLibrarySuggestions.snapshot?.tags?.find((option) => option.tagID === tagID)
    || null;
}

function tagLibrarySuggestionThreshold(option, method) {
  if (!option) return null;
  return method === "personalAdamW"
    ? option.personalAdamWMinScore
    : option.personalCentroidMinScore;
}

function activeTagSuggestionSources() {
  return state.sources.filter((source) => source.state === "active");
}

function activeReviewSources() {
  return state.sources.filter((source) => source.state === "active");
}

function sanitizeReviewSourceFilter() {
  if (state.review.sourceFilterIDs === null) return;
  const activeIDs = new Set(activeReviewSources().map((source) => source.id));
  const selected = new Set(
    [...state.review.sourceFilterIDs].filter((sourceID) => activeIDs.has(sourceID))
  );
  state.review.sourceFilterIDs = selected.size === activeIDs.size
    ? null
    : selected;
}

function applyReviewSourceFilterHistoryContext(context = {}) {
  const rawSourceIDs = context.reviewSourceIDs;
  if (!Array.isArray(rawSourceIDs)) {
    state.review.sourceFilterIDs = null;
    return;
  }
  const requested = new Set(
    rawSourceIDs
      .filter((sourceID) => typeof sourceID === "string")
      .slice(0, 10_000)
  );
  const activeIDs = activeReviewSources().map((source) => source.id);
  const selected = new Set(activeIDs.filter((sourceID) => requested.has(sourceID)));
  state.review.sourceFilterIDs = selected.size === activeIDs.length ? null : selected;
}

function applyReviewSelectionHistoryContext(context = {}) {
  if (state.review.mode !== "queue" || !state.review.items.length) {
    state.review.selectionMode = false;
    state.review.selectedIndex = -1;
    state.review.selectedAssetIDs.clear();
    state.review.selectionAnchorIndex = -1;
    return false;
  }

  const validAssetIDs = new Set(state.review.items.map((item) => item.assetID));
  const selectedAssetIDs = new Set(
    [...new Set(
      (Array.isArray(context.reviewSelectedAssetIDs)
        ? context.reviewSelectedAssetIDs
        : [])
        .map(galleryHistoryIdentifier)
        .filter((assetID) => assetID && validAssetIDs.has(assetID))
    )].slice(0, GALLERY_HISTORY_LOADED_LIMIT)
  );
  const requestedPrimaryKey = galleryHistoryIdentifier(context.reviewItemKey);
  const requestedPrimaryAssetID = galleryHistoryIdentifier(context.reviewAssetID);
  let primaryIndex = requestedPrimaryKey
    ? state.review.items.findIndex(
      (item) => reviewItemKey(item) === requestedPrimaryKey
    )
    : -1;
  if (primaryIndex < 0 && requestedPrimaryAssetID) {
    primaryIndex = state.review.items.findIndex(
      (item) => item.assetID === requestedPrimaryAssetID
    );
  }
  if (!selectedAssetIDs.size && primaryIndex >= 0) {
    selectedAssetIDs.add(state.review.items[primaryIndex].assetID);
  }
  if (selectedAssetIDs.size
    && (primaryIndex < 0
      || !selectedAssetIDs.has(state.review.items[primaryIndex].assetID))) {
    primaryIndex = state.review.items.findIndex(
      (item) => selectedAssetIDs.has(item.assetID)
    );
  }
  if (primaryIndex < 0) {
    primaryIndex = 0;
    selectedAssetIDs.add(state.review.items[primaryIndex].assetID);
  }

  const requestedAnchorKey = galleryHistoryIdentifier(context.reviewSelectionAnchorKey);
  let anchorIndex = requestedAnchorKey
    ? state.review.items.findIndex(
      (item) => reviewItemKey(item) === requestedAnchorKey
        && selectedAssetIDs.has(item.assetID)
    )
    : -1;
  if (anchorIndex < 0) anchorIndex = primaryIndex;

  state.review.selectedAssetIDs = selectedAssetIDs;
  state.review.selectedIndex = primaryIndex;
  state.review.selectionAnchorIndex = anchorIndex;
  state.review.selectionMode = Boolean(
    context.reviewSelectionMode && selectedAssetIDs.size
  );
  renderReviewSelectionState();
  return true;
}

function resolvedReviewSourceFilter() {
  sanitizeReviewSourceFilter();
  if (state.review.sourceFilterIDs === null) return null;
  return activeReviewSources()
    .filter((source) => state.review.sourceFilterIDs.has(source.id))
    .map((source) => source.id);
}

function reviewSourceFilterSummaryText() {
  const active = activeReviewSources();
  const selectedIDs = resolvedReviewSourceFilter();
  if (selectedIDs === null) {
    return `显示全部 ${active.length} 个来源的待审核建议`;
  }
  const selected = new Set(selectedIDs);
  const names = active.filter((source) => selected.has(source.id))
    .map((source) => source.displayName);
  if (!names.length) return "未选择来源，待审核列表为空";
  if (names.length === active.length) {
    return `显示全部 ${active.length} 个来源的待审核建议`;
  }
  return `仅显示：${names.join("、")}`;
}

function createReviewSourceFilterOption() {
  const button = document.createElement("button");
  button.type = "button";
  button.className = "review-source-option";
  button.setAttribute("role", "menuitemcheckbox");
  const check = document.createElement("span");
  check.className = "review-source-check";
  check.setAttribute("aria-hidden", "true");
  check.textContent = "✓";
  button.append(check, document.createElement("span"));
  return button;
}

function syncReviewSourceFilterOption(button, source, included, locked) {
  button.dataset.reviewSourceId = source.id;
  button.setAttribute("aria-checked", String(included));
  button.disabled = locked;
  configurePersistentHelp(button, {
    title: `${included ? "已包含" : "未包含"} · ${source.displayName}`,
    detail: `切换“${source.displayName}”是否参与建议生成和待审列表；其他来源、图库位置和当前媒体类型保持不变。`,
    kind: "review",
    keyShortcuts: "ArrowUp ArrowDown PageUp PageDown Home End",
  });
  const name = button.querySelector("span:last-child");
  if (name.textContent !== source.displayName) name.textContent = source.displayName;
}

function focusReviewSourceFilterButton(button) {
  if (!button) return;
  button.focus({ preventScroll: true });
  if (!elements.reviewSourceFilterOptions.contains(button)) return;
  const viewport = elements.reviewSourceFilterOptions.getBoundingClientRect();
  const target = button.getBoundingClientRect();
  if (target.top < viewport.top) {
    elements.reviewSourceFilterOptions.scrollTop += target.top - viewport.top;
  } else if (target.bottom > viewport.bottom) {
    elements.reviewSourceFilterOptions.scrollTop += target.bottom - viewport.bottom;
  }
}

function moveReviewSourceFilterFocus(event) {
  if (event.key === "Escape") {
    event.preventDefault();
    void returnFromActionMenu();
    return true;
  }
  const movementKeys = ["ArrowUp", "ArrowDown", "PageUp", "PageDown", "Home", "End"];
  if (!movementKeys.includes(event.key)) return false;
  const buttons = [...elements.reviewSourceFilterPopover.querySelectorAll(
    "button:not(:disabled)"
  )];
  if (!buttons.length) return false;
  event.preventDefault();
  const current = Math.max(0, buttons.indexOf(document.activeElement));
  let next;
  if (["PageUp", "PageDown"].includes(event.key)) {
    next = longListNavigationTarget(
      buttons,
      current,
      event.key,
      elements.reviewSourceFilterOptions
    );
  } else if (event.key === "Home") {
    next = 0;
  } else if (event.key === "End") {
    next = buttons.length - 1;
  } else {
    next = (current + (event.key === "ArrowUp" ? -1 : 1) + buttons.length)
      % buttons.length;
  }
  focusReviewSourceFilterButton(buttons[next]);
  return true;
}

function reviewSourceFilterEmptyState() {
  let empty = elements.reviewSourceFilterOptions.querySelector(
    ":scope > .popover-empty"
  );
  if (!empty) {
    empty = document.createElement("p");
    empty.className = "popover-empty";
  }
  if (empty.textContent !== "没有已启用来源") empty.textContent = "没有已启用来源";
  return empty;
}

function renderReviewSourceFilter() {
  const focusedSource = document.activeElement?.closest?.("[data-review-source-id]");
  if (focusedSource && elements.reviewSourceFilterPopover.contains(focusedSource)) {
    state.review.sourceFilterFocusSelector =
      `[data-review-source-id="${CSS.escape(focusedSource.dataset.reviewSourceId)}"]`;
  } else if (document.activeElement === elements.selectAllReviewSourcesButton) {
    state.review.sourceFilterFocusSelector = "#selectAllReviewSourcesButton";
  }
  const sources = activeReviewSources();
  const selectedIDs = resolvedReviewSourceFilter();
  const selected = selectedIDs === null
    ? new Set(sources.map((source) => source.id))
    : new Set(selectedIDs);
  const summary = reviewSourceFilterSummaryText();
  const locked = state.review.loading
    || state.review.overviewLoading
    || state.review.mutating;
  elements.reviewSourceFilterSummary.textContent = summary;
  elements.reviewSourceFilterButton.title = `${summary}。选择建议生成和待审列表覆盖的来源；不会改变图库侧栏当前浏览位置。`;
  elements.reviewSourceFilterButton.setAttribute("aria-label", `审核来源：${summary}`);
  elements.reviewSourceFilterButton.disabled = locked || sources.length === 0;
  elements.selectAllReviewSourcesButton.disabled = locked || selectedIDs === null;
  configurePersistentHelp(elements.reviewSourceFilterButton, {
    detail: `${summary}。这里同时限定建议生成和待审列表范围；不会改变图库侧栏当前来源或浏览位置。`,
    kind: "review",
  });
  configurePersistentHelp(elements.selectAllReviewSourcesButton, {
    title: "全选审核来源",
    detail: "恢复使用全部已启用来源生成建议并显示待审媒体；不会切换图库侧栏范围。Page Up/Page Down 可按当前可见来源页幅移动。",
    kind: "review",
    keyShortcuts: "ArrowUp ArrowDown PageUp PageDown Home End",
  });

  if (!sources.length) {
    reconcileStableChildren(
      elements.reviewSourceFilterOptions,
      [reviewSourceFilterEmptyState()]
    );
    return;
  }
  const existingOptions = new Map(
    [...elements.reviewSourceFilterOptions.querySelectorAll(
      ":scope > [data-review-source-id]"
    )].map((button) => [button.dataset.reviewSourceId, button])
  );
  const options = sources.map((source) => {
    const button = existingOptions.get(source.id) || createReviewSourceFilterOption();
    syncReviewSourceFilterOption(button, source, selected.has(source.id), locked);
    return button;
  });
  reconcileStableChildren(elements.reviewSourceFilterOptions, options);
  if (!locked
    && !elements.reviewSourceFilterPopover.classList.contains("hidden")
    && state.review.sourceFilterFocusSelector) {
    const focusTarget = elements.reviewSourceFilterPopover.querySelector(
      state.review.sourceFilterFocusSelector
    );
    if (document.activeElement !== focusTarget) {
      requestAnimationFrame(() => {
        const currentTarget = elements.reviewSourceFilterPopover.querySelector(
          state.review.sourceFilterFocusSelector
        );
        if (document.activeElement !== currentTarget) {
          currentTarget?.focus({ preventScroll: true });
        }
      });
    }
  }
}

function closeReviewSourceFilter(options = {}) {
  if (activeActionMenuDescriptor()?.kind !== "reviewSources") return;
  closeActionMenu(options);
}

function toggleReviewSourceFilter() {
  toggleActionMenu("reviewSources");
}

async function reloadReviewSourceScope(focusSelector) {
  state.review.sourceFilterFocusSelector = focusSelector;
  renderReviewSourceFilter();
  renderSampleSuggestions();
  await loadReviewOverview();
  if (state.review.mode === "queue") await loadReviewQueue();
  renderReviewSourceFilter();
  if (!elements.reviewSourceFilterPopover.classList.contains("hidden")) {
    requestAnimationFrame(() => {
      elements.reviewSourceFilterPopover.querySelector(focusSelector)
        ?.focus({ preventScroll: true });
    });
  }
  recordWorkspaceHistory("review", currentWorkspaceHistoryContext("review"), "replace");
}

async function setReviewSourceIncluded(sourceID, included) {
  const activeIDs = new Set(activeReviewSources().map((source) => source.id));
  if (!activeIDs.has(sourceID)) return;
  const selected = state.review.sourceFilterIDs === null
    ? new Set(activeIDs)
    : new Set(state.review.sourceFilterIDs);
  if (included) selected.add(sourceID);
  else selected.delete(sourceID);
  for (const selectedID of [...selected]) {
    if (!activeIDs.has(selectedID)) selected.delete(selectedID);
  }
  state.review.sourceFilterIDs = selected.size === activeIDs.size ? null : selected;
  recordWorkspaceHistory("review", currentWorkspaceHistoryContext("review"), "replace");
  await reloadReviewSourceScope(
    `[data-review-source-id="${CSS.escape(sourceID)}"]`
  );
}

async function selectAllReviewSources() {
  state.review.sourceFilterIDs = null;
  recordWorkspaceHistory("review", currentWorkspaceHistoryContext("review"), "replace");
  const firstSourceID = activeReviewSources()[0]?.id;
  await reloadReviewSourceScope(
    firstSourceID
      ? `[data-review-source-id="${CSS.escape(firstSourceID)}"]`
      : "#selectAllReviewSourcesButton"
  );
}

const reviewSuggestionLimitBounds = { minimum: 1, maximum: 10_000, step: 50 };

function currentReviewSuggestionLimit() {
  const configured = state.generalSettings.snapshot?.maxPendingSuggestionsPerTag;
  if (Number.isInteger(configured)) return configured;
  const projected = state.tagLibrarySuggestions.snapshot?.maximumPendingCount;
  return Number.isInteger(projected) ? projected : 500;
}

function renderReviewSuggestionLimit() {
  const value = currentReviewSuggestionLimit();
  const writable = Number.isInteger(
    state.generalSettings.snapshot?.maxPendingSuggestionsPerTag
  );
  const locked = state.generalSettings.loading
    || state.generalSettings.submitting
    || !state.online
    || !writable;
  elements.reviewSuggestionLimitValue.textContent = String(value);
  elements.decreaseReviewSuggestionLimitButton.disabled = locked
    || value <= reviewSuggestionLimitBounds.minimum;
  elements.increaseReviewSuggestionLimitButton.disabled = locked
    || value >= reviewSuggestionLimitBounds.maximum;
  elements.reviewSuggestionLimitControl.title = writable
    ? "调整每个标签最多保留的待审核建议数；四种建议生成路径共用。"
    : "当前 Mac Host 只能读取每标签上限；升级 Host 后可在网页修改。";
  configurePersistentHelp(elements.reviewSuggestionLimitControl, {
    title: `每标签上限 · ${value}`,
    detail: writable
      ? "调整每个标签最多保留的待审核建议数；特征向量、标准模型、个人模型和超级个人四条生成路径共用。"
      : "当前 Host 只提供读取能力；升级 Mac App 后才能从网页修改每标签上限。",
    kind: "review",
  });
  configurePersistentHelp(elements.decreaseReviewSuggestionLimitButton, {
    title: "减少每标签上限",
    detail: `把每标签上限从 ${value} 减少 ${reviewSuggestionLimitBounds.step}；不会立即生成或删除建议。`,
    kind: "review",
  });
  configurePersistentHelp(elements.increaseReviewSuggestionLimitButton, {
    title: "增加每标签上限",
    detail: `把每标签上限从 ${value} 增加 ${reviewSuggestionLimitBounds.step}；不会立即生成或删除建议。`,
    kind: "review",
  });
}

async function adjustReviewSuggestionLimit(delta) {
  const configured = state.generalSettings.snapshot?.maxPendingSuggestionsPerTag;
  if (!Number.isInteger(configured)
    || state.generalSettings.loading
    || state.generalSettings.submitting) return;
  const next = Math.min(
    reviewSuggestionLimitBounds.maximum,
    Math.max(reviewSuggestionLimitBounds.minimum, configured + delta)
  );
  if (next === configured) return;
  const returnFocus = delta < 0
    ? elements.decreaseReviewSuggestionLimitButton
    : elements.increaseReviewSuggestionLimitButton;
  await submitGeneralSettingsPatch({ maxPendingSuggestionsPerTag: next });
  if (state.generalSettings.snapshot?.maxPendingSuggestionsPerTag === next) {
    await loadTagLibrarySuggestions({ quiet: true });
  }
  restoreOverlayFocus(returnFocus);
}

function createTagSuggestionSourceOption() {
  const label = document.createElement("label");
  label.className = "tag-suggestion-source-option";
  const input = document.createElement("input");
  input.type = "checkbox";
  label.append(input, document.createElement("span"));
  return label;
}

function syncTagSuggestionSourceOption(label, source, selected, disabled) {
  const input = label.querySelector(':scope > input[type="checkbox"]');
  input.id = `tagSuggestionSource-${source.id}`;
  input.value = source.id;
  input.checked = selected;
  input.disabled = disabled;
  input.setAttribute("aria-keyshortcuts", choiceGridNavigationShortcuts);
  const name = label.querySelector(":scope > span");
  if (name.textContent !== source.displayName) name.textContent = source.displayName;
  configurePersistentHelp(label, {
    title: `建议来源 · ${source.displayName}`,
    detail: "勾选后只扫描这个来源；方向键、Page Up/Page Down 或 Home/End 可在来源之间移动，空格键切换勾选。",
    kind: "review",
    keyShortcuts: choiceGridNavigationShortcuts,
  });
}

function renderTagSuggestionDialog() {
  const suggestions = state.tagLibrarySuggestions;
  const dialog = suggestions.dialog;
  const tag = tagByID(dialog.tagID);
  const option = tagLibrarySuggestionOption(dialog.tagID);
  const threshold = tagLibrarySuggestionThreshold(option, dialog.method);
  const sources = activeTagSuggestionSources();
  const validSourceIDs = new Set(sources.map((source) => source.id));
  const previousSourceIDs = [...dialog.selectedSourceIDs];
  dialog.selectedSourceIDs = new Set(
    previousSourceIDs.filter((sourceID) => validSourceIDs.has(sourceID))
  );
  const removedSourceCount = new Set(
    previousSourceIDs.filter((sourceID) => !validSourceIDs.has(sourceID))
  ).size;
  if (removedSourceCount) {
    const sourceNotice = `${removedSourceCount} 个所选来源当前不可用，已从本次扫描中移除。`;
    if (!dialog.notice.includes(sourceNotice)) {
      dialog.notice = `${dialog.notice ? `${dialog.notice} ` : ""}${sourceNotice}`;
    }
  }

  elements.tagSuggestionDialogTitle.textContent = tag
    ? `为“${tag.displayName}”生成建议`
    : "生成标签建议";
  elements.tagSuggestionDialogSubtitle.textContent =
    "使用这台 Mac 上已训练的个人模型扫描所选来源。";
  elements.tagSuggestionMethodSummary.textContent = tagLibrarySuggestionMethodText(dialog.method);
  elements.tagSuggestionLimitSummary.textContent =
    `Top ${suggestions.snapshot?.maximumPendingCount || 500}`;
  elements.tagSuggestionThresholdSummary.textContent = Number.isFinite(threshold)
    ? threshold.toFixed(3)
    : "由 Mac 设置";
  elements.tagSuggestionNotice.textContent = dialog.notice;
  elements.tagSuggestionNotice.classList.toggle("hidden", !dialog.notice);
  elements.tagSuggestionSelectionSummary.textContent =
    `已选择 ${dialog.selectedSourceIDs.size} 个来源`;

  const existingOptions = new Map(
    [...elements.tagSuggestionSourceOptions.querySelectorAll(
      ":scope > .tag-suggestion-source-option"
    )].map((label) => [label.querySelector('input[type="checkbox"]')?.value, label])
  );
  const sourceOptions = sources.map((source) => {
    const label = existingOptions.get(source.id) || createTagSuggestionSourceOption();
    syncTagSuggestionSourceOption(
      label,
      source,
      dialog.selectedSourceIDs.has(source.id),
      suggestions.submitting
    );
    return label;
  });
  reconcileStableChildren(elements.tagSuggestionSourceOptions, sourceOptions);

  const locked = suggestions.submitting || suggestions.loading;
  elements.selectAllTagSuggestionSourcesButton.disabled = locked || sources.length === 0;
  elements.clearTagSuggestionSourcesButton.disabled = locked || dialog.selectedSourceIDs.size === 0;
  elements.launchTagSuggestionButton.disabled = !state.online
    || locked
    || !tag
    || !option?.personalEligible
    || !tagLibrarySuggestionMethodAvailable(dialog.method)
    || !Number.isFinite(threshold)
    || dialog.selectedSourceIDs.size === 0
    || Boolean(activeTagLibrarySuggestion());
  elements.launchTagSuggestionButton.textContent = suggestions.submitting
    ? "正在交给 Mac…"
    : "开始扫描";
}

function currentTagSuggestionHistoryContext() {
  const dialog = state.tagLibrarySuggestions.dialog;
  return {
    tagSuggestionTagID: galleryHistoryIdentifier(dialog.tagID),
    tagSuggestionMethod: ["personalCentroid", "personalAdamW"].includes(dialog.method)
      ? dialog.method
      : null,
    tagSuggestionSourceIDs: [...dialog.selectedSourceIDs]
      .slice(0, GALLERY_HISTORY_LOADED_LIMIT),
    tagSuggestionDialogScrollTop: elements.tagSuggestionDialog.scrollTop || 0,
    tagSuggestionSourcesScrollTop: elements.tagSuggestionSourceOptions.scrollTop || 0,
  };
}

function applyTagSuggestionHistoryContext(context = {}) {
  const dialog = state.tagLibrarySuggestions.dialog;
  const tagID = galleryHistoryIdentifier(context.tagSuggestionTagID);
  const allowedMethods = new Set(["personalCentroid", "personalAdamW"]);
  const method = allowedMethods.has(context.tagSuggestionMethod)
    ? context.tagSuggestionMethod
    : null;
  const savedSourceIDs = Array.isArray(context.tagSuggestionSourceIDs)
    ? context.tagSuggestionSourceIDs
      .map(galleryHistoryIdentifier)
      .filter(Boolean)
      .slice(0, GALLERY_HISTORY_LOADED_LIMIT)
    : [];
  const activeSourceIDs = new Set(activeTagSuggestionSources().map((source) => source.id));
  const selectedSourceIDs = [...new Set(savedSourceIDs)]
    .filter((sourceID) => activeSourceIDs.has(sourceID));

  dialog.tagID = tagID;
  dialog.method = method;
  dialog.selectedSourceIDs = new Set(selectedSourceIDs);
  const notes = [];
  const tag = tagByID(tagID);
  const option = tagLibrarySuggestionOption(tagID);
  if (!tag || !option?.personalEligible) {
    notes.push("刷新前的标签当前不可用于个人建议，请返回总览重新选择标签。");
  }
  if (!method || !tagLibrarySuggestionMethodAvailable(method)) {
    notes.push("刷新前的个人模型方法当前不可用，请返回总览选择可用方法。");
  }
  const missingSourceCount = new Set(
    savedSourceIDs.filter((sourceID) => !activeSourceIDs.has(sourceID))
  ).size;
  if (missingSourceCount) {
    notes.push(`${missingSourceCount} 个历史来源当前不可用，已从本次扫描中移除。`);
  }
  if (!selectedSourceIDs.length) {
    notes.push("刷新前的来源范围当前为空，请重新选择至少一个来源。");
  }
  if (activeTagLibrarySuggestion()) {
    notes.push("已有个人模型扫描正在运行，当前配置暂不能提交。");
  }
  dialog.notice = notes.join(" ");
  return Boolean(tagID);
}

async function restoreTagSuggestionLayoutFromHistory(context = {}) {
  await waitForWorkspaceLayout();
  for (const [surface, value] of [
    [elements.tagSuggestionDialog, context.tagSuggestionDialogScrollTop],
    [elements.tagSuggestionSourceOptions, context.tagSuggestionSourcesScrollTop],
  ]) {
    surface.scrollTop = Math.min(
      workspaceHistoryScrollTop(value),
      Math.max(0, surface.scrollHeight - surface.clientHeight)
    );
  }
}

function tagSuggestionBaseLevelFromHistory(context = {}) {
  return ["sidebar", "inspector", "lightbox"].includes(context.tagSuggestionBaseLevel)
    ? context.tagSuggestionBaseLevel
    : "workspace";
}

function replaceTagSuggestionHistoryWithBase(baseLevel) {
  if (!state.workspaceNavigation.initialized
    || elements.appView.classList.contains("hidden")) return;
  const current = activeWorkspaceHistoryEntry();
  const route = visibleWorkspaceRoute();
  if (current?.route !== route || current.navigationLevel !== "tagSuggestion") return;
  const context = currentWorkspaceHistoryContext(route);
  if (context && typeof context === "object") delete context.tagSuggestionBaseLevel;
  const navigationLevel = visibleWorkspaceNavigationBaseLevel(route, baseLevel);
  history.replaceState({
    ...(history.state || {}),
    [WORKSPACE_HISTORY_KEY]: workspaceHistoryEntry(route, context, navigationLevel),
  }, "", location.href);
}

function clearTagSuggestionDialogState() {
  const dialog = state.tagLibrarySuggestions.dialog;
  dialog.tagID = null;
  dialog.method = "personalCentroid";
  dialog.selectedSourceIDs.clear();
  dialog.notice = "";
  dialog.returnFocus = null;
  dialog.baseLevel = "workspace";
  dialog.historyRestoreFocus = true;
  dialog.focusID = "closeTagSuggestionDialogButton";
  dialog.restorable = false;
  elements.tagSuggestionError.textContent = "";
}

function presentTagSuggestionDialog({
  historyMode = "pushTagSuggestion",
  baseLevel = null,
  focus = true,
} = {}) {
  const dialog = state.tagLibrarySuggestions.dialog;
  if (elements.tagSuggestionDialog.open) {
    if (focus) restoreOverlayFocus(elements.closeTagSuggestionDialogButton);
    return;
  }
  const current = activeWorkspaceHistoryEntry();
  dialog.baseLevel = baseLevel
    || workspaceNavigationBaseLevel(
      current?.navigationLevel || "workspace",
      current?.context || {}
    );
  renderTagSuggestionDialog();
  elements.tagSuggestionDialog.showModal();
  if (historyMode !== "none") {
    const route = visibleWorkspaceRoute();
    recordWorkspaceHistory(route, currentWorkspaceHistoryContext(route), historyMode);
  }
  dialog.restorable = true;
  if (focus) {
    restoreOverlayFocus(
      document.getElementById(dialog.focusID) || elements.closeTagSuggestionDialogButton
    );
  }
}

function closeTagSuggestionDialog({
  restoreFocus = true,
  checkpoint = true,
  preserveState = false,
} = {}) {
  if (!elements.tagSuggestionDialog.open) return;
  const dialog = state.tagLibrarySuggestions.dialog;
  const active = document.activeElement;
  if (active instanceof HTMLElement && elements.tagSuggestionDialog.contains(active) && active.id) {
    dialog.focusID = active.id;
  }
  const baseLevel = dialog.baseLevel;
  const returnFocus = dialog.returnFocus;
  elements.tagSuggestionDialog.close();
  if (restoreFocus) {
    restoreOverlayFocus(stableReturnFocusTarget(returnFocus, elements.reviewButton));
  }
  if (checkpoint) replaceTagSuggestionHistoryWithBase(baseLevel);
  if (!preserveState) clearTagSuggestionDialogState();
}

function returnFromTagSuggestion({ restoreFocus = true } = {}) {
  if (!elements.tagSuggestionDialog.open) return Promise.resolve();
  const dialog = state.tagLibrarySuggestions.dialog;
  dialog.historyRestoreFocus = restoreFocus;
  if (state.workspaceNavigation.pendingReturnPromise) {
    return state.workspaceNavigation.pendingReturnPromise;
  }
  const current = activeWorkspaceHistoryEntry();
  if (state.workspaceNavigation.initialized
    && current?.route === visibleWorkspaceRoute()
    && current.navigationLevel === "tagSuggestion") {
    const pending = new Promise((resolve) => {
      state.workspaceNavigation.pendingReturnResolve = resolve;
    });
    state.workspaceNavigation.pendingReturnPromise = pending;
    history.back();
    return pending;
  }
  closeTagSuggestionDialog({ restoreFocus });
  dialog.historyRestoreFocus = true;
  return Promise.resolve();
}

async function reconcileTagSuggestionFromWorkspaceHistory(route, navigationLevel, context = {}) {
  const shouldOpen = navigationLevel === "tagSuggestion"
    && route === visibleWorkspaceRoute();
  const suggestions = state.tagLibrarySuggestions;
  const dialog = suggestions.dialog;
  if (shouldOpen && !dialog.restorable) {
    clearTagSuggestionDialogState();
    if (!applyTagSuggestionHistoryContext(context)) {
      replaceTagSuggestionHistoryWithBase(tagSuggestionBaseLevelFromHistory(context));
      return false;
    }
    presentTagSuggestionDialog({
      historyMode: "none",
      baseLevel: tagSuggestionBaseLevelFromHistory(context),
    });
    await restoreTagSuggestionLayoutFromHistory(context);
    return true;
  }
  if (shouldOpen && !elements.tagSuggestionDialog.open) {
    presentTagSuggestionDialog({
      historyMode: "none",
      baseLevel: tagSuggestionBaseLevelFromHistory(context),
    });
  } else if (!shouldOpen && elements.tagSuggestionDialog.open) {
    const restoreFocus = dialog.historyRestoreFocus;
    closeTagSuggestionDialog({
      restoreFocus,
      checkpoint: false,
      preserveState: true,
    });
    dialog.historyRestoreFocus = true;
  }
  return false;
}

function openTagSuggestionDialog(tagID, method, returnFocus = null) {
  const suggestions = state.tagLibrarySuggestions;
  const option = tagLibrarySuggestionOption(tagID);
  const available = method === "personalAdamW"
    ? suggestions.snapshot?.personalAdamWAvailable
    : suggestions.snapshot?.personalCentroidAvailable;
  if (!option?.personalEligible || !available || activeTagLibrarySuggestion()) return;
  const reviewSourceIDs = resolvedReviewSourceFilter();
  const selectedSourceIDs = reviewSourceIDs?.length
    ? new Set(reviewSourceIDs)
    : new Set(activeTagSuggestionSources().map((source) => source.id));
  suggestions.dialog.tagID = tagID;
  suggestions.dialog.method = method;
  suggestions.dialog.selectedSourceIDs = selectedSourceIDs;
  suggestions.dialog.notice = "";
  suggestions.dialog.returnFocus = returnFocus || document.activeElement;
  elements.tagSuggestionError.textContent = "";
  suggestions.dialog.focusID = "closeTagSuggestionDialogButton";
  suggestions.dialog.restorable = true;
  presentTagSuggestionDialog();
}

function scheduleTagLibrarySuggestionPoll() {
  clearTimeout(state.tagLibrarySuggestions.pollTimer);
  state.tagLibrarySuggestions.pollTimer = null;
  if (!activeTagLibrarySuggestion()) return;
  state.tagLibrarySuggestions.pollTimer = setTimeout(
    () => loadTagLibrarySuggestions({ quiet: true }),
    900
  );
}

async function loadTagLibrarySuggestions({ quiet = false } = {}) {
  const suggestions = state.tagLibrarySuggestions;
  const generation = ++suggestions.requestGeneration;
  const activeIDs = new Set(tagLibrarySuggestionActivities()
    .filter((activity) => activeTagLibrarySuggestion(activity.tagID)?.operationID === activity.operationID)
    .map((activity) => activity.operationID));
  suggestions.loading = true;
  try {
    const query = new URLSearchParams({ mediaKind: state.mediaKind });
    const snapshot = await api(`/v1/tag-library-suggestions?${query}`);
    if (generation !== suggestions.requestGeneration) return;
    suggestions.snapshot = snapshot;
    const terminal = (snapshot.activities || []).find((activity) =>
      activeIDs.has(activity.operationID)
      && !["preparingCandidates", "scoring", "publishing"].includes(activity.phase)
    );
    if (terminal && !suggestions.seenTerminalOperationIDs.has(terminal.operationID)) {
      suggestions.seenTerminalOperationIDs.add(terminal.operationID);
      toast(tagLibrarySuggestionTerminalText(terminal));
      if (!elements.reviewWorkspace.classList.contains("hidden")) {
        await loadReviewOverview();
        if (terminal.phase === "completed" && terminal.insertedCount > 0) {
          await enterReviewQueue(terminal.tagID);
        }
      }
    }
  } catch (error) {
    if (generation === suggestions.requestGeneration && !quiet) {
      toast(error.message || "无法读取按标签生成建议状态");
    }
  } finally {
    if (generation === suggestions.requestGeneration) {
      suggestions.loading = false;
      renderReviewOverview();
      if (elements.tagSuggestionDialog.open) renderTagSuggestionDialog();
      scheduleTagLibrarySuggestionPoll();
    }
  }
}

async function generateTagLibrarySuggestions() {
  const suggestions = state.tagLibrarySuggestions;
  const dialog = suggestions.dialog;
  const option = tagLibrarySuggestionOption(dialog.tagID);
  const threshold = tagLibrarySuggestionThreshold(option, dialog.method);
  if (suggestions.submitting
    || !dialog.tagID
    || !tagByID(dialog.tagID)
    || !option?.personalEligible
    || !tagLibrarySuggestionMethodAvailable(dialog.method)
    || !Number.isFinite(threshold)
    || !dialog.selectedSourceIDs.size
    || activeTagLibrarySuggestion()) return;
  suggestions.submitting = true;
  elements.tagSuggestionError.textContent = "";
  renderTagSuggestionDialog();
  try {
    const response = await api("/v1/tag-library-suggestions/requests", {
      method: "POST",
      body: JSON.stringify({
        operationID: crypto.randomUUID(),
        mediaKind: state.mediaKind,
        method: dialog.method,
        tagID: dialog.tagID,
        sourceIDs: [...dialog.selectedSourceIDs].sort(),
      }),
    });
    suggestions.snapshot = {
      ...suggestions.snapshot,
      activities: [
        response.activity,
        ...tagLibrarySuggestionActivities().filter(
          (activity) => activity.operationID !== response.activity.operationID
        ),
      ],
    };
    const returnFocus = dialog.returnFocus;
    const submittedMethod = dialog.method;
    await returnFromTagSuggestion({ restoreFocus: false });
    clearTagSuggestionDialogState();
    toast(`已交给 Mac 用${tagLibrarySuggestionMethodText(submittedMethod)}扫描所选来源`);
    restoreOverlayFocus(stableReturnFocusTarget(returnFocus, elements.reviewButton));
  } catch (error) {
    elements.tagSuggestionError.textContent = error.message || "无法开始生成标签建议";
  } finally {
    suggestions.submitting = false;
    renderReviewOverview();
    if (elements.tagSuggestionDialog.open) renderTagSuggestionDialog();
    scheduleTagLibrarySuggestionPoll();
  }
}

async function cancelTagLibrarySuggestions(operationID) {
  const suggestions = state.tagLibrarySuggestions;
  if (!operationID || suggestions.cancellingIDs.has(operationID)) return;
  suggestions.cancellingIDs.add(operationID);
  renderReviewOverview();
  try {
    const response = await api(
      `/v1/tag-library-suggestions/requests/${operationID}/actions`,
      { method: "POST", body: JSON.stringify({ action: "cancel" }) }
    );
    suggestions.snapshot = {
      ...suggestions.snapshot,
      activities: tagLibrarySuggestionActivities().map((activity) =>
        activity.operationID === operationID ? response.activity : activity
      ),
    };
    suggestions.seenTerminalOperationIDs.add(operationID);
    toast(tagLibrarySuggestionTerminalText(response.activity));
  } catch (error) {
    toast(error.message || "无法停止按标签生成建议");
  } finally {
    suggestions.cancellingIDs.delete(operationID);
    renderReviewOverview();
    scheduleTagLibrarySuggestionPoll();
  }
}

async function findSimilarFromSelection(returnFocus = document.activeElement) {
  const seedAssetIDs = [...state.selectedAssetIDs];
  if (!seedAssetIDs.length || !state.online || state.findingSimilarFromSelection) return;
  state.slimming.mediaKind = state.mediaKind;
  let openedWorkspace = false;
  state.findingSimilarFromSelection = true;
  renderEmbeddingPreparation();
  try {
    const result = await api("/v1/library-slimming/launch", {
      method: "POST",
      body: JSON.stringify({
        operationID: crypto.randomUUID(),
        mediaKind: state.mediaKind,
        mode: "seeds",
        sourceIDs: null,
        seedAssetIDs,
        filter: currentSlimmingFilterRequest(),
      }),
    });
    state.slimming.selectedJobID = result.jobID;
    toast(`正在从所选 ${seedAssetIDs.length} 项查找相似内容`);
    state.findingSimilarFromSelection = false;
    renderEmbeddingPreparation();
    if (returnFocus instanceof HTMLElement
      && returnFocus.isConnected
      && !returnFocus.disabled
      && returnFocus.getClientRects().length > 0) {
      returnFocus.focus({ preventScroll: true });
    }
    await openSlimmingWorkspace();
    openedWorkspace = true;
    if (returnFocus instanceof HTMLElement && returnFocus.isConnected) {
      state.slimmingReturnFocus = returnFocus;
    }
    await loadSlimmingWorkspace({ jobID: result.jobID, quiet: true });
  } catch (error) {
    toast(error.message || "无法从所选项目查找相似内容");
  } finally {
    state.findingSimilarFromSelection = false;
    renderEmbeddingPreparation();
    if (!openedWorkspace
      && returnFocus instanceof HTMLElement
      && returnFocus.isConnected
      && !returnFocus.disabled
      && returnFocus.getClientRects().length > 0) {
      requestAnimationFrame(() => returnFocus.focus({ preventScroll: true }));
    }
  }
}

function renderAssetSelectionState() {
  for (const card of elements.assetGrid.querySelectorAll(":scope > .asset-card")) {
    const assetID = card.dataset.assetId;
    const isBatchSelected = state.selectedAssetIDs.has(assetID);
    card.classList.toggle(
      "selected",
      state.selectedAssetID === assetID && !state.selectionMode
    );
    card.classList.toggle("batch-selected", isBatchSelected);
    assetCardMainButton(card)?.setAttribute(
      "aria-pressed",
      String(state.selectionMode ? isBatchSelected : state.selectedAssetID === assetID)
    );
    syncAssetCardSelectionMark(card);
  }
  syncLibraryGridTabStops();
  updateInspectorNavigation();
}

function scheduleSelectionAggregate() {
  clearTimeout(state.aggregateTimer);
  state.aggregateTimer = setTimeout(() => {
    state.aggregateTimer = null;
    void loadSelectionAggregate();
  }, 120);
  renderSelectionInspectorHeader({ pending: true });
  void loadSelectionPrimaryDetail();
}

async function loadSelectionAggregate() {
  const assetIDs = [...state.selectedAssetIDs];
  const tagIDs = activeTags().map((tag) => tag.id);
  if (!tagIDs.length || !assetIDs.length) {
    state.selectionAggregates = [];
    renderSelectionBar();
    return;
  }
  if (state.loadingAggregate) {
    state.aggregateGeneration += 1;
    renderSelectionBar({ updateInspector: false });
    renderSelectionInspectorHeader({ pending: true });
    return;
  }
  const generation = ++state.aggregateGeneration;
  state.loadingAggregate = true;
  state.selectionAggregates = [];
  elements.batchAggregate.textContent = "正在统计…";
  renderSelectionInspectorHeader({ pending: true });
  try {
    const aggregates = await api("/v1/tags/selection", {
      method: "POST",
      body: JSON.stringify({ tagIDs, assetIDs }),
    });
    if (generation !== state.aggregateGeneration) return;
    state.selectionAggregates = aggregates;
    const aggregate = aggregates.find(
      (item) => item.tagID === elements.batchTagSelect.value
    );
    elements.batchAggregate.textContent = aggregate
      ? `确认 ${aggregate.acceptedCount} · 拒绝 ${aggregate.rejectedCount} · 未决定 ${aggregate.unknownCount}`
      : "选择标签后可查看汇总";
  } catch (error) {
    if (generation !== state.aggregateGeneration) return;
    elements.batchAggregate.textContent = error.message || "无法读取标签汇总";
  } finally {
    state.loadingAggregate = false;
    if (generation === state.aggregateGeneration) {
      renderSelectionBar({ updateInspector: false });
      renderSelectionInspector();
    } else {
      setTimeout(loadSelectionAggregate, 0);
    }
  }
}

async function applyBatchTagDecision(action, requestedTagID = null) {
  const tagID = requestedTagID || elements.batchTagSelect.value;
  const assetIDs = [...state.selectedAssetIDs];
  if (!state.online || !tagID || !assetIDs.length || state.tagMutating) return;
  const generation = state.workspaceGeneration;
  state.tagMutating = true;
  syncWriteActionControls();
  try {
    const result = await api("/v1/tag-decisions/batch", {
      method: "POST",
      body: JSON.stringify({
        operationID: crypto.randomUUID(),
        tagID,
        assetIDs,
        action,
      }),
    });
    if (generation !== state.workspaceGeneration) return;
    try {
      await loadAssets({
        preserveSelection: true,
        preserveUnchangedGrid: true,
        preserveLoadedWindow: true,
      });
      await loadSelectionAggregate();
      if (generation !== state.workspaceGeneration) return;
      undoToast(`已更新 ${result.appliedAssetCount} 项`, result.undoID);
    } catch {
      if (generation !== state.workspaceGeneration) return;
      void refreshWorkspace({
        quiet: true,
        kinds: ["tagsChanged", "assetsChanged"],
      });
      undoToast(
        `已更新 ${result.appliedAssetCount} 项，界面同步暂时失败，正在重试`,
        result.undoID
      );
    }
  } catch (error) {
    if (generation === state.workspaceGeneration) {
      toast(error.message || "批量标签更新失败");
    }
  } finally {
    if (generation === state.workspaceGeneration) {
      state.tagMutating = false;
      renderSelectionBar({ updateInspector: false });
      syncWriteActionControls();
      if (state.selectionMode && state.selectedAssetIDs.size) renderSelectionInspector();
    }
  }
}

function jobTitle(job) {
  const title = {
    folderReconcile: "文件夹同步",
    photosReconcile: "照片图库同步",
    personalizationSuggestions: "个性化建议",
    standardSuggestions: "标准模型建议",
    librarySlimmingAnalysis: "图库瘦身分析",
    librarySlimmingSourceIndex: "来源相似度索引",
    background: "后台任务",
    other: "后台任务",
  }[job?.kind] || "后台任务";
  if (job?.sourceDisplayName
    && ["folderReconcile", "photosReconcile"].includes(job.kind)) {
    return `${job.sourceDisplayName} · ${title}`;
  }
  return title;
}

function activeCatalogJob() {
  return state.jobs.find((job) =>
    ["folderReconcile", "photosReconcile"].includes(job.kind)
    && ["pending", "running"].includes(job.state)
  ) || null;
}

function catalogJobSourceName(job) {
  return job?.sourceDisplayName
    || (job?.kind === "photosReconcile" ? "Apple Photos" : "文件夹");
}

function catalogJobProgressLabel(job) {
  const source = catalogJobSourceName(job);
  const completed = Math.max(0, Number(job?.progress?.completedUnitCount || 0));
  const total = Math.max(0, Number(job?.progress?.totalUnitCount || 0));
  if (total > 0) return `${source} ${completed.toLocaleString()} / ${total.toLocaleString()}`;
  if (completed > 0) return `${source} 已检查 ${completed.toLocaleString()} 张`;
  return `正在扫描 ${source}`;
}

function syncCatalogProgressStatus() {
  const job = activeCatalogJob();
  const active = Boolean(job);
  elements.catalogProgressStatusButton.classList.toggle("hidden", !active);
  elements.appView.classList.toggle("catalog-progress-active", active);
  if (!job) {
    elements.catalogProgressStatusButton.removeAttribute("data-job-id");
    elements.catalogProgressStatusFill.style.width = "0%";
    elements.catalogProgressStatusButton.classList.remove("indeterminate");
    syncCompactToolbarMenu();
    return;
  }
  const completed = Math.max(0, Number(job.progress?.completedUnitCount || 0));
  const total = Math.max(0, Number(job.progress?.totalUnitCount || 0));
  const label = catalogJobProgressLabel(job);
  const percent = total > 0 ? Math.max(0, Math.min(100, completed / total * 100)) : 0;
  elements.catalogProgressStatusButton.dataset.jobId = job.id;
  elements.catalogProgressStatusLabel.textContent = label;
  elements.catalogProgressStatusFill.style.width = `${percent}%`;
  elements.catalogProgressStatusButton.classList.toggle("indeterminate", total <= 0);
  elements.catalogProgressStatusButton.setAttribute(
    "aria-label",
    `${label}，在活动中查看`
  );
  elements.catalogProgressStatusButton.title = `${label} · 在活动中查看`;
  syncCompactToolbarMenu();
}

function scheduleCatalogProgressPoll() {
  clearTimeout(state.catalogProgressPollTimer);
  state.catalogProgressPollTimer = null;
  if (!activeCatalogJob()
    || elements.appView.classList.contains("hidden")
    || !["account", "pairedDevice"].includes(state.authMode)) return;
  const delay = state.online ? 1_000 : 3_000;
  const generation = state.workspaceGeneration;
  state.catalogProgressPollTimer = setTimeout(async () => {
    state.catalogProgressPollTimer = null;
    if (generation !== state.workspaceGeneration) return;
    await refreshJobs({
      announce: false,
      indicateBusy: false,
      reportError: false,
    });
  }, delay);
}

function jobStateText(job) {
  if (job?.state === "running" && job.controlRequest === "pause") return "正在暂停";
  if (job?.state === "running" && job.controlRequest === "cancel") return "正在取消";
  return {
    pending: "等待中",
    running: "进行中",
    paused: "已暂停",
    retryableFailed: "失败，可重试",
    completed: "已完成",
    terminalFailed: "失败",
    cancelled: "已取消",
  }[job.state] || job.state;
}

function jobFailureGuidance(job) {
  const guidance = {
    interrupted: "Mac 上次退出时任务被中断；继续后会从已保存进度恢复。",
    attemptsExhausted: "已达到最大尝试次数；请检查来源状态，再删除记录并重新分析。",
    librarySlimmingAnalysisFailed: "分析遇到可恢复错误；可继续任务并沿用已保存进度。",
    librarySlimmingSourceIndexFailed: "来源索引构建失败；请确认来源在线后重试。",
    folderAuthorizationRequired: "文件夹授权已失效；请先在来源管理中重新授权。",
    folderSourceUnavailable: "文件夹来源当前不可用；重新连接磁盘或来源后再继续。",
    photosAuthorizationRequired: "照片图库授权不足；请在 Mac 系统设置中允许照片访问。",
    photosSourceUnavailable: "照片图库当前不可用；请确认系统照片图库可访问。",
  };
  return guidance[job?.lastErrorCode]
    || (job?.state === "retryableFailed" ? "任务可安全重试，并会尽量沿用已保存进度。" : "请在 Mac 端检查来源和任务状态。");
}

function jobActionText(action) {
  return { pause: "暂停", resume: "继续", cancel: "取消" }[action] || action;
}

function jobRows() {
  return [...elements.jobsList.querySelectorAll("[data-job-row-id]")];
}

function visibleListPageStep(rows, viewport) {
  if (!rows.length || !viewport) return 1;
  const viewportRect = viewport.getBoundingClientRect();
  const viewportStyle = getComputedStyle(viewport);
  const insetTop = Number.parseFloat(viewportStyle.scrollPaddingTop) || 0;
  const insetBottom = Number.parseFloat(viewportStyle.scrollPaddingBottom) || 0;
  const visibleTop = viewportRect.top + insetTop;
  const visibleBottom = viewportRect.bottom - insetBottom;
  const visibleCount = rows.reduce((count, row) => {
    const rowRect = row.getBoundingClientRect();
    return count + (rowRect.bottom > visibleTop && rowRect.top < visibleBottom ? 1 : 0);
  }, 0);
  return Math.max(1, visibleCount - 1);
}

function longListNavigationTarget(rows, currentIndex, key, viewport) {
  if (!rows.length) return 0;
  if (key === "Home") return 0;
  if (key === "End") return rows.length - 1;
  const direction = ["ArrowUp", "PageUp"].includes(key) ? -1 : 1;
  const step = ["PageUp", "PageDown"].includes(key)
    ? visibleListPageStep(rows, viewport)
    : 1;
  return Math.max(0, Math.min(rows.length - 1, currentIndex + direction * step));
}

const choiceGridNavigationShortcuts =
  "ArrowLeft ArrowRight ArrowUp ArrowDown PageUp PageDown Home End";

function revealCheckboxGridRow(container, row) {
  const containerRect = container.getBoundingClientRect();
  const rowRect = row.getBoundingClientRect();
  const visibleTop = containerRect.top + container.clientTop;
  const visibleBottom = visibleTop + container.clientHeight;
  if (rowRect.top < visibleTop) {
    container.scrollTop -= visibleTop - rowRect.top;
  } else if (rowRect.bottom > visibleBottom) {
    container.scrollTop += rowRect.bottom - visibleBottom;
  }
}

function handleChoiceGridNavigation(event, {
  container,
  inputSelector,
  rowSelector,
  selectRadioOnMove = false,
}) {
  if (event.altKey || event.ctrlKey || event.metaKey) return false;
  if (!choiceGridNavigationShortcuts.split(" ").includes(event.key)) return false;
  const input = event.target.closest(inputSelector);
  if (!input || !container.contains(input)) return false;
  const inputs = [...container.querySelectorAll(inputSelector)]
    .filter((candidate) => !candidate.disabled);
  const currentIndex = inputs.indexOf(input);
  if (currentIndex < 0 || !inputs.length) return false;

  const rows = inputs.map((candidate) => candidate.closest(rowSelector));
  const cardSelector = `:scope > ${rowSelector}`;
  const columns = renderedGridColumnCount(container, cardSelector);
  const pageItems = renderedGridPageItemCount(
    container,
    container,
    cardSelector
  );
  const pageStep = Math.max(columns, pageItems - columns);
  const movement = {
    ArrowLeft: -1,
    ArrowRight: 1,
    ArrowUp: -columns,
    ArrowDown: columns,
    PageUp: -pageStep,
    PageDown: pageStep,
  }[event.key];
  const targetIndex = event.key === "Home" ? 0
    : event.key === "End" ? inputs.length - 1
      : Math.max(0, Math.min(inputs.length - 1, currentIndex + movement));
  const target = inputs[targetIndex];
  const targetRow = rows[targetIndex];
  if (!target || !targetRow) return false;

  event.preventDefault();
  event.stopPropagation();
  target.focus({ preventScroll: true });
  if (selectRadioOnMove && target.type === "radio" && !target.checked) {
    target.click();
  }
  revealCheckboxGridRow(container, targetRow);
  return true;
}

function tagGroupNavigationViewport(toggle, fallback) {
  for (let candidate = toggle?.parentElement; candidate; candidate = candidate.parentElement) {
    const overflowY = getComputedStyle(candidate).overflowY;
    if (["auto", "scroll", "overlay"].includes(overflowY)) return candidate;
    if (candidate === document.body) break;
  }
  return fallback;
}

function handleTagGroupNavigationKeydown(
  event,
  { container, selector, toggleGroup }
) {
  const toggle = event.target.closest(selector);
  if (!toggle || event.altKey || event.ctrlKey || event.metaKey) return false;
  const disclosureKeys = ["ArrowLeft", "ArrowRight"];
  const movementKeys = ["ArrowUp", "ArrowDown", "PageUp", "PageDown", "Home", "End"];
  if (![...disclosureKeys, ...movementKeys].includes(event.key)) return false;

  event.preventDefault();
  event.stopPropagation();
  if (disclosureKeys.includes(event.key)) {
    const expanded = toggle.getAttribute("aria-expanded") === "true";
    const wantsExpanded = event.key === "ArrowRight";
    if (expanded !== wantsExpanded) toggleGroup(toggle);
    return true;
  }

  const toggles = [...container.querySelectorAll(selector)]
    .filter((candidate) => !candidate.closest(".hidden"));
  const currentIndex = toggles.indexOf(toggle);
  if (currentIndex < 0) return true;
  const viewport = tagGroupNavigationViewport(toggle, container);
  const targetIndex = longListNavigationTarget(
    toggles,
    currentIndex,
    event.key,
    viewport
  );
  const target = toggles[targetIndex];
  target?.focus({ preventScroll: true });
  target?.scrollIntoView({ block: "nearest", inline: "nearest" });
  return true;
}

function selectJobRow(jobID, { focus = false } = {}) {
  if (!state.jobs.some((job) => job.id === jobID)) return;
  state.focusedActivityJobID = jobID;
  const jobsByID = new Map(state.jobs.map((job) => [job.id, job]));
  for (const row of jobRows()) {
    const selected = row.dataset.jobRowId === jobID;
    if (row.classList.contains("focused") !== selected) {
      row.classList.toggle("focused", selected);
    }
    if (selected && row.getAttribute("aria-current") !== "true") {
      row.setAttribute("aria-current", "true");
    } else if (!selected && row.hasAttribute("aria-current")) {
      row.removeAttribute("aria-current");
    }
    const tabIndex = selected ? 0 : -1;
    if (row.tabIndex !== tabIndex) row.tabIndex = tabIndex;
    const job = jobsByID.get(row.dataset.jobRowId);
    const fingerprint = job ? jobRowFingerprint(job, selected) : null;
    if (fingerprint && row.dataset.jobFingerprint !== fingerprint) {
      row.dataset.jobFingerprint = fingerprint;
    }
  }
  if (focus) {
    requestAnimationFrame(() => {
      elements.jobsList.querySelector(
        `[data-job-row-id="${CSS.escape(jobID)}"]`
      )?.focus({ preventScroll: true });
    });
  }
}

function moveJobSelection(key) {
  const rows = jobRows();
  if (!rows.length) return;
  const current = Math.max(
    0,
    rows.findIndex((row) => row.dataset.jobRowId === state.focusedActivityJobID)
  );
  const next = longListNavigationTarget(rows, current, key, elements.jobsList);
  selectJobRow(rows[next].dataset.jobRowId, { focus: true });
  rows[next].scrollIntoView({ block: "nearest" });
}

function syncJobsRefreshControl() {
  const busy = state.jobsRefreshing && state.jobsRefreshIndicated;
  elements.refreshJobsButton.disabled = state.jobsRefreshing;
  elements.refreshJobsButton.classList.toggle("busy", busy);
  elements.refreshJobsButton.setAttribute("aria-busy", String(busy));
  elements.refreshJobsButton.setAttribute(
    "aria-label",
    busy ? "正在刷新活动" : (state.online ? "刷新活动" : "重试刷新活动")
  );
  elements.refreshJobsButton.title = busy
    ? "正在读取后台任务…"
    : (state.online ? "刷新活动（R）" : "重新连接并刷新活动（R）");
}

function captureJobFocusSnapshot() {
  const active = document.activeElement;
  const row = active?.closest?.("[data-job-row-id]");
  if (!row) return null;
  return {
    jobID: row.dataset.jobRowId,
    action: active.dataset.action || null,
    opensSlimming: Boolean(active.dataset.openSlimmingJobId),
  };
}

function restoreJobFocusSnapshot(snapshot) {
  if (elements.jobsPopover.classList.contains("hidden")) return;
  const preferredID = snapshot?.jobID || state.focusedActivityJobID;
  const preferredRow = preferredID
    ? elements.jobsList.querySelector(
      `[data-job-row-id="${CSS.escape(preferredID)}"]`
    )
    : null;
  const row = preferredRow
    || elements.jobsList.querySelector('[data-job-row-id][aria-current="true"]')
    || elements.jobsList.querySelector("[data-job-row-id]");
  if (!row) {
    elements.refreshJobsButton.focus({ preventScroll: true });
    return;
  }
  const matchingAction = snapshot?.action
    ? row.querySelector(`[data-action="${CSS.escape(snapshot.action)}"]`)
    : null;
  const firstAvailableAction = row.querySelector(".job-actions button:not(:disabled)");
  const target = snapshot?.action
    ? (matchingAction && !matchingAction.disabled ? matchingAction : null)
      || firstAvailableAction
      || row
    : (snapshot?.opensSlimming
      ? row.querySelector("[data-open-slimming-job-id]")
        || firstAvailableAction
        || row
      : row);
  target.focus({ preventScroll: true });
}

async function refreshJobs({
  announce = true,
  indicateBusy = true,
  reportError = true,
} = {}) {
  if (state.jobsRefreshing) return;
  const generation = state.workspaceGeneration;
  const focusSnapshot = captureJobFocusSnapshot();
  const headerFocusID = !focusSnapshot
    && document.activeElement?.closest?.(".popover-heading-actions")
    ? document.activeElement.id
    : null;
  const selectedJobID = state.focusedActivityJobID;
  const scrollTop = elements.jobsList.scrollTop;
  const restoreActivityContext = () => {
    requestAnimationFrame(() => {
      if (generation !== state.workspaceGeneration) return;
      elements.jobsList.scrollTop = scrollTop;
      const headerFocus = headerFocusID ? document.getElementById(headerFocusID) : null;
      if (headerFocus instanceof HTMLElement && !headerFocus.disabled) {
        headerFocus.focus({ preventScroll: true });
      } else {
        restoreJobFocusSnapshot(focusSnapshot);
      }
      elements.jobsList.scrollTop = scrollTop;
    });
  };
  state.jobsRefreshing = true;
  state.jobsRefreshIndicated = indicateBusy;
  syncJobsRefreshControl();
  try {
    const jobs = await api("/v1/jobs");
    if (generation !== state.workspaceGeneration) return;
    state.jobs = jobs;
    if (selectedJobID && jobs.some((job) => job.id === selectedJobID)) {
      state.focusedActivityJobID = selectedJobID;
    }
    renderJobs();
    restoreActivityContext();
    if (announce) toast("活动已刷新");
  } catch (error) {
    if (generation === state.workspaceGeneration) {
      if (reportError) toast(error.message || "活动刷新失败");
      restoreActivityContext();
    }
  } finally {
    state.jobsRefreshing = false;
    state.jobsRefreshIndicated = false;
    syncJobsRefreshControl();
    scheduleCatalogProgressPoll();
  }
}

function jobsBaseLevelFromHistory(context = {}) {
  return ["sidebar", "inspector", "lightbox"].includes(context.jobsBaseLevel)
    ? context.jobsBaseLevel
    : "workspace";
}

function replaceJobsHistoryWithBase(baseLevel) {
  if (!state.workspaceNavigation.initialized
    || elements.appView.classList.contains("hidden")) return;
  const current = activeWorkspaceHistoryEntry();
  const route = visibleWorkspaceRoute();
  if (current?.route !== route || current.navigationLevel !== "jobs") return;
  const context = currentWorkspaceHistoryContext(route);
  if (context && typeof context === "object") delete context.jobsBaseLevel;
  const navigationLevel = visibleWorkspaceNavigationBaseLevel(route, baseLevel);
  history.replaceState({
    ...(history.state || {}),
    [WORKSPACE_HISTORY_KEY]: workspaceHistoryEntry(route, context, navigationLevel),
  }, "", location.href);
}

function clearJobsPopoverState() {
  state.jobsReturnFocus = null;
  state.jobsReturnTarget = null;
  state.jobsBaseLevel = "workspace";
  state.jobsHistoryRestoreFocus = true;
  state.jobsFocusSnapshot = null;
  state.jobsScrollTop = 0;
  state.jobsRestorable = false;
  state.jobsOpening = false;
}

function closeJobsPopover({
  restoreFocus = true,
  checkpoint = true,
  preserveState = false,
} = {}) {
  const wasOpen = !elements.jobsPopover.classList.contains("hidden");
  if (!wasOpen) return;
  state.jobsFocusSnapshot = captureJobFocusSnapshot();
  state.jobsScrollTop = elements.jobsList.scrollTop;
  const baseLevel = state.jobsBaseLevel;
  const returnFocus = state.jobsReturnFocus;
  const returnTarget = state.jobsReturnTarget;
  elements.jobsPopover.classList.add("hidden");
  if (checkpoint) replaceJobsHistoryWithBase(baseLevel);
  if (!preserveState) clearJobsPopoverState();
  if (!restoreFocus) return;
  const resolveReturnFocus = () => {
    const target = returnTarget?.trainingRunID
      ? elements.trainingRunList.querySelector(
        `[data-training-run-id="${CSS.escape(returnTarget.trainingRunID)}"]`
      )
      : (returnTarget?.reviewTrainingJobID
        ? elements.reviewOverviewGrid.querySelector(
          `[data-review-training-job-id="${CSS.escape(returnTarget.reviewTrainingJobID)}"]`
        )
        : (returnTarget?.slimmingJobID
          ? elements.slimmingJobList.querySelector(
            `[data-slimming-job-id="${CSS.escape(returnTarget.slimmingJobID)}"]`
          )
          : null));
    const fallback = returnFocus instanceof HTMLElement && document.contains(returnFocus)
      ? returnFocus
      : elements.jobsButton;
    return target || fallback;
  };
  stabilizeDismissedOverlayFocus(
    resolveReturnFocus,
    elements.jobsPopover,
    () => elements.jobsPopover.classList.contains("hidden")
  );
}

function openJobsPopover({
  jobID = null,
  refreshProjection = true,
  historyMode = "pushJobs",
  baseLevel = null,
  focus = true,
  returnFocus = null,
} = {}) {
  if (state.jobsOpening) return;
  if (!elements.jobsPopover.classList.contains("hidden")) {
    if (focus) restoreJobFocusSnapshot(state.jobsFocusSnapshot);
    return;
  }
  state.jobsOpening = true;
  const restoring = historyMode === "none" && state.jobsRestorable;
  try {
    if (!restoring) {
      const origin = returnFocus instanceof HTMLElement
        ? returnFocus
        : document.activeElement;
      state.jobsReturnFocus = origin;
      state.jobsReturnTarget = {
        trainingRunID: origin?.closest?.("[data-training-run-id]")
          ?.dataset.trainingRunId || null,
        reviewTrainingJobID: origin?.closest?.("[data-review-training-job-id]")
          ?.dataset.reviewTrainingJobId || null,
        slimmingJobID: origin?.closest?.("[data-slimming-job-id]")
          ?.dataset.slimmingJobId || null,
      };
      state.jobsFocusSnapshot = null;
      state.jobsScrollTop = 0;
    }
    const current = activeWorkspaceHistoryEntry();
    const replacesOverlay = historyMode === "pushJobs"
      && ["actionMenu", "layoutMenu"].includes(current?.navigationLevel);
    state.jobsBaseLevel = baseLevel
      || workspaceNavigationBaseLevel(
        current?.navigationLevel || "workspace",
        current?.context || {}
      );
    closeCompactToolbarMenu({ restoreFocus: false });
    closeLayoutMenu({ restoreFocus: false, checkpoint: !replacesOverlay });
    closeFilterPopover({ restoreFocus: false });
    closeActionMenu({ restoreFocus: false, checkpoint: !replacesOverlay });
    elements.jobsPopover.classList.remove("hidden");
    const targetID = jobID && state.jobs.some((job) => job.id === jobID)
      ? jobID
      : (state.jobsFocusSnapshot?.jobID
        && state.jobs.some((job) => job.id === state.jobsFocusSnapshot.jobID)
        ? state.jobsFocusSnapshot.jobID
        : (state.focusedActivityJobID
          && state.jobs.some((job) => job.id === state.focusedActivityJobID)
          ? state.focusedActivityJobID
          : state.jobs[0]?.id));
    if (targetID) selectJobRow(targetID);
    if (historyMode !== "none") {
      const route = visibleWorkspaceRoute();
      recordWorkspaceHistory(
        route,
        currentWorkspaceHistoryContext(route),
        replacesOverlay ? "replaceOverlay" : historyMode
      );
    }
    state.jobsRestorable = true;
    requestAnimationFrame(() => {
      elements.jobsList.scrollTop = state.jobsScrollTop;
      if (!focus) return;
      if (restoring) restoreJobFocusSnapshot(state.jobsFocusSnapshot);
      else if (targetID) selectJobRow(targetID, { focus: true });
      else elements.refreshJobsButton.focus({ preventScroll: true });
    });
    if (refreshProjection) void refreshJobs({ announce: false });
  } finally {
    state.jobsOpening = false;
  }
}

function returnFromJobsPopover({ restoreFocus = true } = {}) {
  if (elements.jobsPopover.classList.contains("hidden")) return Promise.resolve();
  state.jobsHistoryRestoreFocus = restoreFocus;
  if (state.workspaceNavigation.pendingReturnPromise) {
    return state.workspaceNavigation.pendingReturnPromise;
  }
  const current = activeWorkspaceHistoryEntry();
  if (state.workspaceNavigation.initialized
    && current?.route === visibleWorkspaceRoute()
    && current.navigationLevel === "jobs") {
    const pending = new Promise((resolve) => {
      state.workspaceNavigation.pendingReturnResolve = resolve;
    });
    state.workspaceNavigation.pendingReturnPromise = pending;
    history.back();
    return pending;
  }
  closeJobsPopover({ restoreFocus });
  state.jobsHistoryRestoreFocus = true;
  return Promise.resolve();
}

function reconcileJobsPopoverFromWorkspaceHistory(route, navigationLevel, context = {}) {
  const shouldOpen = navigationLevel === "jobs" && route === visibleWorkspaceRoute();
  if (shouldOpen && !state.jobsRestorable) {
    clearJobsPopoverState();
    if (history.length > 1 && Object.prototype.hasOwnProperty.call(
      context,
      "jobsBaseLevel"
    )) {
      history.back();
    } else {
      replaceJobsHistoryWithBase(jobsBaseLevelFromHistory(context));
    }
    return;
  }
  if (shouldOpen && elements.jobsPopover.classList.contains("hidden")) {
    openJobsPopover({
      refreshProjection: false,
      historyMode: "none",
      baseLevel: jobsBaseLevelFromHistory(context),
    });
  } else if (!shouldOpen && !elements.jobsPopover.classList.contains("hidden")) {
    const restoreFocus = state.jobsHistoryRestoreFocus;
    closeJobsPopover({ restoreFocus, checkpoint: false, preserveState: true });
    state.jobsHistoryRestoreFocus = true;
  }
}

function toggleJobsPopover() {
  if (elements.jobsPopover.classList.contains("hidden")) openJobsPopover();
  else void returnFromJobsPopover();
}

function openJobsFromKeyboardShortcut() {
  const trainingOpen = !elements.trainingWorkspace.classList.contains("hidden");
  const selectedRun = trainingOpen
    ? state.training.runs.find((run) => run.id === state.training.selectedRunID)
    : null;
  if (selectedRun?.jobID) void openAssociatedJob(selectedRun.jobID);
  else openJobsPopover();
}

function jobRowFingerprint(job, selected) {
  return JSON.stringify([
    job,
    Boolean(selected),
    Boolean(state.online),
    state.jobMutatingIDs.has(job.id),
  ]);
}

function syncJobRowDiagnostic(row, job) {
  const showsDiagnostic = job.attempts != null || job.lastErrorCode;
  let diagnostic = row.querySelector(":scope > .job-diagnostic");
  if (!showsDiagnostic) {
    diagnostic?.remove();
    return null;
  }
  if (!diagnostic) {
    diagnostic = document.createElement("div");
    diagnostic.className = "job-diagnostic";
  }
  const wanted = [];
  if (job.attempts != null) {
    let attempts = diagnostic.querySelector('[data-job-diagnostic="attempts"]');
    if (!attempts) {
      attempts = document.createElement("span");
      attempts.dataset.jobDiagnostic = "attempts";
    }
    attempts.textContent = `尝试 ${job.attempts}/${job.maxAttempts ?? "—"}`;
    wanted.push(attempts);
  }
  if (job.lastErrorCode) {
    let guidance = diagnostic.querySelector('[data-job-diagnostic="guidance"]');
    if (!guidance) {
      guidance = document.createElement("span");
      guidance.dataset.jobDiagnostic = "guidance";
    }
    guidance.textContent = jobFailureGuidance(job);
    let code = diagnostic.querySelector('[data-job-diagnostic="code"]');
    if (!code) {
      code = document.createElement("code");
      code.dataset.jobDiagnostic = "code";
    }
    code.textContent = job.lastErrorCode;
    wanted.push(guidance, code);
  }
  for (const [index, child] of wanted.entries()) {
    if (diagnostic.children[index] !== child) {
      diagnostic.insertBefore(child, diagnostic.children[index] || null);
    }
  }
  for (const child of [...diagnostic.children]) {
    if (!wanted.includes(child)) child.remove();
  }
  return diagnostic;
}

function jobActionSemanticKey(button) {
  if (button.dataset.openSlimmingJobId) return "openSlimming";
  return button.dataset.action ? `action:${button.dataset.action}` : null;
}

function syncJobRowActions(row, job) {
  const availableActions = job.availableActions || [];
  const opensSlimming = job.navigationTarget?.workspace === "librarySlimming";
  let actions = row.querySelector(":scope > .job-actions");
  if (!availableActions.length && !opensSlimming) {
    actions?.remove();
    return null;
  }
  if (!actions) {
    actions = document.createElement("div");
    actions.className = "job-actions";
  }
  const existing = new Map(
    [...actions.querySelectorAll(":scope > button")]
      .map((button) => [jobActionSemanticKey(button), button])
      .filter(([key]) => key)
  );
  const wanted = [];
  if (opensSlimming) {
    const open = existing.get("openSlimming") || document.createElement("button");
    open.type = "button";
    open.className = "button job-action job-context-action";
    open.dataset.openSlimmingJobId = job.id;
    open.textContent = "在图库瘦身中查看";
    wanted.push(open);
  }
  for (const action of availableActions) {
    const key = `action:${action}`;
    const button = existing.get(key) || document.createElement("button");
    button.type = "button";
    button.className = "button job-action write-action";
    button.dataset.jobId = job.id;
    button.dataset.action = action;
    button.disabled = !state.online || state.jobMutatingIDs.has(job.id);
    button.textContent = jobActionText(action);
    wanted.push(button);
  }
  for (const [index, button] of wanted.entries()) {
    if (actions.children[index] !== button) {
      actions.insertBefore(button, actions.children[index] || null);
    }
  }
  for (const button of [...actions.children]) {
    if (!wanted.includes(button)) button.remove();
  }
  return actions;
}

function syncJobRow(row, job, selected) {
  row.className = "job-row";
  row.tabIndex = selected ? 0 : -1;
  row.setAttribute("role", "listitem");
  if (selected) row.setAttribute("aria-current", "true");
  else row.removeAttribute("aria-current");
  row.dataset.jobRowId = job.id;
  row.classList.toggle("focused", selected);

  let heading = row.querySelector(":scope > .job-heading");
  if (!heading) {
    heading = document.createElement("div");
    heading.className = "job-heading";
    row.append(heading);
  }
  let title = heading.querySelector(":scope > strong");
  if (!title) {
    title = document.createElement("strong");
    heading.append(title);
  }
  title.textContent = jobTitle(job);
  let stateLabel = heading.querySelector(":scope > .secondary");
  if (!stateLabel) {
    stateLabel = document.createElement("span");
    stateLabel.className = "secondary";
    heading.append(stateLabel);
  }
  stateLabel.textContent = jobStateText(job);

  const completed = Number(job.progress?.completedUnitCount || 0);
  const total = Number(job.progress?.totalUnitCount || 0);
  const percent = total > 0 ? Math.max(0, Math.min(100, completed / total * 100)) : 0;
  let progress = row.querySelector(":scope > .job-progress");
  if (!progress) {
    progress = document.createElement("div");
    progress.className = "job-progress";
    row.append(progress);
  }
  progress.classList.toggle(
    "indeterminate",
    total <= 0 && ["pending", "running"].includes(job.state)
  );
  let fill = progress.querySelector(":scope > span");
  if (!fill) {
    fill = document.createElement("span");
    progress.append(fill);
  }
  fill.style.width = `${percent}%`;

  let stateLine = row.querySelector(":scope > .job-state-line");
  if (!stateLine) {
    stateLine = document.createElement("div");
    stateLine.className = "job-state-line";
    row.append(stateLine);
  }
  let amount = stateLine.querySelector(':scope > [data-job-state-part="amount"]');
  if (!amount) {
    amount = document.createElement("span");
    amount.dataset.jobStatePart = "amount";
    stateLine.append(amount);
  }
  amount.textContent = total > 0 ? `${completed} / ${total}` : `${completed} 项`;
  let percentLabel = stateLine.querySelector(':scope > [data-job-state-part="percent"]');
  if (!percentLabel) {
    percentLabel = document.createElement("span");
    percentLabel.dataset.jobStatePart = "percent";
    stateLine.append(percentLabel);
  }
  percentLabel.textContent = total > 0 ? `${Math.round(percent)}%` : "";

  const diagnostic = syncJobRowDiagnostic(row, job);
  const actions = syncJobRowActions(row, job);
  const children = [heading, progress, stateLine, diagnostic, actions].filter(Boolean);
  for (const [index, child] of children.entries()) {
    if (row.children[index] !== child) {
      row.insertBefore(child, row.children[index] || null);
    }
  }
  for (const child of [...row.children]) {
    if (!children.includes(child)) child.remove();
  }
  row.dataset.jobFingerprint = jobRowFingerprint(job, selected);
}

function renderJobs() {
  const focusSnapshot = captureJobFocusSnapshot();
  const scrollTop = elements.jobsList.scrollTop;
  syncJobsRefreshControl();
  syncCatalogProgressStatus();
  scheduleCatalogProgressPoll();
  elements.jobsEmpty.classList.toggle("hidden", state.jobs.length > 0);
  const activeCount = state.jobs.filter((job) =>
    ["pending", "running", "paused", "retryableFailed"].includes(job.state)
  ).length;
  elements.jobsBadge.textContent = String(activeCount);
  elements.jobsBadge.classList.toggle("hidden", activeCount === 0);
  if (!state.jobs.some((job) => job.id === state.focusedActivityJobID)) {
    state.focusedActivityJobID = state.jobs[0]?.id || null;
  }

  const existing = new Map(
    jobRows().map((row) => [row.dataset.jobRowId, row])
  );
  const wanted = [];
  for (const job of state.jobs) {
    const selected = state.focusedActivityJobID === job.id;
    const row = existing.get(job.id) || document.createElement("article");
    const fingerprint = jobRowFingerprint(job, selected);
    if (row.dataset.jobFingerprint !== fingerprint) {
      syncJobRow(row, job, selected);
    }
    wanted.push(row);
  }
  for (const [index, row] of wanted.entries()) {
    if (elements.jobsList.children[index] !== row) {
      elements.jobsList.insertBefore(row, elements.jobsList.children[index] || null);
    }
  }
  for (const row of [...elements.jobsList.children]) {
    if (!wanted.includes(row)) row.remove();
  }
  elements.jobsList.scrollTop = scrollTop;
  if (focusSnapshot) {
    restoreJobFocusSnapshot(focusSnapshot);
    elements.jobsList.scrollTop = scrollTop;
  }
}

async function applyJobAction(jobID, action) {
  if (!state.online || state.jobMutatingIDs.has(jobID)) return;
  const generation = state.workspaceGeneration;
  state.jobMutatingIDs.add(jobID);
  syncWriteActionControls();
  try {
    await api(`/v1/jobs/${jobID}/actions`, {
      method: "POST",
      body: JSON.stringify({ action }),
    });
    if (generation !== state.workspaceGeneration) return;
    try {
      const jobs = await api("/v1/jobs");
      if (generation !== state.workspaceGeneration) return;
      state.jobs = jobs;
      renderJobs();
      if (!elements.trainingWorkspace.classList.contains("hidden")) {
        await loadTrainingWorkspace({ quiet: true });
      }
      if (!elements.reviewWorkspace.classList.contains("hidden")) {
        await loadReviewOverview();
      }
      toast(`任务已${jobActionText(action)}`);
    } catch {
      if (generation !== state.workspaceGeneration) return;
      void refreshWorkspace({ quiet: true, kinds: ["jobsChanged"] });
      toast(`任务已${jobActionText(action)}，状态同步暂时失败，正在重试`);
    }
  } catch (error) {
    if (generation === state.workspaceGeneration) {
      toast(error.message || "任务操作失败");
    }
  } finally {
    if (generation === state.workspaceGeneration) {
      state.jobMutatingIDs.delete(jobID);
      syncWriteActionControls();
      restoreTrainingDetailActionFocus();
    }
  }
}

async function openAssociatedJob(jobID) {
  state.training.focusedJobID = jobID;
  await openAssociatedActivity(jobID);
}

async function openAssociatedActivity(jobID) {
  state.focusedActivityJobID = jobID;
  try {
    state.jobs = await api("/v1/jobs");
    renderJobs();
  } catch (error) {
    toast(error.message || "关联任务载入失败");
    return;
  }
  openJobsPopover({ jobID, refreshProjection: false });
  const row = elements.jobsList.querySelector(`[data-job-row-id="${CSS.escape(jobID)}"]`);
  if (!row) {
    toast("关联任务已不在当前任务列表中，历史记录仍会保留");
    return;
  }
  row.scrollIntoView({ block: "nearest" });
}

async function openSlimmingJobFromActivity(jobID) {
  const job = state.jobs.find((item) => item.id === jobID);
  const target = job?.navigationTarget;
  if (!target || target.workspace !== "librarySlimming") {
    toast("这个任务没有可打开的图库瘦身记录");
    return;
  }
  state.focusedActivityJobID = jobID;
  state.slimming.view = "analysis";
  state.slimming.mediaKind = target.mediaKind || "image";
  state.slimming.selectedJobID = target.recordID;
  state.slimming.selectedClusterID = null;
  state.slimming.selectedMemberIDs.clear();
  state.slimming.selectionAnchorID = null;
  state.slimming.clusterLimit = 48;
  state.slimming.memberLimit = 96;
  await openSlimmingWorkspace();
  focusSelectedSlimmingJob();
}

