function syncReviewControls() {
  const controlsLocked = state.review.loading
    || state.review.overviewLoading
    || state.review.mutating;
  const selectionControlsLocked = state.review.overviewLoading
    || state.review.mutating;
  const hasSelection = state.review.selectedAssetIDs.size > 0;
  elements.loadMoreReviewButton.disabled = controlsLocked;
  elements.reviewTagSelect.disabled = controlsLocked || activeTags().length === 0;
  elements.refreshReviewButton.disabled = controlsLocked;
  elements.reviewBackButton.disabled = controlsLocked;
  syncReviewSelectionModeControls({ controlsLocked: selectionControlsLocked });
  elements.reviewThumbnailLayoutControls.classList.toggle(
    "hidden",
    state.review.mode !== "queue" || state.review.items.length === 0
  );
  renderReviewSourceFilter();
  renderReviewSuggestionLimit();
  configureReviewWorkspacePersistentHelp();
  document.querySelectorAll(".review-action").forEach((button) => {
    button.disabled = !state.online || controlsLocked || !hasSelection;
  });
  renderReviewInspectorActions();
  syncInlineTagCreationControls();
}

function reviewTaskStatusText(status, overview) {
  const progress = overview.totalCount == null
    ? `${overview.checkedCount} 项已检查`
    : `${overview.checkedCount} / ${overview.totalCount} 项已检查`;
  return {
    notReady: `样本尚未就绪 · ${progress}`,
    ready: `可以生成建议 · ${progress}`,
    waiting: `等待处理 · ${progress}`,
    running: `正在生成建议 · ${progress}`,
    paused: `生成已暂停 · ${progress}`,
    retryableFailure: `生成遇到问题，可在 Mac 端重试 · ${progress}`,
    completed: `本轮生成完成 · ${progress}`,
    terminalFailure: `生成失败，请在 Mac 端检查 · ${progress}`,
    cancelled: `生成已取消 · ${progress}`,
  }[status] || progress;
}

function reviewOverviewGroupSections() {
  const remaining = new Map(state.review.overview.map((overview) => [overview.id, overview]));
  const sections = [];
  for (const group of orderedTagGroups()) {
    const overviews = orderedTagsInGroup(
      activeTags().filter((tag) => tag.groupID === group.id),
      group.id
    ).map((tag) => remaining.get(tag.id)).filter(Boolean);
    for (const overview of overviews) remaining.delete(overview.id);
    if (overviews.length) {
      sections.push({ id: group.id, displayName: group.displayName, overviews });
    }
  }
  const unmatched = state.review.overview.filter((overview) => remaining.has(overview.id));
  if (unmatched.length) {
    sections.push({ id: "other", displayName: "其他", overviews: unmatched });
  }
  return sections.length
    ? sections
    : (state.review.overview.length
      ? [{ id: "all", displayName: "标签", overviews: state.review.overview }]
      : []);
}

function reviewOverviewStableNodeKey(node) {
  if (!(node instanceof Element)) return null;
  if (node.dataset.reviewOverviewCardId) {
    return `card:${node.dataset.reviewOverviewCardId}`;
  }
  if (node.dataset.reviewOverviewTagId) {
    return `open:${node.dataset.reviewOverviewTagId}`;
  }
  if (node.dataset.reviewControlTagId) {
    return `details:${node.dataset.reviewControlTagId}`;
  }
  if (node.tagName === "SUMMARY" && node.parentElement?.dataset.reviewControlTagId) {
    return `summary:${node.parentElement.dataset.reviewControlTagId}`;
  }
  if (node.dataset.tagSuggestionMethod && node.dataset.tagId) {
    return `personal:${node.dataset.tagId}:${node.dataset.tagSuggestionMethod}`;
  }
  if (node.dataset.reviewFeatureTagId) {
    return `feature:${node.dataset.reviewFeatureTagId}:${node.dataset.reviewFeatureMode || ""}`;
  }
  if (node.dataset.reviewTrainingJobId) {
    return `training:${node.dataset.reviewTrainingJobId}`;
  }
  if (node.dataset.jobId && node.dataset.action) {
    return `job:${node.dataset.jobId}:${node.dataset.action}`;
  }
  if (node.dataset.cancelTagSuggestionId) {
    return `cancel:${node.dataset.cancelTagSuggestionId}`;
  }
  if (node.dataset.thresholdFocus && node.dataset.thresholdTagId && node.dataset.thresholdMethod) {
    return `threshold:${node.dataset.thresholdFocus}:${node.dataset.thresholdTagId}:${node.dataset.thresholdMethod}`;
  }
  return null;
}

function reviewOverviewPartKey(node, index) {
  if (node.nodeType === Node.TEXT_NODE) return `text:${index}`;
  if (!(node instanceof Element)) return `node:${node.nodeType}:${index}`;
  const stableKey = reviewOverviewStableNodeKey(node);
  if (stableKey) return `stable:${stableKey}`;
  if (node.dataset.reviewOverviewPart) {
    return `part:${node.dataset.reviewOverviewPart}`;
  }
  return `element:${node.tagName}:${node.className}:${index}`;
}

function syncReviewOverviewAttributes(target, source) {
  for (const attribute of [...target.attributes]) {
    if (!source.hasAttribute(attribute.name)) target.removeAttribute(attribute.name);
  }
  for (const attribute of source.attributes) {
    if (target.getAttribute(attribute.name) !== attribute.value) {
      target.setAttribute(attribute.name, attribute.value);
    }
  }
  if ("disabled" in target && "disabled" in source && target.disabled !== source.disabled) {
    target.disabled = source.disabled;
  }
  if (
    target instanceof HTMLInputElement
    && source instanceof HTMLInputElement
    && target.value !== source.value
  ) {
    target.value = source.value;
  }
  if (
    target instanceof HTMLDetailsElement
    && source instanceof HTMLDetailsElement
    && target.open !== source.open
  ) {
    target.open = source.open;
  }
}

function syncReviewOverviewText(element, text) {
  if (
    element.childNodes.length === 1
    && element.firstChild?.nodeType === Node.TEXT_NODE
  ) {
    if (element.firstChild.data !== text) element.firstChild.data = text;
    return;
  }
  if (!element.childNodes.length) {
    element.append(document.createTextNode(text));
    return;
  }
  if (element.textContent !== text) element.textContent = text;
}

function syncReviewOverviewNode(target, source) {
  if (target === source) return target;
  if (target.nodeType === Node.TEXT_NODE && source.nodeType === Node.TEXT_NODE) {
    if (target.data !== source.data) target.data = source.data;
    return target;
  }
  if (!(target instanceof Element) || !(source instanceof Element)) return source;
  if (target.tagName !== source.tagName) return source;
  syncReviewOverviewAttributes(target, source);
  const existingByKey = new Map(
    [...target.childNodes].map((child, index) => [reviewOverviewPartKey(child, index), child])
  );
  const wanted = [...source.childNodes].map((child, index) => {
    if (target.contains(child)) return child;
    const existing = existingByKey.get(reviewOverviewPartKey(child, index));
    if (!existing) return child;
    return syncReviewOverviewNode(existing, child);
  });
  reconcileStableChildren(target, wanted);
  return target;
}

function syncReviewOverviewStableNode(target, source) {
  syncReviewOverviewNode(target, source);
}

function reconcileReviewOverviewCard(existingCard, renderedCard) {
  syncReviewOverviewStableNode(existingCard, renderedCard);
  return existingCard;
}

function syncReviewOverviewGroupToggle(toggle, section, collapsed) {
  toggle.type = "button";
  toggle.className = "review-overview-group-toggle";
  toggle.dataset.reviewOverviewGroupToggle = section.id;
  toggle.setAttribute("aria-expanded", String(!collapsed));
  toggle.setAttribute(
    "aria-keyshortcuts",
    "ArrowLeft ArrowRight ArrowUp ArrowDown PageUp PageDown Home End"
  );
  const chevron = toggle.querySelector(':scope > [data-review-overview-part="group-chevron"]')
    || document.createElement("span");
  chevron.dataset.reviewOverviewPart = "group-chevron";
  chevron.setAttribute("aria-hidden", "true");
  syncReviewOverviewText(chevron, collapsed ? "›" : "⌄");
  const title = toggle.querySelector(':scope > [data-review-overview-part="group-title"]')
    || document.createElement("strong");
  title.dataset.reviewOverviewPart = "group-title";
  syncReviewOverviewText(title, section.displayName);
  const count = toggle.querySelector(':scope > [data-review-overview-part="group-count"]')
    || document.createElement("span");
  count.dataset.reviewOverviewPart = "group-count";
  syncReviewOverviewText(count, `${section.overviews.length} 个标签`);
  const pending = toggle.querySelector(':scope > [data-review-overview-part="group-pending"]')
    || document.createElement("span");
  pending.dataset.reviewOverviewPart = "group-pending";
  pending.className = "review-overview-group-pending";
  syncReviewOverviewText(pending, `${section.overviews.reduce(
    (total, overview) => total + (overview.pendingSuggestionCount || 0),
    0
  )} 条待审`);
  configurePersistentHelp(toggle, {
    title: `${collapsed ? "展开" : "折叠"}“${section.displayName}”分组`,
    detail: `只改变审核总览中“${section.displayName}”的显示；不会改变侧栏或检查器的标签分组状态。左/右折叠或展开；上/下、Page Up/Page Down 或 Home/End 在分组间移动。`,
    kind: "review",
    keyShortcuts: "ArrowLeft ArrowRight ArrowUp ArrowDown PageUp PageDown Home End",
  });
  reconcileStableChildren(toggle, [chevron, title, count, pending]);
}

function toggleReviewOverviewGroup(groupID) {
  if (state.layout.collapsedReviewTagGroupIDs.has(groupID)) {
    state.layout.collapsedReviewTagGroupIDs.delete(groupID);
  } else {
    state.layout.collapsedReviewTagGroupIDs.add(groupID);
  }
  persistWorkspacePreferences();
  renderReviewOverview({ reconcileContent: true });
}

function organizeReviewOverviewGroups() {
  const cardsByTagID = new Map(
    [...elements.reviewOverviewGrid.querySelectorAll(".review-overview-card")].map((card) => [
      card.querySelector("[data-review-overview-tag-id]")?.dataset.reviewOverviewTagId,
      card,
    ])
  );
  const existingGroups = new Map(
    [...elements.reviewOverviewGrid.querySelectorAll(":scope > [data-review-overview-group-id]")]
      .map((group) => [group.dataset.reviewOverviewGroupId, group])
  );
  for (const [index, section] of reviewOverviewGroupSections().entries()) {
    const collapsed = state.layout.collapsedReviewTagGroupIDs.has(section.id);
    const group = existingGroups.get(section.id) || document.createElement("section");
    existingGroups.delete(section.id);
    group.className = "review-overview-group";
    group.dataset.reviewOverviewGroupId = section.id;
    const toggle = group.querySelector(":scope > .review-overview-group-toggle")
      || document.createElement("button");
    syncReviewOverviewGroupToggle(toggle, section, collapsed);

    const grid = group.querySelector(":scope > .review-overview-group-grid")
      || document.createElement("div");
    grid.className = "review-overview-group-grid";
    grid.hidden = collapsed;
    reconcileStableChildren(
      grid,
      section.overviews.map((overview) => cardsByTagID.get(overview.id)).filter(Boolean)
    );
    reconcileStableChildren(group, [toggle, grid]);
    const currentGroup = elements.reviewOverviewGrid.children[index] || null;
    if (currentGroup !== group) elements.reviewOverviewGrid.insertBefore(group, currentGroup);
  }
  for (const group of existingGroups.values()) group.remove();
}

function reviewOverviewOpenButtons({ includeDisabled = false } = {}) {
  return [...elements.reviewOverviewGrid.querySelectorAll(
    "[data-review-overview-tag-id]"
  )].filter((button) => (
    !button.closest("[hidden]") && (includeDisabled || !button.disabled)
  ));
}

function syncReviewOverviewCardTabStops(preferredTagID = null) {
  const enabledButtons = reviewOverviewOpenButtons();
  const preferred = enabledButtons.find((button) => (
    button.dataset.reviewOverviewTagId === preferredTagID
  ));
  const focused = enabledButtons.find((button) => button === document.activeElement);
  const remembered = enabledButtons.find((button) => (
    button.dataset.reviewOverviewTagId === state.review.overviewFocusTagID
  ));
  const existing = enabledButtons.find((button) => button.tabIndex === 0);
  const tabStop = preferred || focused || remembered || existing || enabledButtons[0] || null;
  for (const button of elements.reviewOverviewGrid.querySelectorAll(
    "[data-review-overview-tag-id]"
  )) {
    button.tabIndex = button === tabStop ? 0 : -1;
    button.removeAttribute("aria-posinset");
    button.removeAttribute("aria-setsize");
  }
  enabledButtons.forEach((button, index) => {
    button.setAttribute("aria-posinset", String(index + 1));
    button.setAttribute("aria-setsize", String(enabledButtons.length));
  });
  state.review.overviewFocusTagID = tabStop?.dataset.reviewOverviewTagId || null;
  return enabledButtons;
}

function moveReviewOverviewCardFocus(event) {
  const button = event.target.closest("[data-review-overview-tag-id]");
  if (!button || button.disabled || event.altKey || event.ctrlKey || event.metaKey) return false;
  const movementKeys = [
    "ArrowLeft", "ArrowRight", "ArrowUp", "ArrowDown",
    "PageUp", "PageDown", "Home", "End",
  ];
  if (!movementKeys.includes(event.key)) return false;
  const buttons = syncReviewOverviewCardTabStops(button.dataset.reviewOverviewTagId);
  const currentIndex = buttons.indexOf(button);
  if (currentIndex < 0) return false;

  const grid = button.closest(".review-overview-group-grid");
  const viewport = button.closest(".review-overview-content") || elements.reviewOverviewGrid;
  const columns = grid
    ? renderedGridColumnCount(grid, ":scope > .review-overview-card")
    : 1;
  const pageItems = grid
    ? renderedGridPageItemCount(
      viewport,
      grid,
      ":scope > .review-overview-card"
    )
    : columns;
  const delta = {
    ArrowLeft: -1,
    ArrowRight: 1,
    ArrowUp: -columns,
    ArrowDown: columns,
    PageUp: -pageItems,
    PageDown: pageItems,
  }[event.key];
  const nextIndex = event.key === "Home" ? 0
    : event.key === "End" ? buttons.length - 1
      : Math.max(0, Math.min(buttons.length - 1, currentIndex + delta));
  const target = buttons[nextIndex];
  if (!target) return false;

  event.preventDefault();
  event.stopPropagation();
  syncReviewOverviewCardTabStops(target.dataset.reviewOverviewTagId);
  target.closest(".review-overview-card")
    ?.scrollIntoView({ block: "nearest", inline: "nearest" });
  target.focus({ preventScroll: true });
  return true;
}

function reviewOverviewContentFingerprint() {
  return JSON.stringify({
    mediaKind: state.mediaKind,
    overview: state.review.overview,
    overviewTotal: state.review.overviewTotal,
    tags: activeTags().map((tag) => ({
      id: tag.id,
      displayName: tag.displayName,
      groupID: tag.groupID,
    })),
    groups: orderedTagGroups().map((group) => ({
      id: group.id,
      displayName: group.displayName,
    })),
    generalSettings: state.generalSettings.snapshot,
    tagLibrarySuggestions: state.tagLibrarySuggestions.snapshot,
    tagLibraryActivities: state.tagLibrarySuggestions.activities,
    cancellingSuggestionIDs: [...state.tagLibrarySuggestions.cancellingIDs].sort(),
    mutatingJobIDs: [...state.jobMutatingIDs].sort(),
    online: state.online,
  });
}

function reviewOverviewCanPreserveContent() {
  return state.review.overviewRenderedFingerprint !== null
    && state.review.overviewRenderedFingerprint === reviewOverviewContentFingerprint();
}

function renderReviewOverview({ preserveContent = false, reconcileContent = false } = {}) {
  const activeControl = elements.reviewOverviewGrid.contains(document.activeElement)
    ? document.activeElement
    : null;
  const overviewContent = elements.reviewOverviewGrid.closest(".review-overview-content");
  const overviewScrollTop = overviewContent?.scrollTop || 0;
  const focusedThreshold = thresholdFocusSelector(activeControl)
    || state.review.pendingThresholdFocus;
  const focusedTrainingJobID = !focusedThreshold && (state.review.pendingFocusTrainingJobID
    || activeControl?.dataset?.reviewTrainingJobId
    || null);
  const focusedTagID = !focusedThreshold && !focusedTrainingJobID
    ? (activeControl?.dataset?.reviewOverviewTagId || null)
    : null;
  const focusedGroupID = !focusedThreshold && !focusedTrainingJobID && !focusedTagID
    ? (activeControl?.dataset?.reviewOverviewGroupToggle || null)
    : null;
  const loading = state.review.overviewLoading;
  if (state.review.mode === "overview") {
    elements.reviewSummary.textContent = loading
      ? "正在载入审核总览…"
      : `${state.review.overviewTotal} 条待审 · ${currentMediaNoun()}`;
    elements.reviewNavigationCount.textContent = state.review.overviewTotal
      ? String(state.review.overviewTotal)
      : "";
  }
  elements.reviewOverviewEmpty.classList.toggle(
    "hidden",
    loading || state.review.overview.length > 0
  );
  if (preserveContent && reviewOverviewCanPreserveContent()) {
    syncReviewControls();
    return;
  }
  const existingCards = reconcileContent
    ? new Map(
      [...elements.reviewOverviewGrid.querySelectorAll("[data-review-overview-card-id]")]
        .map((card) => [card.dataset.reviewOverviewCardId, card])
    )
    : new Map();
  if (!reconcileContent) clearElement(elements.reviewOverviewGrid);
  for (const overview of state.review.overview) {
    const card = document.createElement("article");
    card.className = "review-overview-card";
    card.dataset.reviewOverviewCardId = overview.id;
    const openButton = document.createElement("button");
    openButton.type = "button";
    openButton.className = "review-overview-open";
    openButton.dataset.reviewOverviewTagId = overview.id;
    openButton.disabled = !overview.canReview || overview.pendingSuggestionCount === 0;
    openButton.setAttribute("aria-disabled", String(openButton.disabled));
    configurePersistentHelp(openButton, {
      title: `审核“${overview.displayName}”`,
      detail: overview.pendingSuggestionCount > 0
        ? `打开 ${overview.pendingSuggestionCount} 条待审核${currentMediaNoun()}，逐项或批量使用 P 属于、X 不属于、U 稍后。`
        : `“${overview.displayName}”当前没有待审核${currentMediaNoun()}；可展开门槛与生成来创建新建议。`,
      kind: "review",
      keyShortcuts: "ArrowLeft ArrowRight ArrowUp ArrowDown PageUp PageDown Home End Enter Space",
      owner: `review-overview:${overview.id}`,
    });

    const heading = document.createElement("div");
    heading.className = "review-overview-card-heading";
    heading.dataset.reviewOverviewPart = "card-heading";
    const name = document.createElement("strong");
    name.dataset.reviewOverviewPart = "card-name";
    name.textContent = overview.displayName;
    const pending = document.createElement("span");
    pending.className = "review-pending-count";
    pending.dataset.reviewOverviewPart = "card-pending";
    pending.textContent = String(overview.pendingSuggestionCount);
    heading.append(name, pending);

    const stats = document.createElement("div");
    stats.className = "review-overview-stats";
    stats.dataset.reviewOverviewPart = "card-stats";
    stats.textContent = `已确认 ${overview.acceptedSampleCount} · 已拒绝 ${overview.rejectedSampleCount}`;

    const origins = document.createElement("div");
    origins.className = "review-origin-counts";
    origins.dataset.reviewOverviewPart = "card-origins";
    const originLabels = [
      ["personalAdamW", "超级个人"],
      ["personalModel", "个人模型"],
      ["featurePrint", "特征向量"],
      ["standardModel", "标准模型"],
    ];
    for (const [key, label] of originLabels) {
      const count = overview.pendingSuggestionCounts?.[key] || 0;
      if (!count) continue;
      const badge = document.createElement("span");
      badge.dataset.reviewOverviewPart = `card-origin-${key}`;
      badge.textContent = `${label} ${count}`;
      origins.append(badge);
    }

    const status = document.createElement("div");
    status.className = "review-overview-status";
    status.dataset.reviewOverviewPart = "card-status";
    status.textContent = reviewTaskStatusText(overview.taskStatus, overview);
    openButton.append(heading, stats);
    if (origins.childElementCount) openButton.append(origins);
    openButton.append(status);
    card.append(openButton);

    const controlBody = document.createElement("div");
    controlBody.className = "review-card-control-body";
    controlBody.dataset.reviewOverviewPart = "control-body";
    const thresholdControls = renderReviewThresholdControls(overview);
    if (thresholdControls) controlBody.append(thresholdControls);

    const hasFeatureAction = Boolean(overview.canGenerate || overview.canUpdate);
    const hasFeatureJob = Boolean(overview.activeJobID);
    if (hasFeatureAction || hasFeatureJob) {
      const feature = document.createElement("div");
      feature.className = "review-overview-generate review-overview-feature";
      feature.dataset.reviewOverviewPart = "feature-section";
      const label = document.createElement("span");
      label.dataset.reviewOverviewPart = "feature-label";
      label.textContent = "FEATURE PRINT 建议";
      feature.append(label);

      if (hasFeatureAction) {
        const actions = document.createElement("div");
        actions.className = "review-overview-generate-actions";
        actions.dataset.reviewOverviewPart = "feature-actions";
        const generate = document.createElement("button");
        generate.type = "button";
        generate.className = "button button-plain";
        generate.dataset.reviewFeatureTagId = overview.id;
        generate.dataset.reviewFeatureMode = overview.canUpdate ? "update" : "generate";
        generate.disabled = !state.online || state.review.overviewLoading;
        generate.textContent = overview.canUpdate ? "更新特征向量" : "生成特征向量";
        configurePersistentHelp(generate, {
          title: generate.textContent,
          detail: `打开“${overview.displayName}”的相似${currentMediaNoun()}训练设置，确认来源后再创建任务；不会在点击时直接开始扫描。`,
          kind: "review",
        });
        actions.append(generate);
        feature.append(actions);
      }

      if (hasFeatureJob) {
        const jobRow = document.createElement("div");
        jobRow.className = "review-tag-activity review-feature-job";
        jobRow.dataset.reviewOverviewPart = "feature-job";
        const jobStatus = document.createElement("span");
        jobStatus.dataset.reviewOverviewPart = "feature-job-status";
        jobStatus.textContent = reviewTaskStatusText(overview.taskStatus, overview);
        jobRow.append(jobStatus);

        const viewRun = document.createElement("button");
        viewRun.type = "button";
        viewRun.className = "button button-plain";
        viewRun.dataset.reviewTrainingTagId = overview.id;
        viewRun.dataset.reviewTrainingJobId = overview.activeJobID;
        viewRun.textContent = "训练记录";
        configurePersistentHelp(viewRun, {
          title: `查看“${overview.displayName}”训练记录`,
          detail: "打开训练工程并定位到这个建议生成任务；返回后恢复当前审核总览位置和焦点。",
          kind: "review",
        });
        jobRow.append(viewRun);

        const jobActions = [
          ["pause", overview.canPause, "暂停"],
          ["resume", overview.canResume, "继续"],
          ["cancel", overview.canCancel, "取消"],
        ];
        for (const [action, available, title] of jobActions) {
          if (!available) continue;
          const button = document.createElement("button");
          button.type = "button";
          button.className = `button button-plain job-action write-action${action === "cancel" ? " button-danger" : ""}`;
          button.dataset.jobId = overview.activeJobID;
          button.dataset.action = action;
          button.disabled = !state.online || state.jobMutatingIDs.has(overview.activeJobID);
          button.textContent = state.jobMutatingIDs.has(overview.activeJobID)
            ? "处理中…"
            : title;
          configurePersistentHelp(button, {
            title: `${title}“${overview.displayName}”任务`,
            detail: {
              pause: "暂停建议生成并保存当前进度；已经写入的待审建议会保留。",
              resume: "从保存的进度继续建议生成；仍使用任务创建时冻结的范围。",
              cancel: "取消建议生成；已经写入的待审建议不会被删除。",
            }[action],
            kind: "review",
          });
          jobRow.append(button);
        }
        feature.append(jobRow);
      }
      controlBody.append(feature);
    }

    const option = tagLibrarySuggestionOption(overview.id);
    const suggestions = state.tagLibrarySuggestions;
    const activeActivity = activeTagLibrarySuggestion(overview.id);
    const canGeneratePersonal = Boolean(
      state.mediaKind === "image"
      && overview.canGeneratePersonalModel
      && option?.personalEligible
    );
    if (canGeneratePersonal || activeActivity) {
      const generation = document.createElement("div");
      generation.className = "review-overview-generate";
      generation.dataset.reviewOverviewPart = "personal-section";
      const label = document.createElement("span");
      label.dataset.reviewOverviewPart = "personal-label";
      label.textContent = "全库个人建议";
      generation.append(label);
      if (activeActivity) {
        const activityRow = document.createElement("div");
        activityRow.className = "review-tag-activity";
        activityRow.dataset.reviewOverviewPart = "personal-activity";
        const activityText = document.createElement("span");
        activityText.dataset.reviewOverviewPart = "personal-activity-status";
        activityText.textContent = `${tagLibrarySuggestionMethodText(activeActivity.method)} · ${tagLibrarySuggestionPhaseText(activeActivity)}`;
        activityRow.append(activityText);
        if (activeActivity.availableActions?.includes("cancel")) {
          const cancelButton = document.createElement("button");
          cancelButton.type = "button";
          cancelButton.className = "button button-plain";
          cancelButton.dataset.cancelTagSuggestionId = activeActivity.operationID;
          cancelButton.disabled = !state.online
            || suggestions.cancellingIDs.has(activeActivity.operationID);
          cancelButton.textContent = suggestions.cancellingIDs.has(activeActivity.operationID)
            ? "停止中…"
            : "停止";
          configurePersistentHelp(cancelButton, {
            title: `停止“${overview.displayName}”个人建议`,
            detail: "停止当前个人模型扫描；已经写入审核队列的建议会保留，原始媒体不会改变。",
            kind: "review",
          });
          activityRow.append(cancelButton);
        }
        generation.append(activityRow);
      } else {
        const actions = document.createElement("div");
        actions.className = "review-overview-generate-actions";
        actions.dataset.reviewOverviewPart = "personal-actions";
        const methods = [
          ["personalCentroid", "个人模型"],
          ["personalAdamW", "超级个人"],
        ];
        for (const [method, labelText] of methods) {
          const available = method === "personalAdamW"
            ? suggestions.snapshot?.personalAdamWAvailable
            : suggestions.snapshot?.personalCentroidAvailable;
          if (!available) continue;
          const button = document.createElement("button");
          button.type = "button";
          button.className = "button button-plain";
          button.dataset.tagSuggestionMethod = method;
          button.dataset.tagId = overview.id;
          button.disabled = !state.online
            || suggestions.loading
            || suggestions.submitting
            || Boolean(activeTagLibrarySuggestion());
          button.textContent = `${labelText} Top ${suggestions.snapshot?.maximumPendingCount || 500}`;
          configurePersistentHelp(button, {
            title: `使用${labelText}生成建议`,
            detail: `打开来源确认，为“${overview.displayName}”创建${labelText}全库建议任务；结果进入待审核队列。`,
            kind: "review",
          });
          actions.append(button);
        }
        if (actions.childElementCount) generation.append(actions);
      }
      if (generation.childElementCount > 1) controlBody.append(generation);
    }
    if (controlBody.childElementCount) {
      const details = document.createElement("details");
      details.className = "review-card-controls";
      details.dataset.reviewControlTagId = overview.id;
      details.open = state.review.expandedControlTagIDs.has(overview.id);
      const summary = document.createElement("summary");
      const disclosure = document.createElement("span");
      disclosure.className = "review-card-controls-chevron";
      disclosure.dataset.reviewOverviewPart = "summary-chevron";
      disclosure.setAttribute("aria-hidden", "true");
      disclosure.textContent = "›";
      const summaryLabel = document.createElement("span");
      summaryLabel.dataset.reviewOverviewPart = "summary-label";
      summaryLabel.textContent = "门槛与生成";
      const summaryHint = document.createElement("span");
      summaryHint.dataset.reviewOverviewPart = "summary-hint";
      summaryHint.textContent = thresholdControls ? "3 条建议轨道" : "生成选项";
      configurePersistentHelp(summary, {
        title: `${details.open ? "收起" : "展开"}“${overview.displayName}”门槛与生成`,
        detail: "查看或调整三条建议轨道门槛、创建建议任务及控制活动任务；展开本身不会开始任务。",
        kind: "review",
      });
      summary.append(disclosure, summaryLabel, summaryHint);
      details.append(summary, controlBody);
      card.append(details);
    }
    const existingCard = existingCards.get(overview.id);
    existingCards.delete(overview.id);
    if (existingCard) {
      reconcileReviewOverviewCard(existingCard, card);
    } else {
      elements.reviewOverviewGrid.append(card);
    }
  }
  for (const card of existingCards.values()) card.remove();
  organizeReviewOverviewGroups();
  syncReviewOverviewCardTabStops(focusedTagID);
  syncReviewControls();
  if (reconcileContent && overviewContent) overviewContent.scrollTop = overviewScrollTop;
  const focusAfterRender = () => {
    if (reconcileContent && activeControl?.isConnected) {
      if (!activeControl.disabled) {
        activeControl.focus({ preventScroll: true });
        return;
      }
      const sameCardFallback = activeControl.closest("[data-review-overview-card-id]")
        ?.querySelector("[data-review-control-tag-id] > summary");
      if (sameCardFallback instanceof HTMLElement) {
        sameCardFallback.focus({ preventScroll: true });
        return;
      }
    }
    const thresholdTarget = reviewThresholdFocusTarget(focusedThreshold);
    const target = thresholdTarget || (focusedTrainingJobID
      ? elements.reviewOverviewGrid.querySelector(
        `[data-review-training-job-id="${CSS.escape(focusedTrainingJobID)}"]`
      )
      : (focusedTagID
        ? elements.reviewOverviewGrid.querySelector(
          `[data-review-overview-tag-id="${CSS.escape(focusedTagID)}"]`
        )
        : (focusedGroupID
          ? elements.reviewOverviewGrid.querySelector(
            `[data-review-overview-group-toggle="${CSS.escape(focusedGroupID)}"]`
          )
          : null)));
    if (!(target instanceof HTMLElement) || target.disabled) return;
    target.focus({ preventScroll: true });
    if (thresholdTarget) state.review.pendingThresholdFocus = null;
    if (focusedTrainingJobID && !state.review.overviewLoading) {
      state.review.pendingFocusTrainingJobID = null;
    }
  };
  focusAfterRender();
  requestAnimationFrame(focusAfterRender);
  state.review.overviewRenderedFingerprint = reviewOverviewContentFingerprint();
}

function renderReviewMode() {
  renderReviewWorkspaceTitle();
  const overviewMode = state.review.mode === "overview";
  elements.reviewOverview.classList.toggle("hidden", !overviewMode);
  elements.reviewQueueLayout.classList.toggle("hidden", overviewMode);
  elements.reviewBackButton.classList.toggle("hidden", overviewMode);
  elements.reviewTagControl.classList.toggle("hidden", overviewMode);
  if (overviewMode) {
    renderReviewOverview();
  } else {
    renderReview();
  }
}

function reviewWorkspaceTitleText() {
  if (state.review.mode !== "queue") return "待审核建议";
  const tagID = elements.reviewTagSelect.value;
  const displayName = activeTags().find((tag) => tag.id === tagID)?.displayName?.trim();
  return displayName ? `审核“${displayName}”建议` : "审核建议";
}

function renderReviewWorkspaceTitle() {
  const title = reviewWorkspaceTitleText();
  if (elements.reviewWorkspaceTitle.textContent !== title) {
    elements.reviewWorkspaceTitle.textContent = title;
  }
  const accessibilityTitle = `${title}工作区`;
  if (elements.reviewWorkspace.getAttribute("aria-label") !== accessibilityTitle) {
    elements.reviewWorkspace.setAttribute("aria-label", accessibilityTitle);
  }
}

async function loadReviewOverview({ throwOnError = false } = {}) {
  const generation = ++state.review.overviewGeneration;
  const workspaceGeneration = state.workspaceGeneration;
  const scopeKey = currentReviewOverviewScopeKey();
  state.review.overviewLoading = true;
  renderReviewOverview({
    preserveContent: reviewOverviewCanPreserveContent(),
    reconcileContent: true,
  });
  const query = new URLSearchParams({ mediaKind: state.mediaKind });
  const sourceIDs = resolvedReviewSourceFilter();
  if (sourceIDs?.length === 0) {
    state.review.overview = [];
    state.review.overviewTotal = 0;
    state.review.overviewLoadedScopeKey = scopeKey;
    state.review.overviewLoading = false;
    renderReviewOverview({ reconcileContent: true });
    return true;
  }
  if (sourceIDs) query.set("sourceIDs", sourceIDs.join(","));
  try {
    const overview = await api(`/v1/review/overview?${query}`);
    if (generation !== state.review.overviewGeneration
      || workspaceGeneration !== state.workspaceGeneration) return false;
    state.review.overview = overview.tags || [];
    state.review.overviewTotal = overview.totalPendingSuggestionCount || 0;
    state.review.overviewLoadedScopeKey = scopeKey;
    return true;
  } catch (error) {
    if (generation === state.review.overviewGeneration && !throwOnError) {
      toast(error.message || "审核总览载入失败");
    }
    if (throwOnError) throw error;
    return false;
  } finally {
    if (generation === state.review.overviewGeneration) {
      state.review.overviewLoading = false;
      renderReviewOverview({
        preserveContent: reviewOverviewCanPreserveContent(),
        reconcileContent: true,
      });
      if (state.review.mode === "queue") renderReviewCollectionSummary();
    }
  }
}

async function enterReviewQueue(tagID) {
  const overview = state.review.overview.find((item) => item.id === tagID);
  if (!overview) return;
  state.review.mode = "queue";
  state.review.selectionMode = false;
  elements.reviewTagSelect.value = tagID;
  recordWorkspaceHistory("review", currentWorkspaceHistoryContext("review"), "replace");
  renderReviewMode();
  await loadReviewQueue({ preserveLoadedWindow: true });
}

async function openTrainingWorkspaceForReviewTag(tagID, jobID = null) {
  state.training.mediaKind = state.mediaKind;
  state.training.method = "featureKnn";
  state.training.focusedJobID = jobID;
  state.training.focusedTagID = tagID;
  await openTrainingWorkspace({
    returnToReview: {
      mode: state.review.mode,
      tagID,
      jobID,
    },
  });
  const selected = state.training.runs.find(
    (run) => run.id === state.training.selectedRunID
      && (run.jobID === jobID || run.tagID === tagID)
  );
  if (!selected) toast("对应训练记录尚未写入，任务进度仍可在审核卡片和任务面板查看");
}

async function returnToReviewOverview() {
  finishReviewMarqueeSelection();
  state.review.selectionMode = false;
  state.review.mode = "overview";
  recordWorkspaceHistory("review", currentWorkspaceHistoryContext("review"), "replace");
  renderReviewMode();
  await loadReviewOverview();
}

function selectedReviewItems() {
  const primary = state.review.items[state.review.selectedIndex];
  if (state.review.selectedAssetIDs.size === 1
    && primary
    && state.review.selectedAssetIDs.has(primary.assetID)) return [primary];
  const seenAssetIDs = new Set();
  return state.review.items.filter((item) => {
    if (!state.review.selectedAssetIDs.has(item.assetID)
      || seenAssetIDs.has(item.assetID)) return false;
    seenAssetIDs.add(item.assetID);
    return true;
  });
}

function reviewCardMainButton(card, { create = false } = {}) {
  let button = card?.querySelector(":scope > .review-card-main") || null;
  if (!button && create && card) {
    button = document.createElement("button");
    button.type = "button";
    button.className = "review-card-main";
    card.append(button);
  }
  return button;
}

function reviewGridRovingKey() {
  const visibleKeys = new Set(state.review.items.map(reviewItemKey));
  const focusedCard = document.activeElement?.closest?.("#reviewGrid > .review-card");
  if (visibleKeys.has(focusedCard?.dataset.reviewKey)) {
    return focusedCard.dataset.reviewKey;
  }
  const selectedKey = reviewItemKey(state.review.items[state.review.selectedIndex]);
  if (visibleKeys.has(selectedKey)) return selectedKey;
  if (visibleKeys.has(state.review.gridFocusReviewKey)) return state.review.gridFocusReviewKey;
  return reviewItemKey(state.review.items[0]);
}

function syncReviewCardKeyboardAccess(card, rovingKey = reviewGridRovingKey()) {
  const isTabStop = card?.dataset.reviewKey === rovingKey;
  const mainButton = reviewCardMainButton(card);
  if (mainButton) mainButton.tabIndex = isTabStop ? 0 : -1;
  const favoriteButton = card?.querySelector(":scope > .review-card-favorite");
  if (favoriteButton) favoriteButton.tabIndex = isTabStop ? 0 : -1;
}

function syncReviewGridTabStops(reviewKey = null) {
  const visibleKeys = new Set(state.review.items.map(reviewItemKey));
  if (reviewKey && visibleKeys.has(reviewKey)) state.review.gridFocusReviewKey = reviewKey;
  const rovingKey = reviewGridRovingKey();
  state.review.gridFocusReviewKey = rovingKey;
  for (const card of elements.reviewGrid.querySelectorAll(":scope > .review-card")) {
    syncReviewCardKeyboardAccess(card, rovingKey);
  }
}

function syncReviewCardFavoriteButton(card, item) {
  let button = card.querySelector(":scope > .review-card-favorite");
  if (!supportsFavorites() || !item.favorite) {
    button?.remove();
    return;
  }
  if (!button) {
    button = document.createElement("button");
    button.type = "button";
    button.className = "review-card-favorite write-action";
    button.dataset.reviewCardFavorite = "true";
    const icon = document.createElement("span");
    icon.className = "review-card-favorite-icon media-favorite-icon";
    icon.setAttribute("aria-hidden", "true");
    const badge = document.createElement("span");
    badge.className = "review-card-favorite-sync media-favorite-sync hidden";
    badge.setAttribute("aria-hidden", "true");
    button.append(icon, badge);
    card.append(button);
  }
  syncMediaFavoriteButton(button, {
    assetID: item.assetID,
    fileName: item.fileName,
    favorite: item.favorite,
  });
}

async function toggleReviewItemFavorite(assetID, { returnFocus = null } = {}) {
  const itemIndex = state.review.items.findIndex((item) => item.assetID === assetID);
  const favorite = favoriteStateForAssetID(assetID);
  if (!assetID || itemIndex < 0 || !favorite || state.favoriteMutating) return;

  const scrollTop = elements.reviewQueuePane.scrollTop;
  const selectedAssetIDs = new Set(state.review.selectedAssetIDs);
  const selectedIndex = state.review.selectedIndex;
  const anchorIndex = state.review.selectionAnchorIndex;
  await applyFavoriteMutation([assetID], favorite.isFavorite !== true);
  elements.reviewQueuePane.scrollTop = scrollTop;

  // Favorite is orthogonal to review selection. Keep the frozen P/X/U target,
  // primary detail, range anchor and viewport exactly where the user left them.
  state.review.selectedAssetIDs = selectedAssetIDs;
  state.review.selectedIndex = selectedIndex;
  state.review.selectionAnchorIndex = anchorIndex;
  renderReviewSelectionState({ renderDetail: false });
  elements.reviewQueuePane.scrollTop = scrollTop;

  if (returnFocus?.isConnected) {
    returnFocus.focus({ preventScroll: true });
    return;
  }
  reviewCardFocusTarget(assetID)?.focus({ preventScroll: true });
}

async function toggleReviewCardFavorite(button) {
  const assetID = button?.dataset.mediaFavoriteAssetId
    || button?.closest(".review-card")?.dataset.reviewAssetId;
  await toggleReviewItemFavorite(assetID, { returnFocus: button });
}

async function applyReviewInspectorFavorite(button, isFavorite) {
  const assetIDs = selectedReviewItems().map((item) => item.assetID);
  if (!assetIDs.length) return;
  const scrollTop = elements.reviewQueuePane.scrollTop;
  await applyFavoriteMutation(assetIDs, isFavorite);
  if (state.review.mode !== "queue") return;
  elements.reviewQueuePane.scrollTop = scrollTop;
  renderReviewDetail();
  if (button.isConnected && !button.disabled) button.focus({ preventScroll: true });
}

function syncReviewCardSelection(card, item, index) {
  const selected = state.review.selectedAssetIDs.size === 1
    ? index === state.review.selectedIndex
    : state.review.selectedAssetIDs.has(item.assetID);
  const primary = selected && index === state.review.selectedIndex;
  card.classList.toggle("selected", selected);
  card.classList.toggle("primary", primary);
  const mainButton = reviewCardMainButton(card, { create: true });
  mainButton.setAttribute("aria-pressed", String(selected));
  mainButton.title = item.fileName || "未命名媒体";
  configurePersistentHelp(mainButton, {
    title: item.fileName || "未命名媒体",
    detail: `${selected ? (primary ? "当前主项目并已选择" : "已选择") : "未选择"} · ${reviewOriginText(item.suggestionOrigin)}`
      + `${item.score == null ? "" : ` · 可信度 ${Math.round(item.score * 100)}%`}。`
      + "方向键移动，Shift 扩展选择，Space 打开单图；P 属于、X 不属于、U 稍后，Delete 安全删除，Command/Ctrl-A 全选已载入项目；右键、触控长按或 Shift-F10 可加入或取消红心。",
    kind: "review",
    keyShortcuts: "ArrowLeft ArrowRight ArrowUp ArrowDown Home End PageUp PageDown Space P X U Delete Meta+A Control+A Shift+F10 ContextMenu",
  });
  if (primary) {
    mainButton.setAttribute("aria-current", "true");
  } else {
    mainButton.removeAttribute("aria-current");
  }
  let mark = card.querySelector(":scope > .review-selection-mark");
  if (!mark) {
    mark = document.createElement("span");
    mark.className = "review-selection-mark";
    mark.setAttribute("aria-hidden", "true");
    card.append(mark);
  }
  syncAssetCardOverlayText(mark, "✓");
}

function syncReviewSelectionModeControls({ controlsLocked = false } = {}) {
  const available = state.review.mode === "queue"
    && (state.review.items.length > 0 || (state.review.selectionMode && state.review.loading));
  if (!available) state.review.selectionMode = false;
  const active = available && state.review.selectionMode;
  const selectedCount = state.review.selectedAssetIDs.size;
  elements.reviewWorkspace.classList.toggle("touch-selection-mode", active);
  elements.reviewSelectionModeButton.classList.toggle("hidden", !available);
  elements.reviewSelectionModeButton.disabled = controlsLocked;
  elements.reviewSelectionModeButton.setAttribute("aria-pressed", String(active));
  elements.reviewSelectionModeButton.textContent = active ? "完成" : "选择";
  elements.reviewSelectionModeButton.title = active
    ? `结束触控多选${selectedCount ? `，当前已选择 ${selectedCount} 项` : ""}`
    : "进入触控多选模式";
  elements.reviewSelectionModeButton.setAttribute(
    "aria-label",
    active
      ? `完成多选${selectedCount ? `，当前已选择 ${selectedCount} 项` : ""}`
      : "选择多项待审核建议"
  );
  elements.reviewSelectAllButton.classList.toggle("hidden", !active);
  elements.reviewSelectAllButton.disabled = controlsLocked
    || selectedCount === new Set(state.review.items.map((item) => item.assetID)).size;
}

function setReviewSelectionMode(enabled, { restoreFocus = true } = {}) {
  state.gridDoubleClickSelectionSnapshot = null;
  const available = state.review.mode === "queue" && state.review.items.length > 0;
  const next = Boolean(enabled) && available;
  if (next === state.review.selectionMode) {
    syncReviewSelectionModeControls();
    return;
  }
  state.review.selectionMode = next;
  if (next && state.review.selectedAssetIDs.size === 0) {
    const index = state.review.selectedIndex >= 0 ? state.review.selectedIndex : 0;
    const item = state.review.items[index];
    if (item) {
      state.review.selectedIndex = index;
      state.review.selectedAssetIDs = new Set([item.assetID]);
      state.review.selectionAnchorIndex = index;
    }
  } else if (!next && state.review.items.length > 0) {
    let index = state.review.selectedIndex;
    if (!state.review.selectedAssetIDs.has(state.review.items[index]?.assetID)) {
      index = state.review.items.findIndex((item) => (
        state.review.selectedAssetIDs.has(item.assetID)
      ));
    }
    if (index < 0 && state.review.selectionAnchorIndex >= 0) {
      index = Math.min(state.review.selectionAnchorIndex, state.review.items.length - 1);
    }
    if (index < 0) index = 0;
    state.review.selectedIndex = index;
    state.review.selectedAssetIDs = new Set([state.review.items[index].assetID]);
    state.review.selectionAnchorIndex = index;
  }
  renderReviewSelectionState();
  checkpointActiveWorkspaceHistory();
  if (restoreFocus) {
    elements.reviewSelectionModeButton.focus({ preventScroll: true });
  }
}

function renderReviewSelectionState({ renderDetail = true } = {}) {
  state.review.items.forEach((item, index) => {
    const button = elements.reviewGrid.querySelector(`[data-review-index="${index}"]`);
    if (button) syncReviewCardSelection(button, item, index);
  });
  syncReviewGridTabStops();
  const count = state.review.selectedAssetIDs.size;
  elements.reviewSummary.textContent = reviewQueueSummaryText({ selectedCount: count });
  syncReviewSelectionModeControls({
    controlsLocked: state.review.overviewLoading || state.review.mutating,
  });
  if (renderDetail) renderReviewDetail();
}

function currentReviewQueueOverview() {
  if (state.review.overviewLoadedScopeKey !== currentReviewOverviewScopeKey()) return null;
  const tagID = elements.reviewTagSelect.value;
  return state.review.overview.find((overview) => String(overview.id) === tagID) || null;
}

function normalizedReviewCount(value) {
  if (value == null) return null;
  const count = Number(value);
  return Number.isInteger(count) && count >= 0 ? count : null;
}

function reviewQueueRunningProgress(overview) {
  const checked = normalizedReviewCount(overview?.checkedCount) ?? 0;
  const total = normalizedReviewCount(overview?.totalCount);
  const skipped = normalizedReviewCount(overview?.skippedCount) ?? 0;
  const checkedText = total != null && total > 0 && checked <= total
    ? `${checked}/${total}`
    : String(checked);
  return `正在分析 · 已检查 ${checkedText} · 跳过 ${skipped}`;
}

function reviewQueueSummaryText({ selectedCount = 0 } = {}) {
  if (state.review.loading && !state.review.appending) return "正在载入…";
  const overview = currentReviewQueueOverview();
  const loadedCount = state.review.loadedScopeKey === currentReviewScopeKey()
    ? state.review.items.length
    : 0;
  const pendingCount = normalizedReviewCount(overview?.pendingSuggestionCount);
  const hasMore = Boolean(state.review.nextCursor);
  const hasConsistentPendingCount = pendingCount != null
    && loadedCount <= pendingCount
    && (!hasMore || loadedCount < pendingCount);
  const parts = [];

  if (overview?.taskStatus === "running") {
    parts.push(reviewQueueRunningProgress(overview));
  } else if (overview?.taskStatus === "paused") {
    parts.push("已暂停");
  } else if (overview?.taskStatus === "waiting") {
    parts.push("等待运行");
  }
  if (hasConsistentPendingCount) parts.push(`待审核 ${pendingCount} 条`);

  const shouldShowLoadedWindow = !hasConsistentPendingCount
    || loadedCount < pendingCount
    || hasMore
    || state.review.appending;
  if (shouldShowLoadedWindow) {
    parts.push(loadedCount > 0 ? `已载入 ${loadedCount} 条` : "当前未载入");
  }
  if (hasMore) parts.push("还有更多");
  if (selectedCount > 1) parts.push(`已选择 ${selectedCount} 项`);
  if (state.review.appending) parts.push("正在载入更多…");
  return parts.join(" · ") || "审核队列尚未载入";
}

function reviewQueueMissingSamplesDescription(overview) {
  const missingPositive = normalizedReviewCount(overview?.missingPositiveCount);
  const missingNegative = normalizedReviewCount(overview?.missingNegativeCount);
  const missing = [];
  if (missingPositive > 0) missing.push(`${missingPositive} 个“属于”样本`);
  if (missingNegative > 0) missing.push(`${missingNegative} 个“不属于”样本`);
  if (!missing.length) {
    return "当前标签还缺少可用的确认或拒绝样本；补充样本后即可生成建议。";
  }
  return `还需确认 ${missing.join("、")}；样本就绪后即可生成建议。`;
}

function reviewQueueEmptyState() {
  const overview = currentReviewQueueOverview();
  const states = {
    notReady: {
      state: "warning",
      icon: "◌",
      title: "样本不足",
      description: reviewQueueMissingSamplesDescription(overview),
    },
    ready: {
      state: "ready",
      icon: "✦",
      title: "可以生成建议",
      description: "返回审核总览，为当前标签开始生成建议。",
    },
    waiting: {
      state: "progress",
      icon: "◷",
      title: "正在等待生成",
      description: "Mac 已接收任务；开始处理后，进度会显示在上方。",
    },
    running: {
      state: "progress",
      icon: "↻",
      title: "正在生成建议",
      description: "新建议生成后会进入当前队列；也可返回总览查看或控制任务。",
    },
    paused: {
      state: "warning",
      icon: "Ⅱ",
      title: "建议生成已暂停",
      description: "返回审核总览继续或取消当前生成任务。",
    },
    retryableFailure: {
      state: "failure",
      icon: "!",
      title: "生成遇到问题",
      description: "返回审核总览查看任务状态；必要时在 Mac 端重试。",
    },
    completed: {
      state: "complete",
      icon: "✓",
      title: "已全部审核",
      description: "当前标签没有剩余建议；可返回总览生成新一轮。",
    },
    terminalFailure: {
      state: "failure",
      icon: "!",
      title: "任务失败",
      description: "请在 Mac 端检查任务后，再返回总览重新生成建议。",
    },
    cancelled: {
      state: "neutral",
      icon: "×",
      title: "生成已取消",
      description: "返回审核总览可重新生成当前标签的建议。",
    },
  };
  return states[overview?.taskStatus] || {
    state: overview ? "neutral" : "unavailable",
    icon: overview ? "✦" : "▧",
    title: overview ? "暂无建议" : "队列状态尚未载入",
    description: overview
      ? "选择其他标签，或返回总览生成新建议。"
      : "刷新审核队列，或返回总览选择其他标签。",
  };
}

function renderReviewEmptyState() {
  const empty = reviewQueueEmptyState();
  elements.reviewEmpty.dataset.state = empty.state;
  elements.reviewEmptyIcon.textContent = empty.icon;
  elements.reviewEmptyTitle.textContent = empty.title;
  elements.reviewEmptyDescription.textContent = empty.description;
}

function selectAllReviewItems() {
  if (!state.review.items.length) return;
  state.review.selectedAssetIDs = new Set(state.review.items.map((item) => item.assetID));
  if (state.review.selectedIndex < 0) state.review.selectedIndex = 0;
  state.review.selectionAnchorIndex = state.review.selectedIndex;
  renderReviewSelectionState();
  checkpointActiveWorkspaceHistory();
  reviewCardMainButton(
    elements.reviewGrid.querySelector(`[data-review-index="${state.review.selectedIndex}"]`)
  )?.focus({ preventScroll: true });
}

function selectAllSlimmingMembers() {
  if (state.slimming.view !== "analysis" || !state.slimming.members.length) return;
  state.slimming.selectedMemberIDs = new Set(
    state.slimming.members.map((member) => member.id)
  );
  state.slimming.selectionAnchorID = state.slimming.members[0]?.id || null;
  renderSlimmingMemberSelection();
  const primaryID = state.slimming.selectionAnchorID;
  restoreOverlayFocus(primaryID
    ? slimmingMemberMainButton(elements.slimmingMemberGrid.querySelector(
      `[data-slimming-member-id="${CSS.escape(primaryID)}"]`
    ))
    : elements.closeSlimmingButton);
}

function slimmingSelectionPrimaryID() {
  const selectedIDs = state.slimming.selectedMemberIDs;
  const anchorID = state.slimming.selectionAnchorID;
  if (anchorID && selectedIDs.has(anchorID)
    && state.slimming.members.some((member) => member.id === anchorID)) {
    return anchorID;
  }
  return state.slimming.members.find((member) => selectedIDs.has(member.id))?.id || null;
}

function renderReviewCollectionSummary() {
  renderReviewEmptyState();
  elements.reviewEmpty.classList.toggle(
    "hidden",
    (state.review.loading && !state.review.appending) || state.review.items.length > 0
  );
  elements.loadMoreReviewButton.classList.toggle("hidden", !state.review.nextCursor);
  elements.reviewSummary.textContent = reviewQueueSummaryText();
  elements.reviewNavigationCount.textContent = state.review.overviewTotal
    ? String(state.review.overviewTotal)
    : "";
  syncReviewControls();
}

function syncReviewCard(card, item, index, rovingKey) {
  card.className = "review-card";
  card.dataset.reviewKey = reviewItemKey(item);
  card.dataset.reviewIndex = String(index);
  card.dataset.reviewAssetId = item.assetID;
  if (Number(item.width) > 0 && Number(item.height) > 0) {
    card.style.setProperty(
      "--review-card-aspect",
      `${Number(item.width)} / ${Number(item.height)}`
    );
  } else {
    card.style.removeProperty("--review-card-aspect");
  }
  const mainButton = reviewCardMainButton(card, { create: true });
  mainButton.setAttribute("aria-label", `${item.fileName || "未命名照片"}，${reviewOriginText(item.suggestionOrigin)}`);
  syncAssetCardImage(card, item);
  syncReviewCardSelection(card, item, index);
  syncReviewCardFavoriteButton(card, item);
  syncReviewCardKeyboardAccess(card, rovingKey);
  let origin = card.querySelector(".review-origin-badge");
  if (!origin) {
    origin = document.createElement("span");
    origin.className = "review-origin-badge";
    card.append(origin);
  }
  origin.textContent = reviewOriginText(item.suggestionOrigin).replace("建议", "");
  let score = card.querySelector(".review-score");
  if (item.score != null) {
    if (!score) {
      score = document.createElement("span");
      score.className = "review-score";
      card.append(score);
    }
    score.textContent = `${Math.round(item.score * 100)}%`;
  } else {
    score?.remove();
  }
}

function renderReview() {
  renderReviewCollectionSummary();
  state.review.gridFocusReviewKey = reviewGridRovingKey();
  const rovingKey = state.review.gridFocusReviewKey;
  const existing = new Map(
    [...elements.reviewGrid.querySelectorAll(":scope > .review-card")]
      .map((button) => [button.dataset.reviewKey, button])
  );
  state.review.items.forEach((item, index) => {
    const key = reviewItemKey(item);
    const card = existing.get(key) || document.createElement("div");
    existing.delete(key);
    syncReviewCard(card, item, index, rovingKey);
    elements.reviewGrid.append(card);
  });
  for (const card of existing.values()) {
    card.querySelectorAll("img[data-protected-path]").forEach(clearProtectedImageSource);
    card.remove();
  }
  renderReviewDetail();
}

function appendReviewCards(items, startIndex) {
  const fragment = document.createDocumentFragment();
  const rovingKey = reviewGridRovingKey();
  items.forEach((item, offset) => {
    const card = document.createElement("div");
    syncReviewCard(card, item, startIndex + offset, rovingKey);
    fragment.append(card);
  });
  elements.reviewGrid.append(fragment);
  renderReviewDetail();
}

function renderReviewCardsForKeys(reviewKeys) {
  const requestedKeys = new Set(reviewKeys);
  if (!requestedKeys.size) return;
  const itemsByKey = new Map(
    state.review.items
      .map((item, index) => [reviewItemKey(item), { item, index }])
      .filter(([key]) => requestedKeys.has(key))
  );
  const rovingKey = reviewGridRovingKey();
  for (const card of elements.reviewGrid.querySelectorAll(":scope > .review-card")) {
    const entry = itemsByKey.get(card.dataset.reviewKey);
    if (entry) syncReviewCard(card, entry.item, entry.index, rovingKey);
  }
}

function reviewInspectorSelectionKey() {
  return [...state.review.selectedAssetIDs].sort().join("|");
}

function reviewInspectorDetailMatches(item) {
  return Boolean(item)
    && state.review.detail?.assetID === item.assetID
    && state.review.detailSelectionKey === reviewInspectorSelectionKey();
}

function syncReviewViewOriginalControl(detail, item) {
  const isVideo = state.mediaKind === "video";
  elements.reviewViewOriginalButton.dataset.assetId = item?.assetID || detail?.assetID || "";
  elements.reviewViewOriginalButtonLabel.textContent = isVideo
    ? "在网页播放原视频"
    : "在网页查看原图";
  elements.reviewViewOriginalButtonIcon.textContent = isVideo ? "▶" : "⌕";
  elements.reviewViewOriginalButton.disabled = !state.online
    || !detail
    || detail.availability !== "available"
    || state.review.selectedAssetIDs.size !== 1;
}

function syncReviewOpenOriginalControl(detail, item) {
  const isVideo = state.mediaKind === "video";
  const assetID = item?.assetID || detail?.assetID || "";
  elements.reviewOpenOriginalButton.dataset.assetId = assetID;
  elements.reviewOpenOriginalButtonLabel.textContent = state.openingOriginal
    ? "正在 Mac 上打开…"
    : (isVideo ? "在 Mac 上用系统播放器打开" : "在 Mac 上用“预览”打开原图");
  elements.reviewOpenOriginalButtonIcon.textContent = isVideo ? "▶" : "↗";
  elements.reviewOpenOriginalHint.textContent = isVideo
    ? "网页直接播放原始视频；也可交给运行 ImageAll 的 Mac 系统播放器"
    : "网页只在明确点击后读取本地原图；iCloud 原图不会静默下载，也可在 Mac 打开";
  elements.reviewOpenOriginalButton.classList.toggle("busy", state.openingOriginal);
  elements.reviewOpenOriginalButton.disabled = !state.online
    || !detail
    || detail.availability !== "available"
    || state.review.selectedAssetIDs.size !== 1
    || state.openingOriginal;
}

function renderReviewInspectorMetadata(item, detail) {
  const loading = state.review.detailLoadingAssetID === item?.assetID
    && state.review.detailLoadingSelectionKey === reviewInspectorSelectionKey();
  const preservesExisting = elements.reviewAssetMetadata.dataset.assetId === item?.assetID
    && elements.reviewAssetMetadata.childElementCount > 0;
  elements.reviewMetadataState.textContent = loading
    ? "正在读取…"
    : (detail
      ? "Mac 资产详情"
      : (preservesExisting ? "详情暂不可用 · 显示上次成功读取" : "详情暂不可用"));
  if (detail) {
    const isVideo = state.mediaKind === "video";
    const rows = [
      metadataRow("文件名", detail.fileName || item?.fileName || "—"),
      metadataRow("来源", detail.sourceName),
      metadataRow("相对位置", detail.relativePath),
      metadataRow("媒体", isVideo ? "视频" : "照片"),
      metadataRow(
        "尺寸",
        detail.width && detail.height ? `${detail.width} × ${detail.height}` : "—"
      ),
      ...(isVideo ? [metadataRow("时长", formatDuration(detail.durationMs))] : []),
      metadataRow("文件大小", formatFileSize(detail.fingerprintSizeBytes)),
      metadataRow("拍摄时间", formatDate(detail.mediaCreatedAtMs)),
      metadataRow("修改时间", formatDate(detail.mediaModifiedAtMs)),
      metadataRow("格式", detail.mediaType),
      metadataRow("状态", availabilityText(detail.availability)),
    ];
    reconcileMetadataRows(elements.reviewAssetMetadata, rows);
    elements.reviewAssetMetadata.dataset.assetId = detail.assetID;
  } else if (!preservesExisting) {
    reconcileMetadataRows(elements.reviewAssetMetadata, []);
    delete elements.reviewAssetMetadata.dataset.assetId;
  }
  syncReviewViewOriginalControl(detail, item);
  syncReviewOpenOriginalControl(detail, item);
}

function reviewTagDecisionProjection(tagID, detail, selectedCount) {
  if (selectedCount > 1) {
    const aggregate = state.review.tagAggregates.find((item) => item.tagID === tagID);
    if (!aggregate) {
      return {
        decision: "unknown",
        summary: "正在统计…",
        states: { accepted: false, rejected: false, unknown: false, disabled: true },
      };
    }
    const decision = aggregate.acceptedCount === selectedCount
      ? "accepted"
      : aggregate.rejectedCount === selectedCount
        ? "rejected"
        : aggregate.unknownCount === selectedCount
          ? "unknown"
          : "mixed";
    return {
      decision,
      summary: selectionAggregateText(aggregate, selectedCount),
      states: {
        accepted: decision === "accepted",
        rejected: decision === "rejected",
        unknown: decision === "unknown",
      },
    };
  }
  const tag = detail?.tags?.find((candidate) => candidate.tagID === tagID);
  const decision = tag?.decision || "unknown";
  return {
    decision,
    summary: null,
    states: {
      accepted: decision === "accepted",
      rejected: decision === "rejected",
      unknown: decision === "unknown",
      disabled: !detail,
    },
  };
}

function renderReviewInspectorTags(item, detail, selectedItems) {
  const selectedCount = selectedItems.length;
  elements.reviewTagSummary.textContent = selectedCount > 1
    ? `已选择 ${mediaItemCountText(selectedCount)}`
    : (detail
      ? `已确认 ${detail.acceptedTagCount} · 已拒绝 ${detail.rejectedTagCount}`
      : "正在读取…");
  if (elements.reviewTags.dataset.activeTagDrag) return;
  const query = state.review.tagSearchText.toLocaleLowerCase("zh-CN");
  const tags = orderedActiveTags().filter((tag) => (
    !query || tag.displayName.toLocaleLowerCase("zh-CN").includes(query)
  ));
  elements.reviewTagEmpty.classList.toggle("hidden", tags.length > 0);
  reconcileInspectorTagGroups(elements.reviewTags, tags, (row, tag) => {
    const projection = reviewTagDecisionProjection(tag.id, detail, selectedCount);
    return syncReviewInspectorTagRow(
      row,
      tag,
      projection,
      selectedCount,
      Boolean(query)
    );
  });
  restoreInspectorTagFocus("review");
}

function renderReviewInspectorActions(selectedItems = selectedReviewItems()) {
  const selectedCount = selectedItems.length;
  const assetIDs = selectedItems.map((item) => item.assetID);
  const favoriteUnavailable = !supportsFavorites()
    || !state.online
    || state.favoriteMutating
    || state.favoriteRetrying
    || state.review.loading
    || state.review.mutating
    || selectedCount === 0;
  const activeRemoval = activeGalleryRemovalRequest();
  const deletionIDs = galleryRemovalTargetAssetIDs(assetIDs, { surface: "review" });
  const deletionProtection = removalFavoriteProtectionPlan(deletionIDs);
  const deletionUnavailable = !supportsLibrarySlimming()
    || !state.online
    || state.review.loading
    || state.review.mutating
    || state.galleryRemoval.submitting
    || Boolean(activeRemoval)
    || deletionIDs.length !== selectedCount
    || deletionProtection.removalAssetIDs.length === 0
    || deletionProtection.unverifiableAssetIDs.length > 0
    || selectedCount === 0;

  elements.reviewInspectorSelectionTitle.textContent = selectedCount
    ? `已选择 ${mediaItemCountText(selectedCount)}`
    : "未选择照片";
  for (const button of [
    elements.reviewInspectorFavoriteButton,
    elements.reviewInspectorUnfavoriteButton,
  ]) {
    button.classList.toggle("hidden", !supportsFavorites());
    button.disabled = favoriteUnavailable;
  }
  elements.reviewInspectorDeleteButton.classList.toggle(
    "hidden",
    !supportsLibrarySlimming()
  );
  elements.reviewInspectorDeleteButton.disabled = deletionUnavailable;

  const activeText = galleryRemovalStatusText(activeRemoval);
  elements.reviewInspectorDeleteButtonLabel.textContent = state.galleryRemoval.submitting
    ? "正在交给 Mac…"
    : (activeText || "删除");
  elements.reviewInspectorActionStatus.dataset.active = String(Boolean(activeText));
  if (activeText) {
    elements.reviewInspectorActionStatus.textContent = activeText;
  } else if (selectedCount && deletionIDs.length !== selectedCount) {
    elements.reviewInspectorActionStatus.textContent =
      "所选项目包含当前不可用的媒体，暂不能安全删除。";
  } else if (deletionProtection.unverifiableAssetIDs.length) {
    elements.reviewInspectorActionStatus.textContent =
      "无法核验红心保护，未删除任何项目。";
  } else if (deletionProtection.favoriteProtectedAssetIDs.length) {
    elements.reviewInspectorActionStatus.textContent = deletionProtection.removalAssetIDs.length
      ? `将保留 ${deletionProtection.favoriteProtectedAssetIDs.length} 项红心，只删除其余 ${deletionProtection.removalAssetIDs.length} 项。`
      : "所选项目均有红心保护；请先取消红心再删除。";
  } else {
    elements.reviewInspectorActionStatus.textContent =
      "文件夹原始媒体将永久删除；Apple Photos 项进入系统“最近删除”。";
  }
  elements.reviewInspectorDeleteButton.title = !supportsLibrarySlimming()
    ? "当前 Mac Host 不支持图库快速删除"
    : (activeText || (deletionProtection.unverifiableAssetIDs.length
      ? "无法核验红心保护，暂不能删除"
      : deletionProtection.removalAssetIDs.length === 0 && selectedCount
        ? "所选项目均有红心保护；请先取消红心再删除"
        : deletionUnavailable
          ? "当前审核选区暂不能删除"
          : `删除 ${mediaItemCountText(deletionProtection.removalAssetIDs.length)}`
            + `${deletionProtection.favoriteProtectedAssetIDs.length ? `，保留 ${deletionProtection.favoriteProtectedAssetIDs.length} 项红心` : ""}；仍需在 Mac 原生窗口确认`));
  elements.reviewInspectorDeleteButton.setAttribute(
    "aria-label",
    elements.reviewInspectorDeleteButton.title
  );
}

async function loadReviewInspectorDetail({ force = false, quiet = false } = {}) {
  const item = state.review.items[state.review.selectedIndex];
  const selectedItems = selectedReviewItems();
  const selectionKey = reviewInspectorSelectionKey();
  if (state.review.mode !== "queue" || !item || !selectedItems.length) return false;
  if (!force && reviewInspectorDetailMatches(item)) {
    renderReviewDetail();
    return true;
  }
  if (!force
    && state.review.detailLoadingAssetID === item.assetID
    && state.review.detailLoadingSelectionKey === selectionKey) return false;

  const generation = ++state.review.detailRequestGeneration;
  const workspaceGeneration = state.workspaceGeneration;
  const tagIDs = activeTags().map((tag) => tag.id);
  state.review.detail = null;
  state.review.tagAggregates = [];
  state.review.detailSelectionKey = null;
  state.review.detailLoadingAssetID = item.assetID;
  state.review.detailLoadingSelectionKey = selectionKey;
  renderReviewDetail();
  try {
    const [detail, aggregates] = await Promise.all([
      api(`/v1/assets/${item.assetID}`),
      selectedItems.length > 1 && tagIDs.length
        ? api("/v1/tags/selection", {
          method: "POST",
          body: JSON.stringify({
            tagIDs,
            assetIDs: selectedItems.map((candidate) => candidate.assetID),
          }),
        })
        : Promise.resolve([]),
    ]);
    if (generation !== state.review.detailRequestGeneration
      || workspaceGeneration !== state.workspaceGeneration
      || state.review.mode !== "queue"
      || state.review.items[state.review.selectedIndex]?.assetID !== item.assetID
      || reviewInspectorSelectionKey() !== selectionKey) return false;
    state.review.detail = detail;
    state.review.tagAggregates = aggregates;
    state.review.detailSelectionKey = selectionKey;
    return true;
  } catch (error) {
    if (generation === state.review.detailRequestGeneration
      && workspaceGeneration === state.workspaceGeneration
      && !quiet) {
      toast(error.message || "审核检查器详情载入失败");
    }
    return false;
  } finally {
    if (generation === state.review.detailRequestGeneration) {
      state.review.detailLoadingAssetID = null;
      state.review.detailLoadingSelectionKey = null;
      renderReviewDetail();
    }
  }
}

function renderReviewDetail() {
  const item = state.review.items[state.review.selectedIndex];
  const selectedItems = selectedReviewItems();
  const hasDetail = Boolean(item) && state.review.selectedAssetIDs.has(item.assetID);
  renderReviewInspectorActions(selectedItems);
  elements.reviewPlaceholder.classList.toggle("hidden", hasDetail);
  elements.reviewDetail.classList.toggle("hidden", !hasDetail);
  if (!hasDetail) {
    if (state.review.cloudPreview.assetID) resetReviewCloudPreviewRecovery();
    state.review.detail = null;
    state.review.tagAggregates = [];
    state.review.detailSelectionKey = null;
    state.review.detailRequestGeneration += 1;
    state.review.detailLoadingAssetID = null;
    state.review.detailLoadingSelectionKey = null;
    syncReviewControls();
    return;
  }

  elements.reviewPreviewImage.alt = item.fileName || "审核照片预览";
  const previewRevision = reviewInspectorDetailMatches(item)
    ? state.review.detail?.contentRevision
    : item.contentRevision;
  const previewQuery = previewRevision == null ? "" : `?r=${previewRevision}`;
  const recoveringCloudPreview = state.review.cloudPreview.assetID === item.assetID
    && state.review.cloudPreview.status !== "hidden";
  if (!recoveringCloudPreview) {
    setProtectedImageSource(
      elements.reviewPreviewImage,
      `/v1/assets/${item.assetID}/preview${previewQuery}`,
      { priority: "high", forceFetch: true }
    );
  }
  renderReviewCloudPreviewRecovery();
  elements.reviewFileName.textContent = item.fileName || "未命名照片";
  elements.reviewOrigin.textContent = [
    reviewOriginText(item.suggestionOrigin),
    item.score == null ? "" : `可信度 ${Math.round(item.score * 100)}%`,
    `已确认 ${item.acceptedTagCount} · 已拒绝 ${item.rejectedTagCount}`,
  ].filter(Boolean).join(" · ");
  elements.reviewSelectionSummary.textContent = selectedItems.length > 1
    ? `已选择 ${mediaItemCountText(selectedItems.length)} · 下方操作应用到全部选中项`
    : "当前 1 项";
  elements.reviewPosition.textContent = `${state.review.selectedIndex + 1} / ${state.review.items.length}`;
  elements.previousReviewButton.disabled = state.review.selectedIndex <= 0;
  elements.nextReviewButton.disabled = state.review.selectedIndex >= state.review.items.length - 1;
  const actionCount = selectedItems.length;
  for (const button of elements.reviewDetail.querySelectorAll(".review-action")) {
    const label = button.querySelector("span");
    if (!label) continue;
    label.textContent = {
      accept: actionCount > 1 ? `属于 ${actionCount} 项` : "属于",
      reject: actionCount > 1 ? `不属于 ${actionCount} 项` : "不属于",
      defer: actionCount > 1 ? `稍后处理 ${actionCount} 项` : "稍后",
    }[button.dataset.action] || label.textContent;
  }
  const detail = reviewInspectorDetailMatches(item) ? state.review.detail : null;
  renderReviewInspectorMetadata(item, detail);
  renderReviewInspectorTags(item, detail, selectedItems);
  syncReviewControls();
  if (!detail
    && !(state.review.detailLoadingAssetID === item.assetID
      && state.review.detailLoadingSelectionKey === reviewInspectorSelectionKey())) {
    queueMicrotask(() => void loadReviewInspectorDetail());
  }
}

function selectReviewIndex(
  index,
  { additive = false, extendRange = false, focusGrid = false } = {}
) {
  const previousPrimaryAssetID = state.review.items[state.review.selectedIndex]?.assetID || null;
  if (!state.review.items.length) {
    state.review.selectedIndex = -1;
    state.review.selectedAssetIDs.clear();
    state.review.selectionAnchorIndex = -1;
  } else {
    const bounded = Math.max(0, Math.min(index, state.review.items.length - 1));
    const assetID = state.review.items[bounded].assetID;
    if (extendRange) {
      const anchor = state.review.selectionAnchorIndex >= 0
        ? state.review.selectionAnchorIndex
        : (state.review.selectedIndex >= 0 ? state.review.selectedIndex : bounded);
      const next = additive ? new Set(state.review.selectedAssetIDs) : new Set();
      for (let candidate = Math.min(anchor, bounded); candidate <= Math.max(anchor, bounded); candidate += 1) {
        next.add(state.review.items[candidate].assetID);
      }
      state.review.selectedAssetIDs = next;
      state.review.selectedIndex = bounded;
      state.review.selectionAnchorIndex = anchor;
    } else if (additive) {
      if (state.review.selectedAssetIDs.has(assetID)) {
        state.review.selectedAssetIDs.delete(assetID);
        if (state.review.selectedIndex === bounded) {
          state.review.selectedIndex = state.review.items.findIndex((item) => (
            state.review.selectedAssetIDs.has(item.assetID)
          ));
        }
      } else {
        state.review.selectedAssetIDs.add(assetID);
        state.review.selectedIndex = bounded;
      }
      state.review.selectionAnchorIndex = bounded;
    } else {
      state.review.selectedAssetIDs = new Set([assetID]);
      state.review.selectedIndex = bounded;
      state.review.selectionAnchorIndex = bounded;
    }
  }
  const nextPrimaryAssetID = state.review.items[state.review.selectedIndex]?.assetID || null;
  if (previousPrimaryAssetID !== nextPrimaryAssetID
    && state.review.cloudPreview.assetID
    && state.review.cloudPreview.assetID !== nextPrimaryAssetID) {
    resetReviewCloudPreviewRecovery();
  }
  renderReviewSelectionState();
  checkpointActiveWorkspaceHistory();
  const selectedCard = elements.reviewGrid.querySelector(
    `[data-review-index="${state.review.selectedIndex}"]`
  );
  selectedCard?.scrollIntoView({
    block: "nearest",
    inline: "nearest",
  });
  if (focusGrid) {
    reviewCardMainButton(selectedCard)?.focus({ preventScroll: true });
  }
}

function moveReviewSelection(key, { extendRange = false } = {}) {
  if (!state.review.items.length) return;
  const currentIndex = state.review.selectedIndex >= 0
    ? state.review.selectedIndex
    : 0;
  let nextIndex;
  if (key === "Home") {
    nextIndex = 0;
  } else if (key === "End") {
    nextIndex = state.review.items.length - 1;
  } else {
    const columns = renderedGridColumnCount(
      elements.reviewGrid,
      ":scope > .review-card"
    );
    const delta = {
      ArrowLeft: -1,
      ArrowRight: 1,
      ArrowUp: -columns,
      ArrowDown: columns,
      PageUp: -renderedGridPageItemCount(
        elements.reviewQueuePane,
        elements.reviewGrid,
        ":scope > .review-card"
      ),
      PageDown: renderedGridPageItemCount(
        elements.reviewQueuePane,
        elements.reviewGrid,
        ":scope > .review-card"
      ),
    }[key];
    if (!delta) return;
    nextIndex = currentIndex + delta;
  }
  selectReviewIndex(nextIndex, { extendRange, focusGrid: true });
}

function reviewCardFingerprint(item) {
  return JSON.stringify([
    item.assetID,
    item.fileName,
    item.availability,
    item.contentRevision,
    item.acceptedTagCount,
    item.rejectedTagCount,
    item.suggestionOrigin,
    item.score,
    item.width,
    item.height,
    item.favorite?.isFavorite ?? null,
    item.favorite?.photosObservedValue ?? null,
    item.favorite?.syncStatus ?? null,
    item.favorite?.lastErrorCode ?? null,
  ]);
}

function reviewPageFingerprint(items, nextCursor) {
  return JSON.stringify([
    nextCursor || null,
    items.map(reviewCardFingerprint),
  ]);
}

function reviewItemKey(item) {
  return item ? `${item.assetID}:${item.suggestionOrigin}` : null;
}

function renderedReviewGridMatches(items) {
  const cards = [...elements.reviewGrid.querySelectorAll(":scope > .review-card")];
  return cards.length === items.length
    && cards.every((card, index) => (
      card.dataset.reviewKey === reviewItemKey(items[index])
      && card.dataset.reviewIndex === String(index)
    ));
}

function reviewPageStructureMatches(leftItems, leftCursor, rightItems, rightCursor) {
  return (leftCursor || null) === (rightCursor || null)
    && leftItems.length === rightItems.length
    && leftItems.every((item, index) => (
      reviewItemKey(item) === reviewItemKey(rightItems[index])
    ));
}

function currentReviewScopeKey() {
  const sourceIDs = resolvedReviewSourceFilter();
  return JSON.stringify({
    tagID: elements.reviewTagSelect.value,
    mediaKind: state.mediaKind,
    sourceIDs,
  });
}

function currentReviewOverviewScopeKey() {
  const sourceIDs = resolvedReviewSourceFilter();
  return JSON.stringify({ mediaKind: state.mediaKind, sourceIDs });
}

function reviewQueueNearEnd() {
  const pane = elements.reviewQueuePane;
  return pane.clientHeight > 0
    && pane.scrollHeight - pane.scrollTop - pane.clientHeight <= 280;
}

function scheduleReviewAutoPagination() {
  if (state.review.autoLoadFrame != null) return;
  state.review.autoLoadFrame = requestAnimationFrame(() => {
    state.review.autoLoadFrame = null;
    void autoPaginateReviewQueueIfNeeded();
  });
}

function deferReviewQueueRefreshUntilMarqueeEnds() {
  state.review.deferredQueueRefresh = true;
}

function reviewMarqueeBlocksQueueRefresh(marqueeGeneration) {
  return Boolean(state.review.marquee)
    || marqueeGeneration !== state.review.marqueeGeneration;
}

function flushDeferredReviewQueueRefresh() {
  if (!state.review.deferredQueueRefresh
    || state.review.marquee
    || state.review.loading) return;
  state.review.deferredQueueRefresh = false;
  if (state.review.mode !== "queue"
    || elements.reviewWorkspace.classList.contains("hidden")) return;
  void loadReviewQueue({
    preserveUnchangedGrid: true,
    preserveLoadedWindow: true,
  });
}

async function autoPaginateReviewQueueIfNeeded() {
  if (state.review.mode !== "queue"
    || elements.reviewWorkspace.classList.contains("hidden")
    || !state.review.nextCursor
    || state.review.loading
    || !reviewQueueNearEnd()) return;
  const previousCursor = state.review.nextCursor;
  const previousCount = state.review.items.length;
  const previousScrollTop = elements.reviewQueuePane.scrollTop;
  await loadReviewQueue({
    append: true,
    preserveUnchangedGrid: true,
    schedulePagination: false,
  });
  elements.reviewQueuePane.scrollTop = previousScrollTop;
  if (state.review.items.length <= previousCount
    || !state.review.nextCursor
    || state.review.nextCursor === previousCursor) return;
  scheduleReviewAutoPagination();
}

async function loadReviewQueue({
  append = false,
  preserveUnchangedGrid = false,
  preserveLoadedWindow = false,
  throwOnError = false,
  schedulePagination = true,
} = {}) {
  const marqueeGeneration = state.review.marqueeGeneration;
  if (state.review.marquee) {
    deferReviewQueueRefreshUntilMarqueeEnds();
    return false;
  }
  state.review.deferredQueueRefresh = false;
  const tagID = elements.reviewTagSelect.value;
  const scopeKey = currentReviewScopeKey();
  if (state.review.loadedScopeKey && state.review.loadedScopeKey !== scopeKey) {
    state.review.selectionMode = false;
    state.review.selectedAssetIDs.clear();
    state.review.selectionAnchorIndex = -1;
  }
  const loadedTargetCount = preserveLoadedWindow
    && state.review.loadedScopeKey === scopeKey
    ? Math.max(48, state.review.items.length)
    : 48;
  const generation = ++state.review.requestGeneration;
  const existingItems = state.review.items;
  const existingLoadedScopeKey = state.review.loadedScopeKey;
  const selectedKey = reviewItemKey(state.review.items[state.review.selectedIndex]);
  const selectedAssetIDs = new Set(state.review.selectedAssetIDs);
  const anchorAssetID = state.review.items[state.review.selectionAnchorIndex]?.assetID || null;
  const previousIndex = state.review.selectedIndex;
  const previousScrollTop = elements.reviewQueuePane.scrollTop;
  const focusedReviewKey = document.activeElement
    ?.closest(".review-card")?.dataset.reviewKey || null;
  if (!tagID) {
    state.review.items = [];
    state.review.nextCursor = null;
    state.review.selectedIndex = -1;
    state.review.selectedAssetIDs.clear();
    state.review.selectionAnchorIndex = -1;
    state.review.loadedScopeKey = scopeKey;
    state.review.loading = false;
    state.review.appending = false;
    renderReview();
    return true;
  }
  const sourceIDs = resolvedReviewSourceFilter();
  if (sourceIDs?.length === 0) {
    state.review.items = [];
    state.review.nextCursor = null;
    state.review.selectedIndex = -1;
    state.review.selectedAssetIDs.clear();
    state.review.selectionAnchorIndex = -1;
    state.review.loadedScopeKey = scopeKey;
    state.review.loading = false;
    state.review.appending = false;
    renderReview();
    return true;
  }

  const canPreserveExistingGrid = preserveUnchangedGrid
    && existingLoadedScopeKey === scopeKey
    && renderedReviewGridMatches(existingItems);
  state.review.loading = true;
  state.review.appending = append;
  let shouldRender = !canPreserveExistingGrid;
  let deferredForMarquee = false;
  let appendedItems = null;
  let changedReviewKeys = null;
  if (!append) {
    if (!canPreserveExistingGrid) {
      state.review.items = [];
      state.review.nextCursor = null;
      state.review.selectedIndex = -1;
    }
  }
  if (shouldRender) {
    renderReview();
  } else {
    syncReviewControls();
  }
  const fetchPage = (cursor = null) => {
    const query = new URLSearchParams({ tagID, mediaKind: state.mediaKind, limit: "48" });
    if (sourceIDs) query.set("sourceIDs", sourceIDs.join(","));
    if (cursor) query.set("cursor", cursor);
    return api(`/v1/review/queue?${query}`);
  };
  const requestCursor = append ? state.review.nextCursor : null;

  try {
    let page;
    if (!append && preserveLoadedWindow) {
      const items = [];
      const seenCursors = new Set();
      let nextCursor = null;
      do {
        const nextPage = await fetchPage(nextCursor);
        items.push(...nextPage.items);
        nextCursor = nextPage.nextCursor || null;
        if (!nextCursor || seenCursors.has(nextCursor)) break;
        seenCursors.add(nextCursor);
      } while (items.length < loadedTargetCount);
      page = { items, nextCursor };
    } else {
      page = await fetchPage(requestCursor);
    }
    if (generation !== state.review.requestGeneration
      || scopeKey !== currentReviewScopeKey()) return false;
    if (reviewMarqueeBlocksQueueRefresh(marqueeGeneration)) {
      deferReviewQueueRefreshUntilMarqueeEnds();
      deferredForMarquee = true;
      shouldRender = false;
      return false;
    }
    const nextItems = append ? state.review.items.concat(page.items) : page.items;
    const nextCursor = page.nextCursor || null;
    shouldRender = shouldRender
      || reviewPageFingerprint(state.review.items, state.review.nextCursor)
        !== reviewPageFingerprint(nextItems, nextCursor);
    const canRenderChangedCardsOnly = !append
      && canPreserveExistingGrid
      && reviewPageStructureMatches(
        existingItems,
        state.review.nextCursor,
        nextItems,
        nextCursor
      );
    if (canRenderChangedCardsOnly) {
      changedReviewKeys = nextItems
        .filter((item, index) => (
          reviewCardFingerprint(item) !== reviewCardFingerprint(existingItems[index])
        ))
        .map(reviewItemKey);
    }
    const existingKeys = append
      ? new Set(existingItems.map(reviewItemKey))
      : null;
    const appendedKeys = append ? new Set() : null;
    const canAppendCardsOnly = append
      && existingLoadedScopeKey === scopeKey
      && renderedReviewGridMatches(existingItems)
      && page.items.every((item) => {
        const key = reviewItemKey(item);
        if (!key || existingKeys.has(key) || appendedKeys.has(key)) return false;
        appendedKeys.add(key);
        return true;
      });
    if (canAppendCardsOnly) appendedItems = page.items;
    state.review.items = nextItems;
    state.review.nextCursor = nextCursor;
    state.review.loadedScopeKey = scopeKey;
    const validAssetIDs = new Set(state.review.items.map((item) => item.assetID));
    state.review.selectedAssetIDs = new Set(
      [...selectedAssetIDs].filter((assetID) => validAssetIDs.has(assetID))
    );
    const restoredIndex = selectedKey
      ? state.review.items.findIndex((item) => reviewItemKey(item) === selectedKey)
      : -1;
    if (state.review.selectedAssetIDs.size) {
      state.review.selectedIndex = restoredIndex >= 0
        && state.review.selectedAssetIDs.has(state.review.items[restoredIndex].assetID)
        ? restoredIndex
        : state.review.items.findIndex((item) => state.review.selectedAssetIDs.has(item.assetID));
    } else if (state.review.items.length) {
      state.review.selectedIndex = Math.max(0, Math.min(previousIndex, state.review.items.length - 1));
      state.review.selectedAssetIDs.add(state.review.items[state.review.selectedIndex].assetID);
    } else {
      state.review.selectedIndex = -1;
    }
    const restoredAnchorIndex = anchorAssetID
      ? state.review.items.findIndex((item) => item.assetID === anchorAssetID)
      : -1;
    state.review.selectionAnchorIndex = restoredAnchorIndex >= 0
      ? restoredAnchorIndex
      : state.review.selectedIndex;
  } catch (error) {
    if (generation === state.review.requestGeneration && !throwOnError) {
      toast(error.message || "审核队列载入失败");
    }
    if (throwOnError) throw error;
  } finally {
    if (generation === state.review.requestGeneration) {
      state.review.loading = false;
      state.review.appending = false;
      if (shouldRender) {
        if (appendedItems !== null) {
          renderReviewCollectionSummary();
          appendReviewCards(appendedItems, existingItems.length);
        } else if (changedReviewKeys !== null) {
          renderReviewCollectionSummary();
          renderReviewCardsForKeys(changedReviewKeys);
          const selectedReviewKey = reviewItemKey(
            state.review.items[state.review.selectedIndex]
          );
          if (changedReviewKeys.includes(selectedReviewKey)) renderReviewDetail();
        } else {
          renderReview();
        }
      } else {
        syncReviewControls();
      }
      if (append || preserveUnchangedGrid) {
        elements.reviewQueuePane.scrollTop = previousScrollTop;
      }
      if (focusedReviewKey
        && document.activeElement?.closest(".review-card")?.dataset.reviewKey
          !== focusedReviewKey) {
        reviewCardMainButton(elements.reviewGrid.querySelector(
          `[data-review-key="${CSS.escape(focusedReviewKey)}"]`
        ))?.focus({ preventScroll: true });
      }
      if (!deferredForMarquee && schedulePagination) scheduleReviewAutoPagination();
      if (deferredForMarquee) flushDeferredReviewQueueRefresh();
    }
  }
  return shouldRender;
}

async function openReviewWorkspace({
  returnToTrainingRunID = null,
  initialMode = "overview",
  initialTagID = null,
  historyMode = "push",
  refreshTagSuggestions = true,
} = {}) {
  leaveIntegratedGalleryOverviewForLibrary({ historyMode: "none" });
  leaveIntegratedWorldMapForLibrary({ historyMode: "none" });
  resetCloudPreviewRecovery();
  if (elements.trainingSetupDialog.open) closeTrainingSetupDialog();
  closeReviewSourceFilter({ restoreFocus: false });
  elements.trainingWorkspace.classList.add("hidden");
  syncTrainingPresentation({ renderSurfaces: false });
  if (returnToTrainingRunID) {
    state.review.returnTarget = {
      workspace: "training",
      runID: returnToTrainingRunID,
    };
  } else {
    state.review.returnTarget = null;
    state.review.pendingFocusTrainingJobID = null;
    state.trainingReturnFocus = null;
  }
  elements.slimmingWorkspace.classList.add("hidden");
  syncSlimmingPresentation({ renderSurfaces: false });
  state.slimmingReturnFocus = null;
  state.slimmingReturnTarget = null;
  closeJobsPopover({ restoreFocus: false });
  closeFilterPopover({ restoreFocus: false });
  if (!returnToTrainingRunID && elements.reviewWorkspace.classList.contains("hidden")) {
    state.reviewReturnFocus = document.activeElement;
  }
  elements.reviewWorkspace.classList.remove("hidden");
  state.review.mode = initialMode === "queue" ? "queue" : "overview";
  state.review.selectionMode = false;
  if (initialTagID) elements.reviewTagSelect.value = initialTagID;
  syncReviewPresentation({ focus: true });
  recordWorkspaceHistory(
    "review",
    currentWorkspaceHistoryContext("review"),
    historyMode
  );
  syncReviewClosePresentation();
  renderSampleSuggestions();
  renderReviewMode();
  await Promise.all([
    loadReviewOverview(),
    refreshTagSuggestions
      ? loadTagLibrarySuggestions({ quiet: true })
      : Promise.resolve(),
    loadSampleSuggestions({ quiet: true }),
    loadLibrarySuggestions({ quiet: true, refreshServiceHealth: true }),
    supportsGeneralSettings() ? loadGeneralSettings({ quiet: true }) : Promise.resolve(),
  ]);
  if (state.review.mode === "queue") {
    await loadReviewQueue({ preserveLoadedWindow: true });
  }
}

function trainingSetupMethodAvailability(method) {
  return state.training.setup.snapshot?.methods?.find((item) => item.method === method)?.isAvailable
    ?? false;
}

function trainingSetupEligibleTags(method = state.training.setup.method) {
  const tags = state.training.setup.snapshot?.tags || [];
  if (method === "featureKnn") return tags.filter((tag) => Boolean(tag.featureMode));
  return tags.filter((tag) => tag.personalEligible);
}

function trainingSetupMethodCopy(method) {
  const noun = state.training.mediaKind === "video" ? "视频" : "照片";
  return {
    featureKnn: {
      icon: "⌁",
      title: `寻找相似${noun}`,
      technical: "Feature Print k-NN",
      detail: `用确认的正反样本，在所选来源中寻找相似${noun}。`,
      requirement: "每个标签至少 2 个属于、2 个不属于",
    },
    personalCentroid: {
      icon: "◎",
      title: "快速个人模型",
      technical: "Personal Centroid",
      detail: "按标签建立轻量个人模型，训练快，适合频繁更新。",
      requirement: `每个标签至少 2 个已确认${noun}`,
    },
    personalAdamW: {
      icon: "✦",
      title: "增强个人模型",
      technical: "Personal AdamW",
      detail: "进行多轮优化并保留验证指标，适合样本更完整的标签。",
      requirement: `每个标签至少 2 个已确认${noun}`,
    },
  }[method];
}

function chooseInitialTrainingSetupMethod() {
  const ordered = ["featureKnn", "personalCentroid", "personalAdamW"];
  return ordered.find((method) => trainingSetupMethodAvailability(method)
    && trainingSetupEligibleTags(method).length
    && (method !== "featureKnn" || state.training.setup.snapshot.sources.length))
    || ordered.find(trainingSetupMethodAvailability)
    || "featureKnn";
}

function resetTrainingSetupSelection(method) {
  const setup = state.training.setup;
  setup.method = method;
  setup.selectedTagIDs = new Set();
  setup.selectedSourceIDs = new Set();
  setup.scope = "allSources";
  setup.tagSearchText = "";
  setup.error = "";
  setup.notice = "";
  elements.trainingTagSearch.value = "";
  const eligibleTags = trainingSetupEligibleTags(method);
  if (method === "featureKnn") {
    if (eligibleTags[0]) setup.selectedTagIDs.add(eligibleTags[0].id);
    for (const source of setup.snapshot?.sources || []) setup.selectedSourceIDs.add(source.id);
  } else if (eligibleTags.length === 1) {
    setup.selectedTagIDs.add(eligibleTags[0].id);
  }
}

function reconcileTrainingSetupSummary(rows) {
  const existing = new Map(
    [...elements.trainingLaunchSummary.querySelectorAll(
      ":scope > dt[data-training-summary-key]"
    )].map((term) => {
      const description = term.nextElementSibling;
      return description?.matches("dd[data-training-summary-key]")
        && description.dataset.trainingSummaryKey === term.dataset.trainingSummaryKey
        ? [term.dataset.trainingSummaryKey, { term, description }]
        : null;
    }).filter(Boolean)
  );
  const wanted = [];
  for (const row of rows) {
    let pair = existing.get(row.key) || null;
    existing.delete(row.key);
    if (!pair) {
      const term = document.createElement("dt");
      const description = document.createElement("dd");
      term.dataset.trainingSummaryKey = row.key;
      description.dataset.trainingSummaryKey = row.key;
      pair = { term, description };
    }
    if (pair.term.textContent !== row.label) pair.term.textContent = row.label;
    if (pair.description.textContent !== row.value) pair.description.textContent = row.value;
    wanted.push(pair.term, pair.description);
  }
  reconcileStableChildren(elements.trainingLaunchSummary, wanted);
}

function createTrainingSetupMethodOption() {
  const button = document.createElement("button");
  button.type = "button";
  button.className = "training-method-option";
  const icon = document.createElement("span");
  icon.className = "training-method-icon";
  const body = document.createElement("span");
  body.className = "training-method-copy";
  body.append(
    document.createElement("strong"),
    document.createElement("span"),
    document.createElement("span"),
    document.createElement("span")
  );
  const check = document.createElement("span");
  check.className = "training-method-check";
  button.append(icon, body, check);
  return button;
}

function syncTrainingSetupMethodOption(button, method) {
  const copy = trainingSetupMethodCopy(method);
  const eligibleCount = trainingSetupEligibleTags(method).length;
  const available = trainingSetupMethodAvailability(method)
    && eligibleCount > 0
    && (method !== "featureKnn" || Boolean(state.training.setup.snapshot?.sources?.length));
  const selected = state.training.setup.method === method;
  button.id = `trainingSetupMethod-${method}`;
  button.classList.toggle("selected", selected);
  button.disabled = !available
    || state.training.setup.launching
    || Boolean(currentActiveTrainingActivity());
  button.dataset.trainingSetupMethod = method;
  button.setAttribute("role", "radio");
  button.setAttribute("aria-checked", String(selected));
  configurePersistentHelp(button, {
    title: copy.title,
    detail: available
      ? `${copy.detail}\n${copy.requirement}\n点击后可继续选择标签和${state.training.mediaKind === "video" ? "视频" : "照片"}范围。`
      : `${copy.detail}\n${eligibleCount ? "当前 Mac 尚未提供此训练能力。" : copy.requirement}`,
    kind: "training",
  });
  const icon = button.querySelector(":scope > .training-method-icon");
  if (icon.textContent !== copy.icon) icon.textContent = copy.icon;
  const body = button.querySelector(":scope > .training-method-copy");
  const [title, technical, detail, requirement] = body.children;
  if (title.textContent !== copy.title) title.textContent = copy.title;
  const technicalText = `技术：${copy.technical}`;
  if (technical.textContent !== technicalText) technical.textContent = technicalText;
  if (detail.textContent !== copy.detail) detail.textContent = copy.detail;
  const requirementText = available
    ? `✓ ${copy.requirement}`
    : (eligibleCount ? "当前设备尚未提供此训练能力" : copy.requirement);
  if (requirement.textContent !== requirementText) requirement.textContent = requirementText;
  const check = button.querySelector(":scope > .training-method-check");
  const checkText = selected ? "●" : "○";
  if (check.textContent !== checkText) check.textContent = checkText;
}

function renderTrainingSetupMethods() {
  const existingOptions = new Map(
    [...elements.trainingSetupMethods.querySelectorAll(":scope > .training-method-option")]
      .map((button) => [button.dataset.trainingSetupMethod, button])
  );
  const methodOptions = ["featureKnn", "personalCentroid", "personalAdamW"].map((method) => {
    const button = existingOptions.get(method) || createTrainingSetupMethodOption();
    syncTrainingSetupMethodOption(button, method);
    return button;
  });
  reconcileStableChildren(elements.trainingSetupMethods, methodOptions);
  syncRovingSegmentedControl(
    elements.trainingSetupMethods,
    "[data-training-setup-method]"
  );
}

function createTrainingTagOption() {
  const row = document.createElement("label");
  row.className = "training-option-row";
  row.append(
    document.createElement("input"),
    document.createElement("strong"),
    document.createElement("span")
  );
  return row;
}

function syncTrainingTagOption(row, tag, isFeature) {
  const input = row.querySelector(":scope > input");
  input.id = `trainingTag-${tag.id}`;
  input.type = isFeature ? "radio" : "checkbox";
  input.name = "trainingTag";
  input.value = tag.id;
  input.checked = state.training.setup.selectedTagIDs.has(tag.id);
  input.disabled = state.training.setup.launching;
  input.dataset.trainingTagId = tag.id;
  input.setAttribute("aria-keyshortcuts", choiceGridNavigationShortcuts);
  const name = row.querySelector(":scope > strong");
  if (name.textContent !== tag.displayName) name.textContent = tag.displayName;
  const counts = row.querySelector(":scope > span");
  const countText = isFeature
    ? `属于 ${tag.acceptedSampleCount} · 不属于 ${tag.rejectedSampleCount}`
    : `已确认 ${tag.acceptedSampleCount} 个`;
  if (counts.textContent !== countText) counts.textContent = countText;
  configurePersistentHelp(row, {
    title: `训练标签 · ${tag.displayName}`,
    detail: isFeature
      ? `属于 ${tag.acceptedSampleCount} · 不属于 ${tag.rejectedSampleCount}。方向键、Page Up/Page Down 或 Home/End 会移动并选择标签；Mac 会再次检查 2 + 2 样本门槛。`
      : `已确认 ${tag.acceptedSampleCount} 个样本。方向键、Page Up/Page Down 或 Home/End 可移动，空格键切换勾选；每个标签独立发布。`,
    kind: "training",
    keyShortcuts: choiceGridNavigationShortcuts,
  });
}

function renderTrainingTagOptions() {
  const setup = state.training.setup;
  const isFeature = setup.method === "featureKnn";
  const query = setup.tagSearchText.trim().toLocaleLowerCase("zh-CN");
  const tags = trainingSetupEligibleTags().filter((tag) => (
    !query || tag.displayName.toLocaleLowerCase("zh-CN").includes(query)
  ));
  if (!tags.length) {
    let empty = elements.trainingTagOptions.querySelector(":scope > .training-options-empty");
    if (!empty) {
      empty = document.createElement("div");
      empty.className = "training-options-empty";
    }
    empty.textContent = query ? "没有匹配的可训练标签" : "还没有达到最低样本要求的标签";
    reconcileStableChildren(elements.trainingTagOptions, [empty]);
    return;
  }
  const existingOptions = new Map(
    [...elements.trainingTagOptions.querySelectorAll(":scope > .training-option-row")]
      .map((row) => [row.querySelector("[data-training-tag-id]")?.dataset.trainingTagId, row])
  );
  const tagOptions = tags.map((tag) => {
    const row = existingOptions.get(tag.id) || createTrainingTagOption();
    syncTrainingTagOption(row, tag, isFeature);
    return row;
  });
  reconcileStableChildren(elements.trainingTagOptions, tagOptions);
}

function createTrainingSourceOption() {
  const row = document.createElement("label");
  row.className = "training-option-row";
  const input = document.createElement("input");
  input.type = "checkbox";
  row.append(input, document.createElement("strong"), document.createElement("span"));
  return row;
}

function syncTrainingSourceOption(row, source) {
  const input = row.querySelector(':scope > input[type="checkbox"]');
  input.id = `trainingSource-${source.id}`;
  input.checked = state.training.setup.selectedSourceIDs.has(source.id);
  input.disabled = state.training.setup.launching;
  input.dataset.trainingSourceId = source.id;
  input.setAttribute("aria-keyshortcuts", choiceGridNavigationShortcuts);
  const name = row.querySelector(":scope > strong");
  if (name.textContent !== source.displayName) name.textContent = source.displayName;
  const status = row.querySelector(":scope > span");
  if (status.textContent !== "可用") status.textContent = "可用";
  configurePersistentHelp(row, {
    title: `训练来源 · ${source.displayName}`,
    detail: `决定相似${state.training.mediaKind === "video" ? "视频" : "照片"}任务扫描哪些来源。方向键、Page Up/Page Down 或 Home/End 可移动，空格键切换勾选；Mac 会冻结本次目录范围。`,
    kind: "training",
    keyShortcuts: choiceGridNavigationShortcuts,
  });
}

function createTrainingScopeOption() {
  const row = document.createElement("label");
  row.className = "training-option-row";
  const input = document.createElement("input");
  input.type = "radio";
  input.name = "trainingScope";
  row.append(input, document.createElement("strong"), document.createElement("span"));
  return row;
}

function syncTrainingScopeOption(row, choice, noun) {
  const input = row.querySelector(':scope > input[type="radio"]');
  input.id = `trainingScope-${choice.value}`;
  input.value = choice.value;
  input.checked = state.training.setup.scope === choice.value;
  input.disabled = state.training.setup.launching;
  input.dataset.trainingScope = choice.value;
  const title = row.querySelector(":scope > strong");
  if (title.textContent !== choice.title) title.textContent = choice.title;
  const note = row.querySelector(":scope > span");
  if (note.textContent !== choice.note) note.textContent = choice.note;
  configurePersistentHelp(row, {
    title: choice.title,
    detail: choice.value === "currentSelection"
      ? `只使用图库当前选择的 ${state.selectedAssetIDs.size} 项；离开设置前仍由 Mac 复核媒体类型与可用性。`
      : `使用所有来源中已确认属于所选标签的${noun}；不会受图库当前来源、搜索或滚动位置限制。`,
    kind: "training",
  });
}

function renderTrainingScopeOptions() {
  const setup = state.training.setup;
  const noun = state.training.mediaKind === "video" ? "视频" : "照片";
  if (setup.method === "featureKnn") {
    elements.trainingScopeTitle.textContent = `扫描哪些${noun}来源？`;
    elements.trainingScopeHint.textContent = "只读取所选来源；任务会冻结本次范围。";
    const existingOptions = new Map(
      [...elements.trainingScopeOptions.querySelectorAll(
        ":scope > .training-option-row"
      )].map((row) => [
        row.querySelector("[data-training-source-id]")?.dataset.trainingSourceId,
        row,
      ])
    );
    const sourceOptions = (setup.snapshot?.sources || []).map((source) => {
      const row = existingOptions.get(source.id) || createTrainingSourceOption();
      syncTrainingSourceOption(row, source);
      return row;
    });
    reconcileStableChildren(elements.trainingScopeOptions, sourceOptions);
    return;
  }
  elements.trainingScopeTitle.textContent = `使用哪些${noun}？`;
  elements.trainingScopeHint.textContent = `默认使用所有来源中的已确认${noun}；只有明确选择时才限制为图库当前选择。`;
  const choices = [{ value: "allSources", title: `所有来源中的已确认${noun}`, note: "推荐" }];
  const canUseSelection = state.mediaKind === state.training.mediaKind && state.selectedAssetIDs.size > 0;
  if (canUseSelection) {
    choices.push({
      value: "currentSelection",
      title: `图库中当前选择的 ${state.selectedAssetIDs.size} ${noun === "照片" ? "张照片" : "个视频"}`,
      note: "限制范围",
    });
  }
  const existingOptions = new Map(
    [...elements.trainingScopeOptions.querySelectorAll(":scope > .training-option-row")]
      .map((row) => [row.querySelector("[data-training-scope]")?.dataset.trainingScope, row])
  );
  const scopeOptions = choices.map((choice) => {
    const row = existingOptions.get(choice.value) || createTrainingScopeOption();
    syncTrainingScopeOption(row, choice, noun);
    return row;
  });
  reconcileStableChildren(elements.trainingScopeOptions, scopeOptions);
}

function canLaunchTrainingSetup() {
  const setup = state.training.setup;
  if (setup.loading
    || setup.launching
    || Boolean(currentActiveTrainingActivity())
    || !setup.snapshot
    || !trainingSetupMethodAvailability(setup.method)
    || !setup.selectedTagIDs.size) return false;
  if (setup.method === "featureKnn") {
    return setup.selectedTagIDs.size === 1 && setup.selectedSourceIDs.size > 0;
  }
  if (setup.scope === "currentSelection") {
    return state.mediaKind === state.training.mediaKind && state.selectedAssetIDs.size > 0;
  }
  return true;
}

function renderTrainingSetupSummary() {
  const setup = state.training.setup;
  const copy = trainingSetupMethodCopy(setup.method);
  const selectedTags = (setup.snapshot?.tags || [])
    .filter((tag) => setup.selectedTagIDs.has(tag.id))
    .map((tag) => tag.displayName);
  reconcileTrainingSetupSummary([
    { key: "task", label: "任务", value: `${copy.title}（${copy.technical}）` },
    {
      key: "tags",
      label: "标签",
      value: selectedTags.length ? selectedTags.join("、") : "尚未选择",
    },
    setup.method === "featureKnn"
      ? { key: "scope", label: "来源", value: `${setup.selectedSourceIDs.size} 个来源` }
      : {
        key: "scope",
        label: state.training.mediaKind === "video" ? "视频范围" : "照片范围",
        value: setup.scope === "currentSelection"
          ? `图库当前选择 ${state.selectedAssetIDs.size} 项`
          : "所有来源中的已确认样本",
      },
    { key: "requirement", label: "最低要求", value: copy.requirement },
  ]);
}

function renderTrainingSetup() {
  const setup = state.training.setup;
  const activeActivity = currentActiveTrainingActivity();
  elements.trainingSetupLoading.classList.toggle("hidden", !setup.loading);
  elements.trainingSetupConfiguration.classList.toggle("hidden", setup.loading || !setup.snapshot);
  elements.trainingSetupError.textContent = setup.error;
  const activeNotice = activeActivity
    ? "当前已有个人模型训练正在运行；完成或取消后才能创建下一项。"
    : "";
  const notice = [setup.notice, activeNotice].filter(Boolean).join(" ");
  elements.trainingSetupNotice.textContent = notice;
  elements.trainingSetupNotice.classList.toggle("hidden", !notice);
  elements.trainingTagSearch.disabled = setup.loading || setup.launching;
  elements.launchTrainingButton.disabled = !canLaunchTrainingSetup();
  elements.launchTrainingButton.textContent = setup.launching
    ? "正在交给 Mac…"
    : (setup.method === "featureKnn" ? "开始寻找" : "开始训练");
  configurePersistentHelp(elements.cancelTrainingSetupButton, {
    title: "取消新建任务",
    detail: "放弃本次训练设置并关闭窗口，不创建任务，也不会停止已经运行的后台任务。",
    kind: "training",
  });
  configurePersistentHelp(elements.launchTrainingButton, {
    title: setup.method === "featureKnn" ? "开始寻找" : "开始训练",
    detail: canLaunchTrainingSetup()
      ? `按当前标签、方法和${state.training.mediaKind === "video" ? "视频" : "照片"}范围创建任务；Mac 会在接受前再次校验样本、来源和选择。`
      : (activeActivity
        ? "当前已有个人模型训练在运行；完成或取消后才能创建下一项。"
        : "请先选择可用的方法、至少一个合格标签和有效媒体范围。"),
    kind: "training",
  });
  if (!setup.snapshot) return;
  const noun = state.training.mediaKind === "video" ? "视频" : "照片";
  const isFeature = setup.method === "featureKnn";
  elements.trainingSetupConfigTitle.textContent = isFeature
    ? `选择一个标签和${noun}来源`
    : `选择标签和${noun}范围`;
  elements.trainingSetupConfigHint.textContent = isFeature
    ? `标签会显示现有正反样本数；Host 会再次检查 2 + 2 门槛。`
    : "每个标签独立训练、独立发布；一个失败不会撤销其他标签。";
  renderTrainingSetupMethods();
  renderTrainingTagOptions();
  renderTrainingScopeOptions();
  renderTrainingSetupSummary();
}

function applyTrainingSetupPrefill(prefill) {
  if (!prefill) return;
  const setup = state.training.setup;
  const requestedMethod = prefill.method;
  if (requestedMethod
    && setup.snapshot?.methods?.some((item) => item.method === requestedMethod)) {
    resetTrainingSetupSelection(requestedMethod);
  }

  const eligibleTagIDs = new Set(trainingSetupEligibleTags().map((tag) => tag.id));
  const requestedTagIDs = (prefill.tagIDs || []).filter((id) => eligibleTagIDs.has(id));
  if (requestedTagIDs.length) {
    setup.selectedTagIDs = new Set(
      setup.method === "featureKnn" ? requestedTagIDs.slice(0, 1) : requestedTagIDs
    );
    const selectedTag = requestedTagIDs.length === 1
      ? setup.snapshot?.tags?.find((tag) => tag.id === requestedTagIDs[0])
      : null;
    setup.tagSearchText = selectedTag?.displayName || "";
    elements.trainingTagSearch.value = setup.tagSearchText;
  }
  if (prefill.requireExplicitTag && !requestedTagIDs.length) {
    setup.selectedTagIDs.clear();
  }

  if (prefill.scope === "currentSelection"
    && setup.method !== "featureKnn"
    && state.mediaKind === state.training.mediaKind
    && state.selectedAssetIDs.size) {
    setup.scope = "currentSelection";
  }

  setup.notice = prefill.note || "";
  if (requestedMethod && !trainingSetupMethodAvailability(requestedMethod)) {
    setup.notice = `${setup.notice ? `${setup.notice} ` : ""}当前 Mac Host 尚未提供此训练能力。`;
  }
  if (setup.method === "featureKnn" && prefill.sourceScope === "unresolved") {
    setup.selectedSourceIDs.clear();
  } else if (setup.method === "featureKnn" && prefill.sourceScope === "selectedSources") {
    const availableSourceIDs = new Set((setup.snapshot?.sources || []).map((source) => source.id));
    const savedSourceIDs = prefill.sourceIDs || [];
    const requestedSourceIDs = savedSourceIDs.filter((id) => availableSourceIDs.has(id));
    setup.selectedSourceIDs = new Set(requestedSourceIDs);
    const unavailableCount = savedSourceIDs.length - requestedSourceIDs.length;
    if (unavailableCount > 0) {
      setup.notice = `${setup.notice ? `${setup.notice} ` : ""}${unavailableCount} 个历史来源当前不可用，已从本次配置中移除。`;
    }
  }
}

function trainingSetupBaseLevelFromHistory(context = {}) {
  return ["sidebar", "inspector", "lightbox"].includes(context.trainingSetupBaseLevel)
    ? context.trainingSetupBaseLevel
    : "workspace";
}

function trainingSetupScrollSurfaces() {
  return {
    methods: elements.trainingSetupDialog.querySelector(".training-setup-body > aside"),
    configuration: elements.trainingSetupDialog.querySelector(".training-setup-body > main"),
    tags: elements.trainingTagOptions,
    scope: elements.trainingScopeOptions,
  };
}

function currentTrainingSetupHistoryContext() {
  const setup = state.training.setup;
  const scroll = trainingSetupScrollSurfaces();
  return {
    trainingSetupMethod: setup.method,
    trainingSetupTagIDs: [...setup.selectedTagIDs].slice(0, GALLERY_HISTORY_LOADED_LIMIT),
    trainingSetupSourceIDs: [...setup.selectedSourceIDs]
      .slice(0, GALLERY_HISTORY_LOADED_LIMIT),
    trainingSetupScope: setup.scope,
    trainingSetupMethodsScrollTop: scroll.methods?.scrollTop || 0,
    trainingSetupConfigurationScrollTop: scroll.configuration?.scrollTop || 0,
    trainingSetupTagsScrollTop: scroll.tags?.scrollTop || 0,
    trainingSetupScopeScrollTop: scroll.scope?.scrollTop || 0,
  };
}

function applyTrainingSetupHistoryContext(context = {}) {
  const setup = state.training.setup;
  if (!setup.snapshot) return false;
  const methods = new Set(["featureKnn", "personalCentroid", "personalAdamW"]);
  const requestedMethod = methods.has(context.trainingSetupMethod)
    && setup.snapshot.methods?.some((item) => item.method === context.trainingSetupMethod)
    ? context.trainingSetupMethod
    : chooseInitialTrainingSetupMethod();
  resetTrainingSetupSelection(requestedMethod);

  const eligibleTagIDs = new Set(trainingSetupEligibleTags().map((tag) => tag.id));
  const savedTagIDs = Array.isArray(context.trainingSetupTagIDs)
    ? context.trainingSetupTagIDs
      .map(galleryHistoryIdentifier)
      .filter(Boolean)
      .slice(0, GALLERY_HISTORY_LOADED_LIMIT)
    : null;
  if (savedTagIDs) {
    const selectedTagIDs = [...new Set(savedTagIDs)]
      .filter((tagID) => eligibleTagIDs.has(tagID));
    setup.selectedTagIDs = new Set(
      setup.method === "featureKnn" ? selectedTagIDs.slice(0, 1) : selectedTagIDs
    );
  }

  if (setup.method === "featureKnn") {
    const activeSourceIDs = new Set((setup.snapshot.sources || []).map((source) => source.id));
    const savedSourceIDs = Array.isArray(context.trainingSetupSourceIDs)
      ? context.trainingSetupSourceIDs
        .map(galleryHistoryIdentifier)
        .filter(Boolean)
        .slice(0, GALLERY_HISTORY_LOADED_LIMIT)
      : null;
    if (savedSourceIDs) {
      setup.selectedSourceIDs = new Set(
        [...new Set(savedSourceIDs)].filter((sourceID) => activeSourceIDs.has(sourceID))
      );
    }
  } else if (["allSources", "currentSelection"].includes(context.trainingSetupScope)) {
    setup.scope = context.trainingSetupScope;
  }

  const missingTagCount = savedTagIDs
    ? new Set(savedTagIDs.filter((tagID) => !eligibleTagIDs.has(tagID))).size
    : 0;
  const activeSourceIDs = new Set((setup.snapshot.sources || []).map((source) => source.id));
  const savedSourceIDs = Array.isArray(context.trainingSetupSourceIDs)
    ? context.trainingSetupSourceIDs.map(galleryHistoryIdentifier).filter(Boolean)
    : [];
  const missingSourceCount = setup.method === "featureKnn"
    ? new Set(savedSourceIDs.filter((sourceID) => !activeSourceIDs.has(sourceID))).size
    : 0;
  const notes = [];
  if (context.trainingSetupMethod && requestedMethod !== context.trainingSetupMethod) {
    notes.push("刷新前的训练方法当前不可用，已切换到可用方法。");
  }
  if (missingTagCount) notes.push(`${missingTagCount} 个历史标签当前不可用，已移除。`);
  if (missingSourceCount) notes.push(`${missingSourceCount} 个历史来源当前不可用，已移除。`);
  if (setup.scope === "currentSelection" && !state.selectedAssetIDs.size) {
    notes.push("刷新前的图库选区当前不可用，请重新确认照片范围。");
  }
  setup.notice = notes.join(" ");
  setup.tagSearchText = "";
  elements.trainingTagSearch.value = "";
  return true;
}

async function restoreTrainingSetupScrollFromHistory(context = {}) {
  await waitForWorkspaceLayout();
  const scroll = trainingSetupScrollSurfaces();
  const targets = [
    [scroll.methods, context.trainingSetupMethodsScrollTop],
    [scroll.configuration, context.trainingSetupConfigurationScrollTop],
    [scroll.tags, context.trainingSetupTagsScrollTop],
    [scroll.scope, context.trainingSetupScopeScrollTop],
  ];
  for (const [surface, value] of targets) {
    if (!surface) continue;
    surface.scrollTop = Math.min(
      workspaceHistoryScrollTop(value),
      Math.max(0, surface.scrollHeight - surface.clientHeight)
    );
  }
}

function replaceTrainingSetupHistoryWithBase(baseLevel) {
  if (!state.workspaceNavigation.initialized
    || elements.appView.classList.contains("hidden")) return;
  const current = activeWorkspaceHistoryEntry();
  const route = visibleWorkspaceRoute();
  if (current?.route !== route || current.navigationLevel !== "trainingSetup") return;
  const context = currentWorkspaceHistoryContext(route);
  if (context && typeof context === "object") delete context.trainingSetupBaseLevel;
  const navigationLevel = visibleWorkspaceNavigationBaseLevel(route, baseLevel);
  history.replaceState({
    ...(history.state || {}),
    [WORKSPACE_HISTORY_KEY]: workspaceHistoryEntry(route, context, navigationLevel),
  }, "", location.href);
}

function clearTrainingSetupDialogState({ cancelRequest = true } = {}) {
  const setup = state.training.setup;
  if (cancelRequest) setup.requestGeneration += 1;
  setup.loading = false;
  setup.launching = false;
  setup.operationID = null;
  setup.returnFocus = null;
  setup.baseLevel = "workspace";
  setup.historyRestoreFocus = true;
  setup.focusID = "closeTrainingSetupButton";
  setup.restorable = false;
  setup.opening = false;
}

function presentTrainingSetupDialog({
  historyMode = "pushTrainingSetup",
  baseLevel = null,
  focus = true,
} = {}) {
  const setup = state.training.setup;
  if (elements.trainingSetupDialog.open) {
    if (focus) restoreOverlayFocus(elements.closeTrainingSetupButton);
    return;
  }
  const current = activeWorkspaceHistoryEntry();
  setup.baseLevel = baseLevel
    || workspaceNavigationBaseLevel(
      current?.navigationLevel || "workspace",
      current?.context || {}
    );
  elements.trainingSetupDialog.showModal();
  if (historyMode !== "none") {
    const route = visibleWorkspaceRoute();
    recordWorkspaceHistory(route, currentWorkspaceHistoryContext(route), historyMode);
  }
  setup.restorable = true;
  renderTrainingSetup();
  if (focus) {
    restoreOverlayFocus(
      document.getElementById(setup.focusID) || elements.closeTrainingSetupButton
    );
  }
}

async function openTrainingSetupDialog(prefill = null, {
  historyMode = "pushTrainingSetup",
  baseLevel = null,
  focus = true,
  historyContext = null,
} = {}) {
  if (currentActiveTrainingActivity()) {
    toast("当前已有个人模型训练正在运行；完成或取消后再新建任务");
    return;
  }
  const setup = state.training.setup;
  if (elements.trainingSetupDialog.open || setup.opening) return;
  setup.opening = true;
  setup.loading = true;
  setup.launching = false;
  setup.snapshot = null;
  setup.error = "";
  setup.notice = "";
  setup.operationID = null;
  setup.returnFocus = prefill?.returnFocus
    || (historyContext ? elements.newTrainingButton : document.activeElement);
  const generation = ++setup.requestGeneration;
  try {
    presentTrainingSetupDialog({ historyMode, baseLevel, focus });
  } finally {
    setup.opening = false;
  }
  try {
    const query = new URLSearchParams({ mediaKind: state.training.mediaKind });
    const snapshot = await api(`/v1/training/setup?${query}`);
    if (generation !== setup.requestGeneration) return;
    setup.snapshot = snapshot;
    if (historyContext) {
      applyTrainingSetupHistoryContext(historyContext);
    } else {
      resetTrainingSetupSelection(chooseInitialTrainingSetupMethod());
      applyTrainingSetupPrefill(prefill);
    }
  } catch (error) {
    if (generation === setup.requestGeneration) {
      setup.error = error.message || "训练设置载入失败";
    }
  } finally {
    if (generation === setup.requestGeneration) {
      setup.loading = false;
      if (elements.trainingSetupDialog.open) {
        renderTrainingSetup();
        if (historyContext && setup.snapshot) {
          await restoreTrainingSetupScrollFromHistory(historyContext);
        }
        if (!historyContext) checkpointActiveWorkspaceHistory();
      }
    }
  }
}

function openTrainingSetupForRun(runID) {
  const run = state.training.runs.find((item) => item.id === runID);
  if (!run) return;
  const recovery = run.recoveryContext;
  const tagIDs = recovery?.tagIDs?.length
    ? recovery.tagIDs
    : (run.tagID ? [run.tagID] : []);
  openTrainingSetupDialog({
    method: run.method,
    tagIDs,
    requireExplicitTag: !tagIDs.length,
    sourceIDs: recovery?.sourceIDs || [],
    sourceScope: recovery?.scope || "unresolved",
    note: recovery?.note || "这条旧记录只能恢复训练方法；请重新确认标签和范围。",
  });
}

function closeTrainingSetupDialog({
  restoreFocus = true,
  checkpoint = true,
  preserveState = false,
} = {}) {
  if (!elements.trainingSetupDialog.open) return;
  const setup = state.training.setup;
  const active = document.activeElement;
  if (active instanceof HTMLElement && elements.trainingSetupDialog.contains(active) && active.id) {
    setup.focusID = active.id;
  }
  const baseLevel = setup.baseLevel;
  const returnFocus = setup.returnFocus;
  elements.trainingSetupDialog.close();
  if (restoreFocus) {
    restoreOverlayFocus(stableReturnFocusTarget(returnFocus, elements.newTrainingButton));
  }
  if (checkpoint) replaceTrainingSetupHistoryWithBase(baseLevel);
  if (!preserveState) clearTrainingSetupDialogState();
}

function returnFromTrainingSetup({ restoreFocus = true } = {}) {
  if (!elements.trainingSetupDialog.open) return Promise.resolve();
  const setup = state.training.setup;
  setup.historyRestoreFocus = restoreFocus;
  if (state.workspaceNavigation.pendingReturnPromise) {
    return state.workspaceNavigation.pendingReturnPromise;
  }
  const current = activeWorkspaceHistoryEntry();
  if (state.workspaceNavigation.initialized
    && current?.route === visibleWorkspaceRoute()
    && current.navigationLevel === "trainingSetup") {
    const pending = new Promise((resolve) => {
      state.workspaceNavigation.pendingReturnResolve = resolve;
    });
    state.workspaceNavigation.pendingReturnPromise = pending;
    history.back();
    return pending;
  }
  closeTrainingSetupDialog({ restoreFocus });
  setup.historyRestoreFocus = true;
  return Promise.resolve();
}

async function reconcileTrainingSetupFromWorkspaceHistory(route, navigationLevel, context = {}) {
  const shouldOpen = navigationLevel === "trainingSetup"
    && route === visibleWorkspaceRoute();
  const setup = state.training.setup;
  if (shouldOpen && Boolean(currentActiveTrainingActivity()) && !setup.launching) {
    clearTrainingSetupDialogState();
    replaceTrainingSetupHistoryWithBase(trainingSetupBaseLevelFromHistory(context));
    return false;
  }
  if (shouldOpen && !setup.restorable) {
    clearTrainingSetupDialogState();
    await openTrainingSetupDialog(null, {
      historyMode: "none",
      baseLevel: trainingSetupBaseLevelFromHistory(context),
      focus: false,
      historyContext: context,
    });
    return Boolean(setup.snapshot);
  }
  if (shouldOpen && !elements.trainingSetupDialog.open) {
    presentTrainingSetupDialog({
      historyMode: "none",
      baseLevel: trainingSetupBaseLevelFromHistory(context),
    });
  } else if (!shouldOpen && elements.trainingSetupDialog.open) {
    const restoreFocus = setup.historyRestoreFocus;
    closeTrainingSetupDialog({
      restoreFocus,
      checkpoint: false,
      preserveState: true,
    });
    setup.historyRestoreFocus = true;
  }
  return false;
}

async function submitTrainingSetup() {
  const setup = state.training.setup;
  if (!canLaunchTrainingSetup()) return;
  setup.launching = true;
  setup.error = "";
  setup.operationID ||= crypto.randomUUID();
  renderTrainingSetup();
  const assetIDs = setup.method !== "featureKnn" && setup.scope === "currentSelection"
    ? [...state.selectedAssetIDs]
    : [];
  try {
    const result = await api("/v1/training/launch", {
      method: "POST",
      body: JSON.stringify({
        operationID: setup.operationID,
        mediaKind: state.training.mediaKind,
        method: setup.method,
        tagIDs: [...setup.selectedTagIDs],
        sourceIDs: setup.method === "featureKnn" ? [...setup.selectedSourceIDs] : [],
        assetIDs,
      }),
    });
    const copy = trainingSetupMethodCopy(result.method);
    const returnFocus = setup.returnFocus;
    await returnFromTrainingSetup({ restoreFocus: false });
    clearTrainingSetupDialogState({ cancelRequest: false });
    toast(`${copy.title}已交给 Mac · ${result.scheduledTagCount} 个标签`);
    restoreOverlayFocus(stableReturnFocusTarget(returnFocus, elements.newTrainingButton));
    await Promise.all([
      loadTrainingWorkspace({ quiet: true }),
      loadTrainingActivities({ quiet: true }),
    ]);
  } catch (error) {
    setup.error = error.message || "训练任务创建失败";
    setup.launching = false;
    renderTrainingSetup();
  }
}

function trainingMethodPresentation(method, mediaKind = state.training.mediaKind) {
  const noun = mediaKind === "video" ? "视频" : "照片";
  return {
    featureKnn: { title: `相似${noun}`, technical: "Feature Print k-NN" },
    personalCentroid: { title: "快速个人模型", technical: "Personal Centroid" },
    personalAdamW: { title: "增强个人模型", technical: "Personal AdamW" },
  }[method] || { title: "训练任务", technical: method || "—" };
}

function trainingStateText(value) {
  return {
    queued: "等待中",
    running: "训练中",
    succeeded: "已完成",
    failed: "失败",
    cancelled: "已取消",
  }[value] || value || "未知";
}

function trainingDate(milliseconds) {
  if (!Number.isFinite(milliseconds)) return "—";
  return new Intl.DateTimeFormat("zh-CN", {
    dateStyle: "medium",
    timeStyle: "short",
  }).format(new Date(milliseconds));
}

function prettyTrainingJSON(value, fallback) {
  if (!value) return fallback;
  try {
    return JSON.stringify(JSON.parse(value), null, 2);
  } catch {
    return fallback;
  }
}

function trainingMetricsSummary(value) {
  if (!value) return "当前记录没有可概括的评估口径。";
  try {
    const metrics = JSON.parse(value);
    const trainCount = Number(metrics.trainSampleCount || 0);
    const validationCount = Number(metrics.validationSampleCount || 0);
    if (metrics.evaluationSplit === "validation") {
      return `评估口径：验证集 · 训练样本 ${trainCount} · 验证样本 ${validationCount}`;
    }
    if (metrics.evaluationSplit === "trainFallback") {
      return `评估口径：训练集回退（样本不足，未建立验证集）· 训练样本 ${trainCount}`;
    }
    if (metrics.evaluationSplit) return `评估口径：${metrics.evaluationSplit}`;
    if ("validationLoss" in metrics || "bestValidationLoss" in metrics) {
      return "历史指标：评估切分未记录，不能把该 loss 判定为验证损失。";
    }
  } catch {
    // Host already sanitized the projection; malformed historical JSON is shown as absent.
  }
  return "当前记录没有可概括的评估口径。";
}

function trainingMetricCurve(value) {
  if (!value) return [];
  try {
    const metrics = JSON.parse(value);
    if (!Array.isArray(metrics.epochs)) return [];
    const lossByEpoch = new Map();
    for (const item of metrics.epochs) {
      const epoch = item?.epoch;
      const loss = item?.evaluationLoss ?? item?.validationLoss;
      if (!Number.isInteger(epoch) || epoch <= 0 || !Number.isFinite(loss) || loss < 0) {
        continue;
      }
      lossByEpoch.set(epoch, loss);
    }
    return [...lossByEpoch]
      .map(([epoch, loss]) => ({ epoch, loss }))
      .sort((left, right) => left.epoch - right.epoch);
  } catch {
    return [];
  }
}

function formatTrainingLoss(value) {
  if (!Number.isFinite(value)) return "—";
  return new Intl.NumberFormat("zh-CN", {
    minimumSignificantDigits: 3,
    maximumSignificantDigits: 5,
  }).format(value);
}

function createTrainingChartElement(name, attributes = {}) {
  const element = document.createElementNS("http://www.w3.org/2000/svg", name);
  for (const [key, value] of Object.entries(attributes)) {
    element.setAttribute(key, String(value));
  }
  return element;
}

function syncTrainingChartElement(container, key, name, attributes = {}) {
  let element = container.querySelector(
    `:scope > [data-training-chart-part="${CSS.escape(key)}"]`
  );
  if (element && element.localName !== name) {
    element.remove();
    element = null;
  }
  if (!element) {
    element = createTrainingChartElement(name);
    element.dataset.trainingChartPart = key;
  }
  for (const [attribute, value] of Object.entries(attributes)) {
    const text = String(value);
    if (element.getAttribute(attribute) !== text) element.setAttribute(attribute, text);
  }
  return element;
}

function trainingMetricChartMarks() {
  return [...elements.trainingLossChart.querySelectorAll("[data-metric-epoch]")];
}

function syncTrainingMetricPointSelection(mark) {
  if (!mark) return;
  const marks = trainingMetricChartMarks();
  if (!marks.includes(mark)) return;
  for (const candidate of marks) {
    candidate.dataset.current = String(candidate === mark);
  }
  elements.trainingLossChart.dataset.activeMetricEpoch = mark.dataset.metricEpoch;
  const focusRule = elements.trainingLossChart.querySelector(
    '[data-training-chart-part="focus-rule"]'
  );
  const x = mark.getAttribute("cx");
  if (focusRule && x != null) {
    focusRule.setAttribute("x1", x);
    focusRule.setAttribute("x2", x);
  }
  const status = mark.dataset.metricStatus || "聚焦曲线后可查看每轮精确损失";
  if (elements.trainingMetricPointStatus.textContent !== status) {
    elements.trainingMetricPointStatus.textContent = status;
  }
}

function moveTrainingMetricPoint(event) {
  if (event.altKey || event.ctrlKey || event.metaKey || event.shiftKey) return;
  if (!["ArrowLeft", "ArrowRight", "PageUp", "PageDown", "Home", "End"]
    .includes(event.key)) return;
  const marks = trainingMetricChartMarks();
  if (!marks.length) return;
  const currentIndex = Math.max(0, marks.findIndex(
    (mark) => mark.dataset.metricEpoch === elements.trainingLossChart.dataset.activeMetricEpoch
  ));
  const pageStep = Math.max(1, Math.ceil(marks.length / 6));
  let nextIndex = currentIndex;
  if (event.key === "Home") nextIndex = 0;
  else if (event.key === "End") nextIndex = marks.length - 1;
  else if (event.key === "PageUp") nextIndex -= pageStep;
  else if (event.key === "PageDown") nextIndex += pageStep;
  else nextIndex += event.key === "ArrowLeft" ? -1 : 1;
  event.preventDefault();
  event.stopPropagation();
  syncTrainingMetricPointSelection(
    marks[Math.max(0, Math.min(marks.length - 1, nextIndex))]
  );
}

function nearestTrainingMetricMark(clientX) {
  return trainingMetricChartMarks().reduce((nearest, mark) => {
    const rect = mark.getBoundingClientRect();
    const distance = Math.abs(clientX - (rect.left + rect.width / 2));
    return !nearest || distance < nearest.distance ? { mark, distance } : nearest;
  }, null)?.mark || null;
}

function trainingMetricPointStatus(point, index, count, bestMetric, latestMetric) {
  const parts = [
    `第 ${point.epoch} 轮`,
    `评估损失 ${formatTrainingLoss(point.loss)}`,
  ];
  if (point.epoch === bestMetric.epoch && point.loss === bestMetric.loss) parts.push("最佳");
  if (point.epoch === latestMetric.epoch && point.loss === latestMetric.loss) parts.push("最终");
  parts.push(`第 ${index + 1} 项，共 ${count} 项`);
  return parts.join(" · ");
}

function renderTrainingLossChart(points, bestMetric, latestMetric, activeEpoch = null) {
  const width = 720;
  const height = 230;
  const margin = { top: 18, right: 22, bottom: 42, left: 58 };
  const plotWidth = width - margin.left - margin.right;
  const plotHeight = height - margin.top - margin.bottom;
  const firstEpoch = points[0].epoch;
  const lastEpoch = points.at(-1).epoch;
  const losses = points.map((point) => point.loss);
  const minimumLoss = Math.min(...losses);
  const maximumLoss = Math.max(...losses);
  const rawRange = maximumLoss - minimumLoss;
  const padding = rawRange > 0 ? rawRange * 0.12 : Math.max(maximumLoss * 0.08, 0.01);
  const domainMinimum = Math.max(0, minimumLoss - padding);
  const domainMaximum = maximumLoss + padding;
  const domainRange = Math.max(domainMaximum - domainMinimum, Number.EPSILON);
  const x = (epoch) => margin.left + (lastEpoch === firstEpoch
    ? plotWidth / 2
    : ((epoch - firstEpoch) / (lastEpoch - firstEpoch)) * plotWidth);
  const y = (loss) => margin.top
    + ((domainMaximum - loss) / domainRange) * plotHeight;
  const activeMetric = points.find((point) => point.epoch === activeEpoch) || bestMetric;

  const svg = syncTrainingChartElement(elements.trainingLossChart, "svg", "svg", {
    viewBox: `0 0 ${width} ${height}`,
    preserveAspectRatio: "xMidYMid meet",
    "aria-hidden": "true",
  });
  const chartParts = [];
  const yTicks = 5;
  for (let index = 0; index < yTicks; index += 1) {
    const ratio = index / (yTicks - 1);
    const loss = domainMaximum - ratio * domainRange;
    const position = margin.top + ratio * plotHeight;
    chartParts.push(syncTrainingChartElement(svg, `y-grid-${index}`, "line", {
      class: "training-chart-grid-line",
      x1: margin.left,
      x2: width - margin.right,
      y1: position,
      y2: position,
    }));
    const label = syncTrainingChartElement(svg, `y-label-${index}`, "text", {
      class: "training-chart-axis-value",
      x: margin.left - 9,
      y: position + 3,
      "text-anchor": "end",
    });
    const labelText = formatTrainingLoss(loss);
    if (label.textContent !== labelText) label.textContent = labelText;
    chartParts.push(label);
  }

  const desiredXTicks = Math.min(6, points.length);
  const tickEpochs = new Set();
  for (let index = 0; index < desiredXTicks; index += 1) {
    const ratio = desiredXTicks === 1 ? 0 : index / (desiredXTicks - 1);
    tickEpochs.add(Math.round(firstEpoch + ratio * (lastEpoch - firstEpoch)));
  }
  for (const epoch of [...tickEpochs].sort((left, right) => left - right)) {
    const position = x(epoch);
    chartParts.push(syncTrainingChartElement(svg, `x-tick-${epoch}`, "line", {
      class: "training-chart-axis-tick",
      x1: position,
      x2: position,
      y1: height - margin.bottom,
      y2: height - margin.bottom + 5,
    }));
    const label = syncTrainingChartElement(svg, `x-label-${epoch}`, "text", {
      class: "training-chart-axis-value",
      x: position,
      y: height - margin.bottom + 18,
      "text-anchor": "middle",
    });
    const labelText = String(epoch);
    if (label.textContent !== labelText) label.textContent = labelText;
    chartParts.push(label);
  }

  chartParts.push(syncTrainingChartElement(svg, "best-rule", "line", {
    class: "training-chart-best-rule",
    x1: margin.left,
    x2: width - margin.right,
    y1: y(bestMetric.loss),
    y2: y(bestMetric.loss),
  }));
  chartParts.push(syncTrainingChartElement(svg, "focus-rule", "line", {
    class: "training-chart-focus-rule",
    x1: x(activeMetric.epoch),
    x2: x(activeMetric.epoch),
    y1: margin.top,
    y2: height - margin.bottom,
  }));
  chartParts.push(syncTrainingChartElement(svg, "loss-line", "polyline", {
    class: "training-chart-loss-line",
    points: points.map((point) => `${x(point.epoch)},${y(point.loss)}`).join(" "),
  }));
  for (const [index, point] of points.entries()) {
    const best = point.epoch === bestMetric.epoch && point.loss === bestMetric.loss;
    const current = point.epoch === activeMetric.epoch;
    const mark = syncTrainingChartElement(svg, `point-${point.epoch}`, "circle", {
      class: best ? "training-chart-point best" : "training-chart-point",
      cx: x(point.epoch),
      cy: y(point.loss),
      r: best ? 5 : 3.5,
      "data-metric-epoch": point.epoch,
      "data-metric-loss": point.loss,
      "data-metric-status": trainingMetricPointStatus(
        point,
        index,
        points.length,
        bestMetric,
        latestMetric
      ),
      "data-best": String(best),
      "data-current": String(current),
    });
    let title = mark.querySelector(":scope > title");
    if (!title) title = createTrainingChartElement("title");
    const titleText = `第 ${point.epoch} 轮 · ${formatTrainingLoss(point.loss)}${best ? " · 最佳" : ""}`;
    if (title.textContent !== titleText) title.textContent = titleText;
    reconcileStableChildren(mark, [title]);
    chartParts.push(mark);
  }

  const xAxisTitle = syncTrainingChartElement(svg, "x-axis-title", "text", {
    class: "training-chart-axis-title",
    x: margin.left + plotWidth / 2,
    y: height - 4,
    "text-anchor": "middle",
  });
  if (xAxisTitle.textContent !== "训练轮次") xAxisTitle.textContent = "训练轮次";
  chartParts.push(xAxisTitle);
  const yAxisTitle = syncTrainingChartElement(svg, "y-axis-title", "text", {
    class: "training-chart-axis-title",
    x: 13,
    y: margin.top + plotHeight / 2,
    transform: `rotate(-90 13 ${margin.top + plotHeight / 2})`,
    "text-anchor": "middle",
  });
  if (yAxisTitle.textContent !== "评估损失") yAxisTitle.textContent = "评估损失";
  chartParts.push(yAxisTitle);
  reconcileStableChildren(svg, chartParts);
  reconcileStableChildren(elements.trainingLossChart, [svg]);
  elements.trainingLossChart.setAttribute(
    "aria-label",
    `训练损失曲线：${points.length} 轮，最佳损失 ${formatTrainingLoss(bestMetric.loss)}`
      + `（第 ${bestMetric.epoch} 轮），最终损失 ${formatTrainingLoss(latestMetric.loss)}`
  );
  syncTrainingMetricPointSelection(
    elements.trainingLossChart.querySelector(
      `[data-metric-epoch="${CSS.escape(String(activeMetric.epoch))}"]`
    )
  );
}

function renderTrainingMetrics(value, runID = "") {
  const runKey = runID || "";
  const fingerprint = `${runKey}\n${value || ""}`;
  if (elements.trainingLossChart.dataset.trainingMetricsFingerprint === fingerprint) return;
  const runChanged = elements.trainingLossChart.dataset.trainingMetricRunId !== runKey;
  elements.trainingLossChart.dataset.trainingMetricsFingerprint = fingerprint;
  elements.trainingLossChart.dataset.trainingMetricRunId = runKey;
  if (runChanged) delete elements.trainingLossChart.dataset.activeMetricEpoch;
  const summary = trainingMetricsSummary(value);
  if (elements.trainingMetricsSummary.textContent !== summary) {
    elements.trainingMetricsSummary.textContent = summary;
  }
  const metricsJSON = prettyTrainingJSON(value, "没有过程指标");
  if (elements.trainingMetricsJSON.textContent !== metricsJSON) {
    elements.trainingMetricsJSON.textContent = metricsJSON;
  }
  const points = trainingMetricCurve(value);
  const hasCurve = points.length > 0;
  elements.trainingMetricHighlights.classList.toggle("hidden", !hasCurve);
  elements.trainingLossChart.classList.toggle("hidden", !hasCurve);
  elements.trainingMetricPointStatus.classList.toggle("hidden", !hasCurve);
  elements.trainingMetricEmpty.classList.toggle("hidden", hasCurve);
  if (!hasCurve) {
    elements.trainingLossChart.tabIndex = -1;
    delete elements.trainingLossChart.dataset.activeMetricEpoch;
    reconcileStableChildren(elements.trainingMetricHighlights, []);
    reconcileStableChildren(elements.trainingLossChart, []);
    elements.trainingLossChart.setAttribute("aria-label", "训练损失曲线：没有可绘制的数据");
    elements.trainingMetricPointStatus.textContent = "聚焦曲线后可查看每轮精确损失";
    return;
  }
  elements.trainingLossChart.tabIndex = 0;
  const bestMetric = points.reduce((best, point) => (
    point.loss < best.loss || (point.loss === best.loss && point.epoch < best.epoch)
      ? point
      : best
  ));
  const latestMetric = points.at(-1);
  const highlights = [
    { key: "epochs", icon: "↻", title: "训练轮次", value: String(points.length) },
    { key: "best", icon: "↓", title: "最佳损失", value: formatTrainingLoss(bestMetric.loss) },
    { key: "latest", icon: "⚑", title: "最终损失", value: formatTrainingLoss(latestMetric.loss) },
  ];
  const existingHighlights = new Map(
    [...elements.trainingMetricHighlights.querySelectorAll(
      ":scope > [data-training-metric-key]"
    )].map((card) => [card.dataset.trainingMetricKey, card])
  );
  const highlightCards = [];
  for (const metric of highlights) {
    const card = existingHighlights.get(metric.key) || document.createElement("div");
    existingHighlights.delete(metric.key);
    card.dataset.trainingMetricKey = metric.key;
    card.className = "training-metric-highlight";
    let icon = card.querySelector(':scope > [data-training-metric-part="icon"]');
    if (!icon) {
      icon = document.createElement("span");
      icon.dataset.trainingMetricPart = "icon";
    }
    icon.className = "training-metric-highlight-icon";
    icon.setAttribute("aria-hidden", "true");
    if (icon.textContent !== metric.icon) icon.textContent = metric.icon;
    let copy = card.querySelector(':scope > [data-training-metric-part="copy"]');
    if (!copy) {
      copy = document.createElement("span");
      copy.dataset.trainingMetricPart = "copy";
    }
    let title = copy.querySelector(':scope > [data-training-metric-copy-part="title"]');
    if (!title) {
      title = document.createElement("small");
      title.dataset.trainingMetricCopyPart = "title";
    }
    if (title.textContent !== metric.title) title.textContent = metric.title;
    let valueText = copy.querySelector(':scope > [data-training-metric-copy-part="value"]');
    if (!valueText) {
      valueText = document.createElement("strong");
      valueText.dataset.trainingMetricCopyPart = "value";
    }
    if (valueText.textContent !== metric.value) valueText.textContent = metric.value;
    reconcileStableChildren(copy, [title, valueText]);
    reconcileStableChildren(card, [icon, copy]);
    highlightCards.push(card);
  }
  reconcileStableChildren(elements.trainingMetricHighlights, highlightCards);
  renderTrainingLossChart(
    points,
    bestMetric,
    latestMetric,
    Number(elements.trainingLossChart.dataset.activeMetricEpoch)
  );
}

function reconcileTrainingFacts(container, facts) {
  const existing = new Map(
    [...container.querySelectorAll(":scope > [data-training-fact-key]")]
      .map((wrapper) => [wrapper.dataset.trainingFactKey, wrapper])
  );
  const wanted = facts.map((fact) => {
    const wrapper = existing.get(fact.key) || document.createElement("div");
    existing.delete(fact.key);
    if (!wrapper.hasAttribute("data-training-fact-key")) {
      wrapper.append(document.createElement("dt"), document.createElement("dd"));
    }
    wrapper.dataset.trainingFactKey = fact.key;
    wrapper.className = fact.className || "training-fact";
    const term = wrapper.querySelector(":scope > dt");
    const description = wrapper.querySelector(":scope > dd");
    if (term.textContent !== fact.label) term.textContent = fact.label;
    const value = fact.value || "—";
    if (description.textContent !== value) description.textContent = value;
    return wrapper;
  });
  reconcileStableChildren(container, wanted);
}

function isActiveTrainingActivity(activity) {
  return !["completed", "failed", "cancelled"].includes(activity?.phase);
}

function currentActiveTrainingActivity() {
  return (state.training.activities || []).find(isActiveTrainingActivity) || null;
}

function isRecentTrainingActivity(activity) {
  const updatedAtMs = Number(activity?.updatedAtMs || 0);
  return updatedAtMs > 0 && Date.now() - updatedAtMs < 15_000;
}

function trainingBatchCounts(activity) {
  const tags = activity?.tagActivities || [];
  return {
    succeeded: tags.filter((tag) => tag.phase === "succeeded").length,
    skipped: tags.filter((tag) => tag.phase === "skipped").length,
    failed: tags.filter((tag) => tag.phase === "failed").length,
    cancelled: tags.filter((tag) => tag.phase === "cancelled").length,
    pending: tags.filter((tag) => !["succeeded", "skipped", "failed", "cancelled"]
      .includes(tag.phase)).length,
  };
}

function trainingBatchPresentation(activity) {
  const counts = trainingBatchCounts(activity);
  if (isActiveTrainingActivity(activity)) {
    return { label: "进行中", className: "running", counts };
  }
  if (activity.phase === "cancelled") {
    return { label: "已取消", className: "cancelled", counts };
  }
  if (activity.phase === "failed") {
    const interrupted = activity.errorCode === "hostRestartInterrupted";
    return {
      label: interrupted ? "被 App 重启中断" : "未完成",
      className: "failed",
      counts,
    };
  }
  if (counts.failed || counts.skipped || counts.cancelled || counts.pending) {
    return { label: "部分完成", className: "partial", counts };
  }
  return { label: "全部完成", className: "completed", counts };
}

function trainingRunBatchID(run) {
  if (run?.batchID) return run.batchID;
  try {
    return JSON.parse(run?.sampleSummaryJSON || "{}").batchID || null;
  } catch {
    return null;
  }
}

function isBatchTrainingRun(run) {
  return Boolean(trainingRunBatchID(run));
}

function visibleTrainingRuns() {
  if (state.training.runScope === "batch") {
    return state.training.runs.filter(isBatchTrainingRun);
  }
  if (state.training.runScope === "single") {
    return state.training.runs.filter((run) => !isBatchTrainingRun(run));
  }
  return state.training.runs;
}

function trainingRunListContextKey() {
  return [
    state.training.mediaKind,
    state.training.method || "all-methods",
    state.training.runScope,
  ].join(":");
}

function captureTrainingRunListScroll() {
  const contextKey = state.training.renderedRunListContextKey;
  if (!contextKey) return;
  state.training.runListScrollOffsets.set(
    contextKey,
    elements.trainingRunPane.scrollTop
  );
}

function restoreTrainingRunListScroll(contextKey) {
  elements.trainingRunPane.scrollTop = state.training.runListScrollOffsets.get(contextKey) || 0;
  state.training.renderedRunListContextKey = contextKey;
}

function resetTrainingDetailScroll() {
  elements.trainingDetailPane.scrollTop = 0;
}

function trainingRunTagName(run) {
  if (run?.tagDisplayName) return run.tagDisplayName;
  const current = run?.tagID ? tagByID(run.tagID)?.displayName : null;
  if (current) return current;
  return run?.tagID ? `历史标签 ${run.tagID.slice(0, 8)}` : "未关联标签";
}

function trainingRunBatchPosition(run) {
  if (!isBatchTrainingRun(run)) return null;
  const index = run.batchTagIndex == null ? Number.NaN : Number(run.batchTagIndex);
  const count = run.batchTagCount == null ? Number.NaN : Number(run.batchTagCount);
  if (Number.isInteger(index) && index >= 0 && Number.isInteger(count) && count > 0) {
    return `${Math.min(index + 1, count)} / ${count}`;
  }
  return "批次成员";
}

function trainingRunDuration(run) {
  const startedAtMs = run?.startedAtMs == null ? Number.NaN : Number(run.startedAtMs);
  const endAtMs = Number(run?.finishedAtMs ?? Date.now());
  if (!Number.isFinite(startedAtMs) || !Number.isFinite(endAtMs) || endAtMs < startedAtMs) {
    return null;
  }
  const seconds = Math.max(0, Math.round((endAtMs - startedAtMs) / 1000));
  if (seconds < 60) return `${seconds} 秒`;
  const minutes = Math.floor(seconds / 60);
  const remainder = seconds % 60;
  return remainder ? `${minutes} 分 ${remainder} 秒` : `${minutes} 分钟`;
}

function trainingRunScopeText(run) {
  const scope = run?.recoveryContext?.scope;
  if (scope === "allSources") return "所有可用来源";
  if (scope === "selectedSources") {
    const count = run.recoveryContext?.sourceIDs?.length || 0;
    return count ? `${count} 个选定来源` : "选定来源";
  }
  if (scope === "selectedAssets") return "当时选择的媒体";
  if (scope === "unresolved") return "历史范围未保存";
  return "训练时目录快照";
}

function setTrainingRunScope(scope, { focus = false } = {}) {
  if (!["all", "batch", "single"].includes(scope)) return;
  const previousRunID = state.training.selectedRunID;
  state.training.runScope = scope;
  const visible = visibleTrainingRuns();
  if (!visible.some((run) => run.id === state.training.selectedRunID)) {
    state.training.selectedRunID = visible[0]?.id || null;
  }
  if (state.training.selectedRunID !== previousRunID) resetTrainingDetailScroll();
  renderTrainingWorkspace();
  checkpointActiveWorkspaceHistory();
  if (focus) focusTrainingRun(state.training.selectedRunID, { reveal: true });
}

function cycleTrainingRunScope() {
  const scopes = ["all", "batch", "single"];
  const index = scopes.indexOf(state.training.runScope);
  setTrainingRunScope(scopes[(index + 1) % scopes.length], { focus: true });
}

function syncTrainingBatchTags(container, tagActivities) {
  const visibleTags = (tagActivities || []).slice(0, 8);
  const existing = new Map(
    [...container.querySelectorAll(":scope > [data-training-batch-tag-id]")]
      .map((chip) => [chip.dataset.trainingBatchTagId, chip])
  );
  const wanted = visibleTags.map((tag) => {
    const chip = existing.get(tag.tagID) || document.createElement("span");
    chip.dataset.trainingBatchTagId = tag.tagID;
    chip.className = tag.phase;
    const name = tag.displayName || tag.tagID.slice(0, 8);
    if (chip.textContent !== name) chip.textContent = name;
    chip.title = `${name} · ${tag.phase}`;
    return chip;
  });
  if ((tagActivities || []).length > 8) {
    const more = container.querySelector(":scope > [data-training-batch-tag-overflow]")
      || document.createElement("span");
    more.dataset.trainingBatchTagOverflow = "true";
    const label = `＋${tagActivities.length - 8}`;
    if (more.textContent !== label) more.textContent = label;
    wanted.push(more);
  }
  reconcileStableChildren(container, wanted);
}

function syncTrainingBatchCard(card, activity) {
  const presentation = trainingBatchPresentation(activity);
  const method = trainingMethodPresentation(activity.method, activity.mediaKind);
  const hasRun = state.training.runs.some(
    (run) => trainingRunBatchID(run) === activity.operationID
  );
  const fingerprint = JSON.stringify({ activity, hasRun });
  if (card.dataset.trainingFingerprint === fingerprint) return;
  card.className = `training-batch-card ${presentation.className}`;
  card.dataset.trainingBatchId = activity.operationID;
  let heading = card.querySelector(":scope > header");
  if (!heading) {
    heading = document.createElement("header");
    const copy = document.createElement("div");
    const title = document.createElement("strong");
    const date = document.createElement("span");
    date.className = "secondary";
    copy.append(title, date);
    const status = document.createElement("span");
    heading.append(copy, status);
    const summary = document.createElement("p");
    const tags = document.createElement("div");
    tags.className = "training-batch-tags";
    const actions = document.createElement("footer");
    card.append(heading, summary, tags, actions);
  }
  const title = heading.querySelector("strong");
  const date = heading.querySelector(".secondary");
  const status = heading.querySelector(":scope > .training-batch-state, :scope > span");
  title.textContent = method.title;
  date.textContent = trainingDate(Number(activity.acceptedAtMs || activity.updatedAtMs));
  status.className = `training-batch-state ${presentation.className}`;
  status.textContent = presentation.label;

  const summary = card.querySelector(":scope > p");
  const countParts = [
    presentation.counts.succeeded ? `完成 ${presentation.counts.succeeded}` : "",
    presentation.counts.skipped ? `跳过 ${presentation.counts.skipped}` : "",
    presentation.counts.failed ? `失败 ${presentation.counts.failed}` : "",
    presentation.counts.cancelled ? `取消 ${presentation.counts.cancelled}` : "",
    presentation.counts.pending ? `处理中 ${presentation.counts.pending}` : "",
  ].filter(Boolean);
  summary.textContent = countParts.join(" · ") || `${activity.totalUnitCount || 0} 个标签`;

  const tags = card.querySelector(":scope > .training-batch-tags");
  syncTrainingBatchTags(tags, activity.tagActivities || []);

  const actions = card.querySelector(":scope > footer");
  const retainedActions = new Set();
  if (hasRun) {
    const view = actions.querySelector(
      `:scope > [data-training-batch-view-id="${CSS.escape(activity.operationID)}"]`
    ) || document.createElement("button");
    view.type = "button";
    view.className = "button button-compact";
    view.dataset.trainingBatchViewId = activity.operationID;
    view.textContent = "查看 Run";
    configurePersistentHelp(view, {
      title: "查看批次 Run",
      detail: "定位到这个批次已经生成的训练记录；不会重新运行或改变模型发布状态。",
      kind: "training",
    });
    retainedActions.add(view);
    if (!actions.contains(view)) actions.append(view);
  }
  const unfinished = (activity.tagActivities || []).some((tag) => tag.phase !== "succeeded");
  if (!isActiveTrainingActivity(activity) && unfinished) {
    const retry = actions.querySelector(
      `:scope > [data-training-batch-reconfigure-id="${CSS.escape(activity.operationID)}"]`
    ) || document.createElement("button");
    retry.type = "button";
    retry.className = "button button-compact button-primary";
    retry.dataset.trainingBatchReconfigureId = activity.operationID;
    retry.textContent = "重新处理未完成标签";
    configurePersistentHelp(retry, {
      title: "重新处理未完成标签",
      detail: "只把失败、跳过、取消或未开始的标签带回训练设置；已经成功发布的标签保持不变。",
      kind: "training",
    });
    retainedActions.add(retry);
    if (!actions.contains(retry)) actions.append(retry);
  }
  for (const button of actions.querySelectorAll(":scope > button")) {
    if (!retainedActions.has(button)) button.remove();
  }
  card.dataset.trainingFingerprint = fingerprint;
}

function renderTrainingBatchHistory() {
  const batches = (state.training.activities || [])
    .filter((activity) =>
      ["personalCentroid", "personalAdamW"].includes(activity.method)
      && (!state.training.method || activity.method === state.training.method)
    )
    .sort((lhs, rhs) => Number(rhs.updatedAtMs || 0) - Number(lhs.updatedAtMs || 0))
    .slice(0, 12);
  elements.trainingBatchHistory.classList.toggle("hidden", batches.length === 0);
  elements.trainingBatchCount.textContent = String(batches.length);
  const existingCards = new Map(
    [...elements.trainingBatchList.querySelectorAll("[data-training-batch-id]")]
      .map((card) => [card.dataset.trainingBatchId, card])
  );
  for (const [index, activity] of batches.entries()) {
    const card = existingCards.get(activity.operationID) || document.createElement("article");
    existingCards.delete(activity.operationID);
    syncTrainingBatchCard(card, activity);
    const currentCard = elements.trainingBatchList.children[index] || null;
    if (currentCard !== card) elements.trainingBatchList.insertBefore(card, currentCard);
  }
  for (const card of existingCards.values()) card.remove();
}

function syncTrainingTagActivityList(list, tagActivities) {
  const phaseCopy = {
    pending: "等待",
    preparingSamples: "准备样本",
    preparingEmbeddings: "准备特征",
    trainingAndPublishing: "训练发布",
    succeeded: "已完成",
    skipped: "已跳过",
    failed: "失败",
    cancelled: "已取消",
  };
  const existing = new Map(
    [...list.querySelectorAll(":scope > [data-training-tag-activity-id]")]
      .map((item) => [item.dataset.trainingTagActivityId, item])
  );
  const wanted = tagActivities.map((tag) => {
    const item = existing.get(tag.tagID) || document.createElement("li");
    item.dataset.trainingTagActivityId = tag.tagID;
    item.className = `training-tag-activity ${tag.phase}`;
    let mark = item.querySelector(":scope > .training-tag-activity-mark");
    if (!mark) {
      mark = document.createElement("span");
      mark.className = "training-tag-activity-mark";
      mark.setAttribute("aria-hidden", "true");
    }
    const name = item.querySelector(":scope > strong") || document.createElement("strong");
    const displayName = tag.displayName || tag.tagID.slice(0, 8);
    if (name.textContent !== displayName) name.textContent = displayName;
    const status = item.querySelector(":scope > span:not(.training-tag-activity-mark)")
      || document.createElement("span");
    const statusText = `${phaseCopy[tag.phase] || tag.phase}`
      + (tag.sampleCount ? ` · ${tag.sampleCount} 个样本` : "")
      + (tag.errorCode ? ` · ${tag.errorCode}` : "");
    if (status.textContent !== statusText) status.textContent = statusText;
    reconcileStableChildren(item, [mark, name, status]);
    return item;
  });
  reconcileStableChildren(list, wanted);
}

function renderTrainingActivities() {
  const activities = state.training.activities || [];
  const activity = activities.find(isActiveTrainingActivity)
    || activities.find(isRecentTrainingActivity);
  elements.trainingActivityStrip.classList.toggle("hidden", !activity);
  elements.trainingActivityStrip.classList.toggle("failed", activity?.phase === "failed");
  elements.trainingActivityStrip.classList.toggle("completed", activity?.phase === "completed");
  elements.trainingActivityStrip.classList.toggle("cancelled", activity?.phase === "cancelled");
  if (!activity) return;
  const operationChanged = elements.trainingActivityStrip.dataset.trainingActivityOperationId
    !== activity.operationID;
  if (operationChanged) {
    clearElement(elements.trainingActivityStrip);
    delete elements.trainingActivityStrip.dataset.trainingActivityOperationId;
  }
  const copy = trainingMethodPresentation(activity.method, activity.mediaKind);
  let summary = elements.trainingActivityStrip.querySelector(":scope > .training-activity-summary");
  if (!summary) {
    summary = document.createElement("div");
    summary.className = "training-activity-summary";
    const progress = document.createElement("span");
    progress.className = "training-activity-progress";
    const fill = document.createElement("span");
    progress.append(fill);
    const heading = document.createElement("strong");
    const detail = document.createElement("span");
    summary.append(progress, heading, detail);
    elements.trainingActivityStrip.append(summary);
  }
  const progress = summary.querySelector(":scope > .training-activity-progress");
  const fill = progress.querySelector(":scope > span");
  const heading = summary.querySelector(":scope > strong");
  const detail = summary.querySelector(":scope > span:not(.training-activity-progress)");
  const phaseText = {
    preparingSamples: "正在准备样本",
    preparingEmbeddings: "正在准备 AI 特征",
    trainingAndPublishing: "正在训练并发布模型",
    completed: "训练已完成",
    failed: "训练失败",
    cancelled: "训练已取消",
  }[activity.phase] || "训练处理中";
  heading.textContent = `${copy.title} · ${phaseText}`;
  const tagActivities = activity.tagActivities || [];
  const succeededCount = tagActivities.filter((tag) => tag.phase === "succeeded").length;
  const skippedCount = tagActivities.filter((tag) => tag.phase === "skipped").length;
  const failedCount = tagActivities.filter((tag) => tag.phase === "failed").length;
  const resultParts = [
    succeededCount ? `完成 ${succeededCount}` : "",
    skippedCount ? `跳过 ${skippedCount}` : "",
    failedCount ? `失败 ${failedCount}` : "",
  ].filter(Boolean);
  detail.textContent = `${activity.completedUnitCount} / ${activity.totalUnitCount} 个标签`
    + (activity.sampleCount ? ` · 当前 ${activity.sampleCount} 个样本` : "")
    + (resultParts.length ? ` · ${resultParts.join(" · ")}` : "")
    + (activity.phase === "failed" && activity.errorCode ? ` · ${activity.errorCode}` : "");
  const ratio = activity.phase === "completed"
    ? 1
    : Math.max(0.08, activity.completedUnitCount / Math.max(activity.totalUnitCount, 1));
  fill.style.width = `${Math.round(ratio * 100)}%`;
  const retainedActions = new Set();
  if (activity.availableActions?.includes("cancel")) {
    const cancel = summary.querySelector(
      `:scope > [data-training-activity-id="${CSS.escape(activity.operationID)}"][data-action="cancel"]`
    ) || document.createElement("button");
    cancel.type = "button";
    cancel.className = "button button-compact button-danger write-action";
    cancel.dataset.trainingActivityId = activity.operationID;
    cancel.dataset.action = "cancel";
    cancel.disabled = state.training.activityMutatingIDs.has(activity.operationID);
    cancel.textContent = cancel.disabled ? "正在取消…" : "取消训练";
    configurePersistentHelp(cancel, {
      title: "取消当前训练",
      detail: "Mac 会停止尚未完成的标签；已经训练并发布成功的标签继续保留。确认前不会提交取消请求。",
      kind: "training",
    });
    retainedActions.add(cancel);
    if (!summary.contains(cancel)) summary.append(cancel);
  }
  const unfinishedTags = tagActivities.filter(
    (tag) => !["succeeded"].includes(tag.phase)
  );
  if (["completed", "failed", "cancelled"].includes(activity.phase)
    && unfinishedTags.length) {
    const retry = summary.querySelector(
      `:scope > [data-training-batch-reconfigure-id="${CSS.escape(activity.operationID)}"]`
    ) || document.createElement("button");
    retry.type = "button";
    retry.className = "button button-compact button-primary";
    retry.dataset.trainingBatchReconfigureId = activity.operationID;
    retry.textContent = "重新处理未完成标签";
    configurePersistentHelp(retry, {
      title: "重新处理未完成标签",
      detail: "只回填这个批次中尚未成功的标签，保留已经完成的标签；提交前仍可调整范围。",
      kind: "training",
    });
    retainedActions.add(retry);
    if (!summary.contains(retry)) summary.append(retry);
  }
  for (const button of summary.querySelectorAll(":scope > button")) {
    if (!retainedActions.has(button)) button.remove();
  }

  if (tagActivities.length) {
    let list = elements.trainingActivityStrip.querySelector(
      ":scope > .training-tag-activity-list"
    );
    if (!list) {
      list = document.createElement("ol");
      list.className = "training-tag-activity-list";
      elements.trainingActivityStrip.append(list);
    }
    syncTrainingTagActivityList(list, tagActivities);
  } else {
    elements.trainingActivityStrip.querySelector(
      ":scope > .training-tag-activity-list"
    )?.remove();
  }
  elements.trainingActivityStrip.dataset.trainingActivityOperationId = activity.operationID;
}

function openTrainingSetupForActivity(operationID) {
  const activity = state.training.activities.find(
    (item) => item.operationID === operationID
  );
  if (!activity) return;
  const allTags = activity.tagActivities || [];
  const tagIDs = allTags
    .filter((tag) => tag.phase !== "succeeded")
    .map((tag) => tag.tagID);
  openTrainingSetupDialog({
    method: activity.method,
    tagIDs,
    requireExplicitTag: !tagIDs.length,
    note: tagIDs.length
      ? `已保留 ${allTags.length - tagIDs.length} 个完成标签，只重新选择 ${tagIDs.length} 个未完成标签。`
      : "这个批次没有未完成标签。",
  });
}

async function openTrainingRunForBatch(operationID) {
  let run = state.training.runs.find((item) => trainingRunBatchID(item) === operationID);
  if (!run) {
    const activity = state.training.activities.find(
      (item) => item.operationID === operationID
    );
    if (activity && state.training.method !== activity.method) {
      state.training.method = activity.method;
      state.training.selectedRunID = null;
      await loadTrainingWorkspace({ quiet: true });
      run = state.training.runs.find((item) => trainingRunBatchID(item) === operationID);
    }
  }
  if (!run) {
    toast("这个批次没有生成可查看的 Run");
    return;
  }
  if (state.training.runScope === "single") state.training.runScope = "batch";
  selectTrainingRun(run.id, { focus: true, reveal: true });
}

function toggleTrainingNavigator() {
  state.layout.trainingNavigatorVisible = !state.layout.trainingNavigatorVisible;
  persistWorkspacePreferences();
  renderTrainingWorkspace();
  elements.toggleTrainingNavigatorButton.focus({ preventScroll: true });
}

async function applyTrainingActivityAction(operationID, action, { confirmed = false } = {}) {
  if (!state.online || state.training.activityMutatingIDs.has(operationID)) return;
  if (action === "cancel" && !confirmed) {
    requestConfirmation({
      eyebrow: "PERSONAL TRAINING",
      title: "取消当前训练？",
      message: "Mac 会停止尚未完成的标签；已经训练并发布成功的标签会继续保留。",
      actionLabel: "取消训练",
      tone: "warning",
      returnFocus: { trainingOperationID: operationID },
      action: () => applyTrainingActivityAction(operationID, action, { confirmed: true }),
    });
    return;
  }
  state.training.activityMutatingIDs.add(operationID);
  renderTrainingActivities();
  try {
    const response = await api(`/v1/training/activities/${operationID}/actions`, {
      method: "POST",
      body: JSON.stringify({ action }),
    });
    const index = state.training.activities.findIndex(
      (activity) => activity.operationID === operationID
    );
    if (index >= 0) state.training.activities[index] = response.activity;
    renderTrainingActivities();
    toast("训练取消请求已交给 Mac");
    await Promise.all([
      loadTrainingWorkspace({ quiet: true }),
      loadTrainingActivities({ quiet: true }),
    ]);
  } catch (error) {
    toast(error.message || "训练任务操作失败");
  } finally {
    state.training.activityMutatingIDs.delete(operationID);
    renderTrainingActivities();
  }
}

function trainingSlotRun(slot) {
  return slot?.publishedRunID
    ? state.training.runs.find((run) => run.id === slot.publishedRunID) || null
    : null;
}

function focusTrainingSlot(method = null) {
  const selectedMethod = method
    || state.training.runs.find((run) => run.id === state.training.selectedRunID)?.method
    || state.training.slots[0]?.method;
  requestAnimationFrame(() => {
    const slot = selectedMethod
      ? elements.trainingSlotStrip.querySelector(
        `[data-training-slot-method="${CSS.escape(selectedMethod)}"]`
      )
      : elements.trainingSlotStrip.querySelector("[data-training-slot-method]");
    slot?.focus({ preventScroll: true });
  });
}

function moveTrainingSlotFocus(key) {
  const slots = [...elements.trainingSlotStrip.querySelectorAll("[data-training-slot-method]")];
  if (!slots.length) return;
  const current = Math.max(0, slots.indexOf(document.activeElement));
  const next = key === "Home"
    ? 0
    : key === "End"
      ? slots.length - 1
      : Math.max(0, Math.min(slots.length - 1, current + (key === "ArrowLeft" ? -1 : 1)));
  slots[next].focus({ preventScroll: true });
  slots[next].scrollIntoView({ block: "nearest", inline: "nearest" });
}

async function openTrainingSlot(method) {
  const slot = state.training.slots.find((item) => item.method === method);
  if (!slot?.isPublished || !slot.publishedRunID) {
    await openTrainingSetupDialog({ method, tagIDs: [], sourceIDs: [] });
    return;
  }
  state.training.method = method;
  state.training.runScope = "all";
  state.training.focusedRunID = slot.publishedRunID;
  await loadTrainingWorkspace();
  if (state.training.selectedRunID !== slot.publishedRunID) {
    toast("已发布记录不在当前历史窗口中，请切换到全部记录后刷新");
    return;
  }
  focusTrainingRun(slot.publishedRunID, { reveal: true });
}

function syncTrainingSlot(item, slot) {
  const presentation = trainingMethodPresentation(slot.method, state.training.mediaKind);
  const run = trainingSlotRun(slot);
  const selectedRun = state.training.runs.find(
    (candidate) => candidate.id === state.training.selectedRunID
  );
  const fingerprint = JSON.stringify({
    slot,
    run,
    selected: selectedRun?.method === slot.method,
    mediaKind: state.training.mediaKind,
  });
  if (item.dataset.trainingFingerprint === fingerprint) return;
  item.type = "button";
  item.className = `training-slot${slot.isPublished ? " published" : ""}${selectedRun?.method === slot.method ? " selected" : ""}`;
  item.dataset.trainingSlotMethod = slot.method;
  item.setAttribute("aria-pressed", String(selectedRun?.method === slot.method));
  let mark = item.querySelector(':scope > [data-training-slot-part="mark"]');
  if (!mark) {
    mark = document.createElement("span");
    mark.dataset.trainingSlotPart = "mark";
    mark.className = "training-slot-mark";
    mark.setAttribute("aria-hidden", "true");
  }
  let copy = item.querySelector(':scope > [data-training-slot-part="copy"]');
  if (!copy) {
    copy = document.createElement("span");
    copy.dataset.trainingSlotPart = "copy";
    copy.className = "training-slot-copy";
  }
  let title = copy.querySelector(':scope > [data-training-slot-copy-part="title"]');
  if (!title) {
    title = document.createElement("strong");
    title.dataset.trainingSlotCopyPart = "title";
  }
  if (title.textContent !== presentation.title) title.textContent = presentation.title;
  let status = copy.querySelector(':scope > [data-training-slot-copy-part="status"]');
  if (!status) {
    status = document.createElement("span");
    status.dataset.trainingSlotCopyPart = "status";
  }
  const statusText = slot.isPublished
    ? `模型已就绪${run?.sampleCount != null ? ` · ${run.sampleCount} 个样本` : ""}`
    : "尚未训练 · 新建任务";
  if (status.textContent !== statusText) status.textContent = statusText;
  let meta = copy.querySelector(':scope > [data-training-slot-copy-part="meta"]');
  if (!meta) {
    meta = document.createElement("small");
    meta.dataset.trainingSlotCopyPart = "meta";
  }
  const metaText = slot.isPublished
    ? `${slot.publishedRunID ? `Run ${slot.publishedRunID.slice(0, 8)}` : "已发布"}${run?.finishedAtMs != null ? ` · ${trainingDate(run.finishedAtMs)}` : ""}`
    : "选择标签、来源与训练范围";
  if (meta.textContent !== metaText) meta.textContent = metaText;
  reconcileStableChildren(copy, [title, status, meta]);
  let disclosure = item.querySelector(':scope > [data-training-slot-part="disclosure"]');
  if (!disclosure) {
    disclosure = document.createElement("span");
    disclosure.dataset.trainingSlotPart = "disclosure";
    disclosure.className = "training-slot-disclosure";
    disclosure.setAttribute("aria-hidden", "true");
    disclosure.textContent = "›";
  }
  reconcileStableChildren(item, [mark, copy, disclosure]);
  item.setAttribute(
    "aria-label",
    `${presentation.title}，${statusText}，${slot.isPublished ? "打开已发布训练记录" : "新建训练任务"}`
  );
  configurePersistentHelp(item, {
    title: presentation.title,
    detail: slot.isPublished
      ? `${statusText}。点击定位到当前发布的 Run；不会重新训练。\n左/右或 Home/End 可在三个模型槽之间移动。`
      : `当前尚未发布模型。点击打开预设为“${presentation.title}”的新建任务。\n左/右或 Home/End 可在三个模型槽之间移动。`,
    kind: "training",
    keyShortcuts: "ArrowLeft ArrowRight Home End",
  });
  item.dataset.trainingFingerprint = fingerprint;
}

function renderTrainingSlots() {
  const slots = state.training.slots.length
    ? state.training.slots
    : ["featureKnn", "personalCentroid", "personalAdamW"].map((method) => ({
      method,
      isPublished: false,
    }));
  const existingSlots = new Map(
    [...elements.trainingSlotStrip.querySelectorAll("[data-training-slot-method]")]
      .map((item) => [item.dataset.trainingSlotMethod, item])
  );
  for (const [index, slot] of slots.entries()) {
    const item = existingSlots.get(slot.method) || document.createElement("button");
    existingSlots.delete(slot.method);
    syncTrainingSlot(item, slot);
    const currentItem = elements.trainingSlotStrip.children[index] || null;
    if (currentItem !== item) elements.trainingSlotStrip.insertBefore(item, currentItem);
  }
  for (const item of existingSlots.values()) item.remove();
}

function syncTrainingRunRow(row, run) {
  const presentation = trainingMethodPresentation(run.method, run.mediaKind);
  const fingerprint = JSON.stringify({
    run,
    selected: run.id === state.training.selectedRunID,
    tagName: trainingRunTagName(run),
  });
  if (row.dataset.trainingFingerprint === fingerprint) return;
  row.type = "button";
  row.className = "training-run-row";
  row.classList.toggle("selected", run.id === state.training.selectedRunID);
  row.dataset.trainingRunId = run.id;
  row.id = `training-run-${run.id}`;
  row.tabIndex = run.id === state.training.selectedRunID ? 0 : -1;
  row.setAttribute("role", "option");
  row.setAttribute("aria-selected", String(run.id === state.training.selectedRunID));
  const tagName = trainingRunTagName(run);
  const position = trainingRunBatchPosition(run);
  const stateText = trainingStateText(run.state);
  row.setAttribute(
    "aria-label",
    `${presentation.title}，标签 ${tagName}，${position ? `批次 ${position}` : "单项"}，${stateText}`
  );
  configurePersistentHelp(row, {
    title: `${presentation.title} · ${tagName}`,
    detail: [
      `${stateText} · ${position ? `批次 ${position}` : "单项记录"}${run.sampleCount != null ? ` · ${run.sampleCount} 个样本` : ""}。`,
      "点击查看数据、配置、过程、产物和失败恢复；不会启动或停止任务。",
      "上/下逐条移动，Page Up/Down 按当前可见页幅移动，Home/End 直达首尾；⌘K 可打开当前工作区命令。",
    ].join("\n"),
    kind: "training",
    keyShortcuts: "ArrowUp ArrowDown PageUp PageDown Home End Meta+K",
  });
  let heading = row.querySelector(':scope > [data-training-run-part="heading"]');
  if (!heading) {
    heading = document.createElement("span");
    heading.dataset.trainingRunPart = "heading";
    heading.className = "training-run-row-heading";
  }
  let title = heading.querySelector(':scope > [data-training-run-heading-part="title"]');
  if (!title) {
    title = document.createElement("strong");
    title.dataset.trainingRunHeadingPart = "title";
  }
  if (title.textContent !== presentation.title) title.textContent = presentation.title;
  let dot = heading.querySelector(':scope > [data-training-run-heading-part="state-mark"]');
  if (!dot) {
    dot = document.createElement("span");
    dot.dataset.trainingRunHeadingPart = "state-mark";
    dot.setAttribute("aria-hidden", "true");
  }
  dot.className = `training-run-state-dot ${run.state}`;
  let stateLabel = heading.querySelector(':scope > [data-training-run-heading-part="state"]');
  if (!stateLabel) {
    stateLabel = document.createElement("span");
    stateLabel.dataset.trainingRunHeadingPart = "state";
    stateLabel.className = "secondary";
  }
  if (stateLabel.textContent !== stateText) stateLabel.textContent = stateText;
  reconcileStableChildren(heading, [title, dot, stateLabel]);
  let context = row.querySelector(':scope > [data-training-run-part="context"]');
  if (!context) {
    context = document.createElement("span");
    context.dataset.trainingRunPart = "context";
    context.className = "training-run-row-context";
  }
  let tag = context.querySelector(':scope > [data-training-run-context-part="tag"]');
  if (!tag) {
    tag = document.createElement("span");
    tag.dataset.trainingRunContextPart = "tag";
    tag.className = "training-run-tag";
  }
  if (tag.textContent !== tagName) tag.textContent = tagName;
  let kind = context.querySelector(':scope > [data-training-run-context-part="kind"]');
  if (!kind) {
    kind = document.createElement("span");
    kind.dataset.trainingRunContextPart = "kind";
  }
  kind.className = `training-run-kind${position ? " batch" : ""}`;
  const kindText = position
    ? (position === "批次成员" ? "批次" : `批次 ${position}`)
    : "单项";
  if (kind.textContent !== kindText) kind.textContent = kindText;
  const contextParts = [tag, kind];
  let samples = context.querySelector(':scope > [data-training-run-context-part="samples"]');
  if (run.sampleCount != null) {
    if (!samples) {
      samples = document.createElement("span");
      samples.dataset.trainingRunContextPart = "samples";
      samples.className = "secondary";
    }
    const sampleText = `${run.sampleCount} 个样本`;
    if (samples.textContent !== sampleText) samples.textContent = sampleText;
    contextParts.push(samples);
  }
  reconcileStableChildren(context, contextParts);
  let subtitle = row.querySelector(':scope > [data-training-run-part="subtitle"]');
  if (!subtitle) {
    subtitle = document.createElement("span");
    subtitle.dataset.trainingRunPart = "subtitle";
    subtitle.className = "training-run-row-subtitle";
  }
  const subtitleText = `${presentation.technical} · ${trainingDate(run.createdAtMs)}`;
  if (subtitle.textContent !== subtitleText) subtitle.textContent = subtitleText;
  reconcileStableChildren(row, [heading, context, subtitle]);
  row.dataset.trainingFingerprint = fingerprint;
}

function renderTrainingRunList() {
  captureTrainingRunListScroll();
  const contextKey = trainingRunListContextKey();
  const runs = visibleTrainingRuns();
  elements.trainingRunCount.textContent = state.training.runScope === "all"
    ? String(runs.length)
    : `${runs.length} / ${state.training.runs.length}`;
  elements.trainingEmpty.classList.toggle(
    "hidden",
    state.training.loading || runs.length > 0
  );
  if (!state.training.loading && !runs.length) {
    const title = elements.trainingEmpty.querySelector("strong");
    const message = elements.trainingEmpty.querySelector("p");
    const filtered = state.training.runs.length > 0;
    title.textContent = filtered ? "没有匹配的训练记录" : "暂无训练记录";
    message.textContent = filtered
      ? "切换到“全部”或其他记录类型；筛选不会删除或停止任务。"
      : "从“新建任务”开始；失败和取消的记录也会保留。";
  }
  const activeCount = state.training.runs.filter(
    (run) => run.state === "queued" || run.state === "running"
  ).length + state.training.activities.filter(
    (activity) => !["completed", "failed", "cancelled"].includes(activity.phase)
  ).length;
  elements.trainingNavigationCount.textContent = activeCount ? String(activeCount) : "";
  if (state.training.selectedRunID) {
    elements.trainingRunList.setAttribute(
      "aria-activedescendant",
      `training-run-${state.training.selectedRunID}`
    );
  } else {
    elements.trainingRunList.removeAttribute("aria-activedescendant");
  }
  const existingRows = new Map(
    [...elements.trainingRunList.querySelectorAll("[data-training-run-id]")]
      .map((row) => [row.dataset.trainingRunId, row])
  );
  for (const [index, run] of runs.entries()) {
    const row = existingRows.get(run.id) || document.createElement("button");
    existingRows.delete(run.id);
    syncTrainingRunRow(row, run);
    const currentRow = elements.trainingRunList.children[index] || null;
    if (currentRow !== row) elements.trainingRunList.insertBefore(row, currentRow);
  }
  for (const row of existingRows.values()) row.remove();
  restoreTrainingRunListScroll(contextKey);
}

function focusTrainingRun(runID, { reveal = false } = {}) {
  if (!runID) return;
  requestAnimationFrame(() => {
    const row = elements.trainingRunList.querySelector(
      `[data-training-run-id="${CSS.escape(runID)}"]`
    );
    if (!row) return;
    row.focus({ preventScroll: true });
    if (reveal) row.scrollIntoView({ block: "nearest" });
  });
}

function selectTrainingRun(runID, { focus = false, reveal = false } = {}) {
  if (!visibleTrainingRuns().some((run) => run.id === runID)) return;
  const selectionChanged = state.training.selectedRunID !== runID;
  state.training.selectedRunID = runID;
  if (selectionChanged) resetTrainingDetailScroll();
  renderTrainingRunList();
  renderTrainingDetail();
  if (trainingWorkspaceIsOpen() && trainingWorkspaceUsesIntegratedLayout()) {
    renderTrainingWorkspaceInspector();
  }
  checkpointActiveWorkspaceHistory();
  if (focus) focusTrainingRun(runID, { reveal });
}

function moveTrainingRunSelection(key) {
  const runs = visibleTrainingRuns();
  if (!runs.length) return;
  const rows = [...elements.trainingRunList.querySelectorAll("[data-training-run-id]")];
  const currentIndex = Math.max(
    0,
    runs.findIndex((run) => run.id === state.training.selectedRunID)
  );
  const nextIndex = longListNavigationTarget(
    rows,
    currentIndex,
    key,
    elements.trainingRunPane
  );
  selectTrainingRun(runs[nextIndex].id, { focus: true, reveal: true });
}

function trainingRunIdentifierText(run) {
  return [
    `training_run: ${run.id}`,
    run.jobID ? `job: ${run.jobID}` : "",
    run.batchID ? `batch: ${run.batchID}` : "",
    run.tagID ? `tag: ${run.tagID}` : "",
  ].filter(Boolean).join("\n");
}

function reconcileTrainingTechnicalBlocks(blocks) {
  const existing = new Map(
    [...elements.trainingTechnicalBlocks.querySelectorAll(
      ":scope > [data-training-technical-key]"
    )].map((block) => [block.dataset.trainingTechnicalKey, block])
  );
  const wanted = blocks.map((descriptor) => {
    const block = existing.get(descriptor.key) || document.createElement("section");
    existing.delete(descriptor.key);
    if (!block.hasAttribute("data-training-technical-key")) {
      block.className = "training-technical-block";
      block.append(document.createElement("h4"), document.createElement("pre"));
    }
    block.dataset.trainingTechnicalKey = descriptor.key;
    const heading = block.querySelector(":scope > h4");
    const pre = block.querySelector(":scope > pre");
    if (heading.textContent !== descriptor.title) heading.textContent = descriptor.title;
    if (pre.textContent !== descriptor.value) pre.textContent = descriptor.value;
    return block;
  });
  reconcileStableChildren(elements.trainingTechnicalBlocks, wanted);
}

function reconcileTrainingDetailContext(items) {
  const existing = new Map(
    [...elements.trainingDetailContext.querySelectorAll(
      ":scope > [data-training-context-key]"
    )].map((chip) => [chip.dataset.trainingContextKey, chip])
  );
  const wanted = items.map((item) => {
    const chip = existing.get(item.key) || document.createElement("span");
    existing.delete(item.key);
    chip.dataset.trainingContextKey = item.key;
    if (chip.className !== item.className) chip.className = item.className;
    if (chip.textContent !== item.text) chip.textContent = item.text;
    return chip;
  });
  reconcileStableChildren(elements.trainingDetailContext, wanted);
}

function trainingDetailJobActionKey(jobID, action) {
  if (["pause", "resume"].includes(action)) return `job:${jobID}:primary`;
  return `job:${jobID}:${action}`;
}

function syncTrainingDetailAction(button, descriptor) {
  button.type = "button";
  button.className = descriptor.className;
  button.setAttribute("data-training-detail-action-key", descriptor.key);
  for (const name of [
    "jobId",
    "trainingJobId",
    "trainingRunJobId",
    "trainingReconfigureRunId",
    "trainingReviewRunId",
    "action",
  ]) {
    delete button.dataset[name];
  }
  for (const [name, value] of Object.entries(descriptor.dataset || {})) {
    button.dataset[name] = value;
  }
  button.disabled = Boolean(descriptor.disabled);
  button.textContent = descriptor.text;
  configurePersistentHelp(button, descriptor.help);
}

function restoreTrainingDetailActionFocus() {
  const key = state.training.pendingDetailActionFocusKey;
  if (!key) return;
  if (elements.trainingWorkspace.classList.contains("hidden")) {
    state.training.pendingDetailActionFocusKey = null;
    return;
  }
  requestAnimationFrame(() => {
    if (state.training.pendingDetailActionFocusKey !== key) return;
    const buttons = [...elements.trainingDetailActions.children];
    const exact = buttons.find(
      (candidate) => candidate.dataset.trainingDetailActionKey === key
    );
    if (exact?.disabled) return;
    const button = exact || buttons.find((candidate) => !candidate.disabled);
    if (!button) {
      state.training.pendingDetailActionFocusKey = null;
      return;
    }
    button.focus({ preventScroll: true });
    state.training.pendingDetailActionFocusKey = null;
  });
}

function reconcileTrainingDetailActions(run) {
  const descriptors = [];
  const job = run.jobID ? state.jobs.find((item) => item.id === run.jobID) : null;
  if (run.jobID) {
    descriptors.push({
      key: `job:${run.jobID}:view`,
      className: "button button-compact",
      dataset: { trainingJobId: run.jobID },
      text: "查看关联任务",
      help: {
        title: "查看关联任务",
        detail: "在活动面板中定位这个 Run 的后台任务；训练详情、选择和滚动位置保持不变。",
        kind: "training",
      },
    });

    for (const action of job?.availableActions || []) {
      const text = action === "resume" && job.state === "retryableFailed"
        ? "重试任务"
        : jobActionText(action);
      descriptors.push({
        key: trainingDetailJobActionKey(run.jobID, action),
        className: `button button-compact job-action write-action${action === "cancel" ? " button-danger" : ""}`,
        dataset: {
          jobId: run.jobID,
          trainingRunJobId: run.jobID,
          action,
        },
        disabled: !state.online || state.jobMutatingIDs.has(run.jobID),
        text,
        help: {
          title: text,
          detail: {
            pause: "暂停关联任务并保留已经完成的进度；可以稍后从活动面板或这里继续。",
            resume: job.state === "retryableFailed"
              ? "从 Mac 保存的恢复点重试失败任务；不会创建重复 Run。"
              : "从 Mac 保存的进度继续关联任务。",
            cancel: "请求 Mac 取消尚未完成的工作；已经保存的训练记录和成功产物不会被删除。",
          }[action] || "把这个任务动作交给 Mac 执行，并保留当前训练详情。",
          kind: "training",
        },
      });
    }
  }

  if (["failed", "cancelled"].includes(run.state)) {
    descriptors.push({
      key: `run:${run.id}:reconfigure`,
      className: "button button-compact button-primary",
      dataset: { trainingReconfigureRunId: run.id },
      text: "重新配置",
      help: {
        title: "重新配置训练",
        detail: "从这条失败或取消记录恢复可证明的方法、标签与来源；无法证明的历史范围会要求重新确认。",
        kind: "training",
      },
    });
  }

  if (run.tagID) {
    descriptors.push({
      key: `run:${run.id}:review`,
      className: "button button-compact",
      dataset: { trainingReviewRunId: run.id },
      text: "打开标签审核",
      help: {
        title: "打开标签审核",
        detail: `进入“${trainingRunTagName(run)}”的建议审核；返回后仍定位到当前 Run 和详情滚动位置。`,
        kind: "training",
      },
    });
  }

  const existing = new Map(
    [...elements.trainingDetailActions.children].map((button) => [
      button.dataset.trainingDetailActionKey,
      button,
    ])
  );
  const wanted = [];
  for (const descriptor of descriptors) {
    const button = existing.get(descriptor.key) || document.createElement("button");
    syncTrainingDetailAction(button, descriptor);
    wanted.push(button);
  }
  for (const [index, button] of wanted.entries()) {
    if (elements.trainingDetailActions.children[index] !== button) {
      elements.trainingDetailActions.insertBefore(
        button,
        elements.trainingDetailActions.children[index] || null
      );
    }
  }
  for (const button of [...elements.trainingDetailActions.children]) {
    if (!wanted.includes(button)) button.remove();
  }
  restoreTrainingDetailActionFocus();
}

async function openReviewFromTrainingRun(runID) {
  const run = state.training.runs.find((item) => item.id === runID);
  if (!run?.tagID) {
    toast("这条训练记录没有可定位的标签");
    return;
  }
  if (run.mediaKind !== state.mediaKind) await switchMediaKind(run.mediaKind);
  await openReviewWorkspace({ returnToTrainingRunID: run.id });
  let overview = state.review.overview.find((item) => item.id === run.tagID);
  if (!overview && state.review.sourceFilterIDs !== null) {
    state.review.sourceFilterIDs = null;
    await loadReviewOverview();
    overview = state.review.overview.find((item) => item.id === run.tagID);
  }
  if (!overview) {
    toast("该标签当前没有可显示的审核记录");
    return;
  }
  if (overview.canReview && overview.pendingSuggestionCount > 0) {
    await enterReviewQueue(run.tagID);
    return;
  }
  requestAnimationFrame(() => {
    const card = elements.reviewOverviewGrid.querySelector(
      `[data-review-overview-tag-id="${CSS.escape(run.tagID)}"]`
    );
    card?.scrollIntoView({ block: "nearest" });
    card?.focus({ preventScroll: true });
  });
  toast("已定位到对应标签；当前没有待审核建议");
}

function trainingDetailFingerprint(run) {
  const job = run.jobID ? state.jobs.find((item) => item.id === run.jobID) : null;
  return JSON.stringify({
    run,
    job,
    jobMutating: Boolean(run.jobID && state.jobMutatingIDs.has(run.jobID)),
    online: state.online,
    tagName: trainingRunTagName(run),
  });
}

function renderTrainingDetail() {
  const run = state.training.runs.find((item) => item.id === state.training.selectedRunID);
  const renderedRunID = state.training.renderedDetailRunID;
  const detailScrollTop = elements.trainingDetailPane.scrollTop;
  elements.trainingDetailPlaceholder.classList.toggle("hidden", Boolean(run));
  elements.trainingDetail.classList.toggle("hidden", !run);
  if (!run) {
    state.training.renderedDetailRunID = null;
    state.training.renderedDetailFingerprint = null;
    resetTrainingDetailScroll();
    state.training.renderedContentFingerprint = trainingWorkspaceContentFingerprint();
    return;
  }
  const detailFingerprint = trainingDetailFingerprint(run);
  if (renderedRunID === run.id
    && state.training.renderedDetailFingerprint === detailFingerprint) {
    state.training.renderedContentFingerprint = trainingWorkspaceContentFingerprint();
    return;
  }

  const presentation = trainingMethodPresentation(run.method, run.mediaKind);
  elements.trainingDetailTitle.textContent = presentation.title;
  elements.trainingDetailSubtitle.textContent = `${presentation.technical} · Run ${run.id.slice(0, 8)}`;
  const detailContexts = [
    { key: "tag", text: trainingRunTagName(run), className: "tag" },
    {
      key: "recordType",
      text: trainingRunBatchPosition(run)
        ? `批次 ${trainingRunBatchPosition(run)}`
        : "单项记录",
      className: isBatchTrainingRun(run) ? "batch" : "single",
    },
    run.sampleCount != null
      ? { key: "samples", text: `${run.sampleCount} 个样本`, className: "samples" }
      : null,
  ].filter(Boolean);
  reconcileTrainingDetailContext(detailContexts);
  elements.trainingDetailState.textContent = trainingStateText(run.state);
  elements.trainingDetailState.className = `training-state-pill ${run.state}`;
  reconcileTrainingDetailActions(run);

  const batchPosition = trainingRunBatchPosition(run);
  const duration = trainingRunDuration(run);
  reconcileTrainingFacts(elements.trainingFactLedger, [
    { key: "tag", label: "标签", value: trainingRunTagName(run) },
    {
      key: "recordType",
      label: "记录类型",
      value: isBatchTrainingRun(run) ? "个人模型批次成员" : "单项训练",
    },
    batchPosition
      ? { key: "batchPosition", label: "批次位置", value: batchPosition }
      : null,
    run.sampleCount != null
      ? { key: "samples", label: "样本", value: `${run.sampleCount} 个` }
      : null,
    run.positiveSampleCount != null || run.negativeSampleCount != null
      ? {
        key: "tagSamples",
        label: "标签样本",
        value: `属于 ${run.positiveSampleCount || 0} · 不属于 ${run.negativeSampleCount || 0}`,
      }
      : null,
    { key: "media", label: "媒体", value: run.mediaKind === "video" ? "视频" : "照片" },
    { key: "created", label: "创建", value: trainingDate(run.createdAtMs) },
    run.startedAtMs != null
      ? { key: "started", label: "开始", value: trainingDate(run.startedAtMs) }
      : null,
    run.finishedAtMs != null
      ? { key: "finished", label: "结束", value: trainingDate(run.finishedAtMs) }
      : null,
    duration ? { key: "duration", label: "耗时", value: duration } : null,
    { key: "scope", label: "数据范围", value: trainingRunScopeText(run) },
    run.mediaKind === "video"
      ? { key: "aiInput", label: "AI 输入", value: "代表缩略图 videoPoster.v1" }
      : null,
    run.jobID
      ? { key: "job", label: "关联任务", value: run.jobID.slice(0, 8) }
      : null,
  ].filter(Boolean));

  const guidance = run.failureGuidance;
  elements.trainingErrorSection.classList.toggle("hidden", !run.errorCode);
  elements.trainingErrorTitle.textContent = guidance?.title || "训练未完成";
  elements.trainingErrorMessage.textContent = guidance?.message || "这台 Mac 已保留失败记录。";
  elements.trainingErrorAction.textContent = guidance?.suggestedAction || "检查关联任务后可重新配置。";
  elements.trainingErrorCode.textContent = run.errorCode || "";
  renderTrainingMetrics(run.metricsJSON, run.id);

  reconcileTrainingFacts(elements.trainingArtifactLedger, [
    {
      key: "type",
      label: "类型",
      value: run.artifactKind || "未发布",
      className: "training-compact-fact",
    },
    run.artifactRef
      ? {
        key: "reference",
        label: "引用",
        value: run.artifactRef,
        className: "training-compact-fact",
      }
      : null,
    run.artifactSHA256
      ? {
        key: "sha256",
        label: "SHA-256",
        value: run.artifactSHA256,
        className: "training-compact-fact",
      }
      : null,
    run.sampleManifestSHA256
      ? {
        key: "manifestSHA256",
        label: "样本清单 SHA-256",
        value: run.sampleManifestSHA256,
        className: "training-compact-fact",
      }
      : null,
  ].filter(Boolean));

  reconcileTrainingTechnicalBlocks([
    { key: "identifiers", title: "运行标识", value: trainingRunIdentifierText(run) },
    {
      key: "samples",
      title: "数据",
      value: prettyTrainingJSON(run.sampleSummaryJSON, "没有样本摘要"),
    },
    {
      key: "config",
      title: "配置",
      value: prettyTrainingJSON(run.configJSON, "没有配置摘要"),
    },
    {
      key: "result",
      title: "结果",
      value: prettyTrainingJSON(run.resultSummaryJSON, "没有结果摘要"),
    },
  ]);
  elements.trainingDetailPane.scrollTop = renderedRunID === run.id ? detailScrollTop : 0;
  state.training.renderedDetailRunID = run.id;
  state.training.renderedDetailFingerprint = detailFingerprint;
  state.training.renderedContentFingerprint = trainingWorkspaceContentFingerprint();
}

function renderTrainingWorkspaceInspector() {
  const activity = currentActiveTrainingActivity();
  const run = state.training.runs.find((item) => item.id === state.training.selectedRunID) || null;
  const mediaNoun = state.training.mediaKind === "video" ? "视频" : "照片";
  elements.inspectorTrainingFeatureRequirement.textContent =
    `相似${mediaNoun}：每个标签至少 2 个属于、2 个不属于。`;
  elements.inspectorTrainingWorkspaceActivity.classList.toggle("hidden", !activity);
  elements.inspectorTrainingWorkspaceRun.classList.toggle("hidden", Boolean(activity) || !run);
  elements.inspectorTrainingWorkspaceEmpty.classList.toggle("hidden", Boolean(activity) || Boolean(run));

  if (activity) {
    const presentation = trainingMethodPresentation(activity.method, activity.mediaKind);
    const phase = {
      preparingSamples: "正在准备样本",
      preparingEmbeddings: "正在准备 AI 特征",
      trainingAndPublishing: "正在训练并发布模型",
    }[activity.phase] || "训练处理中";
    const completed = Math.max(0, Number(activity.completedUnitCount || 0));
    const total = Math.max(completed, Number(activity.totalUnitCount || 0));
    elements.inspectorTrainingWorkspaceActivityTitle.textContent =
      `${presentation.title} · ${phase}`;
    elements.inspectorTrainingWorkspaceActivityDetail.textContent = total
      ? `已完成 ${completed} / ${total}`
      : "正在等待这台 Mac 更新进度";
    elements.inspectorTrainingWorkspaceActivityPhase.textContent =
      activity.tagActivities?.length
        ? `${activity.tagActivities.length} 个标签 · 训练与发布均在这台 Mac 完成`
        : "训练与发布均在这台 Mac 完成";
    return;
  }
  if (!run) return;

  const presentation = trainingMethodPresentation(run.method, run.mediaKind);
  elements.inspectorTrainingWorkspaceTask.textContent = presentation.title;
  elements.inspectorTrainingWorkspaceMethod.textContent = presentation.technical;
  elements.inspectorTrainingWorkspaceState.textContent = trainingStateText(run.state);
  elements.inspectorTrainingWorkspaceCreated.textContent = trainingDate(run.createdAtMs);
  elements.inspectorTrainingWorkspaceIdentifier.textContent = `训练编号 ${run.id}`;
}

function trainingWorkspaceContentFingerprint() {
  return JSON.stringify({
    mediaKind: state.training.mediaKind,
    method: state.training.method,
    runScope: state.training.runScope,
    selectedRunID: state.training.selectedRunID,
    runs: state.training.runs,
    slots: state.training.slots,
    activities: state.training.activities,
    mutatingActivityIDs: [...state.training.activityMutatingIDs].sort(),
    jobs: state.jobs,
    tags: activeTags().map((tag) => ({ id: tag.id, displayName: tag.displayName })),
  });
}

function trainingWorkspaceCanPreserveContent() {
  return state.training.renderedContentFingerprint !== null
    && state.training.renderedContentFingerprint === trainingWorkspaceContentFingerprint();
}

function renderTrainingWorkspace({ preserveContent = false } = {}) {
  for (const button of elements.trainingMediaKindTabs.querySelectorAll(
    "[data-training-media-kind]"
  )) {
    button.setAttribute(
      "aria-pressed",
      String(button.dataset.trainingMediaKind === state.training.mediaKind)
    );
  }
  syncRovingSegmentedControl(
    elements.trainingMediaKindTabs,
    "[data-training-media-kind]"
  );
  elements.trainingMethodFilter.value = state.training.method;
  elements.trainingRecordScopeFilter.value = state.training.runScope;
  elements.trainingFeatureMethodOption.textContent = state.training.mediaKind === "video"
    ? "相似视频"
    : "相似照片";
  elements.refreshTrainingButton.disabled = state.training.loading;
  elements.refreshTrainingButton.setAttribute("aria-busy", String(state.training.loading));
  const activeActivity = currentActiveTrainingActivity();
  elements.newTrainingButton.disabled = state.training.loading || Boolean(activeActivity);
  elements.newTrainingButton.title = activeActivity
    ? "当前已有个人模型训练正在运行；完成或取消后才能创建下一项"
    : "选择目标标签、训练方法和媒体范围";
  const navigatorAction = state.layout.trainingNavigatorVisible ? "隐藏训练记录" : "显示训练记录";
  configurePersistentHelp(elements.closeTrainingButton, {
    title: elements.closeTrainingButton.getAttribute("aria-label") || "返回图库",
    detail: "退出训练工程并返回上一个工作区；正在运行的后台任务不会被取消。",
    kind: "training",
  });
  for (const button of elements.trainingMediaKindTabs.querySelectorAll(
    "[data-training-media-kind]"
  )) {
    const noun = button.dataset.trainingMediaKind === "video" ? "视频" : "照片";
    configurePersistentHelp(button, {
      title: `训练媒体 · ${noun}`,
      detail: `切换到${noun}训练记录、模型槽和新建任务；照片与视频的训练产物不会混用。`,
      kind: "training",
    });
  }
  configurePersistentHelp(elements.newTrainingButton, {
    title: "新建训练任务",
    detail: activeActivity
      ? "当前已有个人模型训练正在运行；完成或取消后才能创建下一项。"
      : `打开训练设置，选择目标标签、训练方法和${state.training.mediaKind === "video" ? "视频" : "照片"}范围，再确认创建任务。快捷键 N。`,
    kind: "training",
    keyShortcuts: "N",
  });
  configurePersistentHelp(elements.trainingMethodFilter, {
    title: "筛选训练方法",
    detail: "筛选左侧训练记录和批次历史；只改变显示范围，不会删除、暂停或重新运行任务。",
    kind: "training",
  });
  configurePersistentHelp(elements.trainingRecordScopeFilter, {
    title: "筛选记录类型",
    detail: "在全部、个人模型批次成员和单项记录之间切换；每种范围分别记住列表滚动位置。",
    kind: "training",
  });
  configurePersistentHelp(elements.toggleTrainingNavigatorButton, {
    title: navigatorAction,
    detail: state.layout.trainingNavigatorVisible
      ? "隐藏训练记录栏，让任务详情使用更多宽度；再次点击或按 L 恢复。"
      : "显示训练记录栏，并恢复该筛选范围上次的选择与滚动位置；快捷键 L。",
    kind: "training",
    keyShortcuts: "L",
  });
  configurePersistentHelp(elements.refreshTrainingButton, {
    title: "刷新训练工程",
    detail: "重新读取训练记录、模型槽位、批次和当前任务进度；不会启动新的训练。快捷键 R。",
    kind: "training",
    keyShortcuts: "R",
  });
  elements.trainingWorkspace.classList.toggle(
    "navigator-hidden",
    !state.layout.trainingNavigatorVisible
  );
  elements.toggleTrainingNavigatorButton.title = navigatorAction;
  elements.toggleTrainingNavigatorButton.setAttribute("aria-label", navigatorAction);
  elements.toggleTrainingNavigatorButton.setAttribute(
    "aria-pressed",
    String(state.layout.trainingNavigatorVisible)
  );
  const noun = state.training.mediaKind === "video" ? "视频" : "照片";
  const visibleRunCount = visibleTrainingRuns().length;
  elements.trainingSummary.textContent = state.training.loading
    ? `正在读取${noun}训练记录…`
    : `${visibleRunCount} 条${noun}训练记录${state.training.runScope === "all" ? "" : ` · 共 ${state.training.runs.length} 条`}`;
  if (!preserveContent) {
    renderTrainingSlots();
    renderTrainingActivities();
    renderTrainingBatchHistory();
    renderTrainingRunList();
    renderTrainingDetail();
    if (trainingWorkspaceIsOpen() && trainingWorkspaceUsesIntegratedLayout()) {
      renderTrainingWorkspaceInspector();
    }
  }
}

async function loadTrainingWorkspace({ quiet = false } = {}) {
  const activeRunRow = document.activeElement?.closest?.("[data-training-run-id]");
  const restoreFocusedRunID = elements.trainingRunList.contains(document.activeElement)
    ? (activeRunRow?.dataset.trainingRunId || state.training.selectedRunID)
    : null;
  const activeActivityAction = elements.trainingActivityStrip.contains(document.activeElement)
    ? document.activeElement?.closest?.(
      "[data-training-activity-id][data-action], [data-training-batch-reconfigure-id]"
    )
    : null;
  const restoreFocusedActivityAction = activeActivityAction
    ? {
      operationID: activeActivityAction.dataset.trainingActivityId
        || activeActivityAction.dataset.trainingBatchReconfigureId,
      action: activeActivityAction.dataset.action || "reconfigure",
    }
    : null;
  const activeBatchAction = elements.trainingBatchList.contains(document.activeElement)
    ? document.activeElement?.closest?.(
      "[data-training-batch-view-id], [data-training-batch-reconfigure-id]"
    )
    : null;
  const restoreFocusedBatchAction = activeBatchAction
    ? {
      attribute: activeBatchAction.dataset.trainingBatchViewId
        ? "data-training-batch-view-id"
        : "data-training-batch-reconfigure-id",
      operationID: activeBatchAction.dataset.trainingBatchViewId
        || activeBatchAction.dataset.trainingBatchReconfigureId,
    }
    : null;
  const generation = ++state.training.requestGeneration;
  state.training.loading = true;
  renderTrainingWorkspace({ preserveContent: trainingWorkspaceCanPreserveContent() });
  const query = new URLSearchParams({ mediaKind: state.training.mediaKind });
  if (state.training.method) query.set("method", state.training.method);
  try {
    const snapshot = await api(`/v1/training/workspace?${query}`);
    if (generation !== state.training.requestGeneration) return;
    const previousRunID = state.training.selectedRunID;
    state.training.runs = snapshot.runs || [];
    state.training.slots = snapshot.slots || [];
    state.training.activities = snapshot.activities || [];
    const focusedRun = state.training.runs.find(
      (run) => state.training.focusedRunID && run.id === state.training.focusedRunID
    ) || state.training.runs.find(
      (run) => state.training.focusedJobID && run.jobID === state.training.focusedJobID
    ) || state.training.runs.find(
      (run) => state.training.focusedTagID && run.tagID === state.training.focusedTagID
    );
    if (focusedRun && !visibleTrainingRuns().some((run) => run.id === focusedRun.id)) {
      state.training.runScope = "all";
    }
    const visibleRuns = visibleTrainingRuns();
    state.training.selectedRunID = focusedRun?.id
      || (visibleRuns.some((run) => run.id === previousRunID)
        ? previousRunID
        : (visibleRuns[0]?.id || null));
    if (state.training.selectedRunID !== previousRunID) resetTrainingDetailScroll();
    if (focusedRun) {
      state.training.focusedRunID = null;
      state.training.focusedJobID = null;
      state.training.focusedTagID = null;
    }
  } catch (error) {
    if (generation === state.training.requestGeneration && !quiet) {
      toast(error.message || "训练记录载入失败");
    }
  } finally {
    if (generation === state.training.requestGeneration) {
      state.training.loading = false;
      renderTrainingWorkspace({ preserveContent: trainingWorkspaceCanPreserveContent() });
      const pendingReturnFocusRunID = state.training.pendingReturnFocusRunID;
      state.training.pendingReturnFocusRunID = null;
      if (pendingReturnFocusRunID
        && !elements.trainingWorkspace.classList.contains("hidden")) {
        stabilizeDismissedOverlayFocus(
          () => elements.trainingRunList.querySelector(
            `[data-training-run-id="${CSS.escape(pendingReturnFocusRunID)}"]`
          ),
          elements.reviewWorkspace,
          () => !elements.trainingWorkspace.classList.contains("hidden")
        );
      } else if (restoreFocusedActivityAction) {
        const operationID = CSS.escape(restoreFocusedActivityAction.operationID);
        const primarySelector = restoreFocusedActivityAction.action === "reconfigure"
          ? `[data-training-batch-reconfigure-id="${operationID}"]`
          : `[data-training-activity-id="${operationID}"]`
            + `[data-action="${CSS.escape(restoreFocusedActivityAction.action)}"]`;
        const fallbackSelector = restoreFocusedActivityAction.action === "reconfigure"
          ? `[data-training-activity-id="${operationID}"][data-action="cancel"]`
          : `[data-training-batch-reconfigure-id="${operationID}"]`;
        const activityAction = elements.trainingActivityStrip.querySelector(primarySelector)
          || elements.trainingActivityStrip.querySelector(fallbackSelector);
        const batchAction = elements.trainingBatchList.querySelector(
          `[data-training-batch-view-id="${operationID}"]`
        ) || elements.trainingBatchList.querySelector(
          `[data-training-batch-reconfigure-id="${operationID}"]`
        );
        const action = activityAction?.offsetParent !== null ? activityAction : batchAction;
        (action && !action.disabled ? action : elements.refreshTrainingButton)
          .focus({ preventScroll: true });
      } else if (restoreFocusedBatchAction) {
        const primaryAction = elements.trainingBatchList.querySelector(
          `[${restoreFocusedBatchAction.attribute}="${CSS.escape(restoreFocusedBatchAction.operationID)}"]`
        );
        const operationID = CSS.escape(restoreFocusedBatchAction.operationID);
        const fallbackAction = elements.trainingBatchList.querySelector(
          `[data-training-batch-view-id="${operationID}"]`
        ) || elements.trainingBatchList.querySelector(
          `[data-training-batch-reconfigure-id="${operationID}"]`
        );
        const action = primaryAction || fallbackAction;
        (action && !action.disabled ? action : elements.refreshTrainingButton)
          .focus({ preventScroll: true });
      } else if (restoreFocusedRunID) {
        const nextFocusID = visibleTrainingRuns().some((run) => run.id === restoreFocusedRunID)
          ? restoreFocusedRunID
          : state.training.selectedRunID;
        focusTrainingRun(nextFocusID);
      }
    }
  }
}

async function openTrainingWorkspace({
  returnToReview = null,
  historyMode = "push",
} = {}) {
  leaveIntegratedGalleryOverviewForLibrary({ historyMode: "none" });
  leaveIntegratedWorldMapForLibrary({ historyMode: "none" });
  elements.reviewWorkspace.classList.add("hidden");
  syncReviewPresentation({ renderSurfaces: false });
  if (returnToReview) {
    state.training.returnTarget = {
      workspace: "review",
      mode: returnToReview.mode || "overview",
      tagID: returnToReview.tagID || null,
      jobID: returnToReview.jobID || null,
    };
  } else {
    state.training.returnTarget = null;
    state.reviewReturnFocus = null;
  }
  elements.slimmingWorkspace.classList.add("hidden");
  syncSlimmingPresentation({ renderSurfaces: false });
  state.slimmingReturnFocus = null;
  state.slimmingReturnTarget = null;
  closeJobsPopover({ restoreFocus: false });
  closeFilterPopover({ restoreFocus: false });
  if (elements.trainingWorkspace.classList.contains("hidden")) {
    state.trainingReturnFocus = document.activeElement;
  }
  elements.trainingWorkspace.classList.remove("hidden");
  recordWorkspaceHistory(
    "training",
    currentWorkspaceHistoryContext("training"),
    historyMode
  );
  syncTrainingClosePresentation();
  syncTrainingPresentation({ focus: true });
  await loadTrainingWorkspace();
}

async function switchTrainingMediaKind(mediaKind) {
  if (!["image", "video"].includes(mediaKind)
    || mediaKind === state.training.mediaKind) return;
  state.training.mediaKind = mediaKind;
  state.training.selectedRunID = null;
  await loadTrainingWorkspace();
  checkpointActiveWorkspaceHistory();
}

function slimmingModeText(mode) {
  return {
    catalog: "全部来源",
    currentFilter: "当前筛选",
    seeds: "从所选项目查找",
  }[mode] || "分析";
}

function slimmingJobStateText(job) {
  if (job?.state === "running" && job.controlRequest === "pause") return "正在暂停";
  if (job?.state === "running" && job.controlRequest === "cancel") return "正在取消";
  return jobStateText(job || {});
}

function slimmingScanPhaseText(progress) {
  if (!progress) return "";
  return {
    preparingFingerprints: "补全内容指纹",
    loadingFeaturePrints: "加载 Feature Print",
    loadingEmbeddings: "加载 DINOv2 向量",
    clustering: "聚类分析",
  }[progress.phase] || "分析中";
}

function selectedSlimmingJob() {
  return state.slimming.jobs.find((job) => job.id === state.slimming.selectedJobID) || null;
}

function selectedSlimmingJobIndex() {
  return state.slimming.jobs.findIndex((job) => job.id === state.slimming.selectedJobID);
}

function totalSlimmingJobCount() {
  return Math.max(state.slimming.jobs.length, Number(state.slimming.totalJobCount || 0));
}

function hasMoreSlimmingJobs() {
  return state.slimming.jobLimit < totalSlimmingJobCount()
    && state.slimming.jobLimit < SLIMMING_JOB_LIMIT_MAX;
}

async function expandSlimmingJobWindow({ all = false } = {}) {
  if (state.slimming.loading || !hasMoreSlimmingJobs()) return false;
  const previousLimit = state.slimming.jobLimit;
  const target = all
    ? totalSlimmingJobCount()
    : previousLimit + SLIMMING_JOB_PAGE_SIZE;
  state.slimming.jobLimit = Math.min(SLIMMING_JOB_LIMIT_MAX, target);
  const loaded = await loadSlimmingWorkspace({ quiet: true, appendKind: "jobs" });
  if (!loaded) {
    state.slimming.jobLimit = previousLimit;
    renderSlimmingWorkspace({
      preserveJobs: true,
      preserveClusters: true,
      preserveMembers: true,
    });
    return false;
  }
  return state.slimming.jobLimit > previousLimit;
}

function focusSelectedSlimmingJob() {
  requestAnimationFrame(() => {
    const selected = elements.slimmingJobList.querySelector('[aria-selected="true"]');
    selected?.focus({ preventScroll: true });
    selected?.scrollIntoView({ block: "nearest", inline: "center" });
  });
}

function focusSelectedSlimmingCluster({ fallbackToScope = true } = {}) {
  requestAnimationFrame(() => {
    const selected = elements.slimmingClusterList.querySelector(
      '[data-slimming-cluster-id][aria-pressed="true"]'
    );
    if (selected) {
      selected.focus({ preventScroll: true });
      selected.scrollIntoView({ block: "nearest", inline: "nearest" });
      return;
    }
    if (fallbackToScope) {
      elements.slimmingClusterScopes.querySelector(
        `[data-slimming-cluster-scope="${CSS.escape(state.slimming.clusterScope)}"]`
      )?.focus({ preventScroll: true });
    }
  });
}

async function selectSlimmingJob(jobID, { focus = false } = {}) {
  if (state.slimming.loading
    || !state.slimming.jobs.some((job) => job.id === jobID)) return;
  if (jobID === state.slimming.selectedJobID) {
    if (focus) focusSelectedSlimmingJob();
    return;
  }
  state.slimming.selectedJobID = jobID;
  state.slimming.selectedClusterID = null;
  state.slimming.selectedMemberIDs.clear();
  state.slimming.selectionAnchorID = null;
  state.slimming.clusterLimit = 48;
  state.slimming.memberLimit = 96;
  await loadSlimmingWorkspace({ jobID });
  checkpointActiveWorkspaceHistory();
  if (focus) focusSelectedSlimmingJob();
}

function hasMoreSlimmingClusters() {
  return state.slimming.clusters.length < totalSlimmingClusterCount()
    && state.slimming.clusterLimit < SLIMMING_CLUSTER_LIMIT_MAX;
}

async function expandSlimmingClusterWindow({ all = false } = {}) {
  if (state.slimming.loading || !hasMoreSlimmingClusters()) return false;
  const previousLimit = state.slimming.clusterLimit;
  const target = all
    ? totalSlimmingClusterCount()
    : previousLimit + 48;
  state.slimming.clusterLimit = Math.min(SLIMMING_CLUSTER_LIMIT_MAX, target);
  const loaded = await loadSlimmingWorkspace({ quiet: true, appendKind: "clusters" });
  if (!loaded) {
    state.slimming.clusterLimit = previousLimit;
    renderSlimmingWorkspace({
      preserveJobs: true,
      preserveClusters: true,
      preserveMembers: true,
    });
    return false;
  }
  return state.slimming.clusterLimit > previousLimit;
}

async function selectSlimmingCluster(clusterID, { focus = false } = {}) {
  if (state.slimming.loading
    || !state.slimming.clusters.some((cluster) => cluster.id === clusterID)) return;
  if (clusterID === state.slimming.selectedClusterID) {
    if (focus) focusSelectedSlimmingCluster({ fallbackToScope: false });
    return;
  }
  state.slimming.selectedClusterID = clusterID;
  state.slimming.memberLimit = 96;
  checkpointActiveWorkspaceHistory();
  await loadSlimmingWorkspace({ clusterID });
  if (focus) focusSelectedSlimmingCluster({ fallbackToScope: false });
}

async function navigateSlimmingClusterByKey(key) {
  if (state.slimming.loading || !state.slimming.clusters.length) return;
  if (key === "End" && hasMoreSlimmingClusters()) {
    await expandSlimmingClusterWindow({ all: true });
  }
  let buttons = [...elements.slimmingClusterList.querySelectorAll(
    "[data-slimming-cluster-id]"
  )];
  let currentIndex = Math.max(
    0,
    state.slimming.clusters.findIndex(
      (cluster) => cluster.id === state.slimming.selectedClusterID
    )
  );
  let targetIndex = longListNavigationTarget(
    buttons,
    currentIndex,
    key,
    elements.slimmingNavigatorPane
  );
  if (key === "PageDown" && targetIndex === currentIndex && hasMoreSlimmingClusters()) {
    await expandSlimmingClusterWindow();
    buttons = [...elements.slimmingClusterList.querySelectorAll(
      "[data-slimming-cluster-id]"
    )];
    currentIndex = Math.max(
      0,
      state.slimming.clusters.findIndex(
        (cluster) => cluster.id === state.slimming.selectedClusterID
      )
    );
    targetIndex = longListNavigationTarget(
      buttons,
      currentIndex,
      key,
      elements.slimmingNavigatorPane
    );
  }
  await selectSlimmingCluster(
    state.slimming.clusters[targetIndex]?.id,
    { focus: true }
  );
}

function slimmingClusterScopeText(scope) {
  return { pending: "待处理", confirmed: "已确认", ignored: "已忽略" }[scope] || "待处理";
}

async function navigateSlimmingJob(target) {
  if (!state.slimming.jobs.length || state.slimming.loading) return;
  let current = Math.max(0, selectedSlimmingJobIndex());
  if ((target === "last" || (Number(target) > 0 && current >= state.slimming.jobs.length - 1))
    && hasMoreSlimmingJobs()) {
    await expandSlimmingJobWindow({ all: target === "last" });
    current = Math.max(0, selectedSlimmingJobIndex());
  }
  const index = target === "first"
    ? 0
    : target === "last"
      ? state.slimming.jobs.length - 1
      : Math.max(0, Math.min(state.slimming.jobs.length - 1, current + Number(target)));
  const job = state.slimming.jobs[index];
  await selectSlimmingJob(job?.id, { focus: true });
}

async function navigateSlimmingJobByKey(key, originJobID = null) {
  if (state.slimming.loading || !state.slimming.jobs.length) return;
  const normalizedKey = key === "ArrowLeft"
    ? "ArrowUp"
    : key === "ArrowRight"
      ? "ArrowDown"
      : key;
  if (normalizedKey === "Home") {
    await navigateSlimmingJob("first");
    return;
  }
  if (normalizedKey === "End") {
    await navigateSlimmingJob("last");
    return;
  }
  let rows = [...elements.slimmingJobList.querySelectorAll("[data-slimming-job-id]")];
  let currentIndex = state.slimming.jobs.findIndex((job) => job.id === originJobID);
  if (currentIndex < 0) currentIndex = Math.max(0, selectedSlimmingJobIndex());
  let targetIndex = longListNavigationTarget(
    rows,
    currentIndex,
    normalizedKey,
    elements.slimmingNavigatorPane
  );
  if (normalizedKey === "PageDown" && targetIndex === currentIndex && hasMoreSlimmingJobs()) {
    await expandSlimmingJobWindow();
    rows = [...elements.slimmingJobList.querySelectorAll("[data-slimming-job-id]")];
    currentIndex = Math.max(0, selectedSlimmingJobIndex());
    targetIndex = longListNavigationTarget(
      rows,
      currentIndex,
      normalizedKey,
      elements.slimmingNavigatorPane
    );
  }
  await selectSlimmingJob(state.slimming.jobs[targetIndex]?.id, { focus: true });
}

function syncSlimmingScanProgressElement(progress, job, compact = false) {
  const scan = job?.scanProgress;
  if (!scan) return null;
  const completed = Math.max(0, Number(scan.completedUnitCount || 0));
  const total = Math.max(1, Number(scan.totalUnitCount || 1));
  const wrapper = progress || document.createElement("span");
  wrapper.className = `slimming-scan-progress${compact ? " compact" : ""}`;
  let track = wrapper.querySelector(":scope > .slimming-scan-progress-track");
  if (!track) {
    track = document.createElement("span");
    track.className = "slimming-scan-progress-track";
  }
  let fill = track.querySelector(":scope > span");
  if (!fill) {
    fill = document.createElement("span");
    track.append(fill);
  }
  fill.style.width = `${Math.min(100, Math.max(0, completed / total * 100))}%`;
  let copy = wrapper.querySelector(
    ':scope > [data-slimming-scan-progress-part="copy"]'
  );
  if (!copy) {
    copy = document.createElement("span");
    copy.dataset.slimmingScanProgressPart = "copy";
  }
  const text = `${slimmingScanPhaseText(scan)} ${completed}/${total}`;
  if (copy.textContent !== text) copy.textContent = text;
  reconcileStableChildren(wrapper, [track, copy]);
  return wrapper;
}

function slimmingClusterPresentation(cluster) {
  const currentMemberCount = Number(cluster.memberCount || 0);
  const originalMemberCount = Number(cluster.originalMemberCount || currentMemberCount);
  const historicalDetail = cluster.isHistoricalProcessedRecord
    ? `原 ${originalMemberCount} 项 · 现 ${currentMemberCount} 项可查看`
    : null;
  if (cluster.isSeedOnlyResult) {
    return {
      title: state.slimming.mediaKind === "video" ? "种子视频" : "种子照片",
      detail: "未找到相似项 · 可继续检查所选项目",
    };
  }
  const video = state.slimming.mediaKind === "video";
  const title = {
    byteIdentical: video ? "完全相同视频" : "完全相同",
    perceptualDuplicate: video ? "代表缩略图重复" : "视觉重复",
    nearDuplicateScene: video ? "相似视频" : "同场景相似",
  }[cluster.kind] || "相似项目";
  const detail = cluster.kind === "byteIdentical"
    ? (video ? "完整视频文件一致" : "内容完全一致")
    : `${cluster.kind === "nearDuplicateScene" ? "相似度" : "匹配度"} ${Math.round(cluster.score * 100)}%`;
  return { title, detail, historicalDetail };
}

function slimmingJobActionKey(jobID, action) {
  if (["pause", "resume"].includes(action)) return `job:${jobID}:primary`;
  return `job:${jobID}:${action}`;
}

function syncSlimmingJobActionButton(button, descriptor) {
  button.type = "button";
  button.className = descriptor.className;
  button.setAttribute("data-slimming-job-action-key", descriptor.key);
  button.dataset.slimmingJobActionId = descriptor.jobID;
  button.dataset.action = descriptor.action;
  button.disabled = descriptor.disabled;
  button.textContent = descriptor.text;
  if (descriptor.title) button.title = descriptor.title;
  else button.removeAttribute("title");
}

function reconcileSlimmingJobActionButtons(container, descriptors) {
  const existing = new Map(
    [...container.children].map((button) => [button.dataset.slimmingJobActionKey, button])
  );
  const wanted = [];
  for (const descriptor of descriptors) {
    const button = existing.get(descriptor.key) || document.createElement("button");
    syncSlimmingJobActionButton(button, descriptor);
    wanted.push(button);
  }
  for (const [index, button] of wanted.entries()) {
    if (container.children[index] !== button) {
      container.insertBefore(button, container.children[index] || null);
    }
  }
  for (const button of [...container.children]) {
    if (!wanted.includes(button)) button.remove();
  }
}

function slimmingJobActionDescriptors(job, { surface }) {
  if (!job) return [];
  const mutating = state.slimming.jobMutatingIDs.has(job.id);
  const options = surface === "options";
  const locked = !state.online || mutating || Boolean(state.slimming.appending);
  const descriptors = [];
  for (const action of job.availableActions || []) {
    if (!["pause", "resume"].includes(action)) continue;
    descriptors.push({
      key: slimmingJobActionKey(job.id, action),
      jobID: job.id,
      action,
      className: `button button-compact write-action${options ? "" : " slimming-job-action"}`,
      disabled: locked,
      text: mutating
        ? (action === "pause" ? "正在暂停…" : "正在继续…")
        : options
          ? (action === "pause" ? "暂停当前" : "继续当前")
          : (action === "pause" ? "暂停" : "继续"),
      title: options
        ? (action === "pause"
          ? "暂停当前分析并保留已经完成的进度"
          : "从保存的进度继续当前分析")
        : null,
    });
  }
  if (job.state !== "running") {
    descriptors.push({
      key: slimmingJobActionKey(job.id, "deleteRecord"),
      jobID: job.id,
      action: "deleteRecord",
      className: `button button-compact button-danger write-action${options ? "" : " slimming-job-action"}`,
      disabled: locked,
      text: options ? "删除当前记录" : "删除记录",
      title: "只删除分析记录和结果，不会删除任何原始媒体",
    });
  }
  return descriptors;
}

function renderSlimmingJobActions() {
  const job = state.slimming.jobs.find((item) => item.id === state.slimming.selectedJobID);
  reconcileSlimmingJobActionButtons(
    elements.slimmingJobActions,
    slimmingJobActionDescriptors(job, { surface: "navigator" })
  );
}

function renderSlimmingCurrentJobControls() {
  const activeAction = document.activeElement?.closest?.(
    "#slimmingCurrentJobActions [data-slimming-job-action-id][data-action]"
  );
  const focusedAction = activeAction
    ? {
      jobID: activeAction.dataset.slimmingJobActionId,
      action: activeAction.dataset.action,
      key: activeAction.dataset.slimmingJobActionKey,
    }
    : null;
  const restoreFocusedAction = () => {
    if (!focusedAction) return;
    const stable = [...elements.slimmingCurrentJobActions.children].find(
      (button) => button.dataset.slimmingJobActionKey === focusedAction.key
    );
    if (stable?.disabled) return;
    const matching = stable || elements.slimmingCurrentJobActions.querySelector(
      `[data-slimming-job-action-id="${CSS.escape(focusedAction.jobID)}"]`
      + `[data-action="${CSS.escape(focusedAction.action)}"]:not(:disabled)`
    );
    const fallback = elements.slimmingCurrentJobActions.querySelector(
      "[data-slimming-job-action-id]:not(:disabled)"
    );
    (matching || fallback || elements.closeSlimmingAnalysisOptionsButton)
      ?.focus({ preventScroll: true });
  };
  const job = selectedSlimmingJob();
  syncSlimmingCurrentJobProgress(job);
  elements.slimmingCurrentJobState.className = "slimming-current-job-state";
  if (!job) {
    if (elements.slimmingCurrentJobSummary.textContent !== "尚未选择分析记录。") {
      elements.slimmingCurrentJobSummary.textContent = "尚未选择分析记录。";
    }
    if (elements.slimmingCurrentJobState.textContent !== "—") {
      elements.slimmingCurrentJobState.textContent = "—";
    }
    reconcileSlimmingJobActionButtons(elements.slimmingCurrentJobActions, []);
    restoreFocusedAction();
    return;
  }

  const sources = job.sourceNames?.length ? job.sourceNames.join("、") : "任务来源不可用";
  const summaryText = `${slimmingModeText(job.mode)} · ${sources}`;
  if (elements.slimmingCurrentJobSummary.textContent !== summaryText) {
    elements.slimmingCurrentJobSummary.textContent = summaryText;
  }
  const stateText = slimmingJobStateText(job);
  if (elements.slimmingCurrentJobState.textContent !== stateText) {
    elements.slimmingCurrentJobState.textContent = stateText;
  }
  elements.slimmingCurrentJobState.classList.add(job.state || "unknown");

  reconcileSlimmingJobActionButtons(
    elements.slimmingCurrentJobActions,
    slimmingJobActionDescriptors(job, { surface: "options" })
  );
  restoreFocusedAction();
}

function syncSlimmingCurrentJobProgress(job) {
  const container = elements.slimmingCurrentJobProgress;
  let progress = container.querySelector(":scope > .slimming-scan-progress");
  if (!job?.scanProgress) {
    progress?.remove();
    container.classList.add("hidden");
    return;
  }
  progress = syncSlimmingScanProgressElement(progress, job);
  reconcileStableChildren(container, [progress]);
  container.classList.remove("hidden");
}

function focusSlimmingCurrentJobAction(jobID, preferredAction = null) {
  requestAnimationFrame(() => {
    if (elements.slimmingAnalysisOptionsPopover.classList.contains("hidden")) return;
    const preferred = preferredAction
      ? elements.slimmingCurrentJobActions.querySelector(
        `[data-slimming-job-action-id="${CSS.escape(jobID)}"]`
        + `[data-action="${CSS.escape(preferredAction)}"]`
      )
      : null;
    const fallback = elements.slimmingCurrentJobActions.querySelector(
      "[data-slimming-job-action-id]:not(:disabled)"
    );
    (preferred || fallback || elements.closeSlimmingAnalysisOptionsButton)
      ?.focus({ preventScroll: true });
  });
}

function focusSlimmingNavigatorJobAction(jobID, preferredAction = null) {
  requestAnimationFrame(() => {
    if (elements.slimmingWorkspace.classList.contains("hidden")) return;
    const preferred = preferredAction
      ? elements.slimmingJobActions.querySelector(
        `[data-slimming-job-action-id="${CSS.escape(jobID)}"]`
        + `[data-action="${CSS.escape(preferredAction)}"]`
      )
      : null;
    const fallback = elements.slimmingJobActions.querySelector(
      "[data-slimming-job-action-id]:not(:disabled)"
    );
    if (preferred || fallback) (preferred || fallback).focus({ preventScroll: true });
    else focusSelectedSlimmingJob();
  });
}

function renderSlimmingJobSummary() {
  const totalCount = totalSlimmingJobCount();
  const loadedCount = state.slimming.jobs.length;
  const hasMore = hasMoreSlimmingJobs();
  const appending = state.slimming.appending === "jobs";
  elements.slimmingJobCount.textContent = `${totalCount} 条`;
  elements.slimmingJobCount.title = hasMore
    ? `已载入 ${loadedCount} / ${totalCount} 条分析记录${appending ? "，正在载入更多" : ""}`
    : `已载入全部 ${totalCount} 条分析记录`;
  const selectedIndex = selectedSlimmingJobIndex();
  elements.slimmingJobPosition.textContent = state.slimming.jobs.length
    ? `${Math.max(0, selectedIndex) + 1} / ${totalCount}`
    : "0 / 0";
  elements.previousSlimmingJobButton.disabled = state.slimming.loading || selectedIndex <= 0;
  elements.nextSlimmingJobButton.disabled = state.slimming.loading
    || selectedIndex < 0
    || (selectedIndex >= state.slimming.jobs.length - 1 && !hasMore);
  elements.slimmingLoadMoreJobsButton.classList.toggle("hidden", !hasMore && !appending);
  elements.slimmingLoadMoreJobsButton.disabled = state.slimming.loading;
  elements.slimmingLoadMoreJobsButton.textContent = appending
    ? "正在载入更多记录…"
    : hasMore
      ? `载入更多记录（剩余 ${Math.max(0, totalCount - loadedCount)}）`
      : "已载入全部记录";
  elements.slimmingLoadMoreJobsButton.setAttribute("aria-busy", String(appending));
  elements.slimmingEmpty.classList.toggle(
    "hidden",
    (state.slimming.loading && !appending) || state.slimming.jobs.length > 0
  );
  const activeCount = state.slimming.jobs.filter(
    (job) => ["pending", "running", "paused", "retryableFailed"].includes(job.state)
  ).length;
  elements.slimmingNavigationCount.textContent = activeCount ? String(activeCount) : "";
}

function syncSlimmingJobRowProgress(row, job) {
  let progress = row.querySelector(
    ':scope > [data-slimming-job-row-part="progress"]'
  );
  if (!job.scanProgress) {
    progress?.remove();
    return null;
  }
  progress = syncSlimmingScanProgressElement(progress, job, true);
  progress.dataset.slimmingJobRowPart = "progress";
  return progress;
}

function syncSlimmingJobRow(row, job) {
  const fingerprint = JSON.stringify({
    job,
    selected: job.id === state.slimming.selectedJobID,
  });
  if (row.dataset.slimmingFingerprint === fingerprint) return row;
  row.type = "button";
  row.className = "slimming-job-row";
  row.dataset.slimmingJobId = job.id;
  row.id = `slimming-job-${job.id}`;
  row.classList.toggle("selected", job.id === state.slimming.selectedJobID);
  row.setAttribute("role", "option");
  row.setAttribute("aria-selected", String(job.id === state.slimming.selectedJobID));
  row.tabIndex = job.id === state.slimming.selectedJobID ? 0 : -1;
  configurePersistentHelp(row, {
    title: `${slimmingModeText(job.mode)} · ${slimmingJobStateText(job)}`,
    detail: "上/下或左/右逐条移动，Page Up/Down 按当前可见页幅移动，Home/End 直达首尾；选择后读取该分析结果。",
    kind: "slimming",
    keyShortcuts: "ArrowLeft ArrowRight ArrowUp ArrowDown PageUp PageDown Home End Shift+F10",
  });
  let heading = row.querySelector(
    ':scope > [data-slimming-job-row-part="heading"]'
  );
  if (!heading) {
    heading = document.createElement("span");
    heading.dataset.slimmingJobRowPart = "heading";
    heading.className = "slimming-row-heading";
  }
  let title = heading.querySelector(
    ':scope > [data-slimming-job-row-heading-part="title"]'
  );
  if (!title) {
    title = document.createElement("strong");
    title.dataset.slimmingJobRowHeadingPart = "title";
  }
  const titleText = slimmingModeText(job.mode);
  if (title.textContent !== titleText) title.textContent = titleText;
  let status = heading.querySelector(
    ':scope > [data-slimming-job-row-heading-part="status"]'
  );
  if (!status) {
    status = document.createElement("span");
    status.dataset.slimmingJobRowHeadingPart = "status";
  }
  status.className = `slimming-state ${job.state}`;
  const statusText = slimmingJobStateText(job);
  if (status.textContent !== statusText) status.textContent = statusText;
  reconcileStableChildren(heading, [title, status]);
  let counts = row.querySelector(
    ':scope > [data-slimming-job-row-part="counts"]'
  );
  if (!counts) {
    counts = document.createElement("span");
    counts.dataset.slimmingJobRowPart = "counts";
    counts.className = "slimming-row-detail";
  }
  const unit = job.mediaKind === "video" ? "个视频" : "张照片";
  const countParts = [`${job.memberCount} ${unit}`];
  if (job.seedCount > 0) countParts.push(`种子 ${job.seedCount}`);
  if (job.hasResult) countParts.push(`${job.clusterCount} 个簇`);
  countParts.push(`尝试 ${job.attempts}/${job.maxAttempts}`);
  const countText = countParts.join(" · ");
  if (counts.textContent !== countText) counts.textContent = countText;
  const progress = syncSlimmingJobRowProgress(row, job);
  let source = row.querySelector(
    ':scope > [data-slimming-job-row-part="source"]'
  );
  if (!source) {
    source = document.createElement("span");
    source.dataset.slimmingJobRowPart = "source";
    source.className = "slimming-row-detail";
  }
  const sourceText = job.sourceNames?.length
    ? job.sourceNames.join(" · ")
    : "全部可用来源";
  if (source.textContent !== sourceText) source.textContent = sourceText;
  let date = row.querySelector(
    ':scope > [data-slimming-job-row-part="date"]'
  );
  if (!date) {
    date = document.createElement("span");
    date.dataset.slimmingJobRowPart = "date";
    date.className = "slimming-row-date";
  }
  const dateText = formatDate(job.updatedAtMs);
  if (date.textContent !== dateText) date.textContent = dateText;
  reconcileStableChildren(
    row,
    [heading, counts, progress, source, date].filter(Boolean)
  );
  row.dataset.slimmingFingerprint = fingerprint;
  return row;
}

function appendSlimmingJobRows(jobs) {
  const fragment = document.createDocumentFragment();
  for (const job of jobs) {
    fragment.append(syncSlimmingJobRow(document.createElement("button"), job));
  }
  elements.slimmingJobList.append(fragment);
}

function renderSlimmingJobs({ appendItems = null } = {}) {
  renderSlimmingJobSummary();
  if (appendItems !== null) {
    appendSlimmingJobRows(appendItems);
  } else {
    const existingRows = new Map(
      [...elements.slimmingJobList.querySelectorAll(":scope > [data-slimming-job-id]")]
        .map((row) => [row.dataset.slimmingJobId, row])
    );
    for (const [index, job] of state.slimming.jobs.entries()) {
      const row = existingRows.get(job.id) || document.createElement("button");
      existingRows.delete(job.id);
      syncSlimmingJobRow(row, job);
      const currentRow = elements.slimmingJobList.children[index] || null;
      if (currentRow !== row) elements.slimmingJobList.insertBefore(row, currentRow);
    }
    for (const row of existingRows.values()) row.remove();
  }
  renderSlimmingJobActions();
}

function slimmingJobStatusPart(key, tagName, className) {
  let part = elements.slimmingJobStatus.querySelector(
    `:scope > [data-slimming-job-status-part="${key}"]`
  );
  if (!part) {
    part = document.createElement(tagName);
    part.dataset.slimmingJobStatusPart = key;
  }
  part.className = className;
  return part;
}

function reconcileStableChildren(container, wanted) {
  for (const [index, child] of wanted.entries()) {
    if (container.childNodes[index] !== child) {
      container.insertBefore(child, container.childNodes[index] || null);
    }
  }
  for (const child of [...container.childNodes]) {
    if (!wanted.includes(child)) child.remove();
  }
}

function syncSlimmingJobStatusProgress(job) {
  if (!job.scanProgress) return null;
  const progress = slimmingJobStatusPart(
    "progress",
    "span",
    "slimming-scan-progress"
  );
  let track = progress.querySelector(":scope > .slimming-scan-progress-track");
  if (!track) {
    track = document.createElement("span");
    track.className = "slimming-scan-progress-track";
  }
  let fill = track.querySelector(":scope > span");
  if (!fill) {
    fill = document.createElement("span");
    track.append(fill);
  }
  let copy = progress.querySelector(":scope > span:not(.slimming-scan-progress-track)");
  if (!copy) copy = document.createElement("span");
  const completed = Math.max(0, Number(job.scanProgress.completedUnitCount || 0));
  const total = Math.max(1, Number(job.scanProgress.totalUnitCount || 1));
  fill.style.width = `${Math.min(100, Math.max(0, completed / total * 100))}%`;
  copy.textContent = `${slimmingScanPhaseText(job.scanProgress)} ${completed}/${total}`;
  reconcileStableChildren(progress, [track, copy]);
  return progress;
}

function syncSlimmingJobStatusActions(job) {
  const actions = slimmingJobStatusPart(
    "actions",
    "span",
    "slimming-job-status-actions"
  );
  let activity = actions.querySelector('[data-slimming-job-status-action="activity"]');
  if (!activity) {
    activity = document.createElement("button");
    activity.type = "button";
    activity.className = "button button-compact";
    activity.dataset.slimmingJobStatusAction = "activity";
  }
  activity.dataset.openJobActivityId = job.id;
  activity.textContent = "在任务中查看";
  const wanted = [activity];
  if (job.state === "retryableFailed" && job.availableActions?.includes("resume")) {
    let resume = actions.querySelector('[data-slimming-job-status-action="resume"]');
    if (!resume) {
      resume = document.createElement("button");
      resume.type = "button";
      resume.className = "button button-compact write-action";
      resume.dataset.slimmingJobStatusAction = "resume";
    }
    resume.dataset.slimmingJobActionId = job.id;
    resume.dataset.action = "resume";
    resume.textContent = "继续分析";
    wanted.push(resume);
  }
  reconcileStableChildren(actions, wanted);
  return actions;
}

function syncSlimmingJobStatusDiagnosis(job) {
  if (!["retryableFailed", "terminalFailed"].includes(job.state)) return null;
  const diagnosis = slimmingJobStatusPart(
    "diagnosis",
    "span",
    "slimming-job-diagnosis"
  );
  let copy = diagnosis.querySelector(':scope > [data-slimming-job-status-diagnosis="copy"]');
  if (!copy) {
    copy = document.createElement("span");
    copy.dataset.slimmingJobStatusDiagnosis = "copy";
  }
  copy.textContent = jobFailureGuidance(job);
  const wanted = [copy];
  if (job.lastErrorCode) {
    let code = diagnosis.querySelector(":scope > code");
    if (!code) code = document.createElement("code");
    code.textContent = job.lastErrorCode;
    wanted.push(document.createTextNode(" "), code);
  }
  reconcileStableChildren(diagnosis, wanted);
  return diagnosis;
}

function reconcileSlimmingJobStatusParts(parts) {
  reconcileStableChildren(elements.slimmingJobStatus, parts);
}

function renderSlimmingJobStatus() {
  const job = selectedSlimmingJob();
  const visible = job && [
    "pending", "running", "paused", "retryableFailed", "terminalFailed", "cancelled",
  ].includes(job.state);
  elements.slimmingJobStatus.classList.toggle("hidden", !visible);
  if (!visible) {
    reconcileSlimmingJobStatusParts([]);
    delete elements.slimmingJobStatus.dataset.slimmingJobStatusJobId;
    return;
  }
  if (elements.slimmingJobStatus.dataset.slimmingJobStatusJobId !== job.id) {
    reconcileSlimmingJobStatusParts([]);
    elements.slimmingJobStatus.dataset.slimmingJobStatusJobId = job.id;
  }
  elements.slimmingJobStatus.className = `slimming-job-status ${job.state}`;
  const parts = [];
  const copy = slimmingJobStatusPart("copy", "div", "slimming-job-status-copy");
  let heading = copy.querySelector(":scope > strong");
  if (!heading) heading = document.createElement("strong");
  heading.textContent = slimmingJobStateText(job);
  let detail = copy.querySelector(":scope > span");
  if (!detail) detail = document.createElement("span");
  const source = job.sourceNames?.length ? job.sourceNames.join("、") : "任务来源不可用";
  detail.textContent = `${slimmingModeText(job.mode)} · ${source} · 尝试 ${job.attempts}/${job.maxAttempts}`;
  reconcileStableChildren(copy, [heading, detail]);
  parts.push(copy);
  const progress = syncSlimmingJobStatusProgress(job);
  if (progress) parts.push(progress);
  parts.push(syncSlimmingJobStatusActions(job));
  if (["pending", "running"].includes(job.state)) {
    const guard = slimmingJobStatusPart("guard", "span", "slimming-job-guard");
    guard.textContent = "分析完成或暂停前，一键清理保持锁定";
    parts.push(guard);
  }
  const diagnosis = syncSlimmingJobStatusDiagnosis(job);
  if (diagnosis) parts.push(diagnosis);
  reconcileSlimmingJobStatusParts(parts);
}

function focusSlimmingJobStatusAction(jobID, preferredAction = null) {
  requestAnimationFrame(() => {
    if (selectedSlimmingJob()?.id !== jobID
      || elements.slimmingJobStatus.classList.contains("hidden")) return;
    const preferred = preferredAction
      ? elements.slimmingJobStatus.querySelector(
        `[data-slimming-job-action-id="${CSS.escape(jobID)}"]`
        + `[data-action="${CSS.escape(preferredAction)}"]:not(:disabled)`
      )
      : null;
    const activity = elements.slimmingJobStatus.querySelector(
      `[data-open-job-activity-id="${CSS.escape(jobID)}"]:not(:disabled)`
    );
    (preferred || activity)?.focus({ preventScroll: true });
  });
}

function reconcileSlimmingInspectorFields(target, fields) {
  const existing = new Map(
    [...target.querySelectorAll(":scope > [data-slimming-inspector-field-key]")]
      .map((wrapper) => [wrapper.dataset.slimmingInspectorFieldKey, wrapper])
  );
  const wanted = fields.map((field) => {
    const wrapper = existing.get(field.key) || document.createElement("div");
    existing.delete(field.key);
    if (!wrapper.hasAttribute("data-slimming-inspector-field-key")) {
      wrapper.append(document.createElement("dt"), document.createElement("dd"));
    }
    wrapper.dataset.slimmingInspectorFieldKey = field.key;
    const className = `slimming-inspector-field${field.className ? ` ${field.className}` : ""}`;
    if (wrapper.className !== className) wrapper.className = className;
    const term = wrapper.querySelector(":scope > dt");
    const detail = wrapper.querySelector(":scope > dd");
    if (term.textContent !== field.label) term.textContent = field.label;
    const value = field.value || "—";
    if (detail.textContent !== value) detail.textContent = value;
    return wrapper;
  });
  reconcileStableChildren(target, wanted);
}

function slimmingInspectorScopeTitle() {
  const noun = state.slimming.mediaKind === "video" ? "视频" : "照片";
  if (state.libraryScope === "worldMapGallery" && state.worldMapGalleryScope) {
    return `${state.worldMapGalleryScope.displayName} · 照片世界`;
  }
  if (state.folderScope) {
    const source = state.sources.find(
      (candidate) => candidate.id === state.folderScope.sourceID
    );
    if (source) {
      return [source.displayName, ...state.folderScope.relativePath.split("/").filter(Boolean)]
        .join(" › ");
    }
  }
  const source = state.sources.find((candidate) => candidate.id === state.selectedSourceID);
  if (source) return source.displayName;
  if (state.filters.tagPresence === "untagged") return `无标签${noun}`;
  if (state.libraryScope === "favorites") return `红心${noun}`;
  return `全部${noun}`;
}

function slimmingInspectorTagFilterSummary() {
  const included = state.filters.tagConditions
    .filter((condition) => condition.decision !== "excluded")
    .map((condition) => tagByID(condition.tagID)?.displayName)
    .filter(Boolean)
    .sort((left, right) => left.localeCompare(right, "zh-CN"));
  const excluded = state.filters.tagConditions
    .filter((condition) => condition.decision === "excluded")
    .map((condition) => tagByID(condition.tagID)?.displayName)
    .filter(Boolean)
    .sort((left, right) => left.localeCompare(right, "zh-CN"));
  const parts = [];
  if (included.length) {
    parts.push(included.join(state.filters.tagMatchMode === "all" ? " 且 " : " 或 "));
  }
  if (excluded.length) parts.push(`排除 ${excluded.join("、")}`);
  return parts.join(" · ");
}

function slimmingInspectorFilterScopeSummary() {
  const parts = [slimmingInspectorScopeTitle()];
  const tagSummary = slimmingInspectorTagFilterSummary();
  if (tagSummary) parts.push(tagSummary);
  const searchText = state.searchText.trim();
  if (searchText) parts.push(`搜索「${searchText}」`);
  if (state.filters.availabilities.length) {
    parts.push(`可用性：${state.filters.availabilities.map(availabilityText).join("、")}`);
  }
  if (state.filters.mediaTypes.length) parts.push("格式筛选");
  return parts.join(" · ");
}

function slimmingInspectorSourceIndexValue() {
  const snapshot = currentSlimmingCatalogSnapshot();
  if (snapshot?.sourceSimilarityIndexAvailable !== true) return null;
  if (!state.selectedSourceID) return "请选择单个来源";
  const source = snapshot.sources?.find(
    (candidate) => candidate.id === state.selectedSourceID
  );
  if (!source) return "未初始化";
  return slimmingSourceIndexCaption(source, true).replace(/^来源索引：/, "");
}

function renderSlimmingInspector() {
  const job = selectedSlimmingJob();
  const cluster = state.slimming.clusters.find(
    (item) => item.id === state.slimming.selectedClusterID
  ) || null;
  const clusterCopy = cluster ? slimmingClusterPresentation(cluster) : null;
  const sourceNames = [...new Set(
    state.slimming.members.map((member) => member.sourceName).filter(Boolean)
  )];
  elements.slimmingInspectorSummary.textContent = clusterCopy?.title
    || (job ? `${slimmingModeText(job.mode)} · ${slimmingJobStateText(job)}` : "分析概览");
  const isVideo = state.slimming.mediaKind === "video";
  elements.inspectorSlimmingWorkspaceDescription.textContent = isVideo
    ? "按代表缩略图查找视觉重复或相似的视频；分析和清理均由这台 Mac 执行。"
    : "查找相同与相似照片；分析和清理均由这台 Mac 执行。";

  const fields = [
    { key: "jobs", label: "分析记录", value: `${totalSlimmingJobCount()} 条` },
    {
      key: "job",
      label: "当前任务",
      value: job ? slimmingModeText(job.mode) : "未选择",
    },
    { key: "state", label: "状态", value: job ? slimmingJobStateText(job) : "—" },
    {
      key: "attempts",
      label: "尝试次数",
      value: job ? `${job.attempts}/${job.maxAttempts}` : "—",
    },
    {
      key: "jobSources",
      label: "任务来源",
      value: job?.sourceNames?.length ? job.sourceNames.join("、") : "任务来源不可用",
      className: "technical",
    },
    {
      key: "scope",
      label: "分析范围",
      value: job ? `${job.memberCount} ${job.mediaKind === "video" ? "个" : "张"}` : "—",
    },
  ];
  if (Number(job?.seedCount || 0) > 0) {
    fields.push({
      key: "seeds",
      label: "种子",
      value: `${job.seedCount} ${job.mediaKind === "video" ? "个" : "张"}`,
    });
  } else if (!job && currentSlimmingSeedIDs().length > 0) {
    fields.push({
      key: "pendingSeeds",
      label: "待用种子",
      value: `${currentSlimmingSeedIDs().length} ${
        state.slimming.mediaKind === "video" ? "个" : "张"
      }`,
    });
  }
  const activeMode = job?.mode || state.slimming.quickLaunchMode;
  if (["currentFilter", "seeds"].includes(activeMode)) {
    fields.push({
      key: "filter",
      label: "筛选",
      value: slimmingInspectorFilterScopeSummary(),
    });
  }
  const sourceIndexValue = slimmingInspectorSourceIndexValue();
  fields.push(
    { key: "analyzed", label: "已分析", value: `${state.slimming.analyzedAssetCount} 项` },
    { key: "pending", label: "待分析", value: `${state.slimming.pendingAnalysisCount} 项` },
    {
      key: "recycle",
      label: "回收站",
      value: `${Number(
        state.slimming.recycle.totalCount || state.slimming.recycle.entries.length
      )} 项`,
    },
    { key: "policy", label: "策略版本", value: state.slimming.policyVersion || "—" },
    ...(sourceIndexValue == null ? [] : [{
      key: "sourceIndex",
      label: "来源索引",
      value: sourceIndexValue,
    }])
  );

  if (cluster) {
    fields.push(
      { key: "clusterType", label: "类型", value: clusterCopy.title },
      {
        key: "members",
        label: "成员",
        value: clusterCopy.historicalDetail || `${cluster.memberCount} 项`,
      },
      { key: "selected", label: "已选", value: `${state.slimming.selectedMemberIDs.size} 项` },
      { key: "sources", label: "来源", value: sourceNames.join("、") || "正在读取…" },
      { key: "result", label: "结果", value: clusterCopy.detail, className: "technical" },
      {
        key: "technical",
        label: "技术详情",
        value: cluster.technicalSummary || "技术摘要不可用",
        className: "technical",
      }
    );
  }
  for (const target of [
    elements.slimmingInspectorContent,
    elements.inspectorSlimmingWorkspaceContent,
  ]) {
    reconcileSlimmingInspectorFields(target, fields);
  }
  const pendingCount = Number(state.slimming.pendingAnalysisCount || 0);
  elements.inspectorSlimmingWorkspacePending.classList.toggle("hidden", pendingCount === 0);
  elements.inspectorSlimmingWorkspacePending.textContent = pendingCount
    ? `有 ${pendingCount} ${isVideo ? "个视频" : "张照片"}缺少分析特征，已标为待分析。`
    : "";
}

function renderSlimmingClusterScopes() {
  const supported = state.slimming.clusterScopeSupported;
  for (const button of elements.slimmingClusterScopes.querySelectorAll(
    "[data-slimming-cluster-scope]"
  )) {
    const scope = button.dataset.slimmingClusterScope;
    const advancedUnavailable = supported === false && scope !== "pending";
    const count = supported === false && scope !== "pending"
      ? "—"
      : Number(state.slimming.clusterScopeCounts?.[scope] || 0).toLocaleString();
    button.setAttribute("aria-pressed", String(scope === state.slimming.clusterScope));
    button.disabled = state.slimming.loading || advancedUnavailable;
    button.title = advancedUnavailable
      ? "需要新版 Mac Host 才能读取此审阅队列"
      : `${slimmingClusterScopeText(scope)}，${count} 组`;
    button.querySelector("[data-slimming-cluster-scope-count]").textContent = count;
  }
  syncRovingSegmentedControl(
    elements.slimmingClusterScopes,
    "[data-slimming-cluster-scope]"
  );
}

function syncSlimmingClusterReviewButton(
  button,
  cluster,
  disposition,
  label,
  symbol
) {
  const active = cluster.reviewDisposition === disposition;
  const pending = state.slimming.clusterReviewPendingIDs.has(cluster.id);
  button.type = "button";
  button.className = "slimming-cluster-review-button write-action";
  button.dataset.slimmingClusterReview = disposition;
  button.dataset.slimmingClusterReviewId = cluster.id;
  button.setAttribute("aria-pressed", String(active));
  button.setAttribute("aria-label", active ? `当前为${label}` : `设为${label}`);
  button.title = active ? `当前为${label}` : `将分组移入${label}队列`;
  button.disabled = !state.online || pending || active;
  let icon = button.querySelector(":scope > [data-slimming-cluster-review-part=icon]");
  if (!icon) {
    icon = document.createElement("span");
    icon.dataset.slimmingClusterReviewPart = "icon";
  }
  icon.setAttribute("aria-hidden", "true");
  icon.textContent = pending ? "…" : symbol;
  let copy = button.querySelector(":scope > [data-slimming-cluster-review-part=label]");
  if (!copy) {
    copy = document.createElement("span");
    copy.dataset.slimmingClusterReviewPart = "label";
  }
  copy.textContent = label;
  reconcileStableChildren(button, [icon, copy]);
}

function reconcileSlimmingClusterReviewButtons(container, cluster) {
  const descriptors = [
    { disposition: "confirmed", label: "已确认", symbol: "✓" },
    { disposition: "ignored", label: "忽略", symbol: "⊘" },
  ];
  const existing = new Map(
    [...container.querySelectorAll(":scope > [data-slimming-cluster-review]")]
      .map((button) => [button.dataset.slimmingClusterReview, button])
  );
  const buttons = descriptors.map(({ disposition, label, symbol }) => {
    const button = existing.get(disposition) || document.createElement("button");
    syncSlimmingClusterReviewButton(button, cluster, disposition, label, symbol);
    return button;
  });
  reconcileStableChildren(container, buttons);
}

function renderSlimmingSelectedClusterReview(cluster) {
  const supported = state.slimming.clusterScopeSupported === true;
  const disposition = cluster?.reviewDisposition || null;
  const pending = cluster && state.slimming.clusterReviewPendingIDs.has(cluster.id);
  const visible = Boolean(supported && cluster && disposition);
  elements.slimmingSelectedClusterReview.classList.toggle("hidden", !visible);
  if (!visible) {
    elements.slimmingSelectedClusterReviewStatus.textContent = "";
    elements.slimmingSelectedClusterReviewStatus.removeAttribute("data-disposition");
    return;
  }
  elements.slimmingSelectedClusterReviewStatus.dataset.disposition = disposition;
  elements.slimmingSelectedClusterReviewStatus.textContent = disposition === "confirmed"
    ? "✓ 已确认"
    : "⊘ 已忽略";
  elements.slimmingReprocessClusterButton.disabled = !state.online || pending;
  elements.slimmingReprocessClusterButton.dataset.slimmingClusterReviewId = cluster.id;
  elements.slimmingReprocessClusterButton.textContent = pending ? "正在保存…" : "重新处理";
}

function totalSlimmingClusterCount() {
  return state.slimming.clusterScopeSupported === true
    ? Number(state.slimming.clusterScopeCounts?.[state.slimming.clusterScope] || 0)
    : state.slimming.clusters.length;
}

function renderSlimmingClusterSummary() {
  renderSlimmingClusterScopes();
  elements.slimmingClusterScopeTitle.textContent = slimmingClusterScopeText(
    state.slimming.clusterScope
  );
  const totalClusterCount = totalSlimmingClusterCount();
  const appending = state.slimming.appending === "clusters";
  elements.slimmingClusterCount.textContent = totalClusterCount > state.slimming.clusters.length
    ? `${state.slimming.clusters.length} / ${totalClusterCount} 组${appending ? " · 正在载入更多…" : ""}`
    : `${state.slimming.clusters.length} 组`;
  elements.slimmingLoadMoreClustersButton.classList.toggle(
    "hidden",
    !appending && state.slimming.clusters.length >= totalClusterCount
  );
  elements.slimmingLoadMoreClustersButton.disabled = state.slimming.loading;
  elements.slimmingLoadMoreClustersButton.textContent = appending
    ? "正在载入更多分组…"
    : `显示更多分组（剩余 ${Math.max(0, totalClusterCount - state.slimming.clusters.length)}）`;
  elements.slimmingLoadMoreClustersButton.setAttribute("aria-busy", String(appending));
  elements.slimmingClusterEmpty.classList.toggle(
    "hidden",
    (state.slimming.loading && !appending)
      || !state.slimming.selectedJobID
      || state.slimming.clusters.length > 0
  );
  const emptyTitle = elements.slimmingClusterEmpty.querySelector("strong");
  const emptyMessage = elements.slimmingClusterEmpty.querySelector("p");
  if (state.slimming.selectedJobID && state.slimming.clusterScopeSupported === true) {
    emptyTitle.textContent = `${slimmingClusterScopeText(state.slimming.clusterScope)}队列为空`;
    emptyMessage.textContent = state.slimming.clusterScope === "pending"
      ? "此记录没有尚待处理的重复或相似分组。"
      : `此记录没有${slimmingClusterScopeText(state.slimming.clusterScope)}的分组。`;
  } else {
    emptyTitle.textContent = "没有候选分组";
    emptyMessage.textContent = "此记录未发现重复或相似项目。";
  }
}

function slimmingClusterRovingID() {
  return state.slimming.clusters.some(
    (cluster) => cluster.id === state.slimming.selectedClusterID
  )
    ? state.slimming.selectedClusterID
    : state.slimming.clusters[0]?.id || null;
}

function syncSlimmingClusterRow(row, cluster) {
  const isTabStop = cluster.id === slimmingClusterRovingID();
  const fingerprint = JSON.stringify({
    cluster,
    selected: cluster.id === state.slimming.selectedClusterID,
    isTabStop,
    reviewSupported: state.slimming.clusterScopeSupported === true,
    reviewPending: state.slimming.clusterReviewPendingIDs.has(cluster.id),
    online: state.online,
  });
  if (row.dataset.slimmingFingerprint === fingerprint) return row;
  const copy = slimmingClusterPresentation(cluster);
  row.className = "slimming-cluster-row";
  row.dataset.slimmingClusterRowId = cluster.id;
  row.classList.toggle("selected", cluster.id === state.slimming.selectedClusterID);
  row.setAttribute("role", "listitem");
  const main = row.querySelector(":scope > .slimming-cluster-main")
    || document.createElement("button");
  main.type = "button";
  main.className = "slimming-cluster-main";
  main.dataset.slimmingClusterId = cluster.id;
  main.setAttribute("aria-pressed", String(cluster.id === state.slimming.selectedClusterID));
  main.setAttribute("aria-label", `${copy.title}，${cluster.memberCount} 项，${copy.detail}`);
  main.tabIndex = isTabStop ? 0 : -1;
  configurePersistentHelp(main, {
    title: `${copy.title} · ${cluster.memberCount} 项`,
    detail: "上/下逐组移动，Page Up/Down 按当前可见页幅移动，Home/End 直达首尾；选择后读取该组成员。",
    kind: "slimming",
    keyShortcuts: "ArrowUp ArrowDown PageUp PageDown Home End",
  });
  const historical = cluster.isHistoricalProcessedRecord
    && Number(cluster.memberCount || 0) === 0;
  const existingVisual = main.querySelector(
    ":scope > img, :scope > .slimming-cluster-history-mark"
  );
  const reusesVisual = historical
    ? existingVisual instanceof HTMLSpanElement
    : existingVisual instanceof HTMLImageElement;
  const image = reusesVisual
    ? existingVisual
    : historical
      ? document.createElement("span")
      : document.createElement("img");
  if (!reusesVisual && existingVisual instanceof HTMLImageElement) {
    clearProtectedImageSource(existingVisual);
  }
  if (image instanceof HTMLImageElement) {
    image.loading = "lazy";
    image.alt = "";
    image.setAttribute("aria-hidden", "true");
    syncProtectedThumbnailSource(image, cluster.representativeAssetID, {
      width: 180,
      revision: 0,
    });
  } else {
    image.className = "slimming-cluster-history-mark";
    image.setAttribute("aria-hidden", "true");
    image.textContent = "✓";
  }
  const text = main.querySelector(":scope > .slimming-cluster-copy")
    || document.createElement("span");
  text.className = "slimming-cluster-copy";
  const title = text.querySelector(":scope > strong") || document.createElement("strong");
  title.textContent = cluster.isHistoricalProcessedRecord
    ? `${copy.title} · ${copy.historicalDetail}`
    : `${copy.title} · ${cluster.memberCount} 项`;
  const detail = text.querySelector(":scope > span") || document.createElement("span");
  detail.textContent = cluster.isHistoricalProcessedRecord
    ? `历史处理记录 · ${copy.detail}`
    : copy.detail;
  reconcileStableChildren(text, [title, detail]);
  reconcileStableChildren(main, [image, text]);
  const children = [main];
  if (state.slimming.clusterScopeSupported === true) {
    const actions = row.querySelector(":scope > .slimming-cluster-review-actions")
      || document.createElement("span");
    actions.className = "slimming-cluster-review-actions";
    reconcileSlimmingClusterReviewButtons(actions, cluster);
    children.push(actions);
  }
  reconcileStableChildren(row, children);
  row.dataset.slimmingFingerprint = fingerprint;
  return row;
}

function appendSlimmingClusterRows(clusters) {
  const fragment = document.createDocumentFragment();
  for (const cluster of clusters) {
    fragment.append(syncSlimmingClusterRow(document.createElement("div"), cluster));
  }
  elements.slimmingClusterList.append(fragment);
}

function renderSlimmingClusters({ appendItems = null } = {}) {
  renderSlimmingClusterSummary();
  if (appendItems !== null) {
    appendSlimmingClusterRows(appendItems);
    return;
  }
  const existingRows = new Map(
    [...elements.slimmingClusterList.querySelectorAll(
      ":scope > .slimming-cluster-row[data-slimming-cluster-row-id]"
    )].map((row) => [row.dataset.slimmingClusterRowId, row])
  );
  for (const [index, cluster] of state.slimming.clusters.entries()) {
    const row = existingRows.get(cluster.id) || document.createElement("div");
    existingRows.delete(cluster.id);
    syncSlimmingClusterRow(row, cluster);
    const currentRow = elements.slimmingClusterList.children[index] || null;
    if (currentRow !== row) elements.slimmingClusterList.insertBefore(row, currentRow);
  }
  for (const row of existingRows.values()) row.remove();
}

function syncSlimmingSelectionModeControls() {
  const available = state.slimming.view === "analysis"
    && state.slimming.members.length > 0;
  if (!available) state.slimming.selectionMode = false;
  const active = available && state.slimming.selectionMode;
  const selectedCount = state.slimming.selectedMemberIDs.size;
  elements.slimmingWorkspace.classList.toggle("touch-selection-mode", active);
  elements.slimmingSelectionModeButton.classList.toggle("hidden", !available);
  const blocksSelection = state.slimming.loading && !state.slimming.appending;
  elements.slimmingSelectionModeButton.disabled = blocksSelection;
  elements.slimmingSelectionModeButton.setAttribute("aria-pressed", String(active));
  elements.slimmingSelectionModeButton.textContent = active ? "完成" : "选择";
  elements.slimmingSelectionModeButton.title = active
    ? `结束触控多选${selectedCount ? `，当前已选择 ${selectedCount} 项` : ""}`
    : "进入触控多选模式";
  elements.slimmingSelectionModeButton.setAttribute(
    "aria-label",
    active
      ? `完成多选${selectedCount ? `，当前已选择 ${selectedCount} 项` : ""}`
      : "选择多个瘦身候选项目"
  );
  elements.slimmingSelectAllButton.classList.toggle("hidden", !active);
  elements.slimmingSelectAllButton.disabled = blocksSelection
    || selectedCount === state.slimming.members.length;
}

function setSlimmingSelectionMode(enabled, { restoreFocus = true } = {}) {
  state.gridDoubleClickSelectionSnapshot = null;
  const available = state.slimming.view === "analysis"
    && state.slimming.members.length > 0;
  const next = Boolean(enabled) && available;
  if (next === state.slimming.selectionMode) {
    syncSlimmingSelectionModeControls();
    return;
  }
  state.slimming.selectionMode = next;
  if (next && state.slimming.selectedMemberIDs.size === 0) {
    const memberID = state.slimming.selectionAnchorID || state.slimming.members[0]?.id;
    if (memberID) {
      state.slimming.selectedMemberIDs = new Set([memberID]);
      state.slimming.selectionAnchorID = memberID;
    }
  } else if (!next && state.slimming.members.length > 0) {
    const memberIDs = new Set(state.slimming.members.map((member) => member.id));
    let memberID = state.slimming.selectionAnchorID;
    if (!memberID || !state.slimming.selectedMemberIDs.has(memberID)) {
      memberID = [...state.slimming.selectedMemberIDs].find((id) => memberIDs.has(id)) || null;
    }
    if (!memberID) memberID = state.slimming.members[0]?.id || null;
    state.slimming.selectedMemberIDs = memberID ? new Set([memberID]) : new Set();
    state.slimming.selectionAnchorID = memberID;
  }
  renderSlimmingMemberSelection();
  if (restoreFocus) {
    elements.slimmingSelectionModeButton.focus({ preventScroll: true });
  }
}

function renderSlimmingMemberSelection({ renderInspector = true } = {}) {
  for (const card of elements.slimmingMemberGrid.querySelectorAll("[data-slimming-member-id]")) {
    const selected = state.slimming.selectedMemberIDs.has(card.dataset.slimmingMemberId);
    card.classList.toggle("selected", selected);
    slimmingMemberMainButton(card)?.setAttribute("aria-pressed", String(selected));
    syncSlimmingMemberFavoriteButton(
      card,
      state.slimming.members.find((member) => member.id === card.dataset.slimmingMemberId)
    );
  }
  syncSlimmingMemberGridTabStops();
  const selectedCount = state.slimming.selectedMemberIDs.size;
  const protection = removalFavoriteProtectionPlan([...state.slimming.selectedMemberIDs]);
  elements.slimmingSelectionSummary.textContent = selectedCount
    ? `已选择 ${selectedCount} 项${protection.favoriteProtectedAssetIDs.length ? ` · 保留 ${protection.favoriteProtectedAssetIDs.length} 项红心` : ""}`
    : "";
  elements.slimmingSelectionBar.classList.toggle("hidden", selectedCount === 0);
  elements.slimmingSelectionBarSummary.textContent = `已选择 ${selectedCount} 项`;
  syncSlimmingSelectionModeControls();
  const active = currentSlimmingRemovalRequest()?.phase;
  const identicalActive = currentSlimmingIdenticalCleanupRequest()?.phase;
  const unavailable = state.slimming.removal.submitting
    || Boolean(state.slimming.appending)
    || active === "awaitingMac"
    || active === "running"
    || identicalActive === "awaitingMac"
    || identicalActive === "running"
    || protection.unverifiableAssetIDs.length > 0;
  const noRemovalCandidates = protection.removalAssetIDs.length === 0;
  elements.slimmingMoveToRecycleButton.disabled = unavailable || noRemovalCandidates;
  elements.slimmingReleaseSpaceButton.disabled = unavailable || noRemovalCandidates;
  elements.slimmingMoveToRecycleButton.textContent = protection.removalAssetIDs.length > 0
    ? `移入可恢复回收站 (${protection.removalAssetIDs.length})`
    : "移入可恢复回收站";
  elements.slimmingReleaseSpaceButton.textContent = protection.removalAssetIDs.length > 0
    ? `快速删除 (${protection.removalAssetIDs.length})`
    : "快速删除";
  const removalHelp = protection.unverifiableAssetIDs.length
    ? "无法核验红心保护，暂不能处理"
    : noRemovalCandidates && selectedCount
      ? "所选项目均有红心保护；请先取消红心"
      : protection.favoriteProtectedAssetIDs.length
        ? `将保留 ${protection.favoriteProtectedAssetIDs.length} 项红心`
        : "";
  elements.slimmingMoveToRecycleButton.title = removalHelp;
  elements.slimmingReleaseSpaceButton.title = removalHelp;
  if (renderInspector) renderSlimmingInspector();
}

function slimmingMemberMainButton(card, { create = false } = {}) {
  let button = card?.querySelector(":scope > .slimming-member-main") || null;
  if (!button && create && card) {
    button = document.createElement("button");
    button.type = "button";
    button.className = "slimming-member-main";
    card.append(button);
  }
  return button;
}

function slimmingMemberGridRovingAssetID() {
  const focusableIDs = new Set(
    state.slimming.members
      .filter((member) => !activeSlimmingRemovalPhase(member.id))
      .map((member) => member.id)
  );
  const focusedCard = document.activeElement?.closest?.(
    "#slimmingMemberGrid > .slimming-member-card"
  );
  if (focusableIDs.has(focusedCard?.dataset.slimmingMemberId)) {
    return focusedCard.dataset.slimmingMemberId;
  }
  const selectedMemberID = slimmingSelectionPrimaryID();
  if (focusableIDs.has(selectedMemberID)) return selectedMemberID;
  if (focusableIDs.has(state.slimming.memberGridFocusAssetID)) {
    return state.slimming.memberGridFocusAssetID;
  }
  return state.slimming.members.find((member) => focusableIDs.has(member.id))?.id || null;
}

function syncSlimmingMemberCardKeyboardAccess(
  card,
  rovingAssetID = slimmingMemberGridRovingAssetID()
) {
  const isTabStop = card?.dataset.slimmingMemberId === rovingAssetID;
  const mainButton = slimmingMemberMainButton(card);
  if (mainButton) mainButton.tabIndex = isTabStop ? 0 : -1;
  const favoriteButton = card?.querySelector(":scope > .slimming-member-favorite");
  if (favoriteButton) favoriteButton.tabIndex = isTabStop ? 0 : -1;
}

function syncSlimmingMemberGridTabStops(assetID = null) {
  const focusableIDs = new Set(
    state.slimming.members
      .filter((member) => !activeSlimmingRemovalPhase(member.id))
      .map((member) => member.id)
  );
  if (assetID && focusableIDs.has(assetID)) {
    state.slimming.memberGridFocusAssetID = assetID;
  }
  const rovingAssetID = slimmingMemberGridRovingAssetID();
  state.slimming.memberGridFocusAssetID = rovingAssetID;
  for (const card of elements.slimmingMemberGrid.querySelectorAll(
    ":scope > .slimming-member-card"
  )) {
    syncSlimmingMemberCardKeyboardAccess(card, rovingAssetID);
  }
}

function activeSlimmingRemovalPhase(assetID) {
  const request = state.slimming.removal.requests.find((candidate) =>
    ["awaitingMac", "running"].includes(candidate.phase)
      && candidate.jobID === state.slimming.selectedJobID
      && candidate.clusterID === state.slimming.selectedClusterID
      && (candidate.assetIDs || []).includes(assetID)
  );
  return request?.phase || null;
}

function syncSlimmingMemberFavoriteButton(card, member) {
  let button = card?.querySelector(":scope > .slimming-member-favorite") || null;
  if (!card || !supportsFavorites() || !member?.favorite) {
    button?.remove();
    return;
  }
  if (!button) {
    button = document.createElement("button");
    button.type = "button";
    button.className = "slimming-member-favorite write-action";
    button.dataset.slimmingMemberFavorite = "true";
    const icon = document.createElement("span");
    icon.className = "slimming-member-favorite-icon media-favorite-icon";
    icon.setAttribute("aria-hidden", "true");
    const badge = document.createElement("span");
    badge.className = "slimming-member-favorite-sync media-favorite-sync hidden";
    badge.setAttribute("aria-hidden", "true");
    button.append(icon, badge);
    card.append(button);
  }
  syncMediaFavoriteButton(button, {
    assetID: member.id,
    fileName: member.fileName,
    favorite: member.favorite,
  });
  const removalPhase = activeSlimmingRemovalPhase(member.id);
  if (removalPhase) {
    button.disabled = true;
    const reason = removalPhase === "awaitingMac"
      ? "等待 Mac 确认回收时不能更改红心"
      : "正在处理回收时不能更改红心";
    button.title = reason;
    button.setAttribute("aria-label", `${member.fileName || "当前项目"}：${reason}`);
  }
}

function syncSlimmingRecycleFavoriteButton(card, entry) {
  let button = card?.querySelector(":scope > .slimming-recycle-favorite") || null;
  if (!card || !supportsFavorites() || !entry?.favorite) {
    button?.remove();
    return;
  }
  if (!button) {
    button = document.createElement("button");
    button.type = "button";
    button.className = "slimming-recycle-favorite write-action";
    button.dataset.slimmingRecycleFavorite = "true";
    const icon = document.createElement("span");
    icon.className = "slimming-recycle-favorite-icon media-favorite-icon";
    icon.setAttribute("aria-hidden", "true");
    const badge = document.createElement("span");
    badge.className = "slimming-recycle-favorite-sync media-favorite-sync hidden";
    badge.setAttribute("aria-hidden", "true");
    button.append(icon, badge);
    card.append(button);
  }
  syncMediaFavoriteButton(button, {
    assetID: entry.assetID,
    fileName: entry.fileName,
    favorite: entry.favorite,
  });
  const warning = entry.sourceKind === "photos"
    ? "红心只用于整理，不会暂停系统“照片”的永久删除"
    : "红心只用于整理，不会阻止恢复、回收或永久删除";
  button.title = `${button.title}；${warning}`;
  button.setAttribute("aria-label", `${entry.fileName || "当前项目"}：${button.title}`);
}

async function toggleSlimmingMemberFavorite(button, { restoreFocus = true } = {}) {
  const card = button?.closest(".slimming-member-card");
  const assetID = button?.dataset.mediaFavoriteAssetId || card?.dataset.slimmingMemberId;
  const memberIndex = state.slimming.members.findIndex((member) => member.id === assetID);
  const favorite = favoriteStateForAssetID(assetID);
  if (!assetID || memberIndex < 0 || !favorite || state.favoriteMutating
    || activeSlimmingRemovalPhase(assetID)) return;

  const scrollContainer = slimmingMemberScrollContainer();
  const scrollTop = scrollContainer.scrollTop;
  const selectedMemberIDs = new Set(state.slimming.selectedMemberIDs);
  const selectionAnchorID = state.slimming.selectionAnchorID;
  await applyFavoriteMutation([assetID], favorite.isFavorite !== true);
  state.slimming.selectedMemberIDs = selectedMemberIDs;
  state.slimming.selectionAnchorID = selectionAnchorID;
  renderSlimmingMemberSelection();
  scrollContainer.scrollTop = scrollTop;

  if (!restoreFocus) return;
  if (button.isConnected) {
    button.focus({ preventScroll: true });
    return;
  }
  const fallback = elements.slimmingMemberGrid.querySelector(
    `[data-slimming-member-id="${CSS.escape(state.slimming.members[memberIndex]?.id || "")}"]`
  );
  slimmingMemberMainButton(fallback)?.focus({ preventScroll: true });
}

async function toggleSlimmingRecycleFavoriteEntry(entryID, { returnFocus = null } = {}) {
  const entry = state.slimming.recycle.entries.find(
    (candidate) => candidate.id === entryID
  );
  const assetID = entry?.assetID;
  const favorite = favoriteStateForAssetID(assetID);
  if (!entry || !assetID || !favorite || state.favoriteMutating
    || state.slimming.recycle.appending
    || state.slimming.recycle.mutatingEntryIDs.has(entryID)) return;
  const scrollTop = elements.slimmingRecycleBody.scrollTop;
  await applyFavoriteMutation([assetID], favorite.isFavorite !== true);
  elements.slimmingRecycleBody.scrollTop = scrollTop;
  if (returnFocus?.isConnected) {
    returnFocus.focus({ preventScroll: true });
    return;
  }
  slimmingRecycleFocusTarget(entryID)?.focus({ preventScroll: true });
}

async function toggleSlimmingRecycleFavorite(button) {
  const card = button?.closest(".slimming-recycle-thumbnail-card");
  const entryID = card?.dataset.slimmingRecycleThumbnailEntryId;
  await toggleSlimmingRecycleFavoriteEntry(entryID, { returnFocus: button });
}

function currentSlimmingRemovalRequest() {
  return state.slimming.removal.requests.find((request) =>
    request.phase === "awaitingMac" || request.phase === "running"
  ) || state.slimming.removal.requests.find((request) =>
    request.jobID === state.slimming.selectedJobID
      && request.clusterID === state.slimming.selectedClusterID
      && Date.now() - Number(request.updatedAtMs || 0) < 10 * 60 * 1000
  ) || null;
}

function currentSlimmingIdenticalCleanupRequest() {
  return state.slimming.identicalCleanup.requests.find(
    (request) => request.phase === "running"
  ) || state.slimming.identicalCleanup.requests.find(
    (request) => request.phase === "awaitingMac"
  ) || state.slimming.identicalCleanup.requests.find((request) =>
    request.jobID === state.slimming.selectedJobID
      && Date.now() - Number(request.updatedAtMs || 0) < 10 * 60 * 1000
  ) || null;
}

function runningIdenticalCleanupRequest() {
  return state.slimming.identicalCleanup.requests.find(
    (request) => request.phase === "running"
  ) || null;
}

function identicalCleanupExecutionPresentation(request) {
  const stage = request?.executionStage
    || (request?.progress?.totalAssetCount ? "recyclingAssets" : null);
  const presentations = {
    validatingPlan: {
      icon: "✓",
      title: "正在复核清理方案",
      detail: "重新读取照片与来源状态，确认清理范围没有变化。",
    },
    recyclingAssets: {
      icon: "⌫",
      title: request?.mode === "releaseSourceSpace"
        ? "正在清理重复媒体"
        : "正在移入回收站",
      detail: "按已确认的优先级逐项处理；这里显示本次运行的实际进度。",
    },
    requestingAuthorization: {
      icon: "⌑",
      title: "正在等待系统授权",
      detail: "如有系统窗口，请先完成照片或文件夹访问授权。",
    },
    refreshingState: {
      icon: "↻",
      title: "正在刷新删除状态",
      detail: "重新读取回收记录和当前可用状态。",
    },
    verifyingResult: {
      icon: "✓",
      title: "正在进行删除后核验",
      detail: "实打实统计已完成去重、仍有冗余和状态待确认的照片。",
    },
  };
  return {
    stage,
    ...(presentations[stage] || {
      icon: "…",
      title: "正在处理清理方案",
      detail: request?.message || "Mac 正在安全执行并核验本次清理。",
    }),
  };
}

function closeIdenticalCleanupBlockingOverlay({ restoreFocus = true } = {}) {
  const cleanup = state.slimming.identicalCleanup;
  const returnFocus = cleanup.blockingReturnFocus;
  cleanup.blockingReturnFocus = null;
  if (elements.identicalCleanupBlockingDialog.open) {
    elements.identicalCleanupBlockingDialog.close();
  }
  if (restoreFocus) {
    restoreOverlayFocus(stableReturnFocusTarget(returnFocus, elements.commandButton));
  }
}

function renderIdenticalCleanupBlockingOverlay() {
  const cleanup = state.slimming.identicalCleanup;
  const request = runningIdenticalCleanupRequest();
  if (!request) {
    if (elements.identicalCleanupBlockingDialog.open) {
      closeIdenticalCleanupBlockingOverlay();
    }
    return;
  }

  const presentation = identicalCleanupExecutionPresentation(request);
  elements.identicalCleanupBlockingIcon.textContent = presentation.icon;
  elements.identicalCleanupBlockingTitle.textContent = presentation.title;
  elements.identicalCleanupBlockingDetail.textContent = presentation.detail;
  const total = Math.max(0, Number(request.progress?.totalAssetCount || 0));
  const completed = Math.min(
    total,
    Math.max(0, Number(request.progress?.completedAssetCount || 0))
  );
  const determinate = presentation.stage === "recyclingAssets" && total > 0;
  elements.identicalCleanupBlockingIndeterminate.classList.toggle("hidden", determinate);
  elements.identicalCleanupBlockingProgress.classList.toggle("hidden", !determinate);
  if (determinate) {
    elements.identicalCleanupBlockingProgressBar.max = total;
    elements.identicalCleanupBlockingProgressBar.value = completed;
    elements.identicalCleanupBlockingProgressBar.setAttribute(
      "aria-label",
      `已处理 ${completed} / ${total} 张`
    );
    elements.identicalCleanupBlockingProgressLabel.textContent =
      `已处理 ${completed.toLocaleString("zh-CN")} / ${total.toLocaleString("zh-CN")} 张`;
  }
  elements.identicalCleanupBlockingDialog.setAttribute(
    "aria-label",
    determinate
      ? `${presentation.title}，已处理 ${completed} / ${total} 张，其他操作已锁定`
      : `${presentation.title}，其他操作已锁定`
  );

  if (!elements.identicalCleanupBlockingDialog.open) {
    cleanup.blockingReturnFocus = document.activeElement instanceof HTMLElement
      ? document.activeElement
      : null;
    hidePersistentHelp();
    hideContextMenus();
    closeCompactToolbarMenu({ restoreFocus: false });
    elements.identicalCleanupBlockingDialog.showModal();
    requestAnimationFrame(() => {
      elements.identicalCleanupBlockingCard.focus({ preventScroll: true });
    });
  }
}

function slimmingRemovalStatusPart(key, tagName, className) {
  let part = elements.slimmingRemovalStatus.querySelector(
    `:scope > [data-slimming-removal-status-part="${key}"]`
  );
  if (!part) {
    part = document.createElement(tagName);
    part.dataset.slimmingRemovalStatusPart = key;
  }
  part.className = className;
  return part;
}

function reconcileSlimmingRemovalStatusParts(parts) {
  reconcileStableChildren(elements.slimmingRemovalStatus, parts);
}

function renderSlimmingRemovalStatus() {
  const request = currentSlimmingIdenticalCleanupRequest()
    || currentSlimmingRemovalRequest();
  elements.slimmingRemovalStatus.classList.toggle("hidden", !request);
  if (!request) {
    reconcileSlimmingRemovalStatusParts([]);
    delete elements.slimmingRemovalStatus.dataset.slimmingRemovalStatusRequestId;
    return;
  }
  if (elements.slimmingRemovalStatus.dataset.slimmingRemovalStatusRequestId !== request.id) {
    reconcileSlimmingRemovalStatusParts([]);
    elements.slimmingRemovalStatus.dataset.slimmingRemovalStatusRequestId = request.id;
  }
  const parts = [];

  const header = slimmingRemovalStatusPart(
    "header",
    "div",
    "slimming-removal-status-header"
  );
  let message = header.querySelector(":scope > strong");
  if (!message) message = document.createElement("strong");
  message.textContent = request.message || "Mac 正在处理批量操作…";
  let phase = header.querySelector(":scope > .secondary");
  if (!phase) {
    phase = document.createElement("span");
    phase.className = "secondary";
  }
  phase.textContent = {
    awaitingMac: "等待 Mac 确认",
    running: "处理中",
    completed: "已完成",
    cancelled: "已取消",
    failed: "未完成",
  }[request.phase] || request.phase;
  reconcileStableChildren(header, [message, phase]);
  parts.push(header);

  if (request.progress && request.phase === "running") {
    const progress = slimmingRemovalStatusPart("progress", "progress", "");
    progress.max = Math.max(1, Number(request.progress.totalAssetCount || 1));
    progress.value = Math.max(0, Number(request.progress.completedAssetCount || 0));
    progress.setAttribute(
      "aria-label",
      `已完成 ${progress.value}/${progress.max} 项`
    );
    parts.push(progress);
  }
  if (request.audit) {
    const audit = slimmingRemovalStatusPart("audit", "div", "slimming-removal-audit");
    const auditParts = [];
    if (request.audit.hiddenAssetIDs?.length) {
      auditParts.push(`已从候选结果隐藏 ${request.audit.hiddenAssetIDs.length} 项`);
    }
    if (request.audit.failedAssetIDs?.length) {
      auditParts.push(`失败 ${request.audit.failedAssetIDs.length} 项`);
    }
    if (request.audit.authorizationRequiredAssetIDs?.length) {
      auditParts.push(`待来源授权 ${request.audit.authorizationRequiredAssetIDs.length} 项`);
    }
    if (request.audit.authorizationDeniedPhotosAssetIDs?.length) {
      auditParts.push(`Photos 未授权 ${request.audit.authorizationDeniedPhotosAssetIDs.length} 项`);
    }
    audit.textContent = auditParts.join(" · ") || "逐项结果已由 Mac 安全核验";
    parts.push(audit);
  }
  if (hasSlimmingVerificationReport(request)) {
    const verification = slimmingRemovalStatusPart(
      "verification",
      "div",
      "slimming-removal-audit"
    );
    verification.textContent = request.verification
      ? request.verification.isComplete
        ? `已独立核验：${request.verification.verifiedGroupCount}/${request.verification.targetGroupCount} 组完成去重，红心资产全部保留`
        : `核验结果：完成 ${request.verification.verifiedGroupCount}/${request.verification.targetGroupCount} 组 · 尚有 ${request.verification.remainingRedundantAssetCount} 项冗余`
      : "删除动作已结束；实际资产状态尚未完成独立核验";
    parts.push(verification);
    const report = slimmingRemovalStatusPart(
      "verificationAction",
      "button",
      "button button-compact slimming-verification-button"
    );
    report.type = "button";
    report.dataset.slimmingVerificationRequestId = request.id;
    report.textContent = request.verification ? "查看完整核验报告" : "查看核验说明";
    parts.push(report);
  }
  reconcileSlimmingRemovalStatusParts(parts);
}

function syncSlimmingVerificationText(element, text) {
  if (element.textContent !== text) element.textContent = text;
}

function syncSlimmingVerificationMetrics(metrics) {
  const existing = new Map(
    [...elements.slimmingVerificationMetrics.querySelectorAll(
      ":scope > [data-slimming-verification-metric-key]"
    )].map((card) => [card.dataset.slimmingVerificationMetricKey, card])
  );
  const wanted = metrics.map((metric) => {
    const card = existing.get(metric.key) || document.createElement("div");
    card.dataset.slimmingVerificationMetricKey = metric.key;
    card.className = `identical-cleanup-metric ${metric.tone || ""}`;
    let title = card.querySelector(":scope > [data-slimming-verification-metric-part='title']");
    if (!title) {
      title = document.createElement("span");
      title.dataset.slimmingVerificationMetricPart = "title";
    }
    let count = card.querySelector(":scope > [data-slimming-verification-metric-part='count']");
    if (!count) {
      count = document.createElement("strong");
      count.dataset.slimmingVerificationMetricPart = "count";
    }
    syncSlimmingVerificationText(title, metric.label);
    syncSlimmingVerificationText(count, Number(metric.value || 0).toLocaleString());
    reconcileStableChildren(card, [title, count]);
    return card;
  });
  reconcileStableChildren(elements.slimmingVerificationMetrics, wanted);
}

function slimmingVerificationResultPart(key, tagName) {
  let part = elements.slimmingVerificationResult.querySelector(
    `:scope > [data-slimming-verification-result-key="${key}"]`
  );
  if (!part) {
    part = document.createElement(tagName);
    part.dataset.slimmingVerificationResultKey = key;
  }
  return part;
}

function syncSlimmingVerificationResult(parts) {
  const wanted = parts.map(({ key, tagName, text }) => {
    const part = slimmingVerificationResultPart(key, tagName);
    syncSlimmingVerificationText(part, text);
    return part;
  });
  reconcileStableChildren(elements.slimmingVerificationResult, wanted);
}

function slimmingVerificationUnavailableMessage(request) {
  return typeof request?.verificationUnavailableMessage === "string"
    ? request.verificationUnavailableMessage.trim()
    : "";
}

function hasSlimmingVerificationReport(request) {
  return Boolean(request?.verification || slimmingVerificationUnavailableMessage(request));
}

function renderSlimmingVerificationReport(request) {
  const verification = request?.verification;
  const unavailableMessage = slimmingVerificationUnavailableMessage(request);
  if (!verification && !unavailableMessage) return false;
  const unavailable = !verification;
  elements.slimmingVerificationDialog.classList.toggle("unavailable", unavailable);
  elements.slimmingVerificationScoreSection.classList.toggle("hidden", unavailable);
  elements.slimmingVerificationMetrics.classList.toggle("hidden", unavailable);
  if (unavailable) {
    elements.slimmingVerificationDialog.classList.add("incomplete");
    syncSlimmingVerificationText(elements.slimmingVerificationIcon, "!");
    syncSlimmingVerificationText(elements.slimmingVerificationTitle, "删除后核验未完成");
    syncSlimmingVerificationText(
      elements.slimmingVerificationSubtitle,
      "删除动作已经结束，但无法取得可信的实际统计。"
    );
    syncSlimmingVerificationMetrics([]);
    syncSlimmingVerificationResult([
      {
        key: "heading",
        tagName: "strong",
        text: "未显示未经证实的保留数量",
      },
      { key: "detail", tagName: "p", text: unavailableMessage },
      {
        key: "guidance",
        tagName: "p",
        text: "请保留当前回收记录并重新进入图库瘦身后再核验；在成功读取真实状态前，ImageAll 不会用删除前计划值代替结果。",
      },
    ]);
    syncSlimmingVerificationText(
      elements.slimmingVerificationFootnote,
      "此处只呈现删除动作已经结束和核验不可用这两个已证实事实。"
    );
    return true;
  }
  const complete = Boolean(verification.isComplete);
  elements.slimmingVerificationDialog.classList.toggle("incomplete", !complete);
  syncSlimmingVerificationText(elements.slimmingVerificationIcon, complete ? "✓" : "!");
  syncSlimmingVerificationText(elements.slimmingVerificationTitle, complete
    ? "删除后核验完成"
    : "删除后核验存在未完成项");
  syncSlimmingVerificationText(
    elements.slimmingVerificationSubtitle,
    "已重新读取本次处理资产的实时可用与回收状态。"
  );
  syncSlimmingVerificationText(
    elements.slimmingVerificationScore,
    `${verification.verifiedGroupCount} / ${verification.targetGroupCount}`
  );
  syncSlimmingVerificationText(
    elements.slimmingVerificationGoal,
    `目标是保留全部红心资产；没有红心时每组保留 1 项，共 ${verification.targetRetainedAssetCount} 项。`
  );
  syncSlimmingVerificationMetrics([
    {
      key: "target",
      label: "目标保留",
      value: verification.targetRetainedAssetCount,
      tone: "blue",
    },
    {
      key: "available",
      label: "当前实际可用",
      value: verification.currentAvailableAssetCount,
      tone: "green",
    },
    {
      key: "verified",
      label: "完成去重",
      value: verification.verifiedGroupCount,
      tone: "indigo",
    },
    {
      key: "unresolved",
      label: "尚未完成",
      value: verification.unresolvedGroupCount,
      tone: complete ? "neutral" : "orange",
    },
  ]);
  syncSlimmingVerificationResult([
    {
      key: "heading",
      tagName: "strong",
      text: complete ? "核验完成" : "核验发现未完成项",
    },
    {
      key: "detail",
      tagName: "p",
      text: complete
        ? `实际读取 ${verification.observedAssetCount} 项，确认已清理 ${verification.recycledRedundantAssetCount} 项；处理范围内没有仍处于可用状态的计划删除项。`
        : `实际读取 ${verification.observedAssetCount} 项；确认已清理 ${verification.recycledRedundantAssetCount} 项；当前实际可用 ${verification.currentAvailableAssetCount} 项；仍可用冗余 ${verification.remainingRedundantAssetCount} 项；状态无法确认 ${verification.unresolvedAssetCount} 项。`,
    },
  ]);
  syncSlimmingVerificationText(
    elements.slimmingVerificationFootnote,
    "“完成去重”“确认已清理”和“当前实际可用”均来自删除后的再次读取；“目标保留”来自本次运行时逐组清理计划，不代表所有分组均已完成。"
  );
  return true;
}

function slimmingVerificationBaseLevelFromHistory(context = {}) {
  return ["sidebar", "inspector", "lightbox"].includes(
    context.slimmingVerificationBaseLevel
  )
    ? context.slimmingVerificationBaseLevel
    : "workspace";
}

function replaceSlimmingVerificationHistoryWithBase(baseLevel) {
  if (!state.workspaceNavigation.initialized
    || elements.appView.classList.contains("hidden")) return;
  const current = activeWorkspaceHistoryEntry();
  const route = visibleWorkspaceRoute();
  if (current?.route !== route || current.navigationLevel !== "slimmingVerification") return;
  const context = currentWorkspaceHistoryContext(route);
  if (context && typeof context === "object") delete context.slimmingVerificationBaseLevel;
  const navigationLevel = visibleWorkspaceNavigationBaseLevel(route, baseLevel);
  history.replaceState({
    ...(history.state || {}),
    [WORKSPACE_HISTORY_KEY]: workspaceHistoryEntry(route, context, navigationLevel),
  }, "", location.href);
}

function clearSlimmingVerificationState() {
  const cleanup = state.slimming.identicalCleanup;
  cleanup.verificationRequest = null;
  cleanup.verificationReturnFocus = null;
  cleanup.verificationBaseLevel = "workspace";
  cleanup.verificationHistoryRestoreFocus = true;
  cleanup.verificationRestorable = false;
  cleanup.verificationOpening = false;
}

function presentSlimmingVerificationReport({
  historyMode = "pushSlimmingVerification",
  baseLevel = null,
  focus = true,
} = {}) {
  const cleanup = state.slimming.identicalCleanup;
  if (!renderSlimmingVerificationReport(cleanup.verificationRequest)) return;
  if (elements.slimmingVerificationDialog.open) {
    if (focus) restoreOverlayFocus(elements.closeSlimmingVerificationButton);
    return;
  }
  const current = activeWorkspaceHistoryEntry();
  cleanup.verificationBaseLevel = baseLevel
    || workspaceNavigationBaseLevel(
      current?.navigationLevel || "workspace",
      current?.context || {}
    );
  elements.slimmingVerificationDialog.showModal();
  if (historyMode !== "none") {
    const route = visibleWorkspaceRoute();
    recordWorkspaceHistory(route, currentWorkspaceHistoryContext(route), historyMode);
  }
  cleanup.verificationRestorable = true;
  if (focus) {
    requestAnimationFrame(() => restoreOverlayFocus(elements.closeSlimmingVerificationButton));
  }
}

function openSlimmingVerificationReport(request) {
  const cleanup = state.slimming.identicalCleanup;
  if (!hasSlimmingVerificationReport(request) || cleanup.verificationOpening) return;
  if (!elements.slimmingVerificationDialog.open) {
    cleanup.verificationReturnFocus = document.activeElement;
  }
  cleanup.verificationRequest = request;
  cleanup.verificationOpening = true;
  try {
    presentSlimmingVerificationReport();
  } finally {
    cleanup.verificationOpening = false;
  }
}

function closeSlimmingVerificationReport({
  restoreFocus = true,
  checkpoint = true,
  preserveState = false,
} = {}) {
  if (!elements.slimmingVerificationDialog.open) return;
  const cleanup = state.slimming.identicalCleanup;
  const baseLevel = cleanup.verificationBaseLevel;
  const returnFocus = cleanup.verificationReturnFocus;
  elements.slimmingVerificationDialog.close();
  if (restoreFocus) {
    const requestID = cleanup.verificationRequest?.id;
    const reportButton = requestID
      ? elements.slimmingRemovalStatus.querySelector(
        `[data-slimming-verification-request-id="${CSS.escape(requestID)}"]`
      )
      : null;
    restoreOverlayFocus(stableReturnFocusTarget(
      returnFocus,
      reportButton || elements.slimmingButton
    ));
  }
  if (checkpoint) replaceSlimmingVerificationHistoryWithBase(baseLevel);
  if (!preserveState) clearSlimmingVerificationState();
}

function returnFromSlimmingVerification({ restoreFocus = true } = {}) {
  if (!elements.slimmingVerificationDialog.open) return Promise.resolve();
  const cleanup = state.slimming.identicalCleanup;
  cleanup.verificationHistoryRestoreFocus = restoreFocus;
  if (state.workspaceNavigation.pendingReturnPromise) {
    return state.workspaceNavigation.pendingReturnPromise;
  }
  const current = activeWorkspaceHistoryEntry();
  if (state.workspaceNavigation.initialized
    && current?.route === visibleWorkspaceRoute()
    && current.navigationLevel === "slimmingVerification") {
    const pending = new Promise((resolve) => {
      state.workspaceNavigation.pendingReturnResolve = resolve;
    });
    state.workspaceNavigation.pendingReturnPromise = pending;
    history.back();
    return pending;
  }
  closeSlimmingVerificationReport({ restoreFocus });
  cleanup.verificationHistoryRestoreFocus = true;
  return Promise.resolve();
}

function reconcileSlimmingVerificationFromWorkspaceHistory(
  route,
  navigationLevel,
  context = {}
) {
  const cleanup = state.slimming.identicalCleanup;
  const shouldOpen = navigationLevel === "slimmingVerification"
    && route === visibleWorkspaceRoute();
  if (shouldOpen && (!cleanup.verificationRestorable
    || !hasSlimmingVerificationReport(cleanup.verificationRequest))) {
    clearSlimmingVerificationState();
    if (history.length > 1 && Object.prototype.hasOwnProperty.call(
      context,
      "slimmingVerificationBaseLevel"
    )) {
      history.back();
    } else {
      replaceSlimmingVerificationHistoryWithBase(
        slimmingVerificationBaseLevelFromHistory(context)
      );
    }
    return;
  }
  if (shouldOpen && !elements.slimmingVerificationDialog.open) {
    presentSlimmingVerificationReport({
      historyMode: "none",
      baseLevel: slimmingVerificationBaseLevelFromHistory(context),
    });
  } else if (!shouldOpen && elements.slimmingVerificationDialog.open) {
    const restoreFocus = cleanup.verificationHistoryRestoreFocus;
    closeSlimmingVerificationReport({
      restoreFocus,
      checkpoint: false,
      preserveState: true,
    });
    cleanup.verificationHistoryRestoreFocus = true;
  }
}

function renderSlimmingMemberSummary() {
  const cluster = state.slimming.clusters.find(
    (item) => item.id === state.slimming.selectedClusterID
  );
  renderSlimmingSelectedClusterReview(cluster);
  const copy = cluster ? slimmingClusterPresentation(cluster) : null;
  const historicalEmpty = Boolean(
    cluster?.isHistoricalProcessedRecord && state.slimming.members.length === 0
  );
  elements.slimmingMemberEmpty.classList.toggle("hidden", Boolean(cluster) && !historicalEmpty);
  elements.slimmingMemberGrid.classList.toggle("hidden", !cluster || historicalEmpty);
  const emptyIcon = elements.slimmingMemberEmpty.querySelector("[aria-hidden='true']");
  const emptyTitle = elements.slimmingMemberEmpty.querySelector("strong");
  const emptyMessage = elements.slimmingMemberEmpty.querySelector("p");
  if (historicalEmpty) {
    emptyIcon.textContent = "✓";
    emptyTitle.textContent = "历史处理记录";
    emptyMessage.textContent = "原分组仍有审阅记录，但成员当前均已回收、清理或不再可查看。";
  } else {
    emptyIcon.textContent = "▧";
    emptyTitle.textContent = "选择一个候选分组";
    emptyMessage.textContent = "可使用普通点击、⌘ 点击、Shift 点击、⌘A 和拖拽空白框选成员；双击或按空格预览。";
  }
  elements.slimmingMemberTitle.textContent = copy?.title || "选择一个候选分组";
  const sourceNames = [...new Set(state.slimming.members.map((item) => item.sourceName).filter(Boolean))];
  elements.slimmingMemberSummary.textContent = cluster
    ? `${copy.detail} · ${copy.historicalDetail || `${state.slimming.members.length}/${cluster.memberCount} 项`} · ${sourceNames.join(" · ") || (historicalEmpty ? "成员当前不可查看" : "来源信息不可用")}`
    : "分组中的照片会在这里显示";
  const appending = state.slimming.appending === "members";
  elements.slimmingLoadMoreMembersButton.classList.toggle(
    "hidden",
    !cluster || (!appending && state.slimming.members.length >= cluster.memberCount)
  );
  elements.slimmingLoadMoreMembersButton.disabled = state.slimming.loading;
  elements.slimmingLoadMoreMembersButton.textContent = appending
    ? "正在载入更多成员…"
    : `显示更多成员（剩余 ${Math.max(
      0,
      Number(cluster?.memberCount || 0) - state.slimming.members.length
    )}）`;
  elements.slimmingLoadMoreMembersButton.setAttribute("aria-busy", String(appending));
  return cluster;
}

function syncSlimmingMemberCard(card, member, rovingAssetID) {
  const removalPhase = activeSlimmingRemovalPhase(member.id);
  const fingerprint = JSON.stringify({
    member,
    mediaKind: state.slimming.mediaKind,
    removalPhase,
  });
  if (card.dataset.slimmingFingerprint === fingerprint) return card;
  card.classList.add("slimming-member-card");
  card.dataset.slimmingMemberId = member.id;
  if (Number(member.width) > 0 && Number(member.height) > 0) {
    card.style.setProperty(
      "--slimming-member-aspect",
      `${Number(member.width)} / ${Number(member.height)}`
    );
  } else {
    card.style.removeProperty("--slimming-member-aspect");
  }
  const main = slimmingMemberMainButton(card, { create: true });
  main.dataset.slimmingMemberMain = "true";
  main.disabled = Boolean(removalPhase);
  main.setAttribute(
    "aria-label",
    `${member.fileName || "未命名项目"}，${member.sourceName || "来源未知"}`
  );
  main.setAttribute(
    "aria-keyshortcuts",
    "ArrowLeft ArrowRight ArrowUp ArrowDown Home End PageUp PageDown Space"
  );
  main.title = "方向键移动，Shift 扩展选择，Space 打开单图";
  let image = main.querySelector(
    ':scope > [data-slimming-member-main-part="image"]'
  );
  if (!image) {
    image = document.createElement("img");
    image.dataset.slimmingMemberMainPart = "image";
  }
  image.loading = "lazy";
  image.alt = "";
  image.setAttribute("aria-hidden", "true");
  syncProtectedThumbnailSource(image, member.id, {
    width: 360,
    revision: member.contentRevision || 0,
  });
  let footer = main.querySelector(
    ':scope > [data-slimming-member-main-part="footer"]'
  );
  if (!footer) {
    footer = document.createElement("span");
    footer.dataset.slimmingMemberMainPart = "footer";
  }
  footer.className = "slimming-member-footer";
  let name = footer.querySelector(
    ':scope > [data-slimming-member-footer-part="name"]'
  );
  if (!name) {
    name = document.createElement("strong");
    name.dataset.slimmingMemberFooterPart = "name";
  }
  const nameText = member.fileName || "未命名项目";
  if (name.textContent !== nameText) name.textContent = nameText;
  let source = footer.querySelector(
    ':scope > [data-slimming-member-footer-part="source"]'
  );
  if (!source) {
    source = document.createElement("span");
    source.dataset.slimmingMemberFooterPart = "source";
  }
  const sourceText = member.sourceName || availabilityText(member.availability);
  if (source.textContent !== sourceText) source.textContent = sourceText;
  reconcileStableChildren(footer, [name, source]);
  let video = main.querySelector(
    ':scope > [data-slimming-member-main-part="video"]'
  );
  if (state.slimming.mediaKind === "video") {
    if (!video) {
      video = document.createElement("span");
      video.dataset.slimmingMemberMainPart = "video";
    }
    video.className = "slimming-member-video-badge";
    video.setAttribute("aria-hidden", "true");
    const videoText = `▶${member.durationMs == null ? "" : ` ${formatDuration(member.durationMs)}`}`;
    if (video.textContent !== videoText) video.textContent = videoText;
  }
  reconcileStableChildren(main, [
    image,
    footer,
    ...(state.slimming.mediaKind === "video" && video ? [video] : []),
  ]);
  syncSlimmingMemberFavoriteButton(card, member);
  card.classList.toggle("pending-removal", Boolean(removalPhase));
  let overlay = card.querySelector(
    ':scope > [data-slimming-member-card-part="pendingOverlay"]'
  );
  if (removalPhase) {
    if (!overlay) {
      overlay = document.createElement("span");
      overlay.dataset.slimmingMemberCardPart = "pendingOverlay";
    }
    overlay.className = "slimming-member-pending-overlay";
    overlay.setAttribute("role", "status");
    overlay.setAttribute("aria-label", removalPhase === "awaitingMac"
      ? "等待 Mac 确认安全回收"
      : "正在安全处理回收");
    let spinner = overlay.querySelector(
      ':scope > [data-slimming-member-overlay-part="spinner"]'
    );
    if (!spinner) {
      spinner = document.createElement("span");
      spinner.dataset.slimmingMemberOverlayPart = "spinner";
    }
    spinner.className = "spinner";
    spinner.setAttribute("aria-hidden", "true");
    let copy = overlay.querySelector(
      ':scope > [data-slimming-member-overlay-part="copy"]'
    );
    if (!copy) {
      copy = document.createElement("strong");
      copy.dataset.slimmingMemberOverlayPart = "copy";
    }
    const overlayText = removalPhase === "awaitingMac" ? "等待 Mac 确认" : "正在移动";
    if (copy.textContent !== overlayText) copy.textContent = overlayText;
    reconcileStableChildren(overlay, [spinner, copy]);
  }
  const favorite = card.querySelector(":scope > .slimming-member-favorite");
  reconcileStableChildren(card, [
    main,
    ...(favorite ? [favorite] : []),
    ...(removalPhase && overlay ? [overlay] : []),
  ]);
  syncSlimmingMemberCardKeyboardAccess(card, rovingAssetID);
  card.dataset.slimmingFingerprint = fingerprint;
  return card;
}

function appendSlimmingMemberCards(members, rovingAssetID) {
  const fragment = document.createDocumentFragment();
  for (const member of members) {
    fragment.append(syncSlimmingMemberCard(
      document.createElement("div"),
      member,
      rovingAssetID
    ));
  }
  elements.slimmingMemberGrid.append(fragment);
}

function renderSlimmingMembers({ appendItems = null } = {}) {
  renderSlimmingMemberSummary();
  state.slimming.memberGridFocusAssetID = slimmingMemberGridRovingAssetID();
  const rovingAssetID = state.slimming.memberGridFocusAssetID;
  if (appendItems !== null) {
    appendSlimmingMemberCards(appendItems, rovingAssetID);
  } else {
    const existingCards = new Map(
      [...elements.slimmingMemberGrid.querySelectorAll(
        ":scope > .slimming-member-card[data-slimming-member-id]"
      )].map((card) => [card.dataset.slimmingMemberId, card])
    );
    for (const [index, member] of state.slimming.members.entries()) {
      const card = existingCards.get(member.id) || document.createElement("div");
      existingCards.delete(member.id);
      syncSlimmingMemberCard(card, member, rovingAssetID);
      const currentCard = elements.slimmingMemberGrid.children[index] || null;
      if (currentCard !== card) elements.slimmingMemberGrid.insertBefore(card, currentCard);
    }
    for (const card of existingCards.values()) card.remove();
  }
  renderSlimmingMemberSelection();
}

function slimmingRecycleCountdown(entry) {
  const remaining = Number(entry.purgeAfterMs) - Date.now();
  const photos = entry.sourceKind === "photos";
  if (remaining <= 0) {
    return photos ? "ImageAll 即将清理此记录" : "即将永久删除";
  }
  const hour = 60 * 60 * 1000;
  const day = 24 * hour;
  const amount = remaining < day
    ? `${Math.max(1, Math.ceil(remaining / hour))} 小时`
    : `${Math.max(1, Math.ceil(remaining / day))} 天`;
  return photos ? `ImageAll 将在 ${amount}后清理此记录` : `${amount}后永久删除`;
}

function slimmingRecycleStateCopy(entry) {
  if (entry.state === "recycled") return slimmingRecycleCountdown(entry);
  if (entry.stateMessage) return entry.stateMessage;
  if (entry.state === "restored") return "媒体已经恢复";
  if (entry.state === "purged") return "媒体已经永久清理";
  if (entry.resolution === "discardPreflightFailure") {
    return "未执行：缺少来源写入授权，可安全撤销失败意图";
  }
  if (entry.resolution === "retryInterruptedOperation") {
    return "操作曾被中断，需要重新检查原位置与隔离区";
  }
  if (entry.resolution === "inspect") {
    return `状态无法自动确定${entry.errorCode ? ` · ${entry.errorCode}` : ""}`;
  }
  return slimmingRecycleCountdown(entry);
}

function slimmingRecycleLifecycleIcon(entry) {
  if (entry.state === "recycled") return entry.sourceKind === "photos" ? "◷" : "⌛";
  if (["pending", "restoring", "purging"].includes(entry.state)) return "↻";
  if (entry.state === "failed") return "!";
  return entry.state === "purged" ? "⌫" : "✓";
}

function slimmingRecycleMovedCaption(entry) {
  const action = {
    recycled: "移入",
    pending: "开始处理",
    restoring: "开始恢复",
    purging: "开始清理",
    failed: "尝试处理",
    restored: "恢复",
    purged: "清理",
  }[entry.state] || "更新";
  const date = new Intl.DateTimeFormat("zh-CN", {
    year: "numeric",
    month: "short",
    day: "numeric",
  }).format(new Date(entry.trashedAtMs));
  return `${date} ${action}`;
}

function slimmingRecyclePolicyCopy(entry) {
  if (entry.policyMessage) return entry.policyMessage;
  return {
    recycled: entry.sourceKind === "photos"
      ? "恢复与永久删除由“照片”App 管理"
      : "可恢复到原位置",
    pending: "ImageAll 会先确认实际位置，不会重复删除",
    restoring: "正在协调原位置与 ImageAll 隔离区",
    purging: "永久清理已经开始，完成后不可恢复",
    restored: "媒体已经恢复",
    purged: "媒体已经永久清理",
    failed: "未确认删除完成；现有内容会继续受到保护",
  }[entry.state] || "现有内容会继续受到保护";
}

function slimmingRecycleRecoveryDescriptor(entry) {
  switch (entry.resolution) {
    case "discardPreflightFailure":
    case "updateFolderAuthorization":
      return {
        kind: "source",
        action: "refreshFolderMutationAuthorization",
        label: "更新回收权限",
        help: "重新选择原文件夹，更新这个来源的回收与恢复权限；不会立即修改媒体。",
      };
    case "refreshSourceBeforeRetry":
      return {
        kind: "source",
        action: entry.sourceKind === "photos" ? "syncPhotos" : "rescan",
        label: "刷新来源",
        help: "重新读取这个来源的目录状态；完成后需重新分析，再重试清理。",
      };
    case "requestPhotosAuthorization":
      return {
        kind: "source",
        action: "requestPhotosWriteAuthorization",
        label: "请求照片权限",
        help: "请求 Apple Photos 完整读写授权；不会立即删除媒体。",
      };
    case "retryFromAnalysis":
      return {
        kind: "navigation",
        action: "analysis",
        label: "返回分析结果",
        help: "返回当前分析结果；核对媒体状态后可重新发起清理。",
      };
    default:
      return null;
  }
}

function slimmingRecycleShowsExplanation(entry) {
  return [
    "reinspectFileLocations",
    "updateFolderAuthorization",
    "refreshSourceBeforeRetry",
    "requestPhotosAuthorization",
    "retryFromAnalysis",
    "inspect",
  ].includes(entry.resolution);
}

function slimmingRecycleDirectActionLabel(entry, action) {
  if (action === "restore") return "恢复";
  if (action === "discardPreflightFailure") return "移除记录";
  if (action === "retryInterruptedOperation") {
    if (entry.resolution === "reinspectFileLocations") return "重新检查";
    return entry.state === "purging" ? "继续清理" : "继续协调";
  }
  if (action === "purge") return "立即删除";
  return action;
}

function slimmingRecycleDirectActionHelp(entry, action) {
  if (action === "restore") return "把这个文件夹媒体从 ImageAll 回收站恢复到原位置。";
  if (action === "discardPreflightFailure") {
    return "只移除这条未开始文件操作的失败记录；不会读写、移动或删除原文件。";
  }
  if (action === "retryInterruptedOperation") {
    return entry.resolution === "reinspectFileLocations"
      ? "只检查原位置与隔离区；只有结果唯一时才更新记录。"
      : "根据已登记的事务继续安全恢复；不会重复提交已经完成的来源删除。";
  }
  if (action === "purge") return "打开永久删除确认；确认后这个原始媒体将不可恢复。";
  return "";
}

function renderSlimmingRecycleExplanation(entryID) {
  const entry = state.slimming.recycle.entries.find((item) => item.id === entryID);
  if (!entry) return false;
  elements.slimmingRecycleExplanationTitle.textContent = entry.sourceKind === "photos"
    && entry.state === "recycled"
    ? "在“照片”App 中恢复"
    : entry.fileName || "回收处理说明";
  elements.slimmingRecycleExplanationSource.textContent = `${entry.sourceDisplayName} · ${
    entry.sourceKind === "photos" ? "Apple Photos" : "文件夹"
  }`;
  elements.slimmingRecycleExplanationState.textContent = slimmingRecycleStateCopy(entry);
  elements.slimmingRecycleExplanationPolicy.textContent = slimmingRecyclePolicyCopy(entry);
  elements.slimmingRecycleExplanationMessage.textContent = entry.explanationMessage
    || (entry.resolution === "photosManagedBySystem"
      ? "请在系统“照片”App 的“最近删除”中恢复；恢复后 ImageAll 会自动对账。永久删除也由系统管理。"
      : "本次操作没有形成可证明的完成状态。ImageAll 不会继续删除；请修正当前原因后再重试。");
  return true;
}

function slimmingRecycleExplanationBaseLevelFromHistory(context = {}) {
  return ["sidebar", "inspector", "lightbox"].includes(
    context.slimmingRecycleExplanationBaseLevel
  )
    ? context.slimmingRecycleExplanationBaseLevel
    : "workspace";
}

function replaceSlimmingRecycleExplanationHistoryWithBase(baseLevel) {
  if (!state.workspaceNavigation.initialized
    || elements.appView.classList.contains("hidden")) return;
  const current = activeWorkspaceHistoryEntry();
  const route = visibleWorkspaceRoute();
  if (current?.route !== route
    || current.navigationLevel !== "slimmingRecycleExplanation") return;
  const context = currentWorkspaceHistoryContext(route);
  if (context && typeof context === "object") {
    delete context.slimmingRecycleExplanationBaseLevel;
  }
  const navigationLevel = visibleWorkspaceNavigationBaseLevel(route, baseLevel);
  history.replaceState({
    ...(history.state || {}),
    [WORKSPACE_HISTORY_KEY]: workspaceHistoryEntry(route, context, navigationLevel),
  }, "", location.href);
}

function clearSlimmingRecycleExplanationState() {
  const recycle = state.slimming.recycle;
  recycle.explanationEntryID = null;
  recycle.explanationReturnFocus = null;
  recycle.explanationBaseLevel = "workspace";
  recycle.explanationHistoryRestoreFocus = true;
  recycle.explanationRestorable = false;
  recycle.explanationOpening = false;
}

function presentSlimmingRecycleExplanation({
  historyMode = "pushSlimmingRecycleExplanation",
  baseLevel = null,
  focus = true,
} = {}) {
  const recycle = state.slimming.recycle;
  if (!renderSlimmingRecycleExplanation(recycle.explanationEntryID)) return;
  if (elements.slimmingRecycleExplanationDialog.open) {
    if (focus) restoreOverlayFocus(elements.closeSlimmingRecycleExplanationButton);
    return;
  }
  const current = activeWorkspaceHistoryEntry();
  recycle.explanationBaseLevel = baseLevel
    || workspaceNavigationBaseLevel(
      current?.navigationLevel || "workspace",
      current?.context || {}
    );
  elements.slimmingRecycleExplanationDialog.showModal();
  if (historyMode !== "none") {
    const route = visibleWorkspaceRoute();
    recordWorkspaceHistory(route, currentWorkspaceHistoryContext(route), historyMode);
  }
  recycle.explanationRestorable = true;
  if (focus) restoreOverlayFocus(elements.closeSlimmingRecycleExplanationButton);
}

function openSlimmingRecycleExplanation(entryID) {
  const recycle = state.slimming.recycle;
  if (!recycle.entries.some((item) => item.id === entryID)
    || elements.slimmingRecycleExplanationDialog.open
    || recycle.explanationOpening) return;
  recycle.explanationEntryID = entryID;
  recycle.explanationReturnFocus = document.activeElement;
  recycle.explanationOpening = true;
  try {
    presentSlimmingRecycleExplanation();
  } finally {
    recycle.explanationOpening = false;
  }
}

function closeSlimmingRecycleExplanation({
  restoreFocus = true,
  checkpoint = true,
  preserveState = false,
} = {}) {
  if (!elements.slimmingRecycleExplanationDialog.open) return;
  const recycle = state.slimming.recycle;
  const entryID = recycle.explanationEntryID;
  const fallback = recycle.explanationReturnFocus;
  const baseLevel = recycle.explanationBaseLevel;
  elements.slimmingRecycleExplanationDialog.close();
  const target = entryID
    ? elements.slimmingRecycleList.querySelector(
      `[data-slimming-recycle-explanation-id="${CSS.escape(entryID)}"]`
    )
    : null;
  if (restoreFocus) {
    restoreOverlayFocus(target || stableReturnFocusTarget(fallback, elements.slimmingButton));
  }
  if (checkpoint) replaceSlimmingRecycleExplanationHistoryWithBase(baseLevel);
  if (!preserveState) clearSlimmingRecycleExplanationState();
}

function returnFromSlimmingRecycleExplanation({ restoreFocus = true } = {}) {
  if (!elements.slimmingRecycleExplanationDialog.open) return Promise.resolve();
  const recycle = state.slimming.recycle;
  recycle.explanationHistoryRestoreFocus = restoreFocus;
  if (state.workspaceNavigation.pendingReturnPromise) {
    return state.workspaceNavigation.pendingReturnPromise;
  }
  const current = activeWorkspaceHistoryEntry();
  if (state.workspaceNavigation.initialized
    && current?.route === visibleWorkspaceRoute()
    && current.navigationLevel === "slimmingRecycleExplanation") {
    const pending = new Promise((resolve) => {
      state.workspaceNavigation.pendingReturnResolve = resolve;
    });
    state.workspaceNavigation.pendingReturnPromise = pending;
    history.back();
    return pending;
  }
  closeSlimmingRecycleExplanation({ restoreFocus });
  recycle.explanationHistoryRestoreFocus = true;
  return Promise.resolve();
}

function reconcileSlimmingRecycleExplanationFromWorkspaceHistory(
  route,
  navigationLevel,
  context = {}
) {
  const recycle = state.slimming.recycle;
  const shouldOpen = navigationLevel === "slimmingRecycleExplanation"
    && route === visibleWorkspaceRoute();
  const entryExists = recycle.entries.some(
    (entry) => entry.id === recycle.explanationEntryID
  );
  if (shouldOpen && (!recycle.explanationRestorable || !entryExists)) {
    clearSlimmingRecycleExplanationState();
    if (history.length > 1 && Object.prototype.hasOwnProperty.call(
      context,
      "slimmingRecycleExplanationBaseLevel"
    )) {
      history.back();
    } else {
      replaceSlimmingRecycleExplanationHistoryWithBase(
        slimmingRecycleExplanationBaseLevelFromHistory(context)
      );
    }
    return;
  }
  if (shouldOpen && !elements.slimmingRecycleExplanationDialog.open) {
    presentSlimmingRecycleExplanation({
      historyMode: "none",
      baseLevel: slimmingRecycleExplanationBaseLevelFromHistory(context),
    });
  } else if (!shouldOpen && elements.slimmingRecycleExplanationDialog.open) {
    const restoreFocus = recycle.explanationHistoryRestoreFocus;
    closeSlimmingRecycleExplanation({
      restoreFocus,
      checkpoint: false,
      preserveState: true,
    });
    recycle.explanationHistoryRestoreFocus = true;
  }
}

function renderSlimmingRecycleSourceOptions() {
  const previous = state.slimming.recycle.sourceID;
  const existingOptions = new Map(
    [...elements.slimmingRecycleSourceSelect.options].map((option) => [option.value, option])
  );
  const sources = [{ id: "", displayName: "全部来源" }, ...state.sources];
  const sourceOptions = sources.map((source) => {
    const option = existingOptions.get(source.id) || document.createElement("option");
    option.value = source.id;
    if (option.textContent !== source.displayName) option.textContent = source.displayName;
    return option;
  });
  reconcileStableChildren(elements.slimmingRecycleSourceSelect, sourceOptions);
  elements.slimmingRecycleSourceSelect.value = previous;
  if (elements.slimmingRecycleSourceSelect.value !== previous) {
    state.slimming.recycle.sourceID = "";
  }
}

function renderSlimmingRecycleScopes() {
  const recycle = state.slimming.recycle;
  const labels = {
    all: "全部",
    photos: "Photos",
    files: "文件夹",
    attention: "待处理",
  };
  for (const button of elements.slimmingRecycleScopes.querySelectorAll(
    "[data-slimming-recycle-scope]"
  )) {
    const scope = button.dataset.slimmingRecycleScope;
    const count = recycle.scopeSupported === false && scope !== "all"
      ? "—"
      : Number(recycle.scopeCounts?.[scope] || 0).toLocaleString();
    button.setAttribute("aria-pressed", String(scope === recycle.scope));
    button.disabled = recycle.scopeSupported === false && scope !== "all";
    button.title = button.disabled
      ? "需要新版 Mac Host 才能按状态范围筛选"
      : `只显示${labels[scope]}范围内的回收站项目`;
    button.setAttribute("aria-label", `${labels[scope]}，${count} 项`);
    const countLabel = button.querySelector("[data-slimming-recycle-scope-count]");
    if (countLabel) countLabel.textContent = count;
  }
  syncRovingSegmentedControl(
    elements.slimmingRecycleScopes,
    "[data-slimming-recycle-scope]"
  );
}

function renderSlimmingRecycleHeader() {
  const recycle = state.slimming.recycle;
  const allCount = recycle.scopeSupported === false
    ? Number(recycle.totalCount || 0)
    : Number(recycle.scopeCounts?.all || 0);
  const attentionCount = recycle.scopeSupported === true
    ? Number(recycle.scopeCounts?.attention || 0)
    : 0;
  const unit = state.slimming.mediaKind === "video" ? "个视频项目" : "张照片项目";
  elements.slimmingRecycleSummary.textContent = attentionCount > 0
    ? `当前 ${allCount.toLocaleString("zh-CN")} ${unit}，其中 ${attentionCount.toLocaleString("zh-CN")} 项需要关注`
    : `当前 ${allCount.toLocaleString("zh-CN")} ${unit}，均处于可恢复或系统管理状态`;

  const activeRequest = recycle.requests.some(
    (request) => ["awaitingMac", "running"].includes(request.phase)
  );
  elements.slimmingRecycleMutationStatus.classList.toggle(
    "hidden",
    recycle.mutatingEntryIDs.size === 0 && !activeRequest
  );

  const selectedSource = state.sources.find((source) => source.id === recycle.sourceID) || null;
  elements.slimmingRecycleSourceBanner.classList.toggle("hidden", !selectedSource);
  elements.slimmingRecycleSourceBannerName.textContent = selectedSource?.displayName || "";

  const hasSearch = Boolean(recycle.searchText.trim());
  elements.slimmingRecycleSearchResultCount.classList.toggle("hidden", !hasSearch);
  elements.clearSlimmingRecycleSearchButton.classList.toggle("hidden", !hasSearch);
  elements.slimmingRecycleSearchResultCount.textContent = hasSearch
    ? Number(recycle.totalCount || 0).toLocaleString("zh-CN")
    : "";
}

function renderSlimmingRecycleRequest() {
  const requests = state.slimming.recycle.requests || [];
  const active = requests.find((request) => ["awaitingMac", "running"].includes(request.phase));
  const latest = active || requests[0] || null;
  elements.slimmingRecycleRequestStatus.classList.toggle("hidden", !latest);
  elements.slimmingRecycleRequestStatus.textContent = latest
    ? `${latest.fileName || "回收站项目"}：${latest.message}`
    : "";
  if (!active && latest && ["completed", "cancelled", "failed"].includes(latest.phase)
    && state.slimming.recycle.lastTerminalRequestID !== latest.id) {
    state.slimming.recycle.lastTerminalRequestID = latest.id;
    toast(latest.message);
  }
}

function renderSlimmingRecycleSummary({ preserveSourceOptions = false } = {}) {
  const recycle = state.slimming.recycle;
  elements.slimmingRecycleSearchInput.value = recycle.searchText;
  if (preserveSourceOptions) {
    elements.slimmingRecycleSourceSelect.value = recycle.sourceID;
  } else {
    renderSlimmingRecycleSourceOptions();
  }
  renderSlimmingRecycleScopes();
  renderSlimmingRecycleHeader();
  const appending = recycle.appending === true;
  elements.slimmingRecycleCount.textContent = recycle.totalCount > recycle.entries.length
    ? `${recycle.entries.length} / ${recycle.totalCount} 项${appending ? " · 正在载入更多…" : ""}`
    : `${recycle.totalCount} 项`;
  elements.slimmingRecycleLoadMoreButton.classList.toggle(
    "hidden",
    !appending && recycle.entries.length >= recycle.totalCount
  );
  elements.slimmingRecycleLoadMoreButton.disabled = recycle.loading;
  elements.slimmingRecycleLoadMoreButton.textContent = appending
    ? "正在载入更多回收项目…"
    : `再显示 ${Math.min(60, Math.max(0, recycle.totalCount - recycle.entries.length))} 项（剩余 ${
      Math.max(0, recycle.totalCount - recycle.entries.length)
    } 项）`;
  elements.slimmingRecycleLoadMoreButton.setAttribute("aria-busy", String(appending));
  elements.slimmingRecycleEmpty.classList.toggle(
    "hidden",
    (recycle.loading && !appending) || recycle.entries.length > 0
  );
  const hasSearch = Boolean(recycle.searchText.trim());
  const hasSource = Boolean(recycle.sourceID);
  const allEmpty = Number(recycle.scopeCounts?.all || 0) === 0;
  let emptyPresentation;
  if (hasSearch) {
    emptyPresentation = {
      title: "没有匹配的媒体",
      message: `没有文件名包含“${recycle.searchText.trim()}”的回收站条目。`,
      action: "clearSearch",
      actionLabel: "清除搜索",
    };
  } else if (hasSource && allEmpty) {
    const sourceName = state.sources.find((source) => source.id === recycle.sourceID)
      ?.displayName || "当前来源";
    emptyPresentation = {
      title: "没有匹配的媒体",
      message: `“${sourceName}”当前没有回收或待处理项目。`,
      action: "clearSource",
      actionLabel: "显示全部来源",
    };
  } else if (recycle.scope !== "all" && recycle.entries.length === 0) {
    emptyPresentation = {
      title: "这个范围内没有媒体",
      message: "其他来源或处理状态中仍有回收站项目。",
      action: "showAll",
      actionLabel: "查看全部",
    };
  } else if (allEmpty) {
    emptyPresentation = {
      title: "回收站为空",
      message: "文件夹媒体在 ImageAll 中保留 30 天；Photos 项遵循系统“照片”App 的恢复规则。",
      action: null,
      actionLabel: "",
    };
  } else {
    emptyPresentation = {
      title: "没有匹配的媒体",
      message: "调整来源或清除文件名搜索以查看其他回收站项目。",
      action: "showAll",
      actionLabel: "查看全部",
    };
  }
  elements.slimmingRecycleEmptyTitle.textContent = emptyPresentation.title;
  elements.slimmingRecycleEmptyMessage.textContent = emptyPresentation.message;
  elements.slimmingRecycleEmptyAction.dataset.action = emptyPresentation.action || "";
  elements.slimmingRecycleEmptyAction.textContent = emptyPresentation.actionLabel;
  elements.slimmingRecycleEmptyAction.classList.toggle("hidden", !emptyPresentation.action);
  elements.slimmingRecycleList.classList.toggle("hidden", recycle.entries.length === 0);
}

function syncSlimmingRecycleRow(row, entry) {
  const recycle = state.slimming.recycle;
  let thumbnail = row.querySelector(":scope > .slimming-recycle-thumbnail-card");
  const reusesThumbnail = thumbnail?.dataset.slimmingRecycleAssetId === entry.assetID
    && thumbnail.dataset.slimmingRecycleMediaKind === entry.mediaKind;
  if (!reusesThumbnail) {
    thumbnail?.remove();
    thumbnail = document.createElement("div");
  }
  row.className = "slimming-recycle-row";
  row.dataset.slimmingRecycleRowId = entry.id;
  thumbnail.className = "slimming-recycle-thumbnail-card";
  thumbnail.dataset.slimmingRecycleThumbnailEntryId = entry.id;
  thumbnail.dataset.slimmingRecycleAssetId = entry.assetID;
  thumbnail.dataset.slimmingRecycleMediaKind = entry.mediaKind;
  thumbnail.tabIndex = -1;
  thumbnail.setAttribute("role", "group");
  thumbnail.setAttribute("aria-haspopup", "menu");
  thumbnail.setAttribute(
    "aria-label",
    `${entry.fileName || "未命名媒体"}，回收站缩略图`
  );
  configurePersistentHelp(thumbnail, {
    title: entry.fileName || "未命名媒体",
    detail: "右键、触控长按、Context Menu 或 Shift-F10 可加入或取消红心。"
      + (entry.sourceKind === "photos"
        ? " Apple Photos 的“最近删除”由系统管理，红心不能暂停系统永久删除。"
        : " 红心只用于整理，不会阻止恢复、回收或永久删除。"),
    kind: "slimming",
    keyShortcuts: "ArrowLeft ArrowRight ArrowUp ArrowDown Home End "
      + "PageUp PageDown Shift+F10 ContextMenu",
  });
  if (!reusesThumbnail) {
    const image = document.createElement("img");
    image.className = "slimming-recycle-thumbnail";
    image.alt = "";
    image.setAttribute("aria-hidden", "true");
    syncProtectedThumbnailSource(image, entry.assetID, { width: 180 });
    thumbnail.append(image);
    if (entry.mediaKind === "video") {
      const video = document.createElement("span");
      video.className = "slimming-recycle-video-badge";
      video.textContent = "▶";
      video.setAttribute("aria-label", "视频代表缩略图");
      thumbnail.append(video);
    }
  }
  syncSlimmingRecycleFavoriteButton(thumbnail, entry);

  const copy = row.querySelector(":scope > .slimming-recycle-copy")
    || document.createElement("div");
  copy.className = "slimming-recycle-copy";
  const title = copy.querySelector(":scope > strong") || document.createElement("strong");
  title.textContent = entry.fileName || "未命名媒体";
  const meta = copy.querySelector(":scope > .slimming-recycle-meta")
    || document.createElement("span");
  meta.className = "slimming-recycle-meta";
  const sourceKind = entry.sourceKind === "photos" ? "Apple Photos" : "文件夹";
  const sourceName = entry.sourceDisplayName && entry.sourceDisplayName !== sourceKind
    ? ` · ${entry.sourceDisplayName}`
    : "";
  meta.textContent = `${sourceKind}${sourceName} · ${slimmingRecycleMovedCaption(entry)}`;
  const detail = copy.querySelector(":scope > .slimming-recycle-detail")
    || document.createElement("span");
  detail.className = "slimming-recycle-detail";
  detail.classList.toggle("warning", entry.resolution !== "restoreOrPurge"
    && entry.resolution !== "photosManagedBySystem");
  detail.classList.toggle(
    "folder-countdown",
    entry.state === "recycled" && entry.sourceKind === "file"
  );
  const detailIcon = detail.querySelector(":scope > .slimming-recycle-detail-icon")
    || document.createElement("span");
  detailIcon.className = "slimming-recycle-detail-icon";
  detailIcon.setAttribute("aria-hidden", "true");
  detailIcon.textContent = slimmingRecycleLifecycleIcon(entry);
  const detailText = detail.querySelector(":scope > span:not(.slimming-recycle-detail-icon)")
    || document.createElement("span");
  detailText.textContent = slimmingRecycleStateCopy(entry);
  reconcileStableChildren(detail, [detailIcon, detailText]);
  reconcileStableChildren(copy, [title, meta, detail]);

  const policy = row.querySelector(":scope > .slimming-recycle-policy")
    || document.createElement("span");
  policy.className = "slimming-recycle-policy";
  policy.textContent = slimmingRecyclePolicyCopy(entry);
  const actions = row.querySelector(":scope > .slimming-recycle-actions")
    || document.createElement("div");
  actions.className = "slimming-recycle-actions";
  const existingActions = new Map(
    [...actions.querySelectorAll(":scope > [data-slimming-recycle-action-key]")]
      .map((button) => [button.dataset.slimmingRecycleActionKey, button])
  );
  const actionButton = (key) => {
    const button = existingActions.get(key) || document.createElement("button");
    button.type = "button";
    button.dataset.slimmingRecycleActionKey = key;
    return button;
  };
  const wantedActions = [];
  if (entry.resolution === "photosManagedBySystem") {
    const info = actionButton("explanation");
    info.className = "button button-compact button-primary";
    info.dataset.slimmingRecycleExplanationId = entry.id;
    info.dataset.helpDetail = "查看如何从 Apple Photos“最近删除”中恢复这个媒体。";
    info.textContent = "恢复说明";
    wantedActions.push(info);
  }
  const recovery = slimmingRecycleRecoveryDescriptor(entry);
  if (recovery) {
    const button = actionButton(`recovery:${recovery.action}`);
    button.className = `button button-compact button-primary${
      recovery.kind === "source" ? " write-action" : ""
    }`;
    button.dataset.slimmingRecycleEntryId = entry.id;
    button.dataset.slimmingRecycleRecoveryKind = recovery.kind;
    button.dataset.slimmingRecycleRecoveryAction = recovery.action;
    button.dataset.helpDetail = recovery.help;
    button.disabled = recycle.mutatingEntryIDs.has(entry.id)
      || (recovery.kind === "source"
        && (state.sourceManagement.submitting || sourceManagementHasActiveRequest()));
    button.textContent = recovery.label;
    wantedActions.push(button);
  }
  for (const action of entry.availableActions || []) {
    const button = actionButton(`direct:${action}`);
    const primary = ["restore", "retryInterruptedOperation"].includes(action)
      ? " button-primary"
      : "";
    button.className = `button button-compact write-action${primary}${
      action === "purge" ? " button-danger" : ""
    }`;
    button.dataset.slimmingRecycleEntryId = entry.id;
    button.dataset.action = action;
    button.dataset.helpDetail = slimmingRecycleDirectActionHelp(entry, action);
    button.disabled = recycle.mutatingEntryIDs.has(entry.id);
    button.textContent = slimmingRecycleDirectActionLabel(entry, action);
    wantedActions.push(button);
  }
  if (slimmingRecycleShowsExplanation(entry)) {
    const explanation = actionButton("explanation");
    explanation.className = "button button-compact";
    explanation.dataset.slimmingRecycleExplanationId = entry.id;
    explanation.dataset.helpDetail = "说明本次操作为何未完成，以及下一步如何处理。";
    explanation.textContent = "说明";
    wantedActions.push(explanation);
  }
  reconcileStableChildren(actions, wantedActions);
  reconcileStableChildren(row, [thumbnail, copy, policy, actions]);
  return row;
}

function slimmingRecycleGridRovingEntryID() {
  const visibleIDs = new Set(state.slimming.recycle.entries.map((entry) => entry.id));
  const focusedRow = document.activeElement?.closest?.(
    "#slimmingRecycleList > .slimming-recycle-row"
  );
  if (visibleIDs.has(focusedRow?.dataset.slimmingRecycleRowId)) {
    return focusedRow.dataset.slimmingRecycleRowId;
  }
  if (visibleIDs.has(state.slimming.recycle.focusEntryID)) {
    return state.slimming.recycle.focusEntryID;
  }
  return state.slimming.recycle.entries[0]?.id || null;
}

function syncSlimmingRecycleRowKeyboardAccess(
  row,
  rovingEntryID = slimmingRecycleGridRovingEntryID()
) {
  const isTabStop = row?.dataset.slimmingRecycleRowId === rovingEntryID;
  const thumbnail = row?.querySelector(":scope > .slimming-recycle-thumbnail-card");
  if (thumbnail) thumbnail.tabIndex = isTabStop ? 0 : -1;
  for (const button of row?.querySelectorAll("button") || []) {
    button.tabIndex = isTabStop && !button.disabled ? 0 : -1;
  }
}

function syncSlimmingRecycleGridTabStops(entryID = null) {
  const visibleIDs = new Set(state.slimming.recycle.entries.map((entry) => entry.id));
  if (entryID && visibleIDs.has(entryID)) state.slimming.recycle.focusEntryID = entryID;
  const rovingEntryID = slimmingRecycleGridRovingEntryID();
  state.slimming.recycle.focusEntryID = rovingEntryID;
  for (const row of elements.slimmingRecycleList.querySelectorAll(
    ":scope > .slimming-recycle-row"
  )) {
    syncSlimmingRecycleRowKeyboardAccess(row, rovingEntryID);
  }
}

function appendSlimmingRecycleRows(entries, rovingEntryID) {
  const fragment = document.createDocumentFragment();
  for (const entry of entries) {
    const row = syncSlimmingRecycleRow(document.createElement("article"), entry);
    syncSlimmingRecycleRowKeyboardAccess(row, rovingEntryID);
    fragment.append(row);
  }
  elements.slimmingRecycleList.append(fragment);
}

function updateSlimmingRecycleRows(entryIDs, rovingEntryID) {
  const entriesByID = new Map(
    state.slimming.recycle.entries.map((entry) => [entry.id, entry])
  );
  for (const entryID of entryIDs) {
    const entry = entriesByID.get(entryID);
    const row = elements.slimmingRecycleList.querySelector(
      `[data-slimming-recycle-row-id="${CSS.escape(entryID)}"]`
    );
    if (!entry || !row) continue;
    syncSlimmingRecycleRow(row, entry);
    syncSlimmingRecycleRowKeyboardAccess(row, rovingEntryID);
  }
}

function syncSlimmingRecycleAppendLocks() {
  if (!state.slimming.recycle.appending) return;
  for (const button of elements.slimmingRecycleList.querySelectorAll("button.write-action")) {
    button.disabled = true;
  }
}

function renderSlimmingRecycle({
  appendItems = null,
  updateEntryIDs = null,
  preserveList = false,
  preserveSourceOptions = false,
} = {}) {
  const rovingEntryID = slimmingRecycleGridRovingEntryID();
  state.slimming.recycle.focusEntryID = rovingEntryID;
  renderSlimmingRecycleSummary({ preserveSourceOptions });
  if (appendItems === null && !preserveList) {
    clearElement(elements.slimmingRecycleList);
    appendSlimmingRecycleRows(state.slimming.recycle.entries, rovingEntryID);
  } else if (appendItems !== null) {
    appendSlimmingRecycleRows(appendItems, rovingEntryID);
  } else if (updateEntryIDs !== null) {
    updateSlimmingRecycleRows(updateEntryIDs, rovingEntryID);
  }
  renderSlimmingRecycleRequest();
  syncWriteActionControls();
  syncSlimmingRecycleAppendLocks();
  syncSlimmingRecycleGridTabStops();
}

function renderSlimmingRecycleEntryState(entryID, continuity = null) {
  renderSlimmingRecycle({
    updateEntryIDs: [entryID],
    preserveList: true,
    preserveSourceOptions: true,
  });
  if (continuity) restoreSlimmingRecycleContinuity(continuity);
}

function scheduleSlimmingRecyclePoll() {
  clearTimeout(state.slimming.recycle.pollTimer);
  state.slimming.recycle.pollTimer = null;
  if (elements.slimmingWorkspace.classList.contains("hidden")
    || state.slimming.view !== "recycle") return;
  const active = state.slimming.recycle.requests.some(
    (request) => ["awaitingMac", "running"].includes(request.phase)
  );
  if (!active) return;
  state.slimming.recycle.pollTimer = setTimeout(() => {
    loadSlimmingRecycle({ quiet: true });
  }, 1000);
}

function renderedSlimmingRecycleEntriesMatch(entries) {
  return renderedSlimmingCollectionMatches(
    elements.slimmingRecycleList,
    ".slimming-recycle-row[data-slimming-recycle-row-id]",
    entries,
    "slimmingRecycleRowId"
  );
}

function slimmingRecycleQuerySignature() {
  const recycle = state.slimming.recycle;
  return JSON.stringify({
    mediaKind: state.slimming.mediaKind,
    scope: recycle.scope,
    sourceID: recycle.sourceID,
    searchText: recycle.searchText.trim(),
  });
}

function restoreRenderedSlimmingRecycleQuery() {
  const recycle = state.slimming.recycle;
  if (!recycle.renderedQuerySignature) return false;
  let renderedQuery;
  try {
    renderedQuery = JSON.parse(recycle.renderedQuerySignature);
  } catch {
    return false;
  }
  if (!renderedQuery || !["image", "video"].includes(renderedQuery.mediaKind)) return false;
  state.slimming.mediaKind = renderedQuery.mediaKind;
  recycle.scope = ["all", "photos", "files", "attention"].includes(renderedQuery.scope)
    ? renderedQuery.scope
    : "all";
  recycle.sourceID = typeof renderedQuery.sourceID === "string"
    ? renderedQuery.sourceID
    : "";
  recycle.searchText = typeof renderedQuery.searchText === "string"
    ? renderedQuery.searchText
    : "";
  recycle.limit = Number.isFinite(recycle.renderedLimit)
    ? recycle.renderedLimit
    : 60;
  return true;
}

function slimmingRecycleEntryFingerprint(entry) {
  return JSON.stringify(entry);
}

function slimmingRecycleEntriesShareStructure(left, right) {
  return left.length === right.length
    && left.every((entry, index) => entry.id === right[index]?.id);
}

function captureSlimmingRecycleContinuity() {
  const active = document.activeElement;
  const row = active?.closest?.("[data-slimming-recycle-row-id]") || null;
  let actionSelector = null;
  if (active?.classList?.contains("slimming-recycle-favorite")) {
    actionSelector = ".slimming-recycle-favorite";
  } else if (active?.dataset?.action) {
    actionSelector = `[data-action="${CSS.escape(active.dataset.action)}"]`;
  } else if (active?.dataset?.slimmingRecycleRecoveryAction) {
    actionSelector = `[data-slimming-recycle-recovery-action="${CSS.escape(
      active.dataset.slimmingRecycleRecoveryAction
    )}"]`;
  } else if (active?.dataset?.slimmingRecycleExplanationId) {
    actionSelector = "[data-slimming-recycle-explanation-id]";
  }
  return {
    scrollTop: elements.slimmingRecycleBody.scrollTop,
    focusedEntryID: row?.dataset.slimmingRecycleRowId || null,
    actionSelector,
    focusedControlID: active?.id || null,
    previousLastEntryID: state.slimming.recycle.entries.at(-1)?.id || null,
  };
}

function captureSlimmingRecycleActionContinuity(entryID, actionSelector) {
  return {
    ...captureSlimmingRecycleContinuity(),
    focusedEntryID: entryID,
    actionSelector,
  };
}

function restoreSlimmingRecycleContinuity(continuity) {
  if (!continuity) return;
  elements.slimmingRecycleBody.scrollTop = continuity.scrollTop;
  let target = null;
  if (continuity.focusedEntryID) {
    const row = elements.slimmingRecycleList.querySelector(
      `[data-slimming-recycle-row-id="${CSS.escape(continuity.focusedEntryID)}"]`
    );
    target = continuity.actionSelector
      ? row?.querySelector(continuity.actionSelector)
      : row?.querySelector(":scope > .slimming-recycle-thumbnail-card");
    if (target?.disabled) target = null;
    if (!target) {
      target = row?.querySelector(":scope > .slimming-recycle-thumbnail-card")
        || slimmingRecycleFocusTarget();
    }
  }
  if (!target && continuity.focusedControlID) {
    const control = document.getElementById(continuity.focusedControlID);
    if (control && !control.classList.contains("hidden") && !control.disabled) target = control;
  }
  if (!target && continuity.focusedControlID === "slimmingRecycleLoadMoreButton") {
    target = elements.slimmingRecycleList.querySelector(
      `[data-slimming-recycle-row-id="${CSS.escape(
        continuity.previousLastEntryID || ""
      )}"] > .slimming-recycle-thumbnail-card`
    );
  }
  if (!target) target = slimmingRecycleFocusTarget();
  target?.focus({ preventScroll: true });
}

function slimmingRecycleAppendSnapshotIsStable(previous, snapshot) {
  const nextEntries = snapshot.entries || [];
  const nextTotalCount = Number(snapshot.totalCount || 0);
  const nextScopeSupported = Boolean(snapshot.scopeCounts);
  const nextScopeCounts = nextScopeSupported
    ? {
      all: Number(snapshot.scopeCounts.all || 0),
      photos: Number(snapshot.scopeCounts.photos || 0),
      files: Number(snapshot.scopeCounts.files || 0),
      attention: Number(snapshot.scopeCounts.attention || 0),
    }
    : { all: nextTotalCount, photos: 0, files: 0, attention: 0 };
  const queryStable = state.slimming.mediaKind === previous.mediaKind
    && state.slimming.recycle.scope === previous.scope
    && state.slimming.recycle.sourceID === previous.sourceID
    && state.slimming.recycle.searchText === previous.searchText;
  return queryStable
    && (!snapshot.mediaKind || snapshot.mediaKind === previous.mediaKind)
    && nextTotalCount === previous.totalCount
    && nextScopeSupported === previous.scopeSupported
    && JSON.stringify(nextScopeCounts) === JSON.stringify(previous.scopeCounts)
    && slimmingItemsEqual(previous.requests, snapshot.requests || [])
    && slimmingItemsFormStablePrefix(previous.entries, nextEntries)
    && previous.renderedEntriesMatch;
}

async function loadSlimmingRecycle({ quiet = false, append = false } = {}) {
  const recycle = state.slimming.recycle;
  const generation = ++recycle.requestGeneration;
  const appending = append === true;
  const requestSignature = slimmingRecycleQuerySignature();
  const renderedQueryMatches = recycle.renderedQuerySignature === requestSignature;
  const queryTransition = recycle.renderedQuerySignature !== null
    && !renderedQueryMatches;
  const renderedEntriesMatch = renderedSlimmingRecycleEntriesMatch(recycle.entries);
  const canPreserveCurrentList = renderedEntriesMatch && renderedQueryMatches;
  const canPreserveLoadingList = renderedEntriesMatch;
  const previous = {
    mediaKind: state.slimming.mediaKind,
    scope: recycle.scope,
    sourceID: recycle.sourceID,
    searchText: recycle.searchText,
    entries: recycle.entries,
    totalCount: Number(recycle.totalCount || 0),
    scopeSupported: recycle.scopeSupported === true,
    scopeCounts: recycle.scopeSupported === true
      ? { ...recycle.scopeCounts }
      : { all: Number(recycle.totalCount || 0), photos: 0, files: 0, attention: 0 },
    requests: recycle.requests,
    renderedEntriesMatch,
    continuity: appending || canPreserveCurrentList
      ? captureSlimmingRecycleContinuity()
      : null,
  };
  let renderOptions = appending || canPreserveLoadingList
    ? { preserveRecycle: true }
    : {};
  recycle.loading = true;
  recycle.appending = appending;
  renderSlimmingWorkspace(renderOptions);
  const query = new URLSearchParams({
    mediaKind: state.slimming.mediaKind,
    scope: recycle.scope,
    limit: String(recycle.limit),
  });
  if (recycle.sourceID) query.set("sourceID", recycle.sourceID);
  if (recycle.searchText.trim()) query.set("search", recycle.searchText.trim());
  try {
    const snapshot = await api(`/v1/library-slimming/recycle?${query}`);
    if (generation !== recycle.requestGeneration) return false;
    const nextEntries = snapshot.entries || [];
    const appendIsStable = appending
      ? slimmingRecycleAppendSnapshotIsStable(previous, snapshot)
      : false;
    const entriesAreUnchanged = !appending
      && previous.renderedEntriesMatch
      && slimmingItemsEqual(previous.entries, nextEntries);
    const canUpdateExistingRows = !appending
      && previous.renderedEntriesMatch
      && slimmingRecycleEntriesShareStructure(previous.entries, nextEntries);
    const updatedEntryIDs = canUpdateExistingRows
      ? nextEntries
        .filter((entry, index) => (
          slimmingRecycleEntryFingerprint(entry)
            !== slimmingRecycleEntryFingerprint(previous.entries[index])
        ))
        .map((entry) => entry.id)
      : null;
    recycle.entries = nextEntries;
    recycle.totalCount = snapshot.totalCount || 0;
    recycle.requests = snapshot.requests || [];
    if (snapshot.scopeCounts) {
      recycle.scopeSupported = true;
      recycle.scopeCounts = {
        all: Number(snapshot.scopeCounts.all || 0),
        photos: Number(snapshot.scopeCounts.photos || 0),
        files: Number(snapshot.scopeCounts.files || 0),
        attention: Number(snapshot.scopeCounts.attention || 0),
      };
    } else {
      recycle.scopeSupported = false;
      recycle.scope = "all";
      recycle.scopeCounts = {
        all: recycle.totalCount,
        photos: 0,
        files: 0,
        attention: 0,
      };
    }
    if (appendIsStable) {
      renderOptions = { appendRecycle: nextEntries.slice(previous.entries.length) };
    } else if (entriesAreUnchanged) {
      renderOptions = { preserveRecycle: true };
    } else if (updatedEntryIDs !== null) {
      renderOptions = { preserveRecycle: true, updateRecycleIDs: updatedEntryIDs };
    } else {
      renderOptions = {};
    }
    recycle.renderedQuerySignature = slimmingRecycleQuerySignature();
    recycle.renderedLimit = recycle.limit;
    return true;
  } catch (error) {
    if (generation === recycle.requestGeneration) {
      const restoredQuery = queryTransition && restoreRenderedSlimmingRecycleQuery();
      if (!quiet || restoredQuery) toast(error.message || "回收站载入失败");
    }
    return false;
  } finally {
    if (generation === recycle.requestGeneration) {
      recycle.loading = false;
      recycle.appending = false;
      renderSlimmingWorkspace(renderOptions);
      if (previous.continuity) restoreSlimmingRecycleContinuity(previous.continuity);
      scheduleSlimmingRecyclePoll();
    }
  }
}

async function submitSlimmingRecycleAction(entryID, action, { confirmed = false } = {}) {
  const entry = state.slimming.recycle.entries.find((item) => item.id === entryID);
  if (!entry
    || state.slimming.recycle.appending
    || state.slimming.recycle.mutatingEntryIDs.has(entryID)) return;
  if (!confirmed && ["purge", "discardPreflightFailure"].includes(action)) {
    const purge = action === "purge";
    requestConfirmation({
      eyebrow: purge ? "PERMANENT DELETE" : "RECYCLE RECORD",
      title: purge
        ? `永久删除“${entry.fileName || "未命名媒体"}”？`
        : "撤销这条未执行的失败记录？",
      message: purge
        ? "网页提交后还必须在 Mac 上再次确认。操作完成后将无法从 ImageAll 恢复。"
        : "只移除失败意图，不会读取、移动、覆盖或删除原文件。",
      actionLabel: purge ? "继续删除" : "撤销失败记录",
      tone: purge ? "danger" : "standard",
      returnFocus: { recycleEntryID: entryID, recycleAction: action },
      action: () => submitSlimmingRecycleAction(entryID, action, { confirmed: true }),
    });
    return;
  }
  const continuity = captureSlimmingRecycleActionContinuity(
    entryID,
    `[data-action="${CSS.escape(action)}"]`
  );
  state.slimming.recycle.mutatingEntryIDs.add(entryID);
  renderSlimmingRecycleEntryState(entryID, continuity);
  try {
    const request = await api("/v1/library-slimming/recycle/requests", {
      method: "POST",
      body: JSON.stringify({ operationID: crypto.randomUUID(), entryID, action }),
    });
    state.slimming.recycle.requests = [
      request,
      ...state.slimming.recycle.requests.filter((item) => item.id !== request.id),
    ];
    toast(request.phase === "awaitingMac" ? "请回到 Mac 完成确认" : request.message);
  } catch (error) {
    toast(error.message || "回收站操作提交失败");
  } finally {
    state.slimming.recycle.mutatingEntryIDs.delete(entryID);
    renderSlimmingRecycleEntryState(entryID, continuity);
    scheduleSlimmingRecyclePoll();
  }
}

async function submitSlimmingRecycleRecoveryAction(entryID, action) {
  const recycle = state.slimming.recycle;
  const entry = recycle.entries.find((item) => item.id === entryID);
  if (!entry
    || recycle.appending
    || recycle.mutatingEntryIDs.has(entryID)
    || state.sourceManagement.submitting
    || sourceManagementHasActiveRequest()) return;
  const continuity = captureSlimmingRecycleActionContinuity(
    entryID,
    `[data-slimming-recycle-recovery-action="${CSS.escape(action)}"]`
  );
  recycle.mutatingEntryIDs.add(entryID);
  renderSlimmingRecycleEntryState(entryID, continuity);
  try {
    await submitSourceManagementAction(action, entry.sourceID);
  } finally {
    recycle.mutatingEntryIDs.delete(entryID);
    renderSlimmingRecycleEntryState(entryID, continuity);
  }
}

async function setSlimmingView(view) {
  if (!['analysis', 'recycle'].includes(view) || view === state.slimming.view) return;
  finishSlimmingMarqueeSelection();
  hideContextMenus();
  state.slimming.selectionMode = false;
  state.slimming.view = view;
  renderSlimmingWorkspace();
  if (view === "recycle") await loadSlimmingRecycle();
  else {
    await loadSlimmingWorkspace();
    await loadSlimmingRemovals({ quiet: true });
    await loadSlimmingIdenticalCleanupRequests({ quiet: true });
  }
}

function renderSlimmingNavigator() {
  const analysisView = state.slimming.view === "analysis";
  const visible = state.slimming.navigatorVisible;
  elements.slimmingNavigatorButton.classList.toggle("hidden", !analysisView);
  elements.slimmingNavigatorButton.setAttribute("aria-pressed", String(visible));
  elements.slimmingNavigatorButton.setAttribute(
    "aria-label",
    visible ? "隐藏分析记录" : "显示分析记录"
  );
  elements.slimmingNavigatorButton.title = visible
    ? "隐藏分析记录与候选分组，让媒体网格使用全部宽度"
    : "显示分析记录与候选分组";
  elements.slimmingAnalysisBody.classList.toggle("navigator-hidden", !visible);
}

function toggleSlimmingNavigator() {
  state.slimming.navigatorVisible = !state.slimming.navigatorVisible;
  renderSlimmingNavigator();
  elements.slimmingNavigatorButton.focus({ preventScroll: true });
}

function syncSlimmingAppendInteractionLocks() {
  const locked = Boolean(state.slimming.appending);
  for (const button of elements.slimmingJobActions.querySelectorAll(
    "[data-slimming-job-action-id]"
  )) {
    button.disabled = locked
      || state.slimming.jobMutatingIDs.has(button.dataset.slimmingJobActionId);
  }
  for (const button of elements.slimmingClusterList.querySelectorAll(
    "[data-slimming-cluster-id]"
  )) {
    button.disabled = locked;
  }
  for (const button of elements.slimmingClusterList.querySelectorAll(
    "[data-slimming-cluster-review-id][data-slimming-cluster-review]"
  )) {
    const cluster = state.slimming.clusters.find(
      (item) => item.id === button.dataset.slimmingClusterReviewId
    );
    button.disabled = locked
      || !state.online
      || state.slimming.clusterReviewPendingIDs.has(button.dataset.slimmingClusterReviewId)
      || cluster?.reviewDisposition === button.dataset.slimmingClusterReview;
  }
  const selectedCluster = state.slimming.clusters.find(
    (item) => item.id === state.slimming.selectedClusterID
  );
  elements.slimmingReprocessClusterButton.disabled = locked
    || !state.online
    || !selectedCluster
    || state.slimming.clusterReviewPendingIDs.has(selectedCluster.id);
}

function renderSlimmingWorkspace({
  preserveJobs = false,
  preserveClusters = false,
  preserveMembers = false,
  appendJobs = null,
  appendClusters = null,
  appendMembers = null,
  preserveRecycle = false,
  appendRecycle = null,
  updateRecycleIDs = null,
} = {}) {
  const recycleView = state.slimming.view === "recycle";
  renderSlimmingNavigator();
  renderSlimmingCurrentJobControls();
  renderSlimmingCatalogCommands();
  elements.slimmingThumbnailLayoutControls.classList.toggle("recycle-view", recycleView);
  for (const button of elements.slimmingWorkspaceTabs.querySelectorAll("[data-slimming-view]")) {
    button.setAttribute("aria-pressed", String(button.dataset.slimmingView === state.slimming.view));
  }
  syncRovingSegmentedControl(elements.slimmingWorkspaceTabs, "[data-slimming-view]");
  for (const button of elements.slimmingMediaKindTabs.querySelectorAll(
    "[data-slimming-media-kind]"
  )) {
    button.setAttribute(
      "aria-pressed",
      String(button.dataset.slimmingMediaKind === state.slimming.mediaKind)
    );
  }
  syncRovingSegmentedControl(
    elements.slimmingMediaKindTabs,
    "[data-slimming-media-kind]"
  );
  elements.slimmingAnalysisBody.classList.toggle("hidden", recycleView);
  elements.slimmingRecycleBody.classList.toggle("hidden", !recycleView);
  if (recycleView) {
    closeSlimmingCatalogSourcePicker({ restoreFocus: false });
    closeSlimmingAnalysisOptions({ restoreFocus: false });
  }
  const identicalGroupCount = state.slimming.clusters.filter(
    (cluster) => cluster.kind === "byteIdentical"
      || (state.slimming.mediaKind === "image"
        && cluster.kind === "perceptualDuplicate"
        && cluster.score === 1)
  ).length;
  const identicalActive = currentSlimmingIdenticalCleanupRequest();
  const analysisBlocksIdenticalCleanup = state.slimming.jobs.some(
    (job) => ["pending", "running"].includes(job.state)
  );
  elements.slimmingIdenticalCleanupButton.classList.toggle(
    "hidden",
    recycleView || identicalGroupCount === 0
  );
  elements.slimmingIdenticalCleanupButton.disabled = state.slimming.loading
    || state.slimming.identicalCleanup.preparing
    || state.slimming.identicalCleanup.submitting
    || analysisBlocksIdenticalCleanup
    || ["awaitingMac", "running"].includes(identicalActive?.phase);
  elements.slimmingIdenticalCleanupButton.textContent = identicalGroupCount
    ? `一键清理重复媒体（${identicalGroupCount} 组）…`
    : "一键清理重复媒体…";
  elements.slimmingIdenticalCleanupButton.setAttribute(
    "aria-label",
    identicalGroupCount
      ? `一键清理重复媒体，共 ${identicalGroupCount} 组`
      : "一键清理重复媒体"
  );
  elements.slimmingIdenticalCleanupButton.title = analysisBlocksIdenticalCleanup
    ? "请先等待当前分析完成或暂停"
    : "处理原文件完全相同及视觉匹配 100% 的照片；每组保留文件最大、同大小时日期最早的一项";
  const loading = recycleView ? state.slimming.recycle.loading : state.slimming.loading;
  elements.refreshSlimmingButton.disabled = loading;
  elements.refreshSlimmingButton.setAttribute("aria-busy", String(loading));
  const noun = state.slimming.mediaKind === "video" ? "视频" : "照片";
  elements.slimmingNoticeText.textContent = recycleView
    ? "回收站状态来自这台 Mac；恢复、重新协调和永久删除必须在 Mac 原生窗口确认。Apple Photos 仍由系统“照片”App 管理。"
    : "分析与任务控制由这台 Mac 执行；网页只接收结果。";
  elements.slimmingSummary.textContent = recycleView
    ? (state.slimming.recycle.loading
      ? (state.slimming.recycle.appending
        ? `${state.slimming.recycle.entries.length} / ${state.slimming.recycle.totalCount} 项 · 正在载入更多回收项目…`
        : `正在读取${noun}回收站…`)
      : `${state.slimming.recycle.totalCount} 个${noun}回收项目`)
    : (state.slimming.loading
      ? (state.slimming.appending
        ? `${state.slimming.jobs.length} 条记录 · 正在载入更多${
          { jobs: "记录", clusters: "分组", members: "成员" }[state.slimming.appending]
        }…`
        : `正在读取${noun}分析记录…`)
      : `${state.slimming.jobs.length} 条记录 · ${state.slimming.jobs.find((job) => job.id === state.slimming.selectedJobID)?.clusterCount || 0} 个候选分组`);
  if (recycleView) {
    renderSlimmingRecycle({
      appendItems: appendRecycle,
      updateEntryIDs: updateRecycleIDs,
      preserveList: preserveRecycle,
      preserveSourceOptions: preserveRecycle
        || appendRecycle !== null
        || updateRecycleIDs !== null,
    });
    renderSlimmingInspector();
    return;
  }
  if (appendJobs !== null) renderSlimmingJobs({ appendItems: appendJobs });
  else if (preserveJobs) {
    renderSlimmingJobSummary();
    renderSlimmingJobActions();
  }
  else renderSlimmingJobs();
  if (appendClusters !== null) renderSlimmingClusters({ appendItems: appendClusters });
  else if (preserveClusters) renderSlimmingClusterSummary();
  else renderSlimmingClusters();
  if (appendMembers !== null) renderSlimmingMembers({ appendItems: appendMembers });
  else if (preserveMembers) {
    renderSlimmingMemberSummary();
    renderSlimmingMemberSelection({ renderInspector: false });
  } else {
    renderSlimmingMembers();
  }
  renderSlimmingInspector();
  renderSlimmingJobStatus();
  renderSlimmingRemovalStatus();
  syncSlimmingAppendInteractionLocks();
  state.slimming.renderedCollectionFingerprint = slimmingWorkspaceCollectionFingerprint();
}

function scheduleSlimmingRemovalPoll() {
  clearTimeout(state.slimming.removal.pollTimer);
  state.slimming.removal.pollTimer = null;
  const active = state.slimming.removal.requests.some(
    (request) => request.phase === "awaitingMac" || request.phase === "running"
  );
  if (!active || elements.slimmingWorkspace.classList.contains("hidden")) return;
  state.slimming.removal.pollTimer = setTimeout(
    () => loadSlimmingRemovals({ quiet: true }),
    900
  );
}

async function loadSlimmingRemovals({ quiet = false } = {}) {
  const generation = ++state.slimming.removal.requestGeneration;
  const previouslyActiveIDs = new Set(
    state.slimming.removal.requests
      .filter((request) => request.phase === "awaitingMac" || request.phase === "running")
      .map((request) => request.id)
  );
  state.slimming.removal.loading = true;
  try {
    const query = new URLSearchParams({ mediaKind: state.slimming.mediaKind });
    const snapshot = await api(`/v1/library-slimming/removals?${query}`);
    if (generation !== state.slimming.removal.requestGeneration) return;
    state.slimming.removal.requests = snapshot.requests || [];
    const terminal = state.slimming.removal.requests.find((request) =>
      previouslyActiveIDs.has(request.id)
        && ["completed", "cancelled", "failed"].includes(request.phase)
    );
    if (terminal && terminal.id !== state.slimming.removal.lastTerminalRequestID) {
      state.slimming.removal.lastTerminalRequestID = terminal.id;
      const hidden = new Set(terminal.audit?.hiddenAssetIDs || []);
      if (hidden.size) {
        state.slimming.members = state.slimming.members.filter((member) => !hidden.has(member.id));
        state.slimming.selectedMemberIDs = new Set(
          [...state.slimming.selectedMemberIDs].filter((id) => !hidden.has(id))
        );
      }
      toast(terminal.message || "批量操作已结束");
      if (terminal.phase === "completed") {
        await loadSlimmingWorkspace({ quiet: true });
      }
      reconcileSlimmingPreviewAfterRemoval(terminal, hidden);
    }
  } catch (error) {
    if (generation === state.slimming.removal.requestGeneration && !quiet) {
      toast(error.message || "批量操作状态载入失败");
    }
  } finally {
    if (generation === state.slimming.removal.requestGeneration) {
      state.slimming.removal.loading = false;
      renderSlimmingWorkspace();
      scheduleSlimmingRemovalPoll();
    }
  }
}

function replacementPreviewAssetID(previousIDs, remainingIDs, previewAssetID) {
  if (remainingIDs.includes(previewAssetID)) return previewAssetID;
  const previousIndex = previousIDs.indexOf(previewAssetID);
  if (previousIndex < 0) return null;
  const remaining = new Set(remainingIDs);
  for (let index = previousIndex + 1; index < previousIDs.length; index += 1) {
    if (remaining.has(previousIDs[index])) return previousIDs[index];
  }
  for (let index = previousIndex - 1; index >= 0; index -= 1) {
    if (remaining.has(previousIDs[index])) return previousIDs[index];
  }
  return null;
}

function continuedAssetIDs(previousIDs, currentIDs) {
  const previous = new Set(previousIDs);
  return [
    ...previousIDs,
    ...currentIDs.filter((assetID) => !previous.has(assetID)),
  ];
}

function replacementSlimmingPreviewAssetID(previousIDs, remainingIDs, previewAssetID) {
  return replacementPreviewAssetID(previousIDs, remainingIDs, previewAssetID);
}

function reconcileSlimmingPreviewAfterRemoval(request, hiddenAssetIDs) {
  const context = state.slimming.removal.previewContexts.get(request.id);
  if (!context) return;
  state.slimming.removal.previewContexts.delete(request.id);
  if (!hiddenAssetIDs.has(context.assetID)) return;
  const remainingIDs = state.slimming.selectedClusterID === context.clusterID
    ? state.slimming.members.map((member) => member.id)
    : [];
  const replacementID = replacementPreviewAssetID(
    context.memberIDs,
    remainingIDs,
    context.assetID
  );
  state.slimming.selectedMemberIDs = replacementID ? new Set([replacementID]) : new Set();
  state.slimming.selectionAnchorID = replacementID;
  if (state.lightboxContext !== "slimming"
    || state.lightboxAssetID !== context.assetID
    || elements.lightbox.classList.contains("hidden")) return;
  if (!replacementID) {
    closeLightbox();
    return;
  }
  state.lightboxAssetID = replacementID;
  state.lightboxOriginalAssetID = null;
  state.lightboxOriginalLoading = false;
  const card = elements.slimmingMemberGrid.querySelector(
    `[data-slimming-member-id="${CSS.escape(replacementID)}"]`
  );
  state.lightboxReturnFocus = slimmingMemberMainButton(card) || state.lightboxReturnFocus;
  renderSlimmingMemberSelection();
  renderLightbox();
}

async function submitSlimmingRemoval(
  mode,
  { assetIDs: requestedAssetIDs = null, previewAssetID = null, confirmed = false } = {}
) {
  const memberIDs = new Set(state.slimming.members.map((member) => member.id));
  const assetIDs = (requestedAssetIDs || [...state.slimming.selectedMemberIDs])
    .filter((id) => memberIDs.has(id) && !activeSlimmingRemovalPhase(id));
  const protection = removalFavoriteProtectionPlan(assetIDs);
  if (!assetIDs.length || !state.slimming.selectedJobID || !state.slimming.selectedClusterID) {
    toast("请先在一个候选分组中选择项目");
    return;
  }
  if (protection.unverifiableAssetIDs.length) {
    toast("无法核验红心保护，未删除或回收任何项目");
    return;
  }
  if (!protection.removalAssetIDs.length) {
    toast("所选项目均有红心保护；请先取消红心再删除或回收");
    return;
  }
  const noun = state.slimming.mediaKind === "video" ? "段视频" : "张照片";
  const targetCopy = previewAssetID ? "当前预览" : "选中的";
  if (!confirmed) {
    const releasesSpace = mode === "releaseSourceSpace";
    requestConfirmation({
      eyebrow: releasesSpace ? "QUICK DELETE" : "RECOVERABLE RECYCLE",
      title: releasesSpace
        ? `立即处理${targetCopy} ${protection.removalAssetIDs.length} ${noun}？`
        : `移入可恢复回收站？`,
      message: releasesSpace
        ? `${protection.favoriteProtectedAssetIDs.length ? `将保留 ${protection.favoriteProtectedAssetIDs.length} 项红心，只处理其余 ${protection.removalAssetIDs.length} 项。` : ""}文件夹来源会在身份核验后永久删除，无法从 ImageAll 恢复；Apple Photos 项只会进入系统“最近删除”。提交后还需要在 Mac 原生窗口再次确认。`
        : `${protection.favoriteProtectedAssetIDs.length ? `将保留 ${protection.favoriteProtectedAssetIDs.length} 项红心，只处理其余 ${protection.removalAssetIDs.length} 项。` : ""}将${targetCopy} ${protection.removalAssetIDs.length} ${noun}移入回收站。文件夹来源会先复制并校验并保留 30 天；Apple Photos 项会进入系统“最近删除”。提交后还需要在 Mac 原生窗口再次确认。`,
      actionLabel: releasesSpace ? "快速删除" : "可恢复回收",
      tone: releasesSpace ? "danger" : "warning",
      returnFocus: previewAssetID
        ? { lightboxAssetID: previewAssetID, slimmingMemberID: previewAssetID }
        : { element: document.activeElement },
      action: () => submitSlimmingRemoval(mode, {
        assetIDs,
        previewAssetID,
        confirmed: true,
      }),
    });
    return;
  }
  state.slimming.removal.submitting = true;
  const submitsCurrentPreview = Boolean(
    previewAssetID
      && state.lightboxContext === "slimming"
      && state.lightboxAssetID === previewAssetID
      && !elements.lightbox.classList.contains("hidden")
  );
  if (submitsCurrentPreview) elements.lightboxDeleteButton.disabled = true;
  renderSlimmingMemberSelection();
  try {
    const request = await api("/v1/library-slimming/removals", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        operationID: crypto.randomUUID(),
        jobID: state.slimming.selectedJobID,
        clusterID: state.slimming.selectedClusterID,
        mediaKind: state.slimming.mediaKind,
        assetIDs,
        mode,
      }),
    });
    state.slimming.removal.requests = [
      request,
      ...state.slimming.removal.requests.filter((item) => item.id !== request.id),
    ];
    if (previewAssetID) {
      state.slimming.removal.previewContexts.set(request.id, {
        assetID: previewAssetID,
        clusterID: state.slimming.selectedClusterID,
        memberIDs: state.slimming.members.map((member) => member.id),
      });
    }
    toast("已冻结本次选区，请回到 Mac 核对并确认");
  } catch (error) {
    toast(error.message || "批量操作提交失败");
  } finally {
    state.slimming.removal.submitting = false;
    renderSlimmingWorkspace();
    if (submitsCurrentPreview) renderLightbox();
    scheduleSlimmingRemovalPoll();
  }
}

function identicalCleanupPlanCount(plan, key) {
  if (!plan || !Object.prototype.hasOwnProperty.call(plan, key)) return null;
  const value = Number(plan[key]);
  if (!Number.isFinite(value) || value < 0) return null;
  return Math.trunc(value);
}

function syncIdenticalCleanupText(element, text) {
  if (element.textContent !== text) element.textContent = text;
}

function syncIdenticalCleanupMetrics(metrics) {
  const container = elements.slimmingIdenticalCleanupMetrics;
  const existing = new Map(
    [...container.querySelectorAll(":scope > [data-identical-cleanup-metric-key]")]
      .map((card) => [card.dataset.identicalCleanupMetricKey, card])
  );
  const wanted = metrics.map((metric) => {
    const card = existing.get(metric.key) || document.createElement("div");
    card.dataset.identicalCleanupMetricKey = metric.key;
    card.className = `identical-cleanup-metric ${metric.tone || ""}`;
    let title = card.querySelector(":scope > .identical-cleanup-metric-label");
    if (!title) {
      title = document.createElement("span");
      title.className = "identical-cleanup-metric-label";
    }
    let icon = title.querySelector(":scope > [data-identical-cleanup-metric-part='icon']");
    if (!icon) {
      icon = document.createElement("span");
      icon.dataset.identicalCleanupMetricPart = "icon";
      icon.className = "identical-cleanup-metric-symbol";
      icon.setAttribute("aria-hidden", "true");
    }
    let label = title.querySelector(":scope > [data-identical-cleanup-metric-part='label']");
    if (!label) {
      label = document.createElement("span");
      label.dataset.identicalCleanupMetricPart = "label";
    }
    let count = card.querySelector(":scope > [data-identical-cleanup-metric-part='count']");
    if (!count) {
      count = document.createElement("strong");
      count.dataset.identicalCleanupMetricPart = "count";
    }
    syncIdenticalCleanupText(icon, metric.symbol || "");
    syncIdenticalCleanupText(label, metric.label);
    syncIdenticalCleanupText(
      count,
      metric.value === null ? "—" : metric.value.toLocaleString()
    );
    reconcileStableChildren(title, metric.symbol ? [icon, label] : [label]);
    reconcileStableChildren(card, [title, count]);
    return card;
  });
  reconcileStableChildren(container, wanted);
}

function identicalCleanupPart(container, key, tagName, className) {
  let part = container.querySelector(`:scope > [data-identical-cleanup-part="${key}"]`);
  if (!part) {
    part = document.createElement(tagName);
    part.dataset.identicalCleanupPart = key;
  }
  if (className !== undefined) part.className = className;
  return part;
}

function renderIdenticalCleanupDispositionChart(plan) {
  const container = elements.slimmingIdenticalCleanupDispositionChart;
  const retained = identicalCleanupPlanCount(plan, "retainedAssetCount") || 0;
  const removal = identicalCleanupPlanCount(plan, "removalAssetCount") || 0;
  const verified = identicalCleanupPlanCount(plan, "verifiedAssetCount") || 0;
  const dispositionTotal = retained + removal;
  const retainedAngle = dispositionTotal > 0 ? (retained / dispositionTotal) * 360 : 360;

  const chart = identicalCleanupPart(
    container, "donut", "div", "identical-cleanup-donut"
  );
  chart.style.setProperty("--retained-angle", `${retainedAngle}deg`);
  const center = identicalCleanupPart(
    chart, "center", "span", "identical-cleanup-donut-center"
  );
  const total = identicalCleanupPart(center, "total", "strong", "");
  const caption = identicalCleanupPart(center, "caption", "span", "");
  syncIdenticalCleanupText(total, verified.toLocaleString());
  syncIdenticalCleanupText(caption, "张已核验");
  reconcileStableChildren(center, [total, caption]);
  reconcileStableChildren(chart, [center]);

  const legend = identicalCleanupPart(
    container, "legend", "div", "identical-cleanup-chart-legend"
  );
  const legendItems = [
    ["保留", retained, "retained"],
    ["清理", removal, "removal"],
  ].map(([label, value, tone]) => {
    let item = legend.querySelector(
      `:scope > [data-identical-cleanup-legend-key="${tone}"]`
    );
    if (!item) {
      item = document.createElement("span");
      item.dataset.identicalCleanupLegendKey = tone;
    }
    item.className = tone;
    let dot = item.querySelector(":scope > [data-identical-cleanup-legend-part='dot']");
    if (!dot) {
      dot = document.createElement("i");
      dot.dataset.identicalCleanupLegendPart = "dot";
    }
    dot.setAttribute("aria-hidden", "true");
    let text = item.querySelector(":scope > [data-identical-cleanup-legend-part='text']");
    if (!text) {
      text = document.createElement("span");
      text.dataset.identicalCleanupLegendPart = "text";
    }
    syncIdenticalCleanupText(text, `${label} ${value.toLocaleString()}`);
    reconcileStableChildren(item, [dot, text]);
    return item;
  });
  reconcileStableChildren(legend, legendItems);
  reconcileStableChildren(container, [chart, legend]);
  container.setAttribute(
    "aria-label",
    `去留比例：已核验 ${verified.toLocaleString()} 张，保留 ${retained.toLocaleString()} 张，清理 ${removal.toLocaleString()} 张`
  );
}

function renderIdenticalCleanupGroupHistogram(plan) {
  const container = elements.slimmingIdenticalCleanupGroupHistogram;
  const buckets = new Map([["2", 0], ["3", 0], ["4", 0], ["5+", 0]]);
  for (const [rawMemberCount, rawGroupCount] of Object.entries(plan.groupSizeHistogram || {})) {
    const memberCount = Number(rawMemberCount);
    const groupCount = Number(rawGroupCount);
    if (!Number.isFinite(memberCount) || !Number.isFinite(groupCount) || groupCount <= 0) continue;
    const label = memberCount >= 5 ? "5+" : String(Math.trunc(memberCount));
    if (buckets.has(label)) buckets.set(label, buckets.get(label) + Math.trunc(groupCount));
  }
  const visibleBuckets = [...buckets.entries()].filter(([, count]) => count > 0);
  const maxCount = Math.max(1, ...visibleBuckets.map(([, count]) => count));
  const wanted = [];
  if (!visibleBuckets.length) {
    const empty = identicalCleanupPart(
      container, "histogram-empty", "p", "identical-cleanup-chart-empty"
    );
    syncIdenticalCleanupText(empty, "当前 Host 未提供分组规模分布。");
    wanted.push(empty);
  } else {
    for (const [label, count] of visibleBuckets) {
      let column = container.querySelector(
        `:scope > [data-identical-cleanup-histogram-key="${label}"]`
      );
      if (!column) {
        column = document.createElement("div");
        column.dataset.identicalCleanupHistogramKey = label;
      }
      column.className = "identical-cleanup-histogram-column";
      const value = identicalCleanupPart(column, "value", "strong", "");
      const track = identicalCleanupPart(
        column, "track", "span", "identical-cleanup-histogram-track"
      );
      const bar = identicalCleanupPart(
        track, "bar", "span", "identical-cleanup-histogram-bar"
      );
      bar.style.setProperty("--bar-ratio", String(count / maxCount));
      const bucket = identicalCleanupPart(
        column, "label", "span", "identical-cleanup-histogram-label"
      );
      syncIdenticalCleanupText(value, count.toLocaleString());
      syncIdenticalCleanupText(bucket, label);
      reconcileStableChildren(track, [bar]);
      reconcileStableChildren(column, [value, track, bucket]);
      wanted.push(column);
    }
  }
  reconcileStableChildren(container, wanted);
  const summary = visibleBuckets.map(([label, count]) => `每组 ${label} 项有 ${count} 组`).join("，");
  container.setAttribute("aria-label", `重复组规模分布${summary ? `：${summary}` : "不可用"}`);
}

function renderIdenticalCleanupSourceChart(plan) {
  const container = elements.slimmingIdenticalCleanupSources;
  const sources = [
    ["Apple Photos", identicalCleanupPlanCount(plan, "photosAssetCount") || 0, "photos"],
    ["文件夹来源", identicalCleanupPlanCount(plan, "fileAssetCount") || 0, "files"],
  ];
  const maxCount = Math.max(1, ...sources.map(([, count]) => count));
  const wanted = sources.map(([label, count, tone]) => {
    let row = container.querySelector(
      `:scope > [data-identical-cleanup-source-key="${tone}"]`
    );
    if (!row) {
      row = document.createElement("div");
      row.dataset.identicalCleanupSourceKey = tone;
    }
    row.className = `identical-cleanup-source-row ${tone}`;
    const term = identicalCleanupPart(row, "term", "dt", "");
    const description = identicalCleanupPart(row, "description", "dd", "");
    const track = identicalCleanupPart(
      description, "track", "span", "identical-cleanup-source-track"
    );
    const bar = identicalCleanupPart(
      track, "bar", "span", "identical-cleanup-source-bar"
    );
    bar.style.setProperty("--source-ratio", String(count / maxCount));
    const value = identicalCleanupPart(description, "value", "strong", "");
    syncIdenticalCleanupText(term, label);
    syncIdenticalCleanupText(value, `${count.toLocaleString()} 张`);
    reconcileStableChildren(track, [bar]);
    reconcileStableChildren(description, [track, value]);
    reconcileStableChildren(row, [term, description]);
    return row;
  });
  reconcileStableChildren(container, wanted);
  container.setAttribute(
    "aria-label",
    `待清理媒体来源：Apple Photos ${sources[0][1].toLocaleString()} 张，文件夹来源 ${sources[1][1].toLocaleString()} 张`
  );
}

function syncIdenticalCleanupNotices(notices) {
  const container = elements.slimmingIdenticalCleanupNotice;
  const existing = new Map(
    [...container.querySelectorAll(":scope > [data-identical-cleanup-notice-key]")]
      .map((notice) => [notice.dataset.identicalCleanupNoticeKey, notice])
  );
  const wanted = notices.map((descriptor) => {
    const notice = existing.get(descriptor.key) || document.createElement("p");
    notice.dataset.identicalCleanupNoticeKey = descriptor.key;
    notice.className = descriptor.tone || "";
    let icon = notice.querySelector(":scope > [data-identical-cleanup-notice-part='icon']");
    if (!icon) {
      icon = document.createElement("span");
      icon.dataset.identicalCleanupNoticePart = "icon";
      icon.setAttribute("aria-hidden", "true");
    }
    let copy = notice.querySelector(":scope > [data-identical-cleanup-notice-part='copy']");
    if (!copy) {
      copy = document.createElement("span");
      copy.dataset.identicalCleanupNoticePart = "copy";
    }
    syncIdenticalCleanupText(icon, descriptor.symbol || "");
    syncIdenticalCleanupText(copy, descriptor.message);
    reconcileStableChildren(notice, descriptor.symbol ? [icon, copy] : [copy]);
    return notice;
  });
  reconcileStableChildren(container, wanted);
}

function renderSlimmingIdenticalCleanupDialog() {
  const cleanup = state.slimming.identicalCleanup;
  elements.slimmingIdenticalCleanupLoading.classList.toggle("hidden", !cleanup.preparing);
  elements.slimmingIdenticalCleanupContent.classList.toggle(
    "hidden",
    cleanup.preparing || !cleanup.plan
  );
  syncIdenticalCleanupText(elements.slimmingIdenticalCleanupError, cleanup.error || "");
  const plan = cleanup.plan;
  if (plan) {
    const favoriteRetained = identicalCleanupPlanCount(plan, "favoriteRetainedAssetCount");
    const ordinaryRetained = identicalCleanupPlanCount(plan, "ordinaryRetainedAssetCount");
    const protectedSkipped = identicalCleanupPlanCount(plan, "protectedSkippedAssetCount");
    syncIdenticalCleanupMetrics([
      {
        key: "verified", label: "已核验媒体",
        value: identicalCleanupPlanCount(plan, "verifiedAssetCount"), tone: "blue", symbol: "✓",
      },
      {
        key: "retained", label: "会保留",
        value: identicalCleanupPlanCount(plan, "retainedAssetCount"), tone: "green", symbol: "▣",
      },
      {
        key: "favorite", label: "红心保留",
        value: favoriteRetained, tone: "red", symbol: "♥",
      },
      {
        key: "removal", label: "将清理",
        value: identicalCleanupPlanCount(plan, "removalAssetCount"), tone: "orange", symbol: "⌫",
      },
      {
        key: "groups", label: "处理分组",
        value: identicalCleanupPlanCount(plan, "groupCount"), tone: "indigo", symbol: "▤",
      },
    ]);
    let retentionSummary;
    if (favoriteRetained !== null && ordinaryRetained !== null && protectedSkipped !== null) {
      retentionSummary =
        `普通保留 ${ordinaryRetained.toLocaleString()} 项；全组红心而安全跳过 ${protectedSkipped.toLocaleString()} 项。红心资产不会进入自动删除计划。`;
    } else {
      retentionSummary =
        "当前 Mac Host 未提供红心保护拆分；执行计划仍由 Mac 按红心保护规则逐项核验。";
    }
    renderIdenticalCleanupDispositionChart(plan);
    renderIdenticalCleanupGroupHistogram(plan);
    renderIdenticalCleanupSourceChart(plan);

    const fileAssetCount = identicalCleanupPlanCount(plan, "fileAssetCount") || 0;
    const photosAssetCount = identicalCleanupPlanCount(plan, "photosAssetCount") || 0;
    const skippedGroupCount = identicalCleanupPlanCount(plan, "skippedGroupCount") || 0;
    const byteIdenticalGroupCount = identicalCleanupPlanCount(
      plan, "byteIdenticalGroupCount"
    );
    const perfectVisualGroupCount = identicalCleanupPlanCount(
      plan, "perfectVisualGroupCount"
    );
    if (byteIdenticalGroupCount !== null && perfectVisualGroupCount !== null) {
      retentionSummary +=
        ` 原文件完全相同 ${byteIdenticalGroupCount.toLocaleString()} 组；视觉匹配 100% ${perfectVisualGroupCount.toLocaleString()} 组。`;
    }
    syncIdenticalCleanupText(elements.slimmingIdenticalCleanupRetentionSummary, retentionSummary);
    const notices = [];
    if ((perfectVisualGroupCount || 0) > 0) {
      notices.push({
        key: "visual-match",
        message: `其中 ${perfectVisualGroupCount.toLocaleString()} 组是视觉特征匹配 100%，原文件字节并不完全相同；请在确认后再清理。`,
        tone: "warning",
        symbol: "△",
      });
    }
    if (fileAssetCount > 0) {
      notices.push({
        key: "permanent-files",
        message: `“快速清理”会永久删除 ${fileAssetCount.toLocaleString()} 个文件夹媒体，ImageAll 无法恢复。`,
        tone: "danger",
        symbol: "!",
      });
    }
    if (photosAssetCount > 0) {
      notices.push({
        key: "photos-confirmation",
        message: "macOS 仍会对全部 Apple Photos 待删项集中显示一次系统确认。",
        tone: "warning",
        symbol: "△",
      });
    }
    if (skippedGroupCount > 0) {
      notices.push({
        key: "skipped-groups",
        message: `另有 ${skippedGroupCount.toLocaleString()} 组因成员或来源状态变化已安全跳过，不会删除。`,
        tone: "warning",
        symbol: "◇",
      });
    }
    if (!notices.length) {
      notices.push({
        key: "safe",
        message: "执行前 Mac 还会再次核验冻结方案，变化的项目不会被删除。",
        tone: "safe",
        symbol: "✓",
      });
    }
    syncIdenticalCleanupNotices(notices);
  } else {
    syncIdenticalCleanupMetrics([]);
    syncIdenticalCleanupText(elements.slimmingIdenticalCleanupRetentionSummary, "");
    reconcileStableChildren(elements.slimmingIdenticalCleanupDispositionChart, []);
    reconcileStableChildren(elements.slimmingIdenticalCleanupGroupHistogram, []);
    reconcileStableChildren(elements.slimmingIdenticalCleanupSources, []);
    syncIdenticalCleanupNotices([]);
  }
  const disabled = cleanup.preparing || cleanup.submitting || !plan;
  elements.recoverableSlimmingIdenticalCleanupButton.disabled = disabled;
  elements.fastSlimmingIdenticalCleanupButton.disabled = disabled;
  syncIdenticalCleanupText(elements.recoverableSlimmingIdenticalCleanupButton, plan
    ? `可恢复回收 ${plan.removalAssetCount} 项`
    : "可恢复回收");
  syncIdenticalCleanupText(elements.fastSlimmingIdenticalCleanupButton, plan
    ? `快速清理 ${plan.removalAssetCount} 项`
    : "快速清理");
}

function slimmingIdenticalCleanupBaseLevelFromHistory(context = {}) {
  return ["sidebar", "inspector", "lightbox"].includes(
    context.slimmingIdenticalCleanupBaseLevel
  )
    ? context.slimmingIdenticalCleanupBaseLevel
    : "workspace";
}

function replaceSlimmingIdenticalCleanupHistoryWithBase(baseLevel) {
  if (!state.workspaceNavigation.initialized
    || elements.appView.classList.contains("hidden")) return;
  const current = activeWorkspaceHistoryEntry();
  const route = visibleWorkspaceRoute();
  if (current?.route !== route
    || current.navigationLevel !== "slimmingIdenticalCleanup") return;
  const context = currentWorkspaceHistoryContext(route);
  if (context && typeof context === "object") {
    delete context.slimmingIdenticalCleanupBaseLevel;
  }
  const navigationLevel = visibleWorkspaceNavigationBaseLevel(route, baseLevel);
  history.replaceState({
    ...(history.state || {}),
    [WORKSPACE_HISTORY_KEY]: workspaceHistoryEntry(route, context, navigationLevel),
  }, "", location.href);
}

function clearSlimmingIdenticalCleanupDialogState({ cancelRequest = true } = {}) {
  const cleanup = state.slimming.identicalCleanup;
  if (cancelRequest) cleanup.planRequestGeneration += 1;
  cleanup.plan = null;
  cleanup.error = "";
  cleanup.preparing = false;
  cleanup.submitting = false;
  cleanup.returnFocus = null;
  cleanup.baseLevel = "workspace";
  cleanup.historyRestoreFocus = true;
  cleanup.focusID = "cancelSlimmingIdenticalCleanupButton";
  cleanup.restorable = false;
  cleanup.opening = false;
}

function presentSlimmingIdenticalCleanupDialog({
  historyMode = "pushSlimmingIdenticalCleanup",
  baseLevel = null,
  focus = true,
} = {}) {
  const cleanup = state.slimming.identicalCleanup;
  if (elements.slimmingIdenticalCleanupDialog.open) {
    renderSlimmingIdenticalCleanupDialog();
    if (focus) restoreOverlayFocus(
      document.getElementById(cleanup.focusID)
        || elements.cancelSlimmingIdenticalCleanupButton
    );
    return;
  }
  const current = activeWorkspaceHistoryEntry();
  cleanup.baseLevel = baseLevel
    || workspaceNavigationBaseLevel(
      current?.navigationLevel || "workspace",
      current?.context || {}
    );
  elements.slimmingIdenticalCleanupDialog.showModal();
  if (historyMode !== "none") {
    const route = visibleWorkspaceRoute();
    recordWorkspaceHistory(route, currentWorkspaceHistoryContext(route), historyMode);
  }
  cleanup.restorable = true;
  renderSlimmingIdenticalCleanupDialog();
  if (focus) restoreOverlayFocus(
    document.getElementById(cleanup.focusID)
      || elements.cancelSlimmingIdenticalCleanupButton
  );
}

async function openSlimmingIdenticalCleanupDialog() {
  const cleanup = state.slimming.identicalCleanup;
  if (!state.slimming.selectedJobID || elements.slimmingIdenticalCleanupDialog.open
    || cleanup.preparing || cleanup.opening) return;
  cleanup.returnFocus = document.activeElement;
  cleanup.plan = null;
  cleanup.error = "";
  cleanup.preparing = true;
  cleanup.submitting = false;
  cleanup.focusID = "cancelSlimmingIdenticalCleanupButton";
  const generation = ++cleanup.planRequestGeneration;
  cleanup.opening = true;
  try {
    presentSlimmingIdenticalCleanupDialog();
  } finally {
    cleanup.opening = false;
  }
  try {
    const plan = await api("/v1/library-slimming/identical-cleanup/plans", {
      method: "POST",
      body: JSON.stringify({
        jobID: state.slimming.selectedJobID,
        mediaKind: state.slimming.mediaKind,
      }),
    });
    if (generation !== cleanup.planRequestGeneration) return;
    cleanup.plan = plan;
  } catch (error) {
    if (generation === cleanup.planRequestGeneration) {
      cleanup.error = error.message || "无法生成一键清理方案";
    }
  } finally {
    if (generation === cleanup.planRequestGeneration) {
      cleanup.preparing = false;
      if (elements.slimmingIdenticalCleanupDialog.open) {
        renderSlimmingIdenticalCleanupDialog();
      }
    }
  }
}

function closeSlimmingIdenticalCleanupDialog({
  restoreFocus = true,
  checkpoint = true,
  preserveState = false,
} = {}) {
  const cleanup = state.slimming.identicalCleanup;
  if (!elements.slimmingIdenticalCleanupDialog.open || cleanup.submitting) return;
  const active = document.activeElement;
  if (active instanceof HTMLElement
    && elements.slimmingIdenticalCleanupDialog.contains(active)
    && active.id) {
    cleanup.focusID = active.id;
  }
  const baseLevel = cleanup.baseLevel;
  const returnFocus = cleanup.returnFocus;
  elements.slimmingIdenticalCleanupDialog.close();
  if (restoreFocus) {
    restoreOverlayFocus(stableReturnFocusTarget(
      returnFocus,
      elements.slimmingIdenticalCleanupButton
    ));
  }
  if (checkpoint) replaceSlimmingIdenticalCleanupHistoryWithBase(baseLevel);
  if (!preserveState) clearSlimmingIdenticalCleanupDialogState();
}

function returnFromSlimmingIdenticalCleanup({ restoreFocus = true } = {}) {
  const cleanup = state.slimming.identicalCleanup;
  if (!elements.slimmingIdenticalCleanupDialog.open || cleanup.submitting) {
    return Promise.resolve();
  }
  cleanup.historyRestoreFocus = restoreFocus;
  if (state.workspaceNavigation.pendingReturnPromise) {
    return state.workspaceNavigation.pendingReturnPromise;
  }
  const current = activeWorkspaceHistoryEntry();
  if (state.workspaceNavigation.initialized
    && current?.route === visibleWorkspaceRoute()
    && current.navigationLevel === "slimmingIdenticalCleanup") {
    const pending = new Promise((resolve) => {
      state.workspaceNavigation.pendingReturnResolve = resolve;
    });
    state.workspaceNavigation.pendingReturnPromise = pending;
    history.back();
    return pending;
  }
  closeSlimmingIdenticalCleanupDialog({ restoreFocus });
  cleanup.historyRestoreFocus = true;
  return Promise.resolve();
}

function reconcileSlimmingIdenticalCleanupFromWorkspaceHistory(
  route,
  navigationLevel,
  context = {}
) {
  const cleanup = state.slimming.identicalCleanup;
  const shouldOpen = navigationLevel === "slimmingIdenticalCleanup"
    && route === visibleWorkspaceRoute();
  const hasRestorableState = cleanup.preparing || cleanup.plan || cleanup.error;
  if (shouldOpen && (!cleanup.restorable || !hasRestorableState)) {
    clearSlimmingIdenticalCleanupDialogState();
    if (history.length > 1 && Object.prototype.hasOwnProperty.call(
      context,
      "slimmingIdenticalCleanupBaseLevel"
    )) {
      history.back();
    } else {
      replaceSlimmingIdenticalCleanupHistoryWithBase(
        slimmingIdenticalCleanupBaseLevelFromHistory(context)
      );
    }
    return;
  }
  if (shouldOpen && !elements.slimmingIdenticalCleanupDialog.open) {
    presentSlimmingIdenticalCleanupDialog({
      historyMode: "none",
      baseLevel: slimmingIdenticalCleanupBaseLevelFromHistory(context),
    });
  } else if (!shouldOpen && elements.slimmingIdenticalCleanupDialog.open) {
    if (cleanup.submitting) {
      history.forward();
      return;
    }
    const restoreFocus = cleanup.historyRestoreFocus;
    closeSlimmingIdenticalCleanupDialog({
      restoreFocus,
      checkpoint: false,
      preserveState: true,
    });
    cleanup.historyRestoreFocus = true;
  }
}

async function submitSlimmingIdenticalCleanup(mode) {
  const cleanup = state.slimming.identicalCleanup;
  if (!cleanup.plan || cleanup.submitting) return;
  cleanup.submitting = true;
  cleanup.error = "";
  renderSlimmingIdenticalCleanupDialog();
  try {
    const request = await api("/v1/library-slimming/identical-cleanup/requests", {
      method: "POST",
      body: JSON.stringify({
        operationID: crypto.randomUUID(),
        planID: cleanup.plan.id,
        mode,
      }),
    });
    cleanup.requests = [
      request,
      ...cleanup.requests.filter((item) => item.id !== request.id),
    ];
    cleanup.submitting = false;
    const returnFocus = cleanup.returnFocus;
    await returnFromSlimmingIdenticalCleanup({ restoreFocus: false });
    clearSlimmingIdenticalCleanupDialogState({ cancelRequest: false });
    restoreOverlayFocus(stableReturnFocusTarget(
      returnFocus,
      elements.slimmingIdenticalCleanupButton
    ));
    toast("方案已冻结，请回到 Mac 核对并确认");
    renderSlimmingWorkspace();
    scheduleSlimmingIdenticalCleanupPoll();
  } catch (error) {
    cleanup.error = error.message || "一键清理提交失败";
  } finally {
    cleanup.submitting = false;
    renderSlimmingIdenticalCleanupDialog();
  }
}

function scheduleSlimmingIdenticalCleanupPoll() {
  const cleanup = state.slimming.identicalCleanup;
  clearTimeout(cleanup.pollTimer);
  cleanup.pollTimer = null;
  const active = cleanup.requests.some(
    (request) => request.phase === "awaitingMac" || request.phase === "running"
  );
  if (!active || elements.appView.classList.contains("hidden")) return;
  cleanup.pollTimer = setTimeout(
    () => loadSlimmingIdenticalCleanupRequests({ quiet: true }),
    900
  );
}

async function loadSlimmingIdenticalCleanupRequests({ quiet = false } = {}) {
  const cleanup = state.slimming.identicalCleanup;
  const generation = ++cleanup.requestGeneration;
  const previouslyActiveIDs = new Set(cleanup.requests
    .filter((request) => request.phase === "awaitingMac" || request.phase === "running")
    .map((request) => request.id));
  try {
    const snapshots = await Promise.all(["image", "video"].map((mediaKind) => {
      const query = new URLSearchParams({ mediaKind });
      return api(`/v1/library-slimming/identical-cleanup/requests?${query}`);
    }));
    if (generation !== cleanup.requestGeneration) return;
    const merged = new Map();
    for (const request of snapshots.flatMap((snapshot) => snapshot.requests || [])) {
      const existing = merged.get(request.id);
      if (!existing || Number(request.updatedAtMs || 0) > Number(existing.updatedAtMs || 0)) {
        merged.set(request.id, request);
      }
    }
    cleanup.requests = [...merged.values()].sort(
      (left, right) => Number(right.updatedAtMs || 0) - Number(left.updatedAtMs || 0)
    );
    renderIdenticalCleanupBlockingOverlay();
    const terminal = cleanup.requests.find((request) =>
      previouslyActiveIDs.has(request.id)
        && ["completed", "cancelled", "failed"].includes(request.phase));
    if (terminal && terminal.id !== cleanup.lastTerminalRequestID) {
      cleanup.lastTerminalRequestID = terminal.id;
      toast(terminal.message || "一键清理已结束");
      if (hasSlimmingVerificationReport(terminal)
        && terminal.id !== cleanup.lastPresentedVerificationID) {
        cleanup.lastPresentedVerificationID = terminal.id;
        openSlimmingVerificationReport(terminal);
      }
      if (terminal.phase === "completed") {
        await loadSlimmingWorkspace({ quiet: true });
        await loadSlimmingRemovals({ quiet: true });
      }
    }
  } catch (error) {
    if (generation === cleanup.requestGeneration && !quiet) {
      toast(error.message || "一键清理状态载入失败");
    }
  } finally {
    if (generation === cleanup.requestGeneration) {
      renderSlimmingWorkspace();
      renderIdenticalCleanupBlockingOverlay();
      scheduleSlimmingIdenticalCleanupPoll();
    }
  }
}

function slimmingItemsEqual(left, right) {
  return left.length === right.length
    && left.every((item, index) => JSON.stringify(item) === JSON.stringify(right[index]));
}

function slimmingItemsFormStablePrefix(previous, next) {
  if (next.length <= previous.length) return false;
  const ids = next.map((item) => item?.id);
  if (ids.some((id) => !id) || new Set(ids).size !== ids.length) return false;
  return previous.every(
    (item, index) => JSON.stringify(item) === JSON.stringify(next[index])
  );
}

function renderedSlimmingCollectionMatches(container, selector, items, datasetKey) {
  const rendered = [...container.querySelectorAll(`:scope > ${selector}`)];
  return rendered.length === items.length
    && rendered.every((element, index) => element.dataset[datasetKey] === items[index]?.id);
}

function renderedSlimmingJobsMatch(items) {
  return renderedSlimmingCollectionMatches(
    elements.slimmingJobList,
    "[data-slimming-job-id]",
    items,
    "slimmingJobId"
  );
}

function renderedSlimmingClustersMatch(items) {
  return renderedSlimmingCollectionMatches(
    elements.slimmingClusterList,
    ".slimming-cluster-row[data-slimming-cluster-row-id]",
    items,
    "slimmingClusterRowId"
  );
}

function renderedSlimmingMembersMatch(items) {
  return renderedSlimmingCollectionMatches(
    elements.slimmingMemberGrid,
    ".slimming-member-card[data-slimming-member-id]",
    items,
    "slimmingMemberId"
  );
}

function slimmingWorkspaceCollectionFingerprint() {
  return JSON.stringify({
    mediaKind: state.slimming.mediaKind,
    jobs: state.slimming.jobs,
    totalJobCount: state.slimming.totalJobCount,
    selectedJobID: state.slimming.selectedJobID,
    jobMutatingIDs: [...state.slimming.jobMutatingIDs].sort(),
    clusters: state.slimming.clusters,
    selectedClusterID: state.slimming.selectedClusterID,
    clusterScope: state.slimming.clusterScope,
    clusterScopeCounts: state.slimming.clusterScopeCounts,
    clusterScopeSupported: state.slimming.clusterScopeSupported,
    clusterReviewPendingIDs: [...state.slimming.clusterReviewPendingIDs].sort(),
    members: state.slimming.members,
    removalRequests: state.slimming.removal.requests,
    online: state.online,
  });
}

function slimmingWorkspaceCanPreserveCollections() {
  return state.slimming.renderedCollectionFingerprint !== null
    && state.slimming.renderedCollectionFingerprint
      === slimmingWorkspaceCollectionFingerprint()
    && renderedSlimmingJobsMatch(state.slimming.jobs)
    && renderedSlimmingClustersMatch(state.slimming.clusters)
    && renderedSlimmingMembersMatch(state.slimming.members);
}

function captureSlimmingRenderContinuity() {
  const active = document.activeElement;
  return {
    navigatorScrollTop: elements.slimmingNavigatorPane.scrollTop,
    memberScrollTop: slimmingMemberScrollContainer().scrollTop,
    focusedJobID: active?.closest?.("[data-slimming-job-id]")?.dataset.slimmingJobId || null,
    focusedClusterID: active?.closest?.("[data-slimming-cluster-id]")
      ?.dataset.slimmingClusterId || null,
    focusedMemberID: active?.closest?.("[data-slimming-member-id]")
      ?.dataset.slimmingMemberId || null,
    focusedControlID: active?.id || null,
    previousLastClusterID: state.slimming.clusters.at(-1)?.id || null,
    previousLastMemberID: state.slimming.members.at(-1)?.id || null,
  };
}

function restoreSlimmingRenderContinuity(continuity) {
  if (!continuity) return;
  elements.slimmingNavigatorPane.scrollTop = continuity.navigatorScrollTop;
  slimmingMemberScrollContainer().scrollTop = continuity.memberScrollTop;
  let target = continuity.focusedMemberID
    ? elements.slimmingMemberGrid.querySelector(
      `[data-slimming-member-id="${CSS.escape(continuity.focusedMemberID)}"] .slimming-member-main`
    )
    : null;
  if (!target && continuity.focusedClusterID) {
    target = elements.slimmingClusterList.querySelector(
      `[data-slimming-cluster-id="${CSS.escape(continuity.focusedClusterID)}"]`
    );
  }
  if (!target && continuity.focusedJobID) {
    target = elements.slimmingJobList.querySelector(
      `[data-slimming-job-id="${CSS.escape(continuity.focusedJobID)}"]`
    );
  }
  if (!target && continuity.focusedControlID) {
    const control = document.getElementById(continuity.focusedControlID);
    if (control && !control.classList.contains("hidden") && !control.disabled) target = control;
  }
  if (!target && continuity.focusedControlID === "slimmingLoadMoreClustersButton") {
    target = elements.slimmingClusterList.querySelector(
      `[data-slimming-cluster-id="${CSS.escape(continuity.previousLastClusterID || "")}"]`
    );
  }
  if (!target && continuity.focusedControlID === "slimmingLoadMoreMembersButton") {
    target = elements.slimmingMemberGrid.querySelector(
      `[data-slimming-member-id="${CSS.escape(continuity.previousLastMemberID || "")}"] .slimming-member-main`
    );
  }
  target?.focus({ preventScroll: true });
}

function slimmingAppendSnapshotIsStable(previous, snapshot, appendKind) {
  const nextJobs = snapshot.jobs || [];
  const nextClusters = snapshot.clusters || [];
  const nextMembers = snapshot.members || [];
  const nextScopeCounts = snapshot.clusterScopeCounts || null;
  const previousScopeCounts = previous.clusterScopeSupported
    ? previous.clusterScopeCounts
    : null;
  const jobsStable = appendKind === "jobs"
    ? slimmingItemsFormStablePrefix(previous.jobs, nextJobs)
    : slimmingItemsEqual(previous.jobs, nextJobs);
  const commonStable = snapshot.selectedJobID === previous.selectedJobID
    && snapshot.selectedClusterID === previous.selectedClusterID
    && Number(snapshot.totalJobCount ?? nextJobs.length) === previous.totalJobCount
    && Number(snapshot.pendingAnalysisCount || 0) === previous.pendingAnalysisCount
    && Number(snapshot.analyzedAssetCount || 0) === previous.analyzedAssetCount
    && (snapshot.policyVersion || null) === previous.policyVersion
    && JSON.stringify(nextScopeCounts) === JSON.stringify(previousScopeCounts)
    && jobsStable
    && previous.renderedJobsMatch
    && previous.renderedClustersMatch
    && previous.renderedMembersMatch;
  if (!commonStable) return false;
  if (appendKind === "jobs") {
    return slimmingItemsEqual(previous.clusters, nextClusters)
      && slimmingItemsEqual(previous.members, nextMembers);
  }
  if (appendKind === "clusters") {
    return slimmingItemsFormStablePrefix(previous.clusters, nextClusters)
      && slimmingItemsEqual(previous.members, nextMembers);
  }
  if (appendKind === "members") {
    return slimmingItemsEqual(previous.clusters, nextClusters)
      && slimmingItemsFormStablePrefix(previous.members, nextMembers);
  }
  return false;
}

async function loadSlimmingWorkspace({
  jobID = null,
  clusterID = null,
  quiet = false,
  appendKind = null,
} = {}) {
  const appending = ["jobs", "clusters", "members"].includes(appendKind)
    ? appendKind
    : null;
  if (jobID || clusterID) state.slimming.selectionMode = false;
  const generation = ++state.slimming.requestGeneration;
  const previousSelectedMemberIDs = new Set(state.slimming.selectedMemberIDs);
  const previousSelectionAnchorID = state.slimming.selectionAnchorID;
  const previous = {
    jobs: state.slimming.jobs,
    totalJobCount: state.slimming.totalJobCount,
    selectedJobID: state.slimming.selectedJobID,
    clusters: state.slimming.clusters,
    selectedClusterID: state.slimming.selectedClusterID,
    clusterScopeSupported: state.slimming.clusterScopeSupported === true,
    clusterScopeCounts: state.slimming.clusterScopeSupported === true
      ? { ...state.slimming.clusterScopeCounts }
      : null,
    members: state.slimming.members,
    pendingAnalysisCount: Number(state.slimming.pendingAnalysisCount || 0),
    analyzedAssetCount: Number(state.slimming.analyzedAssetCount || 0),
    policyVersion: state.slimming.policyVersion || null,
    renderedJobsMatch: renderedSlimmingJobsMatch(state.slimming.jobs),
    renderedClustersMatch: renderedSlimmingClustersMatch(state.slimming.clusters),
    renderedMembersMatch: renderedSlimmingMembersMatch(state.slimming.members),
    continuity: appending ? captureSlimmingRenderContinuity() : null,
  };
  let renderOptions = appending || slimmingWorkspaceCanPreserveCollections()
    ? { preserveJobs: true, preserveClusters: true, preserveMembers: true }
    : {};
  state.slimming.loading = true;
  state.slimming.appending = appending;
  renderSlimmingWorkspace(renderOptions);
  const query = new URLSearchParams({ mediaKind: state.slimming.mediaKind });
  query.set("clusterScope", state.slimming.clusterScope);
  query.set("jobLimit", String(state.slimming.jobLimit));
  query.set("clusterLimit", String(state.slimming.clusterLimit));
  query.set("memberLimit", String(state.slimming.memberLimit));
  if (jobID || state.slimming.selectedJobID) query.set("jobID", jobID || state.slimming.selectedJobID);
  if (clusterID || state.slimming.selectedClusterID) {
    query.set("clusterID", clusterID || state.slimming.selectedClusterID);
  }
  try {
    const snapshot = await api(`/v1/library-slimming/workspace?${query}`);
    if (generation !== state.slimming.requestGeneration) return false;
    const nextJobs = snapshot.jobs || [];
    const nextClusters = snapshot.clusters || [];
    const nextMembers = snapshot.members || [];
    const appendIsStable = appending
      ? slimmingAppendSnapshotIsStable(previous, snapshot, appending)
      : false;
    state.slimming.jobs = nextJobs;
    state.slimming.totalJobCount = Number(snapshot.totalJobCount ?? state.slimming.jobs.length);
    // Deep links may cause the Host to grow the prefix through the requested job.
    // Preserve that authoritative window on later refreshes.
    state.slimming.jobLimit = Math.max(state.slimming.jobLimit, state.slimming.jobs.length);
    state.slimming.selectedJobID = snapshot.selectedJobID || null;
    state.slimming.clusters = nextClusters;
    state.slimming.selectedClusterID = snapshot.selectedClusterID || null;
    state.slimming.members = nextMembers;
    if (snapshot.clusterScopeCounts) {
      state.slimming.clusterScopeSupported = true;
      state.slimming.clusterScopeCounts = {
        pending: Number(snapshot.clusterScopeCounts.pending || 0),
        confirmed: Number(snapshot.clusterScopeCounts.confirmed || 0),
        ignored: Number(snapshot.clusterScopeCounts.ignored || 0),
      };
    } else {
      state.slimming.clusterScopeSupported = false;
      state.slimming.clusterScope = "pending";
      const selectedJob = state.slimming.jobs.find(
        (candidate) => candidate.id === state.slimming.selectedJobID
      );
      state.slimming.clusterScopeCounts = {
        pending: Number(selectedJob?.clusterCount || state.slimming.clusters.length),
        confirmed: 0,
        ignored: 0,
      };
    }
    state.slimming.pendingAnalysisCount = snapshot.pendingAnalysisCount || 0;
    state.slimming.analyzedAssetCount = snapshot.analyzedAssetCount || 0;
    state.slimming.policyVersion = snapshot.policyVersion || null;
    const memberIDs = new Set(state.slimming.members.map((member) => member.id));
    const liveSelectedMemberIDs = appending
      ? new Set(state.slimming.selectedMemberIDs)
      : previousSelectedMemberIDs;
    const liveSelectionAnchorID = appending
      ? state.slimming.selectionAnchorID
      : previousSelectionAnchorID;
    state.slimming.selectedMemberIDs = (jobID || clusterID)
      ? new Set()
      : new Set([...liveSelectedMemberIDs].filter((id) => memberIDs.has(id)));
    state.slimming.selectionAnchorID = state.slimming.selectedMemberIDs.has(
      liveSelectionAnchorID
    ) ? liveSelectionAnchorID : null;
    if (appendIsStable && appending === "jobs") {
      renderOptions = {
        appendJobs: nextJobs.slice(previous.jobs.length),
        preserveClusters: true,
        preserveMembers: true,
      };
    } else if (appendIsStable && appending === "clusters") {
      renderOptions = {
        preserveJobs: true,
        appendClusters: nextClusters.slice(previous.clusters.length),
        preserveMembers: true,
      };
    } else if (appendIsStable && appending === "members") {
      renderOptions = {
        preserveJobs: true,
        preserveClusters: true,
        appendMembers: nextMembers.slice(previous.members.length),
      };
    } else if (!appending && slimmingWorkspaceCanPreserveCollections()) {
      renderOptions = { preserveJobs: true, preserveClusters: true, preserveMembers: true };
    } else {
      renderOptions = {};
    }
    return true;
  } catch (error) {
    if (generation === state.slimming.requestGeneration && !quiet) {
      toast(error.message || "图库瘦身结果载入失败");
    }
    return false;
  } finally {
    if (generation === state.slimming.requestGeneration) {
      state.slimming.loading = false;
      state.slimming.appending = null;
      renderSlimmingWorkspace(renderOptions);
      if (appending) restoreSlimmingRenderContinuity(previous.continuity);
    }
  }
}

async function selectSlimmingClusterScope(scope, { focus = true } = {}) {
  if (!["pending", "confirmed", "ignored"].includes(scope)
    || state.slimming.loading
    || (state.slimming.clusterScopeSupported === false && scope !== "pending")) return;
  if (scope === state.slimming.clusterScope) {
    if (focus) {
      elements.slimmingClusterScopes.querySelector(
        `[data-slimming-cluster-scope="${CSS.escape(scope)}"]`
      )?.focus({ preventScroll: true });
    }
    return;
  }
  state.slimming.clusterScope = scope;
  state.slimming.selectedClusterID = null;
  state.slimming.selectedMemberIDs.clear();
  state.slimming.selectionAnchorID = null;
  state.slimming.clusterLimit = 48;
  state.slimming.memberLimit = 96;
  await loadSlimmingWorkspace({ quiet: true });
  checkpointActiveWorkspaceHistory();
  if (focus) {
    elements.slimmingClusterScopes.querySelector(
      `[data-slimming-cluster-scope="${CSS.escape(state.slimming.clusterScope)}"]`
    )?.focus({ preventScroll: true });
  }
}

async function setSlimmingClusterReviewDisposition(clusterID, disposition) {
  if (!state.online
    || state.slimming.clusterScopeSupported !== true
    || !state.slimming.selectedJobID
    || !clusterID
    || state.slimming.clusterReviewPendingIDs.has(clusterID)) return;
  const cluster = state.slimming.clusters.find((candidate) => candidate.id === clusterID);
  if (!cluster) return;
  const focusedReview = document.activeElement?.closest?.(
    `[data-slimming-cluster-review-id="${CSS.escape(clusterID)}"]`
  );
  const focusedDisposition = focusedReview?.dataset.slimmingClusterReview || null;
  let succeeded = false;
  state.slimming.clusterReviewPendingIDs.add(clusterID);
  renderSlimmingClusters();
  renderSlimmingSelectedClusterReview(cluster);
  try {
    await api("/v1/library-slimming/cluster-review", {
      method: "POST",
      body: JSON.stringify({
        operationID: crypto.randomUUID(),
        jobID: state.slimming.selectedJobID,
        clusterID,
        disposition,
      }),
    });
    succeeded = true;
    const removesResolvedHistoricalRecord = disposition == null
      && cluster.isHistoricalProcessedRecord
      && Number(cluster.memberCount || 0) < 2;
    toast(disposition === "confirmed"
      ? "已收进确认队列，可随时打开重新处理"
      : disposition === "ignored"
        ? "已收进忽略队列，可随时打开重新处理"
        : removesResolvedHistoricalRecord
          ? "历史记录已移出审阅队列；当前不足两项，无需返回待处理"
          : "已移回待处理队列");
    state.slimming.selectedClusterID = null;
    state.slimming.selectedMemberIDs.clear();
    state.slimming.selectionAnchorID = null;
    await loadSlimmingWorkspace({ quiet: true });
    focusSelectedSlimmingCluster();
  } catch (error) {
    toast(error.message || "分组状态保存失败");
  } finally {
    state.slimming.clusterReviewPendingIDs.delete(clusterID);
    renderSlimmingWorkspace();
    if (!succeeded && focusedDisposition) {
      requestAnimationFrame(() => {
        elements.slimmingClusterList.querySelector(
          `[data-slimming-cluster-review-id="${CSS.escape(clusterID)}"]`
          + `[data-slimming-cluster-review="${CSS.escape(focusedDisposition)}"]`
          + ":not(:disabled)"
        )?.focus({ preventScroll: true });
      });
    }
  }
}

async function openSlimmingWorkspace({
  historyMode = "push",
  returnTarget = null,
  awaitCatalogSources = false,
} = {}) {
  leaveIntegratedGalleryOverviewForLibrary({ historyMode: "none" });
  leaveIntegratedWorldMapForLibrary({ historyMode: "none" });
  elements.reviewWorkspace.classList.add("hidden");
  syncReviewPresentation({ renderSurfaces: false });
  state.reviewReturnFocus = null;
  elements.trainingWorkspace.classList.add("hidden");
  syncTrainingPresentation({ renderSurfaces: false });
  state.trainingReturnFocus = null;
  closeJobsPopover({ restoreFocus: false });
  closeFilterPopover({ restoreFocus: false });
  if (elements.slimmingWorkspace.classList.contains("hidden")) {
    state.slimmingReturnFocus = document.activeElement;
    state.slimmingReturnTarget = returnTarget;
  }
  if (matchMedia("(max-width: 720px)").matches
    && !state.slimming.inspectorCompactInitialized) {
    elements.slimmingInspector.open = false;
    state.slimming.inspectorCompactInitialized = true;
  }
  elements.slimmingWorkspace.classList.remove("hidden");
  recordWorkspaceHistory(
    "slimming",
    currentWorkspaceHistoryContext("slimming"),
    historyMode
  );
  syncSlimmingPresentation({ focus: true });
  if (state.slimming.view === "recycle") await loadSlimmingRecycle();
  else {
    const catalogSourcesPromise = loadSlimmingCatalogSources();
    if (awaitCatalogSources) await catalogSourcesPromise;
    else void catalogSourcesPromise;
    await loadSlimmingWorkspace();
    await loadSlimmingRemovals({ quiet: true });
    await loadSlimmingIdenticalCleanupRequests({ quiet: true });
  }
}

async function switchSlimmingMediaKind(mediaKind) {
  if (!["image", "video"].includes(mediaKind)
    || mediaKind === state.slimming.mediaKind) return;
  finishSlimmingMarqueeSelection();
  cancelPendingSlimmingRecycleSearch();
  state.slimming.selectionMode = false;
  state.slimming.mediaKind = mediaKind;
  state.slimming.jobLimit = SLIMMING_JOB_PAGE_SIZE;
  state.slimming.totalJobCount = 0;
  state.slimming.selectedJobID = null;
  state.slimming.selectedClusterID = null;
  state.slimming.selectedMemberIDs.clear();
  state.slimming.selectionAnchorID = null;
  state.slimming.clusterLimit = 48;
  state.slimming.memberLimit = 96;
  state.slimming.recycle.limit = 60;
  state.slimming.catalogSources.requestGeneration += 1;
  state.slimming.catalogSources.snapshot = null;
  state.slimming.catalogSources.loading = false;
  state.slimming.catalogSources.error = "";
  state.slimming.removal.requests = [];
  state.slimming.removal.lastTerminalRequestID = null;
  clearTimeout(state.slimming.removal.pollTimer);
  if (state.slimming.view === "recycle") await loadSlimmingRecycle();
  else {
    void loadSlimmingCatalogSources();
    await Promise.all([
      loadSlimmingWorkspace(),
      loadSlimmingRemovals({ quiet: true }),
      loadSlimmingIdenticalCleanupRequests({ quiet: true }),
    ]);
  }
}

function selectSlimmingMember(
  memberID,
  event = {},
  { focusGrid = false, forceReplace = false } = {}
) {
  const ids = state.slimming.members.map((member) => member.id);
  const additive = !forceReplace
    && (state.slimming.selectionMode || event.metaKey || event.ctrlKey);
  if (event.shiftKey && state.slimming.selectionAnchorID) {
    const anchor = ids.indexOf(state.slimming.selectionAnchorID);
    const target = ids.indexOf(memberID);
    if (anchor >= 0 && target >= 0) {
      const range = ids.slice(Math.min(anchor, target), Math.max(anchor, target) + 1);
      state.slimming.selectedMemberIDs = additive
        ? new Set([...state.slimming.selectedMemberIDs, ...range])
        : new Set(range);
    }
  } else if (additive) {
    if (state.slimming.selectedMemberIDs.has(memberID)) {
      state.slimming.selectedMemberIDs.delete(memberID);
    } else {
      state.slimming.selectedMemberIDs.add(memberID);
    }
    state.slimming.selectionAnchorID = memberID;
  } else {
    state.slimming.selectedMemberIDs = new Set([memberID]);
    state.slimming.selectionAnchorID = memberID;
  }
  renderSlimmingMemberSelection();
  if (focusGrid) {
    const card = elements.slimmingMemberGrid.querySelector(
      `[data-slimming-member-id="${CSS.escape(memberID)}"]`
    );
    card?.scrollIntoView({ block: "nearest", inline: "nearest" });
    slimmingMemberMainButton(card)?.focus({ preventScroll: true });
  }
}

function moveSlimmingMemberSelection(key, { extendRange = false } = {}) {
  if (state.slimming.view !== "analysis" || !state.slimming.members.length) return;
  const ids = state.slimming.members.map((member) => member.id);
  const primaryID = state.slimming.selectionAnchorID
    && state.slimming.selectedMemberIDs.has(state.slimming.selectionAnchorID)
    ? state.slimming.selectionAnchorID
    : [...state.slimming.selectedMemberIDs].find((id) => ids.includes(id));
  const currentIndex = Math.max(0, ids.indexOf(primaryID));
  let nextIndex;
  if (key === "Home") {
    nextIndex = 0;
  } else if (key === "End") {
    nextIndex = ids.length - 1;
  } else {
    const scrollContainer = slimmingMemberScrollContainer();
    const columns = renderedGridColumnCount(
      elements.slimmingMemberGrid,
      ":scope > .slimming-member-card"
    );
    const delta = {
      ArrowLeft: -1,
      ArrowRight: 1,
      ArrowUp: -columns,
      ArrowDown: columns,
      PageUp: -renderedGridPageItemCount(
        scrollContainer,
        elements.slimmingMemberGrid,
        ":scope > .slimming-member-card"
      ),
      PageDown: renderedGridPageItemCount(
        scrollContainer,
        elements.slimmingMemberGrid,
        ":scope > .slimming-member-card"
      ),
    }[key];
    if (!delta) return;
    nextIndex = currentIndex + delta;
  }
  const bounded = Math.max(0, Math.min(ids.length - 1, nextIndex));
  selectSlimmingMember(
    ids[bounded],
    { shiftKey: extendRange },
    { focusGrid: true, forceReplace: true }
  );
}

function currentSlimmingSeedIDs() {
  if (state.mediaKind !== state.slimming.mediaKind) return [];
  if (state.selectedAssetIDs.size) return [...state.selectedAssetIDs];
  return state.selectedAssetID ? [state.selectedAssetID] : [];
}

function currentSlimmingFilterRequest() {
  const accepted = [];
  const rejected = [];
  const excluded = [];
  for (const condition of state.filters.tagConditions) {
    if (condition.decision === "accepted") {
      accepted.push({ tagID: condition.tagID, decision: "accepted" });
    } else if (condition.decision === "rejected") {
      rejected.push({ tagID: condition.tagID, decision: "rejected" });
    } else if (condition.decision === "excluded") {
      excluded.push(condition.tagID);
    }
  }
  return {
    sourceIDs: state.selectedSourceID ? [state.selectedSourceID] : [],
    searchText: state.searchText || null,
    sort: state.sort,
    limit: 200,
    cursor: null,
    tagDecisionFilters: [...accepted, ...rejected],
    excludedTagIDs: excluded,
    tagMatchMode: state.filters.tagMatchMode,
    availabilities: [...state.filters.availabilities],
    mediaKinds: [state.slimming.mediaKind],
    mediaTypes: [...state.filters.mediaTypes],
    tagPresence: state.filters.tagPresence,
  };
}

function slimmingModeCopy(mode) {
  const noun = state.slimming.mediaKind === "video" ? "视频" : "照片";
  return {
    catalog: {
      title: "全部来源",
      detail: `扫描所选来源中的全部可用${noun}`,
    },
    currentFilter: {
      title: "当前筛选",
      detail: `冻结网页图库当前的来源、搜索和标签筛选`,
    },
    seeds: {
      title: "按种子查找",
      detail: `从图库当前选择的${noun}出发查找相似项`,
    },
  }[mode];
}

function slimmingModeAvailable(mode) {
  const setup = state.slimming.setup;
  if (mode === "catalog") return Boolean(setup.snapshot?.sources?.length);
  if (state.mediaKind !== state.slimming.mediaKind) return false;
  if (mode === "seeds") return currentSlimmingSeedIDs().length > 0;
  return true;
}

function normalizeSlimmingThresholdDraft(value) {
  if (!value) return null;
  return {
    featurePrintRecallTopK: Number(value.featurePrintRecallTopK),
    featurePrintMaxL2Distance: Number(value.featurePrintMaxL2Distance),
    dinoCosineMinSimilarity: Number(value.dinoCosineMinSimilarity),
    sceneBucketActivationAssetCount: Number(value.sceneBucketActivationAssetCount),
    featurePrintRecallMode: value.featurePrintRecallMode,
    featurePrintL2Mode: value.featurePrintL2Mode,
    dinoCosineMode: value.dinoCosineMode,
    sceneBucketingMode: value.sceneBucketingMode,
  };
}

function syncSlimmingThresholdInteractionSurface(surface) {
  if (!surface) return;
  for (const range of surface.querySelectorAll("[data-threshold-number-target]")) {
    const numberInput = document.getElementById(range.dataset.thresholdNumberTarget);
    if (!numberInput) continue;
    range.value = numberInput.value;
    range.disabled = numberInput.disabled;
    range.setAttribute("aria-valuetext", numberInput.value);
  }
  for (const toggle of surface.querySelectorAll("[data-threshold-mode-target]")) {
    const select = document.getElementById(toggle.dataset.thresholdModeTarget);
    if (!select) continue;
    toggle.checked = select.value === toggle.dataset.checkedValue;
    toggle.disabled = select.disabled;
  }
  for (const button of surface.querySelectorAll(
    "[data-threshold-select-target][data-threshold-select-value]"
  )) {
    const select = document.getElementById(button.dataset.thresholdSelectTarget);
    if (!select) continue;
    const selected = select.value === button.dataset.thresholdSelectValue;
    button.setAttribute("aria-checked", String(selected));
    button.tabIndex = selected ? 0 : -1;
    button.disabled = select.disabled;
  }
  for (const editor of surface.querySelectorAll("[data-threshold-automatic-for]")) {
    const select = document.getElementById(editor.dataset.thresholdAutomaticFor);
    editor.hidden = select?.value !== "automatic";
  }
}

function bindSlimmingThresholdInteractionSurface(surface) {
  if (!surface) return;
  surface.addEventListener("input", (event) => {
    const range = event.target.closest("[data-threshold-number-target]");
    if (!range) return;
    const numberInput = document.getElementById(range.dataset.thresholdNumberTarget);
    if (numberInput) numberInput.value = range.value;
  });
  surface.addEventListener("change", (event) => {
    const range = event.target.closest("[data-threshold-number-target]");
    if (range) {
      const numberInput = document.getElementById(range.dataset.thresholdNumberTarget);
      if (numberInput) {
        numberInput.value = range.value;
        numberInput.dispatchEvent(new Event("change", { bubbles: true }));
      }
      return;
    }
    const toggle = event.target.closest("[data-threshold-mode-target]");
    if (!toggle) return;
    const select = document.getElementById(toggle.dataset.thresholdModeTarget);
    if (!select) return;
    select.value = toggle.checked
      ? toggle.dataset.checkedValue
      : toggle.dataset.uncheckedValue;
    select.dispatchEvent(new Event("change", { bubbles: true }));
  });
  surface.addEventListener("click", (event) => {
    const button = event.target.closest(
      "[data-threshold-select-target][data-threshold-select-value]"
    );
    if (!button || button.disabled) return;
    const select = document.getElementById(button.dataset.thresholdSelectTarget);
    if (!select || select.value === button.dataset.thresholdSelectValue) return;
    select.value = button.dataset.thresholdSelectValue;
    select.dispatchEvent(new Event("change", { bubbles: true }));
  });
  surface.addEventListener("keydown", (event) => {
    const button = event.target.closest(
      "[data-threshold-select-target][data-threshold-select-value]"
    );
    if (!button || !["ArrowLeft", "ArrowRight", "ArrowUp", "ArrowDown", "Home", "End"].includes(event.key)) {
      return;
    }
    const buttons = [...surface.querySelectorAll(
      `[data-threshold-select-target="${CSS.escape(button.dataset.thresholdSelectTarget)}"]`
    )].filter((candidate) => !candidate.disabled);
    if (!buttons.length) return;
    event.preventDefault();
    const current = Math.max(0, buttons.indexOf(button));
    const backwards = event.key === "ArrowLeft" || event.key === "ArrowUp";
    const next = event.key === "Home" ? 0
      : event.key === "End" ? buttons.length - 1
        : (current + (backwards ? -1 : 1) + buttons.length) % buttons.length;
    buttons[next].focus({ preventScroll: true });
    buttons[next].click();
  });
}

function slimmingThresholdsValid(value = state.slimming.setup.thresholds) {
  return Boolean(value)
    && ["topK", "allCandidates"].includes(value.featurePrintRecallMode)
    && ["radius", "unlimited"].includes(value.featurePrintL2Mode)
    && ["minimum", "unlimited"].includes(value.dinoCosineMode)
    && ["automatic", "always", "never"].includes(value.sceneBucketingMode)
    && Number.isInteger(value.featurePrintRecallTopK)
    && value.featurePrintRecallTopK > 0
    && value.featurePrintRecallTopK <= 128
    && Number.isFinite(value.featurePrintMaxL2Distance)
    && value.featurePrintMaxL2Distance >= 0
    && value.featurePrintMaxL2Distance <= 200
    && Number.isFinite(value.dinoCosineMinSimilarity)
    && value.dinoCosineMinSimilarity >= 0
    && value.dinoCosineMinSimilarity <= 1
    && Number.isInteger(value.sceneBucketActivationAssetCount)
    && value.sceneBucketActivationAssetCount >= 2
    && value.sceneBucketActivationAssetCount <= 10_000;
}

function resolvedSlimmingCatalogSourceIDs(snapshot) {
  const allSourceIDs = (snapshot?.sources || []).map((source) => source.id);
  if (state.slimming.catalogSourceIDs === null) return new Set(allSourceIDs);
  const available = new Set(allSourceIDs);
  return new Set(
    [...state.slimming.catalogSourceIDs].filter((sourceID) => available.has(sourceID))
  );
}

function setSlimmingCatalogSourceIDs(selectedSourceIDs, snapshot) {
  const allSourceIDs = (snapshot?.sources || []).map((source) => source.id);
  const available = new Set(allSourceIDs);
  const selected = new Set(
    [...selectedSourceIDs].filter((sourceID) => available.has(sourceID))
  );
  state.slimming.catalogSourceIDs = allSourceIDs.length === selected.size
    && allSourceIDs.every((sourceID) => selected.has(sourceID))
    ? null
    : selected;
  state.slimming.setup.selectedSourceIDs = new Set(selected);
  state.slimming.sourceMaintenance.selectedSourceIDs = new Set(selected);
}

function currentSlimmingCatalogSnapshot() {
  const mediaKind = state.slimming.mediaKind;
  for (const snapshot of [
    state.slimming.catalogSources.snapshot,
    state.slimming.sourceMaintenance.snapshot,
    state.slimming.setup.snapshot,
  ]) {
    if (snapshot?.mediaKind === mediaKind) return snapshot;
  }
  return null;
}

function selectedSlimmingCatalogSources(snapshot = currentSlimmingCatalogSnapshot()) {
  const selected = resolvedSlimmingCatalogSourceIDs(snapshot);
  return (snapshot?.sources || []).filter((source) => selected.has(source.id));
}

function slimmingCatalogSourceSelectionTitle(snapshot = currentSlimmingCatalogSnapshot()) {
  const sources = snapshot?.sources || [];
  const selected = selectedSlimmingCatalogSources(snapshot);
  if (!snapshot) return state.slimming.catalogSources.loading ? "读取来源…" : "选择来源";
  if (!selected.length) return "未选择来源";
  if (selected.length === sources.length) return `全部来源（${sources.length}）`;
  if (selected.length === 1) return selected[0].displayName;
  return `已选 ${selected.length} 个来源`;
}

function renderSlimmingCatalogCommands() {
  const analysisView = state.slimming.view === "analysis";
  const snapshot = currentSlimmingCatalogSnapshot();
  const sources = snapshot?.sources || [];
  const selected = selectedSlimmingCatalogSources(snapshot);
  const allSelected = sources.length > 0 && selected.length === sources.length;
  const launching = Boolean(state.slimming.quickLaunchMode);
  const catalogLaunching = state.slimming.quickLaunchMode === "catalog";
  const currentFilterAvailable = state.mediaKind === state.slimming.mediaKind;
  const seedCount = currentSlimmingSeedIDs().length;

  for (const control of [
    elements.slimmingCatalogAnalyzeButton,
    elements.slimmingCatalogSourceButton,
    elements.slimmingAnalysisOptionsButton,
  ]) control.classList.toggle("hidden", !analysisView);

  elements.slimmingCatalogAnalyzeButton.textContent = catalogLaunching
    ? (allSelected ? "正在分析全部来源…" : "正在分析所选来源…")
    : (allSelected ? "分析全部来源" : "分析所选来源");
  elements.slimmingCatalogAnalyzeButton.title = selected.length
    ? `分析范围：${allSelected ? `全部 ${sources.length} 个来源` : selected.map((source) => source.displayName).join("、")}；不会取消已有分析记录`
    : "请先选择至少一个可用来源";
  configurePersistentHelp(elements.slimmingCatalogAnalyzeButton, {
    title: allSelected ? "分析全部来源" : "分析所选来源",
    detail: elements.slimmingCatalogAnalyzeButton.title,
    kind: "slimming",
  });
  elements.slimmingCatalogAnalyzeButton.setAttribute("aria-busy", String(catalogLaunching));
  elements.slimmingCatalogAnalyzeButton.disabled = !state.online
    || launching
    || state.slimming.catalogSources.loading
    || selected.length === 0;

  elements.slimmingCatalogSourceButton.lastElementChild.textContent =
    slimmingCatalogSourceSelectionTitle(snapshot);
  elements.slimmingCatalogSourceButton.disabled = launching
    || (state.slimming.catalogSources.loading && !snapshot);
  elements.slimmingCatalogSourceButton.setAttribute(
    "aria-busy",
    String(state.slimming.catalogSources.loading)
  );
  configurePersistentHelp(elements.slimmingCatalogSourceButton, {
    title: "分析来源",
    detail: "选择一个或多个要分析的来源；只列出这台 Mac 当前提供的可用来源。",
    kind: "slimming",
  });

  elements.slimmingCurrentFilterAnalysisButton.textContent =
    state.slimming.quickLaunchMode === "currentFilter"
      ? "正在分析当前筛选…"
      : "分析当前筛选";
  elements.slimmingCurrentFilterAnalysisButton.disabled = !state.online
    || launching
    || !currentFilterAvailable;
  configurePersistentHelp(elements.slimmingCurrentFilterAnalysisButton, {
    title: "分析当前筛选",
    detail: "冻结网页图库当前的来源、搜索、标签、格式与可用状态范围后交给 Mac；不会改变图库筛选。",
    kind: "slimming",
  });
  elements.slimmingSeedAnalysisButton.classList.toggle("hidden", seedCount === 0);
  elements.slimmingSeedAnalysisButton.textContent =
    state.slimming.quickLaunchMode === "seeds"
      ? `正在按种子查找（${seedCount}）…`
      : `按种子查找（${seedCount}）`;
  elements.slimmingSeedAnalysisButton.disabled = !state.online
    || launching
    || seedCount === 0
    || !currentFilterAvailable;
  configurePersistentHelp(elements.slimmingSeedAnalysisButton, {
    title: `按种子查找（${seedCount}）`,
    detail: "使用图库中当前选择的项目查找相似内容；不会修改种子媒体或取消已有分析。",
    kind: "slimming",
  });
  elements.openSlimmingSetupButton.disabled = launching;
  configurePersistentHelp(elements.openSlimmingSetupButton, {
    title: "更多分析设置",
    detail: "在同一个设置页选择分析范围、来源和共享相似阈值；提交前不会创建任务。",
    kind: "slimming",
  });
}

function createSlimmingCatalogSourceOption() {
  const row = document.createElement("label");
  row.className = "slimming-catalog-source-option";
  row.setAttribute("role", "menuitemcheckbox");
  const input = document.createElement("input");
  input.type = "checkbox";
  const icon = document.createElement("span");
  icon.className = "slimming-catalog-source-icon";
  const copy = document.createElement("span");
  copy.append(document.createElement("strong"), document.createElement("small"));
  row.append(input, icon, copy);
  return row;
}

function syncSlimmingCatalogSourceOption(row, source, selected, disabled) {
  row.setAttribute("aria-checked", String(selected));
  const input = row.querySelector(':scope > input[type="checkbox"]');
  input.id = `slimmingCatalogSource-${source.id}`;
  input.checked = selected;
  input.disabled = disabled;
  input.dataset.slimmingCatalogSourceId = source.id;
  input.setAttribute("aria-keyshortcuts", choiceGridNavigationShortcuts);
  const icon = row.querySelector(":scope > .slimming-catalog-source-icon");
  const iconText = source.kind === "photos" ? "▣" : "▱";
  if (icon.textContent !== iconText) icon.textContent = iconText;
  const copy = row.querySelector(":scope > span:last-child");
  const name = copy.querySelector(":scope > strong");
  if (name.textContent !== source.displayName) name.textContent = source.displayName;
  const kind = copy.querySelector(":scope > small");
  const kindText = source.kind === "photos" ? "照片图库" : "文件夹";
  if (kind.textContent !== kindText) kind.textContent = kindText;
  configurePersistentHelp(row, {
    title: `分析来源 · ${source.displayName}`,
    detail: "方向键、Page Up/Down 与 Home/End 移动焦点，空格切换；勾选后才纳入下一次全部来源分析。",
    kind: "slimming",
    keyShortcuts: choiceGridNavigationShortcuts,
  });
}

function renderSlimmingCatalogSourcePicker() {
  const picker = state.slimming.catalogSources;
  const snapshot = currentSlimmingCatalogSnapshot();
  const sources = snapshot?.sources || [];
  const selectedIDs = resolvedSlimmingCatalogSourceIDs(snapshot);
  const allSelected = sources.length > 0
    && sources.every((source) => selectedIDs.has(source.id));

  elements.slimmingCatalogSourceSummary.textContent = picker.loading && !snapshot
    ? "正在读取当前可用来源…"
    : allSelected
      ? `已选择全部 ${sources.length} 个可用来源。`
      : `已选择 ${selectedIDs.size} / ${sources.length} 个来源。`;
  elements.slimmingCatalogSourceError.textContent = picker.error;
  elements.selectAllSlimmingCatalogSourcesButton.disabled = picker.loading
    || Boolean(state.slimming.quickLaunchMode)
    || sources.length === 0
    || allSelected;
  elements.clearSlimmingCatalogSourcesButton.disabled = picker.loading
    || Boolean(state.slimming.quickLaunchMode)
    || selectedIDs.size === 0;

  const existingOptions = new Map(
    [...elements.slimmingCatalogSourceOptions.querySelectorAll(
      ":scope > .slimming-catalog-source-option"
    )].map((row) => [
      row.querySelector("[data-slimming-catalog-source-id]")?.dataset.slimmingCatalogSourceId,
      row,
    ])
  );
  const sourceOptions = sources.map((source) => {
    const row = existingOptions.get(source.id) || createSlimmingCatalogSourceOption();
    syncSlimmingCatalogSourceOption(
      row,
      source,
      selectedIDs.has(source.id),
      picker.loading || Boolean(state.slimming.quickLaunchMode)
    );
    return row;
  });
  reconcileStableChildren(elements.slimmingCatalogSourceOptions, sourceOptions);
  renderSlimmingCatalogCommands();
}

async function loadSlimmingCatalogSources({ force = false } = {}) {
  const picker = state.slimming.catalogSources;
  const mediaKind = state.slimming.mediaKind;
  if (!force && picker.snapshot?.mediaKind === mediaKind) {
    renderSlimmingCatalogSourcePicker();
    return picker.snapshot;
  }
  const generation = ++picker.requestGeneration;
  picker.loading = true;
  picker.error = "";
  renderSlimmingCatalogSourcePicker();
  try {
    const query = new URLSearchParams({ mediaKind });
    const snapshot = await api(`/v1/library-slimming/setup?${query}`);
    if (generation !== picker.requestGeneration || state.slimming.mediaKind !== mediaKind) {
      return null;
    }
    picker.snapshot = snapshot;
    setSlimmingCatalogSourceIDs(resolvedSlimmingCatalogSourceIDs(snapshot), snapshot);
    return snapshot;
  } catch (error) {
    if (generation === picker.requestGeneration) {
      picker.error = error.message || "分析来源载入失败";
    }
    return null;
  } finally {
    if (generation === picker.requestGeneration) {
      picker.loading = false;
      renderSlimmingCatalogSourcePicker();
      renderSlimmingInspector();
    }
  }
}

function closeSlimmingCatalogSourcePicker(options = {}) {
  if (activeActionMenuDescriptor()?.kind !== "slimmingSources") return;
  closeActionMenu(options);
}

function positionSlimmingCatalogSourcePicker() {
  const anchor = elements.slimmingCatalogSourceButton.getBoundingClientRect();
  const popover = elements.slimmingCatalogSourcePopover;
  const width = popover.offsetWidth || Math.min(310, innerWidth - 24);
  const left = Math.max(8, Math.min(anchor.left, innerWidth - width - 8));
  popover.style.top = `${Math.min(anchor.bottom + 6, innerHeight - 80)}px`;
  popover.style.left = `${left}px`;
  popover.style.right = "auto";
}

function openSlimmingCatalogSourcePicker(options = {}) {
  openActionMenu("slimmingSources", options);
}

function toggleSlimmingCatalogSourcePicker() {
  toggleActionMenu("slimmingSources");
}

async function launchSlimmingAnalysis(mode, returnFocus = null) {
  if (!state.online || state.slimming.quickLaunchMode) return;
  if (!["catalog", "currentFilter", "seeds"].includes(mode)) return;
  if (mode !== "catalog" && state.mediaKind !== state.slimming.mediaKind) {
    toast("请先让图库与瘦身工作台使用相同媒体类型");
    return;
  }

  state.slimming.quickLaunchMode = mode;
  renderSlimmingCatalogSourcePicker();
  let snapshot = currentSlimmingCatalogSnapshot();
  if (mode === "catalog" && !snapshot) snapshot = await loadSlimmingCatalogSources();
  const sources = snapshot?.sources || [];
  const selectedSources = selectedSlimmingCatalogSources(snapshot);
  const seedAssetIDs = mode === "seeds" ? currentSlimmingSeedIDs() : [];
  if ((mode === "catalog" && selectedSources.length === 0)
    || (mode === "seeds" && seedAssetIDs.length === 0)) {
    state.slimming.quickLaunchMode = null;
    renderSlimmingCatalogSourcePicker();
    toast(mode === "catalog" ? "请至少选择一个分析来源" : "请先在图库选择种子项目");
    return;
  }

  await returnFromActionMenu({ restoreFocus: false });
  const allSourcesSelected = mode === "catalog"
    && selectedSources.length === sources.length;
  try {
    const result = await api("/v1/library-slimming/launch", {
      method: "POST",
      body: JSON.stringify({
        operationID: crypto.randomUUID(),
        mediaKind: state.slimming.mediaKind,
        mode,
        sourceIDs: mode === "catalog"
          ? (allSourcesSelected ? null : selectedSources.map((source) => source.id))
          : null,
        seedAssetIDs,
        filter: mode === "catalog" ? null : currentSlimmingFilterRequest(),
      }),
    });
    state.slimming.selectedJobID = result.jobID;
    toast(mode === "catalog"
      ? `已交给 Mac 分析 ${selectedSources.length} 个来源 · ${result.memberCount} 项`
      : mode === "currentFilter"
        ? `已交给 Mac 分析当前筛选 · ${result.memberCount} 项`
        : `正在从所选 ${seedAssetIDs.length} 项查找相似内容`);
    await loadSlimmingWorkspace({ jobID: result.jobID, quiet: true });
  } catch (error) {
    toast(error.message || "图库瘦身分析创建失败");
  } finally {
    state.slimming.quickLaunchMode = null;
    renderSlimmingCatalogSourcePicker();
    const focusTarget = returnFocus?.isConnected ? returnFocus : null;
    if (focusTarget && !elements.slimmingWorkspace.classList.contains("hidden")) {
      restoreOverlayFocus(focusTarget);
    }
  }
}

function slimmingSourceIndexShortStatus(source) {
  switch (source?.similarityIndex?.state) {
    case "building": return "索引构建中";
    case "ready": return "索引就绪";
    case "stale": return "索引待重建";
    case "failed": return "索引失败";
    default: return "索引未初始化";
  }
}

function slimmingSourceIndexCaption(source, available) {
  if (!available) return "当前 Mac Host 不支持来源相似索引。";
  if (!source) return "来源索引：请选择单个来源";
  const status = source.similarityIndex;
  if (!status) return "来源索引：未初始化";
  switch (status.state) {
    case "building":
      return `来源索引：构建中 ${status.indexedCount}/${status.assetCount}`;
    case "ready":
      return `来源索引：就绪 ${status.indexedCount}/${status.assetCount} · ${status.clusterCount} 簇`;
    case "stale":
      return "来源索引：需要重建";
    case "failed":
      return "来源索引：失败，请重试";
    default:
      return "来源索引：状态不可用";
  }
}

function createSlimmingMaintenanceSourceOption() {
  const row = document.createElement("label");
  row.className = "slimming-maintenance-source-option";
  const input = document.createElement("input");
  input.type = "checkbox";
  row.append(input, document.createElement("strong"), document.createElement("span"));
  return row;
}

function syncSlimmingMaintenanceSourceOption(row, source, selected, disabled) {
  const input = row.querySelector(':scope > input[type="checkbox"]');
  input.id = `slimmingMaintenanceSource-${source.id}`;
  input.checked = selected;
  input.disabled = disabled;
  input.dataset.slimmingMaintenanceSourceId = source.id;
  input.setAttribute("aria-keyshortcuts", choiceGridNavigationShortcuts);
  const name = row.querySelector(":scope > strong");
  if (name.textContent !== source.displayName) name.textContent = source.displayName;
  const kind = row.querySelector(":scope > span");
  const kindText = `${source.kind === "photos" ? "照片图库" : "文件夹"} · ${slimmingSourceIndexShortStatus(source)}`;
  if (kind.textContent !== kindText) kind.textContent = kindText;
  configurePersistentHelp(row, {
    title: `来源维护 · ${source.displayName}`,
    detail: "方向键、Page Up/Down 与 Home/End 移动焦点，空格切换；只有明确执行操作后才刷新来源。",
    kind: "slimming",
    keyShortcuts: choiceGridNavigationShortcuts,
  });
}

function syncSlimmingIndexSourceOptions(sources) {
  const existingOptions = new Map(
    [...elements.slimmingIndexSourceSelect.options].map((option) => [option.value, option])
  );
  const sourceOptions = sources.map((source) => {
    const option = existingOptions.get(source.id) || document.createElement("option");
    option.value = source.id;
    if (option.textContent !== source.displayName) option.textContent = source.displayName;
    return option;
  });
  reconcileStableChildren(elements.slimmingIndexSourceSelect, sourceOptions);
}

function renderSlimmingSourceMaintenance() {
  const maintenance = state.slimming.sourceMaintenance;
  const snapshot = maintenance.snapshot;
  const sources = snapshot?.sources || [];
  const submitting = Boolean(maintenance.submittingAction);
  elements.slimmingAnalysisOptionsLoading.classList.toggle("hidden", !maintenance.loading);
  elements.slimmingAnalysisOptionsContent.classList.toggle(
    "hidden",
    maintenance.loading || !snapshot
  );
  elements.slimmingAnalysisOptionsError.textContent = maintenance.error;
  renderSlimmingCatalogCommands();
  if (!snapshot) {
    reconcileStableChildren(elements.slimmingMaintenanceSourceOptions, []);
    return;
  }

  const selected = maintenance.selectedSourceIDs;
  const allSelected = sources.length > 0
    && sources.every((source) => selected.has(source.id));
  elements.slimmingMaintenanceSourceSummary.textContent = allSelected
    ? `已选择全部 ${sources.length} 个可用来源。`
    : `已选择 ${selected.size} / ${sources.length} 个来源。`;
  elements.toggleAllSlimmingMaintenanceSourcesButton.textContent = allSelected ? "清除" : "全选";
  elements.toggleAllSlimmingMaintenanceSourcesButton.disabled = submitting || sources.length === 0;

  const existingOptions = new Map(
    [...elements.slimmingMaintenanceSourceOptions.querySelectorAll(
      ":scope > .slimming-maintenance-source-option"
    )].map((row) => [
      row.querySelector("[data-slimming-maintenance-source-id]")
        ?.dataset.slimmingMaintenanceSourceId,
      row,
    ])
  );
  const sourceOptions = sources.map((source) => {
    const row = existingOptions.get(source.id) || createSlimmingMaintenanceSourceOption();
    syncSlimmingMaintenanceSourceOption(
      row,
      source,
      selected.has(source.id),
      submitting
    );
    return row;
  });
  reconcileStableChildren(elements.slimmingMaintenanceSourceOptions, sourceOptions);

  elements.refreshSlimmingSourcesButton.disabled = !state.online
    || submitting
    || selected.size === 0;
  elements.refreshSlimmingSourcesButton.lastElementChild.textContent =
    maintenance.submittingAction === "refreshCatalog"
      ? "正在交给 Mac…" : "刷新所选来源";

  const indexAvailable = snapshot.sourceSimilarityIndexAvailable === true;
  elements.slimmingSourceIndexSection.classList.toggle("hidden", !indexAvailable);
  syncSlimmingIndexSourceOptions(sources);
  if (!sources.some((source) => source.id === maintenance.indexSourceID)) {
    maintenance.indexSourceID = sources.find((source) => selected.has(source.id))?.id
      || sources[0]?.id
      || "";
  }
  elements.slimmingIndexSourceSelect.value = maintenance.indexSourceID;
  elements.slimmingIndexSourceSelect.disabled = submitting || sources.length === 0;
  const indexSource = sources.find((source) => source.id === maintenance.indexSourceID);
  const status = indexSource?.similarityIndex;
  elements.slimmingSourceIndexStatus.textContent = slimmingSourceIndexCaption(
    indexSource,
    indexAvailable
  );
  elements.slimmingSourceIndexStatus.classList.toggle("ready", status?.state === "ready");
  elements.slimmingSourceIndexStatus.classList.toggle(
    "warning",
    status?.state === "stale" || status?.state === "failed"
  );
  elements.initializeSlimmingSourceIndexButton.textContent =
    maintenance.submittingAction === "initializeSimilarityIndex"
      ? "正在交给 Mac…"
      : status?.state === "ready"
        ? "重新构建来源索引"
        : status?.state === "stale" || status?.state === "failed"
          ? "重新构建来源索引"
          : status?.state === "building"
            ? "正在构建来源索引…"
            : "初始化来源索引";
  elements.initializeSlimmingSourceIndexButton.disabled = !state.online
    || submitting
    || !indexSource
    || status?.state === "building";
  if (!elements.slimmingCatalogSourcePopover.classList.contains("hidden")) {
    renderSlimmingCatalogSourcePicker();
  }
  renderSlimmingInspector();
  syncWriteActionControls();
}

function stopSlimmingSourceIndexPolling() {
  clearTimeout(state.slimming.sourceMaintenance.pollTimer);
  state.slimming.sourceMaintenance.pollTimer = null;
}

function scheduleSlimmingSourceIndexPolling() {
  stopSlimmingSourceIndexPolling();
  const maintenance = state.slimming.sourceMaintenance;
  const source = maintenance.snapshot?.sources?.find(
    (item) => item.id === maintenance.indexSourceID
  );
  if (source?.similarityIndex?.state !== "building"
    || elements.slimmingAnalysisOptionsPopover.classList.contains("hidden")) return;
  maintenance.pollTimer = setTimeout(() => {
    void loadSlimmingSourceMaintenance({ quiet: true });
  }, 1500);
}

async function loadSlimmingSourceMaintenance({ quiet = false } = {}) {
  const maintenance = state.slimming.sourceMaintenance;
  const generation = ++maintenance.requestGeneration;
  if (!quiet) maintenance.loading = true;
  maintenance.error = "";
  renderSlimmingSourceMaintenance();
  try {
    const query = new URLSearchParams({ mediaKind: state.slimming.mediaKind });
    const snapshot = await api(`/v1/library-slimming/setup?${query}`);
    if (generation !== maintenance.requestGeneration
      || elements.slimmingAnalysisOptionsPopover.classList.contains("hidden")) return;
    maintenance.snapshot = snapshot;
    state.slimming.catalogSources.snapshot = snapshot;
    setSlimmingCatalogSourceIDs(
      resolvedSlimmingCatalogSourceIDs(snapshot),
      snapshot
    );
  } catch (error) {
    if (generation === maintenance.requestGeneration) {
      maintenance.error = error.message || "来源维护状态载入失败";
    }
  } finally {
    if (generation === maintenance.requestGeneration) {
      maintenance.loading = false;
      renderSlimmingSourceMaintenance();
      scheduleSlimmingSourceIndexPolling();
    }
  }
}

function closeSlimmingAnalysisOptions(options = {}) {
  if (activeActionMenuDescriptor()?.kind !== "slimmingOptions") return;
  closeActionMenu(options);
}

function openSlimmingAnalysisOptions(options = {}) {
  openActionMenu("slimmingOptions", options);
}

function toggleSlimmingAnalysisOptions() {
  toggleActionMenu("slimmingOptions");
}

async function submitSlimmingSourceMaintenance(action) {
  const maintenance = state.slimming.sourceMaintenance;
  if (!state.online || maintenance.submittingAction || !maintenance.snapshot) return;
  const sourceIDs = action === "refreshCatalog"
    ? [...maintenance.selectedSourceIDs]
    : [maintenance.indexSourceID].filter(Boolean);
  if (sourceIDs.length === 0 || (action === "initializeSimilarityIndex" && sourceIDs.length !== 1)) {
    maintenance.error = action === "refreshCatalog"
      ? "请至少选择一个要刷新的来源。"
      : "请选择一个要建立索引的来源。";
    renderSlimmingSourceMaintenance();
    return;
  }
  maintenance.submittingAction = action;
  maintenance.error = "";
  maintenance.operationID ||= crypto.randomUUID();
  renderSlimmingSourceMaintenance();
  try {
    const result = await api("/v1/library-slimming/source-maintenance", {
      method: "POST",
      body: JSON.stringify({
        operationID: maintenance.operationID,
        action,
        mediaKind: state.slimming.mediaKind,
        sourceIDs,
      }),
    });
    maintenance.snapshot = result.setup;
    state.slimming.catalogSources.snapshot = result.setup;
    maintenance.operationID = null;
    setSlimmingCatalogSourceIDs(
      action === "refreshCatalog"
        ? new Set(sourceIDs)
        : resolvedSlimmingCatalogSourceIDs(result.setup),
      result.setup
    );
    toast(action === "refreshCatalog"
      ? `已交给 Mac 刷新 ${sourceIDs.length} 个来源`
      : "来源索引已开始构建");
  } catch (error) {
    maintenance.error = error.message || (action === "refreshCatalog"
      ? "刷新来源失败"
      : "初始化来源索引失败");
  } finally {
    maintenance.submittingAction = null;
    renderSlimmingSourceMaintenance();
    scheduleSlimmingSourceIndexPolling();
  }
}

function syncSlimmingThresholdEditorControls() {
  const editor = state.slimming.thresholdEditor;
  const thresholds = editor.thresholds;
  if (!thresholds) return;
  elements.slimmingThresholdRecallMode.value = thresholds.featurePrintRecallMode;
  elements.slimmingThresholdRecallTopK.value = String(thresholds.featurePrintRecallTopK);
  elements.slimmingThresholdL2Mode.value = thresholds.featurePrintL2Mode;
  elements.slimmingThresholdL2Distance.value = String(
    thresholds.featurePrintMaxL2Distance
  );
  elements.slimmingThresholdDINOMode.value = thresholds.dinoCosineMode;
  elements.slimmingThresholdDINOSimilarity.value = String(
    thresholds.dinoCosineMinSimilarity
  );
  elements.slimmingThresholdBucketingMode.value = thresholds.sceneBucketingMode;
  elements.slimmingThresholdBucketActivationCount.value = String(
    thresholds.sceneBucketActivationAssetCount
  );
  const locked = editor.loading || editor.saving;
  for (const control of [
    elements.slimmingThresholdRecallMode,
    elements.slimmingThresholdL2Mode,
    elements.slimmingThresholdDINOMode,
    elements.slimmingThresholdBucketingMode,
  ]) control.disabled = locked;
  elements.slimmingThresholdRecallTopK.disabled = locked
    || thresholds.featurePrintRecallMode === "allCandidates";
  elements.slimmingThresholdL2Distance.disabled = locked
    || thresholds.featurePrintL2Mode === "unlimited";
  elements.slimmingThresholdDINOSimilarity.disabled = locked
    || thresholds.dinoCosineMode === "unlimited";
  elements.slimmingThresholdBucketActivationCount.disabled = locked
    || thresholds.sceneBucketingMode !== "automatic";
  elements.slimmingThresholdDialogExtremeWarning.classList.toggle(
    "hidden",
    thresholds.featurePrintRecallMode !== "allCandidates"
      && thresholds.featurePrintL2Mode !== "unlimited"
      && thresholds.dinoCosineMode !== "unlimited"
      && thresholds.sceneBucketingMode === "automatic"
  );
  syncSlimmingThresholdInteractionSurface(elements.slimmingThresholdDialogContent);
}

function renderSlimmingThresholdEditor() {
  const editor = state.slimming.thresholdEditor;
  elements.slimmingThresholdDialogLoading.classList.toggle("hidden", !editor.loading);
  elements.slimmingThresholdDialogContent.classList.toggle(
    "hidden",
    editor.loading || !editor.thresholds
  );
  elements.slimmingThresholdDialogError.textContent = editor.error;
  elements.applySlimmingThresholdDialogButton.textContent = editor.saving
    ? "正在保存…" : "应用";
  elements.resetSlimmingThresholdDialogButton.textContent = "恢复默认";
  syncSlimmingThresholdEditorControls();
  syncWriteActionControls();
}

function readSlimmingThresholdEditorControls() {
  const editor = state.slimming.thresholdEditor;
  editor.thresholds = {
    featurePrintRecallTopK: Number(elements.slimmingThresholdRecallTopK.value),
    featurePrintMaxL2Distance: Number(elements.slimmingThresholdL2Distance.value),
    dinoCosineMinSimilarity: Number(elements.slimmingThresholdDINOSimilarity.value),
    sceneBucketActivationAssetCount: Number(
      elements.slimmingThresholdBucketActivationCount.value
    ),
    featurePrintRecallMode: elements.slimmingThresholdRecallMode.value,
    featurePrintL2Mode: elements.slimmingThresholdL2Mode.value,
    dinoCosineMode: elements.slimmingThresholdDINOMode.value,
    sceneBucketingMode: elements.slimmingThresholdBucketingMode.value,
  };
  editor.operationID = null;
  editor.error = slimmingThresholdsValid(editor.thresholds)
    ? "" : "请检查相似阈值；数值必须在允许范围内。";
  renderSlimmingThresholdEditor();
}

function slimmingThresholdBaseLevelFromHistory(context = {}) {
  return ["sidebar", "inspector", "lightbox"].includes(context.slimmingThresholdBaseLevel)
    ? context.slimmingThresholdBaseLevel
    : "workspace";
}

function replaceSlimmingThresholdHistoryWithBase(baseLevel) {
  if (!state.workspaceNavigation.initialized
    || elements.appView.classList.contains("hidden")) return;
  const current = activeWorkspaceHistoryEntry();
  const route = visibleWorkspaceRoute();
  if (current?.route !== route || current.navigationLevel !== "slimmingThreshold") return;
  const context = currentWorkspaceHistoryContext(route);
  if (context && typeof context === "object") delete context.slimmingThresholdBaseLevel;
  const navigationLevel = visibleWorkspaceNavigationBaseLevel(route, baseLevel);
  history.replaceState({
    ...(history.state || {}),
    [WORKSPACE_HISTORY_KEY]: workspaceHistoryEntry(route, context, navigationLevel),
  }, "", location.href);
}

function clearSlimmingThresholdEditorState({ cancelRequest = true } = {}) {
  const editor = state.slimming.thresholdEditor;
  if (cancelRequest) editor.requestGeneration += 1;
  editor.loading = false;
  editor.saving = false;
  editor.operationID = null;
  editor.returnFocus = null;
  editor.baseLevel = "workspace";
  editor.historyRestoreFocus = true;
  editor.focusID = "closeSlimmingThresholdDialogButton";
  editor.restorable = false;
  editor.opening = false;
}

function presentSlimmingThresholdEditor({
  historyMode = "pushSlimmingThreshold",
  baseLevel = null,
  focus = true,
} = {}) {
  const editor = state.slimming.thresholdEditor;
  if (elements.slimmingThresholdDialog.open) {
    if (focus) restoreOverlayFocus(elements.closeSlimmingThresholdDialogButton);
    return;
  }
  const current = activeWorkspaceHistoryEntry();
  editor.baseLevel = baseLevel
    || workspaceNavigationBaseLevel(
      current?.navigationLevel || "workspace",
      current?.context || {}
    );
  elements.slimmingThresholdDialog.showModal();
  if (historyMode !== "none") {
    const route = visibleWorkspaceRoute();
    recordWorkspaceHistory(route, currentWorkspaceHistoryContext(route), historyMode);
  }
  editor.restorable = true;
  renderSlimmingThresholdEditor();
  if (focus) {
    restoreOverlayFocus(
      document.getElementById(editor.focusID) || elements.closeSlimmingThresholdDialogButton
    );
  }
}

async function openSlimmingThresholdEditor(
  returnFocus = elements.slimmingAnalysisOptionsButton
) {
  const editor = state.slimming.thresholdEditor;
  if (elements.slimmingThresholdDialog.open || editor.opening) return;
  await returnFromActionMenu({ restoreFocus: false });
  editor.opening = true;
  editor.loading = true;
  editor.saving = false;
  editor.thresholds = null;
  editor.factoryThresholds = null;
  editor.error = "";
  editor.operationID = null;
  editor.returnFocus = returnFocus;
  const generation = ++editor.requestGeneration;
  try {
    presentSlimmingThresholdEditor();
  } finally {
    editor.opening = false;
  }
  try {
    const query = new URLSearchParams({ mediaKind: state.slimming.mediaKind });
    const snapshot = await api(`/v1/library-slimming/setup?${query}`);
    if (generation !== editor.requestGeneration) return;
    editor.thresholds = normalizeSlimmingThresholdDraft(snapshot.thresholds);
    editor.factoryThresholds = normalizeSlimmingThresholdDraft(snapshot.factoryThresholds);
  } catch (error) {
    if (generation === editor.requestGeneration) {
      editor.error = error.message || "相似阈值载入失败";
    }
  } finally {
    if (generation === editor.requestGeneration) {
      editor.loading = false;
      if (elements.slimmingThresholdDialog.open) renderSlimmingThresholdEditor();
    }
  }
}

function closeSlimmingThresholdEditor({
  restoreFocus = true,
  checkpoint = true,
  preserveState = false,
} = {}) {
  if (!elements.slimmingThresholdDialog.open) return;
  const editor = state.slimming.thresholdEditor;
  const active = document.activeElement;
  if (active instanceof HTMLElement && elements.slimmingThresholdDialog.contains(active) && active.id) {
    editor.focusID = active.id;
  }
  const baseLevel = editor.baseLevel;
  const returnFocus = editor.returnFocus;
  elements.slimmingThresholdDialog.close();
  if (restoreFocus) {
    restoreOverlayFocus(stableReturnFocusTarget(
      returnFocus,
      elements.slimmingAnalysisOptionsButton
    ));
  }
  if (checkpoint) replaceSlimmingThresholdHistoryWithBase(baseLevel);
  if (!preserveState) clearSlimmingThresholdEditorState();
}

function returnFromSlimmingThreshold({ restoreFocus = true } = {}) {
  if (!elements.slimmingThresholdDialog.open) return Promise.resolve();
  const editor = state.slimming.thresholdEditor;
  editor.historyRestoreFocus = restoreFocus;
  if (state.workspaceNavigation.pendingReturnPromise) {
    return state.workspaceNavigation.pendingReturnPromise;
  }
  const current = activeWorkspaceHistoryEntry();
  if (state.workspaceNavigation.initialized
    && current?.route === visibleWorkspaceRoute()
    && current.navigationLevel === "slimmingThreshold") {
    const pending = new Promise((resolve) => {
      state.workspaceNavigation.pendingReturnResolve = resolve;
    });
    state.workspaceNavigation.pendingReturnPromise = pending;
    history.back();
    return pending;
  }
  closeSlimmingThresholdEditor({ restoreFocus });
  editor.historyRestoreFocus = true;
  return Promise.resolve();
}

function reconcileSlimmingThresholdFromWorkspaceHistory(route, navigationLevel, context = {}) {
  const shouldOpen = navigationLevel === "slimmingThreshold"
    && route === "slimming"
    && route === visibleWorkspaceRoute();
  const editor = state.slimming.thresholdEditor;
  if (shouldOpen && !editor.restorable) {
    clearSlimmingThresholdEditorState();
    replaceSlimmingThresholdHistoryWithBase(slimmingThresholdBaseLevelFromHistory(context));
    return;
  }
  if (shouldOpen && !elements.slimmingThresholdDialog.open) {
    presentSlimmingThresholdEditor({
      historyMode: "none",
      baseLevel: slimmingThresholdBaseLevelFromHistory(context),
    });
  } else if (!shouldOpen && elements.slimmingThresholdDialog.open) {
    const restoreFocus = editor.historyRestoreFocus;
    closeSlimmingThresholdEditor({
      restoreFocus,
      checkpoint: false,
      preserveState: true,
    });
    editor.historyRestoreFocus = true;
  }
}

async function saveSlimmingThresholdEditor({ restoreFactory = false } = {}) {
  const editor = state.slimming.thresholdEditor;
  const nextThresholds = normalizeSlimmingThresholdDraft(
    restoreFactory ? editor.factoryThresholds : editor.thresholds
  );
  if (!state.online || editor.saving || !slimmingThresholdsValid(nextThresholds)) return;
  editor.thresholds = nextThresholds;
  editor.saving = true;
  editor.error = "";
  if (restoreFactory) editor.operationID = null;
  editor.operationID ||= crypto.randomUUID();
  renderSlimmingThresholdEditor();
  try {
    const result = await api("/v1/library-slimming/thresholds", {
      method: "PUT",
      body: JSON.stringify({
        operationID: editor.operationID,
        thresholds: editor.thresholds,
      }),
    });
    editor.thresholds = normalizeSlimmingThresholdDraft(result.thresholds);
    editor.operationID = null;
    state.slimming.setup.thresholds = normalizeSlimmingThresholdDraft(result.thresholds);
    if (state.slimming.setup.snapshot) {
      state.slimming.setup.snapshot.thresholds = result.thresholds;
    }
    toast(restoreFactory
      ? "已恢复默认阈值，将在下次分析生效"
      : "阈值已更新，将在下次分析生效");
  } catch (error) {
    editor.error = error.message || "相似阈值保存失败";
  } finally {
    editor.saving = false;
    renderSlimmingThresholdEditor();
  }
}

function canSaveSlimmingThresholds() {
  const setup = state.slimming.setup;
  return Boolean(setup.snapshot)
    && !setup.loading
    && !setup.saving
    && !setup.launching
    && slimmingThresholdsValid();
}

function canLaunchSlimmingSetup() {
  const setup = state.slimming.setup;
  if (!canSaveSlimmingThresholds() || !slimmingModeAvailable(setup.mode)) return false;
  if (setup.mode === "catalog") return setup.selectedSourceIDs.size > 0;
  if (setup.mode === "seeds") return currentSlimmingSeedIDs().length > 0;
  return state.mediaKind === state.slimming.mediaKind;
}

function syncSlimmingSetupText(element, text) {
  if (element.textContent !== text) element.textContent = text;
}

function slimmingSetupSelectedSources() {
  return (state.slimming.setup.snapshot?.sources || []).filter(
    (source) => state.slimming.setup.selectedSourceIDs.has(source.id)
  );
}

function slimmingSetupSourceSummary() {
  const sources = state.slimming.setup.snapshot?.sources || [];
  const selected = slimmingSetupSelectedSources();
  if (!selected.length) return "未选择来源";
  if (selected.length === sources.length) return `全部 ${sources.length} 个可用来源`;
  if (selected.length === 1) return selected[0].displayName;
  return `已选 ${selected.length} 个来源`;
}

function slimmingSetupThresholdSummary(thresholds = state.slimming.setup.thresholds) {
  if (!slimmingThresholdsValid(thresholds)) return "设置值无效";
  const number = (value, maximumFractionDigits = 2) => Number(value).toLocaleString(
    "zh-CN",
    { maximumFractionDigits }
  );
  const recall = thresholds.featurePrintRecallMode === "allCandidates"
    ? "召回全部候选"
    : `Top-K ${number(thresholds.featurePrintRecallTopK, 0)}`;
  const l2 = thresholds.featurePrintL2Mode === "unlimited"
    ? "L2 不限"
    : `L2 ≤ ${number(thresholds.featurePrintMaxL2Distance)}`;
  const dino = thresholds.dinoCosineMode === "unlimited"
    ? "DINOv2 不限"
    : `DINOv2 ≥ ${number(thresholds.dinoCosineMinSimilarity)}`;
  const bucketing = {
    always: "始终按拍摄日分桶",
    never: "不按拍摄日分桶",
    automatic: `媒体 ≥ ${number(thresholds.sceneBucketActivationAssetCount, 0)} 时按拍摄日分桶`,
  }[thresholds.sceneBucketingMode];
  return [recall, l2, dino, bucketing].join(" · ");
}

function slimmingSetupLaunchPresentation() {
  const setup = state.slimming.setup;
  if (setup.mode === "catalog") {
    const sources = setup.snapshot?.sources || [];
    const selected = slimmingSetupSelectedSources();
    const allSelected = sources.length > 0 && selected.length === sources.length;
    return {
      idle: allSelected ? "分析全部来源" : "分析所选来源",
      running: allSelected ? "正在分析全部来源…" : "正在分析所选来源…",
    };
  }
  if (setup.mode === "seeds") {
    return {
      idle: `按种子查找（${currentSlimmingSeedIDs().length}）`,
      running: "正在按种子查找…",
    };
  }
  const selectedSource = (setup.snapshot?.sources || state.sources).find(
    (source) => source.id === state.selectedSourceID
  );
  return selectedSource
    ? {
      idle: `分析来源：${selectedSource.displayName}`,
      running: `正在分析：${selectedSource.displayName}…`,
    }
    : { idle: "分析当前筛选", running: "正在分析当前筛选…" };
}

function reconcileSlimmingSetupSummary(rows) {
  const existing = new Map(
    [...elements.slimmingLaunchSummary.querySelectorAll(
      ":scope > dt[data-slimming-setup-summary-key]"
    )].map((term) => {
      const description = term.nextElementSibling;
      return description?.matches("dd[data-slimming-setup-summary-key]")
        && description.dataset.slimmingSetupSummaryKey === term.dataset.slimmingSetupSummaryKey
        ? [term.dataset.slimmingSetupSummaryKey, { term, description }]
        : null;
    }).filter(Boolean)
  );
  const wanted = [];
  for (const row of rows) {
    let pair = existing.get(row.key) || null;
    if (!pair) {
      const term = document.createElement("dt");
      const description = document.createElement("dd");
      term.dataset.slimmingSetupSummaryKey = row.key;
      description.dataset.slimmingSetupSummaryKey = row.key;
      pair = { term, description };
    }
    syncSlimmingSetupText(pair.term, row.label);
    syncSlimmingSetupText(pair.description, row.value);
    wanted.push(pair.term, pair.description);
  }
  reconcileStableChildren(elements.slimmingLaunchSummary, wanted);
}

function createSlimmingSetupModeOption() {
  const button = document.createElement("button");
  button.type = "button";
  button.className = "slimming-mode-option";
  button.append(document.createElement("strong"), document.createElement("span"));
  return button;
}

function syncSlimmingSetupModeOption(button, mode) {
  const copy = slimmingModeCopy(mode);
  const selected = state.slimming.setup.mode === mode;
  button.id = `slimmingSetupMode-${mode}`;
  button.classList.toggle("selected", selected);
  button.dataset.slimmingMode = mode;
  button.disabled = !slimmingModeAvailable(mode) || state.slimming.setup.launching;
  button.tabIndex = selected ? 0 : -1;
  button.setAttribute("role", "radio");
  button.setAttribute("aria-checked", String(selected));
  const title = button.querySelector(":scope > strong");
  if (title.textContent !== copy.title) title.textContent = copy.title;
  const detail = button.querySelector(":scope > span");
  if (detail.textContent !== copy.detail) detail.textContent = copy.detail;
  configurePersistentHelp(button, {
    title: `瘦身分析范围 · ${copy.title}`,
    detail: copy.detail,
    kind: "slimming",
  });
}

function renderSlimmingSetupModes() {
  const existingOptions = new Map(
    [...elements.slimmingModeOptions.querySelectorAll(":scope > .slimming-mode-option")]
      .map((button) => [button.dataset.slimmingMode, button])
  );
  const modeOptions = ["catalog", "currentFilter", "seeds"].map((mode) => {
    const button = existingOptions.get(mode) || createSlimmingSetupModeOption();
    syncSlimmingSetupModeOption(button, mode);
    return button;
  });
  reconcileStableChildren(elements.slimmingModeOptions, modeOptions);
}

function moveSlimmingSetupModeSelection(event) {
  if (!event.target.closest("[data-slimming-mode]")
    || !["ArrowLeft", "ArrowRight", "ArrowUp", "ArrowDown", "Home", "End"].includes(
      event.key
    )) return;
  const options = [...elements.slimmingModeOptions.querySelectorAll("[data-slimming-mode]")]
    .filter((button) => !button.disabled);
  if (!options.length) return;
  event.preventDefault();
  const current = Math.max(0, options.indexOf(event.target.closest("[data-slimming-mode]")));
  const backwards = event.key === "ArrowLeft" || event.key === "ArrowUp";
  const next = event.key === "Home" ? 0
    : event.key === "End" ? options.length - 1
      : (current + (backwards ? -1 : 1) + options.length) % options.length;
  options[next].focus({ preventScroll: true });
  options[next].click();
}

function createSlimmingSetupSourceOption() {
  const row = document.createElement("label");
  row.className = "training-option-row";
  const input = document.createElement("input");
  input.type = "checkbox";
  row.append(input, document.createElement("strong"), document.createElement("span"));
  return row;
}

function syncSlimmingSetupSourceOption(row, source) {
  const input = row.querySelector(':scope > input[type="checkbox"]');
  input.id = `slimmingSetupSource-${source.id}`;
  input.checked = state.slimming.setup.selectedSourceIDs.has(source.id);
  input.disabled = state.slimming.setup.launching;
  input.dataset.slimmingSourceId = source.id;
  input.setAttribute("aria-keyshortcuts", choiceGridNavigationShortcuts);
  const name = row.querySelector(":scope > strong");
  if (name.textContent !== source.displayName) name.textContent = source.displayName;
  const kind = row.querySelector(":scope > span");
  const kindText = source.kind === "photos" ? "照片图库" : "文件夹";
  if (kind.textContent !== kindText) kind.textContent = kindText;
  configurePersistentHelp(row, {
    title: `瘦身分析来源 · ${source.displayName}`,
    detail: "选择后只在这台 Mac 上读取该来源并纳入本次分析；方向键、Page Up/Page Down 或 Home/End 可移动，空格键切换勾选。",
    kind: "slimming",
    keyShortcuts: choiceGridNavigationShortcuts,
  });
}

function renderSlimmingSourceOptions() {
  const setup = state.slimming.setup;
  elements.slimmingSourceSection.classList.toggle("hidden", setup.mode !== "catalog");
  if (setup.mode !== "catalog") {
    reconcileStableChildren(elements.slimmingSourceOptions, []);
    return;
  }
  const sources = setup.snapshot?.sources || [];
  const allSelected = sources.length > 0
    && sources.every((source) => setup.selectedSourceIDs.has(source.id));
  syncSlimmingSetupText(
    elements.toggleAllSlimmingSourcesButton,
    allSelected ? "清除" : "全选"
  );
  elements.toggleAllSlimmingSourcesButton.disabled = setup.launching;
  syncSlimmingSetupText(
    elements.slimmingSourceHint,
    allSelected
      ? "已选择全部可用来源；提交时保留 Mac 端“全部来源”语义。"
      : `已选择 ${setup.selectedSourceIDs.size} / ${sources.length} 个来源。`
  );
  const existingOptions = new Map(
    [...elements.slimmingSourceOptions.querySelectorAll(":scope > .training-option-row")]
      .map((row) => [
        row.querySelector("[data-slimming-source-id]")?.dataset.slimmingSourceId,
        row,
      ])
  );
  const sourceOptions = sources.map((source) => {
    const row = existingOptions.get(source.id) || createSlimmingSetupSourceOption();
    syncSlimmingSetupSourceOption(row, source);
    return row;
  });
  reconcileStableChildren(elements.slimmingSourceOptions, sourceOptions);
}

function syncSlimmingThresholdControls() {
  const setup = state.slimming.setup;
  const thresholds = setup.thresholds;
  if (!thresholds) return;
  elements.slimmingRecallMode.value = thresholds.featurePrintRecallMode;
  elements.slimmingRecallTopK.value = String(thresholds.featurePrintRecallTopK);
  elements.slimmingL2Mode.value = thresholds.featurePrintL2Mode;
  elements.slimmingL2Distance.value = String(thresholds.featurePrintMaxL2Distance);
  elements.slimmingDINOMode.value = thresholds.dinoCosineMode;
  elements.slimmingDINOSimilarity.value = String(thresholds.dinoCosineMinSimilarity);
  elements.slimmingBucketingMode.value = thresholds.sceneBucketingMode;
  elements.slimmingBucketActivationCount.value = String(
    thresholds.sceneBucketActivationAssetCount
  );
  const locked = setup.saving || setup.launching;
  elements.resetSlimmingThresholdsButton.disabled = locked;
  for (const control of [
    elements.slimmingRecallMode,
    elements.slimmingL2Mode,
    elements.slimmingDINOMode,
    elements.slimmingBucketingMode,
  ]) control.disabled = locked;
  elements.slimmingRecallTopK.disabled = locked
    || thresholds.featurePrintRecallMode === "allCandidates";
  elements.slimmingL2Distance.disabled = locked || thresholds.featurePrintL2Mode === "unlimited";
  elements.slimmingDINOSimilarity.disabled = locked || thresholds.dinoCosineMode === "unlimited";
  elements.slimmingBucketActivationCount.disabled = locked
    || thresholds.sceneBucketingMode !== "automatic";
  elements.slimmingExtremeWarning.classList.toggle(
    "hidden",
    thresholds.featurePrintRecallMode !== "allCandidates"
      && thresholds.featurePrintL2Mode !== "unlimited"
      && thresholds.dinoCosineMode !== "unlimited"
      && thresholds.sceneBucketingMode === "automatic"
  );
  syncSlimmingThresholdInteractionSurface(elements.slimmingSetupConfiguration);
}

function renderSlimmingSetupSummary() {
  const setup = state.slimming.setup;
  const copy = slimmingModeCopy(setup.mode);
  const rows = [{ key: "scope", label: "范围", value: copy.title }];
  if (setup.mode === "catalog") {
    rows.push({ key: "source", label: "来源", value: slimmingSetupSourceSummary() });
  } else if (setup.mode === "seeds") {
    rows.push({
      key: "seeds",
      label: "种子",
      value: `${currentSlimmingSeedIDs().length} 项`,
    });
  } else {
    rows.push({
      key: "filter",
      label: "筛选",
      value: slimmingInspectorFilterScopeSummary(),
    });
  }
  rows.push({
    key: "thresholds",
    label: "相似阈值",
    value: slimmingSetupThresholdSummary(),
  });
  reconcileSlimmingSetupSummary(rows);
}

function renderSlimmingSetup() {
  const setup = state.slimming.setup;
  elements.slimmingSetupLoading.classList.toggle("hidden", !setup.loading);
  elements.slimmingSetupConfiguration.classList.toggle("hidden", setup.loading || !setup.snapshot);
  syncSlimmingSetupText(elements.slimmingSetupNotice, setup.notice);
  elements.slimmingSetupNotice.classList.toggle("hidden", !setup.notice);
  syncSlimmingSetupText(elements.slimmingSetupError, setup.error);
  const launchPresentation = slimmingSetupLaunchPresentation();
  syncSlimmingSetupText(
    elements.launchSlimmingButton,
    setup.launching ? launchPresentation.running : launchPresentation.idle
  );
  elements.launchSlimmingButton.setAttribute(
    "aria-label",
    setup.launching ? launchPresentation.running : launchPresentation.idle
  );
  syncSlimmingSetupText(
    elements.saveSlimmingThresholdsButton,
    setup.saving && !setup.launching ? "正在保存…" : "仅保存设置"
  );
  if (setup.snapshot) {
    renderSlimmingSetupModes();
    renderSlimmingSourceOptions();
    syncSlimmingThresholdControls();
    renderSlimmingSetupSummary();
  }
  renderSlimmingCatalogCommands();
  syncWriteActionControls();
}

function slimmingSetupScrollSurfaces() {
  return {
    body: elements.slimmingSetupDialog.querySelector(".slimming-setup-body"),
    sources: elements.slimmingSourceOptions,
    thresholds: elements.slimmingSetupConfiguration.querySelector(".slimming-thresholds"),
  };
}

function currentSlimmingSetupHistoryContext() {
  const setup = state.slimming.setup;
  const scroll = slimmingSetupScrollSurfaces();
  const thresholds = normalizeSlimmingThresholdDraft(setup.thresholds);
  return {
    slimmingSetupMode: setup.mode,
    slimmingSetupSourceIDs: [...setup.selectedSourceIDs]
      .slice(0, GALLERY_HISTORY_LOADED_LIMIT),
    slimmingSetupThresholds: slimmingThresholdsValid(thresholds) ? thresholds : null,
    slimmingSetupBodyScrollTop: scroll.body?.scrollTop || 0,
    slimmingSetupSourcesScrollTop: scroll.sources?.scrollTop || 0,
    slimmingSetupThresholdsOpen: scroll.thresholds?.open !== false,
  };
}

function applySlimmingSetupHistoryContext(context = {}) {
  const setup = state.slimming.setup;
  if (!setup.snapshot) return false;
  const modes = new Set(["catalog", "currentFilter", "seeds"]);
  const requestedMode = modes.has(context.slimmingSetupMode)
    ? context.slimmingSetupMode
    : (slimmingModeAvailable("currentFilter") ? "currentFilter" : "catalog");
  setup.mode = requestedMode;

  const activeSourceIDs = new Set((setup.snapshot.sources || []).map((source) => source.id));
  const savedSourceIDs = Array.isArray(context.slimmingSetupSourceIDs)
    ? context.slimmingSetupSourceIDs
      .map(galleryHistoryIdentifier)
      .filter(Boolean)
      .slice(0, GALLERY_HISTORY_LOADED_LIMIT)
    : null;
  const selectedSourceIDs = savedSourceIDs
    ? [...new Set(savedSourceIDs)].filter((sourceID) => activeSourceIDs.has(sourceID))
    : [...resolvedSlimmingCatalogSourceIDs(setup.snapshot)];
  setSlimmingCatalogSourceIDs(new Set(selectedSourceIDs), setup.snapshot);

  const savedThresholds = normalizeSlimmingThresholdDraft(context.slimmingSetupThresholds);
  setup.thresholds = slimmingThresholdsValid(savedThresholds)
    ? savedThresholds
    : normalizeSlimmingThresholdDraft(setup.snapshot.thresholds);

  const missingSourceCount = savedSourceIDs
    ? new Set(savedSourceIDs.filter((sourceID) => !activeSourceIDs.has(sourceID))).size
    : 0;
  const notes = [];
  if (context.slimmingSetupMode && !modes.has(context.slimmingSetupMode)) {
    notes.push("刷新前的分析范围无效，已切换到可用范围。");
  } else if (!slimmingModeAvailable(requestedMode)) {
    notes.push(requestedMode === "seeds"
      ? "刷新前的种子选区当前不可用，请重新选择照片后再开始分析。"
      : "刷新前的当前筛选与分析媒体类型不再一致，请重新确认范围。");
  }
  if (missingSourceCount) {
    notes.push(`${missingSourceCount} 个历史来源当前不可用，已从本次配置中移除。`);
  }
  if (context.slimmingSetupThresholds && !slimmingThresholdsValid(savedThresholds)) {
    notes.push("刷新前的相似阈值无效，已恢复为 Mac 当前设置。");
  }
  setup.notice = notes.join(" ");
  return true;
}

async function restoreSlimmingSetupLayoutFromHistory(context = {}) {
  await waitForWorkspaceLayout();
  const scroll = slimmingSetupScrollSurfaces();
  if (scroll.thresholds) {
    scroll.thresholds.open = context.slimmingSetupThresholdsOpen !== false;
  }
  for (const [surface, value] of [
    [scroll.body, context.slimmingSetupBodyScrollTop],
    [scroll.sources, context.slimmingSetupSourcesScrollTop],
  ]) {
    if (!surface) continue;
    surface.scrollTop = Math.min(
      workspaceHistoryScrollTop(value),
      Math.max(0, surface.scrollHeight - surface.clientHeight)
    );
  }
}

function slimmingSetupBaseLevelFromHistory(context = {}) {
  return ["sidebar", "inspector", "lightbox"].includes(context.slimmingSetupBaseLevel)
    ? context.slimmingSetupBaseLevel
    : "workspace";
}

function replaceSlimmingSetupHistoryWithBase(baseLevel) {
  if (!state.workspaceNavigation.initialized
    || elements.appView.classList.contains("hidden")) return;
  const current = activeWorkspaceHistoryEntry();
  const route = visibleWorkspaceRoute();
  if (current?.route !== route || current.navigationLevel !== "slimmingSetup") return;
  const context = currentWorkspaceHistoryContext(route);
  if (context && typeof context === "object") delete context.slimmingSetupBaseLevel;
  const navigationLevel = visibleWorkspaceNavigationBaseLevel(route, baseLevel);
  history.replaceState({
    ...(history.state || {}),
    [WORKSPACE_HISTORY_KEY]: workspaceHistoryEntry(route, context, navigationLevel),
  }, "", location.href);
}

function clearSlimmingSetupDialogState({ cancelRequest = true } = {}) {
  const setup = state.slimming.setup;
  if (cancelRequest) setup.requestGeneration += 1;
  setup.loading = false;
  setup.saving = false;
  setup.launching = false;
  setup.thresholdOperationID = null;
  setup.launchOperationID = null;
  setup.notice = "";
  setup.returnFocus = null;
  setup.baseLevel = "workspace";
  setup.historyRestoreFocus = true;
  setup.focusID = "closeSlimmingSetupButton";
  setup.restorable = false;
  setup.opening = false;
}

function presentSlimmingSetupDialog({
  historyMode = "pushSlimmingSetup",
  baseLevel = null,
  focus = true,
} = {}) {
  const setup = state.slimming.setup;
  if (elements.slimmingSetupDialog.open) {
    if (focus) restoreOverlayFocus(elements.closeSlimmingSetupButton);
    return;
  }
  const current = activeWorkspaceHistoryEntry();
  setup.baseLevel = baseLevel
    || workspaceNavigationBaseLevel(
      current?.navigationLevel || "workspace",
      current?.context || {}
    );
  elements.slimmingSetupDialog.showModal();
  if (historyMode !== "none") {
    const route = visibleWorkspaceRoute();
    recordWorkspaceHistory(route, currentWorkspaceHistoryContext(route), historyMode);
  }
  setup.restorable = true;
  renderSlimmingSetup();
  if (focus) {
    restoreOverlayFocus(
      document.getElementById(setup.focusID) || elements.closeSlimmingSetupButton
    );
  }
}

async function openSlimmingSetupDialog(
  returnFocus = elements.slimmingAnalysisOptionsButton,
  {
    historyMode = "pushSlimmingSetup",
    baseLevel = null,
    focus = true,
    historyContext = null,
  } = {}
) {
  const setup = state.slimming.setup;
  if (elements.slimmingSetupDialog.open || setup.opening) return;
  await returnFromActionMenu({ restoreFocus: false });
  setup.opening = true;
  setup.returnFocus = returnFocus || elements.slimmingAnalysisOptionsButton;
  setup.loading = true;
  setup.saving = false;
  setup.launching = false;
  setup.snapshot = null;
  setup.notice = "";
  setup.error = "";
  setup.thresholdOperationID = null;
  setup.launchOperationID = null;
  const generation = ++setup.requestGeneration;
  try {
    presentSlimmingSetupDialog({ historyMode, baseLevel, focus });
  } finally {
    setup.opening = false;
  }
  try {
    const workspaceSnapshot = historyContext
      && state.slimming.catalogSources.snapshot?.mediaKind === state.slimming.mediaKind
      ? state.slimming.catalogSources.snapshot
      : null;
    const query = new URLSearchParams({ mediaKind: state.slimming.mediaKind });
    const snapshot = workspaceSnapshot
      || await api(`/v1/library-slimming/setup?${query}`);
    if (generation !== setup.requestGeneration) return;
    setup.snapshot = snapshot;
    state.slimming.catalogSources.snapshot = snapshot;
    if (historyContext) {
      applySlimmingSetupHistoryContext(historyContext);
    } else {
      setup.mode = slimmingModeAvailable("currentFilter") ? "currentFilter" : "catalog";
      setSlimmingCatalogSourceIDs(resolvedSlimmingCatalogSourceIDs(snapshot), snapshot);
      setup.thresholds = normalizeSlimmingThresholdDraft(snapshot.thresholds);
    }
  } catch (error) {
    if (generation === setup.requestGeneration) {
      setup.error = error.message || "图库瘦身设置载入失败";
    }
  } finally {
    if (generation === setup.requestGeneration) {
      setup.loading = false;
      if (elements.slimmingSetupDialog.open) {
        renderSlimmingSetup();
        if (historyContext && setup.snapshot) {
          await restoreSlimmingSetupLayoutFromHistory(historyContext);
        }
        if (!historyContext) checkpointActiveWorkspaceHistory();
      }
    }
  }
}

function closeSlimmingSetupDialog({
  restoreFocus = true,
  checkpoint = true,
  preserveState = false,
} = {}) {
  if (!elements.slimmingSetupDialog.open) return;
  const setup = state.slimming.setup;
  const active = document.activeElement;
  if (active instanceof HTMLElement && elements.slimmingSetupDialog.contains(active) && active.id) {
    setup.focusID = active.id;
  }
  const baseLevel = setup.baseLevel;
  const returnFocus = setup.returnFocus;
  elements.slimmingSetupDialog.close();
  if (restoreFocus) {
    restoreOverlayFocus(stableReturnFocusTarget(
      returnFocus,
      elements.slimmingAnalysisOptionsButton
    ));
  }
  if (checkpoint) replaceSlimmingSetupHistoryWithBase(baseLevel);
  if (!preserveState) clearSlimmingSetupDialogState();
}

function returnFromSlimmingSetup({ restoreFocus = true } = {}) {
  if (!elements.slimmingSetupDialog.open) return Promise.resolve();
  const setup = state.slimming.setup;
  setup.historyRestoreFocus = restoreFocus;
  if (state.workspaceNavigation.pendingReturnPromise) {
    return state.workspaceNavigation.pendingReturnPromise;
  }
  const current = activeWorkspaceHistoryEntry();
  if (state.workspaceNavigation.initialized
    && current?.route === visibleWorkspaceRoute()
    && current.navigationLevel === "slimmingSetup") {
    const pending = new Promise((resolve) => {
      state.workspaceNavigation.pendingReturnResolve = resolve;
    });
    state.workspaceNavigation.pendingReturnPromise = pending;
    history.back();
    return pending;
  }
  closeSlimmingSetupDialog({ restoreFocus });
  setup.historyRestoreFocus = true;
  return Promise.resolve();
}

async function reconcileSlimmingSetupFromWorkspaceHistory(route, navigationLevel, context = {}) {
  const shouldOpen = navigationLevel === "slimmingSetup"
    && route === "slimming"
    && route === visibleWorkspaceRoute();
  const setup = state.slimming.setup;
  if (shouldOpen && !setup.restorable) {
    clearSlimmingSetupDialogState();
    await openSlimmingSetupDialog(elements.slimmingAnalysisOptionsButton, {
      historyMode: "none",
      baseLevel: slimmingSetupBaseLevelFromHistory(context),
      focus: false,
      historyContext: context,
    });
    return Boolean(setup.snapshot);
  }
  if (shouldOpen && !elements.slimmingSetupDialog.open) {
    presentSlimmingSetupDialog({
      historyMode: "none",
      baseLevel: slimmingSetupBaseLevelFromHistory(context),
    });
  } else if (!shouldOpen && elements.slimmingSetupDialog.open) {
    const restoreFocus = setup.historyRestoreFocus;
    closeSlimmingSetupDialog({
      restoreFocus,
      checkpoint: false,
      preserveState: true,
    });
    setup.historyRestoreFocus = true;
  }
  return false;
}

function readSlimmingThresholdControls() {
  const setup = state.slimming.setup;
  setup.thresholds = {
    featurePrintRecallTopK: Number(elements.slimmingRecallTopK.value),
    featurePrintMaxL2Distance: Number(elements.slimmingL2Distance.value),
    dinoCosineMinSimilarity: Number(elements.slimmingDINOSimilarity.value),
    sceneBucketActivationAssetCount: Number(elements.slimmingBucketActivationCount.value),
    featurePrintRecallMode: elements.slimmingRecallMode.value,
    featurePrintL2Mode: elements.slimmingL2Mode.value,
    dinoCosineMode: elements.slimmingDINOMode.value,
    sceneBucketingMode: elements.slimmingBucketingMode.value,
  };
  setup.thresholdOperationID = null;
  setup.error = slimmingThresholdsValid() ? "" : "请检查相似阈值；数值必须在允许范围内。";
  renderSlimmingSetup();
  checkpointActiveWorkspaceHistory();
}

async function saveSlimmingThresholds({ forLaunch = false } = {}) {
  const setup = state.slimming.setup;
  if (!slimmingThresholdsValid() || setup.saving) return false;
  setup.saving = true;
  setup.error = "";
  setup.thresholdOperationID ||= crypto.randomUUID();
  renderSlimmingSetup();
  try {
    const result = await api("/v1/library-slimming/thresholds", {
      method: "PUT",
      body: JSON.stringify({
        operationID: setup.thresholdOperationID,
        thresholds: setup.thresholds,
      }),
    });
    setup.thresholds = normalizeSlimmingThresholdDraft(result.thresholds);
    if (setup.snapshot) setup.snapshot.thresholds = result.thresholds;
    setup.thresholdOperationID = null;
    if (!forLaunch) toast("相似阈值已保存到 Mac");
    return true;
  } catch (error) {
    setup.error = error.message || "相似阈值保存失败";
    return false;
  } finally {
    setup.saving = false;
    renderSlimmingSetup();
  }
}

async function submitSlimmingSetup() {
  const setup = state.slimming.setup;
  if (!canLaunchSlimmingSetup()) return;
  setup.launching = true;
  setup.error = "";
  renderSlimmingSetup();
  if (!await saveSlimmingThresholds({ forLaunch: true })) {
    setup.launching = false;
    renderSlimmingSetup();
    return;
  }
  setup.launchOperationID ||= crypto.randomUUID();
  const allSourceIDs = (setup.snapshot?.sources || []).map((source) => source.id);
  const selectedSourceIDs = [...setup.selectedSourceIDs];
  const allSourcesSelected = allSourceIDs.length === selectedSourceIDs.length
    && allSourceIDs.every((id) => setup.selectedSourceIDs.has(id));
  try {
    const result = await api("/v1/library-slimming/launch", {
      method: "POST",
      body: JSON.stringify({
        operationID: setup.launchOperationID,
        mediaKind: state.slimming.mediaKind,
        mode: setup.mode,
        sourceIDs: setup.mode === "catalog"
          ? (allSourcesSelected ? null : selectedSourceIDs)
          : null,
        seedAssetIDs: setup.mode === "seeds" ? currentSlimmingSeedIDs() : [],
        filter: setup.mode === "catalog" ? null : currentSlimmingFilterRequest(),
      }),
    });
    const returnFocus = setup.returnFocus;
    await returnFromSlimmingSetup({ restoreFocus: false });
    clearSlimmingSetupDialogState({ cancelRequest: false });
    state.slimming.selectedJobID = result.jobID;
    toast(`分析已交给 Mac · ${result.memberCount} 项`);
    restoreOverlayFocus(stableReturnFocusTarget(
      returnFocus,
      elements.slimmingAnalysisOptionsButton
    ));
    await loadSlimmingWorkspace({ jobID: result.jobID, quiet: true });
  } catch (error) {
    setup.error = error.message || "图库瘦身分析创建失败";
    setup.launching = false;
    renderSlimmingSetup();
  }
}

async function applySlimmingJobAction(
  jobID,
  action,
  { returnFocus = false, confirmed = false } = {}
) {
  if (!state.online || state.slimming.jobMutatingIDs.has(jobID)) return;
  if (action === "deleteRecord" && !confirmed) {
    requestConfirmation({
      eyebrow: "ANALYSIS RECORD",
      title: "删除这条分析记录？",
      message: "只会永久删除分析任务记录和结果；不会读取、移动或删除任何原始媒体。",
      actionLabel: "删除记录",
      tone: "danger",
      returnFocus: returnFocus === "options"
        ? {
          slimmingJobID: jobID,
          slimmingJobActionSurface: "options",
          slimmingJobAction: action,
        }
        : returnFocus === "navigator"
          ? {
            slimmingJobID: jobID,
            slimmingJobActionSurface: "navigator",
            slimmingJobAction: action,
          }
          : { slimmingJobID: jobID },
      action: () => applySlimmingJobAction(jobID, action, {
        returnFocus,
        confirmed: true,
      }),
    });
    return;
  }
  const selectedBefore = state.slimming.selectedJobID;
  let succeeded = false;
  state.slimming.jobMutatingIDs.add(jobID);
  renderSlimmingJobs();
  renderSlimmingCurrentJobControls();
  try {
    await api(`/v1/library-slimming/jobs/${jobID}/actions`, {
      method: "POST",
      body: JSON.stringify({ operationID: crypto.randomUUID(), action }),
    });
    toast({ pause: "分析已暂停", resume: "分析已继续", deleteRecord: "分析记录已删除" }[action]);
    if (action === "deleteRecord" && selectedBefore === jobID) {
      state.slimming.selectedJobID = null;
      state.slimming.selectedClusterID = null;
      state.slimming.selectedMemberIDs.clear();
      state.slimming.selectionAnchorID = null;
    } else if (action === "deleteRecord") {
      state.slimming.selectedJobID = selectedBefore;
    }
    await loadSlimmingWorkspace({ quiet: true });
    succeeded = true;
  } catch (error) {
    toast(error.message || "分析任务操作失败");
  } finally {
    state.slimming.jobMutatingIDs.delete(jobID);
    renderSlimmingJobs();
    renderSlimmingCurrentJobControls();
    const nextAction = succeeded
      ? ({ pause: "resume", resume: "pause" }[action] || null)
      : action;
    if (returnFocus === "options") {
      focusSlimmingCurrentJobAction(jobID, nextAction);
    } else if (returnFocus === "navigator") {
      focusSlimmingNavigatorJobAction(jobID, nextAction);
    } else if (returnFocus === "status") {
      focusSlimmingJobStatusAction(jobID, nextAction);
    } else if (returnFocus || action === "deleteRecord") {
      focusSelectedSlimmingJob();
    }
  }
}

async function applyReviewTagDecision(action, tagID) {
  const selectedItems = selectedReviewItems();
  const assetIDs = selectedItems.map((item) => item.assetID);
  const generation = state.workspaceGeneration;
  if (!state.online
    || !tagID
    || !assetIDs.length
    || state.review.loading
    || state.review.mutating
    || state.tagMutating
    || state.review.loadedScopeKey !== currentReviewScopeKey()) return;
  const previousIndex = state.review.selectedIndex;
  state.tagMutating = true;
  state.review.mutating = true;
  syncWriteActionControls();
  syncReviewControls();
  try {
    const result = await api("/v1/tag-decisions/batch", {
      method: "POST",
      body: JSON.stringify({
        operationID: crypto.randomUUID(),
        tagID,
        assetIDs,
        action,
      }),
    });
    if (generation !== state.workspaceGeneration) return;
    state.review.detail = null;
    state.review.tagAggregates = [];
    state.review.detailSelectionKey = null;
    state.review.detailRequestGeneration += 1;
    try {
      await Promise.all([
        loadReviewOverview({ throwOnError: true }),
        loadReviewQueue({
          preserveLoadedWindow: true,
          throwOnError: true,
        }),
        loadAssets({
          preserveSelection: true,
          preserveUnchangedGrid: true,
          preserveLoadedWindow: true,
        }),
      ]);
      if (generation !== state.workspaceGeneration) return;
      if (!state.review.selectedAssetIDs.size && state.review.items.length) {
        selectReviewIndex(Math.min(previousIndex, state.review.items.length - 1));
      }
      await loadReviewInspectorDetail({ force: true, quiet: true });
      undoToast(
        result.replayed
          ? "标签操作已恢复"
          : `已为 ${mediaItemCountText(result.appliedAssetCount)}更新人工标签`,
        result.undoID
      );
    } catch {
      if (generation === state.workspaceGeneration) {
        void refreshWorkspace({
          quiet: true,
          kinds: ["tagsChanged", "reviewChanged", "assetsChanged"],
        });
        undoToast("人工标签已更新，界面同步暂时失败，正在重试", result.undoID);
      }
    }
  } catch (error) {
    if (generation === state.workspaceGeneration) {
      toast(error.message || "审核标签更新失败");
    }
  } finally {
    if (generation === state.workspaceGeneration) {
      state.tagMutating = false;
      state.review.mutating = false;
      syncWriteActionControls();
      syncReviewControls();
      renderReviewDetail();
    }
  }
}

async function applyReviewDecision(action) {
  const selectedItems = selectedReviewItems();
  const assetIDs = selectedItems.map((item) => item.assetID);
  const tagID = elements.reviewTagSelect.value;
  const generation = state.workspaceGeneration;
  if (!state.online
    || !assetIDs.length
    || !tagID
    || state.review.loading
    || state.review.mutating
    || state.review.loadedScopeKey !== currentReviewScopeKey()) return;
  state.review.mutating = true;
  syncReviewControls();
  try {
    const result = await api("/v1/review/decisions/batch", {
      method: "POST",
      body: JSON.stringify({
        operationID: crypto.randomUUID(),
        tagID,
        assetIDs,
        action,
      }),
    });
    if (generation !== state.workspaceGeneration) return;
    const previousIndex = state.review.selectedIndex;
    try {
      await Promise.all([
        loadReviewOverview({ throwOnError: true }),
        loadReviewQueue({
          preserveLoadedWindow: true,
          throwOnError: true,
        }),
        loadAssets({
          preserveSelection: true,
          preserveUnchangedGrid: true,
          preserveLoadedWindow: true,
        }),
      ]);
      if (generation !== state.workspaceGeneration) return;
      if (state.review.items.length) {
        selectReviewIndex(Math.min(previousIndex, state.review.items.length - 1));
      }
      undoToast(
        result.replayed
          ? "审核操作已恢复"
          : `已为 ${mediaItemCountText(result.appliedAssetCount)}保存审核决定`,
        result.undoID,
        "review"
      );
    } catch {
      if (generation === state.workspaceGeneration) {
        void refreshWorkspace({
          quiet: true,
          kinds: ["reviewChanged", "assetsChanged"],
        });
        undoToast(
          "审核决定已保存，界面同步暂时失败，正在重试",
          result.undoID,
          "review"
        );
      }
    }
  } catch (error) {
    if (generation === state.workspaceGeneration) {
      toast(error.message || "审核决定保存失败");
    }
  } finally {
    if (generation === state.workspaceGeneration) {
      state.review.mutating = false;
      syncReviewControls();
    }
  }
}

async function deferReviewSelection() {
  const selectedIDs = new Set(state.review.selectedAssetIDs);
  if (state.review.loading
    || state.review.mutating
    || state.review.marquee
    || state.review.loadedScopeKey !== currentReviewScopeKey()
    || !selectedIDs.size
    || !state.review.items.length) return false;
  const workspaceGeneration = state.workspaceGeneration;
  const scopeKey = currentReviewScopeKey();
  const selectedAssetID = state.review.items[state.review.selectedIndex]?.assetID || null;
  const selectedReviewKey = reviewItemKey(state.review.items[state.review.selectedIndex]);
  const advancesByReviewRow = selectedIDs.size === 1
    && selectedAssetID
    && selectedIDs.has(selectedAssetID);
  const selectedIndexes = state.review.items
    .map((item, index) => selectedIDs.has(item.assetID) ? index : -1)
    .filter((index) => index >= 0);
  const lastSelectedIndex = advancesByReviewRow
    ? state.review.selectedIndex
    : (selectedIndexes.length ? Math.max(...selectedIndexes) : -1);
  let nextIndex = state.review.items.findIndex((item, index) => (
    index > lastSelectedIndex
      && (advancesByReviewRow || !selectedIDs.has(item.assetID))
  ));
  let continuationFailed = false;
  if (nextIndex < 0 && state.review.nextCursor) {
    const continuation = loadReviewQueue({
      append: true,
      preserveUnchangedGrid: true,
      throwOnError: true,
      schedulePagination: false,
    });
    const continuationRequestGeneration = state.review.requestGeneration;
    try {
      await continuation;
    } catch {
      continuationFailed = true;
    }
    const selectionUnchanged = state.review.selectedAssetIDs.size === selectedIDs.size
      && [...selectedIDs].every((assetID) => state.review.selectedAssetIDs.has(assetID))
      && reviewItemKey(state.review.items[state.review.selectedIndex]) === selectedReviewKey;
    if (workspaceGeneration !== state.workspaceGeneration
      || scopeKey !== currentReviewScopeKey()
      || continuationRequestGeneration !== state.review.requestGeneration
      || !selectionUnchanged) return false;
    nextIndex = state.review.items.findIndex((item, index) => (
      index > lastSelectedIndex
        && (advancesByReviewRow || !selectedIDs.has(item.assetID))
    ));
  }
  if (nextIndex < 0) {
    if (advancesByReviewRow
      && !continuationFailed
      && !state.review.nextCursor
      && state.review.items.length > 1) {
      nextIndex = 0;
    } else if (!advancesByReviewRow) {
      nextIndex = state.review.items.findIndex(
        (item) => !selectedIDs.has(item.assetID)
      );
    }
  }
  if (nextIndex < 0) {
    if (continuationFailed) {
      toast("下一页载入失败，没有修改标签决定");
    } else if (state.review.nextCursor) {
      toast("下一页暂无新项目，没有修改标签决定");
    } else {
      toast("已到审核队列末尾，没有修改标签决定");
    }
    return false;
  }
  selectReviewIndex(nextIndex);
  reviewCardMainButton(
    elements.reviewGrid.querySelector(`[data-review-index="${nextIndex}"]`)
  )?.focus({ preventScroll: true });
  toast(selectedIDs.size > 1
    ? `已跳过 ${mediaItemCountText(selectedIDs.size)}，没有修改标签决定`
    : "已跳到下一项，没有修改标签决定");
  return true;
}

function lightboxItemsForContext(context = state.lightboxContext) {
  if (context === "review") {
    return state.review.items.map((item) => {
      const detail = state.review.detail?.assetID === item.assetID
        ? state.review.detail
        : null;
      return {
        id: item.assetID,
        reviewKey: reviewItemKey(item),
        fileName: item.fileName,
        contentRevision: detail?.contentRevision ?? item.contentRevision,
        availability: detail?.availability ?? item.availability,
        width: detail?.width ?? item.width,
        height: detail?.height ?? item.height,
      };
    });
  }
  if (context === "slimming") {
    return state.slimming.members;
  }
  if (context === "worldMap") {
    return state.worldMap.selection?.assets || [];
  }
  return state.assets;
}

function lightboxItems() {
  return lightboxItemsForContext();
}

function lightboxItemIndex(
  items,
  context = state.lightboxContext,
  assetID = state.lightboxAssetID,
  reviewKey = state.lightboxReviewKey
) {
  if (context === "review" && reviewKey) {
    const reviewIndex = items.findIndex((item) => item.reviewKey === reviewKey);
    if (reviewIndex >= 0) return reviewIndex;
  }
  return items.findIndex((item) => item.id === assetID);
}

function currentLightboxItem(items = lightboxItems()) {
  const index = lightboxItemIndex(items);
  return index >= 0 ? items[index] : null;
}

function lightboxStandardPreviewPath(item) {
  if (!item?.id) return null;
  const revision = item.contentRevision == null ? "" : `?r=${item.contentRevision}`;
  return `/v1/assets/${item.id}/preview${revision}`;
}

function clearLightboxPreviewPrefetches() {
  clearTimeout(state.lightboxPreviewPrefetchTimer);
  state.lightboxPreviewPrefetchTimer = null;
  for (const entry of state.lightboxPreviewPrefetches.values()) {
    entry.controller.abort();
  }
  state.lightboxPreviewPrefetches.clear();
}

function prefetchLightboxPreview(path) {
  if (!path || state.lightboxPreviewPrefetches.has(path)) return;
  const controller = new AbortController();
  const entry = {
    controller,
    status: "loading",
    promise: null,
  };
  entry.promise = fetchProtectedImageBlob(path, {
    signal: controller.signal,
    priority: "low",
  }).then((blob) => {
    if (state.lightboxPreviewPrefetches.get(path) === entry) {
      entry.status = "ready";
    }
    return blob;
  }).catch(() => {
    if (state.lightboxPreviewPrefetches.get(path) === entry) {
      state.lightboxPreviewPrefetches.delete(path);
    }
    return null;
  });
  state.lightboxPreviewPrefetches.set(path, entry);
}

function prefetchAdjacentLightboxPreviews() {
  if (elements.lightbox.classList.contains("hidden")
    || !state.lightboxAssetID
    || lightboxMediaKind() === "video") {
    clearLightboxPreviewPrefetches();
    return;
  }
  const items = lightboxItems();
  const index = lightboxItemIndex(items);
  if (index < 0) {
    clearLightboxPreviewPrefetches();
    return;
  }
  const desiredPaths = new Set(
    [items[index - 1], items[index + 1]]
      .filter((item) => item?.availability === "available")
      .map(lightboxStandardPreviewPath)
      .filter(Boolean)
  );
  for (const [path, entry] of state.lightboxPreviewPrefetches) {
    if (desiredPaths.has(path)) continue;
    entry.controller.abort();
    state.lightboxPreviewPrefetches.delete(path);
  }
  for (const path of desiredPaths) prefetchLightboxPreview(path);
}

function scheduleAdjacentLightboxPreviewPrefetch() {
  clearTimeout(state.lightboxPreviewPrefetchTimer);
  state.lightboxPreviewPrefetchTimer = setTimeout(() => {
    state.lightboxPreviewPrefetchTimer = null;
    prefetchAdjacentLightboxPreviews();
  }, 80);
}

function lightboxViewportMetrics(overrides = null) {
  if (overrides) return overrides;
  const viewport = elements.lightboxStage.getBoundingClientRect();
  const naturalWidth = elements.lightboxImage.naturalWidth
    || Number(elements.lightboxImage.dataset.width || 0);
  const naturalHeight = elements.lightboxImage.naturalHeight
    || Number(elements.lightboxImage.dataset.height || 0);
  if (viewport.width <= 0 || viewport.height <= 0
    || naturalWidth <= 0 || naturalHeight <= 0) {
    return {
      viewportWidth: Math.max(0, viewport.width),
      viewportHeight: Math.max(0, viewport.height),
      fittedWidth: 0,
      fittedHeight: 0,
    };
  }
  const fitScale = Math.min(viewport.width / naturalWidth, viewport.height / naturalHeight);
  return {
    viewportWidth: viewport.width,
    viewportHeight: viewport.height,
    fittedWidth: naturalWidth * fitScale,
    fittedHeight: naturalHeight * fitScale,
  };
}

function constrainedLightboxOffset(x, y, scale, metrics = lightboxViewportMetrics()) {
  const limitX = Math.max(0, (metrics.fittedWidth * scale - metrics.viewportWidth) / 2);
  const limitY = Math.max(0, (metrics.fittedHeight * scale - metrics.viewportHeight) / 2);
  return {
    x: Math.min(limitX, Math.max(-limitX, Number(x) || 0)),
    y: Math.min(limitY, Math.max(-limitY, Number(y) || 0)),
  };
}

function syncLightboxViewport() {
  const imageMode = Boolean(state.lightboxContext && lightboxMediaKind() !== "video");
  elements.lightboxZoomControls.classList.toggle("hidden", !imageMode);
  elements.lightboxGestureHint.classList.toggle(
    "hidden",
    !imageMode || state.lightboxGestureHintDismissed
  );
  elements.lightboxStage.setAttribute(
    "aria-label",
    imageMode
      ? "照片预览画布；左右滑动切换，双指缩放，放大后拖动"
      : "视频预览画布；使用播放器控制播放"
  );
  if (!imageMode) {
    elements.lightboxImage.style.removeProperty("transform");
    elements.lightboxImage.style.removeProperty("cursor");
    elements.lightboxZoomPercentage.textContent = "100%";
    elements.lightbox.dataset.zoomed = "false";
    elements.lightbox.setAttribute(
      "aria-label",
      state.lightboxContext && lightboxMediaKind() === "video"
        ? "视频全屏预览"
        : "照片全屏预览"
    );
    return;
  }
  const scale = Math.min(
    LIGHTBOX_MAX_SCALE,
    Math.max(LIGHTBOX_MIN_SCALE, Number(state.lightboxViewportScale) || 1)
  );
  const offset = scale <= LIGHTBOX_MIN_SCALE
    ? { x: 0, y: 0 }
    : constrainedLightboxOffset(
      state.lightboxViewportOffsetX,
      state.lightboxViewportOffsetY,
      scale
    );
  state.lightboxViewportScale = scale;
  state.lightboxViewportOffsetX = offset.x;
  state.lightboxViewportOffsetY = offset.y;
  const percentage = Math.round(scale * 100);
  const gestureOffsetX = scale <= LIGHTBOX_MIN_SCALE
    ? state.lightboxGestureSwipeOffsetX
    : 0;
  elements.lightboxImage.style.transform = `translate3d(${offset.x + gestureOffsetX}px, ${offset.y}px, 0) scale(${scale})`;
  elements.lightboxImage.style.cursor = scale > 1
    ? (state.lightboxViewportPointerID == null ? "grab" : "grabbing")
    : "zoom-in";
  elements.lightboxZoomPercentage.textContent = `${percentage}%`;
  elements.lightboxZoomResetButton.setAttribute(
    "aria-label",
    scale > 1 ? `当前缩放 ${percentage}%，恢复适应大小` : "当前为适应大小"
  );
  elements.lightboxZoomOutButton.disabled = scale <= LIGHTBOX_MIN_SCALE;
  elements.lightboxZoomInButton.disabled = scale >= LIGHTBOX_MAX_SCALE;
  elements.lightbox.dataset.zoomed = String(scale > 1);
  elements.lightbox.setAttribute(
    "aria-label",
    `照片全屏预览，当前缩放 ${percentage}%`
  );
}

function resetLightboxViewport(assetID = state.lightboxAssetID) {
  state.lightboxViewportAssetID = assetID || null;
  state.lightboxViewportScale = LIGHTBOX_MIN_SCALE;
  state.lightboxViewportOffsetX = 0;
  state.lightboxViewportOffsetY = 0;
  state.lightboxViewportPointerID = null;
  state.lightboxGesturePointers.clear();
  state.lightboxGestureMode = null;
  state.lightboxGestureSwipeOffsetX = 0;
  state.lightboxGestureDeltaY = 0;
  elements.lightboxStage.classList.remove("dragging");
  syncLightboxViewport();
}

function setLightboxScale(nextScale) {
  if (lightboxMediaKind() === "video") return;
  state.lightboxGestureSwipeOffsetX = 0;
  state.lightboxGestureDeltaY = 0;
  state.lightboxViewportScale = Math.min(
    LIGHTBOX_MAX_SCALE,
    Math.max(LIGHTBOX_MIN_SCALE, Number(nextScale) || LIGHTBOX_MIN_SCALE)
  );
  if (state.lightboxViewportScale <= LIGHTBOX_MIN_SCALE) {
    state.lightboxViewportOffsetX = 0;
    state.lightboxViewportOffsetY = 0;
  }
  syncLightboxViewport();
  scheduleWorkspaceHistoryCheckpoint();
}

function zoomLightboxBy(factor) {
  setLightboxScale(state.lightboxViewportScale * factor);
}

function handleLightboxWheel(event) {
  if (lightboxMediaKind() === "video") return;
  event.preventDefault();
  const limitedDelta = Math.min(500, Math.max(-500, event.deltaY));
  const sensitivity = event.deltaMode === WheelEvent.DOM_DELTA_PIXEL ? 0.002 : 0.08;
  setLightboxScale(state.lightboxViewportScale * Math.exp(-limitedDelta * sensitivity));
}

function captureLightboxPointer(pointerID) {
  try {
    elements.lightboxStage.setPointerCapture?.(pointerID);
  } catch {
    // Synthetic PointerEvents do not always have a browser-owned active pointer.
  }
}

function releaseLightboxPointer(pointerID) {
  try {
    if (elements.lightboxStage.hasPointerCapture?.(pointerID)) {
      elements.lightboxStage.releasePointerCapture(pointerID);
    }
  } catch {
    // The browser may already have released a cancelled pointer.
  }
}

function lightboxGesturePair() {
  return [...state.lightboxGesturePointers.values()].slice(0, 2);
}

function lightboxGestureDistance(first, second) {
  return Math.hypot(second.x - first.x, second.y - first.y);
}

function beginLightboxPinch() {
  const [first, second] = lightboxGesturePair();
  if (!first || !second) return;
  const stage = elements.lightboxStage.getBoundingClientRect();
  state.lightboxGestureMode = "pinch";
  state.lightboxViewportPointerID = null;
  state.lightboxGesturePinchDistance = Math.max(1, lightboxGestureDistance(first, second));
  state.lightboxGesturePinchScale = state.lightboxViewportScale;
  state.lightboxGesturePinchOffsetX = state.lightboxViewportOffsetX;
  state.lightboxGesturePinchOffsetY = state.lightboxViewportOffsetY;
  state.lightboxGesturePinchCenterX = (first.x + second.x) / 2
    - (stage.left + stage.width / 2);
  state.lightboxGesturePinchCenterY = (first.y + second.y) / 2
    - (stage.top + stage.height / 2);
  state.lightboxGestureSwipeOffsetX = 0;
  state.lightboxGestureDeltaY = 0;
}

function rebaseLightboxSinglePointer(pointerID, point) {
  state.lightboxViewportPointerID = pointerID;
  state.lightboxViewportDragStartX = point.x;
  state.lightboxViewportDragStartY = point.y;
  state.lightboxViewportDragOriginX = state.lightboxViewportOffsetX;
  state.lightboxViewportDragOriginY = state.lightboxViewportOffsetY;
  state.lightboxGestureSwipeOffsetX = 0;
  state.lightboxGestureDeltaY = 0;
  state.lightboxGestureStartedAt = performance.now();
  state.lightboxGestureMode = state.lightboxViewportScale > LIGHTBOX_MIN_SCALE
    ? "pan"
    : "swipe";
}

function beginLightboxPan(event) {
  if (lightboxMediaKind() === "video"
    || event.target.closest("button, input, select, textarea, video, a[href]")
    || event.button !== 0) return;
  const touchLike = event.pointerType === "touch" || event.pointerType === "pen";
  if (!touchLike) {
    if (state.lightboxViewportScale <= LIGHTBOX_MIN_SCALE
      || state.lightboxViewportPointerID != null) return;
    event.preventDefault();
    state.lightboxViewportPointerID = event.pointerId;
    state.lightboxViewportDragStartX = event.clientX;
    state.lightboxViewportDragStartY = event.clientY;
    state.lightboxViewportDragOriginX = state.lightboxViewportOffsetX;
    state.lightboxViewportDragOriginY = state.lightboxViewportOffsetY;
    captureLightboxPointer(event.pointerId);
    elements.lightboxStage.classList.add("dragging");
    syncLightboxViewport();
    return;
  }
  event.preventDefault();
  state.lightboxGestureHintDismissed = true;
  elements.lightboxGestureHint.classList.add("hidden");
  state.lightboxGesturePointers.set(event.pointerId, {
    x: event.clientX,
    y: event.clientY,
  });
  captureLightboxPointer(event.pointerId);
  elements.lightboxStage.classList.add("dragging");
  if (state.lightboxGesturePointers.size >= 2) {
    beginLightboxPinch();
  } else {
    rebaseLightboxSinglePointer(event.pointerId, {
      x: event.clientX,
      y: event.clientY,
    });
  }
  syncLightboxViewport();
}

function moveLightboxPan(event) {
  const touchLike = event.pointerType === "touch" || event.pointerType === "pen";
  if (!touchLike) {
    if (event.pointerId !== state.lightboxViewportPointerID) return;
    event.preventDefault();
    const offset = constrainedLightboxOffset(
      state.lightboxViewportDragOriginX + event.clientX - state.lightboxViewportDragStartX,
      state.lightboxViewportDragOriginY + event.clientY - state.lightboxViewportDragStartY,
      state.lightboxViewportScale
    );
    state.lightboxViewportOffsetX = offset.x;
    state.lightboxViewportOffsetY = offset.y;
    syncLightboxViewport();
    return;
  }
  if (!state.lightboxGesturePointers.has(event.pointerId)) return;
  event.preventDefault();
  state.lightboxGesturePointers.set(event.pointerId, {
    x: event.clientX,
    y: event.clientY,
  });
  if (state.lightboxGestureMode === "pinch"
    && state.lightboxGesturePointers.size >= 2) {
    const [first, second] = lightboxGesturePair();
    const stage = elements.lightboxStage.getBoundingClientRect();
    const scale = Math.min(
      LIGHTBOX_MAX_SCALE,
      Math.max(
        LIGHTBOX_MIN_SCALE,
        state.lightboxGesturePinchScale
          * lightboxGestureDistance(first, second)
          / state.lightboxGesturePinchDistance
      )
    );
    const ratio = scale / state.lightboxGesturePinchScale;
    const centerX = (first.x + second.x) / 2 - (stage.left + stage.width / 2);
    const centerY = (first.y + second.y) / 2 - (stage.top + stage.height / 2);
    const offset = constrainedLightboxOffset(
      centerX - (state.lightboxGesturePinchCenterX
        - state.lightboxGesturePinchOffsetX) * ratio,
      centerY - (state.lightboxGesturePinchCenterY
        - state.lightboxGesturePinchOffsetY) * ratio,
      scale
    );
    state.lightboxViewportScale = scale;
    state.lightboxViewportOffsetX = offset.x;
    state.lightboxViewportOffsetY = offset.y;
  } else if (state.lightboxGestureMode === "pan") {
    const offset = constrainedLightboxOffset(
      state.lightboxViewportDragOriginX + event.clientX - state.lightboxViewportDragStartX,
      state.lightboxViewportDragOriginY + event.clientY - state.lightboxViewportDragStartY,
      state.lightboxViewportScale
    );
    state.lightboxViewportOffsetX = offset.x;
    state.lightboxViewportOffsetY = offset.y;
  } else if (state.lightboxGestureMode === "swipe") {
    let offsetX = event.clientX - state.lightboxViewportDragStartX;
    state.lightboxGestureDeltaY = event.clientY - state.lightboxViewportDragStartY;
    const reachesUnavailableEdge = offsetX > 0
      ? elements.lightboxPreviousButton.disabled
      : elements.lightboxNextButton.disabled;
    if (reachesUnavailableEdge) offsetX *= 0.24;
    const stageWidth = Math.max(1, elements.lightboxStage.clientWidth);
    state.lightboxGestureSwipeOffsetX = Math.max(
      -stageWidth * 0.72,
      Math.min(stageWidth * 0.72, offsetX)
    );
  }
  syncLightboxViewport();
}

function endLightboxPan(event) {
  const touchLike = event.pointerType === "touch" || event.pointerType === "pen";
  if (!touchLike) {
    if (event.pointerId !== state.lightboxViewportPointerID) return;
    state.lightboxViewportPointerID = null;
    releaseLightboxPointer(event.pointerId);
    elements.lightboxStage.classList.remove("dragging");
    syncLightboxViewport();
    scheduleWorkspaceHistoryCheckpoint();
    return;
  }
  if (!state.lightboxGesturePointers.has(event.pointerId)) return;
  releaseLightboxPointer(event.pointerId);
  state.lightboxGesturePointers.delete(event.pointerId);
  if (state.lightboxGesturePointers.size === 1) {
    const [pointerID, point] = state.lightboxGesturePointers.entries().next().value;
    rebaseLightboxSinglePointer(pointerID, point);
    syncLightboxViewport();
    return;
  }
  if (state.lightboxGesturePointers.size > 1) {
    beginLightboxPinch();
    return;
  }
  const mode = state.lightboxGestureMode;
  const swipeOffsetX = state.lightboxGestureSwipeOffsetX;
  const deltaY = state.lightboxGestureDeltaY;
  const elapsed = Math.max(1, performance.now() - state.lightboxGestureStartedAt);
  const stageWidth = Math.max(1, elements.lightboxStage.clientWidth);
  const swipeThreshold = elapsed < 350
    ? Math.max(44, stageWidth * 0.12)
    : Math.max(56, stageWidth * 0.18);
  const direction = swipeOffsetX < 0 ? 1 : -1;
  const targetUnavailable = direction > 0
    ? elements.lightboxNextButton.disabled
    : elements.lightboxPreviousButton.disabled;
  const commitsSwipe = event.type !== "pointercancel"
    && mode === "swipe"
    && Math.abs(swipeOffsetX) >= swipeThreshold
    && Math.abs(swipeOffsetX) > Math.abs(deltaY) * 1.25
    && !targetUnavailable;
  state.lightboxViewportPointerID = null;
  state.lightboxGestureMode = null;
  state.lightboxGestureSwipeOffsetX = 0;
  state.lightboxGestureDeltaY = 0;
  elements.lightboxStage.classList.remove("dragging");
  syncLightboxViewport();
  if (commitsSwipe) {
    void navigateLightbox(direction);
  } else if (mode === "pan" || mode === "pinch") {
    scheduleWorkspaceHistoryCheckpoint();
  }
}

function lightboxMediaKind() {
  if (state.lightboxContext === "slimming") return state.slimming.mediaKind;
  if (state.lightboxContext === "worldMap") return "image";
  return state.mediaKind;
}

function lightboxHasMoreItems() {
  if (state.lightboxContext === "library") return Boolean(state.nextCursor);
  if (state.lightboxContext === "review") return Boolean(state.review.nextCursor);
  return false;
}

function lightboxBackText() {
  return {
    library: "返回网格",
    review: "返回审核",
    slimming: "返回分析",
    worldMap: "返回地图",
  }[state.lightboxContext] || "返回";
}

async function renderLightboxMedia(item) {
  const mediaKind = lightboxMediaKind();
  if (mediaKind !== "video") {
    stopLightboxVideo();
    const recoveringReviewCloudPreview = state.lightboxContext === "review"
      && state.review.cloudPreview.assetID === item.id
      && state.review.cloudPreview.status !== "hidden";
    const recoveringSharedCloudPreview = state.lightboxContext !== "review"
      && state.cloudPreview.assetID === item.id
      && state.cloudPreview.status !== "hidden";
    if (recoveringReviewCloudPreview || recoveringSharedCloudPreview) {
      clearProtectedImageSource(elements.lightboxImage);
      elements.lightboxImage.classList.add("hidden");
      renderCloudPreviewRecovery();
      renderReviewCloudPreviewRecovery();
      return;
    }
    elements.lightboxImage.classList.remove("hidden");
    if (item.width) elements.lightboxImage.dataset.width = String(item.width);
    else delete elements.lightboxImage.dataset.width;
    if (item.height) elements.lightboxImage.dataset.height = String(item.height);
    else delete elements.lightboxImage.dataset.height;
    const revision = item.contentRevision == null ? "" : `?r=${item.contentRevision}`;
    const original = state.lightboxOriginalAssetID === item.id;
    setProtectedImageSource(
      elements.lightboxImage,
      `/v1/assets/${item.id}/${original ? "original" : "preview"}${revision}`,
      { priority: "high", forceFetch: true, preserveCurrent: true }
    );
    syncLightboxViewport();
    return;
  }

  clearLightboxPreviewPrefetches();
  const requestGeneration = ++state.lightboxRequestGeneration;
  clearProtectedImageSource(elements.lightboxImage);
  elements.lightboxImage.classList.add("hidden");
  elements.lightboxVideo.pause();
  elements.lightboxVideo.removeAttribute("src");
  const poster = assetThumbnailPlaceholder(item.id);
  if (poster) elements.lightboxVideo.poster = poster;
  else elements.lightboxVideo.removeAttribute("poster");
  elements.lightboxVideo.dataset.assetId = item.id;
  elements.lightboxVideo.dataset.contentRevision = String(item.contentRevision ?? "");
  if (state.authMode === "account") {
    const workerReady = await updateMediaWorkerAuthorization(state.accountAuthorization);
    if (!workerReady
      || requestGeneration !== state.lightboxRequestGeneration
      || state.lightboxAssetID !== item.id) {
      if (requestGeneration === state.lightboxRequestGeneration
        && state.lightboxAssetID === item.id) {
        toast("当前浏览器无法建立视频播放通道");
      }
      return;
    }
  }
  if (requestGeneration !== state.lightboxRequestGeneration
    || state.lightboxAssetID !== item.id) return;
  const revision = item.contentRevision == null ? "" : `?r=${item.contentRevision}`;
  elements.lightboxVideo.src = `/v1/assets/${item.id}/media${revision}`;
  elements.lightboxVideo.classList.remove("hidden");
  elements.lightboxVideo.load();
}

function openLightbox(context, assetID, {
  original = false,
  preserveSelection = false,
  returnFocus = null,
  reviewKey = null,
} = {}) {
  if (!assetID) return;
  stopAssetHoverVideo();
  const wasHidden = elements.lightbox.classList.contains("hidden");
  if (wasHidden) {
    clearLightboxPreviewPrefetches();
    state.lightboxReturnFocus = returnFocus instanceof HTMLElement
      && document.contains(returnFocus)
      ? returnFocus
      : document.activeElement;
  }
  const currentReviewItem = state.review.items[state.review.selectedIndex];
  const reviewItem = context === "review"
    ? (state.review.items.find((item) => reviewItemKey(item) === reviewKey)
      || (currentReviewItem?.assetID === assetID ? currentReviewItem : null)
      || state.review.items.find((item) => item.assetID === assetID))
    : null;
  state.lightboxContext = context;
  state.lightboxAssetID = reviewItem?.assetID || assetID;
  state.lightboxReviewKey = reviewItem ? reviewItemKey(reviewItem) : null;
  state.lightboxPreservesSelection = Boolean(preserveSelection);
  state.lightboxOriginalAssetID = original ? assetID : null;
  state.lightboxOriginalLoading = original;
  if (context === "review") {
    elements.reviewWorkspace.inert = true;
  } else if (context === "slimming") {
    elements.slimmingWorkspace.inert = true;
    if (slimmingWorkspaceUsesIntegratedLayout()) elements.appView.inert = true;
  } else if (context === "worldMap") {
    elements.worldMapWorkspace.inert = true;
    if (worldMapUsesIntegratedLayout()) elements.appView.inert = true;
  }
  elements.lightbox.classList.remove("hidden");
  if (context === "review") {
    syncLightboxWorkspaceFrame();
    syncReviewPresentation({ renderSurfaces: false });
  }
  if (context === "library") syncLightboxWorkspaceFrame();
  renderLightbox();
  if (wasHidden
    && state.workspaceNavigation.initialized
    && !state.workspaceNavigation.applyingHistory
    && !state.workspaceNavigation.pendingRestoreEntry) {
    const route = visibleWorkspaceRoute();
    recordWorkspaceHistory(
      route,
      currentWorkspaceHistoryContext(route),
      "pushLightbox"
    );
  } else {
    scheduleWorkspaceHistoryCheckpoint();
  }
  requestAnimationFrame(() => {
    elements.lightboxBackButton.focus({ preventScroll: true });
  });
}

function restoreLightboxFromHistory(raw, expectedContext) {
  const context = normalizedLightboxHistoryContext(raw);
  const items = lightboxItemsForContext(expectedContext);
  const historyIndex = context
    ? lightboxItemIndex(
      items,
      expectedContext,
      context.assetID,
      context.reviewKey
    )
    : -1;
  if (!context || historyIndex < 0) return false;

  openLightbox(expectedContext, context.assetID, {
    original: context.original,
    preserveSelection: context.preserveSelection,
    reviewKey: expectedContext === "review"
      ? items[historyIndex].reviewKey
      : null,
  });
  if (expectedContext === "library") {
    state.lightboxReturnFocus = assetCardMainButton(elements.assetGrid.querySelector(
      `[data-asset-id="${CSS.escape(context.assetID)}"]`
    ));
  } else if (expectedContext === "review") {
    state.lightboxReturnFocus = reviewCardMainButton(elements.reviewGrid.querySelector(
      `[data-review-index="${historyIndex}"]`
    ));
  } else if (expectedContext === "slimming") {
    state.lightboxReturnFocus = slimmingMemberMainButton(
      elements.slimmingMemberGrid.querySelector(
        `[data-slimming-member-id="${CSS.escape(context.assetID)}"]`
      )
    );
  } else if (expectedContext === "worldMap") {
    state.lightboxReturnFocus = elements.worldMapPhotoStrip.querySelector(
      `[data-world-map-asset-id="${CSS.escape(context.assetID)}"]`
    );
  }
  const remainsCurrent = () => state.lightboxContext === expectedContext
    && state.lightboxAssetID === context.assetID
    && (expectedContext !== "review"
      || !context.reviewKey
      || state.lightboxReviewKey === context.reviewKey)
    && !elements.lightbox.classList.contains("hidden");
  if (lightboxMediaKind() === "video") {
    const restoreVideoTime = () => {
      if (!remainsCurrent()) return;
      const duration = Number(elements.lightboxVideo.duration);
      const maximum = Number.isFinite(duration) && duration > 0 ? duration : context.videoTime;
      try {
        elements.lightboxVideo.currentTime = Math.min(context.videoTime, maximum);
      } catch {
        // Some browsers reject seeking until metadata is ready; loadedmetadata retries it.
      }
      elements.lightboxVideo.pause();
    };
    elements.lightboxVideo.addEventListener("loadedmetadata", restoreVideoTime, { once: true });
    if (elements.lightboxVideo.readyState >= HTMLMediaElement.HAVE_METADATA) {
      requestAnimationFrame(restoreVideoTime);
    }
    return true;
  }

  state.lightboxViewportAssetID = context.assetID;
  state.lightboxViewportScale = context.scale;
  state.lightboxViewportOffsetX = context.offsetX;
  state.lightboxViewportOffsetY = context.offsetY;
  syncLightboxViewport();
  let restored = false;
  const removeImageViewportListeners = () => {
    elements.lightboxImage.removeEventListener("load", restoreImageViewport);
    elements.lightboxImage.removeEventListener(
      "imageall-protected-load",
      restoreImageViewport
    );
  };
  const restoreImageViewport = () => {
    if (restored) return;
    if (!remainsCurrent()) {
      removeImageViewportListeners();
      return;
    }
    if (elements.lightboxImage.naturalWidth <= 0) return;
    restored = true;
    removeImageViewportListeners();
    state.lightboxViewportAssetID = context.assetID;
    state.lightboxViewportScale = context.scale;
    state.lightboxViewportOffsetX = context.offsetX;
    state.lightboxViewportOffsetY = context.offsetY;
    syncLightboxViewport();
  };
  elements.lightboxImage.addEventListener("load", restoreImageViewport);
  elements.lightboxImage.addEventListener(
    "imageall-protected-load",
    restoreImageViewport
  );
  requestAnimationFrame(restoreImageViewport);
  return true;
}

function reconcileLightboxFromWorkspaceHistory(route, context) {
  const expectedContext = workspaceLightboxContext(route);
  const raw = workspaceLightboxHistoryContext(route, context);
  const desired = normalizedLightboxHistoryContext(raw);
  const valid = expectedContext && desired && lightboxItemIndex(
    lightboxItemsForContext(expectedContext),
    expectedContext,
    desired.assetID,
    desired.reviewKey
  ) >= 0;
  if (!valid) {
    if (!elements.lightbox.classList.contains("hidden")) closeLightbox();
    return;
  }

  const alreadyOpen = !elements.lightbox.classList.contains("hidden")
    && state.lightboxContext === expectedContext
    && state.lightboxAssetID === desired.assetID
    && (expectedContext !== "review"
      || !desired.reviewKey
      || state.lightboxReviewKey === desired.reviewKey)
    && Boolean(state.lightboxOriginalAssetID === desired.assetID) === desired.original;
  if (alreadyOpen) return;
  if (!elements.lightbox.classList.contains("hidden")) {
    closeLightbox({ restoreFocus: false });
  }
  restoreLightboxFromHistory(raw, expectedContext);
}

function reconcileGalleryInspectorFromWorkspaceHistory(
  route,
  navigationLevel,
  { focus = true, restoreFocusOnClose = true } = {}
) {
  if (route !== "gallery") return;
  const shouldOpen = !galleryOverviewLayoutQuery.matches && (
    navigationLevel === "inspector"
      || (galleryInspectorHasContent() && navigationLevel === "lightbox")
  );
  if (shouldOpen) {
    state.inspectorDismissed = false;
    state.inspectorDismissedByUser = false;
    elements.inspector.classList.add("open");
    renderInspectorVisibilityControl();
    if (focus && navigationLevel === "inspector") {
      requestAnimationFrame(() => {
        elements.closeInspectorButton.focus({ preventScroll: true });
      });
    }
  } else if (elements.lightbox.classList.contains("hidden")
    && elements.inspector.classList.contains("open")) {
    closeInspectorOverlay({
      restoreFocus: restoreFocusOnClose,
      markDismissed: false,
    });
  }
}

function syncLightboxOpenOriginalControl(item) {
  const isVideo = lightboxMediaKind() === "video";
  elements.lightboxOpenOriginalButton.classList.remove("hidden");
  const fileName = item?.fileName || (isVideo ? "当前视频" : "当前照片");
  const label = state.openingOriginal ? "正在打开…" : (isVideo ? "Mac 播放" : "Mac 预览");
  const description = state.openingOriginal
    ? `正在 Mac 上打开${fileName}`
    : (isVideo
      ? `在 Mac 上用系统播放器打开${fileName}`
      : `在 Mac 上用“预览”打开原图${fileName}`);
  elements.lightboxOpenOriginalButtonIcon.textContent = isVideo ? "▶" : "↗";
  elements.lightboxOpenOriginalButtonLabel.textContent = label;
  elements.lightboxOpenOriginalButton.disabled = !state.online
    || item?.availability !== "available"
    || state.openingOriginal
    || state.lightboxNavigating;
  elements.lightboxOpenOriginalButton.classList.toggle("busy", state.openingOriginal);
  elements.lightboxOpenOriginalButton.title = description;
  elements.lightboxOpenOriginalButton.setAttribute("aria-label", description);
}

function syncLightboxViewOriginalControl(item) {
  const isVideo = lightboxMediaKind() === "video";
  const isOriginal = !isVideo && state.lightboxOriginalAssetID === item?.id;
  elements.lightbox.classList.toggle("image-preview", !isVideo);
  elements.lightboxViewOriginalButton.classList.toggle("hidden", isVideo);
  elements.lightboxViewOriginalButton.setAttribute("aria-pressed", String(isOriginal));
  elements.lightboxViewOriginalButtonIcon.textContent = isOriginal ? "▧" : "⌕";
  elements.lightboxViewOriginalButtonLabel.textContent = isOriginal ? "标准预览" : "查看原图";
  const fileName = item?.fileName || "当前照片";
  const description = isOriginal
    ? `切回${fileName}的标准网页预览`
    : `在网页中读取并查看${fileName}的本地原图`;
  elements.lightboxViewOriginalButton.title = state.lightboxOriginalLoading
    ? `正在读取${fileName}的原图`
    : description;
  elements.lightboxViewOriginalButton.setAttribute("aria-label", description);
  elements.lightboxViewOriginalButton.disabled = isVideo
    || !state.online
    || item?.availability !== "available"
    || state.lightboxNavigating;
  elements.lightboxViewOriginalButton.classList.toggle(
    "busy",
    isOriginal && state.lightboxOriginalLoading
  );
}

function toggleLightboxOriginalView() {
  const item = currentLightboxItem();
  if (!item || lightboxMediaKind() === "video" || item.availability !== "available") return;
  const isOriginal = state.lightboxOriginalAssetID === item.id;
  state.lightboxOriginalAssetID = isOriginal ? null : item.id;
  state.lightboxOriginalLoading = !isOriginal;
  void renderLightboxMedia(item);
  syncLightboxViewOriginalControl(item);
  scheduleWorkspaceHistoryCheckpoint();
}

function renderLightbox() {
  const items = lightboxItems();
  const index = lightboxItemIndex(items);
  if (index < 0) {
    closeLightbox();
    return;
  }
  const item = items[index];
  if (state.lightboxContext === "review") {
    state.lightboxReviewKey = item.reviewKey;
    state.lightboxReturnFocus = reviewCardFocusTarget(item.reviewKey)
      || state.lightboxReturnFocus;
  }
  if (state.lightboxViewportAssetID !== item.id) resetLightboxViewport(item.id);
  const noun = lightboxMediaKind() === "video" ? "视频" : "照片";
  const hasMore = lightboxHasMoreItems();
  elements.lightboxTitle.textContent = item.fileName || `未命名${noun}`;
  elements.lightboxImage.alt = item.fileName || `${noun}全屏预览`;
  void renderLightboxMedia(item);
  elements.lightboxBackLabel.textContent = lightboxBackText();
  elements.lightboxBackButton.setAttribute("aria-label", lightboxBackText());
  elements.lightboxPosition.textContent = `${index + 1} / ${items.length}${hasMore ? " · 还有更多" : ""}`;
  elements.lightboxPreviousButton.disabled = state.lightboxNavigating || index <= 0;
  elements.lightboxNextButton.disabled = state.lightboxNavigating
    || (index >= items.length - 1 && !hasMore);
  elements.lightbox.setAttribute("aria-busy", String(state.lightboxNavigating));
  elements.lightboxReviewActions.classList.toggle(
    "hidden",
    state.lightboxContext !== "review"
  );
  elements.lightbox.classList.toggle("reviewing", state.lightboxContext === "review");
  const showsDelete = ["library", "review", "slimming"].includes(
    state.lightboxContext
  );
  elements.lightboxDeleteButton.classList.toggle("hidden", !showsDelete);
  elements.lightboxDeleteButton.disabled = !state.online
    || state.lightboxNavigating
    || !favoriteStateForAssetID(item.id)
    || assetIsDeletionProtected(item.id)
    || (state.lightboxContext === "slimming"
      ? state.slimming.removal.submitting || Boolean(activeSlimmingRemovalPhase(item.id))
      : !supportsLibrarySlimming()
        || state.galleryRemoval.submitting
        || Boolean(activeGalleryRemovalRequest()));
  elements.lightboxDeleteButton.setAttribute(
    "aria-label",
    assetIsDeletionProtected(item.id)
      ? `当前预览${noun}有红心保护；请先取消红心再删除`
      : `处理当前预览${noun}：${item.fileName || `未命名${noun}`}`
  );
  syncLightboxViewOriginalControl(item);
  syncLightboxOpenOriginalControl(item);
  renderLightboxFavorite();
  if (!favoriteStateForAssetID(item.id)) void loadLightboxFavorite(item.id);
  renderCloudPreviewRecovery();
  renderReviewCloudPreviewRecovery();
  syncReviewControls();
}

function syncReviewLightboxSelection() {
  if (state.lightboxContext !== "review") return;
  const item = state.review.items[state.review.selectedIndex];
  if (!item) {
    closeLightbox();
    return;
  }
  if (state.lightboxAssetID !== item.assetID) {
    state.lightboxOriginalAssetID = null;
    state.lightboxOriginalLoading = false;
  }
  state.lightboxAssetID = item.assetID;
  state.lightboxReviewKey = reviewItemKey(item);
  renderLightbox();
  scheduleWorkspaceHistoryCheckpoint();
}

async function applyLightboxReviewDecision(action) {
  if (state.lightboxContext !== "review") return;
  state.lightboxPreservesSelection = false;
  let currentIndex = state.lightboxReviewKey
    ? state.review.items.findIndex(
      (item) => reviewItemKey(item) === state.lightboxReviewKey
    )
    : -1;
  if (currentIndex < 0) {
    currentIndex = state.review.items.findIndex(
      (item) => item.assetID === state.lightboxAssetID
    );
  }
  if (currentIndex >= 0 && currentIndex !== state.review.selectedIndex) {
    selectReviewIndex(currentIndex);
  }
  if (action === "defer") {
    if (await deferReviewSelection()) syncReviewLightboxSelection();
    return;
  }
  await applyReviewDecision(action);
  syncReviewLightboxSelection();
}

async function loadMoreLightboxItems() {
  if (state.lightboxContext === "library" && state.nextCursor) {
    await loadAssets({ append: true, preserveSelection: true });
    return;
  }
  if (state.lightboxContext === "review" && state.review.nextCursor) {
    await loadReviewQueue({ append: true, preserveUnchangedGrid: true });
  }
}

async function syncLibraryLightboxSelection(assetID) {
  state.selectedAssetID = assetID;
  state.selectedDetail = null;
  if (state.selectionMode) {
    state.selectedAssetIDs = new Set([assetID]);
    state.selectionAnchorID = assetID;
  }
  renderAssetSelectionState();
  if (state.selectionMode) renderSelectionMutation();
  else renderSelectionBar();
  const card = elements.assetGrid.querySelector(`[data-asset-id="${CSS.escape(assetID)}"]`);
  card?.scrollIntoView({ block: "nearest", inline: "nearest" });
  if (card) state.lightboxReturnFocus = assetCardMainButton(card);
  if (state.selectionMode) {
    scheduleSelectionAggregate();
    return;
  }
  await loadInspector(assetID, { preserveExisting: false, quiet: true });
}

function lightboxNavigationFocusTarget(preferredButton) {
  const available = (button) => button instanceof HTMLButtonElement
    && !button.disabled
    && !button.classList.contains("hidden")
    && button.getClientRects().length > 0;
  if (available(preferredButton)) return preferredButton;
  const alternate = preferredButton === elements.lightboxNextButton
    ? elements.lightboxPreviousButton
    : elements.lightboxNextButton;
  if (available(alternate)) return alternate;
  return elements.lightboxBackButton;
}

async function navigateLightbox(direction) {
  if (![-1, 1].includes(direction)) return;
  if (state.lightboxNavigating) {
    state.lightboxPendingDirection = direction;
    return;
  }
  const focusedNavigationButton = [
    elements.lightboxPreviousButton,
    elements.lightboxNextButton,
  ].includes(document.activeElement)
    ? document.activeElement
    : null;
  const currentAssetID = state.lightboxAssetID;
  const currentReviewKey = state.lightboxReviewKey;
  let items = lightboxItems();
  let index = lightboxItemIndex(items);
  if (index < 0) return;
  let next = index + direction;
  state.lightboxNavigating = true;
  renderLightbox();
  try {
    if (direction > 0 && next >= items.length && lightboxHasMoreItems()) {
      await loadMoreLightboxItems();
      if (state.lightboxAssetID !== currentAssetID
        || state.lightboxReviewKey !== currentReviewKey) return;
      items = lightboxItems();
      index = lightboxItemIndex(
        items,
        state.lightboxContext,
        currentAssetID,
        currentReviewKey
      );
      next = index + direction;
    }
    if (next < 0 || next >= items.length) return;
    const nextItem = items[next];
    const nextAssetID = nextItem.id;
    if (state.lightboxContext !== "review"
      && state.cloudPreview.status !== "hidden"
      && state.cloudPreview.assetID === currentAssetID) {
      resetCloudPreviewRecovery();
    }
    state.lightboxAssetID = nextAssetID;
    state.lightboxReviewKey = state.lightboxContext === "review"
      ? nextItem.reviewKey
      : null;
    state.lightboxOriginalAssetID = null;
    state.lightboxOriginalLoading = false;
    renderLightbox();
    checkpointActiveWorkspaceHistory();
    if (state.lightboxContext === "review" && !state.lightboxPreservesSelection) {
      selectReviewIndex(next);
    } else if (state.lightboxContext === "library" && !state.lightboxPreservesSelection) {
      await syncLibraryLightboxSelection(nextAssetID);
    }
  } catch (error) {
    toast(error.message || "无法载入下一页");
  } finally {
    state.lightboxNavigating = false;
    const pendingDirection = state.lightboxPendingDirection;
    state.lightboxPendingDirection = 0;
    if (!elements.lightbox.classList.contains("hidden") && state.lightboxAssetID) {
      renderLightbox();
      if (pendingDirection) {
        void navigateLightbox(pendingDirection);
      } else if (focusedNavigationButton) {
        restoreOverlayFocus(lightboxNavigationFocusTarget(focusedNavigationButton));
      }
    }
  }
}

function navigateLibrarySelection(direction) {
  const index = state.assets.findIndex((asset) => asset.id === state.selectedAssetID);
  const next = index + direction;
  if (index < 0 || next < 0 || next >= state.assets.length) return;
  selectLibraryAssetByIndex(next);
}

function renderedGridColumnCount(container, cardSelector) {
  const cards = [...container.querySelectorAll(cardSelector)];
  if (!cards.length) return 1;
  const firstTop = cards[0].offsetTop;
  const count = cards.findIndex((card) => Math.abs(card.offsetTop - firstTop) > 1);
  return count < 0 ? cards.length : Math.max(1, count);
}

function renderedGridPageItemCount(scrollContainer, grid, cardSelector) {
  const columns = renderedGridColumnCount(grid, cardSelector);
  const card = grid.querySelector(cardSelector);
  if (!card) return columns;
  const rowGap = Number.parseFloat(getComputedStyle(grid).rowGap) || 0;
  const rowHeight = Math.max(1, card.getBoundingClientRect().height + rowGap);
  const rows = Math.max(1, Math.floor(scrollContainer.clientHeight / rowHeight));
  return rows * columns;
}

function gridColumnCount() {
  return renderedGridColumnCount(elements.assetGrid, ":scope > .asset-card");
}

function visibleGridPageItemCount() {
  return renderedGridPageItemCount(
    elements.libraryScroll,
    elements.assetGrid,
    ":scope > .asset-card"
  );
}

async function selectLibraryAssetByIndex(
  index,
  { focusGrid = false, extendRange = false } = {}
) {
  if (!state.assets.length) return;
  const bounded = Math.max(0, Math.min(index, state.assets.length - 1));
  const assetID = state.assets[bounded].id;
  if (state.selectionMode) {
    if (extendRange) {
      const candidateAnchorID = state.selectionAnchorID || state.selectedAssetID;
      const candidateAnchorIndex = state.assets.findIndex(
        (asset) => asset.id === candidateAnchorID
      );
      const anchorIndex = candidateAnchorIndex >= 0 ? candidateAnchorIndex : bounded;
      const anchorID = state.assets[anchorIndex].id;
      const next = new Set();
      for (
        let candidate = Math.min(anchorIndex, bounded);
        candidate <= Math.max(anchorIndex, bounded);
        candidate += 1
      ) {
        next.add(state.assets[candidate].id);
      }
      state.selectedAssetIDs = next;
      state.selectionAnchorID = anchorID;
    } else {
      state.selectedAssetIDs = new Set([assetID]);
      state.selectionAnchorID = assetID;
    }
    state.selectedAssetID = assetID;
    renderAssetSelectionState();
    renderSelectionMutation();
    scheduleSelectionAggregate();
  } else {
    state.selectedAssetID = assetID;
    state.selectedDetail = null;
    renderAssetSelectionState();
    renderInspectorSurface();
  }
  const card = elements.assetGrid.querySelector(`[data-asset-id="${assetID}"]`);
  card?.scrollIntoView({ block: "nearest", inline: "nearest" });
  if (focusGrid) assetCardMainButton(card)?.focus({ preventScroll: true });
  if (!state.selectionMode) {
    await loadInspector(assetID, {
      reveal: true,
      focusInspector: !focusGrid,
    });
  }
}

function moveLibrarySelection(key, { extendRange = false } = {}) {
  if (!state.assets.length) return;
  const primaryID = state.selectionMode
    ? (
      state.selectedAssetID && state.selectedAssetIDs.has(state.selectedAssetID)
        ? state.selectedAssetID
        : (state.selectionAnchorID || [...state.selectedAssetIDs][0])
    )
    : state.selectedAssetID;
  const index = state.assets.findIndex((asset) => asset.id === primaryID);
  if (index < 0) {
    selectLibraryAssetByIndex(0, { focusGrid: true });
    return;
  }
  let nextIndex;
  if (key === "Home") {
    nextIndex = 0;
  } else if (key === "End") {
    nextIndex = state.assets.length - 1;
  } else {
    const columns = gridColumnCount();
    const delta = {
      ArrowLeft: -1,
      ArrowRight: 1,
      ArrowUp: -columns,
      ArrowDown: columns,
      PageUp: -visibleGridPageItemCount(),
      PageDown: visibleGridPageItemCount(),
    }[key];
    if (!delta) return;
    nextIndex = index + delta;
  }
  selectLibraryAssetByIndex(nextIndex, { focusGrid: true, extendRange });
}

async function loadWorkspace({ restoreHistory = false } = {}) {
  resetWorkspaceSessionState();
  const generation = state.workspaceGeneration;
  showApp({ restoreHistory });
  const restoreEntry = state.workspaceNavigation.pendingRestoreEntry;
  const restoreGalleryNavigationLevel = restoreEntry?.route === "gallery"
    ? (restoreEntry.navigationLevel || "workspace")
    : "workspace";
  const restoreGalleryUnderlyingLevel = workspaceNavigationBaseLevel(
    restoreGalleryNavigationLevel,
    restoreEntry?.context || {}
  );
  const restoreGalleryBaseLevel = galleryInspectorHistoryLevel(
    restoreGalleryNavigationLevel,
    restoreEntry?.context || {}
  );
  const restoresGalleryInspector = restoreEntry?.route === "gallery"
    && ["inspector", "lightbox"].includes(restoreGalleryBaseLevel);
  const galleryRestoreSource = restoreEntry?.route === "gallery"
    ? restoreEntry.context
    : restoreEntry?.context?.galleryContext;
  let galleryRestore = galleryRestoreSource
    ? applyGalleryHistoryContext(galleryRestoreSource)
    : null;
  setConnection(true, "正在同步");
  const capabilities = await api("/v1/capabilities");
  if (generation !== state.workspaceGeneration) return;
  state.capabilities = capabilities;
  const [
    sources,
    tags,
    tagGroups,
    jobs,
    sourceManagement,
    embeddingPreparation,
    sampleSuggestions,
    tagLibrarySuggestions,
    trainingActivities,
    librarySuggestions,
    workspaceNotice,
  ] = await Promise.all([
    api("/v1/sources"),
    api("/v1/tags"),
    api("/v1/tag-groups"),
    api("/v1/jobs"),
    supportsSourceManagement() ? api("/v1/source-management") : Promise.resolve(null),
    api(`/v1/embedding-preparation?${new URLSearchParams({ mediaKind: state.mediaKind })}`),
    api(`/v1/sample-suggestions?${new URLSearchParams({ mediaKind: state.mediaKind })}`),
    api(`/v1/tag-library-suggestions?${new URLSearchParams({ mediaKind: state.mediaKind })}`),
    supportsTrainingActivities()
      ? api(`/v1/training/activities?${new URLSearchParams({ mediaKind: state.mediaKind })}`)
      : Promise.resolve([]),
    supportsLibrarySuggestions()
      ? api(`/v1/library-suggestions?${new URLSearchParams({ mediaKind: state.mediaKind })}`)
      : Promise.resolve(null),
    supportsWorkspaceNotices()
      ? api("/v1/workspace-notice").catch(() => null)
      : Promise.resolve(null),
  ]);
  if (generation !== state.workspaceGeneration) return;
  state.sources = sources;
  state.tags = tags;
  state.tagGroups = tagGroups;
  state.jobs = jobs;
  state.sourceManagement.snapshot = sourceManagement || {
    sources,
    canConnectPhotos: !sources.some((source) => source.kind === "photos"),
    requests: [],
  };
  state.embeddingPreparation.isAvailable = Boolean(embeddingPreparation.isAvailable);
  state.embeddingPreparation.activities = embeddingPreparation.activities || [];
  state.sampleSuggestions.isAvailable = Boolean(sampleSuggestions.isAvailable);
  state.sampleSuggestions.maximumSampleCount = sampleSuggestions.maximumSampleCount || 500;
  state.sampleSuggestions.activities = sampleSuggestions.activities || [];
  state.tagLibrarySuggestions.snapshot = tagLibrarySuggestions;
  state.personalModelActivities.mediaKind = state.mediaKind;
  state.personalModelActivities.items = Array.isArray(trainingActivities)
    ? trainingActivities
    : [];
  state.librarySuggestions.snapshot = librarySuggestions;
  state.workspaceNotice.notice = workspaceNotice?.notice || null;
  state.workspaceNotice.dismissing = false;
  state.workspaceNotice.activeActionID = null;
  state.workspaceNotice.pendingReturnActionID = null;
  if (galleryRestore) {
    galleryRestore = applyGalleryHistoryContext(
      galleryRestoreSource,
      { validateCatalog: true }
    );
    if (restoreEntry?.route === "gallery" && !galleryOverviewLayoutQuery.matches) {
      state.inspectorDismissed = !restoresGalleryInspector;
    }
  }
  const restoredFolderAncestorBranches = galleryRestore?.folderScope
    ? expandFolderScopeAncestors(
      galleryRestore.folderScope.sourceID,
      galleryRestore.folderScope.relativePath
    )
    : [];
  renderWorkspaceNotice();
  elements.hostVersion.textContent = `Mac Host ${capabilities.hostAppVersion}`;
  elements.settingsButton.disabled = !supportsGeneralSettings();
  elements.settingsButton.title = supportsGeneralSettings()
    ? "设置（⌘,）"
    : "当前 Mac Host 不支持网页通用设置";
  if (supportsGeneralSettings()) await loadGeneralSettings({ quiet: true });
  if (generation !== state.workspaceGeneration) return;
  renderSources();
  if (galleryRestore?.folderScope) {
    loadFolderScopeAncestorBranches(
      galleryRestore.folderScope.sourceID,
      restoredFolderAncestorBranches
    );
  }
  renderReviewSourceFilter();
  renderTagSelects();
  renderJobs();
  renderSourcePrewarmStatus();
  renderMediaKindTabs();
  syncSelectionModeControls();
  renderLayoutPreferences();
  syncFilterControlsFromState();
  updateLibraryTitle();
  await loadAssets({
    preserveSelection: Boolean(galleryRestore),
    targetLoadedCount: galleryRestore?.loadedCount || null,
  });
  if (generation !== state.workspaceGeneration) return;
  if (galleryRestore) {
    if (!state.selectionMode && state.selectedAssetID) {
      await loadInspector(state.selectedAssetID, {
        reveal: galleryOverviewLayoutQuery.matches || restoresGalleryInspector,
        quiet: true,
      });
    } else if (state.selectionMode && state.selectedAssetIDs.size) {
      scheduleSelectionAggregate();
    }
    await waitForWorkspaceLayout();
    elements.libraryScroll.scrollTop = Math.min(
      galleryRestore.scrollTop,
      Math.max(0, elements.libraryScroll.scrollHeight - elements.libraryScroll.clientHeight)
    );
    restoreLightboxFromHistory(galleryRestore.lightbox, "library");
    reconcileGalleryInspectorFromWorkspaceHistory(
      "gallery",
      restoreGalleryBaseLevel
    );
    reconcileMobileSidebarFromWorkspaceHistory(
      "gallery",
      restoreGalleryUnderlyingLevel,
      restoreEntry?.context || {}
    );
    reconcileCompactToolbarMenuFromWorkspaceHistory(
      "gallery",
      restoreGalleryNavigationLevel,
      restoreEntry?.context || {}
    );
    reconcileJobsPopoverFromWorkspaceHistory(
      "gallery",
      restoreGalleryNavigationLevel,
      restoreEntry?.context || {}
    );
    reconcileFilterPopoverFromWorkspaceHistory(
      "gallery",
      restoreGalleryNavigationLevel,
      restoreEntry?.context || {}
    );
    reconcileLayoutMenuFromWorkspaceHistory(
      "gallery",
      restoreGalleryNavigationLevel,
      restoreEntry?.context || {}
    );
    reconcileActionMenuFromWorkspaceHistory(
      "gallery",
      restoreGalleryNavigationLevel,
      restoreEntry?.context || {}
    );
    reconcileContextMenuFromWorkspaceHistory(
      "gallery",
      restoreGalleryNavigationLevel,
      restoreEntry?.context || {}
    );
    await reconcileCommandPaletteFromWorkspaceHistory(
      "gallery",
      restoreGalleryNavigationLevel,
      restoreEntry?.context || {}
    );
    reconcileKeyboardShortcutsFromWorkspaceHistory(
      "gallery",
      restoreGalleryNavigationLevel,
      restoreEntry?.context || {}
    );
    await reconcileGeneralSettingsFromWorkspaceHistory(
      "gallery",
      restoreGalleryNavigationLevel,
      restoreEntry?.context || {}
    );
    await reconcileWorldMapLocationBackfillFromWorkspaceHistory(
      "gallery",
      restoreGalleryNavigationLevel,
      restoreEntry?.context || {}
    );
    await reconcileWorldMapPlaceTagsFromWorkspaceHistory(
      "gallery",
      restoreGalleryNavigationLevel,
      restoreEntry?.context || {}
    );
    reconcileSlimmingIdenticalCleanupFromWorkspaceHistory(
      "gallery",
      restoreGalleryNavigationLevel,
      restoreEntry?.context || {}
    );
    reconcileSlimmingVerificationFromWorkspaceHistory(
      "gallery",
      restoreGalleryNavigationLevel,
      restoreEntry?.context || {}
    );
    reconcileSlimmingRecycleExplanationFromWorkspaceHistory(
      "gallery",
      restoreGalleryNavigationLevel,
      restoreEntry?.context || {}
    );
    await reconcileSlimmingSetupFromWorkspaceHistory(
      "gallery",
      restoreGalleryNavigationLevel,
      restoreEntry?.context || {}
    );
    reconcileSlimmingThresholdFromWorkspaceHistory(
      "gallery",
      restoreGalleryNavigationLevel,
      restoreEntry?.context || {}
    );
    await reconcileTrainingSetupFromWorkspaceHistory(
      "gallery",
      restoreGalleryNavigationLevel,
      restoreEntry?.context || {}
    );
    await reconcileTagSuggestionFromWorkspaceHistory(
      "gallery",
      restoreGalleryNavigationLevel,
      restoreEntry?.context || {}
    );
    await reconcileNewTagFromWorkspaceHistory(
      "gallery",
      restoreGalleryNavigationLevel,
      restoreEntry?.context || {}
    );
    await reconcileTagManagerFromWorkspaceHistory(
      "gallery",
      restoreGalleryNavigationLevel,
      restoreEntry?.context || {}
    );
    await reconcileSourceManagerFromWorkspaceHistory(
      "gallery",
      restoreGalleryNavigationLevel,
      restoreEntry?.context || {}
    );
    await reconcileStorageMaintenanceFromWorkspaceHistory(
      "gallery",
      restoreGalleryNavigationLevel,
      restoreEntry?.context || {}
    );
    reconcileConfirmationFromWorkspaceHistory(
      "gallery",
      restoreGalleryNavigationLevel,
      restoreEntry?.context || {}
    );
  }
  if (supportsLibrarySlimming()) {
    await Promise.all([
      loadSlimmingIdenticalCleanupRequests({ quiet: true }),
      loadGalleryRemovals({ quiet: true }),
    ]);
  }
  if (generation !== state.workspaceGeneration) return;
  captureMediaSession();
  state.workspaceNavigation.pendingRestoreEntry = null;
  if (restoreEntry?.route && restoreEntry.route !== "gallery") {
    try {
      await applyWorkspaceHistoryEntry(restoreEntry, { restoringReload: true });
    } catch (error) {
      closeAllWorkspacesToGallery({ restoreFocus: false });
      recordWorkspaceHistory("gallery", null, "replace");
      toast(error.message || "未能恢复刷新前的工作区");
    }
  } else if (restoreEntry?.route === "gallery") {
    checkpointActiveWorkspaceHistory();
  }
  if (generation !== state.workspaceGeneration) return;
  setupAutoPagination();
  connectEvents();
  scheduleEmbeddingPreparationPoll();
  scheduleSampleSuggestionPoll();
  scheduleLibrarySuggestionPoll();
  scheduleTagLibrarySuggestionPoll();
  scheduleTrainingActivityPoll();
  scheduleSourceManagementPoll();
}

function expandedRefreshKinds(kinds) {
  const expanded = new Set(kinds);
  if (expanded.has("full")) {
    return new Set([
      "sourcesChanged",
      "tagsChanged",
      "assetsChanged",
      "jobsChanged",
      "reviewChanged",
    ]);
  }
  if (expanded.has("sourcesChanged") || expanded.has("tagsChanged")) {
    expanded.add("assetsChanged");
  }
  return expanded;
}

async function refreshWorkspace({ quiet = false, kinds = null } = {}) {
  const refreshGeneration = state.workspaceGeneration;
  const requestedKinds = kinds == null ? ["full"] : kinds;
  for (const kind of requestedKinds) state.pendingRefreshKinds.add(kind);
  if (
    !quiet
    || (kinds != null
      && kinds.some((kind) => ["full", "assetsChanged", "tagsChanged"].includes(kind)))
  ) {
    state.pendingInspectorRefresh = true;
  }
  if (state.refreshingWorkspace) return;

  clearTimeout(state.refreshRetryTimer);
  state.refreshRetryTimer = null;
  state.refreshingWorkspace = true;
  let failedBatch = null;
  let failedInspectorRefresh = false;
  let retryDelay = 0;
  try {
    while (state.pendingRefreshKinds.size) {
      const batch = expandedRefreshKinds(state.pendingRefreshKinds);
      state.pendingRefreshKinds.clear();
      failedBatch = batch;
      const refreshInspectorForBatch = state.pendingInspectorRefresh;
      state.pendingInspectorRefresh = false;
      failedInspectorRefresh = refreshInspectorForBatch;

      const [sources, tags, tagGroups, jobs, workspaceNotice] = await Promise.all([
        batch.has("sourcesChanged") ? api("/v1/sources") : null,
        batch.has("tagsChanged") ? api("/v1/tags") : null,
        batch.has("tagsChanged") ? api("/v1/tag-groups") : null,
        batch.has("jobsChanged") ? api("/v1/jobs") : null,
        supportsWorkspaceNotices()
          ? api("/v1/workspace-notice").catch(() => undefined)
          : null,
      ]);
      if (refreshGeneration !== state.workspaceGeneration) {
        failedBatch = null;
        return;
      }

      const sourcesChanged = Boolean(
        sources
        && projectionFingerprint(sources) !== projectionFingerprint(state.sources)
      );
      const tagsChanged = Boolean(
        tags
        && projectionFingerprint(tags) !== projectionFingerprint(state.tags)
      );
      const tagGroupsChanged = Boolean(
        tagGroups
        && projectionFingerprint(tagGroups) !== projectionFingerprint(state.tagGroups)
      );
      const jobsChanged = Boolean(
        jobs
        && projectionFingerprint(jobs) !== projectionFingerprint(state.jobs)
      );
      if (workspaceNotice !== undefined && workspaceNotice !== null
        && !state.workspaceNotice.dismissing
        && !state.workspaceNotice.activeActionID) {
        state.workspaceNotice.notice = workspaceNotice.notice || null;
        renderWorkspaceNotice();
      }
      if (batch.has("sourcesChanged")) {
        state.folderNavigation.branches.clear();
        state.folderNavigation.branchRequestGenerations.clear();
        state.folderNavigation.searches.clear();
        state.folderNavigation.searchRequestGenerations.clear();
        state.folderNavigation.requestGeneration += 1;
      }
      if (sourcesChanged) {
        state.sources = sources;
        if (state.selectedSourceID
          && !state.sources.some((source) => source.id === state.selectedSourceID)) {
          state.selectedSourceID = "";
          state.selectedAssetID = null;
          state.selectedDetail = null;
        }
        renderSources();
        sanitizeReviewSourceFilter();
        renderReviewSourceFilter();
        renderReviewLocalModelStatus();
        updateLibraryTitle();
        renderLibraryEmptyState();
        await reconcileSlimmingRecycleSourceProjection();
      }
      if (batch.has("sourcesChanged")) {
        await reconcileSelectedFolderAfterSourceRefresh();
        renderSources();
        loadExpandedFolderBranches();
        updateLibraryTitle();
      }
      if (tagsChanged || tagGroupsChanged) {
        if (tags) state.tags = tags;
        if (tagGroups) state.tagGroups = tagGroups;
        const activeTagIDs = new Set(activeTags().map((tag) => tag.id));
        state.filters.tagConditions = state.filters.tagConditions.filter(
          (condition) => activeTagIDs.has(condition.tagID)
        );
        if (state.filterDraft) {
          state.filterDraft.tagConditions = state.filterDraft.tagConditions.filter(
            (condition) => activeTagIDs.has(condition.tagID)
          );
        }
        renderTagSelects();
        renderFilterChips();
      }
      if (jobsChanged) {
        state.jobs = jobs;
        renderJobs();
        await loadTrainingActivities({ quiet: true });
        if (supportsLibrarySuggestions()) {
          await loadLibrarySuggestions({ quiet: true });
        }
      }

      let assetsChanged = false;
      if (batch.has("assetsChanged")) {
        if (visibleWorkspaceRoute() === "gallery") {
          assetsChanged = await loadAssets({
            preserveSelection: true,
            preserveUnchangedGrid: true,
            preserveLoadedWindow: true,
          });
        } else {
          state.galleryAssetsRefreshPending = true;
        }
      }
      const shouldRefreshInspector = Boolean(
        state.selectedAssetID
        && (refreshInspectorForBatch || tagsChanged || assetsChanged)
        && !state.selectionMode
      );
      if (shouldRefreshInspector) {
        failedInspectorRefresh = true;
        await loadInspector(state.selectedAssetID, {
          preserveExisting: true,
          quiet: true,
          throwOnError: true,
        });
      }
      if (state.selectionMode && batch.has("tagsChanged")) {
        scheduleSelectionAggregate();
      }
      if (
        !elements.reviewWorkspace.classList.contains("hidden")
        && (batch.has("reviewChanged")
          || batch.has("assetsChanged")
          || batch.has("tagsChanged")
          || sourcesChanged)
      ) {
        await loadReviewOverview({ throwOnError: true });
        if (state.review.mode === "queue") {
          await loadReviewQueue({
            preserveUnchangedGrid: true,
            preserveLoadedWindow: true,
            throwOnError: true,
          });
        }
      }
      if (
        !elements.trainingWorkspace.classList.contains("hidden")
        && batch.has("jobsChanged")
      ) {
        await loadTrainingWorkspace({ quiet: true });
      }
      if (
        !elements.slimmingWorkspace.classList.contains("hidden")
        && batch.has("jobsChanged")
      ) {
        await loadSlimmingWorkspace({ quiet: true });
      }
      if (
        !elements.galleryOverviewWorkspace.classList.contains("hidden")
        && (batch.has("assetsChanged") || batch.has("sourcesChanged") || batch.has("tagsChanged"))
      ) {
        await loadGalleryOverview({ quiet: true, throwOnError: true });
      }
      failedBatch = null;
      failedInspectorRefresh = false;
    }
    state.refreshRetryAttempt = 0;
    if (!quiet) toast("图库已刷新");
  } catch (error) {
    if (refreshGeneration !== state.workspaceGeneration) {
      failedBatch = null;
      return;
    }
    for (const kind of failedBatch || []) state.pendingRefreshKinds.add(kind);
    if (failedInspectorRefresh) state.pendingInspectorRefresh = true;
    const retryDelays = [1000, 2000, 4000, 8000, 16000, 30000];
    retryDelay = retryDelays[
      Math.min(state.refreshRetryAttempt, retryDelays.length - 1)
    ];
    state.refreshRetryAttempt += 1;
    if (!quiet) toast(error.message || "刷新失败");
  } finally {
    state.refreshingWorkspace = false;
    if (state.pendingRefreshKinds.size) {
      state.refreshRetryTimer = setTimeout(
        () => refreshWorkspace({ quiet: true, kinds: [] }),
        retryDelay
      );
    }
  }
}

function socketURL() {
  const scheme = location.protocol === "https:" ? "wss:" : "ws:";
  return `${scheme}//${location.host}/v1/events/websocket`;
}

function disconnectEvents() {
  state.socketGeneration += 1;
  clearTimeout(state.accountPollTimer);
  state.accountPollTimer = null;
  if (state.socket) {
    state.socket.onclose = null;
    state.socket.close();
    state.socket = null;
  }
}

function markWorkspaceInteraction() {
  state.lastWorkspaceInteractionAt = Date.now();
  if (state.authMode === "pairedDevice" && state.accountPollTimer != null) {
    scheduleProjectionPoll(state.socketGeneration);
  }
}

function bindWorkspaceInteractionDeferral() {
  document.addEventListener("pointerdown", markWorkspaceInteraction, {
    capture: true,
    passive: true,
  });
  document.addEventListener("keydown", markWorkspaceInteraction, {
    capture: true,
  });
  document.addEventListener("wheel", markWorkspaceInteraction, {
    capture: true,
    passive: true,
  });
  document.addEventListener("input", markWorkspaceInteraction, {
    capture: true,
  });
}

function scheduleProjectionPoll(generation, delayOverride = null) {
  clearTimeout(state.accountPollTimer);
  const interval = state.authMode === "account" ? 10_000 : 15_000;
  state.accountPollTimer = setTimeout(async () => {
    if (generation !== state.socketGeneration
      || !["account", "pairedDevice"].includes(state.authMode)
      || elements.appView.classList.contains("hidden")) return;
    if (state.authMode === "pairedDevice") {
      const settleRemaining = state.lastWorkspaceInteractionAt
        + PROJECTION_POLL_INTERACTION_SETTLE_MS
        - Date.now();
      if (settleRemaining > 0) {
        scheduleProjectionPoll(generation, Math.ceil(settleRemaining));
        return;
      }
    }
    try {
      await api("/web/session", {}, false);
      await refreshWorkspace({ quiet: true });
      setConnection(true, state.authMode === "account" ? "账号已登录" : "已连接");
      scheduleProjectionPoll(generation);
    } catch (error) {
      if (error.status === 401) {
        if (state.authMode === "account") {
          state.accountAuthorization = null;
          state.authMode = null;
          showPairing("账号密码无效或已从 Mac 白名单移除。");
        } else {
          showPairing("网页会话已过期，请在 Mac 上重新配对。");
        }
      } else {
        setConnection(false);
        scheduleProjectionPoll(generation);
      }
    }
  }, delayOverride ?? interval);
}

function scheduleEventReconnect(generation) {
  const delays = [1000, 2000, 4000, 8000, 16000, 30000];
  const delay = delays[Math.min(state.reconnectAttempt, delays.length - 1)];
  state.reconnectAttempt += 1;
  setTimeout(() => {
    if (generation === state.socketGeneration && !elements.appView.classList.contains("hidden")) {
      connectEvents();
    }
  }, delay);
}

async function connectEvents() {
  disconnectEvents();
  const generation = state.socketGeneration;
  if (state.authMode === "account") {
    try {
      await api("/web/session", {}, false);
      if (generation !== state.socketGeneration) return;
      state.reconnectAttempt = 0;
      setConnection(true, "账号已登录");
      scheduleProjectionPoll(generation);
    } catch (error) {
      if (error.status === 401) {
        state.accountAuthorization = null;
        state.authMode = null;
        showPairing("账号密码无效或已从 Mac 白名单移除。");
      } else {
        setConnection(false);
        scheduleProjectionPoll(generation);
      }
    }
    return;
  }
  setConnection(true, "正在连接实时更新");
  try {
    await api("/web/session");
  } catch (error) {
    if (generation !== state.socketGeneration) return;
    if (error.status === 401) {
      showPairing("网页会话已过期，请在 Mac 上重新配对。");
      return;
    }
    setConnection(false);
    scheduleEventReconnect(generation);
    return;
  }
  if (generation !== state.socketGeneration) return;
  scheduleProjectionPoll(generation);

  const socket = new WebSocket(socketURL());
  state.socket = socket;
  socket.addEventListener("open", () => {
    if (generation !== state.socketGeneration) return;
    state.reconnectAttempt = 0;
    setConnection(true, "已连接");
  });
  socket.addEventListener("message", (event) => {
    if (generation !== state.socketGeneration) return;
    try {
      const message = JSON.parse(event.data);
      if (message.kind === "ping") return;
      state.pendingRefreshKinds.add(message.kind);
      if (["full", "assetsChanged", "tagsChanged"].includes(message.kind)) {
        state.pendingInspectorRefresh = true;
      }
      clearTimeout(state.eventRefreshTimer);
      state.eventRefreshTimer = setTimeout(
        () => refreshWorkspace({ quiet: true, kinds: [] }),
        280
      );
    } catch {
      // Ignore malformed events while preserving the live connection.
    }
  });
  socket.addEventListener("close", () => {
    if (generation !== state.socketGeneration) return;
    state.socket = null;
    setConnection(false);
    scheduleEventReconnect(generation);
  });
  socket.addEventListener("error", () => {
    if (generation === state.socketGeneration) setConnection(false);
  });
}

async function pair(event) {
  event.preventDefault();
  const pairingToken = elements.pairingToken.value.trim();
  const deviceName = elements.deviceName.value.trim();
  if (!pairingToken || !deviceName) return;

  elements.pairButton.disabled = true;
  elements.pairButton.textContent = "正在连接…";
  elements.pairingError.textContent = "";
  try {
    state.accountAuthorization = null;
    await updateMediaWorkerAuthorization(null);
    await api("/web/session/pair", {
      method: "POST",
      body: JSON.stringify({
        pairingToken,
        deviceName,
        clientID: clientID(),
      }),
    }, false);
    state.authMode = "pairedDevice";
    elements.pairingToken.value = "";
    await loadWorkspace();
  } catch (error) {
    const message = /invalidToken|noActiveOffer|offerExpired/.test(error.message)
      ? "配对码无效或已过期，请在 Mac 上重新开始配对。"
      : (error.message || "无法完成配对");
    elements.pairingError.textContent = message;
  } finally {
    elements.pairButton.disabled = false;
    elements.pairButton.textContent = "连接图库";
  }
}

async function loginWithAccount(event) {
  event.preventDefault();
  const username = elements.accountUsername.value.trim();
  const password = elements.accountPassword.value;
  if (!username || !password) return;

  elements.accountLoginButton.disabled = true;
  elements.accountLoginButton.textContent = "正在登录…";
  elements.accountLoginError.textContent = "";
  const authorization = basicAuthorization(username, password);
  state.accountAuthorization = authorization;
  try {
    const session = await api("/web/account/login", {
      method: "POST",
      body: "{}",
    }, false);
    state.authMode = session.authMode || "account";
    await updateMediaWorkerAuthorization(state.accountAuthorization);
    elements.accountPassword.value = "";
    await loadWorkspace();
  } catch (error) {
    state.accountAuthorization = null;
    state.authMode = null;
    updateMediaWorkerAuthorization(null);
    elements.accountLoginError.textContent = error.status === 401
      ? "账号名或密码不正确，或该账号不在 Mac 白名单中。"
      : (error.message || "无法登录图库");
  } finally {
    elements.accountLoginButton.disabled = false;
    elements.accountLoginButton.textContent = "登录图库";
  }
}

