async function logout() {
  try {
    await rawFetch("/web/session/logout", { method: "POST", body: "{}" });
  } finally {
    state.autoLoadObserver?.disconnect();
    showPairing("已退出这台设备上的网页会话。");
  }
}

async function selectSource(sourceID, { focusAfterNavigation = false } = {}) {
  leaveIntegratedReviewForLibrary();
  leaveIntegratedGalleryOverviewForLibrary();
  leaveIntegratedWorldMapForLibrary();
  leaveIntegratedTrainingForLibrary();
  leaveIntegratedSlimmingForLibrary();
  if (state.selectionMode) setSelectionMode(false);
  state.libraryScope = "all";
  state.worldMapGalleryScope = null;
  state.folderScope = null;
  state.folderNavigation.selectedSessionID = null;
  state.selectedSourceID = sourceID;
  state.selectedAssetID = null;
  state.selectedDetail = null;
  resetAssetLocalSuggestionState();
  state.inspectorDismissed = false;
  elements.inspector.classList.remove("open");
  renderInspectorSurface();
  renderSources();
  updateLibraryTitle();
  if (focusAfterNavigation) focusFolderBreadcrumbNavigation(sourceID);
  closeMobileSidebar({ restoreFocus: false });
  await loadAssets();
}

async function selectFolder(
  sourceID,
  relativePath,
  { historySessionID = null, focusAfterNavigation = false } = {}
) {
  const source = state.sources.find((candidate) => candidate.id === sourceID);
  if (!folderSourceSupportsHierarchy(source) || !relativePath) return;
  leaveIntegratedReviewForLibrary();
  leaveIntegratedGalleryOverviewForLibrary();
  leaveIntegratedWorldMapForLibrary();
  leaveIntegratedTrainingForLibrary();
  leaveIntegratedSlimmingForLibrary();
  if (state.selectionMode) setSelectionMode(false);
  const scope = { sourceID, relativePath };
  const sessionID = historySessionID || crypto.randomUUID();
  state.folderNavigation.historyScopes.set(sessionID, cloneFolderScope(scope));
  state.folderNavigation.selectedSessionID = sessionID;
  state.folderScope = scope;
  const ancestorBranches = expandFolderScopeAncestors(sourceID, relativePath);
  state.libraryScope = "all";
  state.worldMapGalleryScope = null;
  state.selectedSourceID = sourceID;
  state.selectedAssetID = null;
  state.selectedDetail = null;
  resetAssetLocalSuggestionState();
  state.inspectorDismissed = false;
  elements.inspector.classList.remove("open");
  renderInspectorSurface();
  renderSources();
  loadFolderScopeAncestorBranches(sourceID, ancestorBranches);
  updateLibraryTitle();
  if (focusAfterNavigation) focusFolderBreadcrumbNavigation(sourceID, relativePath);
  closeMobileSidebar({ restoreFocus: false });
  try {
    await loadAssets();
  } catch (error) {
    if (error.status === 400 && state.folderScope?.sourceID === sourceID) {
      toast("这个文件夹已不在最新索引中，已返回来源根目录");
      await selectSource(sourceID, { focusAfterNavigation });
      return;
    }
    toast(error.message || "无法打开文件夹");
  }
}

const LIBRARY_SORT_OPTIONS = [
  { value: "newest", title: "最新优先" },
  { value: "oldest", title: "最早优先" },
  { value: "fileNameAscending", title: "文件名升序" },
];

function librarySortTitle(sort) {
  return LIBRARY_SORT_OPTIONS.find((option) => option.value === sort)?.title
    || "文件名升序";
}

function renderSortControls() {
  const title = librarySortTitle(state.sort);
  elements.sortSelect.value = state.sort;
  elements.sortButtonLabel.textContent = title;
  elements.sortButton.setAttribute("aria-label", `排序：${title}`);
  elements.sortButton.title = `排序：${title}`;
  configurePersistentHelp(elements.sortButton, {
    title: `排序：${title}`,
    detail: "更改照片列表的排序方式：最新优先、最早优先或文件名升序。",
  });
  for (const button of elements.sortPopover.querySelectorAll("[data-sort]")) {
    const option = LIBRARY_SORT_OPTIONS.find(
      (candidate) => candidate.value === button.dataset.sort
    );
    const selected = button.dataset.sort === state.sort;
    button.setAttribute("aria-checked", String(selected));
    configurePersistentHelp(button, {
      title: option?.title || "排序",
      detail: `按“${option?.title || "当前方式"}”重新排列当前${currentMediaNoun()}列表。`,
    });
  }
}

function positionSortPopover() {
  if (elements.sortPopover.classList.contains("hidden")) return;
  const anchor = elements.sortButton.getBoundingClientRect();
  const menu = elements.sortPopover.getBoundingClientRect();
  const margin = 8;
  const gap = 6;
  const left = Math.max(
    margin,
    Math.min(anchor.left, globalThis.innerWidth - menu.width - margin)
  );
  const below = anchor.bottom + gap;
  const top = below + menu.height <= globalThis.innerHeight - margin
    ? below
    : Math.max(margin, anchor.top - menu.height - gap);
  elements.sortPopover.style.left = `${left}px`;
  elements.sortPopover.style.top = `${top}px`;
}

function layoutMenuDescriptor(kind) {
  if (kind === "sort") {
    return {
      kind,
      route: "gallery",
      button: elements.sortButton,
      popover: elements.sortPopover,
      optionAttribute: "sort",
    };
  }
  const control = gridDensityControls().find((candidate) => candidate.kind === kind);
  return control
    ? { ...control, optionAttribute: "gridDensity" }
    : null;
}

function activeLayoutMenuDescriptor() {
  if (!elements.sortPopover.classList.contains("hidden")) {
    return layoutMenuDescriptor("sort");
  }
  const control = gridDensityControls().find(
    (candidate) => !candidate.popover.classList.contains("hidden")
  );
  return control ? layoutMenuDescriptor(control.kind) : null;
}

function layoutMenuBaseLevelFromHistory(context = {}) {
  return ["sidebar", "inspector", "lightbox"].includes(context.layoutMenuBaseLevel)
    ? context.layoutMenuBaseLevel
    : "workspace";
}

function layoutMenuFocusValue(descriptor, target = document.activeElement) {
  if (!descriptor?.popover.contains(target)) return null;
  return target?.dataset?.[descriptor.optionAttribute] || null;
}

function layoutMenuRestorableFocusTarget(descriptor) {
  if (!descriptor) return null;
  const stored = state.layoutMenuKind === descriptor.kind
    ? state.layoutMenuFocusedValue
    : null;
  const selected = descriptor.kind === "sort" ? state.sort : String(state.layout.density);
  const value = stored || selected;
  return descriptor.popover.querySelector(
    `[data-${descriptor.optionAttribute.replace(/[A-Z]/g, (letter) => `-${letter.toLowerCase()}`)}="${CSS.escape(value)}"]`
  ) || descriptor.popover.querySelector("button:not(:disabled)");
}

function layoutMenuIsAvailable(descriptor, route = visibleWorkspaceRoute()) {
  return Boolean(
    descriptor
      && descriptor.route === route
      && descriptor.button.getClientRects().length > 0
  );
}

function replaceLayoutMenuHistoryWithBase(baseLevel) {
  if (!state.workspaceNavigation.initialized
    || elements.appView.classList.contains("hidden")) return;
  const current = activeWorkspaceHistoryEntry();
  const route = visibleWorkspaceRoute();
  if (current?.route !== route || current.navigationLevel !== "layoutMenu") return;
  const context = currentWorkspaceHistoryContext(route);
  if (context && typeof context === "object") {
    delete context.layoutMenuBaseLevel;
    delete context.layoutMenuKind;
  }
  const navigationLevel = visibleWorkspaceNavigationBaseLevel(route, baseLevel);
  history.replaceState({
    ...(history.state || {}),
    [WORKSPACE_HISTORY_KEY]: workspaceHistoryEntry(route, context, navigationLevel),
  }, "", location.href);
}

function closeLayoutMenu({
  restoreFocus = true,
  checkpoint = true,
  preserveState = true,
} = {}) {
  const descriptor = activeLayoutMenuDescriptor();
  if (!descriptor) return;
  const focusedValue = layoutMenuFocusValue(descriptor);
  if (focusedValue) state.layoutMenuFocusedValue = focusedValue;
  state.layoutMenuKind = descriptor.kind;
  const baseLevel = state.layoutMenuBaseLevel;
  const returnFocus = state.layoutMenuReturnFocus;
  descriptor.popover.classList.add("hidden");
  descriptor.button.setAttribute("aria-expanded", "false");
  state.layoutMenuReturnFocus = null;
  state.layoutMenuBaseLevel = "workspace";
  if (!preserveState) {
    state.layoutMenuKind = null;
    state.layoutMenuFocusedValue = null;
  }
  if (restoreFocus) restoreOverlayFocus(stableReturnFocusTarget(
    returnFocus || descriptor.button,
    elements.commandButton
  ));
  if (checkpoint) replaceLayoutMenuHistoryWithBase(baseLevel);
}

function returnFromLayoutMenu({ restoreFocus = true } = {}) {
  if (!activeLayoutMenuDescriptor()) return Promise.resolve();
  state.layoutMenuHistoryRestoreFocus = restoreFocus;
  if (state.workspaceNavigation.pendingReturnPromise) {
    return state.workspaceNavigation.pendingReturnPromise;
  }
  const current = activeWorkspaceHistoryEntry();
  if (state.workspaceNavigation.initialized
    && current?.route === visibleWorkspaceRoute()
    && current.navigationLevel === "layoutMenu") {
    const pending = new Promise((resolve) => {
      state.workspaceNavigation.pendingReturnResolve = resolve;
    });
    state.workspaceNavigation.pendingReturnPromise = pending;
    history.back();
    return pending;
  }
  closeLayoutMenu({ restoreFocus });
  state.layoutMenuHistoryRestoreFocus = true;
  return Promise.resolve();
}

function openLayoutMenu(kind, {
  focus = true,
  historyMode = "pushLayoutMenu",
  baseLevel = null,
  restoring = false,
} = {}) {
  const descriptor = layoutMenuDescriptor(kind);
  const route = visibleWorkspaceRoute();
  if (!layoutMenuIsAvailable(descriptor, route)) return;
  const active = activeLayoutMenuDescriptor();
  if (active?.kind === kind) {
    if (focus) restoreOverlayFocus(layoutMenuRestorableFocusTarget(descriptor));
    return;
  }
  if (active) closeLayoutMenu({ restoreFocus: false });
  state.layoutMenuReturnFocus = document.activeElement instanceof HTMLElement
    ? document.activeElement
    : descriptor.button;
  const current = activeWorkspaceHistoryEntry();
  const replacesActionMenu = historyMode === "pushLayoutMenu"
    && current?.navigationLevel === "actionMenu";
  state.layoutMenuBaseLevel = baseLevel
    || workspaceNavigationBaseLevel(
      current?.navigationLevel || "workspace",
      current?.context || {}
    );
  state.layoutMenuKind = kind;
  if (!restoring) state.layoutMenuFocusedValue = null;
  closeCompactToolbarMenu({ restoreFocus: false });
  closeFilterPopover({ restoreFocus: false });
  closeJobsPopover({ restoreFocus: false });
  closeActionMenu({ restoreFocus: false, checkpoint: !replacesActionMenu });
  hideContextMenus();
  if (kind === "sort") renderSortControls();
  else renderGridDensityControls();
  descriptor.popover.classList.remove("hidden");
  descriptor.button.setAttribute("aria-expanded", "true");
  if (kind === "sort") positionSortPopover();
  else positionGridDensityPopover(gridDensityControlForButton(descriptor.button));
  if (historyMode !== "none") {
    recordWorkspaceHistory(
      route,
      currentWorkspaceHistoryContext(route),
      replacesActionMenu ? "replaceOverlay" : historyMode
    );
  }
  if (focus) requestAnimationFrame(() => {
    layoutMenuRestorableFocusTarget(descriptor)?.focus({ preventScroll: true });
  });
}

function reconcileLayoutMenuFromWorkspaceHistory(route, navigationLevel, context = {}) {
  const kind = typeof context.layoutMenuKind === "string"
    ? context.layoutMenuKind
    : null;
  const descriptor = layoutMenuDescriptor(kind);
  const shouldOpen = navigationLevel === "layoutMenu"
    && route === visibleWorkspaceRoute()
    && layoutMenuIsAvailable(descriptor, route);
  const active = activeLayoutMenuDescriptor();
  if (shouldOpen && active?.kind !== kind) {
    if (active) closeLayoutMenu({ restoreFocus: false, checkpoint: false });
    openLayoutMenu(kind, {
      historyMode: "none",
      baseLevel: layoutMenuBaseLevelFromHistory(context),
      restoring: true,
    });
  } else if (!shouldOpen && active) {
    const restoreFocus = state.layoutMenuHistoryRestoreFocus;
    closeLayoutMenu({ restoreFocus, checkpoint: false, preserveState: true });
    state.layoutMenuHistoryRestoreFocus = true;
  } else if (navigationLevel === "layoutMenu" && !shouldOpen) {
    replaceLayoutMenuHistoryWithBase(layoutMenuBaseLevelFromHistory(context));
  }
}

function toggleSortPopover() {
  if (activeLayoutMenuDescriptor()?.kind === "sort") {
    void returnFromLayoutMenu();
  } else {
    openLayoutMenu("sort");
  }
}

async function applyLibrarySort(sort) {
  if (!LIBRARY_SORT_OPTIONS.some((option) => option.value === sort)) return;
  const changed = state.sort !== sort;
  state.sort = sort;
  renderSortControls();
  await returnFromLayoutMenu();
  if (changed) await loadAssets();
}

function moveSortMenuFocus(event) {
  const buttons = [...elements.sortPopover.querySelectorAll("[data-sort]")];
  if (!buttons.length) return;
  if (event.key === "Escape") {
    event.preventDefault();
    void returnFromLayoutMenu();
    return;
  }
  if (!["ArrowUp", "ArrowDown", "Home", "End"].includes(event.key)) return;
  event.preventDefault();
  const current = Math.max(0, buttons.indexOf(document.activeElement));
  const next = event.key === "Home" ? 0
    : event.key === "End" ? buttons.length - 1
      : (current + (event.key === "ArrowUp" ? -1 : 1) + buttons.length) % buttons.length;
  buttons[next].focus({ preventScroll: true });
}

function gridDensityControlForButton(button) {
  return gridDensityControls().find((control) => control.button === button) || null;
}

function gridDensityControlForPopover(popover) {
  return gridDensityControls().find((control) => control.popover === popover) || null;
}

function positionGridDensityPopover(control) {
  if (!control || control.popover.classList.contains("hidden")) return;
  const anchor = control.button.getBoundingClientRect();
  const menu = control.popover.getBoundingClientRect();
  const margin = 8;
  const gap = 6;
  const left = Math.max(
    margin,
    Math.min(anchor.left, globalThis.innerWidth - menu.width - margin)
  );
  const below = anchor.bottom + gap;
  const top = below + menu.height <= globalThis.innerHeight - margin
    ? below
    : Math.max(margin, anchor.top - menu.height - gap);
  control.popover.style.left = `${left}px`;
  control.popover.style.top = `${top}px`;
}

function closeGridDensityPopovers(options = {}) {
  const active = activeLayoutMenuDescriptor();
  if (!active || active.kind === "sort") return;
  closeLayoutMenu(options);
}

function openGridDensityPopover(button) {
  const control = gridDensityControlForButton(button);
  if (!control || !control.popover.classList.contains("hidden")) return;
  openLayoutMenu(control.kind);
}

function toggleGridDensityPopover(button) {
  const control = gridDensityControlForButton(button);
  if (!control) return;
  if (control.popover.classList.contains("hidden")) openGridDensityPopover(button);
  else void returnFromLayoutMenu();
}

function applyGridDensity(value) {
  const next = Number(value);
  if (!Number.isInteger(next) || !GRID_DENSITY_OPTIONS.some((option) => option.value === next)) {
    return;
  }
  state.layout.density = next;
  renderLayoutPreferences();
  persistWorkspacePreferences();
  void returnFromLayoutMenu();
}

function moveGridDensityMenuFocus(event) {
  const control = gridDensityControlForPopover(event.currentTarget);
  if (!control) return;
  const buttons = [...control.popover.querySelectorAll("[data-grid-density]")];
  if (!buttons.length) return;
  if (event.key === "Escape") {
    event.preventDefault();
    void returnFromLayoutMenu();
    return;
  }
  if (!['ArrowUp', 'ArrowDown', 'Home', 'End'].includes(event.key)) return;
  event.preventDefault();
  const current = Math.max(0, buttons.indexOf(document.activeElement));
  const next = event.key === "Home" ? 0
    : event.key === "End" ? buttons.length - 1
      : (current + (event.key === "ArrowUp" ? -1 : 1) + buttons.length) % buttons.length;
  buttons[next].focus({ preventScroll: true });
}

function bindGridDensityControls() {
  for (const control of gridDensityControls()) {
    control.button.addEventListener("click", () => toggleGridDensityPopover(control.button));
    control.popover.addEventListener("click", (event) => {
      const button = event.target.closest("[data-grid-density]");
      if (button && !button.disabled) applyGridDensity(button.dataset.gridDensity);
    });
    control.popover.addEventListener("keydown", moveGridDensityMenuFocus);
  }
}

function filterBaseLevelFromHistory(context = {}) {
  return ["sidebar", "inspector", "lightbox"].includes(context.filterBaseLevel)
    ? context.filterBaseLevel
    : "workspace";
}

function replaceFilterHistoryWithBase(baseLevel) {
  if (!state.workspaceNavigation.initialized
    || elements.appView.classList.contains("hidden")) return;
  const current = activeWorkspaceHistoryEntry();
  if (current?.route !== "gallery" || current.navigationLevel !== "filter") return;
  const context = currentGalleryHistoryContext();
  if (context && typeof context === "object") delete context.filterBaseLevel;
  const navigationLevel = visibleWorkspaceNavigationBaseLevel("gallery", baseLevel);
  history.replaceState({
    ...(history.state || {}),
    [WORKSPACE_HISTORY_KEY]: workspaceHistoryEntry("gallery", context, navigationLevel),
  }, "", location.href);
}

function filterRestorableFocusTarget() {
  const target = state.filterFocusedControl;
  if (target instanceof HTMLElement
    && target.isConnected
    && elements.filterPopover.contains(target)
    && !target.matches(":disabled")
    && target.getClientRects().length > 0) return target;
  return elements.filterPopover.querySelector(
    'input:not(:disabled), select:not(:disabled), button:not(:disabled)'
  ) || elements.closeFilterButton;
}

function closeFilterPopover({
  restoreFocus = true,
  checkpoint = true,
  preserveState = true,
} = {}) {
  if (elements.filterPopover.classList.contains("hidden")) return;
  if (elements.filterPopover.contains(document.activeElement)) {
    state.filterFocusedControl = document.activeElement;
  }
  state.filterScrollTop = elements.filterPopover.scrollTop;
  const baseLevel = state.filterBaseLevel;
  const returnFocus = state.filterReturnFocus;
  elements.filterPopover.classList.add("hidden");
  elements.filterButton.setAttribute("aria-expanded", "false");
  state.filterDraft = null;
  state.filterReturnFocus = null;
  state.filterBaseLevel = "workspace";
  if (!preserveState) {
    state.filterFocusedControl = null;
    state.filterScrollTop = 0;
  }
  if (restoreFocus) restoreOverlayFocus(stableReturnFocusTarget(
    returnFocus || elements.filterButton,
    elements.commandButton
  ));
  if (checkpoint) replaceFilterHistoryWithBase(baseLevel);
}

function returnFromFilterPopover({ restoreFocus = true } = {}) {
  if (elements.filterPopover.classList.contains("hidden")) return Promise.resolve();
  state.filterHistoryRestoreFocus = restoreFocus;
  if (state.workspaceNavigation.pendingReturnPromise) {
    return state.workspaceNavigation.pendingReturnPromise;
  }
  const current = activeWorkspaceHistoryEntry();
  if (state.workspaceNavigation.initialized
    && current?.route === "gallery"
    && current.navigationLevel === "filter") {
    const pending = new Promise((resolve) => {
      state.workspaceNavigation.pendingReturnResolve = resolve;
    });
    state.workspaceNavigation.pendingReturnPromise = pending;
    history.back();
    return pending;
  }
  closeFilterPopover({ restoreFocus });
  state.filterHistoryRestoreFocus = true;
  return Promise.resolve();
}

function openFilterPopover({
  focus = true,
  historyMode = "pushFilter",
  baseLevel = null,
  restoring = false,
} = {}) {
  if (visibleWorkspaceRoute() !== "gallery"
    || elements.filterButton.getClientRects().length === 0) return;
  if (!elements.filterPopover.classList.contains("hidden")) {
    if (focus) restoreOverlayFocus(filterRestorableFocusTarget());
    return;
  }
  state.filterReturnFocus = document.activeElement instanceof HTMLElement
    ? document.activeElement
    : elements.filterButton;
  const current = activeWorkspaceHistoryEntry();
  const replacesActionMenu = historyMode === "pushFilter"
    && current?.navigationLevel === "actionMenu";
  state.filterBaseLevel = baseLevel
    || workspaceNavigationBaseLevel(
      current?.navigationLevel || "workspace",
      current?.context || {}
    );
  if (!restoring) {
    state.filterFocusedControl = null;
    state.filterScrollTop = 0;
  }
  closeCompactToolbarMenu({ restoreFocus: false });
  closeLayoutMenu({ restoreFocus: false });
  closeJobsPopover({ restoreFocus: false });
  closeActionMenu({ restoreFocus: false, checkpoint: !replacesActionMenu });
  state.filterDraft = cloneFilters(state.filters);
  syncFilterControlsFromState();
  elements.filterPopover.classList.remove("hidden");
  elements.filterButton.setAttribute("aria-expanded", "true");
  if (historyMode !== "none") {
    recordWorkspaceHistory(
      "gallery",
      currentGalleryHistoryContext(),
      replacesActionMenu ? "replaceOverlay" : historyMode
    );
  }
  requestAnimationFrame(() => {
    elements.filterPopover.scrollTop = state.filterScrollTop;
    if (focus) filterRestorableFocusTarget().focus({ preventScroll: true });
  });
}

function reconcileFilterPopoverFromWorkspaceHistory(route, navigationLevel, context = {}) {
  const shouldOpen = route === "gallery"
    && navigationLevel === "filter"
    && elements.filterButton.getClientRects().length > 0;
  if (shouldOpen && elements.filterPopover.classList.contains("hidden")) {
    openFilterPopover({
      historyMode: "none",
      baseLevel: filterBaseLevelFromHistory(context),
      restoring: true,
    });
  } else if (!shouldOpen && !elements.filterPopover.classList.contains("hidden")) {
    const restoreFocus = state.filterHistoryRestoreFocus;
    closeFilterPopover({ restoreFocus, checkpoint: false, preserveState: true });
    state.filterHistoryRestoreFocus = true;
  } else if (navigationLevel === "filter" && !shouldOpen) {
    replaceFilterHistoryWithBase(filterBaseLevelFromHistory(context));
  }
}

function toggleFilterPopover() {
  if (elements.filterPopover.classList.contains("hidden")) openFilterPopover();
  else void returnFromFilterPopover();
}

function compactToolbarOriginalIsAvailable(element, { optional = false } = {}) {
  if (!(element instanceof HTMLElement)) return false;
  if (optional && element.classList.contains("hidden")) return false;
  return true;
}

function compactToolbarAction(
  element,
  { icon, label, detail = "", optional = false, destructive = false }
) {
  if (!compactToolbarOriginalIsAvailable(element, { optional })) return null;
  return {
    element,
    icon,
    label,
    detail,
    destructive,
    disabled: element.matches(":disabled"),
  };
}

function compactToolbarSections() {
  const undoActions = [
    compactToolbarAction(elements.undoTagButton, {
      icon: "↶",
      label: "撤销标签操作",
      detail: elements.undoTagButton.disabled ? "当前没有可撤销操作" : "恢复最近一次标签决定",
    }),
    compactToolbarAction(elements.undoReviewButton, {
      icon: "↶✓",
      label: "撤销审核操作",
      detail: "恢复最近一次审核决定",
      optional: true,
    }),
  ].filter(Boolean);
  const progressActions = [
    compactToolbarAction(elements.catalogProgressStatusButton, {
      icon: "↻",
      label: elements.catalogProgressStatusLabel.textContent.trim() || "正在扫描来源",
      detail: "在活动中查看",
      optional: true,
    }),
    compactToolbarAction(elements.sourcePrewarmStatusButton, {
      icon: "▦",
      label: elements.sourcePrewarmStatusLabel.textContent.trim() || "正在缓存缩略图",
      detail: "打开来源管理",
      optional: true,
    }),
    compactToolbarAction(elements.sourcePrewarmCancelButton, {
      icon: "×",
      label: "取消来源缩略图缓存",
      detail: "停止当前缓存任务",
      optional: true,
      destructive: true,
    }),
  ].filter(Boolean);
  const workspaceActions = [
    compactToolbarAction(elements.worldMapButton, {
      icon: "◎", label: "照片世界", detail: "按地点浏览图库",
    }),
    compactToolbarAction(elements.trainingButton, {
      icon: "⌁", label: "训练工程", detail: "数据集、运行与模型槽",
    }),
    compactToolbarAction(elements.slimmingButton, {
      icon: "◫", label: "图库瘦身", detail: "分析、候选组与回收站",
    }),
    compactToolbarAction(elements.reviewButton, {
      icon: "✓⃝", label: "待审核建议", detail: "审核模型与个人建议",
    }),
  ].filter(Boolean);
  const layoutActions = [
    compactToolbarAction(elements.inspectorVisibilityButton, {
      icon: "◧",
      label: elements.inspectorVisibilityLabel.textContent.trim() || "显示检查器",
      detail: galleryOverviewLayoutQuery.matches
        ? "显示或隐藏右侧检查器"
        : "打开或关闭当前图库检查器抽屉",
    }),
  ].filter(Boolean);
  const maintenanceActions = [
    compactToolbarAction(elements.toolbarConnectFolderButton, {
      icon: "▤＋",
      label: "连接文件夹",
      detail: "在 Mac 上选择新的照片来源",
    }),
    compactToolbarAction(elements.toolbarExportPortableDataButton, {
      icon: "⇧",
      label: "导出用户数据",
      detail: storageMaintenanceActiveRequest()?.message || "在 Mac 上选择导出位置",
    }),
    compactToolbarAction(elements.storageButton, {
      icon: "▣",
      label: elements.storageStatusLabel.textContent.trim() || "应用存储与预览缓存",
      detail: storageMaintenanceActiveRequest()?.message || "查看用量与维护操作",
    }),
    compactToolbarAction(elements.currentSourceRefreshButton, {
      icon: "↻",
      label: elements.currentSourceRefreshLabel.textContent.trim() || "立即更新当前来源",
      detail: "让 Mac 同步或重扫当前范围",
    }),
    compactToolbarAction(elements.refreshButton, {
      icon: "⟳", label: "重新读取网页数据", detail: "不重新扫描来源",
    }),
  ].filter(Boolean);
  const utilityActions = [
    compactToolbarAction(elements.settingsButton, {
      icon: "⚙", label: "通用设置", detail: "界面、本地模型与性能",
    }),
    compactToolbarAction(elements.shortcutButton, {
      icon: "?", label: "快捷键", detail: "查看当前操作方式",
    }),
    compactToolbarAction(elements.logoutButton, {
      icon: "⇥", label: "退出网页账号", detail: "返回登录界面", destructive: true,
    }),
  ].filter(Boolean);
  return [
    { key: "status", label: "状态与撤销", actions: [...progressActions, ...undoActions] },
    { key: "workspaces", label: "工作区", actions: workspaceActions },
    { key: "layout", label: "布局", actions: layoutActions },
    { key: "maintenance", label: "Mac 与数据", actions: maintenanceActions },
    { key: "settings", label: "设置", actions: utilityActions },
  ].filter((section) => section.actions.length);
}

function compactToolbarHasActivity() {
  return !elements.catalogProgressStatusButton.classList.contains("hidden")
    || !elements.sourcePrewarmStatusButton.classList.contains("hidden");
}

function syncCompactToolbarMenuButton() {
  const active = compactToolbarHasActivity();
  elements.compactToolbarActivityDot.classList.toggle("hidden", !active);
  const activityLabel = active ? "，有正在进行的 Mac 任务" : "";
  elements.compactToolbarMenuButton.setAttribute(
    "aria-label",
    `更多工具栏操作${activityLabel}`
  );
  elements.compactToolbarMenuButton.title = `更多工具栏操作${activityLabel}`;
}

function compactToolbarSectionNode(section) {
  let group = elements.compactToolbarMenuContent.querySelector(
    `:scope > [data-compact-toolbar-section="${CSS.escape(section.key)}"]`
  );
  if (!group) {
    group = document.createElement("section");
    group.className = "compact-toolbar-menu-section";
    group.dataset.compactToolbarSection = section.key;
  }
  group.setAttribute("aria-label", section.label);
  let heading = group.querySelector(":scope > [data-compact-toolbar-part=heading]");
  if (!heading) {
    heading = document.createElement("h3");
    heading.dataset.compactToolbarPart = "heading";
  }
  if (heading.textContent !== section.label) heading.textContent = section.label;
  return { group, heading };
}

function compactToolbarActionNode(action) {
  const targetID = action.element.id;
  let button = elements.compactToolbarMenuContent.querySelector(
    `[data-compact-toolbar-target="${CSS.escape(targetID)}"]`
  );
  if (!button) {
    button = document.createElement("button");
    button.type = "button";
    button.className = "compact-toolbar-menu-item";
    button.setAttribute("role", "menuitem");
    button.dataset.compactToolbarTarget = targetID;

    const icon = document.createElement("span");
    icon.className = "compact-toolbar-menu-icon";
    icon.dataset.compactToolbarPart = "icon";
    icon.setAttribute("aria-hidden", "true");
    const copy = document.createElement("span");
    copy.className = "compact-toolbar-menu-copy";
    const label = document.createElement("strong");
    label.dataset.compactToolbarPart = "label";
    const detail = document.createElement("small");
    detail.dataset.compactToolbarPart = "detail";
    copy.append(label, detail);
    button.append(icon, copy);
  }
  button.classList.toggle("destructive", action.destructive);
  if (button.disabled !== action.disabled) button.disabled = action.disabled;
  const icon = button.querySelector("[data-compact-toolbar-part=icon]");
  const label = button.querySelector("[data-compact-toolbar-part=label]");
  const detail = button.querySelector("[data-compact-toolbar-part=detail]");
  if (icon.textContent !== action.icon) icon.textContent = action.icon;
  if (label.textContent !== action.label) label.textContent = action.label;
  if (detail.textContent !== action.detail) detail.textContent = action.detail;
  return button;
}

function reconcileCompactToolbarMenuContent() {
  const groups = [];
  for (const section of compactToolbarSections()) {
    const { group, heading } = compactToolbarSectionNode(section);
    const actions = section.actions.map(compactToolbarActionNode);
    reconcileStableChildren(group, [heading, ...actions]);
    groups.push(group);
  }
  reconcileStableChildren(elements.compactToolbarMenuContent, groups);
}

function renderCompactToolbarMenu() {
  syncCompactToolbarMenuButton();
  const connection = elements.connectionLabel.textContent.trim()
    || (state.online ? "已连接" : "Mac 离线");
  if (elements.compactToolbarConnectionSummary.textContent !== connection) {
    elements.compactToolbarConnectionSummary.textContent = connection;
  }
  const hostName = state.capabilities?.hostDisplayName || "这台 Mac";
  const hostVersion = state.capabilities?.hostAppVersion || "";
  const hostSummary = [hostName, hostVersion].filter(Boolean).join(" · ");
  if (elements.compactToolbarHostSummary.textContent !== hostSummary) {
    elements.compactToolbarHostSummary.textContent = hostSummary;
  }
  reconcileCompactToolbarMenuContent();
}

function compactToolbarMenuIsOpen() {
  return !elements.compactToolbarMenu.classList.contains("hidden");
}

function compactToolbarBaseLevelFromHistory(context = {}) {
  return ["sidebar", "inspector", "lightbox"].includes(context.toolbarMenuBaseLevel)
    ? context.toolbarMenuBaseLevel
    : "workspace";
}

function visibleWorkspaceNavigationBaseLevel(route, requestedLevel) {
  if (requestedLevel === "sidebar" && route === "gallery" && mobileSidebarOverlayIsOpen()) {
    return "sidebar";
  }
  if (requestedLevel === "lightbox"
    && !elements.lightbox.classList.contains("hidden")
    && state.lightboxContext === workspaceLightboxContext(route)) {
    return "lightbox";
  }
  if (requestedLevel === "inspector"
    && route === "gallery"
    && galleryInspectorOverlayIsOpen()) {
    return "inspector";
  }
  return "workspace";
}

function replaceCompactToolbarHistoryWithBase(baseLevel) {
  if (!state.workspaceNavigation.initialized
    || elements.appView.classList.contains("hidden")) return;
  const current = activeWorkspaceHistoryEntry();
  const route = visibleWorkspaceRoute();
  if (current?.route !== route || current.navigationLevel !== "toolbarMenu") return;
  const context = currentWorkspaceHistoryContext(route);
  if (context && typeof context === "object") delete context.toolbarMenuBaseLevel;
  const navigationLevel = visibleWorkspaceNavigationBaseLevel(route, baseLevel);
  history.replaceState({
    ...(history.state || {}),
    [WORKSPACE_HISTORY_KEY]: workspaceHistoryEntry(route, context, navigationLevel),
  }, "", location.href);
}

function closeCompactToolbarMenu({ restoreFocus = true, checkpoint = true } = {}) {
  if (!compactToolbarMenuIsOpen()) return;
  const baseLevel = state.compactToolbarBaseLevel;
  elements.compactToolbarMenu.classList.add("hidden");
  elements.compactToolbarMenuButton.setAttribute("aria-expanded", "false");
  const returnFocus = state.compactToolbarReturnFocus;
  state.compactToolbarReturnFocus = null;
  state.compactToolbarBaseLevel = "workspace";
  if (restoreFocus) restoreOverlayFocus(
    returnFocus instanceof HTMLElement && document.contains(returnFocus)
      ? returnFocus
      : elements.compactToolbarMenuButton
  );
  if (checkpoint) replaceCompactToolbarHistoryWithBase(baseLevel);
}

function returnFromCompactToolbarMenu({ restoreFocus = true } = {}) {
  if (!compactToolbarMenuIsOpen()) return Promise.resolve();
  state.compactToolbarHistoryRestoreFocus = restoreFocus;
  if (state.workspaceNavigation.pendingReturnPromise) {
    return state.workspaceNavigation.pendingReturnPromise;
  }
  const current = activeWorkspaceHistoryEntry();
  if (state.workspaceNavigation.initialized
    && current?.route === visibleWorkspaceRoute()
    && current.navigationLevel === "toolbarMenu") {
    const pending = new Promise((resolve) => {
      state.workspaceNavigation.pendingReturnResolve = resolve;
    });
    state.workspaceNavigation.pendingReturnPromise = pending;
    history.back();
    return pending;
  }
  closeCompactToolbarMenu({ restoreFocus });
  state.compactToolbarHistoryRestoreFocus = true;
  return Promise.resolve();
}

function openCompactToolbarMenu({
  focus = true,
  historyMode = "pushToolbarMenu",
  baseLevel = null,
} = {}) {
  if (compactToolbarMenuIsOpen()) {
    if (focus) restoreOverlayFocus(elements.compactToolbarMenu.querySelector(
      ".compact-toolbar-menu-item:not(:disabled)"
    ));
    return;
  }
  if (elements.compactToolbarMenuButton.getClientRects().length === 0) return;
  state.compactToolbarReturnFocus = document.activeElement instanceof HTMLElement
    ? document.activeElement
    : elements.compactToolbarMenuButton;
  const current = activeWorkspaceHistoryEntry();
  const replacesActionMenu = historyMode === "pushToolbarMenu"
    && current?.navigationLevel === "actionMenu";
  state.compactToolbarBaseLevel = baseLevel
    || workspaceNavigationBaseLevel(
      current?.navigationLevel || "workspace",
      current?.context || {}
    );
  closeLayoutMenu({ restoreFocus: false });
  closeFilterPopover({ restoreFocus: false });
  closeJobsPopover({ restoreFocus: false });
  closeActionMenu({ restoreFocus: false, checkpoint: !replacesActionMenu });
  hideContextMenus();
  renderCompactToolbarMenu();
  elements.compactToolbarMenu.classList.remove("hidden");
  elements.compactToolbarMenuButton.setAttribute("aria-expanded", "true");
  if (historyMode !== "none") {
    const route = visibleWorkspaceRoute();
    recordWorkspaceHistory(
      route,
      currentWorkspaceHistoryContext(route),
      replacesActionMenu ? "replaceOverlay" : historyMode
    );
  }
  if (focus) requestAnimationFrame(() => {
    elements.compactToolbarMenu.querySelector(
      '.compact-toolbar-menu-item:not(:disabled)'
    )?.focus({ preventScroll: true });
  });
}

function reconcileCompactToolbarMenuFromWorkspaceHistory(
  route,
  navigationLevel,
  context = {}
) {
  const shouldOpen = navigationLevel === "toolbarMenu"
    && route === visibleWorkspaceRoute()
    && elements.compactToolbarMenuButton.getClientRects().length > 0;
  if (shouldOpen) {
    openCompactToolbarMenu({
      historyMode: "none",
      baseLevel: compactToolbarBaseLevelFromHistory(context),
    });
  } else if (compactToolbarMenuIsOpen()) {
    const restoreFocus = state.compactToolbarHistoryRestoreFocus;
    closeCompactToolbarMenu({ restoreFocus, checkpoint: false });
    state.compactToolbarHistoryRestoreFocus = true;
  } else if (navigationLevel === "toolbarMenu") {
    replaceCompactToolbarHistoryWithBase(compactToolbarBaseLevelFromHistory(context));
  }
}

function toggleCompactToolbarMenu() {
  if (!compactToolbarMenuIsOpen()) {
    openCompactToolbarMenu();
  } else {
    void returnFromCompactToolbarMenu();
  }
}

function syncCompactToolbarMenu() {
  syncCompactToolbarMenuButton();
  scheduleAdaptiveToolbarSync();
  if (!elements.compactToolbarMenu.classList.contains("hidden")) {
    const previousItems = [...elements.compactToolbarMenu.querySelectorAll(
      ".compact-toolbar-menu-item"
    )];
    const focusedItem = document.activeElement?.closest?.(".compact-toolbar-menu-item");
    const menuHadFocus = focusedItem != null
      && elements.compactToolbarMenu.contains(focusedItem);
    const focusedTarget = focusedItem?.dataset?.compactToolbarTarget || null;
    const focusedIndex = focusedItem ? previousItems.indexOf(focusedItem) : -1;
    const scrollTop = elements.compactToolbarMenuContent.scrollTop;
    renderCompactToolbarMenu();
    const enabledItems = [...elements.compactToolbarMenu.querySelectorAll(
      ".compact-toolbar-menu-item:not(:disabled)"
    )];
    const preserved = focusedTarget
      ? elements.compactToolbarMenu.querySelector(
        `[data-compact-toolbar-target="${CSS.escape(focusedTarget)}"]:not(:disabled)`
      )
      : null;
    if (menuHadFocus) {
      const fallback = enabledItems[Math.min(Math.max(focusedIndex, 0), enabledItems.length - 1)]
        || enabledItems[enabledItems.length - 1]
        || null;
      (preserved || fallback)?.focus({ preventScroll: true });
    }
    elements.compactToolbarMenuContent.scrollTop = scrollTop;
  }
}

function visibleToolbarChildren(container) {
  return [...container.children].filter((child) => {
    if (!(child instanceof HTMLElement)) return false;
    const style = getComputedStyle(child);
    return style.display !== "none" && style.position !== "fixed";
  });
}

function toolbarChildrenRequiredWidth(container, { titleLimit = null } = {}) {
  const children = visibleToolbarChildren(container);
  if (!children.length) return 0;
  const style = getComputedStyle(container);
  const gap = Number.parseFloat(style.columnGap || style.gap) || 0;
  const childrenWidth = children.reduce((total, child) => {
    if (titleLimit != null && child === elements.libraryTitle) {
      return total + Math.min(Math.max(child.scrollWidth, 44), titleLimit);
    }
    return total + child.getBoundingClientRect().width;
  }, 0);
  return childrenWidth + gap * Math.max(0, children.length - 1);
}

function fullToolbarRequiredWidth() {
  if (globalThis.innerWidth <= 720) return Number.POSITIVE_INFINITY;
  const wasCompact = elements.appView.classList.contains("compact-toolbar-active");
  if (wasCompact) elements.appView.classList.remove("compact-toolbar-active");
  const titlebarStyle = getComputedStyle(elements.titlebar);
  const padding = (Number.parseFloat(titlebarStyle.paddingLeft) || 0)
    + (Number.parseFloat(titlebarStyle.paddingRight) || 0);
  const gap = Number.parseFloat(titlebarStyle.columnGap || titlebarStyle.gap) || 0;
  const required = toolbarChildrenRequiredWidth(elements.titlebarLeading, { titleLimit: 180 })
    + toolbarChildrenRequiredWidth(elements.titlebarActions)
    + gap
    + padding;
  if (wasCompact) elements.appView.classList.add("compact-toolbar-active");
  return Math.ceil(required);
}

function syncAdaptiveToolbar() {
  state.adaptiveToolbarFrame = null;
  if (elements.appView.classList.contains("hidden") || !elements.titlebar.clientWidth) return;
  const wasCompact = elements.appView.classList.contains("compact-toolbar-active");
  // Measuring the full toolbar temporarily removes compact mode. That makes the
  // compact menu `display: none`, so capture focus ownership before measuring
  // rather than consulting document.activeElement after the browser has blurred it.
  const compactMenuHadFocus = wasCompact && (
    elements.compactToolbarMenu.contains(document.activeElement)
      || document.activeElement === elements.compactToolbarMenuButton
  );
  const hardCompact = globalThis.innerWidth <= 720;
  const available = elements.titlebar.clientWidth;
  const required = hardCompact ? Number.POSITIVE_INFINITY : fullToolbarRequiredWidth();
  const hysteresis = wasCompact ? 28 : 6;
  const shouldCompact = hardCompact || required > available - hysteresis;
  if (!shouldCompact) closeCompactToolbarMenu({ restoreFocus: false });
  elements.appView.classList.toggle("compact-toolbar-active", shouldCompact);
  elements.appView.dataset.toolbarRequiredWidth = Number.isFinite(required)
    ? String(required)
    : "compact";
  elements.appView.dataset.toolbarAvailableWidth = String(Math.round(available));
  if (!shouldCompact && compactMenuHadFocus) restoreOverlayFocus(elements.commandButton);
  syncCompactToolbarMenuButton();
}

function scheduleAdaptiveToolbarSync() {
  if (state.adaptiveToolbarFrame != null) return;
  state.adaptiveToolbarFrame = requestAnimationFrame(syncAdaptiveToolbar);
}

function isTextInputTarget(target) {
  return target instanceof HTMLInputElement
    || target instanceof HTMLSelectElement
    || target instanceof HTMLTextAreaElement
    || (target instanceof HTMLElement && target.isContentEditable);
}

function isInteractiveControlTarget(target) {
  if (!(target instanceof Element)) return false;
  const control = target.closest(
    "button, a, [role=\"button\"], [role=\"option\"], [role=\"menuitem\"]"
  );
  return Boolean(control && !control.matches(".asset-card-main, .review-card-main"));
}

function lightboxControlOwnsKeyboardEvent(event) {
  const target = event.target;
  if (!(target instanceof Element)) return false;
  const video = target.closest("video");
  if (event.code === "Space") {
    return Boolean(video) || isInteractiveControlTarget(target);
  }
  return Boolean(video) && ["ArrowLeft", "ArrowRight", "Home", "End"].includes(event.key);
}

function commandWorkspaceName(route = visibleWorkspaceRoute()) {
  return {
    gallery: state.mediaKind === "video" ? "视频图库" : "照片图库",
    review: state.review.mode === "queue" ? "建议审核队列" : "建议审核",
    training: "训练工程",
    slimming: state.slimming.view === "recycle" ? "图库瘦身回收站" : "图库瘦身",
    worldMap: "照片世界",
    galleryOverview: "图库总览",
  }[route] || "图库";
}

function commandContextSnapshot() {
  const route = visibleWorkspaceRoute();
  const lightboxOpen = !elements.lightbox.classList.contains("hidden");
  return {
    route,
    lightboxContext: lightboxOpen ? state.lightboxContext : null,
    lightboxOpen,
    label: lightboxOpen ? `全屏预览 · ${commandWorkspaceName(route)}` : commandWorkspaceName(route),
  };
}

function commandContextRoute() {
  return state.commandContext?.route || visibleWorkspaceRoute();
}

function commandContextHasLightbox() {
  return Boolean(state.commandContext?.lightboxOpen)
    && !elements.lightbox.classList.contains("hidden");
}

function commandReturnTitle() {
  if (commandContextHasLightbox()) return "关闭全屏预览";
  const route = commandContextRoute();
  const button = {
    review: elements.closeReviewButton,
    training: elements.closeTrainingButton,
    slimming: elements.closeSlimmingButton,
    worldMap: elements.closeWorldMapButton,
    galleryOverview: elements.closeGalleryOverviewButton,
  }[route];
  return button?.getAttribute("aria-label") || "返回图库";
}

function commandRefreshTitle() {
  return `刷新${commandWorkspaceName(commandContextRoute())}`;
}

function focusWorkspacePrimaryControl(route = visibleWorkspaceRoute()) {
  let target = null;
  if (route === "gallery") {
    const assetID = state.selectionMode && state.selectedAssetIDs.size === 1
      ? [...state.selectedAssetIDs][0]
      : state.selectedAssetID;
    target = assetID ? assetCardFocusTarget(assetID) : elements.searchInput;
  } else if (route === "review") {
    target = state.review.mode === "queue" && state.review.selectedIndex >= 0
      ? reviewCardMainButton(elements.reviewGrid.querySelector(
        `[data-review-index="${state.review.selectedIndex}"]`
      ))
      : elements.reviewOverviewGrid.querySelector(
        "[data-review-overview-tag-id][tabindex=\"0\"]:not(:disabled)"
      );
    target ||= elements.closeReviewButton;
  } else if (route === "training") {
    target = state.training.selectedRunID
      ? elements.trainingRunList.querySelector(
        `[data-training-run-id="${CSS.escape(state.training.selectedRunID)}"]`
      )
      : null;
    target ||= elements.refreshTrainingButton || elements.closeTrainingButton;
  } else if (route === "slimming") {
    const memberID = [...state.slimming.selectedMemberIDs][0];
    target = memberID ? slimmingMemberMainButton(elements.slimmingMemberGrid.querySelector(
      `[data-slimming-member-id="${CSS.escape(memberID)}"]`
    )) : null;
    target ||= state.slimming.selectedClusterID
      ? elements.slimmingClusterList.querySelector(
        `[data-slimming-cluster-id="${CSS.escape(state.slimming.selectedClusterID)}"]`
      )
      : null;
    target ||= state.slimming.selectedJobID
      ? elements.slimmingJobList.querySelector(
        `[data-slimming-job-id="${CSS.escape(state.slimming.selectedJobID)}"]`
      )
      : null;
    target ||= elements.closeSlimmingButton;
  } else if (route === "worldMap") {
    target = elements.closeWorldMapButton;
  } else if (route === "galleryOverview") {
    target = elements.closeGalleryOverviewButton;
  }
  restoreOverlayFocus(target || elements.commandButton);
}

function commandPaletteBaseLevelFromHistory(context = {}) {
  return ["sidebar", "inspector", "lightbox"].includes(context.commandPaletteBaseLevel)
    ? context.commandPaletteBaseLevel
    : "workspace";
}

function replaceCommandPaletteHistoryWithBase(baseLevel) {
  if (!state.workspaceNavigation.initialized
    || elements.appView.classList.contains("hidden")) return;
  const current = activeWorkspaceHistoryEntry();
  const route = visibleWorkspaceRoute();
  if (current?.route !== route || current.navigationLevel !== "commandPalette") return;
  const context = currentWorkspaceHistoryContext(route);
  if (context && typeof context === "object") delete context.commandPaletteBaseLevel;
  const navigationLevel = visibleWorkspaceNavigationBaseLevel(route, baseLevel);
  history.replaceState({
    ...(history.state || {}),
    [WORKSPACE_HISTORY_KEY]: workspaceHistoryEntry(route, context, navigationLevel),
  }, "", location.href);
}

function closeCommandPalette({ restoreFocus = true, checkpoint = true } = {}) {
  if (!elements.commandPalette.open) return;
  const baseLevel = state.commandPaletteBaseLevel;
  const returnFocus = state.commandReturnFocus;
  state.commandReturnFocus = null;
  state.commandContext = null;
  state.commandPaletteBaseLevel = "workspace";
  elements.commandPalette.close();
  syncCommandPaletteAccessibility();
  if (restoreFocus) {
    restoreOverlayFocus(stableReturnFocusTarget(returnFocus, elements.commandButton));
  }
  if (checkpoint) replaceCommandPaletteHistoryWithBase(baseLevel);
}

function returnFromCommandPalette({ restoreFocus = true } = {}) {
  if (!elements.commandPalette.open) return Promise.resolve();
  state.commandPaletteHistoryRestoreFocus = restoreFocus;
  if (state.workspaceNavigation.pendingReturnPromise) {
    return state.workspaceNavigation.pendingReturnPromise;
  }
  const current = activeWorkspaceHistoryEntry();
  if (state.workspaceNavigation.initialized
    && current?.route === visibleWorkspaceRoute()
    && current.navigationLevel === "commandPalette") {
    const pending = new Promise((resolve) => {
      state.workspaceNavigation.pendingReturnResolve = resolve;
    });
    state.workspaceNavigation.pendingReturnPromise = pending;
    history.back();
    return pending;
  }
  closeCommandPalette({ restoreFocus });
  state.commandPaletteHistoryRestoreFocus = true;
  return Promise.resolve();
}

async function reconcileCommandPaletteFromWorkspaceHistory(
  route,
  navigationLevel,
  context = {}
) {
  const shouldOpen = navigationLevel === "commandPalette"
    && route === visibleWorkspaceRoute();
  if (shouldOpen) {
    await openCommandPalette({
      historyMode: "none",
      baseLevel: commandPaletteBaseLevelFromHistory(context),
    });
  } else if (elements.commandPalette.open) {
    const restoreFocus = state.commandPaletteHistoryRestoreFocus;
    closeCommandPalette({ restoreFocus, checkpoint: false });
    state.commandPaletteHistoryRestoreFocus = true;
  }
}

function keyboardShortcutsContextSnapshot(baseLevel = "workspace") {
  const route = visibleWorkspaceRoute();
  const lightboxOpen = baseLevel === "lightbox"
    && !elements.lightbox.classList.contains("hidden");
  return {
    route,
    label: lightboxOpen
      ? `全屏预览 · ${commandWorkspaceName(route)}`
      : commandWorkspaceName(route),
    lightboxOpen,
    lightboxContext: lightboxOpen ? state.lightboxContext : null,
    mediaKind: lightboxOpen ? lightboxMediaKind() : null,
    reviewMode: route === "review" ? state.review.mode : null,
    slimmingView: route === "slimming" ? state.slimming.view : null,
    worldMapDetailOpen: route === "worldMap"
      && !elements.worldMapDetail.classList.contains("hidden"),
  };
}

function keyboardShortcutSections(context) {
  const globalShortcuts = [
    { id: "commandPalette", title: "打开命令面板", keys: ["⌘K"] },
    { id: "commandNavigation", title: "命令选择、首尾与翻页", keys: ["↑ ↓", "Home End", "Page Up Down"] },
    { id: "search", title: "返回图库并搜索", keys: ["⌘F"] },
    { id: "settings", title: "打开通用设置", keys: ["⌘,"] },
    { id: "activity", title: "打开或关闭活动", keys: ["J"] },
    { id: "undo", title: "撤销最近标签或审核操作", keys: ["⌘Z"] },
    { id: "shortcuts", title: "查看当前工作区快捷键", keys: ["?"] },
  ];

  let contextualShortcuts = [];
  if (context.lightboxOpen) {
    contextualShortcuts = [
      { id: "previewNavigate", title: "上一项或下一项", keys: ["← →"] },
      { id: "previewClose", title: "关闭预览并返回原位置", keys: ["Space", "Esc"] },
      ...(context.mediaKind !== "video" ? [{
        id: "previewZoom",
        title: "放大、缩小或适应窗口",
        keys: ["+", "−", "0"],
      }] : []),
      ...(["library", "review", "slimming"].includes(context.lightboxContext) ? [{
        id: "previewDelete",
        title: "删除当前项目并由 Mac 确认",
        keys: ["Delete"],
      }] : []),
      ...(context.lightboxContext === "review" ? [{
        id: "previewReviewDecision",
        title: "审核属于、不属于或稍后",
        keys: ["P", "X", "U"],
      }] : []),
    ];
  } else if (context.route === "gallery") {
    contextualShortcuts = [
      { id: "gallerySelectAll", title: "全选当前已载入项目", keys: ["⌘A"] },
      { id: "galleryNavigate", title: "移动主选择、翻页或扩展连续选择", keys: ["← ↑ ↓ →", "Page Up Down", "Shift"] },
      { id: "galleryPreview", title: "切换单图查看", keys: ["Space"] },
      { id: "galleryDelete", title: "删除所选项目并由 Mac 确认", keys: ["Delete"] },
      { id: "sidebarNavigate", title: "侧栏逐项、翻页与首尾导航", keys: ["↑ ↓", "Page Up Down", "Home End"] },
      { id: "tagNavigate", title: "标签按视觉位置、翻页与首尾导航", keys: ["← ↑ ↓ →", "Page Up Down", "Home End"] },
    ];
  } else if (context.route === "review") {
    contextualShortcuts = context.reviewMode === "queue" ? [
      { id: "reviewSelectAll", title: "全选当前已载入审核项", keys: ["⌘A"] },
      { id: "reviewNavigate", title: "移动主审核项、翻页或扩展选择", keys: ["← ↑ ↓ →", "Page Up Down", "Shift"] },
      { id: "reviewPreview", title: "预览当前审核项", keys: ["Space"] },
      { id: "reviewDecision", title: "确认属于、不属于或稍后", keys: ["P", "X", "U"] },
      { id: "reviewDelete", title: "删除所选审核项并由 Mac 确认", keys: ["Delete"] },
      { id: "reviewReturn", title: "退出选择模式或返回图库", keys: ["Esc"] },
    ] : [
      { id: "reviewOpenQueue", title: "打开聚焦的审核队列", keys: ["Enter"] },
      { id: "reviewReturn", title: "返回图库", keys: ["Esc"] },
    ];
  } else if (context.route === "training") {
    contextualShortcuts = [
      { id: "trainingPrimary", title: "新建任务、刷新或显示记录栏", keys: ["N", "R", "L"] },
      { id: "trainingScope", title: "切换全部、批次或单项范围", keys: ["B"] },
      { id: "trainingModel", title: "定位模型槽", keys: ["M"] },
      { id: "trainingFollowup", title: "打开审核或重新配置失败任务", keys: ["V", "E"] },
      { id: "trainingNavigate", title: "训练记录逐条、翻页与首尾导航", keys: ["↑ ↓", "Page Up Down", "Home End"] },
      { id: "trainingOpenReturn", title: "打开任务或返回图库", keys: ["Enter", "Esc"] },
    ];
  } else if (context.route === "slimming") {
    contextualShortcuts = context.slimmingView === "analysis" ? [
      { id: "slimmingSelectAll", title: "全选当前候选组成员", keys: ["⌘A"] },
      { id: "slimmingNavigate", title: "移动候选成员、翻页或扩展选择", keys: ["← ↑ ↓ →", "Page Up Down", "Shift"] },
      { id: "slimmingPreview", title: "预览当前候选成员", keys: ["Space"] },
      { id: "slimmingDelete", title: "快速删除所选成员并由 Mac 确认", keys: ["Delete"] },
      { id: "slimmingNavigator", title: "分析记录与候选组逐条、翻页及首尾", keys: ["↑ ↓", "Page Up Down", "Home End"] },
      { id: "slimmingContextMenu", title: "打开当前记录或成员菜单", keys: ["Shift F10"] },
    ] : [
      { id: "slimmingRecycleContextMenu", title: "打开当前回收项菜单", keys: ["Shift F10"] },
      { id: "slimmingReturn", title: "返回图库", keys: ["Esc"] },
    ];
  } else if (context.route === "worldMap") {
    contextualShortcuts = [
      ...(context.worldMapDetailOpen ? [{
        id: "worldMapPhotoNavigate",
        title: "地点照片逐张、翻页或直达首尾",
        keys: ["← →", "Page Up Down", "Home End"],
      }] : []),
      {
        id: "worldMapReturn",
        title: context.worldMapDetailOpen ? "关闭地点详情或返回图库" : "返回图库",
        keys: ["Esc"],
      },
    ];
  } else if (context.route === "galleryOverview") {
    contextualShortcuts = [{
      id: "galleryOverviewReturn",
      title: "返回图库",
      keys: ["Esc"],
    }];
  }

  return [
    { id: "global", title: "全局", shortcuts: globalShortcuts },
    { id: "context", title: context.label, shortcuts: contextualShortcuts },
  ].filter((section) => section.shortcuts.length);
}

function renderKeyboardShortcuts(context) {
  elements.shortcutContextLabel.textContent = `当前：${context.label}`;
  elements.shortcutList.dataset.shortcutRoute = context.route;
  elements.shortcutList.dataset.shortcutContext = context.lightboxOpen
    ? "lightbox"
    : context.route;
  const fragment = document.createDocumentFragment();
  for (const section of keyboardShortcutSections(context)) {
    const group = document.createElement("div");
    group.className = "shortcut-group";
    group.dataset.shortcutGroup = section.id;
    const title = document.createElement("h3");
    title.textContent = section.title;
    const list = document.createElement("dl");
    for (const shortcut of section.shortcuts) {
      const row = document.createElement("div");
      row.dataset.shortcutId = shortcut.id;
      const term = document.createElement("dt");
      term.textContent = shortcut.title;
      const definition = document.createElement("dd");
      shortcut.keys.forEach((keyLabel, index) => {
        if (index) definition.append(document.createTextNode(" / "));
        const key = document.createElement("kbd");
        key.textContent = keyLabel;
        definition.append(key);
      });
      row.append(term, definition);
      list.append(row);
    }
    group.append(title, list);
    fragment.append(group);
  }
  elements.shortcutList.replaceChildren(fragment);
  elements.shortcutList.scrollTop = 0;
}

function keyboardShortcutsBaseLevelFromHistory(context = {}) {
  return ["sidebar", "inspector", "lightbox"].includes(
    context.keyboardShortcutsBaseLevel
  )
    ? context.keyboardShortcutsBaseLevel
    : "workspace";
}

function replaceKeyboardShortcutsHistoryWithBase(baseLevel) {
  if (!state.workspaceNavigation.initialized
    || elements.appView.classList.contains("hidden")) return;
  const current = activeWorkspaceHistoryEntry();
  const route = visibleWorkspaceRoute();
  if (current?.route !== route || current.navigationLevel !== "keyboardShortcuts") return;
  const context = currentWorkspaceHistoryContext(route);
  if (context && typeof context === "object") delete context.keyboardShortcutsBaseLevel;
  const navigationLevel = visibleWorkspaceNavigationBaseLevel(route, baseLevel);
  history.replaceState({
    ...(history.state || {}),
    [WORKSPACE_HISTORY_KEY]: workspaceHistoryEntry(route, context, navigationLevel),
  }, "", location.href);
}

function openKeyboardShortcuts({
  focus = true,
  historyMode = "pushKeyboardShortcuts",
  baseLevel = null,
  returnFocus = null,
} = {}) {
  if (elements.shortcutDialog.open || state.keyboardShortcutsOpening
    || elements.appView.classList.contains("hidden")) return;
  state.keyboardShortcutsOpening = true;
  try {
    state.keyboardShortcutsReturnFocus = returnFocus
      || (document.activeElement instanceof HTMLElement ? document.activeElement : null);
    const current = activeWorkspaceHistoryEntry();
    state.keyboardShortcutsBaseLevel = baseLevel
      || workspaceNavigationBaseLevel(
        current?.navigationLevel || "workspace",
        current?.context || {}
      );
    state.keyboardShortcutsContext = keyboardShortcutsContextSnapshot(
      state.keyboardShortcutsBaseLevel
    );
    renderKeyboardShortcuts(state.keyboardShortcutsContext);
    elements.shortcutDialog.showModal();
    if (historyMode !== "none") {
      const route = visibleWorkspaceRoute();
      recordWorkspaceHistory(route, currentWorkspaceHistoryContext(route), historyMode);
    }
    if (focus) restoreOverlayFocus(elements.closeShortcutButton);
  } finally {
    state.keyboardShortcutsOpening = false;
  }
}

function closeKeyboardShortcuts({ restoreFocus = true, checkpoint = true } = {}) {
  if (!elements.shortcutDialog.open) return;
  const baseLevel = state.keyboardShortcutsBaseLevel;
  const returnFocus = state.keyboardShortcutsReturnFocus;
  state.keyboardShortcutsReturnFocus = null;
  state.keyboardShortcutsBaseLevel = "workspace";
  state.keyboardShortcutsContext = null;
  elements.shortcutDialog.close();
  if (restoreFocus) {
    const toolbarFallback = stableReturnFocusTarget(
      elements.shortcutButton,
      elements.commandButton
    );
    restoreOverlayFocus(stableReturnFocusTarget(returnFocus, toolbarFallback));
  }
  if (checkpoint) replaceKeyboardShortcutsHistoryWithBase(baseLevel);
}

function returnFromKeyboardShortcuts({ restoreFocus = true } = {}) {
  if (!elements.shortcutDialog.open) return Promise.resolve();
  state.keyboardShortcutsHistoryRestoreFocus = restoreFocus;
  if (state.workspaceNavigation.pendingReturnPromise) {
    return state.workspaceNavigation.pendingReturnPromise;
  }
  const current = activeWorkspaceHistoryEntry();
  if (state.workspaceNavigation.initialized
    && current?.route === visibleWorkspaceRoute()
    && current.navigationLevel === "keyboardShortcuts") {
    const pending = new Promise((resolve) => {
      state.workspaceNavigation.pendingReturnResolve = resolve;
    });
    state.workspaceNavigation.pendingReturnPromise = pending;
    history.back();
    return pending;
  }
  closeKeyboardShortcuts({ restoreFocus });
  state.keyboardShortcutsHistoryRestoreFocus = true;
  return Promise.resolve();
}

function reconcileKeyboardShortcutsFromWorkspaceHistory(
  route,
  navigationLevel,
  context = {}
) {
  const shouldOpen = navigationLevel === "keyboardShortcuts"
    && route === visibleWorkspaceRoute();
  if (shouldOpen) {
    openKeyboardShortcuts({
      historyMode: "none",
      baseLevel: keyboardShortcutsBaseLevelFromHistory(context),
    });
  } else if (elements.shortcutDialog.open) {
    const restoreFocus = state.keyboardShortcutsHistoryRestoreFocus;
    closeKeyboardShortcuts({ restoreFocus, checkpoint: false });
    state.keyboardShortcutsHistoryRestoreFocus = true;
  }
}

async function navigateCommandToGallery({ focus = false } = {}) {
  const route = visibleWorkspaceRoute();
  const lightboxOpen = !elements.lightbox.classList.contains("hidden");
  if (route !== "gallery") {
    recordWorkspaceHistory(route, currentWorkspaceHistoryContext(route), "replace");
  }
  if (lightboxOpen) closeLightbox({ restoreFocus: false });
  if (route !== "gallery") {
    closeAllWorkspacesToGallery({ restoreFocus: false });
    recordWorkspaceHistory("gallery", null, "push");
  }
  if (focus) focusWorkspacePrimaryControl("gallery");
}

async function focusLibrarySearch() {
  await navigateCommandToGallery();
  elements.searchInput.focus({ preventScroll: true });
  elements.searchInput.select();
}

async function openWorkspaceFromCommand(target) {
  const current = visibleWorkspaceRoute();
  const lightboxOpen = !elements.lightbox.classList.contains("hidden");
  if (lightboxOpen) closeLightbox({ restoreFocus: false });
  if (target === "gallery") {
    await navigateCommandToGallery({ focus: true });
    return;
  }
  if (current === target) {
    focusWorkspacePrimaryControl(target);
    return;
  }
  if (current !== "gallery") {
    recordWorkspaceHistory(current, currentWorkspaceHistoryContext(current), "replace");
  }
  closeAllWorkspacesToGallery({ restoreFocus: false });
  if (target === "review") await openReviewWorkspace();
  else if (target === "training") await openTrainingWorkspace();
  else if (target === "slimming") await openSlimmingWorkspace();
  else if (target === "worldMap") await openWorldMapWorkspace();
  else if (target === "galleryOverview") await openGalleryOverviewWorkspace();
}

async function returnFromCommandContext() {
  if (!elements.lightbox.classList.contains("hidden")) {
    await returnFromLightbox();
    return;
  }
  const route = visibleWorkspaceRoute();
  if (route !== "gallery") await returnFromWorkspace(route);
}

async function refreshCommandContext() {
  const route = commandContextRoute();
  if (route === "review") {
    await Promise.all([
      supportsGeneralSettings() ? loadGeneralSettings({ quiet: true }) : Promise.resolve(),
      loadTagLibrarySuggestions({ quiet: true }),
      loadSampleSuggestions({ quiet: true }),
      loadLibrarySuggestions({ quiet: true }),
      loadReviewOverview(),
    ]);
    if (state.review.mode === "queue") {
      await loadReviewQueue({
        preserveLoadedWindow: true,
        preserveUnchangedGrid: true,
      });
    }
  } else if (route === "training") {
    await loadTrainingWorkspace();
  } else if (route === "slimming") {
    if (state.slimming.view === "recycle") await loadSlimmingRecycle();
    else {
      await Promise.all([
        loadSlimmingWorkspace(),
        loadSlimmingRemovals({ quiet: true }),
        loadSlimmingIdenticalCleanupRequests({ quiet: true }),
      ]);
    }
  } else if (route === "worldMap") {
    await loadWorldMapSnapshot({ bounds: state.worldMap.viewport });
    if (state.worldMap.selectedClusterID) {
      await loadWorldMapSelection(state.worldMap.selectedClusterID);
    }
  } else if (route === "galleryOverview") {
    await loadGalleryOverview();
  } else {
    await refreshWorkspace();
  }
}

async function switchCommandMediaKind(mediaKind) {
  const route = commandContextRoute();
  if (route === "training") {
    await switchTrainingMediaKind(mediaKind);
  } else if (route === "slimming") {
    await switchSlimmingMediaKind(mediaKind);
  } else {
    await switchMediaKind(mediaKind);
    if (route === "review") {
      await loadReviewOverview();
      if (state.review.mode === "queue") {
        await loadReviewQueue({ preserveLoadedWindow: true });
      }
    }
  }
}

function commandSelectionContext(route = commandContextRoute()) {
  if (commandContextHasLightbox()) return null;
  if (route === "gallery") {
    const selectedIDs = state.selectionMode
      ? [...state.selectedAssetIDs]
      : (state.selectedAssetID ? [state.selectedAssetID] : []);
    return {
      route,
      noun: currentMediaNoun(),
      allIDs: state.assets.map((asset) => asset.id),
      selectedIDs,
      primaryID: selectedIDs.length === 1 ? selectedIDs[0] : state.selectedAssetID,
    };
  }
  if (route === "review" && state.review.mode === "queue") {
    const selectedIDs = [...state.review.selectedAssetIDs];
    const primaryItem = state.review.items[state.review.selectedIndex];
    return {
      route,
      noun: "审核项",
      allIDs: state.review.items.map((item) => item.assetID),
      selectedIDs,
      primaryID: primaryItem?.assetID
        || selectedIDs[0]
        || null,
      primaryReviewKey: reviewItemKey(primaryItem),
    };
  }
  if (route === "slimming" && state.slimming.view === "analysis") {
    const selectedIDs = [...state.slimming.selectedMemberIDs];
    return {
      route,
      noun: "候选成员",
      allIDs: state.slimming.members.map((member) => member.id),
      selectedIDs,
      primaryID: slimmingSelectionPrimaryID(),
    };
  }
  return null;
}

function selectAllCommandContext(route) {
  if (route === "review") {
    selectAllReviewItems();
  } else if (route === "slimming") {
    selectAllSlimmingMembers();
  } else {
    selectAllLoadedAssets();
  }
}

function previewCommandContext(route, context = commandSelectionContext(route)) {
  if (!context?.primaryID) return;
  const options = { preserveSelection: context.selectedIDs.length > 1 };
  if (route === "review") {
    const item = state.review.items.find(
      (candidate) => reviewItemKey(candidate) === context.primaryReviewKey
    );
    openReviewLightbox(item, options);
    return;
  }
  openLightbox(route === "slimming" ? "slimming" : "library", context.primaryID, options);
}

