function commandItemFingerprint(command, index) {
  return JSON.stringify([
    command.id,
    command.icon,
    command.title,
    command.hint,
    Boolean(command.disabled),
    index === state.commandIndex,
  ]);
}

function syncCommandItem(button, command, index, fingerprint) {
  button.type = "button";
  button.id = `command-item-${command.id}`;
  button.classList.add("command-item");
  button.dataset.commandId = command.id;
  button.dataset.commandFingerprint = fingerprint;
  button.classList.toggle("active", index === state.commandIndex);
  button.disabled = Boolean(command.disabled);
  button.setAttribute("role", "option");
  button.setAttribute("aria-selected", String(index === state.commandIndex));
  button.setAttribute("aria-disabled", String(Boolean(command.disabled)));

  let icon = button.querySelector(":scope > .command-item-icon");
  if (!icon) {
    icon = document.createElement("span");
    icon.className = "command-item-icon";
    button.append(icon);
  }
  icon.textContent = command.icon;
  let title = button.querySelector(":scope > .command-item-title");
  if (!title) {
    title = document.createElement("span");
    title.className = "command-item-title";
    button.append(title);
  }
  title.textContent = command.title;
  let hint = button.querySelector(":scope > .command-item-hint");
  if (!hint) {
    hint = document.createElement("small");
    hint.className = "command-item-hint";
    button.append(hint);
  }
  hint.textContent = command.hint;
}

function syncCommandPaletteAccessibility() {
  const expanded = elements.commandPalette.open;
  elements.commandSearchInput.setAttribute("aria-expanded", String(expanded));
  const active = expanded
    ? elements.commandList.querySelector(":scope > .command-item.active")
    : null;
  if (active?.id) {
    elements.commandSearchInput.setAttribute("aria-activedescendant", active.id);
  } else {
    elements.commandSearchInput.removeAttribute("aria-activedescendant");
  }
}

function renderCommandItems() {
  if (!elements.commandList) return;
  const scrollTop = elements.commandList.scrollTop;
  const query = elements.commandSearchInput.value.trim().toLocaleLowerCase("zh-CN");
  state.commandItems = availableCommands().filter(
    (command) => !query || command.title.toLocaleLowerCase("zh-CN").includes(query)
  );
  state.commandIndex = Math.max(0, Math.min(
    state.commandIndex,
    Math.max(0, state.commandItems.length - 1)
  ));
  if (state.commandItems[state.commandIndex]?.disabled) {
    const firstEnabled = state.commandItems.findIndex((command) => !command.disabled);
    state.commandIndex = firstEnabled >= 0 ? firstEnabled : 0;
  }
  if (!state.commandItems.length) {
    const empty = elements.commandList.querySelector(":scope > .command-empty")
      || document.createElement("div");
    empty.className = "command-empty";
    empty.textContent = `没有与“${elements.commandSearchInput.value.trim()}”匹配的命令`;
    reconcileStableChildren(elements.commandList, [empty]);
    elements.commandList.scrollTop = scrollTop;
    syncCommandPaletteAccessibility();
    return;
  }
  const existingItems = new Map(
    [...elements.commandList.querySelectorAll(":scope > [data-command-id]")]
      .map((button) => [button.dataset.commandId, button])
  );
  const wantedItems = state.commandItems.map((command, index) => {
    const button = existingItems.get(command.id) || document.createElement("button");
    const fingerprint = commandItemFingerprint(command, index);
    if (button.dataset.commandFingerprint !== fingerprint) {
      syncCommandItem(button, command, index, fingerprint);
    }
    return button;
  });
  reconcileStableChildren(elements.commandList, wantedItems);
  elements.commandList.scrollTop = scrollTop;
  syncCommandPaletteAccessibility();
}

function moveCommandSelection(direction) {
  if (!state.commandItems.length) return;
  let next = state.commandIndex;
  for (let remaining = state.commandItems.length; remaining > 0; remaining -= 1) {
    next = (next + direction + state.commandItems.length) % state.commandItems.length;
    if (!state.commandItems[next].disabled) {
      state.commandIndex = next;
      return;
    }
  }
}

function moveCommandSelectionToBoundary(boundary) {
  const direction = boundary === "end" ? -1 : 1;
  let next = boundary === "end" ? state.commandItems.length - 1 : 0;
  while (next >= 0 && next < state.commandItems.length) {
    if (!state.commandItems[next].disabled) {
      state.commandIndex = next;
      return;
    }
    next += direction;
  }
}

function commandPageStep() {
  const item = elements.commandList.querySelector(":scope > .command-item");
  const itemHeight = item?.getBoundingClientRect().height || 0;
  if (!itemHeight || !elements.commandList.clientHeight) return 1;
  return Math.max(1, Math.floor(elements.commandList.clientHeight / itemHeight) - 1);
}

function moveCommandSelectionByPage(direction) {
  if (!state.commandItems.length) return;
  const lastIndex = state.commandItems.length - 1;
  const target = Math.max(0, Math.min(
    state.commandIndex + direction * commandPageStep(),
    lastIndex
  ));
  for (let next = target; next >= 0 && next <= lastIndex; next += direction) {
    if (!state.commandItems[next].disabled) {
      state.commandIndex = next;
      return;
    }
  }
  for (let next = target - direction; next >= 0 && next <= lastIndex; next -= direction) {
    if (!state.commandItems[next].disabled) {
      state.commandIndex = next;
      return;
    }
  }
}

function revealActiveCommandItem() {
  elements.commandList.querySelector(":scope > .command-item.active")?.scrollIntoView({
    block: "nearest",
    inline: "nearest",
  });
}

async function executeSourceCommandAction(action, sourceID, returnFocus) {
  await submitSourceManagementAction(action, sourceID || null);
  const source = sourceID
    ? elements.sourceList.querySelector(`[data-source-id="${CSS.escape(sourceID)}"]`)
    : null;
  restoreOverlayFocus(stableReturnFocusTarget(
    returnFocus,
    source || elements.commandButton
  ));
}

async function executeCommand(commandID) {
  const command = availableCommands().find((item) => item.id === commandID);
  if (!command || command.disabled) return;
  const contextRoute = commandContextRoute();
  const selectionContext = commandSelectionContext(contextRoute);
  const commandReturnFocus = state.commandReturnFocus;
  await returnFromCommandPalette({ restoreFocus: false });
  if (commandID.startsWith("media:")) {
    await switchCommandMediaKind(commandID.slice(6));
    return;
  }
  if (commandID.startsWith("source:")) {
    await navigateCommandToGallery();
    await selectSource(commandID.slice(7));
    return;
  }
  if (commandID.startsWith("tag:")) {
    await navigateCommandToGallery();
    await applyQuickTagFilter(commandID.slice(4));
    return;
  }
  if (commandID.startsWith("tagAction:")) {
    const [, action, tagID] = commandID.split(":");
    if (state.selectionMode) await applyBatchTagDecision(action, tagID);
    else await mutateTag(tagID, action);
    return;
  }
  if (commandID.startsWith("sourceAction:")) {
    const [, action, sourceID] = commandID.split(":");
    await executeSourceCommandAction(action, sourceID, commandReturnFocus);
    return;
  }
  switch (commandID) {
  case "returnWorkspace":
    await returnFromCommandContext();
    break;
  case "refresh":
    await refreshCommandContext();
    break;
  case "showAll":
    await navigateCommandToGallery();
    state.filters = emptyFilters();
    state.filters.mediaKind = state.mediaKind;
    state.filterDraft = null;
    syncFilterControlsFromState();
    renderTagNavigation();
    await selectSource("");
    break;
  case "showFavorites":
    await navigateCommandToGallery();
    await applyFavoritesFilter();
    break;
  case "retryFavoriteSync":
    await retryFavoriteSync();
    break;
  case "showUntagged":
    await navigateCommandToGallery();
    if (state.filters.tagPresence !== "untagged") await applyUntaggedFilter();
    break;
  case "focusSearch":
    await focusLibrarySearch();
    break;
  case "openFilter":
    await navigateCommandToGallery();
    toggleFilterPopover();
    break;
  case "openReviewSources":
    openActionMenu("reviewSources");
    break;
  case "newTrainingTask":
    await openTrainingSetupDialog({
      returnFocus: commandReturnFocus || elements.newTrainingButton,
    });
    break;
  case "toggleTrainingNavigator":
    toggleTrainingNavigator();
    break;
  case "openSlimmingSetup":
    await openSlimmingSetupDialog(
      commandReturnFocus || elements.slimmingAnalysisOptionsButton
    );
    break;
  case "openSlimmingThresholdEditor":
    await openSlimmingThresholdEditor(
      commandReturnFocus || elements.slimmingAnalysisOptionsButton
    );
    break;
  case "toggleSlimmingNavigator":
    toggleSlimmingNavigator();
    break;
  case "showSlimmingRecycle":
    await setSlimmingView("recycle");
    break;
  case "showSlimmingAnalysis":
    await setSlimmingView("analysis");
    break;
  case "openWorldMapPlaceTags":
    openWorldMapPlaceTags(elements.openWorldMapPlaceTagsButton);
    break;
  case "openWorldMapLocationBackfill":
    openWorldMapLocationBackfill(elements.openWorldMapLocationBackfillButton);
    break;
  case "browseWorldMapCluster":
    await openWorldMapClusterInGallery();
    break;
  case "selectAll":
    selectAllCommandContext(contextRoute);
    break;
  case "favoriteSelection":
    await applyFavoriteMutation(
      commandSelectionContext(contextRoute)?.selectedIDs || [],
      true
    );
    break;
  case "unfavoriteSelection":
    await applyFavoriteMutation(
      commandSelectionContext(contextRoute)?.selectedIDs || [],
      false
    );
    break;
  case "undoTag":
    await undoLatestDecision("tag");
    break;
  case "undoReview":
    await undoLatestDecision("review");
    break;
  case "previewSelection": {
    previewCommandContext(contextRoute, selectionContext);
    break;
  }
  case "reviewAcceptSelection":
    await applyReviewDecision("accept");
    break;
  case "reviewRejectSelection":
    await applyReviewDecision("reject");
    break;
  case "reviewDeferSelection":
    await deferReviewSelection();
    break;
  case "deleteReviewSelection":
    await submitGalleryRemoval({
      assetIDs: commandSelectionContext("review")?.selectedIDs || [],
      surface: "review",
      returnFocus: { element: elements.reviewInspectorDeleteButton },
    });
    break;
  case "recycleSlimmingSelection":
    await submitSlimmingRemoval("recoverableRecycle");
    break;
  case "releaseSlimmingSelection":
    await submitSlimmingRemoval("releaseSourceSpace");
    break;
  case "newTag":
    if (!focusInlineTagCreationFromCommand(commandReturnFocus)) {
      presentNewTagDialog({ returnFocus: commandReturnFocus });
    }
    break;
  case "prepareSelectedFeatures":
    await prepareSelectedFeatures();
    break;
  case "generateSelectedSuggestions":
    await generateSampleSuggestions({ useSelection: true });
    break;
  case "generateLibrarySuggestions":
    if (state.librarySuggestions.snapshot?.personalMode === "fullLibrary") {
      await openWorkspaceFromCommand("review");
      await submitLibrarySuggestions("personal");
    } else {
      await openWorkspaceFromCommand("review");
      await generateSampleSuggestions();
    }
    break;
  case "generateStandardLibrarySuggestions":
    await openWorkspaceFromCommand("review");
    await submitLibrarySuggestions("standard");
    break;
  case "findSimilarSelection":
    await findSimilarFromSelection();
    break;
  case "deleteGallerySelection":
    {
      const context = commandSelectionContext("gallery");
      await submitGalleryRemoval({
        assetIDs: context?.selectedIDs || [],
        returnFocus: { element: assetCardFocusTarget(context?.primaryID) },
      });
    }
    break;
  case "connectFolder":
    await openSourceManager();
    await submitSourceManagementAction("connectFolder");
    break;
  case "installPresetTags":
    await installPresetTags(elements.commandButton);
    break;
  case "openReview":
    await openWorkspaceFromCommand("review");
    break;
  case "openGalleryOverview":
    await openWorkspaceFromCommand("galleryOverview");
    break;
  case "openWorldMap":
    await openWorkspaceFromCommand("worldMap");
    break;
  case "openTraining":
    await openWorkspaceFromCommand("training");
    break;
  case "openSlimming":
    await openWorkspaceFromCommand("slimming");
    break;
  case "rebuildPersonalModel":
    await navigateCommandToGallery();
    await openLibraryPersonalTraining("personalCentroid");
    break;
  case "rebuildPersonalAdamW":
    await navigateCommandToGallery();
    await openLibraryPersonalTraining("personalAdamW");
    break;
  case "openStorage":
    await openStorageMaintenance();
    break;
  case "openSettings":
    await openGeneralSettings();
    break;
  case "exportPortableData":
    await openStorageMaintenance();
    await submitStorageMaintenanceAction("exportPortableData");
    break;
  case "chooseExternalStorage":
    await openStorageMaintenance();
    await submitStorageMaintenanceAction("chooseExternalStorage");
    break;
  case "openJobs":
    openJobsPopover({
      returnFocus: commandReturnFocus || elements.jobsButton,
    });
    break;
  case "toggleSidebar":
    await toggleSidebarVisibility(commandReturnFocus || elements.commandButton);
    break;
  case "toggleInspector":
    await toggleInspectorVisibility(commandReturnFocus || elements.commandButton);
    break;
  case "refreshAllSources":
    await executeSourceCommandAction("refreshAll", null, commandReturnFocus);
    break;
  case "prewarmAllSources":
    await executeSourceCommandAction("prewarmAllThumbnails", null, commandReturnFocus);
    break;
  case "prewarmAllOriginalSources":
    await executeSourceCommandAction("prewarmAllOriginalAspect", null, commandReturnFocus);
    break;
  case "reauthorizeAllSources":
    await executeSourceCommandAction("reauthorizeAll", null, commandReturnFocus);
    break;
  case "refreshAllFolderMutationAuthorizations":
    await executeSourceCommandAction(
      "refreshAllFolderMutationAuthorizations",
      null,
      commandReturnFocus
    );
    break;
  case "shortcuts":
    openKeyboardShortcuts({ returnFocus: commandReturnFocus || elements.commandButton });
    break;
  default:
    break;
  }
}

async function openCommandPalette({
  focus = true,
  historyMode = "pushCommandPalette",
  baseLevel = null,
} = {}) {
  if (elements.commandPalette.open || state.commandPaletteOpening) return;
  state.commandPaletteOpening = true;
  const returnFocus = document.activeElement instanceof HTMLElement
    ? document.activeElement
    : null;
  try {
    if (compactToolbarMenuIsOpen()) {
      await returnFromCompactToolbarMenu({ restoreFocus: false });
    }
    if (elements.commandPalette.open || elements.appView.classList.contains("hidden")) return;
    state.commandReturnFocus = returnFocus;
    const current = activeWorkspaceHistoryEntry();
    const replacesActionMenu = historyMode === "pushCommandPalette"
      && current?.navigationLevel === "actionMenu";
    state.commandPaletteBaseLevel = baseLevel
      || workspaceNavigationBaseLevel(
        current?.navigationLevel || "workspace",
        current?.context || {}
      );
    state.commandContext = commandContextSnapshot();
    closeLayoutMenu({ restoreFocus: false });
    closeFilterPopover({ restoreFocus: false });
    closeActionMenu({ restoreFocus: false, checkpoint: !replacesActionMenu });
    closeJobsPopover({
      restoreFocus: false,
      checkpoint: false,
      preserveState: true,
    });
    hideContextMenus();
    elements.commandSearchInput.value = "";
    state.commandIndex = 0;
    elements.commandContextLabel.textContent = `当前：${state.commandContext.label}`;
    renderCommandItems();
    elements.commandPalette.showModal();
    syncCommandPaletteAccessibility();
    if (historyMode !== "none") {
      const route = visibleWorkspaceRoute();
      recordWorkspaceHistory(
        route,
        currentWorkspaceHistoryContext(route),
        replacesActionMenu ? "replaceOverlay" : historyMode
      );
    }
    if (focus) elements.commandSearchInput.focus({ preventScroll: true });
  } finally {
    state.commandPaletteOpening = false;
  }
}

function hideContextMenu() {
  elements.assetContextMenu.classList.add("hidden");
  state.contextAssetID = null;
  elements.reviewContextMenu.classList.add("hidden");
  state.contextReviewKey = null;
  elements.sourceContextMenu.classList.add("hidden");
  state.contextSourceID = null;
  elements.tagContextMenu.classList.add("hidden");
  state.contextTagID = null;
  state.contextTagGroupID = null;
  state.contextTagReturnFocus = null;
  elements.slimmingMemberContextMenu.classList.add("hidden");
  state.slimming.contextMemberID = null;
  elements.slimmingRecycleContextMenu.classList.add("hidden");
  state.slimming.contextRecycleEntryID = null;
  elements.slimmingJobContextMenu.classList.add("hidden");
  state.slimming.contextJobID = null;
}

function hideContextMenus() {
  hideContextMenu();
}

function activeContextMenuDescriptor() {
  const descriptors = [
    { kind: "asset", menu: elements.assetContextMenu },
    { kind: "review", menu: elements.reviewContextMenu },
    { kind: "slimmingMember", menu: elements.slimmingMemberContextMenu },
    { kind: "slimmingRecycle", menu: elements.slimmingRecycleContextMenu },
    { kind: "slimmingJob", menu: elements.slimmingJobContextMenu },
    { kind: "source", menu: elements.sourceContextMenu },
    { kind: "tag", menu: elements.tagContextMenu },
  ];
  return descriptors.find(({ menu }) => !menu.classList.contains("hidden")) || null;
}

function contextMenuVisualViewportBounds() {
  const viewport = globalThis.visualViewport;
  const left = viewport?.offsetLeft || 0;
  const top = viewport?.offsetTop || 0;
  const width = viewport?.width || globalThis.innerWidth;
  const height = viewport?.height || globalThis.innerHeight;
  return {
    left,
    top,
    right: left + width,
    bottom: top + height,
  };
}

function repositionActiveContextMenu() {
  const descriptor = activeContextMenuDescriptor();
  const session = state.contextMenuSession;
  if (!descriptor || !session) return;
  positionContextMenu(descriptor.menu, session.clientX, session.clientY);
}

function containContextMenuBackgroundScroll(event) {
  const descriptor = activeContextMenuDescriptor();
  if (!descriptor || event.composedPath().includes(descriptor.menu)) return;
  if (event.cancelable) event.preventDefault();
  event.stopImmediatePropagation();
}

function contextMenuActionButtons(menu) {
  return [
    ...menu.querySelectorAll(
      "button:not([hidden]):not(.hidden):not(:disabled)"
    ),
  ];
}

function focusContextMenuAction(menu, button) {
  button.focus({ preventScroll: true });
  const menuRect = menu.getBoundingClientRect();
  const buttonRect = button.getBoundingClientRect();
  const visibleTop = menuRect.top + 5;
  const visibleBottom = menuRect.bottom - 5;
  if (buttonRect.top < visibleTop) {
    menu.scrollTop += buttonRect.top - visibleTop;
  } else if (buttonRect.bottom > visibleBottom) {
    menu.scrollTop += buttonRect.bottom - visibleBottom;
  }
}

function moveContextMenuFocus(event) {
  const menu = event.currentTarget;
  if (event.key === "Escape") {
    event.preventDefault();
    event.stopPropagation();
    void returnFromContextMenu();
    return;
  }
  if (!["ArrowUp", "ArrowDown", "Home", "End"].includes(event.key)) return;
  const buttons = contextMenuActionButtons(menu);
  if (!buttons.length) return;
  event.preventDefault();
  event.stopPropagation();
  const current = buttons.indexOf(document.activeElement);
  const next = event.key === "Home" ? 0
    : event.key === "End" ? buttons.length - 1
      : current < 0
        ? (event.key === "ArrowUp" ? buttons.length - 1 : 0)
        : (current + (event.key === "ArrowUp" ? -1 : 1) + buttons.length)
          % buttons.length;
  focusContextMenuAction(menu, buttons[next]);
}

let contextMenuOutsideClickSuppression = null;

function beginContextMenuOutsideDismissal(event) {
  const descriptor = activeContextMenuDescriptor();
  if (event.button !== 0
    || !descriptor
    || event.composedPath().includes(descriptor.menu)) return;
  contextMenuOutsideClickSuppression = {
    target: event.target,
    until: performance.now() + 900,
  };
  event.preventDefault();
  event.stopImmediatePropagation();
  void returnFromContextMenu({ restoreFocus: false });
}

function dismissContextMenuFromOutside(event) {
  const suppression = contextMenuOutsideClickSuppression;
  if (suppression && performance.now() < suppression.until
    && event.composedPath().includes(suppression.target)) {
    contextMenuOutsideClickSuppression = null;
    event.preventDefault();
    event.stopImmediatePropagation();
    return;
  }
  contextMenuOutsideClickSuppression = null;
  const descriptor = activeContextMenuDescriptor();
  if (!descriptor || event.composedPath().includes(descriptor.menu)) return;
  event.preventDefault();
  event.stopImmediatePropagation();
  void returnFromContextMenu({ restoreFocus: false });
}

function contextMenuReturnFocus(session = state.contextMenuSession) {
  if (!session) return null;
  if (session.returnFocus?.isConnected) return session.returnFocus;
  if (session.kind === "asset") return assetCardFocusTarget(session.targetID);
  if (session.kind === "review") return reviewCardFocusTarget(session.targetID);
  if (session.kind === "slimmingMember") {
    return slimmingMemberMainButton(elements.slimmingMemberGrid.querySelector(
      `[data-slimming-member-id="${CSS.escape(session.targetID || "")}"]`
    ));
  }
  if (session.kind === "slimmingRecycle") {
    return slimmingRecycleFocusTarget(session.targetID);
  }
  if (session.kind === "slimmingJob") {
    return elements.slimmingJobList.querySelector(
      `[data-slimming-job-id="${CSS.escape(session.targetID || "")}"]`
    );
  }
  if (session.kind === "source") {
    return elements.sourceList.querySelector(
      `[data-source-id="${CSS.escape(session.targetID || "")}"]`
    );
  }
  if (session.kind === "tag") {
    return session.targetType === "group"
      ? elements.tagNavigation.querySelector(
          `[data-sidebar-tag-group-toggle="${CSS.escape(session.targetID || "")}"]`
        )
      : elements.tagNavigation.querySelector(
          `[data-quick-tag-id="${CSS.escape(session.targetID || "")}"]`
        );
  }
  return null;
}

function registerContextMenuSession({
  kind,
  targetID,
  clientX,
  clientY,
  returnFocus = null,
  targetType = null,
  historyMode = null,
}) {
  const current = activeWorkspaceHistoryEntry();
  const replacingContextMenu = current?.navigationLevel === "contextMenu";
  state.contextMenuBaseLevel = replacingContextMenu
    ? workspaceNavigationBaseLevel("contextMenu", current.context || {})
    : workspaceNavigationBaseLevel(
        current?.navigationLevel || "workspace",
        current?.context || {}
      );
  state.contextMenuSession = {
    kind,
    targetID,
    clientX,
    clientY,
    route: visibleWorkspaceRoute(),
    returnFocus: returnFocus instanceof HTMLElement ? returnFocus : null,
    targetType,
  };
  const resolvedHistoryMode = historyMode
    ?? (replacingContextMenu ? "replaceOverlay" : "pushContextMenu");
  if (resolvedHistoryMode !== "none") {
    const route = visibleWorkspaceRoute();
    recordWorkspaceHistory(
      route,
      currentWorkspaceHistoryContext(route),
      resolvedHistoryMode
    );
  }
}

function closeContextMenu({ restoreFocus = true, checkpoint = true } = {}) {
  const session = state.contextMenuSession;
  hideContextMenus();
  if (restoreFocus) restoreOverlayFocus(contextMenuReturnFocus(session));
  if (!checkpoint || !state.workspaceNavigation.initialized) return;
  const current = activeWorkspaceHistoryEntry();
  if (current?.navigationLevel !== "contextMenu") return;
  recordWorkspaceHistory(
    visibleWorkspaceRoute(),
    currentWorkspaceHistoryContext(),
    "replace"
  );
}

function returnFromContextMenu({ restoreFocus = true } = {}) {
  if (!activeContextMenuDescriptor()) return Promise.resolve();
  state.contextMenuHistoryRestoreFocus = restoreFocus;
  if (state.workspaceNavigation.pendingReturnPromise) {
    return state.workspaceNavigation.pendingReturnPromise;
  }
  const current = activeWorkspaceHistoryEntry();
  if (current?.route === visibleWorkspaceRoute()
    && current.navigationLevel === "contextMenu") {
    const pending = new Promise((resolve) => {
      state.workspaceNavigation.pendingReturnResolve = resolve;
    });
    state.workspaceNavigation.pendingReturnPromise = pending;
    history.back();
    return pending;
  }
  closeContextMenu({ restoreFocus });
  state.contextMenuHistoryRestoreFocus = true;
  return Promise.resolve();
}

function restoreContextMenuSession(session) {
  const options = { historyMode: "none", returnFocus: session.returnFocus };
  if (session.kind === "asset") {
    showAssetContextMenu(session.clientX, session.clientY, session.targetID, options);
  } else if (session.kind === "review") {
    showReviewContextMenu(session.clientX, session.clientY, session.targetID, options);
  } else if (session.kind === "slimmingMember") {
    showSlimmingMemberContextMenu(session.clientX, session.clientY, session.targetID, options);
  } else if (session.kind === "slimmingRecycle") {
    showSlimmingRecycleContextMenu(session.clientX, session.clientY, session.targetID, options);
  } else if (session.kind === "slimmingJob") {
    showSlimmingJobContextMenu(session.clientX, session.clientY, session.targetID, options);
  } else if (session.kind === "source") {
    showSourceContextMenu(session.clientX, session.clientY, session.targetID, options);
  } else if (session.kind === "tag") {
    if (session.targetType === "group") {
      showTagGroupContextMenu(
        session.clientX,
        session.clientY,
        session.targetID,
        session.returnFocus,
        options
      );
    } else {
      showTagContextMenu(
        session.clientX,
        session.clientY,
        session.targetID,
        session.returnFocus,
        options
      );
    }
  }
}

function reconcileContextMenuFromWorkspaceHistory(route, navigationLevel, context = {}) {
  const session = state.contextMenuSession;
  const shouldOpen = navigationLevel === "contextMenu"
    && route === visibleWorkspaceRoute()
    && session?.route === route
    && session.kind === context.contextMenuKind;
  if (shouldOpen) {
    restoreContextMenuSession(session);
    if (!activeContextMenuDescriptor()) {
      recordWorkspaceHistory(route, currentWorkspaceHistoryContext(route), "replace");
    }
  } else if (activeContextMenuDescriptor()) {
    const restoreFocus = state.contextMenuHistoryRestoreFocus;
    closeContextMenu({ restoreFocus, checkpoint: false });
    state.contextMenuHistoryRestoreFocus = true;
  }
}

function positionContextMenu(menu, clientX, clientY) {
  const bounds = contextMenuVisualViewportBounds();
  const rect = menu.getBoundingClientRect();
  const minLeft = bounds.left + 6;
  const minTop = bounds.top + 6;
  const maxLeft = Math.max(minLeft, bounds.right - rect.width - 6);
  const maxTop = Math.max(minTop, bounds.bottom - rect.height - 6);
  const left = Math.max(minLeft, Math.min(clientX, maxLeft));
  const top = Math.max(minTop, Math.min(clientY, maxTop));
  menu.style.left = `${left}px`;
  menu.style.top = `${top}px`;
}

const CONTEXT_LONG_PRESS_DELAY_MS = 520;
const CONTEXT_LONG_PRESS_MOVE_TOLERANCE = 11;
let contextLongPressGesture = null;
let contextLongPressSuppression = null;

function contextLongPressDescriptor(target) {
  if (!(target instanceof Element)) return null;

  const sourceHeading = target.closest("#sourceSectionHeading");
  if (sourceHeading) {
    return {
      target: sourceHeading,
      open: openSourceActionsContextMenu,
    };
  }

  const tagHeading = target.closest("#tagSectionHeading");
  if (tagHeading) {
    return {
      target: tagHeading,
      open: openTagActionsContextMenu,
    };
  }

  const source = target.closest("#sourceList [data-source-id]");
  if (source) {
    return {
      target: source,
      open: (x, y) => showSourceContextMenu(x, y, source.dataset.sourceId),
    };
  }

  const sidebarTag = target.closest("#tagNavigation [data-quick-tag-id]");
  if (sidebarTag) {
    return {
      target: sidebarTag,
      open: (x, y) => showTagContextMenu(
        x,
        y,
        sidebarTag.dataset.quickTagId,
        sidebarTag
      ),
    };
  }

  const groupToggle = target.closest(
    "[data-sidebar-tag-group-toggle], [data-inspector-tag-group-toggle]"
  );
  const groupID = groupToggle?.dataset.sidebarTagGroupToggle
    || groupToggle?.dataset.inspectorTagGroupToggle;
  const group = groupByID(groupID);
  if (groupToggle && group && !group.isSystem) {
    return {
      target: groupToggle,
      open: (x, y) => showTagGroupContextMenu(x, y, groupID, groupToggle),
    };
  }

  const assetMain = target.closest("#assetGrid .asset-card-main");
  const assetCard = assetMain?.closest("[data-asset-id]");
  if (assetMain && assetCard) {
    return {
      target: assetMain,
      open: (x, y) => showAssetContextMenu(x, y, assetCard.dataset.assetId),
    };
  }

  const reviewMain = target.closest("#reviewGrid .review-card-main");
  const reviewCard = reviewMain?.closest("[data-review-asset-id]");
  if (reviewMain && reviewCard) {
    return {
      target: reviewMain,
      open: (x, y) => showReviewContextMenu(
        x,
        y,
        reviewCard.dataset.reviewKey
      ),
    };
  }

  const slimmingMember = target.closest(
    "#slimmingMemberGrid [data-slimming-member-main]"
  );
  const slimmingMemberCard = slimmingMember?.closest("[data-slimming-member-id]");
  if (slimmingMember && slimmingMemberCard) {
    return {
      target: slimmingMember,
      open: (x, y) => showSlimmingMemberContextMenu(
        x,
        y,
        slimmingMemberCard.dataset.slimmingMemberId
      ),
    };
  }

  const recycleThumbnail = target.closest(
    "#slimmingRecycleList [data-slimming-recycle-thumbnail-entry-id]"
  );
  if (recycleThumbnail) {
    return {
      target: recycleThumbnail,
      open: (x, y) => showSlimmingRecycleContextMenu(
        x,
        y,
        recycleThumbnail.dataset.slimmingRecycleThumbnailEntryId
      ),
    };
  }

  const slimmingJob = target.closest("#slimmingJobList [data-slimming-job-id]");
  const job = state.slimming.jobs.find(
    (candidate) => candidate.id === slimmingJob?.dataset.slimmingJobId
  );
  if (slimmingJob && job && job.state !== "running") {
    return {
      target: slimmingJob,
      open: (x, y) => showSlimmingJobContextMenu(
        x,
        y,
        slimmingJob.dataset.slimmingJobId
      ),
    };
  }
  return null;
}

function clearContextLongPressGesture() {
  if (!contextLongPressGesture) return;
  clearTimeout(contextLongPressGesture.timer);
  contextLongPressGesture.target.classList.remove("context-long-press-active");
  contextLongPressGesture = null;
}

function beginContextLongPress(event) {
  if (event.pointerType !== "touch" || event.button !== 0) return;
  const descriptor = contextLongPressDescriptor(event.target);
  if (!descriptor) return;
  clearContextLongPressGesture();
  const gesture = {
    ...descriptor,
    pointerID: event.pointerId,
    startX: event.clientX,
    startY: event.clientY,
    timer: null,
  };
  descriptor.target.classList.add("context-long-press-active");
  gesture.timer = setTimeout(() => {
    if (contextLongPressGesture !== gesture || !gesture.target.isConnected) return;
    hidePersistentHelp();
    contextLongPressSuppression = {
      target: gesture.target,
      until: performance.now() + 900,
    };
    gesture.open(gesture.startX + 8, gesture.startY + 8);
    clearContextLongPressGesture();
  }, CONTEXT_LONG_PRESS_DELAY_MS);
  contextLongPressGesture = gesture;
}

function updateContextLongPress(event) {
  const gesture = contextLongPressGesture;
  if (!gesture || gesture.pointerID !== event.pointerId) return;
  if (Math.hypot(event.clientX - gesture.startX, event.clientY - gesture.startY)
    > CONTEXT_LONG_PRESS_MOVE_TOLERANCE) {
    clearContextLongPressGesture();
  }
}

function finishContextLongPress(event) {
  if (contextLongPressGesture?.pointerID !== event.pointerId) return;
  clearContextLongPressGesture();
}

function suppressContextLongPressFollowUp(event) {
  if (event.type === "contextmenu"
    && contextLongPressGesture
    && event.composedPath().includes(contextLongPressGesture.target)) {
    event.preventDefault();
    event.stopImmediatePropagation();
    return true;
  }
  const suppression = contextLongPressSuppression;
  if (!suppression || performance.now() >= suppression.until) {
    contextLongPressSuppression = null;
    return false;
  }
  if (!event.composedPath().includes(suppression.target)) return false;
  event.preventDefault();
  event.stopImmediatePropagation();
  return true;
}

